private enum class Tab(val label: String) {
    INVENTORY("Inventory"), MAGIC("Spells"), HUD("HUD"), STATS("Stats"), JOURNAL("Journal")
}

private fun InventoryItem.displayName(): String =
    if (name.isNotBlank()) name else prettify(id)

private fun SpellEntry.displayName(): String =
    if (name.isNotBlank()) name else prettify(id)

private fun BarterItem.displayName(): String =
    if (name.isNotBlank()) name else prettify(id)

/** Canonical head-to-toe display order for equipment slots. Currently UNREFERENCED — its only
 *  consumer was the inventory strip's equipped-chip row, replaced by the sort controls. Kept
 *  because it encodes the intended ordering for any future equipped view (the "Equipped" filter
 *  tab and the pinned Equipped section both sort by category rank instead). */
@Suppress("unused")
private val EQUIPMENT_SLOT_ORDER = listOf(
    "weapon", "ammo", "shield",
    "lockpick", "probe",
    "helmet", "cuirass",
    "left_pauldron", "right_pauldron",
    "greaves", "boots",
    "left_gauntlet", "right_gauntlet",
    "amulet", "left_ring", "right_ring",
    "shirt", "pants", "skirt", "robe",
    "carried_left", "carried_right",
    "book"
)

private data class InvCategory(val label: String, val cats: Set<String>)

private val INV_CATEGORIES = listOf(
    InvCategory("Weapons", setOf("weapon", "ammo")),
    InvCategory("Armor",   setOf("helmet", "cuirass", "left_pauldron", "right_pauldron",
                                  "greaves", "boots", "left_gauntlet", "right_gauntlet",
                                  "shield", "armor")),
    InvCategory("Apparel", setOf("amulet", "left_ring", "shirt", "pants", "skirt",
                                  "robe", "clothing")),
    // "carried_left" is Lights (torches/lanterns) — itemCategory maps ONLY types.Light there, so
    // this moves exactly torches out of Misc and nothing else. Grouped with Tools because that
    // category is already "carried, not worn, has a use" (lockpicks/probes/apparatus/repair hammers)
    // rather than a vanilla grouping — vanilla itself files torches under Misc.
    InvCategory("Tools",   setOf("lockpick", "probe", "apparatus", "repair", "carried_left")),
    InvCategory("Books",       setOf("book", "scroll")),
    InvCategory("Consumables", setOf("potion", "ingredient")),
    // Keys out of Misc — the one sub-bucket of Misc worth its own tab: a playthrough accumulates
    // dozens, they are never sold or dropped, and they were previously buried among plates/cups/
    // gems. `key` comes from the Lua itemCategory (types.Miscellaneous record `isKey` flag) and,
    // on the barter side, from Class::isKey — see companion-barter-categories.patch. Misc keeps
    // its meaning as "everything else", so this is purely additive.
    InvCategory("Keys",        setOf("key")),
    InvCategory("Misc",        setOf("misc")),
)

// Sentinel filter label (NOT an INV_CATEGORIES entry): shows only equipped items. Rendered as
// the first sub-tab after "All". Kept distinct from the category labels so the selectedCategory
// == EQUIPPED_FILTER check is unambiguous.
private const val EQUIPPED_FILTER = "Equipped"

// Vanilla-style category ordering (SortFilterItemModel::getTypeOrder) mapped onto BOTH the fine
// inventory/container category strings (Lua itemCategory) AND the coarse barter category strings
// (native companionBarterCategory), so every item list sorts by category then name like the menus.
private fun itemCategoryRank(category: String): Int = when (category) {
    "weapon", "ammo" -> 0
    "armor", "helmet", "cuirass", "left_pauldron", "right_pauldron", "greaves", "boots",
        "left_gauntlet", "right_gauntlet", "shield" -> 1
    "apparel", "amulet", "left_ring", "shirt", "pants", "skirt", "robe", "clothing" -> 2
    "consumable", "potion" -> 3
    "ingredient" -> 4
    "book", "scroll" -> 6
    // ONE rank for the whole INV_CATEGORIES "Tools" set, so those items sort contiguously and ahead
    // of Misc. Previously they were scattered — carried_left 7, apparatus/repair fell through to the
    // misc `else` 8, lockpick 9, probe 11 — which interleaved tools with misc items in the flattened
    // CARDS "All" view. Torches (carried_left) join them here rather than sitting next to Misc.
    // (The old `else` comment claiming apparatus/repair/light fold into "misc" was stale: itemCategory
    // returns them as their own categories.)
    "tools", "lockpick", "probe", "apparatus", "repair", "carried_left" -> 7
    // Keys sort as their own contiguous block just ahead of Misc (they used to BE misc, so
    // without this they would interleave with it by name in the flattened "All" views).
    "key" -> 8
    else -> 9   // misc
}

/** Subtle gold backdrop behind an enchanted item's icon (mirrors vanilla's menu_icon_magic frame).
 *  Call as the FIRST child of an icon Box so it draws behind the icon image. */
@Composable
private fun BoxScope.EnchantBackdrop(enchanted: Boolean) {
    if (enchanted) Box(Modifier.matchParentSize().background(EnchantTint))
}

/** The live player character name (from COMPANION_CHARACTER → state.character.name), used for the
 *  "your side" column headers. Falls back to [fallback] until the name is known. Maps to just the
 *  name (distinctUntilChanged) so it doesn't recompose on every fast COMPANION_STATS tick. */
@Composable
private fun rememberPlayerName(fallback: String = "You"): String {
    val flow = remember { GameStateRepository.state.map { it.character.name }.distinctUntilChanged() }
    val name by flow.collectAsState(initial = "")
    return name.ifBlank { fallback }
}

/** A thin, subtle horizontal scrollbar for a [LazyHorizontalGrid], shown ONLY when the content is
 *  wider than the viewport (more item-columns than fit). Track = muted bronze, thumb = brighter
 *  bronze; thumb width/position approximated from the visible/total item counts. */
@Composable
private fun HorizontalGridScrollbar(state: LazyGridState, modifier: Modifier = Modifier) {
    val metrics by remember(state) {
        derivedStateOf {
            val info = state.layoutInfo
            val total = info.totalItemsCount
            val visible = info.visibleItemsInfo.size
            if (total <= 0 || visible >= total) null
            else {
                val thumb = (visible.toFloat() / total).coerceIn(0.08f, 1f)
                val start = (state.firstVisibleItemIndex.toFloat() / total).coerceIn(0f, 1f - thumb)
                start to thumb
            }
        }
    }
    val m = metrics
    if (m != null) {
        val (start, thumb) = m
        BoxWithConstraints(modifier.fillMaxWidth().height(4.dp)) {
            val w = maxWidth
            Box(
                Modifier.fillMaxWidth().height(3.dp).align(Alignment.Center)
                    .clip(RoundedCornerShape(2.dp)).background(BronzeDark.copy(alpha = 0.35f))
            )
            Box(
                Modifier.align(Alignment.CenterStart)
                    .offset(x = w * start).width(w * thumb).height(3.dp)
                    .clip(RoundedCornerShape(2.dp)).background(BronzeLight.copy(alpha = 0.7f))
            )
        }
    }
}

/** A vertical proportional scrollbar for a [LazyColumn], shown ONLY when the content is taller
 *  than the viewport. Track = muted bronze, thumb = bright bronze; thumb length/position come from
 *  the visible/total ITEM counts, the same approximation [HorizontalGridScrollbar] makes.
 *
 *  DELIBERATELY WIDER AND BRIGHTER than that one (5dp vs 3dp, full-strength [BronzeLight] thumb).
 *  A thin drawn scrollbar for vertical content was tried and REJECTED in Aug 2026 — see
 *  [ScrollMoreHint], whose doc records that 3dp of bronze "was too easy to miss" on the 3.92"
 *  bottom screen. This is not a re-litigation of that: the chevron answers "is there more?", which
 *  is all a short list needs, while a long browse list (the enchanting Magic Effects list can run
 *  to dozens of rows) also needs "how far in am I, and how much is there" — which a chevron cannot
 *  express at any size. The two are complementary and both are used there.
 *
 *  Meant to sit BESIDE the list as its sibling in a Row, given a fillMaxHeight modifier. */
@Composable
private fun VerticalListScrollbar(state: LazyListState, modifier: Modifier = Modifier) {
    val metrics by remember(state) {
        derivedStateOf {
            val info = state.layoutInfo
            val total = info.totalItemsCount
            val visible = info.visibleItemsInfo.size
            if (total <= 0 || visible >= total) null
            else {
                // Clamped so the thumb never shrinks to an invisible sliver on a very long list.
                val thumb = (visible.toFloat() / total).coerceIn(0.10f, 1f)
                val start = (state.firstVisibleItemIndex.toFloat() / total).coerceIn(0f, 1f - thumb)
                start to thumb
            }
        }
    }
    val m = metrics ?: return
    val (start, thumb) = m
    BoxWithConstraints(modifier.width(SCROLLBAR_WIDTH)) {
        val h = maxHeight
        Box(
            Modifier.fillMaxHeight().width(SCROLLBAR_WIDTH).align(Alignment.Center)
                .clip(RoundedCornerShape(3.dp)).background(BronzeDark.copy(alpha = 0.45f))
        )
        Box(
            Modifier.align(Alignment.TopCenter)
                .offset(y = h * start).height(h * thumb).width(SCROLLBAR_WIDTH)
                .clip(RoundedCornerShape(3.dp)).background(BronzeLight)
        )
    }
}

private val SCROLLBAR_WIDTH = 5.dp

/** "There is more list below/above" hint for a plain `verticalScroll` [ScrollState] — a centred
 *  chevron strip meant to sit BELOW the scrolling content as its sibling, in the same Column.
 *
 *  This is the vertical counterpart of the `canScrollForward` chevron on `CategoryShelf`'s shelves,
 *  and it replaced a thin drawn scrollbar (Aug 2026) that was too easy to miss on the 3.92" bottom
 *  screen. A chevron survives being glanced at; 3dp of bronze does not.
 *
 *  Emits NOTHING when the content fits (no wasted row on a short list), but once it is scrollable
 *  at all the strip stays at a FIXED height and only swaps its glyph — so reaching the bottom
 *  doesn't resize the menu under the player's finger. */
@Composable
private fun ScrollMoreHint(state: ScrollState, modifier: Modifier = Modifier) {
    val scrollable by remember(state) {
        derivedStateOf { state.canScrollForward || state.canScrollBackward }
    }
    if (!scrollable) return
    val more = state.canScrollForward
    Box(
        modifier
            .fillMaxWidth()
            .height(SCROLL_HINT_HEIGHT)
            .background(SlotBg.copy(alpha = 0.6f)),
        contentAlignment = Alignment.Center
    ) {
        Text(
            if (more) "▾" else "▴",
            color = BronzeLight, fontSize = 11.sp,
            fontFamily = MwDisplay, fontWeight = FontWeight.Bold
        )
    }
}

/** [ScrollMoreHint] for a [LazyColumn]. Same strip, same rules — `canScrollForward` /
 *  `canScrollBackward` exist on both state types, so only the parameter differs. */
@Composable
private fun ScrollMoreHint(state: LazyListState, modifier: Modifier = Modifier) {
    val scrollable by remember(state) {
        derivedStateOf { state.canScrollForward || state.canScrollBackward }
    }
    if (!scrollable) return
    val more = state.canScrollForward
    Box(
        modifier
            .fillMaxWidth()
            .height(SCROLL_HINT_HEIGHT)
            .background(SlotBg.copy(alpha = 0.6f)),
        contentAlignment = Alignment.Center
    ) {
        Text(
            if (more) "▾" else "▴",
            color = BronzeLight, fontSize = 11.sp,
            fontFamily = MwDisplay, fontWeight = FontWeight.Bold
        )
    }
}

private val SCROLL_HINT_HEIGHT = 14.dp

// How a tap / long-press acts on an inventory item. Mutually exclusive, keyed off
// the coarse category from Lua's itemCategory(). Kept in one place so the two
// inventory list call sites (grouped + single-category) stay in agreement.
//   readable   → open the book/scroll reader (CMP:read)
//   usable     → native use() action (CMP:use): potion=drink, ingredient=eat,
//                apparatus=alchemy menu, repair=repair menu — NONE are worn
//   equippable → worn gear toggled via CMP:equip / CMP:unequip (weapons, armor,
//                clothing, lockpick/probe, and lights/torches → carried_left)
private fun InventoryItem.isReadable() = category == "book" || category == "scroll"
private fun InventoryItem.isUsable() =
    category == "potion" || category == "ingredient" || category == "apparatus" || category == "repair"
private fun InventoryItem.isEquippable() = !isUsable() && !isReadable() && category != "misc"

// Long-press / tap verb for a usable item: potion→Drink, food→Eat, tool→Use.
private fun InventoryItem.useVerb() = when (category) {
    "potion" -> "Drink"
    "ingredient" -> "Eat"
    else -> "Use"
}

// Barter overlay category tabs — one bucket per tab, matching the coarse `cat` the engine emits on
// COMPANION_BARTER_ITEM (weapon/armor/apparel/tools/book/consumable/key/misc). Deliberately NOT the
// inventory's fine SLOT categories — the barter screen groups into these tabs directly — but the
// BUCKETS deliberately mirror [INV_CATEGORIES], and in the same order, so an item lands under the
// same tab name whether you are looting it or buying it. Books and Keys, plus apparatus/repair/
// torches moving into Tools, came from companion-barter-categories.patch; before that everything
// here except lockpicks/probes fell into Misc.
private data class BarterCat(val label: String, val cat: String)

private val BARTER_CATEGORIES = listOf(
    BarterCat("Weapons", "weapon"),
    BarterCat("Armor", "armor"),
    BarterCat("Apparel", "apparel"),
    BarterCat("Tools", "tools"),
    BarterCat("Books", "book"),
    BarterCat("Consumables", "consumable"),
    BarterCat("Keys", "key"),
    BarterCat("Misc", "misc"),
)

/** Cycle a barter side's category filter by [dir] (-1 = previous, +1 = next) through
 *  [All] + the categories actually present in [items] (in BARTER_CATEGORIES order), wrapping.
 *  Returns the new selection (null = All). Matches the visible CategoryTab set, so the L1/R1
 *  shoulder buttons mirror tapping the tabs. */
private fun cycleBarterCat(items: List<BarterItem>, current: String?, dir: Int): String? {
    val present = items.map { it.category }.toSet()
    val avail: List<String?> = listOf<String?>(null) + BARTER_CATEGORIES.filter { it.cat in present }.map { it.cat }
    if (avail.size <= 1) return current
    val cur = avail.indexOf(current).coerceAtLeast(0)
    val next = ((cur + dir) % avail.size + avail.size) % avail.size
    return avail[next]
}

/** Stone panel with a bronze frame — the signature Morrowind window look. */
/**
 * Background-fill opacity for panels in the CURRENT composition. 1f (opaque) everywhere by default,
 * so bottom-screen companion panels are untouched; the top-screen overlay windows provide the
 * player's chosen value via [ProvideTopPanelOpacity].
 *
 * A CompositionLocal rather than a parameter because the panels that need to fade are drawn by
 * composables SHARED with the bottom screen (`ShelfDualPanel`, the loot/barter grid columns, the
 * conversation panel). Threading a flag through every one of them would touch a dozen signatures
 * and be easy to miss a call site on; providing it at the window root means "anything drawn inside
 * a top overlay fades, everything else doesn't" falls out automatically.
 */
private val LocalPanelOpacity = compositionLocalOf { 1f }

/**
 * Adaptive-dim TINT ALPHA for the CURRENT composition, 0f = untinted. Non-zero only inside a
 * top-screen overlay window (supplied by [ProvideTopPanelOpacity]); the bottom screen leaves it at
 * 0f because it is dimmed wholesale by [AdaptiveDimOverlay] instead.
 *
 * WHY A TINT AND NOT A SCRIM. The bottom screen can draw one opaque-ish black layer over
 * everything because nothing is behind it. A top-screen overlay window is full-screen and
 * TRANSLUCENT — the game shows through it — so a plain scrim would darken the GAME, which is
 * already dark (that darkness is what drives this ramp) and would stack once per visible overlay
 * window. Instead each panel tints ONLY the pixels it drew, via SrcAtop.
 *
 * WHY NOT FOLD IT INTO [LocalPanelOpacity]. That local is read by background FILLS only; the
 * borders and every piece of text/bar/icon deliberately ignore it. Lowering it does not dim the UI,
 * it makes the panel more TRANSPARENT — in a dark cave that would fade the fill toward invisible
 * while leaving bone-white text at full brightness, i.e. more glare, not less. The two settings
 * stay orthogonal: the slider decides how solid the fill is, this tints whatever that produced.
 */
private val LocalTopScreenDim = compositionLocalOf { 0f }

/**
 * Darken this element's OWN drawn pixels by the ambient dim ([LocalTopScreenDim]), leaving
 * everything it did not draw untouched.
 *
 * `SrcAtop` is what makes that true: it paints the black only where the destination already has
 * coverage. So a panel is tinted across its fill, border and text; a bare overlay with no
 * background (the two combat HUD overlays) tints its bars and numbers and nothing else — no
 * leftover dimmed rectangle when the overlay draws nothing, and no visible box added at 0% dim.
 *
 * COMPOSITING NOTE. Blend modes other than SrcOver need a bounded layer to composite against, so
 * this attaches `CompositingStrategy.Offscreen` — but ONLY while the tint is actually non-zero, and
 * only around the ELEMENT (a panel, or a combat overlay's small bar column), never around a whole
 * overlay window. In daylight, or with dimming off, the modifier chain is returned unchanged and
 * costs nothing at all.
 *
 * NESTING: apply this at panel ROOTS only. Two nested applications would tint the inner content
 * twice (1-(1-a)² instead of a).
 */
@Composable
private fun Modifier.adaptiveDimTint(): Modifier = dimTint(LocalTopScreenDim.current)

/** The tint itself, at an explicit alpha. Shared by [adaptiveDimTint] (top-screen panels, whose
 *  alpha comes from [LocalTopScreenDim]) and [CompanionDropdownMenu] (Popup windows, which have to
 *  source their own via [rememberPopupDimAlpha]) so the two cannot drift. Returns the chain UNCHANGED when clear, so the common
 *  daylight/disabled case allocates no layer and costs nothing. */
private fun Modifier.dimTint(alpha: Float): Modifier {
    if (alpha <= 0.001f) return this
    return this
        .graphicsLayer { compositingStrategy = CompositingStrategy.Offscreen }
        .drawWithContent {
            drawContent()
            drawRect(Color.Black.copy(alpha = alpha), blendMode = BlendMode.SrcAtop)
        }
}

/**
 * True inside a TOP-screen overlay window's composition (set by [ProvideTopPanelOpacity]).
 *
 * Needed because [LocalTopScreenDim] alone cannot answer "which screen am I on" — it reads 0f both
 * on the bottom screen AND on the top screen with dimming off. A Popup has to know, because the two
 * screens dim by DIFFERENT amounts (the top screen's tighter ceiling) and the dimming preferences
 * themselves are global.
 */
private val LocalIsTopScreen = compositionLocalOf { false }

/**
 * Adaptive-dim alpha that a Compose **Popup** must apply to itself.
 *
 * WHY POPUPS ARE A SPECIAL CASE: `DropdownMenu` (and anything else built on `Popup`) renders into
 * its OWN Android window, not into the composition that declared it. So NEITHER dimming mechanism
 * reaches it — not the bottom screen's full-screen [AdaptiveDimOverlay] scrim (a Box at zIndex 40f
 * cannot cover a different window at any zIndex) nor a parent panel's [adaptiveDimTint] (the popup
 * is not inside that element's draw). A popup that wants to dim has to dim itself.
 *
 * CompositionLocals DO cross into a popup's sub-composition, which is what makes this work.
 */
@Composable
private fun rememberPopupDimAlpha(): Float {
    val top = LocalTopScreenDim.current
    val bottom = rememberBottomScreenDimAlpha()
    return if (LocalIsTopScreen.current) top else bottom
}

/**
 * The companion's DropdownMenu. Every menu in the companion UI shares the same styling, the same
 * focus-critical [PopupProperties], and — since Aug 11 2026 — the same self-applied screen dim, so
 * they are encapsulated here instead of being spelled out ten times.
 *
 * **The dimming is the reason this exists.** A DropdownMenu is a Compose Popup, i.e. its own Android
 * window, so neither dimming mechanism reaches it: not the bottom screen's full-screen
 * [AdaptiveDimOverlay] scrim (a Box cannot cover a different window at any zIndex) nor a parent
 * panel's [adaptiveDimTint] (the popup is not inside that element's draw). Left alone, a menu opened
 * in a pitch-dark cave glares at full brightness against a dimmed screen. Routing every menu through
 * one composable means new menus are dimmed by construction rather than by remembering to.
 *
 * The dim is applied in two halves because a menu's Surface paints its container OUTSIDE any
 * modifier its content can carry: [dimTint] on the content column (via `modifier`, which
 * Material3 applies to that column, so no extra wrapper and no layout change), and [dimColor] on the
 * container + border. For an opaque colour, lerping toward black IS compositing black over it, so
 * the two halves land on exactly the value the scrim would have produced.
 *
 * `PopupProperties(focusable = false, dismissOnClickOutside = false)` is load-bearing and must not
 * change — it is what stops a menu stealing game-window focus on the Thor; dismissal is handled by
 * the screen-level scrim / [DropdownState].
 */
@Composable
private fun CompanionDropdownMenu(
    expanded: Boolean,
    onDismissRequest: () -> Unit,
    // Shift relative to the anchor, passed straight to DropdownMenu. Note M3's position provider
    // SUBTRACTS x in its flipped (right-aligned) branch, so a horizontal offset does not mean the
    // same thing in both branches — prefer moving the anchor over nudging this.
    offset: DpOffset = DpOffset(0.dp, 0.dp),
    content: @Composable ColumnScope.() -> Unit
) {
    val dim = rememberPopupDimAlpha()
    DropdownMenu(
        expanded = expanded,
        onDismissRequest = onDismissRequest,
        offset = offset,
        modifier = Modifier.dimTint(dim),
        properties = PopupProperties(focusable = false, dismissOnClickOutside = false),
        containerColor = dimColor(StonePanel, dim),
        shadowElevation = 0.dp,
        border = BorderStroke(1.dp, dimColor(Bronze, dim)),
        shape = RoundedCornerShape(3.dp),
        content = content
    )
}

/** Darken an OPAQUE colour as if the dim scrim were over it — for an opaque colour, compositing
 *  black at [alpha] IS a lerp toward black, so this matches exactly what the rest of the screen
 *  gets. Used for a popup's `containerColor`/border, which its own Surface paints. */
private fun dimColor(color: Color, alpha: Float): Color =
    if (alpha <= 0.001f) color else lerp(color, Color.Black, alpha)

/** Wrap a TOP-screen overlay's content so it picks up the shared companion environment: panel
 *  opacity and the font setting. Public because EngineActivity applies it at each top-screen
 *  window root — that is the one place that reliably means "this composition is on the top
 *  screen", and it covers overlays added later for free.
 *
 *  Name kept for its existing call sites; it now supplies the font too, so a DS overlay on the top
 *  screen matches the companion below it without EngineActivity needing to know about fonts. */
@Composable
fun ProvideTopPanelOpacity(content: @Composable () -> Unit) {
    val opacity by UiPreferences.topPanelOpacityFlow().collectAsState()
    CompositionLocalProvider(
        LocalPanelOpacity provides opacity,
        LocalTopScreenDim provides rememberTopScreenDimAlpha(),
        LocalIsTopScreen provides true
    ) {
        ProvideCompanionFont(content)
    }
}

/**
 * The BRIGHT end of the dimming ramp for the scene the player is actually in — the day ceiling
 * outdoors in daylight and everywhere the weather system does not light, crossfaded toward the
 * night ceiling as the sun goes down.
 *
 * WHY A SECOND CEILING RATHER THAN A SMARTER RAMP. [adaptiveDimAlpha] reads ONE number, the
 * scene's ambient luminance, and the Game Brightness night lift raises that number at night. At
 * a 0.15 lift the day and night bands overlap outright: lifted Overcast night reports
 * 0.384 against Overcast day's 0.377, so the ramp reads night as the brighter of the two and
 * leaves it at alpha 0.03. (0.15 shipped for part of Aug 20 2026; the lift now defaults to 0, so
 * at stock settings there is no overlap — this ceiling still applies, it just no longer has a
 * measurement error to correct.) No value of [DIM_LUMINANCE_BRIGHT] can separate them either —
 * Thunderstorm DAY sits at 0.353, below both. Night has to be identified independently, which is
 * what `GameStateRepository.nightWeight` is for.
 *
 * TWO THINGS HERE ARE LOAD-BEARING:
 *  - **`min(day, night)`.** The night slider only ever LOWERS the ceiling. Without it, dragging
 *    the day slider below the night one would make night the BRIGHTER of the two — the ramp
 *    inverting under the player's hand. With it, lowering either slider darkens night.
 *  - **Blending the CEILING, before the ramp.** The alternative — ramping twice and mixing the
 *    resulting alphas — would need its own smoothing and its own top-screen handling. Done here,
 *    there is still one ramp function, one `projectBrightness` seam, and one 800ms fade; both
 *    screens inherit the night ceiling with no screen-specific code, and the crossfade rides the
 *    animation that is already there.
 *
 * The weight itself is the engine's own dawn/dusk interpolation factor (see the Lua exporter), so
 * the ceiling crossfades on the game's curve rather than snapping at an hour we chose. Interiors
 * report 0 and therefore keep the day ceiling — correct, because their ambient comes from
 * `configureAmbient` and the night lift cannot reach it.
 */
@Composable
private fun rememberDimMaxBrightness(): Float {
    val dayMax by UiPreferences.adaptiveDimMaxBrightnessFlow().collectAsState()
    val nightMaxPref by UiPreferences.adaptiveDimNightMaxBrightnessFlow().collectAsState()
    val nightWeight by GameStateRepository.nightWeight.collectAsState()

    val nightMax = kotlin.math.min(dayMax, nightMaxPref)
    return dayMax + (nightMax - dayMax) * nightWeight.coerceIn(0f, 1f)
}

/**
 * The current top-screen dim alpha: the SHARED dimming sliders, re-projected into the top screen's
 * tighter band, run through the SHARED ramp, and animated with the same 800ms fade the bottom
 * screen uses (so a cell transition reads as one adjustment across both screens rather than two).
 *
 * Returns 0f whenever the master switch is off — gated at the MAPPING stage, exactly like
 * [AdaptiveDimOverlay], so turning it off animates back to clear instead of snapping and the switch
 * still wins over any slider position.
 */
@Composable
private fun rememberTopScreenDimAlpha(): Float {
    val enabled by UiPreferences.adaptiveDimmingFlow().collectAsState()
    val minBrightness by UiPreferences.adaptiveDimMinBrightnessFlow().collectAsState()
    // Day or night ceiling, already blended — projected through the DAY range because the two
    // ceiling ranges are identical, so one projection covers both and the top screen needs no
    // night-specific code of its own.
    val maxBrightness = rememberDimMaxBrightness()
    val luminance by GameStateRepository.ambientLuminance.collectAsState()

    val target = if (!enabled) 0f else adaptiveDimAlpha(
        luminance = luminance,
        minBrightness = projectBrightness(minBrightness, ADAPTIVE_DIM_MIN_RANGE, TOP_ADAPTIVE_DIM_MIN_RANGE),
        maxBrightness = projectBrightness(maxBrightness, ADAPTIVE_DIM_MAX_RANGE, TOP_ADAPTIVE_DIM_MAX_RANGE),
        ceiling = TOP_DIM_ABSOLUTE_MAX_ALPHA
    )
    val alpha by animateFloatAsState(
        targetValue = target,
        animationSpec = tween(durationMillis = DIM_ANIM_MS),
        label = "topScreenDim"
    )
    return alpha
}

/**
 * The standard panel look. Only the FILL honours [LocalPanelOpacity] — the 2dp Bronze border stays
 * fully opaque on purpose, so at 0% the panel's bounds (and therefore which text belongs to it)
 * are still readable against the game behind it.
 */
@Composable
private fun Modifier.mwPanel(): Modifier = this
    .adaptiveDimTint()
    .clip(RoundedCornerShape(3.dp))
    .background(StonePanel.copy(alpha = LocalPanelOpacity.current))
    .border(2.dp, Bronze, RoundedCornerShape(3.dp))

/** Index-cycle a category order list, wrapping. dir +1 = next, -1 = previous; a missing current
 *  starts from index 0. Shared by every swipe/shoulder category switch. */
private fun <T> cycleValue(order: List<T>, current: T, dir: Int): T {
    if (order.isEmpty()) return current
    val i = order.indexOf(current).let { if (it < 0) 0 else it }
    return order[((i + dir) % order.size + order.size) % order.size]
}

/** Horizontal swipe that cycles a filter category: swipe LEFT → next (dir +1), swipe RIGHT →
 *  previous (dir -1). Fires once per gesture past a small threshold. It's orthogonal to vertical
 *  list scrolling (a horizontal-only detector), and a nested horizontal scroller — an icon grid or
 *  an overflowing tab row — consumes drags that start on it first, so this fires on the list body /
 *  non-scrolling areas without fighting them. [key] must include the current selection (and anything
 *  else [onCycle] reads) so the gesture re-captures fresh state on change. */
private fun Modifier.categorySwipe(key: Any?, onCycle: (dir: Int) -> Unit): Modifier =
    this.pointerInput(key) {
        val thresholdPx = 40.dp.toPx()
        var total = 0f
        detectHorizontalDragGestures(
            onDragStart = { total = 0f },
            onHorizontalDrag = { _, dx -> total += dx },
            onDragEnd = {
                if (total <= -thresholdPx) onCycle(1)
                else if (total >= thresholdPx) onCycle(-1)
            }
        )
    }

/**
 * The bottom-screen companion UI. A thin wrapper so the whole screen composes under the shared
 * font setting; the top-screen DS overlays get the same thing via [ProvideTopPanelOpacity].
 *
 * [UiPreferences.init] is called HERE, before the setting is read, rather than relying on the copy
 * inside the content below: the wrapper composes first, so without this the font pref would be
 * read at its default and the screen would visibly re-font itself a frame later. It is idempotent,
 * so the inner call simply becomes a no-op.
 */
@Composable
fun CompanionScreen() {
    val context = LocalContext.current
    remember(context) { UiPreferences.init(context); true }
    ProvideCompanionFont { CompanionScreenContent() }
}

@Composable
private fun CompanionScreenContent() {
    val state by GameStateRepository.state.collectAsState()
    var tab by remember { mutableStateOf(Tab.HUD) }
    // Dismiss the item info popup when the tab changes so it never lingers over another screen.
    LaunchedEffect(tab) { ItemInfoPopupState.close() }

    // Companion data arrives solely via the native JNI push (core.companionPush →
    // companionPushLine → EngineActivity.onCompanionLine → GameStateRepository.onJniLine).
    // There is no file-tail fallback: companion lines are no longer written to openmw.log at
    // all (see the disk-logging elimination), so there is nothing on disk to tail.
    val context = LocalContext.current
    // Load the last-known character's favourites synchronously during composition
    // (not LaunchedEffect) so favourite pills show persisted content on the very
    // first frame, with no post-composition flash of empty slots.
    remember(context) { FavouritesRepository.init(context) }
    // Same first-frame treatment for the per-character quest prefs (hidden set + followed quest),
    // so the HUD's followed-quest label and the quest list's stars are right on the first frame.
    remember(context) { QuestPrefsRepository.init(context); true }
    // Manual journal entries: same first-frame treatment, so opening the Journal immediately after
    // launch shows the last-known save's notes rather than filling them in a moment later. Reads
    // external storage (not SharedPreferences) — see CustomJournalRepository for why.
    remember { CustomJournalRepository.init(); true }
    // Load persisted UI routing (which screen the conversation lives on, etc.).
    remember(context) { UiPreferences.init(context); true }

    // Favourites are save-dependent (keyed by character name). Once the live
    // character is known — and whenever the player loads a different save at
    // runtime — swap to that character's bucket, THEN prune any favourite whose
    // item/spell no longer exists in the loaded save. Ordering matters: switch
    // first so reconcile only ever prunes the ACTIVE character's set.
    //
    // A category is pruned only when its source list is non-empty; passing null
    // while inventory/spells are still empty (the save-load window) prevents a
    // transient blank state from wiping favourites.
    // Keep the favourites repository's visible slot counts in step with the options. Truncation
    // happens inside the repository so the HUD groups, the star indicators and the long-press
    // favourite menu can never disagree about whether a hidden slot counts.
    val favGearSlots by UiPreferences.favGearSlotsFlow().collectAsState()
    val favMagicSlots by UiPreferences.favMagicSlotsFlow().collectAsState()
    LaunchedEffect(favGearSlots, favMagicSlots) {
        FavouritesRepository.setVisibleCounts(favGearSlots, favMagicSlots)
    }

    LaunchedEffect(state.character.name, state.inventory, state.spells) {
        val name = state.character.name
        if (name.isNotBlank()) {
            FavouritesRepository.setCharacter(context, name)
            FavouritesRepository.reconcile(
                context,
                inventoryIds = state.inventory.takeIf { it.isNotEmpty() }?.map { it.id }?.toSet(),
                spellIds = state.spells.takeIf { it.isNotEmpty() }?.map { it.id }?.toSet()
            )
        }
    }

    // Quest prefs are save-dependent in exactly the same way (see QuestPrefsRepository). Kept as
    // its own effect rather than folded into the favourites one so it re-runs on journal changes
    // without re-running favourites' reconcile on every inventory tick. Same ordering rule: switch
    // character first, then prune — and pass null while the journal is still empty (the save-load
    // window) so a transient blank state can't wipe the hidden set.
    //
    // The id set passed to reconcile is the MERGED one (game entries + the manual pseudo-quest).
    // Passing the raw journal would silently un-hide "Manual Entries" on the next journal tick:
    // reconcile prunes any id it doesn't see, and the reserved id is never in the game's export.
    // The non-empty GATE still tests the REAL journal, though — a save-load window where only
    // manual entries exist must not look like "the journal loaded", or reconcile would wipe the
    // hidden/followed state of every genuine quest.
    //
    // The finished-quest set rides along in the SAME effect rather than getting its own, so the
    // setCharacter → mutate ordering above also covers it: a standalone effect could clear the
    // followed quest out of the previous character's bucket during a runtime save switch.
    val mergedJournal = rememberMergedJournal(state.journalEntries)
    val finishedQuestIdsForPrefs by GameStateRepository.finishedQuestIds.collectAsState()
    // The quest LIST ids ride along too. A quest can be in that list with no journal entry at all
    // (started by SetJournalIndex, or entries with empty text), so pruning against the entries
    // alone would silently drop the player's hide/follow flag for exactly the quests the entry-
    // derived list used to miss entirely.
    val questInfosForPrefs by GameStateRepository.quests.collectAsState()
    // Every id belonging to a quest log that has FINISHED, not just the ids the engine flagged.
    // Empty when the quest export hasn't arrived, in which case the raw finished set is used
    // instead — a superset is what this is for, never a narrower one.
    val finishedGroupIdsForPrefs = remember(questInfosForPrefs, finishedQuestIdsForPrefs) {
        buildQuestGroups(questInfosForPrefs, finishedQuestIdsForPrefs)
            .filter { it.finished }
            .flatMapTo(mutableSetOf()) { it.ids }
    }
    LaunchedEffect(
        state.character.name, mergedJournal, state.journalEntries, finishedQuestIdsForPrefs,
        finishedGroupIdsForPrefs, questInfosForPrefs
    ) {
        val name = state.character.name
        if (name.isNotBlank()) {
            QuestPrefsRepository.setCharacter(context, name)
            QuestPrefsRepository.reconcile(
                context,
                questIds = state.journalEntries.takeIf { it.isNotEmpty() }
                    ?.let {
                        mergedJournal.mapTo(mutableSetOf()) { e -> e.questId }
                            .apply { addAll(questInfosForPrefs.map { q -> q.id }) }
                    }
            )
            // A completed quest stops being a sensible HUD pointer — drop it (no-op unless the
            // followed quest is actually in the finished set; see clearFollowedIfFinished).
            //
            // The set passed is GROUP-EXPANDED, not the raw finished ids. Several quest ids can
            // share one quest log and the log is finished when ANY of them is (see
            // buildQuestGroups), while `follow` stores the group's REPRESENTATIVE id — so a log
            // finished under a sibling id would never match the followed id and the HUD would keep
            // pointing at a completed quest. Same reasoning as QuestContextMenu's unhide, which
            // already clears every member id rather than the representative alone.
            QuestPrefsRepository.clearFollowedIfFinished(
                context,
                finishedGroupIdsForPrefs.ifEmpty { finishedQuestIdsForPrefs }
            )
        }
    }

    // KEEPING THE FINISHED SET CURRENT — without this the auto-unfollow above can only fire late.
    //
    // `finishedQuestIds` is an ON-DEMAND export (`CMP:questStatus`, read from the C++ journal), and
    // the only thing that ever asked for it was JournalPanel's one-shot LaunchedEffect when the
    // Journal tab composes. So a quest completed while the player was anywhere else stayed followed
    // on the HUD until they next opened the journal — which is exactly the case this is for.
    //
    // Only polls while a quest is actually followed, so the common case costs nothing. Keyed on the
    // journal entry count as well as the followed id: finishing a quest normally writes a journal
    // entry, so that restarts the loop and refreshes IMMEDIATELY; the periodic tick is the backstop
    // for a quest finished by MWScript SetJournalIndex or by an empty-text entry, neither of which
    // moves the journal.
    val followedQuestForRefresh by QuestPrefsRepository.state.collectAsState()
    val followedIdForRefresh = followedQuestForRefresh.followed
    LaunchedEffect(followedIdForRefresh, state.journalEntries.size) {
        if (followedIdForRefresh == null) return@LaunchedEffect
        while (true) {
            CompanionActions.refreshQuestStatus()
            delay(QUEST_STATUS_POLL_MS)
        }
    }

    // The HUD's followed-quest label navigates to that quest's journal page, which lives in
    // another tab — switch to it here (JournalPanel consumes the request once it composes).
    val pendingQuestNav = JournalQuestNavState.questId
    LaunchedEffect(pendingQuestNav) {
        if (pendingQuestNav != null) tab = Tab.JOURNAL
    }
    // Same trip, but for the empty tracked-quest slot: the QUESTS list itself, nothing selected.
    val pendingQuestList = JournalQuestNavState.listRequest
    LaunchedEffect(pendingQuestList) {
        if (pendingQuestList > 0) tab = Tab.JOURNAL
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .imePadding()
            .background(StoneDark)
    ) {
        // Tapped stat row on the Stats screen. Rendered as a root-level overlay
        // (below) so its scrim covers the tab bars, exactly like ItemInfoOverlay.
        var selectedStat by remember { mutableStateOf<StatInfo?>(null) }

        // Hoisted above the tab content so MapPanel can gate its map-canvas clickable on it.
        // Belt-and-braces since SplashPanel now swallows taps itself, but kept: it is the gate that
        // guarantees a press landing on the HUD's map canvas cannot fire openWorldMap while the
        // splash is up, without depending on the two composables' z-order staying as it is.
        var splashVisible by remember { mutableStateOf(true) }

        when (tab) {
            Tab.INVENTORY -> InventoryPanel(state)
            Tab.MAGIC -> MagicPanel(state)
            Tab.HUD -> MapPanel(state, splashVisible = splashVisible, onSelectTab = { tab = it })
            Tab.STATS -> StatsPanel(state, onSelectStat = { selectedStat = it })
            Tab.JOURNAL -> JournalPanel()
        }

        BottomTabBar(
            selected = tab,
            onSelect = {
                // Tapping JOURNAL always returns it to the chronological journal view, including
                // when it's already the selected tab (where the panel stays composed and would
                // otherwise keep showing whatever detail page was open).
                if (it == Tab.JOURNAL) JournalResetState.request()
                tab = it
            },
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .fillMaxWidth()
                .padding(12.dp)
        )

        // Transparent scrim: intercepts outside taps while a dropdown is open so they
        // dismiss the menu without also firing the click handler of the row beneath.
        // Uses PointerEventPass.Initial so the DOWN event is seen but not consumed,
        // letting scroll gestures reach the LazyColumn; only a confirmed tap-UP is consumed.
        if (DropdownState.anyOpen) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .zIndex(10f)
                    .pointerInput(Unit) {
                        awaitEachGesture {
                            val down = awaitPointerEvent(PointerEventPass.Initial)
                            val startPos = down.changes.firstOrNull()?.position
                                ?: return@awaitEachGesture
                            var dragged = false
                            while (true) {
                                val event = awaitPointerEvent(PointerEventPass.Initial)
                                val change = event.changes.firstOrNull() ?: break
                                if ((change.position - startPos).getDistance() > viewConfiguration.touchSlop) {
                                    dragged = true
                                }
                                if (!change.pressed) {
                                    if (!dragged) {
                                        change.consume()
                                        DropdownState.closeAll()
                                    }
                                    break
                                }
                            }
                        }
                    }
            )
        }

        // Key on the stable hasData boolean (false→true once), NOT on
        // state.lastUpdateMs: COMPANION_STATS ticks every 0.1s, so keying on
        // lastUpdateMs cancels+restarts this effect every ~100ms and the
        // delay(500ms) can never complete — the splash would only ever dismiss
        // on a manual tap. hasData flips exactly once, so the delay runs to
        // completion and auto-dismisses on first load.
        LaunchedEffect(state.hasData) {
            if (state.hasData && splashVisible) {
                delay(500L.milliseconds)
                splashVisible = false
            }
        }
        if (splashVisible) {
            SplashPanel()
        }

        // Item info popup — a small, position-aware tooltip anchored near the triggering item
        // (long-press → Info, or R3 on the focused item). In-window overlay (NOT a Dialog — see the
        // Presentation window-type mismatch). Base rows arrive async via COMPANION_INFO; the
        // enchant section renders instantly from the local item's `enchant`. Dismiss: tap the scrim,
        // R3 again (toggle), or it follows D-pad focus to the newly focused item.
        // Bottom-screen host: renders unless the trigger came from a SPLIT top-grid cell (then the
        // top overlay hosts it — see ItemInfoPopupHost usage in LootingTopOverlay/BarterTopOverlay).
        if (ItemInfoPopupState.isOpen && !ItemInfoPopupState.onTopScreen) {
            ItemInfoPopupHost()
        }

        // Stat detail popup (Stats screen). Same in-window overlay pattern as
        // ItemInfoOverlay — tap outside to dismiss.
        selectedStat?.let { StatInfoPopup(it, onDismiss = { selectedStat = null }) }

        // Quantity prompt (e.g. "drop N of a stack"). Reusable in-window overlay
        // driven by QuantityRequestState; the confirm callback already carries the
        // action, so this just renders the picker.
        QuantityRequestState.request?.let { req ->
            QuantitySelector(
                name = req.name,
                max = req.max,
                confirmLabel = req.confirmLabel,
                initial = req.initial,
                showControllerHint = req.showControllerHint,
                onConfirm = req.onConfirm,
                onCancel = { QuantityRequestState.clear() }
            )
        }

        // Crime-reported toast — top of the whole z-stack so it's visible even over the looting /
        // barter panels (the native message renders behind them, bottom-center of the top screen).
        CrimeToast()

        // UI hints, in the same card. Hosted at the ROOT beside the crime toast, not inside the HUD
        // panel that raises them: a hint fires AS the tab switches away from the HUD, so anything
        // scoped to that panel would be torn down in the same frame and never seen.
        HintToast()

        // The turning journal leaf. Hosted HERE rather than inside JournalPanel because it has to
        // paint over the BOTTOM tab bar as well as the journal's own sub-tab bar — and BottomTabBar
        // is a later sibling at this level, so anything nested inside JournalPanel would draw
        // underneath it however it were z-ordered. Inert unless the chronological journal is open
        // with the page-turn animation on. Declared before AdaptiveDimOverlay so it dims too.
        JournalLeafOverlay()

        // Adaptive dimming — ABOVE everything else (see AdaptiveDimOverlay for why).
        AdaptiveDimOverlay()

        // Per-element Game UI mode. Each companion overlay is gated by its OWN element: when that
        // element is VANILLA it's suppressed so native OpenMW handles it; DS shows the companion
        // version. The tab UI (inventory/spells/stats/journal/HUD) works regardless.
        val lootingDs by UiPreferences.gameUiModeFlow("game_ui_looting").collectAsState()
        val conversationDs by UiPreferences.gameUiModeFlow("game_ui_conversation").collectAsState()
        val barteringDs by UiPreferences.gameUiModeFlow("game_ui_bartering").collectAsState()
        val persuasionDs by UiPreferences.gameUiModeFlow("game_ui_persuasion").collectAsState()
        val repairDs by UiPreferences.gameUiModeFlow("game_ui_repair").collectAsState()
        val restwaitDs by UiPreferences.gameUiModeFlow("game_ui_restwait").collectAsState()
        val travelDs by UiPreferences.gameUiModeFlow("game_ui_travel").collectAsState()

        // Looting / pickpocketing overlay. Driven by COMPANION_CONTAINER_* from the
        // engine (via Lua). Shown whenever a container session is active, regardless
        // of Hide UI — same as the dialogue overlay, so the panel stays available
        // when the player hides the in-game HUD (the native container window is left
        // in place; this overlay is additive, not a replacement). It renders at
        // zIndex 15f (above the global dropdown-dismiss scrim so its buttons stay
        // tappable; it hosts its own local dismiss-scrim) and below QuantitySelector
        // (20f) so take/put quantity prompts stack above it.
        val containerSession by GameStateRepository.containerSession.collectAsState()
        val lootingLocation by UiPreferences.lootingLocationFlow().collectAsState()
        if (lootingDs == GameUiMode.DS) {
            containerSession?.let { session ->
                LootingOverlay(
                    session = session,
                    playerInventory = state.inventory,
                    playerEquipment = state.equipment,
                    playerEncumbrance = state.encumbrance,
                    location = lootingLocation
                )
            }
        }

        // Active-dialogue overlay. Driven by COMPANION_DIALOGUE_* from the engine and
        // shown over whatever tab is active. There is NO tap-away dismiss: it closes
        // only when the conversation ends (engine sends COMPANION_DIALOGUE_CLOSED →
        // both lists empty) or the player taps a topic/GOODBYE. Topics or services
        // non-empty = a conversation is open.
        val dialogueTopics by GameStateRepository.dialogueTopics.collectAsState()
        val dialogueServices by GameStateRepository.dialogueServices.collectAsState()
        val dialogueNpcName by GameStateRepository.dialogueNpcName.collectAsState()
        val dialogueHistory by GameStateRepository.dialogueHistory.collectAsState()
        val dialogueChoices by GameStateRepository.dialogueChoices.collectAsState()
        val dialogueDisposition by GameStateRepository.dialogueDisposition.collectAsState()
        val dialoguePersuadeAvailable by GameStateRepository.dialoguePersuadeAvailable.collectAsState()
        val dialogueGold by GameStateRepository.dialogueGold.collectAsState()
        if (conversationDs == GameUiMode.DS && (dialogueNpcName.isNotEmpty() || dialogueTopics.isNotEmpty() ||
                dialogueServices.isNotEmpty() || dialogueHistory.isNotEmpty() ||
                dialogueChoices.isNotEmpty())
        ) {
            // Bottom-screen conversation UI depends on where the conversation is routed:
            // - BOTTOM: the classic full two-column overlay here.
            // - SPLIT: history is on the top screen; the bottom shows ONLY the controls.
            // - TOP: the whole conversation is on the top screen (hosted by EngineActivity);
            //   the bottom screen is just a dimmed, inert scrim over the current tab.
            val conversationLocation by UiPreferences.conversationLocationFlow().collectAsState()
            // Show the "Persuade" entry whenever the NPC offers persuasion, in BOTH modes: DS opens
            // the companion popup, Vanilla opens the native modal (see triggerPersuade). Gating it to
            // DS-only previously left Vanilla persuasion with no trigger in a DS conversation.
            val persuadeAvailable = dialoguePersuadeAvailable
            DialogueTopicsOverlay(
                dialogueNpcName, dialogueHistory, dialogueTopics, dialogueServices,
                dialogueChoices, dialogueDisposition, persuadeAvailable,
                location = conversationLocation
            )
        }

        // Persuasion popup — BOTTOM location. Hosted at the CompanionScreen root (independent of the
        // conversation overlay above, so it works even when the conversation is routed to the top
        // screen). Open-state is the shared GameStateRepository.persuasionVisible flow (set by the
        // Persuade row, reset on Cancel / conversation-close / NPC-change). Gated on the persuasion
        // element being DS. The TOP location is a separate top-screen panel window (EngineActivity).
        // Renders at PersuasionPopup's own zIndex(30f) — above the dialogue (15f) / service overlays.
        val persuasionVisible by GameStateRepository.persuasionVisible.collectAsState()
        val persuasionLocation by UiPreferences.persuasionLocationFlow().collectAsState()
        if (persuasionVisible && persuasionLocation == PersuasionLocation.BOTTOM &&
            persuasionDs == GameUiMode.DS
        ) {
            // Prefer the live COMPANION_DIALOGUE_GOLD value (updates after a bribe); fall back to the
            // inventory gold_001 count until the first gold line arrives.
            val persuasionGold = if (dialogueGold >= 0) dialogueGold
                else state.inventory.firstOrNull { it.id.equals("gold_001", ignoreCase = true) }?.count ?: 0
            // Band-sized only when the conversation controls are the SPLIT bottom band, matching them.
            val conversationLocation by UiPreferences.conversationLocationFlow().collectAsState()
            PersuasionPopup(
                gold = persuasionGold,
                bandSized = conversationLocation == ConversationLocation.SPLIT,
                onPersuade = { type ->
                    CompanionActions.persuade(type); GameStateRepository.setPersuasionVisible(false)
                },
                onCancel = { GameStateRepository.setPersuasionVisible(false) }
            )
        }

        // Barter overlay. Driven by COMPANION_BARTER_* from the engine (native TradeWindow),
        // shown over whatever tab/dialogue is active whenever a barter session exists —
        // regardless of Hide UI (the companion-hide-barter-on-hideui patch makes the bottom
        // screen the sole barter surface). Renders above the dialogue overlay (barter is
        // pushed on top of the conversation) at zIndex 16f; the rejection alert stacks above
        // at 18f; the shared QuantitySelector (20f) stacks above both for stack-split prompts.
        // The disposition bar reuses the dialogue disposition (the native TradeWindow re-emits
        // COMPANION_DIALOGUE_DISPOSITION during barter — DialogueWindow::onFrame is dormant then).
        val barterSession by GameStateRepository.barterSession.collectAsState()
        val barterResult by GameStateRepository.barterResult.collectAsState()
        val barterLocation by UiPreferences.barterLocationFlow().collectAsState()
        if (barteringDs == GameUiMode.DS) {
            barterSession?.let { session ->
                BarterOverlay(session = session, disposition = dialogueDisposition, location = barterLocation)
            }
            if (barterSession != null) {
                (barterResult as? BarterResult.Rejected)?.let { rej ->
                    BarterRejectedAlert(rej.reason) { GameStateRepository.dismissBarterResult() }
                }
            }
        }

        // Merchant-repair overlay. Driven by COMPANION_REPAIR_* from the engine (native
        // MerchantRepair window). Shown over whatever tab/dialogue is active whenever a repair
        // session exists AND Repair is in DS mode (Vanilla → native OpenMW handles it). A
        // centred popup (zIndex 17f, above barter's 16f — repair is a dialogue service pushed
        // like barter); the shared QuantitySelector (20f) still stacks above.
        val repairSession by GameStateRepository.repairSession.collectAsState()
        if (repairDs == GameUiMode.DS) {
            repairSession?.let { session ->
                RepairOverlay(session = session)
            }
        }

        // Travel overlay. Driven by COMPANION_TRAVEL_* from the engine (native TravelWindow). Shown
        // over whatever tab/dialogue is active whenever a travel session exists AND Travel is DS
        // (Vanilla → native OpenMW handles it). Centred popup (zIndex 17f, same tier as repair —
        // travel is a dialogue service pushed like barter/repair, never open simultaneously with them).
        val travelSession by GameStateRepository.travelSession.collectAsState()
        if (travelDs == GameUiMode.DS) {
            travelSession?.let { session ->
                TravelOverlay(session = session)
            }
        }

        // Training overlay. Driven by COMPANION_TRAINING_* (native TrainingWindow). Shown while
        // Training is DS. NOT gated purely on the session: the "Training…"/completion messages must
        // outlive the session going null on COMPANION_TRAINING_CLOSED, so the host latches its own
        // mount (see TrainingOverlayHost's LIST→TRAINING→COMPLETE machine). zIndex 17f (repair tier).
        val trainingDs by UiPreferences.gameUiModeFlow("game_ui_training").collectAsState()
        val trainingSession by GameStateRepository.trainingSession.collectAsState()
        if (trainingDs == GameUiMode.DS) {
            TrainingOverlayHost(session = trainingSession)
        }

        // Level-up overlay. Driven by COMPANION_LEVELUP_* — display data from Lua, selection state
        // and the coin count from the NATIVE LevelupDialog. Shown while Level up is DS. zIndex 18f:
        // one above the dialogue-service tier because level-up is modal in a way those are not —
        // there is no cancel, and nothing else can legitimately sit over it.
        val levelUpDs by UiPreferences.gameUiModeFlow("game_ui_levelup").collectAsState()
        val levelUpSession by GameStateRepository.levelUpSession.collectAsState()
        if (levelUpDs == GameUiMode.DS) {
            levelUpSession?.let { session ->
                LevelUpOverlay(session = session)
            }
        }

        // Alchemy overlay. Driven by COMPANION_ALCHEMY_* (native AlchemyWindow) — the whole batch
        // is read off the live MWMechanics::Alchemy after every mutation, so nothing about the
        // mechanic lives here. Shown while Alchemy is DS. zIndex 18f: like level-up it fully
        // REPLACES a native window rather than layering over a conversation, and the TOP half of
        // the screen (name + apparatus + created effects) is its own overlay in EngineActivity.
        val alchemyDs by UiPreferences.gameUiModeFlow("game_ui_alchemy").collectAsState()
        val alchemySession by GameStateRepository.alchemySession.collectAsState()
        if (alchemyDs == GameUiMode.DS) {
            alchemySession?.let { session ->
                AlchemyOverlay(session = session)
            }
        }

        // DS map controls (bottom screen). The map itself is the TOP-screen overlay; this is the
        // toggle, zoom and note UI. Mounting this composable is ALSO what sets the native
        // suppression flag (see MapDsControls' DisposableEffect), so the native map window is
        // hidden exactly as long as this is on screen and not one frame longer.
        val mapDs by UiPreferences.gameUiModeFlow("game_ui_map").collectAsState()
        val mapOpen by GameStateRepository.mapModeOpen.collectAsState()
        if (mapDs == GameUiMode.DS && mapOpen) {
            MapDsControls()
        }

        // Enchanting overlay. Driven by COMPANION_ENCHANTING_* (native EnchantingDialog) — the whole
        // batch is read off the live MWMechanics::Enchanting after every mutation, so nothing about
        // the mechanic lives here. Shown while Enchanting is DS. zIndex 18f, like alchemy: it fully
        // REPLACES a native window, and the TOP half (name + stats + effects readout) is its own
        // overlay in EngineActivity.
        val enchantDs by UiPreferences.gameUiModeFlow("game_ui_enchanting").collectAsState()
        val enchantSession by GameStateRepository.enchantSession.collectAsState()
        if (enchantDs == GameUiMode.DS) {
            enchantSession?.let { session ->
                EnchantingOverlay(session = session)
            }
        }

        // Spellmaking overlay. Driven by COMPANION_SPELLMAKING_* (native SpellCreationDialog), the
        // sibling of the enchanting screen above: same shared effect editor, same zIndex, same
        // top/bottom split. The two can never be up at once — both are GUI modes pushed over
        // dialogue — so they do not need to coordinate.
        val spellmakingDs by UiPreferences.gameUiModeFlow("game_ui_spellmaking").collectAsState()
        val spellmakingSession by GameStateRepository.spellmakingSession.collectAsState()
        if (spellmakingDs == GameUiMode.DS) {
            spellmakingSession?.let { session ->
                SpellmakingOverlay(session = session)
            }
        }

        // Spell-buying overlay. Driven by COMPANION_SPELLBUYING_* (native SpellBuyingWindow). Shown
        // whenever a session exists AND Spell buying is DS. The engine re-exports the list after each
        // purchase (bought spell flips to known=1, keeping its slot). zIndex 17f (repair tier).
        val spellBuyingDs by UiPreferences.gameUiModeFlow("game_ui_spellbuying").collectAsState()
        val spellBuyingSession by GameStateRepository.spellBuyingSession.collectAsState()
        if (spellBuyingDs == GameUiMode.DS) {
            spellBuyingSession?.let { session ->
                SpellBuyingOverlay(session = session)
            }
        }

        // Rest/wait overlay. Driven by COMPANION_SLEEP_* from the engine (native WaitDialog).
        // Shown whenever a rest/wait picker is open AND Rest/Wait is DS. Confirming dismisses it
        // (the engine runs the fade + time advance on the top screen). zIndex 17f (same tier as
        // repair — they're never open simultaneously).
        val sleepSession by GameStateRepository.sleepSession.collectAsState()
        if (restwaitDs == GameUiMode.DS) {
            sleepSession?.let { session ->
                RestWaitOverlay(session = session)
            }
        }

        // On-screen text-entry keyboard. Driven by COMPANION_TEXT_INPUT_OPEN/_CLOSED (native, when a
        // MyGUI EditBox — character name / class name / save name — gains/loses key focus). A CUSTOM
        // Compose keyboard, NOT the Android IME: the OS keyboard is a focusable window that steals the
        // input-focused display to the bottom screen (controller then hits the bottom launcher, not the
        // game — unrecoverable without a manual top-screen tap), and its screen depends on the user's
        // IME pinning. A tappable Compose overlay needs touch, not key-focus, so nothing ever steals
        // focus from the game and the keys are always on the bottom panel for every user. Enter sends
        // the existing CMPTEXT:set (fill the field + accept/advance the dialog natively).
        val textInputRequest by GameStateRepository.textInputRequest.collectAsState()
        textInputRequest?.let { initial ->
            TextInputOverlay(
                initialText = initial,
                onConfirm = { text ->
                    CompanionActions.submitTextInput(text)
                    GameStateRepository.dismissTextInput()
                }
            )
        }

        // Manual journal-entry composer — the SECOND, independent use of the same keyboard. Hosted
        // at the root (like the native one above) so it covers the tab bar and every panel, and
        // kept entirely separate from that instance: this one is cancellable and prose-shaped,
        // while the native one must keep its no-escape behaviour for prompts the game won't let you
        // dismiss. Nothing about the native path changes.
        if (ManualJournalComposerState.visible) {
            val gameDate by GameStateRepository.gameDate.collectAsState()
            // Publish an empty draft the moment the composer opens, so the TOP-screen preview
            // appears together with the card rather than only on the first keystroke; clear it on
            // both exits (confirm and cancel) via onDispose, which cannot be missed.
            DisposableEffect(Unit) {
                GameStateRepository.setManualJournalDraft("")
                onDispose { GameStateRepository.setManualJournalDraft(null) }
            }
            TextInputOverlay(
                initialText = "",
                title = "JOURNAL ENTRY",
                prose = true,
                onTextChange = { GameStateRepository.setManualJournalDraft(it) },
                onCancel = { ManualJournalComposerState.close() },
                onConfirm = { text ->
                    // Stamped from the live COMPANION_GAMEDATE and nothing else — never from the
                    // last journal entry (arbitrarily stale) and never from a sentinel (which would
                    // strand the entry on a phantom page). The button that opens this is gated on
                    // the same value, so the null branch is only reachable if the date vanished
                    // mid-compose; dropping the entry beats filing it under a guessed day.
                    gameDate?.let { d ->
                        CustomJournalRepository.add(text, d.day, d.month, d.dayOfMonth)
                    }
                    ManualJournalComposerState.close()
                }
            )
        }
    }
}

/**
 * Route a "Persuade" tap by the persuasion Game UI mode:
 *  - DS: open the companion persuasion popup (hosted by its own Screen Layout location).
 *  - Vanilla: open the NATIVE PersuasionDialog modal by selecting the sPersuasion topic
 *    (CMPDLG:topic:<name> -> onSelectListItem(sPersuasion) -> setVisible(true)); the DS overlay
 *    doesn't list persuasion as a topic, so this is the only trigger. The native modal's onOpen
 *    emits COMPANION_PERSUASION_OPEN, stepping the conversation overlay aside so it's visible.
 * Reads the mode/name synchronously off the flows (this runs on tap, not during composition).
 */
private fun triggerPersuade() {
    if (UiPreferences.gameUiModeFlow("game_ui_persuasion").value == GameUiMode.DS) {
        GameStateRepository.setPersuasionVisible(true)
    } else {
        val name = GameStateRepository.dialoguePersuadeTopicName.value
        if (name.isNotEmpty()) CompanionActions.selectDialogueTopic(name)
    }
}

/* ---- Dialogue topic list overlay (bottom screen) ---- */

@Composable
private fun DialogueTopicsOverlay(
    npcName: String,
    history: List<DialogueSay>,
    topics: List<String>,
    services: List<String>,
    choices: List<DialogueChoice>,
    disposition: Int,
    persuadeAvailable: Boolean,
    location: ConversationLocation
) {
    // Persuasion popup open-state is a shared repo flow now (the popup is hosted independently by
    // its own Screen Layout location — bottom root or top window — so it's not composed here).
    // While it's open the topic/service list is dimmed + inert, same as when a choice question is up.
    val persuasionVisible by GameStateRepository.persuasionVisible.collectAsState()

    // Non-interactive dark scrim (NOT a Dialog — that crashes on the Presentation display).
    // NO tap-away dismiss; the empty detectTapGestures swallows taps so they don't fall
    // through to the tab underneath. In TOP mode this scrim IS the entire bottom-screen UI:
    // the conversation itself lives on the top screen (hosted by EngineActivity).
    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(15f)
            .background(Color(0xCC0F0C08))
            .pointerInput(Unit) { detectTapGestures {} }
    ) {
        when (location) {
            // TOP: the whole conversation is on the top screen; the bottom screen is just a
            // dimmed, inert scrim (the active tab shows through). Nothing else to render.
            ConversationLocation.TOP -> Unit

            // SPLIT: history is on the top screen; the bottom screen shows ONLY the controls
            // (disposition, Barter, Repair, Persuade, topics, Goodbye) centred at [SPLIT_PANEL_WIDTH],
            // with the persuasion/choices popups over it.
            ConversationLocation.SPLIT -> {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    // The panel supplies its own vertical inset (see [splitDialoguePanel]); this box
                    // just centres it in the leftover space.
                    contentAlignment = Alignment.Center
                ) {
                    Column(
                        modifier = Modifier
                            .splitDialoguePanel()
                            .mwPanel()
                            .pointerInput(Unit) { detectTapGestures {} }
                    ) {
                        DialogueRightColumn(
                            topics = topics, services = services, disposition = disposition,
                            persuadeAvailable = persuadeAvailable,
                            // A choice question OR an open persuasion popup dims the topic/service/
                            // Goodbye rows and makes them inert; a choice's answers render inline in
                            // the history on the top screen (SPLIT), and the persuasion popup is
                            // hosted by its own location.
                            choicesActive = choices.isNotEmpty() || persuasionVisible,
                            interactive = choices.isEmpty() && !persuasionVisible,
                            onPersuadeTapped = { triggerPersuade() },
                            // SPLIT mode uses a larger, unified row font (topics/services on the
                            // bottom screen — matches the persuade/repair/travel popups).
                            // BOTTOM/TOP keep the default 13sp.
                            rowFontSize = SPLIT_ROW_FONT_SIZE,
                            // Chunkier rows + centred labels: SPLIT only (see the two params).
                            rowVerticalPadding = SPLIT_ROW_VERTICAL_PADDING,
                            centerRows = true,
                            modifier = Modifier.fillMaxSize().padding(8.dp)
                        )
                    }
                }
            }

            // BOTTOM: the classic full two-column conversation on the bottom screen. Choices render
            // inline in the history (below the newest response), matching vanilla, and are
            // controller-navigable. Fills the screen (12dp insets, covering the tab bar — dialogue
            // is a modal left via Goodbye).
            ConversationLocation.BOTTOM -> {
                DialogueConversationOverlay(
                    npcName = npcName, history = history, topics = topics, services = services,
                    choices = choices, disposition = disposition,
                    persuadeAvailable = persuadeAvailable,
                    panelAlignment = Alignment.Center,
                    panelWidthFraction = null, panelHeightFraction = null,
                    panelPadding = PaddingValues(12.dp)
                )
            }
        }
    }
}

/** The full interactive two-column conversation — NPC title bar, scrollable history (left)
 *  and the right column of controls. Shared by the BOTTOM-screen and TOP-screen full layouts.
 *  A mid-dialogue choice question renders INLINE in the history (below the newest response),
 *  matching vanilla — never a separate popup. The panel is sized/anchored by
 *  [panelWidthFraction]/[panelHeightFraction]/[panelAlignment]/[panelPadding] (null fraction =
 *  fill that axis). Must be placed inside a fillMaxSize parent Box. */
@Composable
private fun DialogueConversationOverlay(
    npcName: String,
    history: List<DialogueSay>,
    topics: List<String>,
    services: List<String>,
    choices: List<DialogueChoice>,
    disposition: Int,
    persuadeAvailable: Boolean,
    panelAlignment: Alignment,
    panelWidthFraction: Float?,
    panelHeightFraction: Float?,
    panelPadding: PaddingValues,
    // TOP mode: put the disposition bar in the name title bar (right side, ~aligned with the
    // right column below) and shrink the Goodbye button, freeing vertical room in the shorter
    // panel. false (BOTTOM) keeps the original layout (disposition at the top of the right column).
    compactLayout: Boolean = false
) {
    // Persuasion popup open-state is a shared repo flow (the popup is hosted separately by its own
    // Screen Layout location). While open, the topic/service list here is dimmed + inert.
    val persuasionVisible by GameStateRepository.persuasionVisible.collectAsState()

    Box(
        modifier = Modifier.fillMaxSize().padding(panelPadding),
        contentAlignment = panelAlignment
    ) {
        Column(
            modifier = Modifier
                .then(if (panelWidthFraction != null) Modifier.fillMaxWidth(panelWidthFraction) else Modifier.fillMaxWidth())
                .then(if (panelHeightFraction != null) Modifier.fillMaxHeight(panelHeightFraction) else Modifier.fillMaxHeight())
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures {} }
        ) {
            // ---- NPC name title bar (full width, window-title style) ----
            if (npcName.isNotEmpty()) {
                if (compactLayout) {
                    // Name on the left; disposition bar on the right (~35% width so it sits roughly
                    // above the right column, same horizontal location it occupied there before).
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 8.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(
                            npcName,
                            color = BronzeLight, fontSize = 14.sp,
                            fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                            maxLines = 1, overflow = TextOverflow.Ellipsis,
                            modifier = Modifier.weight(0.65f)
                        )
                        if (disposition >= 0) {
                            Box(Modifier.weight(0.35f).padding(start = 10.dp)) {
                                DispositionBar(disposition)
                            }
                        } else {
                            Spacer(Modifier.weight(0.35f))
                        }
                    }
                } else {
                    Text(
                        npcName,
                        color = BronzeLight, fontSize = 14.sp,
                        fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                        modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 8.dp)
                    )
                }
                Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            }

            // ---- Two columns: dialogue history (65%) | topics/services (35%) ----
            Row(Modifier.fillMaxSize()) {
                DialogueHistoryColumn(
                    // Choices render inline in the history (below the newest response).
                    history = history,
                    choices = choices,
                    topics = topics,
                    modifier = Modifier.weight(0.65f).fillMaxHeight().padding(8.dp)
                )
                Box(Modifier.fillMaxHeight().width(1.dp).background(BronzeDark))
                DialogueRightColumn(
                    topics = topics, services = services, disposition = disposition,
                    persuadeAvailable = persuadeAvailable,
                    // While a choice is active OR the persuasion popup is open, the topic/service/
                    // Goodbye rows stay visible but greyed and non-tappable — the popup takes
                    // priority over topic selection.
                    choicesActive = choices.isNotEmpty() || persuasionVisible,
                    interactive = choices.isEmpty() && !persuasionVisible,
                    onPersuadeTapped = { triggerPersuade() },
                    // TOP compact: disposition now lives in the name bar (don't repeat it here);
                    // the Goodbye button + topic rows tighten up, freeing vertical room for topics.
                    showDisposition = !compactLayout,
                    compact = compactLayout,
                    modifier = Modifier.weight(0.35f).fillMaxHeight().padding(8.dp)
                )
            }
        }
    }
}

/**
 * TOP-screen conversation overlay (Display 0). Hosted by [org.openmw.EngineActivity] in a
 * WindowManager panel window while a conversation is active AND the Conversation location is
 * SPLIT or TOP. Its content depends on the location:
 *  - SPLIT: a read-only, bottom-anchored history box (full width inside the 12dp inset, 51%
 *    height) — NPC name + scrolling history. The controls live on the bottom screen. (Touchable
 *    only for scrolling.)
 *  - TOP: the full interactive two-column conversation (history + controls + popups), the SAME
 *    full width, expanded to 92% height. The bottom screen is a dimmed, inert scrim.
 */
@Composable
fun ConversationHistoryOverlay() {
    val location by UiPreferences.conversationLocationFlow().collectAsState()
    val npcName by GameStateRepository.dialogueNpcName.collectAsState()
    val history by GameStateRepository.dialogueHistory.collectAsState()
    // Collected here (not just in the TOP branch) so the SPLIT read-only history below
    // can also retroactively highlight newly-introduced topics.
    val topics by GameStateRepository.dialogueTopics.collectAsState()

    if (location == ConversationLocation.TOP) {
        // Full interactive conversation on the top screen (bottom screen is scrim-only).
        val services by GameStateRepository.dialogueServices.collectAsState()
        val choices by GameStateRepository.dialogueChoices.collectAsState()
        val disposition by GameStateRepository.dialogueDisposition.collectAsState()
        val persuadeAvailable by GameStateRepository.dialoguePersuadeAvailable.collectAsState()

        Box(Modifier.fillMaxSize()) {
            DialogueConversationOverlay(
                npcName = npcName, history = history, topics = topics, services = services,
                choices = choices, disposition = disposition,
                persuadeAvailable = persuadeAvailable,
                panelAlignment = Alignment.BottomCenter,
                // Full width within the 12dp padding → sides sit the same 12dp from the screen edge
                // as the bottom does (null = fillMaxWidth, no centred fraction).
                panelWidthFraction = null,
                panelHeightFraction = 0.48f,  // ~60% of the old 0.70, then +15% to fit more topics
                panelPadding = PaddingValues(start = 12.dp, end = 12.dp, bottom = 12.dp),
                // TOP compact layout: disposition moves into the name bar and the Goodbye button
                // shrinks, reclaiming vertical space for topics in the shorter panel.
                compactLayout = true
            )
        }
        return
    }

    // SPLIT: read-only history box (bottom-anchored, full width inside the inset, 51% height). A mid-dialogue
    // choice question renders inline here (with the conversation), controller-navigable — the
    // controls live on the bottom screen but the choices live with the text, matching vanilla.
    val choices by GameStateRepository.dialogueChoices.collectAsState()
    Box(
        modifier = Modifier
            .fillMaxSize()
            .padding(start = 12.dp, end = 12.dp, bottom = 12.dp),
        contentAlignment = Alignment.BottomCenter
    ) {
        Column(
            modifier = Modifier
                // Full width inside the 12dp inset — the SAME width TOP mode uses (which passes
                // panelWidthFraction = null), so switching Conversation location doesn't resize the
                // history box. Was 0.75f (~25% narrower) until Aug 20 2026.
                .fillMaxWidth()
                .fillMaxHeight(0.51f)            // ~10% taller than the previous 0.46
                .adaptiveDimTint()
                .clip(RoundedCornerShape(3.dp))
                // Hand-rolled rather than mwPanel() (different width/height), so it must apply the
                // top-panel opacity itself or the SPLIT read-only history would stay opaque while
                // every neighbouring panel faded.
                .background(StonePanel.copy(alpha = LocalPanelOpacity.current))
                .border(2.dp, Bronze, RoundedCornerShape(3.dp))
        ) {
            if (npcName.isNotEmpty()) {
                Box(
                    modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 8.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        npcName,
                        color = BronzeLight, fontSize = 15.sp,
                        fontFamily = MwDisplay, fontWeight = FontWeight.Bold
                    )
                }
                Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            }
            // interactive = true so topic hyperlinks AND inline choices are tappable/navigable on
            // the top screen (the panel window has FLAG_NOT_TOUCHABLE removed, so touch reaches
            // these clickable spans; the controller drives choice nav via the shared navEvent flow).
            // choicesHorizontal = true → the short, wide Split box lays the options side-by-side,
            // navigated Left/Right (BOTTOM/TOP keep the vertical Up/Down stack).
            DialogueHistoryColumn(
                history = history,
                choices = choices,
                topics = topics,
                modifier = Modifier.fillMaxSize().padding(12.dp),
                interactive = true,
                choicesHorizontal = true
            )
        }
    }
}

/**
 * Top-screen persuasion popup (a panel-window ComposeView added by EngineActivity on Display 0 when
 * the persuasion Screen Layout location is [PersuasionLocation.TOP] AND the popup is open). The
 * window's lifecycle is driven by [GameStateRepository.persuasionVisible]; this just renders the
 * centred [PersuasionPopup] card. Fully interactive (the window omits FLAG_NOT_TOUCHABLE). Actions
 * send the persuade command and clear the shared open-flow; Cancel clears it.
 */
@Composable
fun PersuasionTopOverlay() {
    val dialogueGold by GameStateRepository.dialogueGold.collectAsState()
    val state by GameStateRepository.state.collectAsState()
    // Prefer the live COMPANION_DIALOGUE_GOLD value (updates after a bribe); fall back to inventory.
    val gold = if (dialogueGold >= 0) dialogueGold
        else state.inventory.firstOrNull { it.id.equals("gold_001", ignoreCase = true) }?.count ?: 0

    Box(Modifier.fillMaxSize()) {
        PersuasionPopup(
            gold = gold,
            bandSized = false,   // centred card on the top screen (never the SPLIT bottom band)
            onPersuade = { type ->
                CompanionActions.persuade(type); GameStateRepository.setPersuasionVisible(false)
            },
            onCancel = { GameStateRepository.setPersuasionVisible(false) }
        )
    }
}

/**
 * Top-screen combat-target health overlay (a panel-window ComposeView added by EngineActivity on
 * Display 0 when [TargetHealthLocation.TOP] is selected AND a combat target exists). Top-centre,
 * 8dp from top, 30% of screen width: target name, a full-width red health bar, and a percentage.
 * Renders nothing when there is no target (EngineActivity also removes the window then).
 */
@Composable
fun CombatTargetTopOverlay() {
    val state by GameStateRepository.state.collectAsState()
    val target = state.target ?: return

    Box(
        modifier = Modifier.fillMaxSize().padding(top = 8.dp),
        contentAlignment = Alignment.TopCenter
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth(0.30f)
                // Adaptive dim on the BAR COLUMN, not the fillMaxSize parent: SrcAtop tints only
                // pixels this element actually drew, so no background is needed (and none is added —
                // that would change the look at 0% dim) and there is no full-screen layer. When the
                // overlay draws nothing it is not composed at all, so no dimmed rectangle can linger.
                .adaptiveDimTint()
                .padding(horizontal = 10.dp, vertical = 6.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Health bar first so it sits at the same vertical offset as the player's health bar
            // (the top bar of PlayerCombatTopOverlay) — both columns are 8dp from top with the same
            // 6dp padding. The NPC name goes UNDER the bar to keep them horizontally aligned.
            CombatBar(
                ratio = target.health.ratio,
                color = HealthCol,
                centerText = "${(target.health.ratio * 100).roundToInt()}%",
                // Match the player combat overlay's compact bar height.
                height = 9.dp, textSize = 7.sp
            )
            Spacer(Modifier.height(3.dp))
            Text(
                target.name,
                color = BronzeLight, fontSize = 10.sp, fontFamily = MwDisplay,
                fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis
            )
        }
    }
}

/**
 * Top-screen live preview of a manual journal entry as it is typed on the bottom screen.
 *
 * Non-interactive by construction — EngineActivity adds it with FLAG_NOT_TOUCHABLE, so every touch
 * still reaches the game; all input happens on the bottom-screen keyboard. Styled as a page of the
 * journal (the same date header + body treatment as [JournalColumn]) so what the player sees while
 * writing is what the entry will look like once it is filed.
 *
 * Renders nothing when no draft is in progress; [GameStateRepository.manualJournalDraft] is null
 * except while the composer is open.
 */
/**
 * TOP-screen half of the DS level-up screen: the class image and the flavour paragraph.
 *
 * These live up here because the top screen is otherwise idle during this modal moment, and
 * because they are the two purely-decorative parts — putting them on the bottom screen would push
 * the attribute grid, which is what the player actually has to interact with, into a scroll.
 *
 * Non-interactive (hosted with FLAG_NOT_TOUCHABLE), so it never takes touch away from the game.
 *
 * The image is genuinely dynamic: the name is derived from the lifetime specialization counters,
 * exactly as MWGui::LevelupDialog does, and resolves to textures/levelup/<name>.dds — the same
 * asset vanilla would have shown. It is NOT simplified to a static picture.
 */
@Composable
fun LevelUpTopOverlay() {
    val session by GameStateRepository.levelUpSession.collectAsState()
    val s = session ?: return
    val image = rememberItemIcon(if (s.image.isBlank()) "" else "textures/levelup/${s.image}.dds")

    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
        Column(
            Modifier
                .fillMaxWidth(0.62f)
                .clip(RoundedCornerShape(4.dp))
                .background(StonePanel.copy(alpha = LocalPanelOpacity.current))
                .border(2.dp, BronzeLight, RoundedCornerShape(4.dp))
                .adaptiveDimTint()
                .padding(14.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            if (image != null) {
                Image(
                    bitmap = image,
                    contentDescription = null,
                    contentScale = ContentScale.Fit,
                    modifier = Modifier.fillMaxWidth().heightIn(max = 190.dp)
                )
                Spacer(Modifier.height(10.dp))
            }
            Text(
                "You have ascended to level ${s.level}",
                color = BronzeLight, fontSize = 17.sp, fontFamily = MwDisplay,
                fontWeight = FontWeight.Bold, textAlign = TextAlign.Center
            )
            if (s.flavour.isNotBlank()) {
                Spacer(Modifier.height(8.dp))
                Text(
                    s.flavour,
                    color = Bone, fontSize = 12.sp, fontFamily = MwBody,
                    textAlign = TextAlign.Center, lineHeight = 16.sp
                )
            }
        }
    }
}

@Composable
fun ManualJournalDraftTopOverlay() {
    val draft by GameStateRepository.manualJournalDraft.collectAsState()
    val text = draft ?: return
    val gameDate by GameStateRepository.gameDate.collectAsState()
    // The date this entry WILL be stamped with, rendered through the same helper the real journal
    // uses — so the preview cannot drift from the filed entry's header.
    val dateLabel = gameDate?.let {
        journalDateLabel(
            JournalEntry(
                questId = MANUAL_QUEST_ID, questName = MANUAL_QUEST_NAME, text = "",
                day = it.day, month = it.month, dayOfMonth = it.dayOfMonth
            )
        )
    }

    Box(
        modifier = Modifier.fillMaxSize().padding(top = 40.dp),
        contentAlignment = Alignment.TopCenter
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth(0.46f)
                .mwPanel()
                .padding(horizontal = 14.dp, vertical = 12.dp)
        ) {
            if (dateLabel != null) {
                Text(
                    dateLabel,
                    color = BronzeLight, fontSize = 12.sp, fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.padding(bottom = 4.dp)
                )
            }
            Text(
                // An empty draft would collapse the panel to a sliver the instant it appeared, so
                // show the prompt until the first keystroke.
                text.ifEmpty { "…" },
                color = if (text.isEmpty()) BoneDim else Bone,
                fontSize = 14.sp, fontFamily = MwBody, lineHeight = 18.sp
            )
        }
    }
}

/**
 * Top-screen player-status-in-combat overlay (a panel-window ComposeView added by EngineActivity on
 * Display 0 when the "Player status in combat" option is On AND a combat target exists). Top-left,
 * 8dp from top / 12dp from left, 20% of screen width: three stacked labelled bars for
 * Health / Magicka / Fatigue with "current/max" values. Renders nothing when there is no target.
 */
@Composable
fun PlayerCombatTopOverlay() {
    val state by GameStateRepository.state.collectAsState()
    if (state.target == null) return

    Box(
        modifier = Modifier.fillMaxSize().padding(top = 8.dp, start = 12.dp),
        contentAlignment = Alignment.TopStart
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth(0.15f)
                // Same treatment as CombatTargetTopOverlay — tint the bars themselves, no panel.
                .adaptiveDimTint()
                .padding(horizontal = 8.dp, vertical = 6.dp)
        ) {
            // No labels — the bar colours communicate which vital is which. The "cur/max" value
            // rides INSIDE each bar. Compact sizing: 9dp bars (half the target overlay's 18dp) with a
            // 7sp value that still fits, at 15% screen width (25% narrower than before).
            CombatBar(ratio = state.health.ratio, color = HealthCol, centerText = dynValue(state.health),
                height = 9.dp, textSize = 7.sp)
            Spacer(Modifier.height(3.dp))
            CombatBar(ratio = state.magicka.ratio, color = MagickaCol, centerText = dynValue(state.magicka),
                height = 9.dp, textSize = 7.sp)
            Spacer(Modifier.height(3.dp))
            CombatBar(ratio = state.fatigue.ratio, color = FatigueCol, centerText = dynValue(state.fatigue),
                height = 9.dp, textSize = 7.sp)
        }
    }
}

/** "cur/max" for a [Dynamic], rounded — the value shown inside a player combat bar. */
private fun dynValue(dyn: Dynamic): String = "${dyn.current.roundToInt()}/${dyn.max.roundToInt()}"

/** A full-width stat bar (dark track, bronze border, [color] fill) for the combat overlays, with an
 *  optional [centerText] drawn centred INSIDE the bar (light, small, over the fill). [height] and
 *  [textSize] default to the target-overlay sizing; the player-combat overlay passes smaller values. */
@Composable
private fun CombatBar(
    ratio: Float,
    color: Color,
    centerText: String? = null,
    height: Dp = 18.dp,
    textSize: TextUnit = 8.sp,
) {
    Box(
        Modifier
            .fillMaxWidth()
            .height(height)
            .clip(RoundedCornerShape(2.dp))
            .background(Color(0xFF0E0B07))
            .border(1.dp, BronzeDark, RoundedCornerShape(2.dp)),
        contentAlignment = Alignment.Center
    ) {
        Box(
            Modifier
                .fillMaxWidth(ratio.coerceIn(0f, 1f))
                .fillMaxHeight()
                .clip(RoundedCornerShape(2.dp))
                .background(color)
                .align(Alignment.CenterStart)
        )
        if (centerText != null) {
            Text(
                centerText,
                color = Color.White, fontSize = textSize, fontFamily = MwData,
                fontWeight = FontWeight.Bold, maxLines = 1
            )
        }
    }
}

/** One navigable row in the dialogue right column: its [label] and what activating it does.
 *  Built in render order so the controller focus index maps 1:1 to a visible row. */
private class DialogueNavItem(val label: String, val onActivate: () -> Unit)

/** The dialogue right column — services, disposition bar, the Persuade trigger, the
 *  scrolling topics list and the Goodbye button. [choicesActive] greys the rows (a
 *  mid-dialogue question is showing its answers in the left column); [interactive] gates
 *  every tap — off while a choice is active OR while the persuasion column owns input.
 *  Owns controller navigation (Phase 2): D-pad up/down move focus through the services+topics
 *  list, A activates the focused row (B closes via the existing patch). This is the single
 *  composable rendering that list in every conversation location (BOTTOM/SPLIT/TOP), and only
 *  one instance is ever composed, so the nav collector below is unambiguous. */
@Composable
private fun DialogueRightColumn(
    topics: List<String>,
    services: List<String>,
    disposition: Int,
    persuadeAvailable: Boolean,
    choicesActive: Boolean,
    interactive: Boolean,
    onPersuadeTapped: () -> Unit,
    rowFontSize: TextUnit = 13.sp,
    // Row height. Null = derive from [compact] (7dp) / the BOTTOM default (9dp); SPLIT passes
    // [SPLIT_ROW_VERTICAL_PADDING] so its larger-font rows get proportionally chunkier buttons.
    rowVerticalPadding: Dp? = null,
    // Centre the row labels instead of left-aligning them. SPLIT only — the wide, short band panel
    // reads better centred; the tall BOTTOM/TOP columns stay left-aligned (a long topic list scans
    // faster down a straight left edge).
    centerRows: Boolean = false,
    // TOP compact layout: the caller renders the disposition bar in the name bar instead (so skip
    // it here); tighten the topic-row padding and match the Goodbye font to the topics font, to fit
    // more topic rows in the shorter panel.
    showDisposition: Boolean = true,
    compact: Boolean = false,
    modifier: Modifier = Modifier
) {
    // Per-topic read-status flags (name -> 0/Specific/Exhausted) for colouring the topic rows,
    // collected directly here (this column already reads the repo for nav/session state).
    val topicFlags by GameStateRepository.dialogueTopicFlags.collectAsState()
    // Barter, Repair and Travel are pulled out of the services list so they can sit above the
    // divider (matched by their display strings — the sBarter/sRepair/sTravel GMST values the engine
    // exports). EVERY other service drops into the scrollable list with the topics.
    val barterService = services.firstOrNull { it.equals("Barter", ignoreCase = true) }
    val spellsService = services.firstOrNull { it.equals("Spells", ignoreCase = true) }
    val repairService = services.firstOrNull { it.equals("Repair", ignoreCase = true) }
    // sSpellmakingMenuTitle / sEnchanting GMST display values (verified against Morrowind.esm);
    // matched case-insensitively so "SpellMaking"/"Spellmaking" spelling variants both hit.
    val spellmakingService = services.firstOrNull { it.equals("Spellmaking", ignoreCase = true) }
    val enchantingService = services.firstOrNull { it.equals("Enchanting", ignoreCase = true) }
    val trainingService = services.firstOrNull { it.equals("Training", ignoreCase = true) }
    val travelService = services.firstOrNull { it.equals("Travel", ignoreCase = true) }
    // "Beds" (renting a room) is a dialogue TOPIC in Morrowind, not a service window — it's exported
    // among the topics and (when tapped) fires a yes/no choice. Pull it out of whichever list it
    // arrives in so it can sit in the services block above the divider; dispatch it as a service or
    // a topic depending on where it came from.
    val bedsFromService = services.firstOrNull { it.equals("Beds", ignoreCase = true) }
    val bedsFromTopic = topics.firstOrNull { it.equals("Beds", ignoreCase = true) }
    val bedsService = bedsFromService ?: bedsFromTopic
    val otherServices = services.filter {
        it != barterService && it != spellsService && it != repairService &&
            it != spellmakingService && it != enchantingService && it != trainingService &&
            it != travelService && it != bedsService
    }
    val topicRows = topics.filter { it != bedsService }

    // Flattened, ordered navigable rows: the services block (Barter/Beds/Persuade/Repair/Travel),
    // then any OTHER services, then the dialogue topics — the SAME order they render, so the D-pad
    // focus index maps 1:1 to a visible row. Goodbye is deliberately excluded (controller B closes
    // the conversation via companion-b-button-choice-fix.patch).
    // Above-divider order: Persuade → Barter → Spells → Repair → Spellmaking → Enchanting →
    // Training → Travel → Beds. (Beds is the conditional rent-a-room topic; Persuade sits first.)
    val serviceBlock = buildList {
        if (persuadeAvailable) add(DialogueNavItem("Persuade") { onPersuadeTapped() })
        barterService?.let { s -> add(DialogueNavItem(s) { CompanionActions.activateDialogueService(s) }) }
        spellsService?.let { s -> add(DialogueNavItem(s) { CompanionActions.activateDialogueService(s) }) }
        repairService?.let { s -> add(DialogueNavItem(s) { CompanionActions.activateDialogueService(s) }) }
        spellmakingService?.let { s -> add(DialogueNavItem(s) { CompanionActions.activateDialogueService(s) }) }
        enchantingService?.let { s -> add(DialogueNavItem(s) { CompanionActions.activateDialogueService(s) }) }
        trainingService?.let { s -> add(DialogueNavItem(s) { CompanionActions.activateDialogueService(s) }) }
        travelService?.let { s -> add(DialogueNavItem(s) { CompanionActions.activateDialogueService(s) }) }
        bedsService?.let { s ->
            add(DialogueNavItem(s) {
                if (bedsFromService != null) CompanionActions.activateDialogueService(s)
                else CompanionActions.selectDialogueTopic(s)
            })
        }
    }
    val listRows = buildList {
        otherServices.forEach { s -> add(DialogueNavItem(s) { CompanionActions.activateDialogueService(s) }) }
        topicRows.forEach { t -> add(DialogueNavItem(t) { CompanionActions.selectDialogueTopic(t) }) }
    }
    val navItems = serviceBlock + listRows
    // Index of the first non-block row (where the bold services/topics divider is drawn). Prefixing
    // the divider onto that row keeps one lazy item per navItem, so focusIndex == lazy index.
    val dividerAt = serviceBlock.size

    // ---- Controller focus (Phase 2) --------------------------------------------------------------
    // Focus starts at the first row when the conversation opens (this composable enters composition),
    // persists across topic selections within a conversation, and is clamped as the topic list grows/
    // shrinks. Only ONE DialogueRightColumn is ever composed (BOTTOM/SPLIT/TOP), so this collector
    // uniquely owns dialogue navigation.
    var focusIndex by remember { mutableStateOf(0) }
    LaunchedEffect(navItems.size) {
        if (navItems.isEmpty()) focusIndex = 0
        else if (focusIndex > navItems.lastIndex) focusIndex = navItems.lastIndex
    }
    val listState = rememberLazyListState()
    LaunchedEffect(focusIndex) {
        if (focusIndex in navItems.indices) listState.animateScrollToItem(focusIndex)
    }
    val itemsState = rememberUpdatedState(navItems)
    val interactiveState = rememberUpdatedState(interactive)
    val choicesActiveState = rememberUpdatedState(choicesActive)
    LaunchedEffect(Unit) {
        // Skip the StateFlow's replayed latest value / any event that predates this overlay.
        var lastSeq = GameStateRepository.navEvent.value?.seq ?: -1L
        GameStateRepository.navEvent.collect { ev ->
            if (ev == null || ev.seq <= lastSeq) return@collect
            lastSeq = ev.seq
            // Yield to a choice question (the choices popup owns nav), a cancelable modal on top
            // (persuasion popup) OR any higher overlay pushed OVER the conversation (barter/repair/
            // travel/rest): its own collector owns nav while it's up, so the dialogue list doesn't
            // move — and A can't select a topic behind it. Barter is Phase-4; the rest are Phase-5.
            if (choicesActiveState.value ||
                ModalNav.open ||
                GameStateRepository.barterSession.value != null ||
                GameStateRepository.repairSession.value != null ||
                GameStateRepository.travelSession.value != null ||
                GameStateRepository.sleepSession.value != null ||
                GameStateRepository.trainingSession.value != null ||
                GameStateRepository.spellBuyingSession.value != null ||
                // Enchanting and Alchemy REPLACE a native window rather than layering a popup, so
                // they were easy to miss here — but Enchanting is a DIALOGUE SERVICE, so the
                // conversation stays composed underneath it and this collector kept running while
                // the DS enchanting screen was up: the D-pad moved the hidden topic list and A fired
                // CMPDLG:topic: behind the overlay (Aug 21 2026). Alchemy is only reachable from an
                // apparatus in the inventory, never from dialogue, so it is safe today — it is
                // listed anyway so the rule is "every DS service yields", not "the ones that
                // happened to bite".
                GameStateRepository.enchantSession.value != null ||
                GameStateRepository.spellmakingSession.value != null ||
                GameStateRepository.alchemySession.value != null
            ) return@collect
            val items = itemsState.value
            if (items.isEmpty()) return@collect
            when (ev) {
                is NavEvent.Down -> focusIndex = (focusIndex + 1) % items.size            // wraps
                is NavEvent.Up -> focusIndex = (focusIndex - 1 + items.size) % items.size  // wraps
                // A activates the focused row; only when the list is interactive (not while a choice
                // question is up — choices are navigated separately in Phase 5).
                is NavEvent.Confirm ->
                    if (interactiveState.value) items.getOrNull(focusIndex)?.onActivate?.invoke()
                else -> Unit // Left/Right/Action1/L2/R2/R1/slider are unused in the topic list
            }
        }
    }

    Column(modifier) {
        // 1. Disposition bar (fixed at the top). Hidden when unknown (< 0, e.g. a creature), and
        //    skipped entirely in compact/TOP mode where it's drawn in the name bar instead.
        //    A small divider below it stays put (outside the LazyColumn) while topics scroll.
        if (showDisposition && disposition >= 0) {
            DispositionBar(disposition)
            Spacer(Modifier.height(6.dp))
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.5f)))
            Spacer(Modifier.height(4.dp))
        }

        // 2. Services block + divider + other services + topics — one lazy item per navItem so the
        //    D-pad focus index maps directly to a lazy item. The divider is prefixed onto the
        //    boundary row (index == dividerAt), so it doesn't shift indices.
        LazyColumn(state = listState, modifier = Modifier.weight(1f).fillMaxWidth()) {
            itemsIndexed(navItems) { index, navItem ->
                if (index == dividerAt && dividerAt > 0) {
                    // Extra breathing room either side of the services/topics divider so it reads
                    // clearly — especially in Split mode and when Persuade (the last block row) is
                    // focused/highlighted right above it.
                    Spacer(Modifier.height(8.dp))
                    Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
                    Spacer(Modifier.height(8.dp))
                }
                DialogueOptionRow(
                    navItem.label,
                    dimmed = choicesActive,
                    fontSize = rowFontSize,
                    focused = index == focusIndex,
                    // Tighter rows in compact/TOP mode so more topics fit.
                    verticalPadding = rowVerticalPadding ?: if (compact) 7.dp else 9.dp,
                    centered = centerRows,
                    // Only the below-divider topic rows carry the read-status colour; the service
                    // block (Persuade/Barter/…/Beds) stays the normal colour. Service rows below the
                    // divider aren't in the flags map either, so they resolve to 0.
                    topicFlag = if (index >= dividerAt) topicFlags[navItem.label] ?: 0 else 0
                ) {
                    if (interactive) navItem.onActivate()
                }
            }
        }

        // 6. Goodbye (pinned to the bottom of the column). In compact/TOP mode the Goodbye font
        //    matches the topics font (rowFontSize) and the padding is a tight 4.5dp (half the prior
        //    9dp) so the button takes minimal vertical room; the smaller font keeps it legible.
        Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .background(BronzeDark.copy(alpha = 0.2f))
                .clickable { if (interactive) CompanionActions.dialogueGoodbye() }
                .padding(vertical = if (compact) 4.5.dp else 10.dp),
            contentAlignment = Alignment.Center
        ) {
            Text(
                "GOODBYE",
                color = if (choicesActive) BoneDim else BronzeLight,
                fontSize = if (compact) rowFontSize else 14.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                letterSpacing = 2.sp
            )
        }
    }
}

/** One tappable row in the right column — shared by topics, services and choices so
 *  they look identical (only the section header distinguishes them). [focused] draws the
 *  controller focus highlight (a 2dp BronzeLight border + faint fill) — deliberately a
 *  BORDER, distinct from any selection/worn styling elsewhere; dialogue rows are actions
 *  with no persistent "selected" state, so the border reads unambiguously as "cursor here". */
@Composable
private fun DialogueOptionRow(
    label: String,
    dimmed: Boolean = false,
    fontSize: TextUnit = 13.sp,
    focused: Boolean = false,
    verticalPadding: Dp = 9.dp,
    // Centre the label instead of left-aligning it (SPLIT topics band).
    centered: Boolean = false,
    // "color topic" read-status (0 none, 1 Specific-unheard, 2 Exhausted-read) — 0 for service/choice
    // rows. Colours a topic like the native list: BronzeLight = new/unheard, BoneDim = already read.
    topicFlag: Int = 0,
    onClick: () -> Unit
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .then(
                if (focused) Modifier
                    .background(BronzeLight.copy(alpha = 0.12f))
                    .border(2.dp, BronzeLight)
                else Modifier
            )
            .clickable(onClick = onClick)
    ) {
        Text(
            label,
            color = when {
                focused -> BoneBright
                dimmed -> BoneDim
                topicFlag and TOPIC_SPECIFIC != 0 -> BronzeLight   // NPC-specific info not yet heard
                topicFlag and TOPIC_EXHAUSTED != 0 -> BoneDim       // already read (in journal)
                else -> Bone
            },
            fontSize = fontSize, fontFamily = MwBody,
            textAlign = if (centered) TextAlign.Center else TextAlign.Start,
            modifier = Modifier.fillMaxWidth().padding(vertical = verticalPadding, horizontal = 4.dp)
        )
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.5f)))
    }
}

// "color topic" read-status bit flags (mirror MWBase::DialogueManager::TopicType).
private const val TOPIC_SPECIFIC = 1
private const val TOPIC_EXHAUSTED = 2

/** One persuasion option row + its hairline divider. Extracted so the SPLIT (LazyColumn) and
 *  BOTTOM/TOP (plain Column) branches of [PersuasionPopup] render identical rows. [alternate]
 *  draws the lighter of the two alternating row backgrounds. */
@Composable
private fun PersuasionOptionRow(
    label: String,
    enabled: Boolean,
    focused: Boolean,
    alternate: Boolean,
    fontSize: TextUnit,
    onClick: () -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .background(
                if (focused) BronzeLight.copy(alpha = 0.15f)
                else if (alternate) Color(0x22000000) else Color(0x11000000)
            )
            .then(if (focused) Modifier.border(2.dp, BronzeLight) else Modifier)
            .then(if (enabled) Modifier.clickable(onClick = onClick) else Modifier)
            .padding(horizontal = 16.dp, vertical = 12.dp)
    ) {
        Text(
            label,
            color = when {
                !enabled -> BoneDim
                focused -> BoneBright
                else -> Bone
            },
            fontSize = fontSize, fontFamily = MwBody
        )
    }
    Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
}

/** Persuasion popup — a centred in-window overlay (NOT a Dialog; that crashes on the
 *  Presentation display) + scrim. Six persuasion option rows (bribes greyed + non-tappable
 *  when the player can't afford them, live gold via dialogueGold), a gold readout and a Cancel
 *  button. Each option sends CMPDLG:persuade:<type> and closes the popup (matches native
 *  Morrowind — reopen Persuade for another attempt); only the Cancel button dismisses (the scrim
 *  swallows taps — no tap-outside dismiss). Hosted independently of the conversation overlay, by
 *  the persuasion Screen Layout location (BOTTOM = CompanionScreen root; TOP = a top-screen panel
 *  window). [bandSized] = draw as the SPLIT topics-band panel (bottom screen, SPLIT conversation)
 *  instead of a centred 360dp card. */
@Composable
private fun PersuasionPopup(gold: Int, bandSized: Boolean, onPersuade: (Int) -> Unit, onCancel: () -> Unit) {
    // label, persuade type (matches native companionPersuade switch), gold cost
    val options = listOf(
        Triple("Admire", 0, 0),
        Triple("Intimidate", 1, 0),
        Triple("Taunt", 2, 0),
        Triple("Bribe 10 Gold", 3, 10),
        Triple("Bribe 100 Gold", 4, 100),
        Triple("Bribe 1000 Gold", 5, 1000)
    )
    // In the SPLIT bottom-screen band the popups use a larger row font (matches the topics/services
    // increase); the centred card keeps the default size.
    val splitMode = bandSized
    val optionFontSize = if (splitMode) SPLIT_ROW_FONT_SIZE else 14.sp

    // Controller: this popup is a cancelable modal. Mark it open so the dialogue-topic nav collector
    // yields underneath (no accidental topic select behind it) and native routes B to cancel JUST the
    // popup (COMPANION_NAV_CANCEL) — returning to the conversation instead of closing it. Selecting an
    // option with the D-pad/A is Phase 5; for now B cancels and touch picks an option.
    DisposableEffect(Unit) {
        ModalNav.count++
        CompanionActions.setModalCancelOpen(true)
        onDispose {
            ModalNav.count--
            if (ModalNav.count == 0) CompanionActions.setModalCancelOpen(false)
        }
    }
    // D-pad up/down navigates the options, A selects the focused one (respecting affordability),
    // B cancels the popup (native → COMPANION_NAV_CANCEL while this modal is open).
    val focusIndex = rememberListNavFocus(
        itemCount = options.size,
        onConfirm = { i ->
            val (_, type, cost) = options[i]
            if (gold >= cost) onPersuade(type)
        },
        onCancel = onCancel,
    )
    // Keep the D-pad-focused option on screen in SPLIT (the only mode where the list scrolls).
    val optionListState = rememberLazyListState()
    LaunchedEffect(focusIndex) {
        if (splitMode && focusIndex in options.indices) optionListState.animateScrollToItem(focusIndex)
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(30f)
            .background(Color(0x99000000))
            // No tap-outside dismiss — the scrim swallows taps; only the Cancel button closes it.
            .pointerInput(Unit) { detectTapGestures {} },
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .then(if (splitMode) Modifier.splitDialoguePanel() else Modifier.width(360.dp))
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures {} }
        ) {
            Text(
                "Persuasion", color = BronzeLight, fontSize = 15.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp)
            )
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))

            // Options. In SPLIT the panel is height-bounded (fills the topics band), so the options
            // SCROLL — otherwise 6 rows at the larger split font overflow and push the gold/Cancel
            // row past the clipped panel edge (bug). In BOTTOM/TOP the panel wraps its content, so
            // the options render plain and the whole box grows to fit.
            //
            // SPLIT uses a LazyColumn + animateScrollToItem, NOT a verticalScroll Column: D-pad
            // focus has to drag the viewport with it. A plain scrollable Column has no way to do
            // that (rememberListNavFocus only moves an index; nothing scrolls a ScrollState), so
            // focus walked off the bottom edge invisibly — the reported bug, Aug 20 2026. Repair,
            // travel, training and spell-buying were already on this pattern; persuasion was the
            // one straggler.
            if (splitMode) {
                LazyColumn(state = optionListState, modifier = Modifier.weight(1f).fillMaxWidth()) {
                    itemsIndexed(options) { i, opt ->
                        PersuasionOptionRow(
                            label = opt.first, enabled = gold >= opt.third, focused = i == focusIndex,
                            alternate = i % 2 == 0, fontSize = optionFontSize,
                            onClick = { onPersuade(opt.second) }
                        )
                    }
                }
            } else {
                Column(Modifier.fillMaxWidth()) {
                    options.forEachIndexed { i, opt ->
                        PersuasionOptionRow(
                            label = opt.first, enabled = gold >= opt.third, focused = i == focusIndex,
                            alternate = i % 2 == 0, fontSize = optionFontSize,
                            onClick = { onPersuade(opt.second) }
                        )
                    }
                }
            }

            // Gold + Cancel — pinned below the (scrollable in SPLIT) options, always visible.
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    "Gold: $gold", color = BronzeLight, fontSize = 13.sp, fontFamily = MwData,
                    modifier = Modifier.weight(1f)
                )
                Box(
                    modifier = Modifier
                        .clip(RoundedCornerShape(2.dp))
                        .background(SlotBg)
                        .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
                        .clickable { onCancel() }
                        .padding(horizontal = 18.dp, vertical = 8.dp)
                ) {
                    Text(
                        "CANCEL", color = BronzeLight, fontSize = 12.sp,
                        fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 1.sp
                    )
                }
            }
        }
    }
}

/** Conversation disposition bar: "Disposition" label + "X/100" over a filled bar.
 *  Fill colour follows disposition thresholds — green above 50, amber 30..50, red below
 *  30. Same track/border/shape as [CompactStat] so it reads as one system. [value] is
 *  clamped 0..100; callers hide it entirely when disposition is unknown (< 0). */
@Composable
private fun DispositionBar(value: Int) {
    val v = value.coerceIn(0, 100)
    val fillColor = when {
        v > 50 -> Color(0xFF7FBF7F)   // green — beneficial (matches effect-dot green)
        v >= 30 -> Color(0xFFD9A441)  // amber — neutral/wary
        else -> Color(0xFFC75C5C)     // red — hostile (matches effect-dot red)
    }
    // No "Disposition" label (it overflowed the narrow column at 100/100). Just the bar
    // with the value to its right.
    Row(
        modifier = Modifier.fillMaxWidth(),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Box(
            modifier = Modifier
                .weight(1f)
                .height(9.dp)
                .clip(RoundedCornerShape(1.dp))
                .background(Color(0xFF0E0B07))
                .border(1.dp, BronzeDark, RoundedCornerShape(1.dp))
        ) {
            Box(
                modifier = Modifier
                    .fillMaxWidth(v / 100f)
                    .height(9.dp)
                    .clip(RoundedCornerShape(1.dp))
                    .background(fillColor)
            )
        }
        Spacer(Modifier.width(6.dp))
        Text("$v/100", color = Bone, fontSize = 12.sp, fontFamily = MwData)
    }
}

/**
 * Controller focus for a simple vertical single-column list overlay (Phase 5: persuasion, travel,
 * repair, choices). Owns a focus [index] into a list of [itemCount] items and consumes NavEvents:
 * D-pad Up/Down move focus (wrapping), A confirms the focused item ([onConfirm]), optional X
 * ([onAction1], e.g. Repair All) and B ([onCancel], for Compose-only modals — native B closes the
 * GM-mode overlays). [enabled] gates the whole collector so the overlay yields to a higher-priority
 * one on top (same pattern as Phase 4). Focus starts at 0 when the overlay opens and is clamped as
 * the list changes; returns the live focus index (-1 when empty). Only the topmost enabled collector
 * should act, so callers pass enabled = "no higher overlay is up".
 */
@Composable
private fun rememberListNavFocus(
    itemCount: Int,
    enabled: Boolean = true,
    // Which D-pad axis moves focus. false (default) = a vertical list (Up/Down); true = a
    // horizontal row (Left/Right — e.g. side-by-side choices in the Split conversation box).
    horizontal: Boolean = false,
    onConfirm: (Int) -> Unit,
    onAction1: (() -> Unit)? = null,
    onCancel: (() -> Unit)? = null,
    // R3 (NavEvent.Info) on the focused row — e.g. open the item/spell info popup. Null = ignore R3.
    onInfo: ((Int) -> Unit)? = null,
    // Y (NavEvent.Action2) — a second discrete action alongside [onAction1] (X). Null = ignore.
    onAction2: (() -> Unit)? = null,
    // L1 / R1 (NavEvent.L1 / NavEvent.R1) — discrete shortcuts that do NOT depend on focus, so
    // unlike [onConfirm]/[onInfo] they take no index. The loot/barter grids use these two for
    // per-column category cycling and have their own helpers; here they are free for whatever the
    // screen's two shoulder actions are (enchanting: open the item / soul picker). Null = ignore.
    onL1: (() -> Unit)? = null,
    onR1: (() -> Unit)? = null,
    // Called with the new focus index whenever D-pad moves focus. Called SYNCHRONOUSLY in the nav
    // collector (before recomposition) so an open info popup can follow to the newly focused row and
    // its anchor gets re-reported during the ensuing layout pass — mirrors the barter grid's follow.
    onFocusChanged: ((Int) -> Unit)? = null,
): Int {
    var index by remember { mutableStateOf(0) }
    LaunchedEffect(itemCount) {
        index = if (itemCount <= 0) 0 else index.coerceIn(0, itemCount - 1)
    }
    val enabledState = rememberUpdatedState(enabled)
    val countState = rememberUpdatedState(itemCount)
    val confirmState = rememberUpdatedState(onConfirm)
    val action1State = rememberUpdatedState(onAction1)
    val cancelState = rememberUpdatedState(onCancel)
    val infoState = rememberUpdatedState(onInfo)
    val action2State = rememberUpdatedState(onAction2)
    val l1State = rememberUpdatedState(onL1)
    val r1State = rememberUpdatedState(onR1)
    val focusChangedState = rememberUpdatedState(onFocusChanged)
    LaunchedEffect(Unit) {
        var lastSeq = GameStateRepository.navEvent.value?.seq ?: -1L
        GameStateRepository.navEvent.collect { ev ->
            if (ev == null || ev.seq <= lastSeq) return@collect
            lastSeq = ev.seq
            if (!enabledState.value) return@collect
            val n = countState.value
            // The "next"/"prev" events depend on the axis: horizontal → Right/Left, else Down/Up.
            val isNext = if (horizontal) ev is NavEvent.Right else ev is NavEvent.Down
            val isPrev = if (horizontal) ev is NavEvent.Left else ev is NavEvent.Up
            val before = index
            when {
                isNext -> if (n > 0) index = (index + 1) % n
                isPrev -> if (n > 0) index = (index - 1 + n) % n
                ev is NavEvent.Confirm -> if (n > 0) confirmState.value(index)
                ev is NavEvent.Action1 -> action1State.value?.invoke()
                ev is NavEvent.Cancel -> cancelState.value?.invoke()
                ev is NavEvent.Info -> if (n > 0) infoState.value?.invoke(index)
                ev is NavEvent.Action2 -> action2State.value?.invoke()
                ev is NavEvent.L1 -> l1State.value?.invoke()
                ev is NavEvent.R1 -> r1State.value?.invoke()
                else -> Unit
            }
            // Focus moved → let the caller follow (e.g. an open info popup) before recomposition.
            if (index != before) focusChangedState.value?.invoke(index)
        }
    }
    return if (itemCount > 0) index.coerceIn(0, itemCount - 1) else -1
}

/**
 * Right-stick scroll: nudges [state] by [step] pixels per tick, driven by the native per-frame
 * right-stick poll (companion-controller-nav.patch). The stick's axis is matched to the content's
 * axis: a VERTICAL list ([horizontal] = false) scrolls on right-stick up/down (ScrollUp/ScrollDown);
 * a HORIZONTAL grid ([horizontal] = true) scrolls on right-stick left/right (ScrollLeft/ScrollRight)
 * — so a physical left push scrolls left, right scrolls right. Each scrollable consumes only its own
 * axis's events, so the two never interfere.
 *
 * Each tick is a SHORT linear [animateScrollBy] (not an instant scrollBy) so that even when ticks
 * arrive at slightly irregular intervals (log-sink latency), each animation eases into the next and
 * the motion stays fluid; LinearEasing keeps constant velocity across ticks; the ~70ms tween ≈ the
 * native ~60ms cadence so animations chain back-to-back. [active] gates it so only the focused
 * scrollable reacts; it also yields while the quantity selector owns input.
 */
@Composable
private fun ScrollByNav(
    state: ScrollableState,
    active: Boolean = true,
    step: Float = 72f,
    horizontal: Boolean = false
) {
    val activeState = rememberUpdatedState(active)
    val spec = remember { tween<Float>(durationMillis = 70, easing = LinearEasing) }
    LaunchedEffect(Unit) {
        var lastSeq = GameStateRepository.navEvent.value?.seq ?: -1L
        GameStateRepository.navEvent.collect { ev ->
            if (ev == null || ev.seq <= lastSeq) return@collect
            lastSeq = ev.seq
            if (!activeState.value || ModalNav.open) return@collect
            // − = toward start (up / left), + = toward end (down / right).
            when {
                !horizontal && ev is NavEvent.ScrollUp -> state.animateScrollBy(-step, spec)
                !horizontal && ev is NavEvent.ScrollDown -> state.animateScrollBy(step, spec)
                horizontal && ev is NavEvent.ScrollLeft -> state.animateScrollBy(-step, spec)
                horizontal && ev is NavEvent.ScrollRight -> state.animateScrollBy(step, spec)
                else -> Unit
            }
        }
    }
}

/**
 * WINDOWED scroll-into-view for a controller-focused cell — the shared core behind the two
 * [WindowedFocusScroll] overloads below.
 *
 * These grids/rows used to call `animateScrollToItem(focusedIndex)` on every focus change, which
 * scrolls the focused item to the START of the viewport — so EVERY horizontal D-pad step dragged
 * the whole panel along and the selection was permanently pinned to the left-most column. Instead:
 * if the focused cell is already fully inside the viewport, don't scroll at all; if it hangs over an
 * edge, scroll by exactly the overhang so it comes just inside; only when it isn't laid out at all
 * (a jump, or a category filter swapping the content out from under the index) fall back to the old
 * [scrollToItem] jump.
 *
 * [itemStart]/[itemEnd] are the focused cell's MAIN-AXIS bounds (null = not currently laid out) and
 * [vpStart]/[vpEnd] the viewport's, in the same coordinate space — which is what makes one body
 * serve both a horizontal LazyGrid (x/width) and a LazyRow (offset/size).
 */
private suspend fun ScrollableState.scrollIntoWindow(
    itemStart: Int?,
    itemEnd: Int?,
    vpStart: Int,
    vpEnd: Int,
    scrollToItem: suspend () -> Unit
) {
    if (itemStart == null || itemEnd == null) { scrollToItem(); return }
    val delta = when {
        itemStart < vpStart -> itemStart - vpStart   // hangs off the START edge → scroll back
        itemEnd > vpEnd -> itemEnd - vpEnd           // hangs off the END edge → scroll forward
        else -> return                               // fully visible → leave the view alone
    }
    animateScrollBy(delta.toFloat())
}

/**
 * Keep the focused cell of a horizontal [LazyHorizontalGrid] in view WITHOUT pinning it to the left
 * edge — see [scrollIntoWindow]. [contentKey] is the visible list: re-running on a content change
 * (optimistic take/put, a category-filter swap) is what stops the focused cell being stranded
 * off-screen when the items move under a focus index that itself didn't change.
 */
@Composable
private fun WindowedFocusScroll(state: LazyGridState, focusedIndex: Int, itemCount: Int, contentKey: Any?) {
    LaunchedEffect(focusedIndex, contentKey) {
        if (focusedIndex !in 0 until itemCount) return@LaunchedEffect
        val info = state.layoutInfo
        val cell = info.visibleItemsInfo.firstOrNull { it.index == focusedIndex }
        state.scrollIntoWindow(
            itemStart = cell?.offset?.x,
            itemEnd = cell?.let { it.offset.x + it.size.width },
            vpStart = info.viewportStartOffset,
            vpEnd = info.viewportEndOffset,
        ) { state.animateScrollToItem(focusedIndex) }
    }
}

/** [WindowedFocusScroll] for a horizontal LazyRow (the shelf layout's category strips). */
@Composable
private fun WindowedFocusScroll(state: LazyListState, focusedIndex: Int, itemCount: Int, contentKey: Any?) {
    LaunchedEffect(focusedIndex, contentKey) {
        if (focusedIndex !in 0 until itemCount) return@LaunchedEffect
        val info = state.layoutInfo
        val cell = info.visibleItemsInfo.firstOrNull { it.index == focusedIndex }
        state.scrollIntoWindow(
            itemStart = cell?.offset,
            itemEnd = cell?.let { it.offset + it.size },
            vpStart = info.viewportStartOffset,
            vpEnd = info.viewportEndOffset,
        ) { state.animateScrollToItem(focusedIndex) }
    }
}

/** Left column: the running NPC-response history, auto-scrolled to the newest line.
 *  When [choices] is non-empty (a mid-dialogue question) the choice buttons render
 *  inline as the LAST item of the list, directly below the most recent response. */
@Composable
private fun DialogueHistoryColumn(
    history: List<DialogueSay>,
    choices: List<DialogueChoice>,
    modifier: Modifier = Modifier,
    interactive: Boolean = true,
    // Current known-topic list. Unioned with each response's own captured hyperlinks
    // so a topic INTRODUCED by a response (not yet known when that line was received —
    // see the COMPANION_DIALOGUE emit ordering) highlights retroactively once it lands
    // in this list. Passing it here (vs. only say.hyperlinks) is what makes the history
    // recompose when topics change.
    topics: List<String> = emptyList(),
    // Lay the inline choice block out side-by-side (a Row, Left/Right nav) instead of a
    // vertical stack (Up/Down). Only the Split top-screen box uses this — the box is short
    // and wide, so two options read better beside each other. BOTTOM/TOP keep the stack.
    choicesHorizontal: Boolean = false
) {
    val listState = rememberLazyListState()
    // Auto-scroll to the newest item — a fresh response OR the choice block appearing.
    // Keyed on both history.size and choices.size so choices scrolling into view is
    // covered; the choice block is appended after all history so the last index shifts
    // by one when it's present.
    LaunchedEffect(history.size, choices.size) {
        val itemCount = history.size + if (choices.isNotEmpty()) 1 else 0
        if (itemCount > 0) listState.animateScrollToItem(itemCount - 1)
    }
    // Right stick scrolls the conversation history.
    ScrollByNav(listState)
    // Controller focus for the inline choice block (a mid-dialogue question). Reuses the same
    // nav helper the old centred DialogueChoicesPopup used: D-pad move focus (Up/Down for the
    // vertical stack, Left/Right for the Split side-by-side row), A confirms. Disabled unless a
    // choice is active AND the history is interactive; returns -1 when idle. id -1 = the synthetic
    // forced-goodbye prompt (NPC taunted into combat, etc.) → goodbye.
    val choiceFocus = rememberListNavFocus(
        itemCount = choices.size,
        enabled = choices.isNotEmpty() && interactive,
        horizontal = choicesHorizontal,
        onConfirm = { i ->
            val c = choices[i]
            if (c.id == -1) CompanionActions.dialogueGoodbye()
            else CompanionActions.activateDialogueChoice(c.id)
        },
    )
    LazyColumn(state = listState, modifier = modifier) {
        itemsIndexed(history) { i, say ->
            if (i > 0) {
                Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.5f)))
                Spacer(Modifier.height(8.dp))
            }
            if (say.topic.isNotEmpty()) {
                Text(
                    say.topic.uppercase(),
                    color = BronzeLight, fontSize = 11.sp,
                    fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 1.sp,
                    modifier = Modifier.padding(bottom = 3.dp)
                )
            }
            if (say.isMessage) {
                // System message box (gold removed, etc.): highlighted BronzeLight, no
                // topic header, no tappable hyperlinks — matches the game's highlight.
                Text(
                    say.text,
                    color = BronzeLight, fontSize = 14.sp, fontFamily = MwBody, lineHeight = 22.4.sp,
                    modifier = Modifier.fillMaxWidth().padding(bottom = 8.dp)
                )
            } else {
                // Retroactive-highlight fix: union the response's captured hyperlinks with
                // the live topic list. When a newly-introduced topic arrives in `topics`
                // (after this line was already stored), the combined list changes and the
                // annotated string recomposes, lighting up the topic in-place.
                val links = remember(say.hyperlinks, topics) {
                    if (topics.isEmpty()) say.hyperlinks
                    else (say.hyperlinks + topics).distinct()
                }
                Text(
                    dialogueAnnotated(say.text, links, interactive),
                    color = Bone, fontSize = 14.sp, fontFamily = MwBody, lineHeight = 22.4.sp,
                    modifier = Modifier.fillMaxWidth().padding(bottom = 8.dp)
                )
            }
        }
        // Inline choice buttons, below the last response, while a question is active.
        if (choices.isNotEmpty()) {
            item {
                Spacer(Modifier.height(6.dp))
                Text(
                    "CHOOSE",
                    color = BoneDim, fontSize = 10.sp,
                    fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 2.sp,
                    modifier = Modifier.padding(bottom = 6.dp)
                )
                if (choicesHorizontal) {
                    // Split: side-by-side options in equal-width columns, navigated Left/Right.
                    Row(Modifier.fillMaxWidth()) {
                        choices.forEachIndexed { i, choice ->
                            if (i > 0) Spacer(Modifier.width(6.dp))
                            DialogueChoiceBox(
                                choice, focused = i == choiceFocus, interactive = interactive,
                                centered = true, modifier = Modifier.weight(1f)
                            )
                        }
                    }
                } else {
                    // Bottom/Top: vertical stack, navigated Up/Down.
                    choices.forEachIndexed { i, choice ->
                        if (i > 0) Spacer(Modifier.height(6.dp))
                        DialogueChoiceBox(
                            choice, focused = i == choiceFocus, interactive = interactive,
                            modifier = Modifier.fillMaxWidth()
                        )
                    }
                }
                Spacer(Modifier.height(10.dp))
            }
        }
    }
}

/** One inline dialogue-choice button, shared by [DialogueHistoryColumn]'s vertical stack and its
 *  Split side-by-side row. [focused] draws the controller-focus highlight (brighter fill + thicker
 *  BronzeLight border + BoneBright text — same as the old popup); taps are inert unless
 *  [interactive]. [centered] centres the label (for the equal-width side-by-side layout). id -1 =
 *  the synthetic forced-goodbye prompt (NPC taunted into combat, etc.) → goodbye, not an answer. */
@Composable
private fun DialogueChoiceBox(
    choice: DialogueChoice,
    focused: Boolean,
    interactive: Boolean,
    modifier: Modifier = Modifier,
    centered: Boolean = false
) {
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(2.dp))
            .background(BronzeLight.copy(alpha = if (focused) 0.22f else 0.06f))
            .border(
                if (focused) 2.dp else 1.dp,
                if (focused) BronzeLight else BronzeDark,
                RoundedCornerShape(2.dp)
            )
            .clickable {
                if (interactive) {
                    if (choice.id == -1) CompanionActions.dialogueGoodbye()
                    else CompanionActions.activateDialogueChoice(choice.id)
                }
            }
            .padding(horizontal = 12.dp, vertical = 8.dp),
        contentAlignment = if (centered) Alignment.Center else Alignment.CenterStart
    ) {
        Text(
            choice.text,
            color = if (focused) BoneBright else BronzeLight,
            fontSize = 14.sp, fontFamily = MwBody,
            textAlign = if (centered) TextAlign.Center else null
        )
    }
}

/**
 * Builds the response text as an AnnotatedString with each topic-hyperlink phrase
 * rendered BronzeLight and tappable (→ selectDialogueTopic). Case-insensitive,
 * longest-match-wins at any position so "Imperial cult" beats "Imperial". When
 * [interactive] is false (e.g. the history column is dimmed during persuasion) the
 * phrases stay highlighted BronzeLight but are NOT tappable.
 */
@Composable
private fun dialogueAnnotated(text: String, links: List<String>, interactive: Boolean = true): AnnotatedString = remember(text, links, interactive) {
    buildAnnotatedString {
        if (links.isEmpty()) {
            append(text)
            return@buildAnnotatedString
        }
        val lower = text.lowercase()
        val lowerLinks = links.map { it.lowercase() }
        var i = 0
        while (i < text.length) {
            var bestStart = -1
            var bestLen = 0
            for (w in lowerLinks) {
                if (w.isEmpty()) continue
                val idx = lower.indexOf(w, i)
                if (idx >= 0 && (bestStart == -1 || idx < bestStart || (idx == bestStart && w.length > bestLen))) {
                    bestStart = idx
                    bestLen = w.length
                }
            }
            if (bestStart == -1) {
                append(text.substring(i))
                break
            }
            if (bestStart > i) append(text.substring(i, bestStart))
            val phrase = text.substring(bestStart, bestStart + bestLen)  // preserve original case
            if (interactive) {
                withLink(
                    LinkAnnotation.Clickable(
                        tag = "topic",
                        styles = TextLinkStyles(style = SpanStyle(color = BronzeLight))
                    ) { CompanionActions.selectDialogueTopic(phrase) }
                ) {
                    append(phrase)
                }
            } else {
                // Dimmed/inert (persuasion active): keep the highlight, drop the link.
                withStyle(SpanStyle(color = BronzeLight)) { append(phrase) }
            }
            i = bestStart + bestLen
        }
    }
}

/**
 * Characters a journal topic link may start after. Taken verbatim from the engine's
 * `KeywordSearch::highlightKeywords`, which only begins a match at the text start or after one of
 * these — that word-start anchoring is what stops a topic like "ash" lighting up inside "cash".
 */
private val TOPIC_WORD_SEPARATORS = charArrayOf('\n', '\r', ' ', '\t', '\'', '"', '(', '[')

/**
 * Journal text with known dialogue topics turned into tappable links, mirroring vanilla's journal.
 *
 * The engine builds these by seeding a `KeywordSearch` with `Journal::getTopics()` and running
 * `parseHyperText` over each entry. We already have exactly that topic set on this side — it is
 * what `COMPANION_TOPICS_*` exports — so the matching is done here and no engine change is needed.
 *
 * Rules follow `KeywordSearch::highlightKeywords`: case-insensitive, anchored to a word start (see
 * [TOPIC_WORD_SEPARATORS]), longest topic wins where several could match at the same position. The
 * engine resolves overlaps globally by length; this scans left-to-right taking the longest match at
 * each position, which gives the same result for non-nested topics and is far simpler.
 *
 * Two deliberate divergences from the engine, both because vanilla content does not exercise them:
 *  - Explicit `@Topic#` markup is NOT handled. `parseHyperText` supports it, but a scan of
 *    Morrowind.esm found no real instances (only binary noise), so it would be dead code here.
 *    Localised or modded content CAN use it, and would show the raw `@`/`#` — worth revisiting if
 *    this ever ships beyond English vanilla.
 *  - Topic keywords are the display names. The engine passes them through
 *    `Translation::Storage::topicKeyword`, which is identity for English.
 *
 * Note this is STRICTER than the conversation's [dialogueAnnotated], which matches anywhere in the
 * text including mid-word. That looseness is long-shipped there and left alone; the journal is much
 * denser prose, so a false link inside a longer word would be far more visible.
 */
@Composable
private fun journalAnnotated(
    text: String,
    topics: List<String>,
    onTopic: (String) -> Unit
): AnnotatedString {
    // Read at click time rather than captured, so a link tapped later still calls the current
    // callback rather than one closed over on the composition that built the string.
    val handler = rememberUpdatedState(onTopic)
    val index = rememberTopicIndex(topics)
    return remember(text, index) { buildJournalAnnotated(text, index) { handler.value } }
}

/**
 * Topic names bucketed by lowercase first character, longest-first within each bucket.
 *
 * Hoisted out of [buildJournalAnnotated] because the paginated journal builds a string for EVERY
 * entry in one pass — rebuilding this index a thousand times would dominate that pass. With a few
 * hundred known topics, bucketing is the difference between a trivial scan and a visibly slow one.
 */
private typealias TopicIndex = Map<Char, List<String>>

private fun buildTopicIndex(topics: List<String>): TopicIndex {
    val byFirstChar = HashMap<Char, MutableList<String>>()
    for (topic in topics) {
        if (topic.isNotEmpty()) {
            byFirstChar.getOrPut(topic[0].lowercaseChar()) { mutableListOf() }.add(topic)
        }
    }
    // Longest first, so the first hit at a position is also the longest one.
    byFirstChar.values.forEach { it.sortByDescending(String::length) }
    return byFirstChar
}

@Composable
private fun rememberTopicIndex(topics: List<String>): TopicIndex =
    remember(topics) { buildTopicIndex(topics) }

/**
 * The scan itself, as a PLAIN function — see [journalAnnotated] for the matching rules.
 *
 * Deliberately not `@Composable`: the paginated journal has to build these strings outside
 * composition (it measures them to decide where pages break), and a single implementation is the
 * only way the two paths can be guaranteed to link identically.
 *
 * [handlerProvider] is called at CLICK time, never captured, so a string built during an earlier
 * composition — or cached across one, as [JournalPaginationCache] does — still routes to whatever
 * handler is live now rather than to a dead composable's callback.
 */
private fun buildJournalAnnotated(
    text: String,
    index: TopicIndex,
    handlerProvider: () -> ((String) -> Unit)?
): AnnotatedString = buildAnnotatedString {
    if (index.isEmpty()) {
        append(text)
        return@buildAnnotatedString
    }
    var i = 0
    var plainFrom = 0
    while (i < text.length) {
        if (i != 0 && text[i - 1] !in TOPIC_WORD_SEPARATORS) {
            i++
            continue
        }
        val match = index[text[i].lowercaseChar()]
            ?.firstOrNull { text.regionMatches(i, it, 0, it.length, ignoreCase = true) }
        if (match == null) {
            i++
            continue
        }
        if (i > plainFrom) append(text.substring(plainFrom, i))
        // Show the text as written (case and all); navigate by the topic's own name.
        withLink(
            LinkAnnotation.Clickable(
                tag = "journalTopic",
                styles = TextLinkStyles(style = SpanStyle(color = BronzeLight))
            ) { handlerProvider()?.invoke(match) }
        ) {
            append(text.substring(i, i + match.length))
        }
        i += match.length
        plainFrom = i
    }
    if (plainFrom < text.length) append(text.substring(plainFrom))
}

/* ---- Item / spell info popup (small, position-aware) ---- */

private enum class PopupEdge { LEFT, RIGHT, TOP, BOTTOM }

/**
 * Global holder for the item info popup (mirrors the DropdownState pattern). Set from a long-press
 * "Info" tap or an R3 (NavEvent.Info) press on the focused item; consumed by the popup host at the
 * CompanionScreen root. `name`/`enchant` come from the LOCAL item (instant); the detailed base
 * rows arrive asynchronously via COMPANION_INFO (GameStateRepository.itemInfo). `anchor` is the
 * triggering row's bounds in root coords, refreshed by that row's onGloballyPositioned.
 */
/** What kind of record the info popup is pointed at, i.e. which `CMP:info <kind>:<id>` request
 *  resolves it. Replaced an `isSpell: Boolean` when EFFECT arrived (Aug 21 2026) — a second boolean
 *  would have made two mutually exclusive flags that can both be set. */
enum class InfoKind { ITEM, SPELL, EFFECT }

object ItemInfoPopupState {
    var targetId by mutableStateOf<String?>(null)
    var name by mutableStateOf("")
    var enchant by mutableStateOf<ItemEnchant?>(null)
    var anchor by mutableStateOf<Rect?>(null)
    // true = the trigger came from a SPLIT top-screen grid cell, so the popup must render in the
    // top overlay (LootingTopOverlay/BarterTopOverlay), not the bottom CompanionScreen root.
    var onTopScreen by mutableStateOf(false)
    // true = the popup was opened via R3 / D-pad (it tracks the controller focus cursor), so the
    // reactive FollowFocusedInfoPopup may re-point it when focus moves for a non-nav reason (item
    // taken/sold, list re-sort). A touch long-press opens it PINNED to a specific item (false), and
    // the reactive path leaves it alone. See FollowFocusedInfoPopup + Bug 1.
    var focusLinked by mutableStateOf(false)
    val isOpen get() = targetId != null

    // Most recent bounds reported by EVERY composed row, not just the current target's. A plain
    // HashMap on purpose (never snapshot state): it is written from the layout pass for every
    // visible row, so a snapshot map would invalidate the popup host on every frame. Read only by
    // follow(), to seed the anchor when the retarget arrives AFTER that layout pass — see the
    // ordering note there. Capped so it can't grow across a long session.
    private val anchorCache = HashMap<String, Rect>()

    fun open(id: String, name: String, ench: ItemEnchant?, kind: InfoKind = InfoKind.ITEM,
             onTop: Boolean = false, focusLinked: Boolean = false) {
        if (id.isBlank()) return
        targetId = id
        this.name = name
        enchant = ench
        anchor = null
        onTopScreen = onTop
        this.focusLinked = focusLinked
        GameStateRepository.dismissItemInfo()      // clear stale rows so the previous item's don't flash
        when (kind) {
            InfoKind.SPELL -> CompanionActions.requestSpellInfo(id)
            InfoKind.EFFECT -> CompanionActions.requestEffectInfo(id)
            InfoKind.ITEM -> CompanionActions.requestItemInfo(id)
        }
    }

    /** R3 / D-pad Info on the SAME item toggles the popup; a different item re-targets. Always
     *  focus-linked — the only callers are the nav collectors (the focus cursor drives it). */
    fun toggle(id: String, name: String, ench: ItemEnchant?, kind: InfoKind = InfoKind.ITEM,
               onTop: Boolean = false) {
        if (targetId == id) close() else open(id, name, ench, kind, onTop, focusLinked = true)
    }

    /** Focus moved while open → follow to the newly focused item/spell (don't dismiss). Called BOTH
     *  synchronously from the nav collectors (D-pad moves) AND reactively (FollowFocusedInfoPopup)
     *  when focus changes for a non-nav reason; either way the popup stays focus-linked. */
    fun follow(id: String, name: String, ench: ItemEnchant?, kind: InfoKind = InfoKind.ITEM,
               onTop: Boolean = false) {
        if (!isOpen || id == targetId) return
        open(id, name, ench, kind = kind, onTop = onTop, focusLinked = true)
        // ORDERING (Bug: info popup went blank after taking the inspected item). open() resets the
        // anchor and waits for the new row's onGloballyPositioned. That is fine for the D-pad path
        // (the nav collector retargets BEFORE the frame's layout pass, so the report lands) and for
        // a fresh open (the host's own arrival re-places the root, re-dispatching every row). But
        // the REACTIVE path — FollowFocusedInfoPopup, a LaunchedEffect, which runs AFTER the layout
        // pass triggered by the take — retargets once every row has already reported against the
        // OLD id. Nothing then invalidates those rows' layout, so no further report ever arrives
        // and the card stays invisible until the next D-pad press. The cache holds that same pass's
        // report for the new item, so seed from it (null = not seen → wait, exactly as before).
        anchorCache[id]?.let { anchor = it }
    }

    fun close() {
        targetId = null
        name = ""
        enchant = null
        anchor = null
        onTopScreen = false
        focusLinked = false
        anchorCache.clear()
        GameStateRepository.dismissItemInfo()
    }

    /** A row reports its current bounds. The active target's anchor is published to the popup
     *  (survives scroll); every row's is also cached for [follow] (see the ordering note there). */
    fun reportAnchor(id: String, r: Rect) {
        if (anchorCache.size >= ANCHOR_CACHE_MAX) anchorCache.clear()
        anchorCache[id] = r
        if (targetId == id) anchor = r
    }
}

/** Cap on [ItemInfoPopupState]'s per-id anchor cache (cleared wholesale on overflow; it refills
 *  from the next layout pass). Comfortably larger than any single screen's row count. */
private const val ANCHOR_CACHE_MAX = 256

/** The item currently under the controller focus cursor, projected to what the info popup needs
 *  (record id for CMP:info + the local name/enchant). Built at the FollowFocusedInfoPopup call site
 *  from the overlay's live (post-mutation) list, so a change here == focus effectively moved. */
private class InfoTarget(val id: String, val name: String, val enchant: ItemEnchant?)

/**
 * Bug-1 fix — keep the item info popup pointed at the CURRENTLY focused item even when focus
 * changes for a NON-nav reason: an item vanishing after a take/sell (the list shrinks and the fixed
 * focus index now points at a different item) or a re-sort moving it (barter's selected-first
 * float). The nav collectors already follow on D-pad moves — synchronously, re-reporting the anchor
 * before layout — so this reactive path is the SECOND mechanism, covering every other cause; both
 * share ItemInfoPopupState.follow(). One shared helper for looting + barter (classic + shelf).
 *
 * Acts only on a FOCUS-LINKED popup (opened via R3 / D-pad, i.e. tracking the focus cursor). A popup
 * opened by a touch long-press is pinned to its specific item and left untouched. When [focused]
 * resolves to null (the focused side emptied), the popup CLOSES rather than showing stale content.
 * Keyed on the focused item's record id, so it re-runs whenever the resolved focus target changes.
 */
@Composable
private fun FollowFocusedInfoPopup(focused: InfoTarget?, onTop: Boolean) {
    LaunchedEffect(focused?.id) {
        if (!ItemInfoPopupState.isOpen || !ItemInfoPopupState.focusLinked) return@LaunchedEffect
        val f = focused
        if (f == null) ItemInfoPopupState.close()
        else ItemInfoPopupState.follow(f.id, f.name, f.enchant, onTop = onTop)
    }
}

/**
 * The toast SHELL — the card the crime alert has always drawn, extracted so the UI hints can reuse
 * it verbatim (Aug 21 2026) instead of a second look-alike. Position and z-order are part of what is
 * shared: vertically centred with the HUD's top box, above every overlay.
 *
 * [icon] is optional and the hints pass none. Not decoration: "⚠" is one of the 16 glyphs MysticCards
 * has no coverage for (see the Game Font notes), so it rides on an Android font fallback. That is a
 * risk already taken for the crime alert, where the warning mark earns it; a neutral hint has nothing
 * to gain from repeating it.
 */
@Composable
private fun HudToastCard(
    text: String,
    accent: Color,
    icon: String? = null,
    // Defaults reproduce the crime alert exactly: bone text in a 1dp accent border. The hints
    // override both to shout — see HintToast.
    textColor: Color = BoneBright,
    borderWidth: Dp = 1.dp,
    onDismiss: () -> Unit
) {
    Box(Modifier.fillMaxSize().zIndex(30f), contentAlignment = Alignment.TopCenter) {
        Box(
            Modifier.fillMaxWidth().padding(top = 12.dp).height(TOP_BOX_HEIGHT),
            contentAlignment = Alignment.Center
        ) {
            Row(
                Modifier
                    .fillMaxWidth(0.9f)
                    .clip(RoundedCornerShape(4.dp))
                    .background(Color(0xF2140D08))
                    .border(borderWidth, accent, RoundedCornerShape(4.dp))
                    .clickable { onDismiss() }
                    .padding(horizontal = 14.dp, vertical = 10.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                if (icon != null) {
                    Text(icon, color = accent, fontSize = 16.sp, modifier = Modifier.padding(end = 8.dp))
                }
                Text(
                    text,
                    color = textColor, fontSize = 13.sp, fontFamily = MwBody, fontWeight = FontWeight.Bold
                )
            }
        }
    }
}

/**
 * A transient UI HINT, drawn in the same card as the crime alert (see [HudToastCard]) but raised
 * locally rather than by a native signal — so it is NOT gated on any Game UI element, and a hint
 * shows whether or not Crime alerts are routed to the DS screen.
 *
 * The seq is what makes a repeat re-fire: tapping the same empty slot twice must show the hint twice,
 * and a bare String state would dedupe the second one away. Exactly why GameStateRepository stamps
 * crimeMessage with a sequence number.
 */
private object HintToastState {
    var message by mutableStateOf<Pair<String, Long>?>(null)
        private set
    private var seq = 0L
    fun show(text: String) { message = text to seq++ }
    fun clear() { message = null }
}

@Composable
private fun HintToast() {
    val current = HintToastState.message ?: return
    LaunchedEffect(current.second) {
        delay(HINT_TOAST_MS)
        HintToastState.clear()
    }
    // Red text AND a 2dp red border. The bronze-on-bone version read as ordinary chrome and was
    // being missed — which is fatal for a hint whose whole job is to be noticed in the moment the
    // tab changes under the player. 2dp is the app's existing "this one matters" border weight
    // (the D-pad focus rings, the selected chips), so it shouts without inventing a new language.
    HudToastCard(
        text = current.first,
        accent = HintToastRed,
        textColor = HintToastRed,
        borderWidth = 2.dp
    ) { HintToastState.clear() }
}

/** Accent for the UI hints. The same red the crime alert borders with and the reset warning uses
 *  (#C75C5C) — named separately rather than borrowing one of those constants because this is a
 *  third, unrelated caller, and a future retune of either should not silently drag the hints along.
 *  Note this deliberately gives a HINT alert colouring; that is the point — it has to be seen. */
private val HintToastRed = Color(0xFFC75C5C)

/** Hint dwell time. Longer than the crime alert's 4.2s: a hint is instructional rather than a
 *  notification, so it has to survive being read after the tab it just switched to has drawn. */
private const val HINT_TOAST_MS = 5000L

/**
 * Top-of-stack "crime reported" toast, driven by GameStateRepository.crimeMessage (the native
 * COMPANION_CRIME_MSG signal). Rendered above every other overlay (zIndex 30f) so it stays visible
 * during looting/barter, where the native transient message is hidden behind the panel windows.
 * Auto-dismisses after a few seconds (re-armed per message via the seq key); tap to dismiss early.
 */
@Composable
private fun CrimeToast() {
    // Gated by the "Crime alerts" Game UI element (DS = this toast; Vanilla = native message). The
    // native side only emits COMPANION_CRIME_MSG when DS, so this is belt-and-suspenders (and hides an
    // in-flight toast if the mode flips to Vanilla).
    val crimeDs by UiPreferences.gameUiModeFlow("game_ui_crime").collectAsState()
    if (crimeDs != GameUiMode.DS) return
    val msg by GameStateRepository.crimeMessage.collectAsState()
    val current = msg ?: return
    LaunchedEffect(current.second) {
        delay(4200)
        GameStateRepository.clearCrimeMessage()
    }
    // Look, position and z-order unchanged — they now live in HudToastCard, which the UI hints share.
    HudToastCard(text = current.first, accent = Color(0xFFC75C5C), icon = "⚠") {
        GameStateRepository.clearCrimeMessage()
    }
}

/**
 * Full scrim (tap-to-dismiss) + the floating card. Hosted at the bottom CompanionScreen root for
 * bottom contexts, and inside LootingTopOverlay/BarterTopOverlay for SPLIT top-grid triggers, so the
 * popup renders on whichever screen the triggering item lives (and anchors in that screen's coords).
 */
@Composable
private fun ItemInfoPopupHost() {
    // Own fillMaxSize box with TopStart alignment so the card's absolute .offset positioning is
    // independent of the CALLER's contentAlignment. The top overlays' root uses BottomCenter, which
    // would otherwise offset the card from a bottom-centre base and push it off-screen.
    Box(modifier = Modifier.fillMaxSize().zIndex(20f), contentAlignment = Alignment.TopStart) {
        // Scrim: tap outside dismisses. Shown immediately so interaction is blocked while we wait
        // for the anchor.
        Box(
            modifier = Modifier
                .fillMaxSize()
                .pointerInput(Unit) { detectTapGestures { ItemInfoPopupState.close() } }
        )
        // Only render the card once the triggering row's onGloballyPositioned has reported its
        // anchor. On open, anchor is reset to null; rendering with a null anchor would flash the
        // card centred for a frame before it jumps to the item — so wait for the real anchor.
        ItemInfoPopupState.anchor?.let { a ->
            ItemInfoFloatingPopup(anchor = a, enchant = ItemInfoPopupState.enchant)
        }
    }
}

/**
 * Positions the info card next to [anchor] and flips to stay on-screen: to the item's right when it
 * fits, else its left; vertically aligned to the row top, clamped to the screen. The side the popup
 * lands on is highlighted with a bright border edge (in lieu of a drawn arrow).
 */
@Composable
private fun ItemInfoFloatingPopup(anchor: Rect?, enchant: ItemEnchant?) {
    val info by GameStateRepository.itemInfo.collectAsState()
    val density = LocalDensity.current
    val cfg = LocalConfiguration.current
    val screenW = with(density) { cfg.screenWidthDp.dp.toPx() }
    val screenH = with(density) { cfg.screenHeightDp.dp.toPx() }
    val marginPx = with(density) { 8.dp.toPx() }
    val widthPx = with(density) { INFO_POPUP_WIDTH.dp.toPx() }
    var popupSize by remember { mutableStateOf(IntSize.Zero) }
    val hPx = popupSize.height.toFloat()

    val x: Float
    val y: Float
    val edge: PopupEdge
    if (anchor == null) {
        x = ((screenW - widthPx) / 2f).coerceAtLeast(marginPx)
        y = ((screenH - hPx) / 2f).coerceAtLeast(marginPx)
        edge = PopupEdge.TOP
    } else {
        val placeRight = anchor.right + widthPx + marginPx <= screenW
        edge = if (placeRight) PopupEdge.LEFT else PopupEdge.RIGHT
        val xRaw = if (placeRight) anchor.right + marginPx else anchor.left - widthPx - marginPx
        x = xRaw.coerceIn(marginPx, (screenW - widthPx - marginPx).coerceAtLeast(marginPx))
        y = anchor.top.coerceIn(marginPx, (screenH - hPx - marginPx).coerceAtLeast(marginPx))
    }

    Box(
        modifier = Modifier
            .zIndex(21f)
            .offset { IntOffset(x.roundToInt(), y.roundToInt()) }
            .width(INFO_POPUP_WIDTH.dp)
            .onSizeChanged { popupSize = it }
            // Swallow taps so tapping the card doesn't reach the dismiss scrim underneath.
            .pointerInput(Unit) { detectTapGestures {} }
    ) {
        ItemInfoPopupCard(info = info, enchant = enchant, edge = edge)
    }
}

private const val INFO_POPUP_WIDTH = 220

@Composable
private fun ItemInfoPopupCard(info: ItemInfo?, enchant: ItemEnchant?, edge: PopupEdge) {
    Box(
        Modifier
            .clip(RoundedCornerShape(3.dp))
            .background(StonePanel.copy(alpha = 0.97f))
            .border(2.dp, BronzeDark, RoundedCornerShape(3.dp))
            .wrapContentHeight()
    ) {
        // The Column drives the card height (wraps its content, scrolls if it exceeds the cap).
        Column(
            modifier = Modifier
                .padding(12.dp)
                .heightIn(max = 480.dp)
                .verticalScroll(rememberScrollState())
        ) {
            Text(
                ItemInfoPopupState.name.ifBlank { info?.name ?: "" },
                color = BronzeLight, fontSize = 14.sp, fontFamily = MwDisplay,
                fontWeight = FontWeight.Bold, maxLines = 2, overflow = TextOverflow.Ellipsis
            )
            Spacer(Modifier.height(6.dp))
            Box(Modifier.fillMaxWidth().height(1.dp).background(Bronze))
            Spacer(Modifier.height(6.dp))

            if (info == null) {
                Text("…", color = BoneDim, fontSize = 11.sp, fontFamily = MwData)
            } else {
                info.rows.forEach { (label, value) ->
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(vertical = 3.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(label, color = BoneDim, fontSize = 11.sp, fontFamily = MwBody)
                        Text(
                            value, color = Bone, fontSize = 11.sp, fontFamily = MwData,
                            modifier = Modifier.padding(start = 10.dp)
                        )
                    }
                }
                // Intrinsic potion/ingredient alchemy effects (COMPANION_INFO effects).
                if (info.effects.isNotEmpty()) {
                    InfoSectionHeader("EFFECTS")
                    info.effects.forEach { eff -> InfoEffectRow(eff.text, eff.harmful, null) }
                }
                // Free-text paragraph, magic effects only. Below the rows, which is where vanilla's
                // MagicEffectToolTip puts the description relative to its "School:" line. Wrapping
                // prose, so it gets MwBody and a line height rather than the rows' MwData.
                if (info.description.isNotBlank()) {
                    Spacer(Modifier.height(6.dp))
                    Text(
                        info.description,
                        color = Bone, fontSize = 11.sp, fontFamily = MwBody, lineHeight = 15.sp
                    )
                }
            }

            // Enchantment section (from the local item — renders instantly, with effect icons).
            if (enchant != null && enchant.effects.isNotEmpty()) {
                InfoSectionHeader("ENCHANTMENT")
                if (enchant.type.isNotBlank()) {
                    Text(enchant.type, color = BronzeLight, fontSize = 10.sp, fontFamily = MwBody)
                    Spacer(Modifier.height(2.dp))
                }
                enchant.effects.forEach { e ->
                    val parts = buildString {
                        if (e.mag.isNotBlank() && e.mag != "0") append(" ${e.mag} pts")
                        if (e.durationSecs > 0) append(" for ${e.durationSecs}s")
                        if (e.area > 0) append(" in ${e.area}ft")
                    }
                    InfoEffectRow(e.name + parts, e.harmful, e.icon)
                }
                // Charge bar — vanilla's "Charges" row, a labelled bar with the current/max pair.
                // Drawn only when the async COMPANION_INFO reply carried a charge, which the
                // exporter emits ONLY for Cast When Strikes / Cast When Used; vanilla likewise
                // draws no bar for Cast Once or Constant Effect. So there is no enchantment-type
                // test here — maxCharge > 0 IS the signal, the same convention the HUD meter uses.
                val maxCharge = info?.maxCharge ?: 0
                if (maxCharge > 0) {
                    val cur = info?.charge ?: 0
                    val ratio = (cur.toFloat() / maxCharge).coerceIn(0f, 1f)
                    Spacer(Modifier.height(6.dp))
                    Row(
                        Modifier.fillMaxWidth(),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text("Charge", color = BoneDim, fontSize = 11.sp, fontFamily = MwBody)
                        Box(
                            Modifier
                                .weight(1f)
                                .padding(horizontal = 8.dp)
                                .height(9.dp)
                                .clip(RoundedCornerShape(1.dp))
                                .background(Color(0xFF0E0B07))
                                .border(1.dp, BronzeDark, RoundedCornerShape(1.dp))
                        ) {
                            Box(
                                Modifier
                                    .fillMaxWidth(ratio)
                                    .fillMaxHeight()
                                    .background(if (ratio >= 0.5f) BronzeLight else Color(0xFFC75C5C))
                            )
                        }
                        Text(
                            "$cur/$maxCharge",
                            color = Bone, fontSize = 11.sp, fontFamily = MwData
                        )
                    }
                }
            }
        }

        // Bright edge strip on the side facing the source item (border-highlight instead of an
        // arrow). matchParentSize() makes this overlay MATCH the Column-driven card height rather
        // than inflate it — a fillMaxHeight() direct child would have stretched the card to the
        // incoming (near-screen) height constraint, leaving empty space below the content.
        Box(Modifier.matchParentSize()) {
            val strip = when (edge) {
                PopupEdge.LEFT -> Modifier.align(Alignment.CenterStart).fillMaxHeight().width(3.dp)
                PopupEdge.RIGHT -> Modifier.align(Alignment.CenterEnd).fillMaxHeight().width(3.dp)
                PopupEdge.TOP -> Modifier.align(Alignment.TopCenter).fillMaxWidth().height(3.dp)
                PopupEdge.BOTTOM -> Modifier.align(Alignment.BottomCenter).fillMaxWidth().height(3.dp)
            }
            Box(strip.background(BronzeLight))
        }
    }
}

@Composable
private fun InfoSectionHeader(text: String) {
    Spacer(Modifier.height(8.dp))
    Text(
        text, color = BronzeLight, fontSize = 10.sp, fontFamily = MwDisplay,
        fontWeight = FontWeight.Bold, letterSpacing = 0.8.sp
    )
    Spacer(Modifier.height(3.dp))
}

@Composable
private fun InfoEffectRow(text: String, harmful: Boolean, iconPath: String?) {
    Row(
        modifier = Modifier.fillMaxWidth().padding(vertical = 3.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        if (!iconPath.isNullOrBlank()) {
            val bmp = rememberItemIcon(iconPath)
            Box(
                Modifier.size(18.dp).clip(RoundedCornerShape(2.dp)).background(SlotBg)
            ) { if (bmp != null) Image(bmp, null, modifier = Modifier.fillMaxSize()) }
            Spacer(Modifier.width(6.dp))
        } else {
            Box(Modifier.size(8.dp).clip(CircleShape)
                .background(if (harmful) Color(0xFFC75C5C) else Color(0xFF7FBF7F)))
            Spacer(Modifier.width(8.dp))
        }
        Text(text, color = Bone, fontSize = 11.sp, fontFamily = MwBody)
    }
}

/* ---- Looting / pickpocketing overlay ---- */

/** Current controller focus in the looting overlay: which [side] (0 = player/left,
 *  1 = container/right) and which [index] into that side's sorted list. */
private data class LootFocus(val side: Int, val index: Int)

/** The per-side visible looting list: filter by the selected category tab (an INV_CATEGORIES
 *  label, null = All), then sort. Pass [isWorn] on the PLAYER side to float worn (equipped) items to
 *  the top ahead of everything else, with the existing [itemCategoryRank] + name order as the
 *  secondary sort applied WITHIN the worn group and WITHIN the rest; the default `{ false }` (container
 *  side / any other caller) leaves the order exactly as category+name — identical to before. Shared by
 *  the SPLIT grid columns' display and the controller focus index so the D-pad index maps 1:1 to a
 *  visible cell. Mirrors [barterVisible]. */
private fun lootVisible(
    items: List<InventoryItem>,
    categoryLabel: String?,
    // DEFAULT keeps looting's own original order (worn-first, then category + name). Weight/Value
    // are a pure ordering with no worn tier — same rule as the BOTTOM lists and the inventory tab.
    sortMode: InvSort = InvSort.DEFAULT,
    sortDescending: Boolean = true,
    isWorn: (InventoryItem) -> Boolean = { false }
): List<InventoryItem> {
    val group = INV_CATEGORIES.find { it.label == categoryLabel }
    val filtered = items.filter { group == null || it.category in group.cats }
    if (sortMode != InvSort.DEFAULT) {
        return filtered.sortedWith(
            invSortComparator(sortMode, sortDescending, { it.displayName() }, { it.weight }, { it.value })
        )
    }
    return filtered.sortedWith(
        compareByDescending<InventoryItem> { isWorn(it) }
            .then(compareBy({ itemCategoryRank(it.category) }, { it.displayName().lowercase() }))
    )
}

/** Cycle a looting column's category filter by [dir] (-1 = previous, +1 = next) through
 *  [All] + the INV_CATEGORIES actually present in [items] (in INV_CATEGORIES order), wrapping.
 *  Returns the new selection (null = All). Matches the visible CategoryTab set, so the L1/R1
 *  shoulder buttons mirror tapping the tabs. Mirrors [cycleBarterCat]. */
private fun cycleLootCat(items: List<InventoryItem>, current: String?, dir: Int): String? {
    val present = items.map { it.category }.toSet()
    val avail: List<String?> =
        listOf<String?>(null) + INV_CATEGORIES.filter { grp -> grp.cats.any { it in present } }.map { it.label }
    if (avail.size <= 1) return current
    val cur = avail.indexOf(current).coerceAtLeast(0)
    val next = ((cur + dir) % avail.size + avail.size) % avail.size
    return avail[next]
}

/**
 * Controller focus + navigation for the looting overlay (Phase 3), shared by the BOTTOM list
 * layout ([rows] = 1) and the SPLIT grid layout ([rows] = 4). Owns focus (side + index into that
 * side's pre-sorted list) and consumes NavEvents while the overlay is up:
 *  - D-pad moves focus. In grid mode (rows = 4) the list is column-major so Up/Down step ±1 within
 *    a grid column and Left/Right jump ±rows to the adjacent column (clamped). In list mode
 *    (rows = 1) Up/Down step ±1 and Left/Right switch side (the two lists sit side by side).
 *  - L2 / R2 switch to the player / container side (in both layouts).
 *  - A activates the focused item via [requestQty] → [onPut]/[onTake] (stacks > 1 prompt first).
 *  - X = [onTakeAll]; Y = [onDispose] (corpse only, [isCorpse]).
 *  - L1 / R1 cycle the focused column's category filter via [onCycleCategory] (SPLIT grids only).
 * Focus starts on the container side when it has items (the point of looting), else the player
 * side, and is clamped as items move between sides. Returns the live focus so the columns can
 * highlight the focused cell. Only ONE looting layout is composed at a time, so this collector is
 * unambiguous. B (Close) is handled by the existing patch, not here.
 */
@Composable
private fun rememberLootNavFocus(
    playerSorted: List<InventoryItem>,
    containerSorted: List<InventoryItem>,
    rows: Int,
    isCorpse: Boolean,
    // Living NPC (pickpocket): a TAKE prompt opens at 1 rather than the whole stack — see
    // lootQtyInitial. Puts and corpse/chest takes still open on max.
    isPickpocket: Boolean,
    requestQty: (String, Int, String, Int, (Int) -> Unit) -> Unit,
    onPut: (InventoryItem, Int) -> Unit,
    onTake: (InventoryItem, Int) -> Unit,
    onTakeAll: () -> Unit,
    onDispose: () -> Unit,
    // Cycle the focused column's category filter (L1 = -1 prev, R1 = +1 next). No-op in the
    // BOTTOM list layout (no category tabs there); wired to the per-side state in the SPLIT grids.
    onCycleCategory: (side: Int, dir: Int) -> Unit = { _, _ -> },
    // Cycle the sort mode/direction (L3). Takes the focused side because SPLIT holds one
    // InvSortState PER COLUMN; BOTTOM shares one across both sides and ignores the argument.
    onCycleSort: (side: Int) -> Unit = { },
): LootFocus {
    var side by remember { mutableStateOf(if (containerSorted.isNotEmpty()) 1 else 0) }
    var index by remember { mutableStateOf(0) }

    // Keep focus in range as the two lists change size (items taken/put) or the side switches.
    LaunchedEffect(playerSorted.size, containerSorted.size, side) {
        val n = if (side == 0) playerSorted.size else containerSorted.size
        index = index.coerceIn(0, (n - 1).coerceAtLeast(0))
    }

    val snapshot = rememberUpdatedState(Triple(playerSorted, containerSorted, isCorpse))
    // Category-cycle callback reads the parent's live per-side category state, so keep it fresh.
    val cycleState = rememberUpdatedState(onCycleCategory)
    val sortState = rememberUpdatedState(onCycleSort)
    // Session-scoped, but this collector outlives a session swap (LaunchedEffect(Unit)).
    val pickpocketState = rememberUpdatedState(isPickpocket)
    LaunchedEffect(Unit) {
        var lastSeq = GameStateRepository.navEvent.value?.seq ?: -1L
        GameStateRepository.navEvent.collect { ev ->
            if (ev == null || ev.seq <= lastSeq) return@collect
            lastSeq = ev.seq
            if (ModalNav.open) return@collect // the quantity selector owns nav while up
            val (pSorted, cSorted, corpse) = snapshot.value
            fun sizeOf(s: Int) = if (s == 0) pSorted.size else cSorted.size
            fun clampTo(s: Int) { index = index.coerceIn(0, (sizeOf(s) - 1).coerceAtLeast(0)) }
            val size = sizeOf(side)
            when (ev) {
                is NavEvent.Down ->
                    if (rows <= 1) { if (index + 1 < size) index++ }
                    else if (index % rows < rows - 1 && index + 1 < size) index++
                is NavEvent.Up ->
                    if (rows <= 1) { if (index > 0) index-- }
                    else if (index % rows > 0) index--
                is NavEvent.Right ->
                    if (rows <= 1) { side = 1; clampTo(1) }
                    else if (index + rows < size) index += rows
                is NavEvent.Left ->
                    if (rows <= 1) { side = 0; clampTo(0) }
                    else if (index - rows >= 0) index -= rows
                is NavEvent.L2 -> { side = 0; clampTo(0) }
                is NavEvent.R2 -> { side = 1; clampTo(1) }
                is NavEvent.Confirm -> {
                    val item = (if (side == 0) pSorted else cSorted).getOrNull(index)
                    if (item != null) {
                        val isPlayer = side == 0
                        requestQty(
                            item.displayName(),
                            item.count,
                            if (isPlayer) "Put" else "Take",
                            lootQtyInitial(item.count, isTake = !isPlayer, isPickpocket = pickpocketState.value)
                        ) { n ->
                            if (isPlayer) onPut(item, n) else onTake(item, n)
                        }
                    }
                }
                is NavEvent.Action1 -> onTakeAll()
                is NavEvent.Action2 -> if (corpse) onDispose()
                // Shoulder buttons cycle the focused side's category filter; reset focus to the
                // first item of the new (filtered) list. No-op in BOTTOM mode (no tabs there).
                is NavEvent.L1 -> { cycleState.value(side, -1); index = 0 }
                is NavEvent.R1 -> { cycleState.value(side, 1); index = 0 }
                is NavEvent.Info -> (if (side == 0) pSorted else cSorted).getOrNull(index)?.let {
                    ItemInfoPopupState.toggle(it.id, it.displayName(), it.enchant, onTop = rows > 1)
                }
                // L3 re-orders the focused column. Focus is an index into that column's sorted
                // list, so it must go back to the top — keeping it would leave the highlight on a
                // different item than the one the player was looking at.
                is NavEvent.Sort -> { sortState.value(side); index = 0 }
                else -> Unit // Slider* / R2 handled above; nothing else used here
            }
            // While the info popup is open, D-pad focus moves follow to the newly focused item.
            if (ItemInfoPopupState.isOpen) {
                (if (side == 0) pSorted else cSorted).getOrNull(index)?.let {
                    ItemInfoPopupState.follow(it.id, it.displayName(), it.enchant, onTop = rows > 1)
                }
            }
        }
    }
    // Clamp the REPORTED focus in composition, not just in the LaunchedEffect above: that effect
    // runs after the composition that reads this, so taking the LAST item of a side would otherwise
    // resolve focus to a non-existent index for one pass — which reads as "nothing is focused" and
    // makes FollowFocusedInfoPopup close a focus-linked info popup that should just have moved. The
    // effect still clamps the underlying state for the next nav press.
    val n = (if (side == 0) playerSorted.size else containerSorted.size)
    return LootFocus(side, index.coerceIn(0, (n - 1).coerceAtLeast(0)))
}

// ============================ SHELF LAYOUT (shared, Phases 1-3) ============================
// An alternate dual-panel layout for the two-panel item screens (looting/pickpocket now;
// barter in Phase 2). Items are grouped into labelled horizontal "shelves" by category
// instead of a tab-filtered grid, stacked vertically inside each panel, with a reserved
// scroll gutter on the inner edge and a collapsible "Equipped" section pinned to the bottom
// of the PLAYER panel only. A common [ShelfItem] view-model lets both InventoryItem (loot)
// and BarterItem (barter) project in at the call site — the underlying data models and each
// overlay's plumbing (session, optimistic updates) stay untouched. Gated per overlay by
// UiPreferences.inventoryLayoutFlow() (the "Inventory Layout" options switch; default CLASSIC).

/** Common per-item view-model both looting (InventoryItem) and barter (BarterItem) project into
 *  so one ShelfColumn/ShelfCell renders every context. Carries display fields (icon/name/worn/
 *  count) + the info-popup fields (id/name/enchant) + the tap action. Barter-only extras
 *  ([price]/[selected]/[selectedCount]) default to inert, so looting cells render exactly as before. */
private data class ShelfItem(
    val id: String,
    val name: String,
    val category: String,
    val icon: String,
    val worn: Boolean,
    val enchant: ItemEnchant?,
    val count: Int,
    val onTap: () -> Unit,
    // Barter: per-unit price (null = no price line, e.g. looting) and offer-selection state.
    val price: Int? = null,
    val selected: Boolean = false,
    val selectedCount: Int = 0,
) {
    val enchanted: Boolean get() = enchant != null
}

/** One labelled shelf: a category bucket's display name + its (alphabetised) items. */
private data class ShelfRowData(val label: String, val items: List<ShelfItem>)

/** A focusable nav row: a category shelf / the equipped strip (both carry [items]) OR the
 *  equipped-section header (no items — [isEquippedHeader], Confirm toggles expand). */
private data class ShelfNavRow(val items: List<ShelfItem>, val isEquippedHeader: Boolean = false)

/** Current shelf-mode controller focus: which [side] (0 = player, 1 = other), which [row]
 *  (index into that side's nav rows), and which [item] within that row. */
private data class ShelfFocus(val side: Int, val row: Int, val item: Int)

/** Map any item category string — fine (looting slot cats) OR coarse (barter cats) — to a
 *  (rank, display-label) shelf bucket. Mirrors the INV_CATEGORIES buckets + itemCategoryRank
 *  order so shelves read like the Classic tabs. */
private fun shelfBucket(category: String): Pair<Int, String> = when (category) {
    "weapon", "ammo" -> 0 to "Weapons"
    "armor", "helmet", "cuirass", "left_pauldron", "right_pauldron", "greaves", "boots",
        "left_gauntlet", "right_gauntlet", "shield" -> 1 to "Armor"
    "apparel", "amulet", "left_ring", "shirt", "pants", "skirt", "robe", "clothing" -> 2 to "Apparel"
    "consumable", "potion", "ingredient" -> 3 to "Consumables"
    "book", "scroll" -> 4 to "Books"
    // apparatus/repair/carried_left(torches) were missing here and fell through to Misc, so the
    // shelves did NOT in fact mirror the Classic Tools tab they claim to. Same set as the
    // INV_CATEGORIES "Tools" bucket and the native companionBarterCategory "tools".
    "tools", "lockpick", "probe", "apparatus", "repair", "carried_left" -> 5 to "Tools"
    "key" -> 6 to "Keys"
    else -> 7 to "Misc"
}

/** Group a flat item list into category shelves (bucket order; within a shelf, selected items
 *  first, then alphabetical). Floating selected-first is what pulls a just-moved barter item to
 *  the FRONT of its category shelf — a bought item joining the player's side, or a sold item
 *  joining the vendor's side — so the move is obvious. Inert for looting (its items are never
 *  selected), which stays plain alphabetical. */
private fun buildShelves(items: List<ShelfItem>): List<ShelfRowData> =
    items.groupBy { shelfBucket(it.category) }
        .entries
        .sortedBy { it.key.first }
        .map { (bucket, list) ->
            ShelfRowData(
                bucket.second,
                list.sortedWith(compareByDescending<ShelfItem> { it.selected }.thenBy { it.name.lowercase() })
            )
        }

/** The player panel's focusable nav rows: category shelves, then the equipped header, then (when
 *  [expanded]) the equipped items strip. The container panel just uses its category shelves. */
private fun playerNavRows(shelves: List<ShelfRowData>, equipped: List<ShelfItem>, expanded: Boolean): List<ShelfNavRow> {
    val rows = shelves.map { ShelfNavRow(it.items) }.toMutableList()
    if (equipped.isNotEmpty()) {
        rows += ShelfNavRow(emptyList(), isEquippedHeader = true)
        if (expanded) rows += ShelfNavRow(equipped)
    }
    return rows
}

/**
 * Shelf-mode controller navigation — a 2D model (row × item, per side) fit for ragged,
 * variable-length shelves plus the collapsible equipped section, replacing the fixed-grid
 * [rememberLootNavFocus]/[rememberBarterNavFocus] math for this layout. Context-neutral (serves
 * looting AND barter):
 *  - Up/Down move between rows (shelves + equipped header/items); Left/Right move within a row.
 *  - L2/R2 switch side; Confirm taps the focused item (loot transfer / barter toggle), or toggles the
 *    equipped section when on its header; Info = the item info popup.
 *  - [onAction1] = X (looting: Take All / barter: Offer), [onAction2] = Y (looting: Dispose),
 *    [onSlider] = left-stick step (barter gold): ±1 on the horizontal axis, ±[BARTER_GOLD_COARSE_STEP]
 *    on the vertical one, both half-rate like [rememberBarterNavFocus].
 * [playerRows]/[containerRows] already reflect the current equipped-expanded state, so a Confirm on
 * the equipped header flips it via [setEquippedExpanded] and the rows recompute next frame.
 */
@Composable
private fun rememberShelfNavFocus(
    playerRows: List<ShelfNavRow>,
    containerRows: List<ShelfNavRow>,
    equippedExpanded: Boolean,
    setEquippedExpanded: (Boolean) -> Unit,
    infoOnTop: Boolean,
    onAction1: () -> Unit = {},
    onAction2: () -> Unit = {},
    onSlider: (Int) -> Unit = {},
): ShelfFocus {
    var side by remember { mutableStateOf(if (containerRows.isNotEmpty()) 1 else 0) }
    var row by remember { mutableStateOf(0) }
    var item by remember { mutableStateOf(0) }

    // Keep focus in range as rows/items change (items taken/put, equipped expand/collapse, side switch).
    LaunchedEffect(playerRows, containerRows, side) {
        val rows = if (side == 0) playerRows else containerRows
        row = row.coerceIn(0, (rows.size - 1).coerceAtLeast(0))
        val n = rows.getOrNull(row)?.items?.size ?: 0
        item = item.coerceIn(0, (n - 1).coerceAtLeast(0))
    }

    val snap = rememberUpdatedState(playerRows to containerRows)
    val expandState = rememberUpdatedState(equippedExpanded)
    val setExpand = rememberUpdatedState(setEquippedExpanded)
    val action1 = rememberUpdatedState(onAction1)
    val action2 = rememberUpdatedState(onAction2)
    val slider = rememberUpdatedState(onSlider)
    LaunchedEffect(Unit) {
        var lastSeq = GameStateRepository.navEvent.value?.seq ?: -1L
        var sliderTick = 0 // apply the gold step every OTHER slider tick → ~half rate (matches barter)
        var coarseTick = 0 // ditto for the vertical (±10) axis; own counter, as in barter
        GameStateRepository.navEvent.collect { ev ->
            if (ev == null || ev.seq <= lastSeq) return@collect
            lastSeq = ev.seq
            if (ModalNav.open) return@collect
            val (pRows, cRows) = snap.value
            fun rowsFor(s: Int) = if (s == 0) pRows else cRows
            fun curRows() = rowsFor(side)
            fun clampRow() { row = row.coerceIn(0, (curRows().size - 1).coerceAtLeast(0)) }
            fun clampItem() {
                val n = curRows().getOrNull(row)?.items?.size ?: 0
                item = item.coerceIn(0, (n - 1).coerceAtLeast(0))
            }
            when (ev) {
                is NavEvent.Down -> if (row + 1 < curRows().size) { row++; clampItem() }
                is NavEvent.Up -> if (row > 0) { row--; clampItem() }
                is NavEvent.Right -> {
                    val n = curRows().getOrNull(row)?.items?.size ?: 0
                    if (item + 1 < n) item++
                }
                is NavEvent.Left -> if (item > 0) item--
                is NavEvent.L2 -> { side = 0; clampRow(); clampItem() }
                is NavEvent.R2 -> { side = 1; clampRow(); clampItem() }
                is NavEvent.Confirm -> {
                    val r = curRows().getOrNull(row) ?: return@collect
                    if (r.isEquippedHeader) setExpand.value(!expandState.value)
                    else r.items.getOrNull(item)?.onTap?.invoke()
                }
                is NavEvent.Action1 -> action1.value()
                is NavEvent.Action2 -> action2.value()
                is NavEvent.SliderLeft -> if (sliderTick++ % 2 == 0) slider.value(-1)
                is NavEvent.SliderRight -> if (sliderTick++ % 2 == 0) slider.value(1)
                is NavEvent.SliderUp ->
                    if (coarseTick++ % 2 == 0) slider.value(BARTER_GOLD_COARSE_STEP)
                is NavEvent.SliderDown ->
                    if (coarseTick++ % 2 == 0) slider.value(-BARTER_GOLD_COARSE_STEP)
                is NavEvent.Info -> curRows().getOrNull(row)?.items?.getOrNull(item)?.let {
                    ItemInfoPopupState.toggle(it.id, it.name, it.enchant, onTop = infoOnTop)
                }
                else -> Unit
            }
            if (ItemInfoPopupState.isOpen) {
                curRows().getOrNull(row)?.items?.getOrNull(item)?.let {
                    ItemInfoPopupState.follow(it.id, it.name, it.enchant, onTop = infoOnTop)
                }
            }
        }
    }
    // Clamp the REPORTED focus in composition (see the same note in rememberLootNavFocus): taking
    // the last item of a shelf drops that whole row, and the clamping effect above only catches up
    // afterwards, so an unclamped row/item would resolve to null for one pass and close a
    // focus-linked info popup instead of moving it.
    val cur = if (side == 0) playerRows else containerRows
    val safeRow = row.coerceIn(0, (cur.size - 1).coerceAtLeast(0))
    val safeItem = item.coerceIn(0, ((cur.getOrNull(safeRow)?.items?.size ?: 0) - 1).coerceAtLeast(0))
    return ShelfFocus(side, safeRow, safeItem)
}

/** Fixed-width reserved scroll gutter on a panel's inner edge. Always present (constant column
 *  width whether or not the content scrolls); the thumb size/offset derive from real
 *  [state] layout info (item-granularity), so it reflects the panel's vertical scroll. */
@Composable
private fun ShelfScrollGutter(state: LazyListState, modifier: Modifier = Modifier) {
    val total = state.layoutInfo.totalItemsCount
    val visible = state.layoutInfo.visibleItemsInfo.size
    Box(
        modifier
            .width(6.dp)
            .fillMaxHeight()
            .clip(RoundedCornerShape(3.dp))
            .background(Color(0xFF0E0B07))
    ) {
        if (total > 0 && visible < total) {
            // Thumb: fraction of items visible, offset by the first visible index (approximate but
            // faithful enough at item granularity for these short lists).
            val thumbFrac = (visible.toFloat() / total).coerceIn(0.12f, 1f)
            val offsetFrac = (state.firstVisibleItemIndex.toFloat() / total).coerceIn(0f, 1f - thumbFrac)
            BoxWithConstraints(Modifier.fillMaxSize()) {
                val h = maxHeight
                Box(
                    Modifier
                        .offset(y = h * offsetFrac)
                        .fillMaxWidth()
                        .height(h * thumbFrac)
                        .clip(RoundedCornerShape(3.dp))
                        .background(BronzeDark)
                )
            }
        }
    }
}

/** One item cell in a shelf: icon (enchant backdrop + worn bronze border, carried over from the
 *  grid cell) with the name beneath, plus a controller-focus ring. Tap = [item].onTap. */
@Composable
private fun ShelfCell(item: ShelfItem, focused: Boolean) {
    val iconBitmap = rememberItemIcon(item.icon)
    Box(modifier = Modifier.onGloballyPositioned { ItemInfoPopupState.reportAnchor(item.id, it.boundsInRoot()) }) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            modifier = Modifier
                .width(54.dp)
                .then(
                    if (focused) Modifier
                        .clip(RoundedCornerShape(4.dp))
                        .background(BronzeLight.copy(alpha = 0.15f))
                        .border(2.dp, BronzeLight, RoundedCornerShape(4.dp))
                    else Modifier
                )
                .clickable { item.onTap() }
                .padding(2.dp)
        ) {
            // Icon box — worn/enchant decoration carried over from LootGridCell; barter's SELECTED
            // (staged into the offer) adds the SlotWorn fill + a bright border + a green count badge,
            // matching BarterGridCell so worn (border only) and selected still read distinctly.
            val highlight = item.worn || item.selected
            Box(
                modifier = Modifier
                    .size(48.dp)
                    .clip(RoundedCornerShape(3.dp))
                    .background(if (item.selected) SlotWorn else SlotBg)
                    .border(
                        BorderStroke(if (highlight) 2.dp else 1.dp, if (highlight) BronzeLight else BronzeDark),
                        RoundedCornerShape(3.dp)
                    )
            ) {
                EnchantBackdrop(item.enchanted)
                if (iconBitmap != null) {
                    Image(
                        bitmap = iconBitmap,
                        contentDescription = null,
                        contentScale = ContentScale.Fit,
                        modifier = Modifier.fillMaxSize().padding(3.dp)
                    )
                }
                if (item.selected && item.selectedCount > 1) {
                    Text(
                        "×${item.selectedCount}",
                        color = BronzeLight, fontSize = 9.sp,
                        fontFamily = MwData, fontWeight = FontWeight.Bold,
                        modifier = Modifier
                            .align(Alignment.BottomEnd)
                            .background(Color(0xCC0E0B07))
                            .padding(horizontal = 2.dp)
                    )
                } else if (!item.selected && item.count > 1) {
                    Text(
                        "×${item.count}",
                        color = BoneBright, fontSize = 9.sp,
                        fontFamily = MwData, fontWeight = FontWeight.Bold,
                        modifier = Modifier
                            .align(Alignment.BottomEnd)
                            .background(Color(0xCC0E0B07))
                            .padding(horizontal = 2.dp)
                    )
                }
            }
            Spacer(Modifier.height(2.dp))
            Text(
                item.name,
                color = if (item.worn || item.selected) BoneBright else Bone,
                fontSize = 8.sp, fontFamily = MwBody,
                textAlign = TextAlign.Center,
                maxLines = 2, overflow = TextOverflow.Ellipsis,
                lineHeight = 9.sp,
                modifier = Modifier.width(54.dp)
            )
            // Per-unit barter price (null for looting → no line).
            if (item.price != null) {
                Text("${item.price}g", color = BoneDim, fontSize = 8.sp, fontFamily = MwData, maxLines = 1)
            }
        }
    }
}

/** One labelled shelf: category label + a horizontal-scrolling row of [ShelfCell]s, with a
 *  trailing chevron hint shown while more items exist off the right edge. [focusedItem] (-1 =
 *  none) drives the cell highlight and scrolls that cell into view. Its own horizontal scroll
 *  state is remembered per shelf slot (keyed by category by the caller's LazyColumn key), so it
 *  survives optimistic take/put list mutation. */
@Composable
private fun CategoryShelf(shelf: ShelfRowData, focusedItem: Int) {
    val hState = rememberLazyListState()
    // Windowed, NOT pinned-to-the-left-edge (see WindowedFocusScroll) — the shelf strips are the
    // shelf layout's horizontal navigation, so they get the same treatment as the classic grids.
    WindowedFocusScroll(hState, focusedItem, shelf.items.size, shelf.items)
    Column(Modifier.fillMaxWidth().padding(vertical = 3.dp)) {
        Text(
            shelf.label,
            color = BronzeLight, fontSize = 11.sp,
            fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 0.5.sp
        )
        Spacer(Modifier.height(2.dp))
        Box(Modifier.fillMaxWidth()) {
            LazyRow(
                state = hState,
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                // No item key: the same record id can legitimately appear twice within one barter
                // panel (a player-owned item and a bought vendor copy of the same id), which would
                // crash a keyed list. Index keys are fine — the per-shelf scroll state is keyed by
                // category on the outer LazyColumn, not per cell.
                itemsIndexed(shelf.items) { i, it ->
                    ShelfCell(it, focused = i == focusedItem)
                }
            }
            // Chevron hint: more items off the right edge.
            if (hState.canScrollForward) {
                Box(
                    Modifier
                        .align(Alignment.CenterEnd)
                        .fillMaxHeight()
                        .background(
                            androidx.compose.ui.graphics.Brush.horizontalGradient(
                                listOf(Color.Transparent, SplitBoxBg)
                            )
                        )
                        .padding(start = 10.dp, end = 1.dp),
                    contentAlignment = Alignment.Center
                ) {
                    Text("›", color = BronzeLight, fontSize = 18.sp, fontFamily = MwDisplay, fontWeight = FontWeight.Bold)
                }
            }
        }
    }
}

/** The player-side Equipped section, pinned to the bottom of the panel by layout. Collapsed by
 *  default to a single "Equipped (N)" row + chevron; expands to a horizontal shelf of the worn
 *  items. Its own dashed border sets it apart — there is NO divider above it. Player-side only.
 *  [headerFocused] = the collapsed/expand header row is focused; [focusedItem] (-1 = none) is the
 *  focused worn item when expanded. */
@Composable
private fun EquippedSection(
    items: List<ShelfItem>,
    expanded: Boolean,
    onToggle: () -> Unit,
    headerFocused: Boolean,
    focusedItem: Int,
) {
    val hState = rememberLazyListState()
    // Windowed, NOT pinned-to-the-left-edge — same as the category strips above.
    WindowedFocusScroll(hState, focusedItem, items.size, items)
    val dash = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(6f, 4f))
    Column(
        Modifier
            .fillMaxWidth()
            .padding(top = 4.dp)
            .drawBehind {
                drawRoundRect(
                    color = BronzeDark,
                    style = androidx.compose.ui.graphics.drawscope.Stroke(width = 1.dp.toPx(), pathEffect = dash),
                    cornerRadius = androidx.compose.ui.geometry.CornerRadius(4.dp.toPx())
                )
            }
            .padding(6.dp)
    ) {
        // Header row (tap toggles expand/collapse). Focus ring when the controller is on the header.
        Row(
            Modifier
                .fillMaxWidth()
                .then(
                    if (headerFocused) Modifier
                        .clip(RoundedCornerShape(3.dp))
                        .background(BronzeLight.copy(alpha = 0.15f))
                        .border(1.dp, BronzeLight, RoundedCornerShape(3.dp))
                    else Modifier
                )
                .clickable { onToggle() }
                .padding(horizontal = 4.dp, vertical = 3.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                "Equipped (${items.size})",
                color = BoneMuted, fontSize = 11.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 0.5.sp
            )
            Spacer(Modifier.weight(1f))
            Text(if (expanded) "▾" else "▸", color = BronzeLight, fontSize = 12.sp, fontFamily = MwDisplay)
        }
        if (expanded) {
            Spacer(Modifier.height(3.dp))
            LazyRow(
                state = hState,
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                itemsIndexed(items) { i, it ->
                    ShelfCell(it, focused = i == focusedItem)
                }
            }
        }
    }
}

/** One shelf-layout panel (player or other side): a header row (name + role-specific info), a
 *  vertically-scrolling stack of [CategoryShelf]s with a reserved [ShelfScrollGutter] on the inner
 *  edge, and — player side only — the pinned [EquippedSection]. Nav rows are: category shelves
 *  (0..n-1), then equipped header (n), then equipped items (n+1) when expanded; [focusedRow] (-1 =
 *  this side unfocused) selects which, [focusedItem] the cell within it. */
@Composable
private fun ShelfColumn(
    headerLeft: String,
    headerRight: AnnotatedString,
    shelves: List<ShelfRowData>,
    equipped: List<ShelfItem>,
    equippedExpanded: Boolean,
    onToggleEquipped: () -> Unit,
    emptyText: String,
    gutterOnLeft: Boolean,
    focusedRow: Int,
    focusedItem: Int,
    modifier: Modifier = Modifier,
) {
    val shelfCount = shelves.size
    val listState = rememberLazyListState()
    // Scroll the focused category shelf into view (equipped rows are pinned, always visible).
    LaunchedEffect(focusedRow) {
        if (focusedRow in 0 until shelfCount) listState.animateScrollToItem(focusedRow)
    }
    ScrollByNav(listState, active = focusedRow in 0 until shelfCount)

    Column(modifier) {
        // Header: name left, role-specific info right.
        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
            Text(
                headerLeft,
                color = BronzeLight, fontSize = 13.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                maxLines = 1, overflow = TextOverflow.Ellipsis,
                modifier = Modifier.weight(1f, fill = false)
            )
            Spacer(Modifier.weight(1f))
            // Default color so a plain (unstyled) headerRight is legible on the dark panel; any
            // SpanStyle colors in the AnnotatedString (gold amount, load-tinted weight) override it.
            Text(headerRight, color = Bone, fontSize = 11.sp, fontFamily = MwData, maxLines = 1)
        }
        Spacer(Modifier.height(3.dp))
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.5f)))
        Spacer(Modifier.height(3.dp))

        // Shelf stack + reserved gutter. weight(1f) so the equipped section pins below.
        Row(Modifier.fillMaxWidth().weight(1f)) {
            if (gutterOnLeft) {
                ShelfScrollGutter(listState)
                Spacer(Modifier.width(4.dp))
            }
            Box(Modifier.weight(1f).fillMaxHeight()) {
                if (shelves.isEmpty()) {
                    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                        Text(emptyText, color = BoneDim, fontSize = 12.sp, fontFamily = MwBody)
                    }
                } else {
                    LazyColumn(state = listState, modifier = Modifier.fillMaxSize()) {
                        items(shelves, key = { it.label }) { shelf ->
                            val fi = if (focusedRow in 0 until shelfCount && shelves.getOrNull(focusedRow) === shelf)
                                focusedItem else -1
                            CategoryShelf(shelf, focusedItem = fi)
                        }
                    }
                }
            }
            if (!gutterOnLeft) {
                Spacer(Modifier.width(4.dp))
                ShelfScrollGutter(listState)
            }
        }

        // Player-side pinned equipped section (no divider above — its own border sets it apart).
        if (equipped.isNotEmpty()) {
            EquippedSection(
                items = equipped,
                expanded = equippedExpanded,
                onToggle = onToggleEquipped,
                headerFocused = focusedRow == shelfCount,
                focusedItem = if (focusedRow == shelfCount + 1) focusedItem else -1,
            )
        }
    }
}

// Width of the center divider strip between the two shelf panels, on the SPLIT (top) screen. Widened
// from the original 18dp so each panel's shelf row fits a WHOLE number of icon cells instead of ~6.2
// (a partial 7th peeking — the chevron already signals more off-screen). Each cell is ~58dp wide
// (54dp + 4dp gap), so trimming ~0.2 cell per panel means ~+23dp of total divider; a further +8dp
// swallows the last thin sliver (~an icon's bronze border) that still peeked, plus a couple px of
// margin. ~4dp of trim per panel. Tune here if the fit is off.
private val SHELF_CENTER_DIVIDER_WIDTH = 50.dp

// The BOTTOM-screen shelf layout is narrower and doesn't need the whole-icon-fit widening — the two
// panels read better closer together, so this is ~half the split width (the panels' separation).
private val SHELF_CENTER_DIVIDER_WIDTH_BOTTOM = 25.dp

/** The center divider between the two shelf panels: a distinct vertical strip with a small
 *  circular badge marking the boundary. Shared across all shelf contexts for one visual language.
 *  [width] is the split-screen default; the bottom layouts pass a narrower value. */
@Composable
private fun ShelfCenterDivider(width: Dp = SHELF_CENTER_DIVIDER_WIDTH) {
    Box(
        Modifier.fillMaxHeight().width(width).adaptiveDimTint(),
        contentAlignment = Alignment.Center
    ) {
        Box(Modifier.width(2.dp).fillMaxHeight().background(BronzeDark))
        Box(
            Modifier
                .size(16.dp)
                .clip(CircleShape)
                // Same panel fill as the columns either side, so it fades with them — left opaque
                // it would sit between two transparent panels as a solid blob.
                .background(SplitBoxBg.copy(alpha = LocalPanelOpacity.current))
                .border(1.dp, Bronze, CircleShape),
            contentAlignment = Alignment.Center
        ) {
            Box(Modifier.size(5.dp).clip(CircleShape).background(BronzeLight))
        }
    }
}

/**
 * Assembles the shelf-mode dual panel (player | center divider | other side) and owns the
 * shelf-mode controller navigation. Screen-agnostic and context-neutral — used by both the bottom
 * and split entry points of looting AND barter. Callers pass already-projected [ShelfItem] lists
 * (worn player items separated into [playerEquipped]) plus the role headers and the generic actions
 * ([onAction1] = X, [onAction2] = Y, [onSlider] = left-stick); this keeps each overlay's data
 * plumbing untouched. [infoOnTop] targets the item-info popup at the screen the panel is composed on.
 */
@Composable
private fun ShelfDualPanel(
    playerHeaderLeft: String,
    playerHeaderRight: AnnotatedString,
    playerShelfItems: List<ShelfItem>,
    playerEquipped: List<ShelfItem>,
    otherHeaderLeft: String,
    otherHeaderRight: AnnotatedString,
    otherItems: List<ShelfItem>,
    otherEmptyText: String,
    infoOnTop: Boolean,
    onAction1: () -> Unit = {},
    onAction2: () -> Unit = {},
    onSlider: (Int) -> Unit = {},
    dividerWidth: Dp = SHELF_CENTER_DIVIDER_WIDTH,
    modifier: Modifier = Modifier,
) {
    val playerShelves = remember(playerShelfItems) { buildShelves(playerShelfItems) }
    val otherShelves = remember(otherItems) { buildShelves(otherItems) }
    var equippedExpanded by remember { mutableStateOf(false) }

    val playerRows = playerNavRows(playerShelves, playerEquipped, equippedExpanded)
    val otherRows = otherShelves.map { ShelfNavRow(it.items) }

    val focus = rememberShelfNavFocus(
        playerRows = playerRows,
        containerRows = otherRows,
        equippedExpanded = equippedExpanded,
        setEquippedExpanded = { equippedExpanded = it },
        infoOnTop = infoOnTop,
        onAction1 = onAction1,
        onAction2 = onAction2,
        onSlider = onSlider,
    )

    // Bug 1: keep a focus-linked info popup on the focused shelf cell when a take/sell removes an
    // item or a re-sort moves it under the fixed focus (side/row/item). Same reactive mechanism the
    // classic grids use; the shelf nav collector still follows synchronously on D-pad moves.
    run {
        val rows = if (focus.side == 0) playerRows else otherRows
        val focusedItem = rows.getOrNull(focus.row)?.items?.getOrNull(focus.item)
        FollowFocusedInfoPopup(focusedItem?.let { InfoTarget(it.id, it.name, it.enchant) }, onTop = infoOnTop)
    }

    Row(modifier.fillMaxWidth()) {
        ShelfColumn(
            headerLeft = playerHeaderLeft,
            headerRight = playerHeaderRight,
            shelves = playerShelves,
            equipped = playerEquipped,
            equippedExpanded = equippedExpanded,
            onToggleEquipped = { equippedExpanded = !equippedExpanded },
            emptyText = "Empty",
            gutterOnLeft = false, // player is the LEFT panel → gutter on its inner (right) edge
            focusedRow = if (focus.side == 0) focus.row else -1,
            focusedItem = focus.item,
            modifier = Modifier.weight(1f).fillMaxHeight().splitColumnBox()
        )
        ShelfCenterDivider(dividerWidth)
        ShelfColumn(
            headerLeft = otherHeaderLeft,
            headerRight = otherHeaderRight,
            shelves = otherShelves,
            equipped = emptyList(), // equipped section is player-side ONLY
            equippedExpanded = false,
            onToggleEquipped = {},
            emptyText = otherEmptyText,
            gutterOnLeft = true, // other is the RIGHT panel → gutter on its inner (left) edge
            focusedRow = if (focus.side == 1) focus.row else -1,
            focusedItem = focus.item,
            modifier = Modifier.weight(1f).fillMaxHeight().splitColumnBox()
        )
    }
}

/** Project a looting [InventoryItem] into a [ShelfItem]. [onTap] runs the put/take (with the
 *  quantity prompt) the caller supplies. */
private fun InventoryItem.toShelfItem(worn: Boolean, onTap: () -> Unit): ShelfItem =
    ShelfItem(
        // Record id (NOT stackId): ShelfItem.id feeds ItemInfoPopupState (R3 info request +
        // anchor matching), and CMP:info needs the record id to resolve the item — same as
        // barter's projection and classic-mode looting's InventoryItem.id. Using stackId here
        // made shelf-mode looting's R3 popup show name-only with empty detail rows.
        id = id,
        name = displayName(),
        category = category,
        icon = icon,
        worn = worn,
        enchant = enchant,
        count = count,
        onTap = onTap,
    )

/** Project a barter [BarterItem] into a [ShelfItem]. [onTap] toggles the offer selection; the
 *  per-unit price + selection state ride along so the shelf cell renders them (worn = the item's own
 *  equipped flag, so worn player gear pulls into the Equipped section like looting). */
private fun BarterItem.toShelfItem(onTap: () -> Unit): ShelfItem =
    ShelfItem(
        id = id,
        name = displayName(),
        category = category,
        icon = icon,
        worn = worn,
        enchant = enchant,
        count = count,
        onTap = onTap,
        price = value,
        selected = isSelected,
        selectedCount = selectedCount,
    )

/** Client-side mirror of vanilla `ContainerItemModel::onDropItem` (PUT direction ONLY): returns the
 *  vanilla GMST message to show — blocking the put — or null to allow. Only genuine containers are
 *  gated (`capacity < 0` sentinel = corpse/NPC → always allowed). [containerWeight] = the container's
 *  current contents weight (summed from the optimistic list). Order + messages mirror the engine and
 *  the Lua authoritative guard exactly: organic → sContentsMessage2; capacity ≤ 0 → sContentsMessage3;
 *  contents + incoming weight > capacity → sContentsMessage3. Take is NEVER gated by this. */
private fun containerPutBlock(
    session: ContainerSession,
    containerWeight: Float,
    item: InventoryItem,
    count: Int,
    msgs: LogParser.PutMessages
): String? {
    if (session.isOrganic) return msgs.organic.ifBlank { "This is an organic container and cannot hold items." }
    if (session.capacity < 0f) return null                          // corpse / NPC → unrestricted
    val full = { msgs.full.ifBlank { "The container is full." } }
    if (session.capacity <= 0f) return full()                       // no capacity
    if (containerWeight + item.weight * count > session.capacity) return full()  // too heavy
    return null
}

/** Brief auto-dismissing restriction banner (top-centre, non-blocking) — the shared shape used by
 *  barter's "vendor won't buy that" and looting's container-put blocks. Renders nothing when null. */
@Composable
private fun RestrictionBanner(message: String?) {
    message?.let { msg ->
        Box(
            modifier = Modifier.fillMaxSize().padding(top = 24.dp),
            contentAlignment = Alignment.TopCenter
        ) {
            Text(
                msg,
                color = BoneBright, fontSize = 13.sp, fontFamily = MwBody, textAlign = TextAlign.Center,
                modifier = Modifier
                    .clip(RoundedCornerShape(4.dp))
                    .background(Color(0xF01A1206))
                    .border(1.dp, BarterRed, RoundedCornerShape(4.dp))
                    .padding(horizontal = 16.dp, vertical = 8.dp)
            )
        }
    }
}

/**
 * Two-panel looting/pickpocketing overlay: the player's inventory on the left,
 * the container/corpse/NPC's contents on the right. Tapping a player item puts
 * it into the container; tapping a container item takes it (a QuantitySelector
 * prompt appears first for stacks > 1). Long-press exposes the fuller menu.
 *
 * In-window overlay (NOT a Compose Dialog — that crashes on the Presentation
 * display; see ItemInfoOverlay). zIndex 8f sits above the tab content/bars but
 * below the shared dropdown-dismiss scrim (10f) and QuantitySelector (20f).
 * A non-interactive scrim dims and blocks the tabs beneath; there is NO
 * tap-away dismiss (Close / B / the container window closing end the session).
 */
@Composable
private fun LootingOverlay(
    session: ContainerSession,
    playerInventory: List<InventoryItem>,
    playerEquipment: Map<String, String>,
    playerEncumbrance: Dynamic,
    location: ScreenLocation
) {
    // Dismiss the item info popup when the looting/pickpocket session ends (Take All/Dispose/Close/B)
    // so it doesn't linger. Composed in BOTH bottom and SPLIT modes, so this also covers the top-grid
    // popup (both this and LootingTopOverlay leave composition on session-null).
    DisposableEffect(Unit) { onDispose { ItemInfoPopupState.close() } }
    val playerName = rememberPlayerName()
    // SPLIT: the item grids live on the TOP screen (LootingTopOverlay, hosted by
    // EngineActivity); the bottom screen shows ONLY the terminal controls. Take All /
    // Dispose / Close all END the session, so the bottom controls never need the
    // optimistic item lists — all per-item take/put taps happen on the top grid.
    if (location == ScreenLocation.SPLIT) {
        LootingControlsOnly(session)
        return
    }

    // Optimistic local copies of both item lists. GM_Container pauses the sim, which
    // freezes the Lua slow tick AND starves the companion UI of background frames, so
    // engine re-exports can't refresh the display mid-session. Instead we mutate these
    // copies locally on each tap — the tap drives its own recomposition, so the move
    // shows instantly — while the CMP:container_* command still performs the REAL move
    // in the engine. Initialized once when the overlay enters composition (on open) and
    // deliberately NOT re-synced from later `session` emissions (stale/frame-starved
    // while paused). On close→reopen the overlay leaves+re-enters composition, so these
    // re-initialize from the fresh session/inventory and the true GameState reconciles.
    var containerItems by remember { mutableStateOf(session.items) }
    var playerItems by remember { mutableStateOf(playerInventory) }

    // Container-put restriction banner (organic / capacity / weight — vanilla parity). putMsgs = the
    // vanilla GMST strings; putBlocked = the Lua backstop signal (fires only if a blocked put ever
    // slips past the client-side gate in put() below).
    val putMsgs by GameStateRepository.putMessages.collectAsState()
    val putBlocked by GameStateRepository.putBlocked.collectAsState()
    var restrictionBanner by remember { mutableStateOf<String?>(null) }
    var bannerNonce by remember { mutableStateOf(0) }
    LaunchedEffect(bannerNonce) { if (restrictionBanner != null) { delay(2200); restrictionBanner = null } }
    LaunchedEffect(putBlocked) {
        putBlocked?.let { restrictionBanner = it.first; bannerNonce++; GameStateRepository.clearPutBlocked() }
    }

    val playerGold = playerItems.firstOrNull { it.id.equals("gold_001", ignoreCase = true) }?.count ?: 0
    // Optimistic encumbrance: anchor on the real value at open (playerEncumbrance), then add/subtract
    // moved item weight per take/put/takeAll so the header updates live while GM_Container has the
    // Lua export frozen. Reconciles exactly to the engine value once looting closes.
    var encDelta by remember { mutableStateOf(0f) }
    val liveEncumbrance = Dynamic(playerEncumbrance.current + encDelta, playerEncumbrance.max)
    val wornIds = remember(playerEquipment) { playerEquipment.values.toSet() }
    fun isWorn(item: InventoryItem): Boolean =
        if (item.stackId.isNotEmpty()) wornIds.contains(item.stackId) else wornIds.contains(item.id)

    // Take: container → player (optimistic) + real CMP:container_take. Put: the reverse.
    fun take(item: InventoryItem, n: Int) {
        val (c, p) = moveOptimistic(containerItems, playerItems, item, n)
        containerItems = c; playerItems = p
        encDelta += item.weight * n
        CompanionActions.containerTake(item.stackId.ifEmpty { item.id }, n)
    }
    fun put(item: InventoryItem, n: Int) {
        // Vanilla container-put gate (organic / capacity / weight): block + banner, no move/command.
        val containerWeight = containerItems.sumOf { it.weight.toDouble() * it.count }.toFloat()
        containerPutBlock(session, containerWeight, item, n, putMsgs)?.let {
            restrictionBanner = it; bannerNonce++; return
        }
        val (p, c) = moveOptimistic(playerItems, containerItems, item, n)
        playerItems = p; containerItems = c
        encDelta -= item.weight * n
        CompanionActions.containerPut(item.stackId.ifEmpty { item.id }, n)
    }
    // Take All: optimistically empty the container into the player list, then fire the command
    // (Lua takes all AND closes the overlay). Shared by the button and the controller X action.
    fun takeAll() {
        encDelta += containerItems.sumOf { (it.weight * it.count).toDouble() }.toFloat()
        playerItems = containerItems.fold(playerItems) { acc, it ->
            moveOptimistic(listOf(it), acc, it, it.count).second
        }
        containerItems = emptyList()
        CompanionActions.containerTakeAll()
    }

    // Sort controls (Default / Weight / Value) — the same InvSortState + chips as the inventory tab.
    val sort = rememberInvSortState()
    // Pre-sort both sides ONCE at the parent — the single source of order shared by the columns'
    // display AND the controller focus index, so sorting can never desync the two.
    // DEFAULT keeps looting's own original order (worn-first player, then category + name); an
    // explicit Weight/Value sort is a pure ordering across the whole side, with no worn tier — a
    // pinned block of worn gear on top is exactly the "it's not really sorted" problem.
    val playerSorted = remember(playerItems, wornIds, sort.mode, sort.descending) {
        if (sort.mode == InvSort.DEFAULT) {
            playerItems.sortedWith(
                compareByDescending<InventoryItem> { isWorn(it) }
                    .then(compareBy({ itemCategoryRank(it.category) }, { it.displayName().lowercase() }))
            )
        } else {
            playerItems.sortedWith(
                invSortComparator(sort.mode, sort.descending, { it.displayName() }, { it.weight }, { it.value })
            )
        }
    }
    val containerSorted = remember(containerItems, sort.mode, sort.descending) {
        if (sort.mode == InvSort.DEFAULT) {
            containerItems.sortedWith(compareBy({ itemCategoryRank(it.category) }, { it.displayName().lowercase() }))
        } else {
            containerItems.sortedWith(
                invSortComparator(sort.mode, sort.descending, { it.displayName() }, { it.weight }, { it.value })
            )
        }
    }
    // Controller focus (BOTTOM = two side-by-side lists → rows = 1). Classic mode only — the shelf
    // layout runs its OWN nav (inside ShelfDualPanel); running both collectors would double-consume
    // nav events. The "Inventory Layout" options switch (default CLASSIC) selects which.
    val shelfMode = UiPreferences.inventoryLayoutFlow().collectAsState().value == InventoryLayout.SHELF
    val focus = if (shelfMode) null else rememberLootNavFocus(
        playerSorted = playerSorted,
        containerSorted = containerSorted,
        rows = 1,
        isCorpse = session.isCorpse,
        isPickpocket = session.isPickpocket,
        requestQty = { name, count, label, initial, action ->
            QuantityRequestState.requestOrRun(name, count, label, initial, action = action)
        },
        onPut = { it, n -> put(it, n) },
        onTake = { it, n -> take(it, n) },
        onTakeAll = { takeAll() },
        onDispose = { CompanionActions.containerDispose() },
        // BOTTOM has ONE sort shared by both lists (the chips live in the shared title bar), so the
        // focused side is irrelevant here. Cycles the same modes the chips offer.
        onCycleSort = { sort.cycle(InvSort.entries) },
    )

    // Bug 1: keep a focus-linked info popup on the CURRENTLY focused item when a take/put shrinks
    // the list under the fixed focus index (the nav collector only follows on D-pad moves). Classic
    // nav only — shelf mode runs its own follow inside ShelfDualPanel.
    if (!shelfMode) {
        val focusedItem = focus?.let { (if (it.side == 0) playerSorted else containerSorted).getOrNull(it.index) }
        FollowFocusedInfoPopup(focusedItem?.let { InfoTarget(it.id, it.displayName(), it.enchant) }, onTop = false)
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            // zIndex 15f (same as the dialogue overlay) — ABOVE the global
            // dropdown-dismiss scrim (10f). At the old 8f it sat BELOW that scrim,
            // so whenever the scrim was active (a LootRow long-press menu open, or
            // its anyOpen state stuck after a row left composition on a container
            // re-emit) it covered the whole overlay and swallowed every tap —
            // including the bottom buttons. Still below QuantitySelector/ItemInfo (20f)
            // so those stack above. Long-press-menu dismissal is handled by the local
            // scrim below (we can no longer rely on the global one from up here).
            .zIndex(15f)
            .background(Color(0xCC0F0C08))
            .pointerInput(Unit) { detectTapGestures {} }
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                // Fills the full screen height (bottom = 12.dp, not BOTTOM_BAR_SPACE): looting is
                // a modal interaction left via Close / Take All / B, so the panel covers the
                // bottom tab bar — same approach as the barter overlay. 12dp matches the insets.
                .padding(top = 12.dp, bottom = 12.dp, start = 12.dp, end = 12.dp)
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures {} }
        ) {
            // ---- Title bar: container name + (Classic only) the sort chips ----
            // The chips ride IN the title bar rather than on a row of their own: this list is being
            // made roomier, so spending another ~34dp of height on a control strip would undo part
            // of what the row tuning just bought. Vertical padding drops 8 → 4 because the chips
            // (which carry their own) now set the bar's height.
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 4.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    session.containerName.ifBlank { "Container" },
                    color = BronzeLight, fontSize = 14.sp,
                    fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                    maxLines = 1, overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f)
                )
                // Classic only — the Shelf layout builds its own lists straight from playerItems/
                // containerItems, so these chips would be inert there.
                if (!shelfMode) {
                    Spacer(Modifier.width(8.dp))
                    SortChipRow(sort)
                }
            }
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))

            // ---- Item panels: Shelf (grouped shelves) or Classic (two side-by-side lists) ----
            if (shelfMode) {
                ShelfDualPanel(
                    playerHeaderLeft = playerName,
                    playerHeaderRight = goldWeightHeaderRight(playerGold, liveEncumbrance),
                    playerShelfItems = playerItems.filter { !isWorn(it) }.map { itm ->
                        itm.toShelfItem(worn = false) {
                            QuantityRequestState.requestOrRun(itm.displayName(), itm.count, "Put") { n -> put(itm, n) }
                        }
                    },
                    playerEquipped = playerItems.filter { isWorn(it) }.map { itm ->
                        itm.toShelfItem(worn = true) {
                            QuantityRequestState.requestOrRun(itm.displayName(), itm.count, "Put") { n -> put(itm, n) }
                        }
                    },
                    // (Puts above use the default initial = whole stack; the Take below is
                    // pickpocket-aware — see lootQtyInitial.)
                    otherHeaderLeft = session.containerName.ifBlank { "Container" },
                    otherHeaderRight = AnnotatedString("${containerItems.size} items"),
                    otherItems = containerItems.map { itm ->
                        itm.toShelfItem(worn = false) {
                            QuantityRequestState.requestOrRun(
                                itm.displayName(), itm.count, "Take",
                                lootQtyInitial(itm.count, isTake = true, isPickpocket = session.isPickpocket)
                            ) { n -> take(itm, n) }
                        }
                    },
                    otherEmptyText = if (session.isPickpocket) "Nothing you can lift" else "Empty",
                    infoOnTop = false,
                    onAction1 = { takeAll() },
                    onAction2 = { if (session.isCorpse) CompanionActions.containerDispose() },
                    dividerWidth = SHELF_CENTER_DIVIDER_WIDTH_BOTTOM,
                    modifier = Modifier.weight(1f).padding(8.dp)
                )
            } else Row(Modifier.weight(1f).fillMaxWidth()) {
                LootColumn(
                    header = playerPackHeader(liveEncumbrance),
                    legend = "tap to put · long press for more",
                    items = playerSorted,
                    isPlayerSide = true,
                    isWorn = { isWorn(it) },
                    onTransfer = { it, n -> put(it, n) },
                    focusedIndex = if (focus!!.side == 0) focus.index else -1,
                    modifier = Modifier.weight(1f).fillMaxHeight().padding(8.dp)
                )
                // Dashed vertical divider between the two columns.
                Canvas(Modifier.fillMaxHeight().width(1.dp)) {
                    drawLine(
                        color = BronzeDark,
                        start = Offset(0f, 0f),
                        end = Offset(0f, size.height),
                        strokeWidth = size.width.coerceAtLeast(1f),
                        pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(6f, 6f))
                    )
                }
                LootColumn(
                    header = AnnotatedString(session.containerName.ifBlank { "Container" }),
                    legend = "tap to take · long press for more",
                    items = containerSorted,
                    isPlayerSide = false,
                    isWorn = { false },
                    onTransfer = { it, n -> take(it, n) },
                    // Pickpocket: an empty visible list usually means your Sneak hid the
                    // items (not that the NPC is broke) — say so. Corpses/chests: "Empty".
                    emptyText = if (session.isPickpocket) "Nothing you can lift" else "Empty",
                    isPickpocket = session.isPickpocket,
                    focusedIndex = if (focus!!.side == 1) focus.index else -1,
                    modifier = Modifier.weight(1f).fillMaxHeight().padding(8.dp)
                )
            }

            // ---- Bottom action buttons (taller than standard rows) ----
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            Row(
                modifier = Modifier.fillMaxWidth().padding(8.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                LootButton(
                    // Always enabled (like Close). Gating on containerItems.isNotEmpty()
                    // made the button go dead — and non-responsive to taps — once the
                    // local list had been optimistically emptied (which is exactly the
                    // state you're in after taking items via the companion, e.g. under
                    // Hide UI where the companion is the only take path). Take All over
                    // an empty container simply closes, which is harmless.
                    label = "Take All", hint = "X",
                    enabled = true,
                    modifier = Modifier.weight(1f)
                ) { takeAll() }
                if (session.isCorpse) {
                    LootButton(
                        // Y, not R1 — Dispose moved to Action2/Y when R1 was repurposed for
                        // category cycling; this BOTTOM-layout hint was left behind while
                        // LootingControlsOnly (SPLIT) was updated. The binding above is
                        // onAction2, so "Y" is what actually works.
                        label = "Dispose of Corpse", hint = "Y",
                        enabled = true,
                        modifier = Modifier.weight(1f)
                    ) { CompanionActions.containerDispose() }
                }
                LootButton(
                    label = "Close", hint = "B",
                    enabled = true,
                    modifier = Modifier.weight(1f)
                ) { CompanionActions.containerClose() }
            }
        }

        // Local dropdown-dismiss scrim for the LootRow long-press menus. Because this
        // overlay renders ABOVE the global DropdownState scrim (10f) — required so its
        // own buttons stay tappable — we can't lean on that global scrim to close a
        // menu on tap-away. Replicate it here: rendered only while a menu is open,
        // above the panel content but below the DropdownMenu popup window, so a tap
        // outside the menu dismisses it instead of tapping through to a row/button.
        if (DropdownState.anyOpen) {
            Box(
                Modifier
                    .fillMaxSize()
                    .pointerInput(Unit) { detectTapGestures { DropdownState.closeAll() } }
            )
        }

        // Vanilla container-put restriction feedback (organic / full / too heavy).
        RestrictionBanner(restrictionBanner)
    }
}

/** Colour for the loot-header encumbrance readout: muted normally, amber above 75 % of
 *  capacity, red at/over 100 %. */
private fun encumbranceColor(enc: Dynamic): Color = when {
    enc.max <= 0f -> BoneMuted
    enc.current >= enc.max -> Color(0xFFC75C5C)         // at/over capacity — red
    enc.current / enc.max > 0.75f -> Color(0xFFD9A441)  // over 75 % — amber
    else -> BoneMuted                                   // normal — muted bone
}

/** Player loot/pickpocket column header: "You (123g) 145/200kg" with the weight tinted by
 *  load (see [encumbranceColor]). "You" + gold ride the base BronzeLight; only the weight
 *  span overrides colour. NOTE: the sim is paused during GM_Container so [enc] is a snapshot
 *  from session open — it does not track optimistic take/put (unlike gold, recomputed live).
 *
 *  Deliberately "You" rather than the character's name: the name is the one part of this header
 *  carrying no information the player doesn't already have, and in the SPLIT layout it shares a
 *  single line with the compact sort chips — a long character name ellipsized the header while
 *  crowding them. The encumbrance figure (which the opposite column never shows) is what actually
 *  identifies this as your side, so the disambiguation survives losing the name. "You" is already
 *  this file's idiom for the player — it is [rememberPlayerName]'s own fallback.
 *
 *  NO gold here, deliberately. Both screens already show it more prominently elsewhere — looting in
 *  the shelf panel's right slot, barter in its gold/offer controls, where it is the number you are
 *  actually transacting with — so repeating it in the column header only cost width that the sort
 *  chips needed. Carried weight is the figure that belongs on the item column, because it is what
 *  limits what you can take or buy.
 *
 *  Shared by looting AND barter so the two cannot drift: it is the same panel doing the same job. */
private fun playerPackHeader(enc: Dynamic): AnnotatedString =
    buildAnnotatedString {
        append("You ")
        withStyle(SpanStyle(color = encumbranceColor(enc))) {
            append("${dynValue(enc)}kg")
        }
    }

/** Right-aligned header info for a player SHELF panel: "123g  145/200kg", gold on BronzeLight and
 *  the weight tinted by load ([encumbranceColor]). Shared by looting AND barter (both show the
 *  player's carried weight). The name rides the shelf header's left slot. */
private fun goldWeightHeaderRight(gold: Int, enc: Dynamic): AnnotatedString =
    buildAnnotatedString {
        withStyle(SpanStyle(color = BronzeLight)) { append("${gold}g  ") }
        withStyle(SpanStyle(color = encumbranceColor(enc))) { append("${dynValue(enc)}kg") }
    }

/** Right-aligned gold-only header (vendor/other side): "123g" on BronzeLight so the amount reads
 *  clearly against the dark panel. */
private fun goldHeaderRight(gold: Int): AnnotatedString =
    buildAnnotatedString {
        withStyle(SpanStyle(color = BronzeLight)) { append("${gold}g") }
    }

/** One side of the looting overlay — header, legend, and a scrolling item list. [items] arrives
 *  pre-sorted from the parent (single source of order shared with the controller focus index).
 *  [focusedIndex] highlights that row (-1 = this side isn't focused) and keeps it on-screen. */
@Composable
private fun LootColumn(
    header: AnnotatedString,
    legend: String,
    items: List<InventoryItem>,
    isPlayerSide: Boolean,
    isWorn: (InventoryItem) -> Boolean,
    onTransfer: (InventoryItem, Int) -> Unit,
    emptyText: String = "Empty",
    /** Living NPC — a Take here opens the quantity picker at 1, not the stack (lootQtyInitial). */
    isPickpocket: Boolean = false,
    focusedIndex: Int = -1,
    modifier: Modifier = Modifier
) {
    Column(modifier) {
        Text(
            header,
            color = BronzeLight, fontSize = 13.sp,
            fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
            maxLines = 1, overflow = TextOverflow.Ellipsis
        )
        Text(
            legend,
            color = BoneDim, fontSize = 9.sp, fontFamily = MwBody,
            maxLines = 1, overflow = TextOverflow.Ellipsis
        )
        Spacer(Modifier.height(4.dp))
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.5f)))
        if (items.isEmpty()) {
            Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                Text(emptyText, color = BoneDim, fontSize = 12.sp, fontFamily = MwBody)
            }
        } else {
            val listState = rememberLazyListState()
            LaunchedEffect(focusedIndex) {
                if (focusedIndex in items.indices) listState.animateScrollToItem(focusedIndex)
            }
            // Right stick scrolls this list while it's the focused side.
            ScrollByNav(listState, active = focusedIndex >= 0)
            LazyColumn(state = listState, modifier = Modifier.fillMaxSize()) {
                itemsIndexed(items) { i, item ->
                    LootRow(
                        item = item,
                        isPlayerSide = isPlayerSide,
                        worn = isPlayerSide && isWorn(item),
                        iconBitmap = rememberItemIcon(item.icon),
                        focused = i == focusedIndex,
                        isPickpocket = isPickpocket,
                        onTransfer = onTransfer
                    )
                }
            }
        }
    }
}

/* ---- Classic item-row geometry (looting + barter BOTTOM lists) ----
 *
 * These are FREE-SCROLLING LazyColumns, not fixed-row grids like the inventory tab's Cards style —
 * so there is no row count to engineer; how many rows are visible simply falls out of the row
 * height against the list's share of the panel.
 *
 * Tuned Aug 2026 ("feels cramped"): slightly more vertical padding, a slightly smaller icon, and
 * item names may now wrap to TWO lines instead of truncating at one. [CLASSIC_ROW_MIN_HEIGHT] is
 * what keeps that last change from making the list ragged — it reserves the two-line height on
 * EVERY row, so a short name and a wrapped one occupy the same box and the rows stay aligned.
 * Shared by both rows so the two Classic lists stay in step; barter's row was already 2dp tighter
 * than looting's for no particular reason, and now they match.
 */
private val CLASSIC_ROW_ICON = 32.dp          // was 36 (loot) / 34 (barter)
private val CLASSIC_ROW_PAD_V = 12.dp         // was 10 (loot) / 8 (barter)
private val CLASSIC_ROW_MIN_HEIGHT = 74.dp    // ≈ padding + two name lines + sub-line

/**
 * One item row in the looting overlay. Tap = transfer (put/take); long-press =
 * the fuller menu. A stack > 1 routes through QuantityRequestState so the shared
 * QuantitySelector asks "how many?" first.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun LootRow(
    item: InventoryItem,
    isPlayerSide: Boolean,
    worn: Boolean,
    iconBitmap: ImageBitmap? = null,
    focused: Boolean = false,
    isPickpocket: Boolean = false,
    onTransfer: (InventoryItem, Int) -> Unit
) {
    val context = LocalContext.current
    var menuOpen by remember { mutableStateOf(false) }
    LaunchedEffect(DropdownState.closeRequest) {
        if (DropdownState.closeRequest > 0) menuOpen = false
    }
    val label = item.displayName()
    val sid = item.stackId.ifEmpty { item.id }
    val favs by FavouritesRepository.state.collectAsState()
    val isFav = isPlayerSide && favs.gear.any { it?.id == item.id }
    val confirmLabel = if (isPlayerSide) "Put" else "Take"

    // The tap action (put or take), prompting for a quantity when the stack > 1. The picker opens
    // on the whole stack except a pickpocket Take (lootQtyInitial).
    // onTransfer performs BOTH the optimistic list move and the CMP:container_* command.
    fun transfer() {
        QuantityRequestState.requestOrRun(
            label, item.count, confirmLabel,
            lootQtyInitial(item.count, isTake = !isPlayerSide, isPickpocket = isPickpocket)
        ) { n ->
            onTransfer(item, n)
        }
    }

    Box(modifier = Modifier.onGloballyPositioned { ItemInfoPopupState.reportAnchor(item.id, it.boundsInRoot()) }) {
        Column {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    // Controller focus: a bronze border + faint fill on the whole row. Worn is shown
                    // by the brighter name + "WORN" tag (text only, no border), so this reads as a
                    // distinct "cursor here" marker.
                    .then(
                        if (focused) Modifier
                            .background(BronzeLight.copy(alpha = 0.12f))
                            .border(2.dp, BronzeLight)
                        else Modifier
                    )
                    .combinedClickable(
                        onClick = { transfer() },
                        onLongClick = { menuOpen = true; DropdownState.open() }
                    )
                    // Uniform row box (see CLASSIC_ROW_MIN_HEIGHT) so one- and two-line names line up.
                    .heightIn(min = CLASSIC_ROW_MIN_HEIGHT)
                    .padding(start = 8.dp, end = 8.dp, top = CLASSIC_ROW_PAD_V, bottom = CLASSIC_ROW_PAD_V),
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Icon box.
                Box(
                    modifier = Modifier
                        .size(CLASSIC_ROW_ICON)
                        .clip(RoundedCornerShape(2.dp))
                        .background(SlotBg)
                        .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
                ) {
                    EnchantBackdrop(item.enchant != null)
                    if (iconBitmap != null) {
                        Image(
                            bitmap = iconBitmap,
                            contentDescription = null,
                            contentScale = ContentScale.Fit,
                            modifier = Modifier.fillMaxSize()
                        )
                    }
                }
                Spacer(Modifier.width(8.dp))
                // Name + sub-line (category · qty / cond).
                Column(Modifier.weight(1f).padding(end = 8.dp)) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Text(
                            label,
                            color = if (worn) BoneBright else BoneMuted,
                            fontSize = 13.sp, fontFamily = MwBody,
                            // Two lines before ellipsis — these columns are ~175dp wide, so a name
                            // like "Extravagant Robe of Deflection" used to truncate outright. The
                            // row reserves the two-line height either way, so wrapping costs nothing.
                            maxLines = 2, overflow = TextOverflow.Ellipsis,
                            modifier = Modifier.weight(1f, fill = false)
                        )
                        if (isFav) { Spacer(Modifier.width(4.dp)); FavStar() }
                        if (worn) {
                            Spacer(Modifier.width(6.dp))
                            Text(
                                "WORN",
                                color = BronzeLight, fontSize = 9.sp,
                                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                                letterSpacing = 0.8.sp
                            )
                        }
                    }
                    Text(
                        lootSubline(item),
                        color = BoneDim, fontSize = 9.sp, fontFamily = MwBody,
                        maxLines = 1, overflow = TextOverflow.Ellipsis
                    )
                }
                // Tap hint (muted).
                Text(
                    if (isPlayerSide) "tap to put" else "tap to take",
                    color = BoneDim.copy(alpha = 0.7f), fontSize = 8.sp,
                    fontFamily = MwBody, letterSpacing = 0.3.sp
                )
            }
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
        }

        CompanionDropdownMenu(
            expanded = menuOpen,
            onDismissRequest = { menuOpen = false; DropdownState.closeAll() }
        ) {
            Text(
                label,
                color = BronzeLight, fontSize = 12.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp)
            )
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
            val menuItemColors = MenuDefaults.itemColors(textColor = Bone)
            // Primary transfer.
            DropdownMenuItem(
                text = { Text(if (isPlayerSide) "Put" else "Take", fontFamily = MwBody, fontSize = 13.sp) },
                onClick = { menuOpen = false; DropdownState.closeAll(); transfer() },
                colors = menuItemColors
            )
            // Equip. Player side equips in place; container side takes the whole
            // stack then equips it by record id (the taken instance re-stacks, so we
            // can't target its new stackId — equipItem finds the first matching record).
            val equippable = item.category !in setOf("misc", "potion", "ingredient", "book", "scroll")
            if (equippable) {
                DropdownMenuItem(
                    text = { Text("Equip", fontFamily = MwBody, fontSize = 13.sp) },
                    onClick = {
                        menuOpen = false; DropdownState.closeAll()
                        if (isPlayerSide) {
                            CompanionActions.equipItem(sid)
                        } else {
                            // Optimistically take the whole stack (list move + command),
                            // then equip the taken item by record id.
                            onTransfer(item, item.count)
                            CompanionActions.equipItem(item.id)
                        }
                    },
                    colors = menuItemColors
                )
            }
            DropdownMenuItem(
                text = { Text("Info", fontFamily = MwBody, fontSize = 13.sp) },
                onClick = { menuOpen = false; DropdownState.closeAll(); ItemInfoPopupState.open(item.id, item.name, item.enchant) },
                colors = menuItemColors
            )
            // Favourite (player side only).
            if (isPlayerSide) {
                FavouriteMenuItems(
                    context = context,
                    isGear = true,
                    itemId = item.id,
                    makeSlot = { FavSlot(item.id, label) },
                    onDone = { menuOpen = false; DropdownState.closeAll() }
                )
            }
        }
    }
}

/**
 * Move `n` of `item` from `source` to `dest` for the optimistic looting UI. Reduces
 * (or removes at 0) the matched stack in `source` — matched by stackId when present,
 * else by record id — and merges `n` into a same-record stack in `dest`, else appends
 * a new stack. Approximate (e.g. distinct-condition stacks may merge for display); the
 * real GameState reconciles when the container closes. Returns (newSource, newDest).
 */
private fun moveOptimistic(
    source: List<InventoryItem>,
    dest: List<InventoryItem>,
    item: InventoryItem,
    n: Int
): Pair<List<InventoryItem>, List<InventoryItem>> {
    val moved = n.coerceIn(1, item.count)
    fun sameStack(a: InventoryItem): Boolean =
        if (a.stackId.isNotEmpty() && item.stackId.isNotEmpty()) a.stackId == item.stackId
        else a.id == item.id
    val newSource = source.mapNotNull { s ->
        if (sameStack(s)) (if (s.count > moved) s.copy(count = s.count - moved) else null) else s
    }
    val idx = dest.indexOfFirst { it.id == item.id }
    val newDest = if (idx >= 0) {
        dest.mapIndexed { i, d -> if (i == idx) d.copy(count = d.count + moved) else d }
    } else {
        dest + item.copy(count = moved)
    }
    return newSource to newDest
}

/** Sub-line under a loot item name: capitalized category + count + condition %. */
/* ---- Looting SPLIT mode (top-screen grids + bottom-screen controls) ---- */

// Gap between the two separate column boxes on the top screen. Single tweakable constant.
private val LOOT_SPLIT_COLUMN_GAP = 8.dp

/* ---- SPLIT grid geometry (looting + barter TOP-screen columns) ----
 *
 * Both grids are `GridCells.Fixed(3)` over the panel's height, so the CELL height is
 * (grid height − 2×4dp spacing) / 3 — there is no per-cell height to set. The cells' name labels
 * are already `maxLines = 2`, but at the old geometry the cell was ~65dp against the ~75dp that
 * icon + two 8sp lines actually need, so the second line was simply clipped off and long names
 * read as truncated (Aug 10 2026 report).
 *
 * Fixed by paying for it on both sides: a slightly taller panel and a slightly smaller icon. The
 * panel is bottom-anchored and grows UPWARD over the game view, so this is a deliberate trade —
 * a looting/barter session is modal anyway. Measured on the top screen (1920×1025 px app area at
 * density 2.30625 = 832.6 × 444.4 dp): panel 292 → 329dp, cell ~65 → ~76dp, against ~71dp needed.
 *
 * SHELF keeps the original 0.675 fraction — it is a different layout and is out of scope.
 */
private const val SPLIT_PANEL_HEIGHT_FRACTION = 0.76f   // was 0.675 (Classic grids only)
private val SPLIT_CELL_ICON = 44.dp                     // was 48

// Each split-overlay column is its own boxed panel (dark fill, subtle border, rounded, padded);
// the gap between the two boxes provides the visual separation (no divider line).
private val SplitBoxBg = Color(0xFF1A1410)
/**
 * Panel box for a SPLIT loot/barter column. Honours [LocalPanelOpacity] exactly like [mwPanel] —
 * these columns are the top screen's main DS panels, and they do NOT go through `mwPanel()` (they
 * have their own radius/padding and a dimmer fill), which is why they need the alpha applied here
 * too. Border stays opaque so the column bounds survive a fully-transparent fill.
 *
 * Also used by ShelfDualPanel, which renders on BOTH screens — harmless, because the local
 * defaults to 1f anywhere outside a top-screen overlay window.
 */
@Composable
private fun Modifier.splitColumnBox(): Modifier = this
    .adaptiveDimTint()
    .clip(RoundedCornerShape(6.dp))
    .background(SplitBoxBg.copy(alpha = LocalPanelOpacity.current))
    .border(1.dp, BronzeDark, RoundedCornerShape(6.dp))
    .padding(8.dp)

/**
 * SPLIT-mode bottom-screen looting controls: just the terminal action buttons (Take All /
 * Dispose / Close), centred vertically in a narrow panel. The item grids live on the top
 * screen ([LootingTopOverlay]). All three actions END the session, so no optimistic item
 * state is needed here. Full-screen scrim (covers the tab bar — looting is modal); NO
 * tap-away dismiss.
 */
@Composable
private fun LootingControlsOnly(session: ContainerSession) {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(15f)
            .background(Color(0xCC0F0C08))
            .pointerInput(Unit) { detectTapGestures {} },
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth(0.5f)
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures {} }
                .padding(16.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            Text(
                session.containerName.ifBlank { "Container" },
                color = BronzeLight, fontSize = 14.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                maxLines = 1, overflow = TextOverflow.Ellipsis
            )
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            LootButton(
                label = "Take All", hint = "X", enabled = true,
                modifier = Modifier.fillMaxWidth()
            ) { CompanionActions.containerTakeAll() }
            if (session.isCorpse) {
                LootButton(
                    label = "Dispose of Corpse", hint = "Y", enabled = true,
                    modifier = Modifier.fillMaxWidth()
                ) { CompanionActions.containerDispose() }
            }
            LootButton(
                label = "Close", hint = "B", enabled = true,
                modifier = Modifier.fillMaxWidth()
            ) { CompanionActions.containerClose() }
        }
    }
}

/**
 * TOP-screen looting grids (Display 0). Hosted by [org.openmw.EngineActivity] in an
 * interactive WindowManager panel window while a container session is active AND Looting is
 * routed to SPLIT. Container items LEFT, player inventory RIGHT — both 3-row horizontally
 * scrolling icon grids. Tapping a cell takes/puts (a QuantitySelector prompt appears first
 * for stacks > 1); long-press opens the fuller menu.
 *
 * Reads its state straight from [GameStateRepository] (no params, like the conversation top
 * overlay). Optimistic local copies of both lists are mutated on each tap — the sim is paused
 * so engine re-exports can't refresh mid-session; the true GameState reconciles on close.
 */
@Composable
fun LootingTopOverlay() {
    val sessionState by GameStateRepository.containerSession.collectAsState()
    val state by GameStateRepository.state.collectAsState()
    val session = sessionState ?: return
    val playerName = rememberPlayerName()

    // Optimistic lists — remember WITHOUT a key so they init once on enter and are NOT
    // re-synced from later (frame-starved) session emissions, matching the bottom overlay.
    // The window is removed on session-null (EngineActivity), so close→reopen re-inits.
    var containerItems by remember { mutableStateOf(session.items) }
    var playerItems by remember { mutableStateOf(state.inventory) }

    // Gold recomputed from the optimistic list so it updates live as you loot coins (matches the
    // bottom overlay).
    val playerGold = playerItems.firstOrNull { it.id.equals("gold_001", ignoreCase = true) }?.count ?: 0
    // Optimistic encumbrance: anchor on the real value snapshotted at open, then add/subtract moved
    // item weight per take/put/takeAll (mirrors the bottom overlay). Reconciles exactly on close.
    val baseEncumbrance = remember { state.encumbrance }
    var encDelta by remember { mutableStateOf(0f) }
    val liveEncumbrance = Dynamic(baseEncumbrance.current + encDelta, baseEncumbrance.max)

    val wornIds = remember(state.equipment) { state.equipment.values.toSet() }
    fun isWorn(item: InventoryItem): Boolean =
        if (item.stackId.isNotEmpty()) wornIds.contains(item.stackId) else wornIds.contains(item.id)

    // Local quantity picker (kept on the TOP screen, not the global bottom-screen holder).
    // [initial] is supplied by the caller (which knows take-vs-put); see lootQtyInitial.
    var qtyReq by remember { mutableStateOf<QuantityRequest?>(null) }
    val requestQty: (String, Int, String, Int, (Int) -> Unit) -> Unit = { name, count, label, initial, action ->
        if (count > 1) qtyReq = QuantityRequest(name, count, label, initial) { n -> qtyReq = null; action(n) }
        else action(1)
    }

    // Container-put restriction banner (organic / capacity / weight — vanilla parity), rendered on
    // THIS top screen. Mirrors the bottom overlay.
    val putMsgs by GameStateRepository.putMessages.collectAsState()
    val putBlocked by GameStateRepository.putBlocked.collectAsState()
    var restrictionBanner by remember { mutableStateOf<String?>(null) }
    var bannerNonce by remember { mutableStateOf(0) }
    LaunchedEffect(bannerNonce) { if (restrictionBanner != null) { delay(2200); restrictionBanner = null } }
    LaunchedEffect(putBlocked) {
        putBlocked?.let { restrictionBanner = it.first; bannerNonce++; GameStateRepository.clearPutBlocked() }
    }

    fun take(item: InventoryItem, n: Int) {
        val (c, p) = moveOptimistic(containerItems, playerItems, item, n)
        containerItems = c; playerItems = p
        encDelta += item.weight * n
        CompanionActions.containerTake(item.stackId.ifEmpty { item.id }, n)
    }
    fun put(item: InventoryItem, n: Int) {
        // Vanilla container-put gate (organic / capacity / weight): block + banner, no move/command.
        val containerWeight = containerItems.sumOf { it.weight.toDouble() * it.count }.toFloat()
        containerPutBlock(session, containerWeight, item, n, putMsgs)?.let {
            restrictionBanner = it; bannerNonce++; return
        }
        val (p, c) = moveOptimistic(playerItems, containerItems, item, n)
        playerItems = p; containerItems = c
        encDelta -= item.weight * n
        CompanionActions.containerPut(item.stackId.ifEmpty { item.id }, n)
    }
    fun takeAll() {
        encDelta += containerItems.sumOf { (it.weight * it.count).toDouble() }.toFloat()
        playerItems = containerItems.fold(playerItems) { acc, it ->
            moveOptimistic(listOf(it), acc, it, it.count).second
        }
        containerItems = emptyList()
        CompanionActions.containerTakeAll()
    }

    // Per-side category filter (an INV_CATEGORIES label; null = All), matching the barter grids.
    var playerCat by remember { mutableStateOf<String?>(null) }
    var containerCat by remember { mutableStateOf<String?>(null) }

    // Per-column sort state (Default / Weight / Value) — the same InvSortState + chips as the
    // BOTTOM lists and the inventory tab. One per side because the chips live in each column's own
    // header; see the `sort` param on LootGridColumn.
    val playerSort = rememberInvSortState()
    val containerSort = rememberInvSortState()

    // The VISIBLE (category-filtered + sorted) lists — shared by the controller focus index; each
    // column re-derives the same via lootVisible for its display, so it is handed the SAME sort
    // state (a different one there would desync the grid from the focus cursor).
    val playerVisible = remember(playerItems, playerCat, playerSort.mode, playerSort.descending) {
        lootVisible(playerItems, playerCat, playerSort.mode, playerSort.descending) { isWorn(it) }
    }
    val containerVisible = remember(containerItems, containerCat, containerSort.mode, containerSort.descending) {
        lootVisible(containerItems, containerCat, containerSort.mode, containerSort.descending)
    }
    // Controller focus (SPLIT = two 3-row icon grids → rows = 3). X/Y fire here too even though
    // the Take All / Dispose buttons live on the bottom controls window — they're plain commands.
    // Classic mode only — the shelf layout runs its own nav (ShelfDualPanel).
    val shelfMode = UiPreferences.inventoryLayoutFlow().collectAsState().value == InventoryLayout.SHELF
    val focus = if (shelfMode) null else rememberLootNavFocus(
        playerSorted = playerVisible,
        containerSorted = containerVisible,
        rows = 3,
        isCorpse = session.isCorpse,
        isPickpocket = session.isPickpocket,
        requestQty = requestQty,
        onPut = { it, n -> put(it, n) },
        onTake = { it, n -> take(it, n) },
        onTakeAll = { takeAll() },
        onDispose = { CompanionActions.containerDispose() },
        onCycleCategory = { side, dir ->
            if (side == 0) playerCat = cycleLootCat(playerItems, playerCat, dir)
            else containerCat = cycleLootCat(containerItems, containerCat, dir)
        },
        // SPLIT has one sort PER COLUMN, so L3 targets the focused one — the same rule L1/R1
        // already follow for the category filter.
        onCycleSort = { side -> (if (side == 0) playerSort else containerSort).cycle(InvSort.entries) },
    )

    // Bug 1: keep a focus-linked info popup (rendered on THIS top screen) on the focused item when a
    // take/put shrinks the list under the fixed focus index. Classic nav only (shelf runs its own).
    if (!shelfMode) {
        val focusedItem = focus?.let { (if (it.side == 0) playerVisible else containerVisible).getOrNull(it.index) }
        FollowFocusedInfoPopup(focusedItem?.let { InfoTarget(it.id, it.displayName(), it.enchant) }, onTop = true)
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .pointerInput(Unit) { detectTapGestures {} }
            // Anchor the panel to the BOTTOM of the top screen, 12dp up.
            .padding(bottom = 12.dp),
        contentAlignment = Alignment.BottomCenter
    ) {
        // Two separate boxed columns (player | container). Shelf mode replaces the two icon grids
        // with the grouped-shelf dual panel; Classic keeps the tab+grid columns with an 8dp gap.
        if (shelfMode) {
            ShelfDualPanel(
                playerHeaderLeft = playerName,
                playerHeaderRight = goldWeightHeaderRight(playerGold, liveEncumbrance),
                playerShelfItems = playerItems.filter { !isWorn(it) }.map { itm ->
                    itm.toShelfItem(worn = false) {
                        requestQty(itm.displayName(), itm.count, "Put", itm.count) { n -> put(itm, n) }
                    }
                },
                playerEquipped = playerItems.filter { isWorn(it) }.map { itm ->
                    itm.toShelfItem(worn = true) {
                        requestQty(itm.displayName(), itm.count, "Put", itm.count) { n -> put(itm, n) }
                    }
                },
                otherHeaderLeft = session.containerName.ifBlank { "Container" },
                otherHeaderRight = AnnotatedString("${containerItems.size} items"),
                otherItems = containerItems.map { itm ->
                    itm.toShelfItem(worn = false) {
                        requestQty(
                            itm.displayName(), itm.count, "Take",
                            lootQtyInitial(itm.count, isTake = true, isPickpocket = session.isPickpocket)
                        ) { n -> take(itm, n) }
                    }
                },
                otherEmptyText = if (session.isPickpocket) "Nothing you can lift" else "Empty",
                infoOnTop = true,
                onAction1 = { takeAll() },
                onAction2 = { if (session.isCorpse) CompanionActions.containerDispose() },
                modifier = Modifier.fillMaxWidth(0.96f).fillMaxHeight(0.675f)
            )
        } else Row(
            modifier = Modifier
                .fillMaxWidth(0.96f)
                // Taller than Shelf's 0.675 so the 3-row grid's cells fit a two-line name.
                .fillMaxHeight(SPLIT_PANEL_HEIGHT_FRACTION)
        ) {
            // LEFT: player.
            LootGridColumn(
                header = playerPackHeader(liveEncumbrance),
                items = playerItems,
                isPlayerSide = true,
                isWorn = { isWorn(it) },
                emptyText = "Empty",
                selectedCategory = playerCat,
                onSelectCategory = { playerCat = it },
                onTransfer = { it, n -> put(it, n) },
                onRequestQty = requestQty,
                focusedIndex = if (focus!!.side == 0) focus.index else -1,
                sort = playerSort,
                modifier = Modifier.weight(1f).fillMaxHeight().splitColumnBox()
            )
            Spacer(Modifier.width(LOOT_SPLIT_COLUMN_GAP))
            // RIGHT: container.
            LootGridColumn(
                header = AnnotatedString(session.containerName.ifBlank { "Container" }),
                items = containerItems,
                isPlayerSide = false,
                isWorn = { false },
                emptyText = if (session.isPickpocket) "Nothing you can lift" else "Empty",
                selectedCategory = containerCat,
                onSelectCategory = { containerCat = it },
                onTransfer = { it, n -> take(it, n) },
                onRequestQty = requestQty,
                isPickpocket = session.isPickpocket,
                focusedIndex = if (focus!!.side == 1) focus.index else -1,
                sort = containerSort,
                modifier = Modifier.weight(1f).fillMaxHeight().splitColumnBox()
            )
        }

        // Local dropdown-dismiss scrim (this window has its own composition — can't lean on
        // the bottom-screen global scrim). Below the DropdownMenu popup, above the grids.
        if (DropdownState.anyOpen) {
            Box(
                Modifier
                    .fillMaxSize()
                    .pointerInput(Unit) { detectTapGestures { DropdownState.closeAll() } }
            )
        }

        // Local quantity picker (fills the window at zIndex 20f with its own scrim).
        qtyReq?.let { req ->
            QuantitySelector(
                name = req.name,
                max = req.max,
                confirmLabel = req.confirmLabel,
                initial = req.initial,
                showControllerHint = req.showControllerHint,
                onConfirm = req.onConfirm,
                onCancel = { qtyReq = null }
            )
        }

        // Item info popup on the TOP screen (SPLIT looting): anchored to the grid cell in THIS
        // window's coords. Only when the trigger came from here (onTopScreen).
        if (ItemInfoPopupState.isOpen && ItemInfoPopupState.onTopScreen) {
            ItemInfoPopupHost()
        }

        // Vanilla container-put restriction feedback (organic / full / too heavy).
        RestrictionBanner(restrictionBanner)
    }
}

/** One side of the SPLIT looting grids — header, per-side category tabs, 3-row horizontally-
 *  scrolling icon grid. [items] is the FULL column; it's filtered+sorted here via [lootVisible]
 *  (the same the parent computes for the controller focus index). [focusedIndex] highlights that
 *  cell (-1 = this side isn't focused) and keeps it on-screen. Mirrors [BarterGridColumn]. */
@Composable
private fun LootGridColumn(
    header: AnnotatedString,
    items: List<InventoryItem>,
    isPlayerSide: Boolean,
    isWorn: (InventoryItem) -> Boolean,
    emptyText: String,
    selectedCategory: String?,
    onSelectCategory: (String?) -> Unit,
    onTransfer: (InventoryItem, Int) -> Unit,
    onRequestQty: (String, Int, String, Int, (Int) -> Unit) -> Unit,
    /** Living NPC — a Take here opens the quantity picker at 1, not the stack (lootQtyInitial). */
    isPickpocket: Boolean = false,
    focusedIndex: Int = -1,
    /** This column's sort. PER-COLUMN, not shared between the two sides: the chips sit in this
     *  column's own header next to its own category tabs, so their scope reads as local — and
     *  sorting the container by value while your own pack stays in its usual order is the useful
     *  case. Owned by the parent so the SAME state also feeds the controller focus list. */
    sort: InvSortState,
    modifier: Modifier = Modifier
) {
    Column(modifier) {
        // Header + this column's sort chips on one line. The chips are `compact` because every dp
        // spent here comes out of the item grid below (see SPLIT_PANEL_HEIGHT_FRACTION).
        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
            Text(
                header,
                color = BronzeLight, fontSize = 14.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                maxLines = 1, overflow = TextOverflow.Ellipsis,
                modifier = Modifier.weight(1f)
            )
            Spacer(Modifier.width(6.dp))
            SortChipRow(sort, compact = true)
        }
        Spacer(Modifier.height(4.dp))
        val presentCats = remember(items) { items.map { it.category }.toSet() }
        val tabs = remember(presentCats) { INV_CATEGORIES.filter { grp -> grp.cats.any { it in presentCats } } }
        CategoryTabStrip(
            tabs = tabs,
            selected = selectedCategory,
            label = { it.label },
            key = { it.label },          // looting filters by the INV_CATEGORIES label
            onSelect = onSelectCategory
        )
        Spacer(Modifier.height(4.dp))
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.5f)))
        Spacer(Modifier.height(6.dp))

        // Same filter+sort the controller focus index is computed against (lootVisible) — including the
        // player-side worn-first float, so cell index maps 1:1 to the parent's focus index. The sort
        // MUST be the same state the parent fed its focus list, or the two silently desync.
        val visible = remember(items, selectedCategory, sort.mode, sort.descending) {
            lootVisible(items, selectedCategory, sort.mode, sort.descending) { isPlayerSide && isWorn(it) }
        }
        if (visible.isEmpty()) {
            Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                Text(emptyText, color = BoneDim, fontSize = 12.sp, fontFamily = MwBody)
            }
        } else {
            val gridState = rememberLazyGridState()
            // Windowed, NOT pinned-to-the-left-edge: only scrolls when the focused cell would fall
            // outside the viewport (see WindowedFocusScroll).
            WindowedFocusScroll(gridState, focusedIndex, visible.size, visible)
            // Right stick left/right scrolls this horizontal grid while it's the focused side.
            ScrollByNav(gridState, active = focusedIndex >= 0, horizontal = true)
            LazyHorizontalGrid(
                // 3 rows. Column-major fill, so item index i sits at grid row i%3, grid column i/3
                // — MUST match the focus math in rememberLootNavFocus (rows = 3).
                state = gridState,
                rows = GridCells.Fixed(3),
                modifier = Modifier.fillMaxWidth().weight(1f),
                horizontalArrangement = Arrangement.spacedBy(4.dp),
                verticalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                gridItemsIndexed(visible) { i, item ->
                    LootGridCell(
                        item = item,
                        isPlayerSide = isPlayerSide,
                        worn = isPlayerSide && isWorn(item),
                        iconBitmap = rememberItemIcon(item.icon),
                        focused = i == focusedIndex,
                        isPickpocket = isPickpocket,
                        onTransfer = onTransfer,
                        onRequestQty = onRequestQty
                    )
                }
            }
            HorizontalGridScrollbar(gridState, Modifier.padding(top = 4.dp))
        }
    }
}

/**
 * One icon cell in the SPLIT looting grids. Tap = transfer (take/put); long-press = the fuller
 * menu (Take/Put, Info, and Favourite on the player side). A worn item gets a bright bronze
 * border highlight. Stacks > 1 route the transfer through the quantity picker first.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun LootGridCell(
    item: InventoryItem,
    isPlayerSide: Boolean,
    worn: Boolean,
    iconBitmap: ImageBitmap? = null,
    focused: Boolean = false,
    isPickpocket: Boolean = false,
    onTransfer: (InventoryItem, Int) -> Unit,
    onRequestQty: (String, Int, String, Int, (Int) -> Unit) -> Unit
) {
    val context = LocalContext.current
    var menuOpen by remember { mutableStateOf(false) }
    LaunchedEffect(DropdownState.closeRequest) {
        if (DropdownState.closeRequest > 0) menuOpen = false
    }
    val label = item.displayName()
    val confirmLabel = if (isPlayerSide) "Put" else "Take"
    // Opens on the whole stack except a pickpocket Take — see lootQtyInitial.
    fun transfer() {
        onRequestQty(
            label, item.count, confirmLabel,
            lootQtyInitial(item.count, isTake = !isPlayerSide, isPickpocket = isPickpocket)
        ) { n -> onTransfer(item, n) }
    }

    Box(modifier = Modifier.onGloballyPositioned { ItemInfoPopupState.reportAnchor(item.id, it.boundsInRoot()) }) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            modifier = Modifier
                .width(54.dp)
                // Controller focus: a bronze ring + faint fill around the WHOLE cell (icon + label).
                // Worn is an inner-icon BronzeLight border, so this outer ring + fill is distinct.
                .then(
                    if (focused) Modifier
                        .clip(RoundedCornerShape(4.dp))
                        .background(BronzeLight.copy(alpha = 0.15f))
                        .border(2.dp, BronzeLight, RoundedCornerShape(4.dp))
                    else Modifier
                )
                .combinedClickable(
                    onClick = { transfer() },
                    onLongClick = { menuOpen = true; DropdownState.open() }
                )
                .padding(2.dp)
        ) {
            // Icon box — bronze highlight border when worn.
            Box(
                modifier = Modifier
                    .size(SPLIT_CELL_ICON)
                    .clip(RoundedCornerShape(3.dp))
                    .background(SlotBg)
                    .border(
                        BorderStroke(if (worn) 2.dp else 1.dp, if (worn) BronzeLight else BronzeDark),
                        RoundedCornerShape(3.dp)
                    )
            ) {
                EnchantBackdrop(item.enchant != null)
                if (iconBitmap != null) {
                    Image(
                        bitmap = iconBitmap,
                        contentDescription = null,
                        contentScale = ContentScale.Fit,
                        modifier = Modifier.fillMaxSize().padding(3.dp)
                    )
                }
                // Count badge (bottom-right).
                if (item.count > 1) {
                    Text(
                        "×${item.count}",
                        color = BoneBright, fontSize = 9.sp,
                        fontFamily = MwData, fontWeight = FontWeight.Bold,
                        modifier = Modifier
                            .align(Alignment.BottomEnd)
                            .background(Color(0xCC0E0B07))
                            .padding(horizontal = 2.dp)
                    )
                }
            }
            Spacer(Modifier.height(2.dp))
            Text(
                label,
                color = if (worn) BoneBright else BoneMuted,
                fontSize = 8.sp, fontFamily = MwBody,
                textAlign = TextAlign.Center,
                maxLines = 2, overflow = TextOverflow.Ellipsis,
                lineHeight = 9.sp,
                modifier = Modifier.width(54.dp)
            )
        }

        CompanionDropdownMenu(
            expanded = menuOpen,
            onDismissRequest = { menuOpen = false; DropdownState.closeAll() }
        ) {
            Text(
                label,
                color = BronzeLight, fontSize = 12.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp)
            )
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
            val menuItemColors = MenuDefaults.itemColors(textColor = Bone)
            DropdownMenuItem(
                text = { Text(if (isPlayerSide) "Put" else "Take", fontFamily = MwBody, fontSize = 13.sp) },
                onClick = { menuOpen = false; DropdownState.closeAll(); transfer() },
                colors = menuItemColors
            )
            DropdownMenuItem(
                text = { Text("Info", fontFamily = MwBody, fontSize = 13.sp) },
                onClick = { menuOpen = false; DropdownState.closeAll(); ItemInfoPopupState.open(item.id, item.name, item.enchant, onTop = true) },
                colors = menuItemColors
            )
            if (isPlayerSide) {
                FavouriteMenuItems(
                    context = context,
                    isGear = true,
                    itemId = item.id,
                    makeSlot = { FavSlot(item.id, label) },
                    onDone = { menuOpen = false; DropdownState.closeAll() }
                )
            }
        }
    }
}

private fun lootSubline(item: InventoryItem): String {
    val parts = mutableListOf<String>()
    if (item.category.isNotBlank()) {
        parts.add(item.category.replaceFirstChar { it.uppercase() })
    }
    if (item.count > 1) parts.add("x${item.count}")
    item.cond?.let { parts.add("${(it.coerceIn(0f, 1f) * 100).toInt()}%") }
    return parts.joinToString(" · ")
}

/** A bottom action button in the looting overlay (Take All / Dispose / Close),
 *  taller than a list row, with a controller-binding hint (display only). */
@Composable
private fun LootButton(
    label: String,
    hint: String,
    enabled: Boolean,
    modifier: Modifier = Modifier,
    onClick: () -> Unit
) {
    Box(
        modifier = modifier
            .height(35.dp)
            .clip(RoundedCornerShape(2.dp))
            .background(if (enabled) SlotWorn else SlotBg)
            .border(1.dp, if (enabled) BronzeLight else BronzeDark, RoundedCornerShape(2.dp))
            .clickable(enabled = enabled, onClick = onClick),
        contentAlignment = Alignment.Center
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(
                label,
                color = if (enabled) BronzeLight else BoneDim, fontSize = 12.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 0.8.sp,
                maxLines = 1, overflow = TextOverflow.Ellipsis
            )
            Spacer(Modifier.width(6.dp))
            Text(
                "[$hint]",
                color = if (enabled) BoneDim else BoneDim.copy(alpha = 0.5f),
                fontSize = 10.sp, fontFamily = MwData
            )
        }
    }
}

/* ---- Reusable quantity picker ---- */

// A standalone, reusable "how many?" overlay. Kept decoupled from inventory/
// dropping so it can be dropped into looting (transfer N corpse→player) and
// bartering (transfer N player↔vendor) later without changes: it only knows a
// display name, a max, and confirm/cancel callbacks.
//
// In-window overlay (NOT a Compose Dialog): the companion UI lives inside a
// Presentation on a secondary display, where a Dialog throws "Window type
// mismatch" — see ItemInfoOverlay. Tapping the scrim cancels; taps inside the
// panel are swallowed. +/- step by 1; ±10 buttons appear for larger stacks so
// big quantities aren't a hundred taps. Quantity is always clamped to [1, max].
@Composable
private fun QuantitySelector(
    name: String,
    max: Int,
    confirmLabel: String = "Confirm",
    // Quantity the picker opens on, clamped to [1, safeMax]. Defaults to the whole stack: taking /
    // putting / selling the lot is the common intent, so Confirm is a single tap. Callers that want
    // a cautious start pass their own value — today that is the pickpocket Take (1), whose catch
    // chance scales with the stack lifted; see lootQtyInitial.
    initial: Int = max,
    // Show the "[Y]" hint next to MAX. Only true where the controller is actually routed to this
    // overlay — i.e. a DS SESSION overlay (loot/barter/…), which is what flips
    // setCompanionNavActive(true) in EngineActivity so native re-emits input as COMPANION_NAV_*.
    // The plain companion TABS (inventory Drop, favourites-slot Drop) are not sessions, so no
    // NavEvent ever arrives there and the hint would be advertising a dead button. MAX itself stays
    // tappable either way.
    showControllerHint: Boolean = true,
    onConfirm: (Int) -> Unit,
    onCancel: () -> Unit
) {
    val safeMax = max.coerceAtLeast(1)
    var qty by remember(name, safeMax, initial) { mutableStateOf(initial.coerceIn(1, safeMax)) }
    fun set(v: Int) { qty = v.coerceIn(1, safeMax) }
    // Single "jump to the whole stack" action, shared by the on-screen MAX button and the Y button.
    fun setMax() { set(safeMax) }
    val showTens = safeMax > 10

    // Controller: while this selector is up it OWNS nav — mark it open so the grid/slider collectors
    // underneath yield, and drive the quantity from the D-pad. D-pad up/down = ±10 (clamped: a single
    // press lands on min(qty+10, max) / max(qty-10, 1)), left/right = ±1; Y = Max (whole stack);
    // A confirms; B cancels JUST the selector (native intercepts B → COMPANION_NAV_CANCEL while
    // companionQtySelectorOpen, instead of closing the whole overlay). Also pushes that open flag to
    // native so the B interception knows to fire; the counter guards against brief enter/exit overlap.
    DisposableEffect(Unit) {
        ModalNav.count++
        CompanionActions.setModalCancelOpen(true)
        onDispose {
            ModalNav.count--
            if (ModalNav.count == 0) CompanionActions.setModalCancelOpen(false)
        }
    }
    LaunchedEffect(name, safeMax) {
        var lastSeq = GameStateRepository.navEvent.value?.seq ?: -1L
        GameStateRepository.navEvent.collect { ev ->
            if (ev == null || ev.seq <= lastSeq) return@collect
            lastSeq = ev.seq
            when (ev) {
                is NavEvent.Up -> set(qty + 10)     // clamps to safeMax → a single press reaches max
                is NavEvent.Down -> set(qty - 10)   // clamps to the floor of 1
                is NavEvent.Right -> set(qty + 1)
                is NavEvent.Left -> set(qty - 1)
                is NavEvent.Action2 -> setMax()     // Y → whole stack (same as the MAX button)
                is NavEvent.Confirm -> onConfirm(qty)
                is NavEvent.Cancel -> onCancel()
                else -> Unit
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(20f)
            .background(Color(0xB3000000))
            .pointerInput(Unit) { detectTapGestures(onTap = { onCancel() }) },
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .width(320.dp)
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures(onTap = {}) }
                .padding(18.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                name,
                color = BronzeLight,
                fontSize = 16.sp,
                fontFamily = MwDisplay,
                fontWeight = FontWeight.Bold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            Spacer(Modifier.height(16.dp))

            // Stepper row: [-10] [-]  qty  [+] [+10]
            Row(verticalAlignment = Alignment.CenterVertically) {
                if (showTens) {
                    QtyButton("−10", enabled = qty > 1) { set(qty - 10) }
                    Spacer(Modifier.width(6.dp))
                }
                QtyButton("−", enabled = qty > 1) { set(qty - 1) }
                Text(
                    qty.toString(),
                    color = BoneBright,
                    fontSize = 34.sp,
                    fontFamily = MwData,
                    fontWeight = FontWeight.Bold,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.width(84.dp)
                )
                QtyButton("+", enabled = qty < safeMax) { set(qty + 1) }
                if (showTens) {
                    Spacer(Modifier.width(6.dp))
                    QtyButton("+10", enabled = qty < safeMax) { set(qty + 10) }
                }
            }
            Spacer(Modifier.height(6.dp))
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text("of $safeMax", color = BoneDim, fontSize = 12.sp, fontFamily = MwBody)
                Spacer(Modifier.width(10.dp))
                // Quick "Max" set — cheaper than tapping +10 up a big stack. Stays TAPPABLE in every
                // context; only the [Y] controller hint is conditional (see showControllerHint).
                Row(
                    modifier = Modifier
                        .clip(RoundedCornerShape(3.dp))
                        .clickable { setMax() }
                        .padding(horizontal = 6.dp, vertical = 2.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        "MAX",
                        color = if (qty < safeMax) BronzeLight else BoneDim,
                        fontSize = 12.sp,
                        fontFamily = MwDisplay,
                        fontWeight = FontWeight.Bold,
                        letterSpacing = 1.sp
                    )
                    // The [Y] hint follows the [X]/[B] hint style used by the overlay buttons.
                    if (showControllerHint) {
                        Spacer(Modifier.width(5.dp))
                        Text(
                            "[Y]",
                            color = if (qty < safeMax) BoneDim else BoneDim.copy(alpha = 0.5f),
                            fontSize = 10.sp, fontFamily = MwData
                        )
                    }
                }
            }

            Spacer(Modifier.height(18.dp))
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                QtyActionButton("Cancel", Modifier.weight(1f), primary = false) { onCancel() }
                QtyActionButton(confirmLabel, Modifier.weight(1f), primary = true) { onConfirm(qty) }
            }
        }
    }
}

// Square +/- stepper button used by QuantitySelector and the SPLIT barter gold row.
// [size] scales the box and its glyph together; the ratios reproduce the original 48dp/22sp
// (single glyph) and 48dp/15sp ("−10"/"+10") exactly, so the picker is visually unchanged.
@Composable
private fun QtyButton(label: String, enabled: Boolean, size: Dp = 48.dp, onClick: () -> Unit) {
    Box(
        modifier = Modifier
            .size(size)
            .clip(RoundedCornerShape(4.dp))
            .background(if (enabled) SlotWorn else SlotBg)
            .border(1.dp, if (enabled) Bronze else BronzeDark, RoundedCornerShape(4.dp))
            .clickable(enabled = enabled) { onClick() },
        contentAlignment = Alignment.Center
    ) {
        Text(
            label,
            color = if (enabled) BronzeLight else BoneDim,
            fontSize = (size.value * if (label.length > 1) 0.3125f else 0.4583f).sp,
            fontFamily = MwData,
            fontWeight = FontWeight.Bold
        )
    }
}

// Confirm / Cancel button used by QuantitySelector.
@Composable
private fun QtyActionButton(
    label: String,
    modifier: Modifier = Modifier,
    primary: Boolean,
    onClick: () -> Unit
) {
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(3.dp))
            .background(if (primary) SlotWorn else BronzeDark.copy(alpha = 0.2f))
            .border(1.dp, if (primary) Bronze else BronzeDark, RoundedCornerShape(3.dp))
            .clickable { onClick() }
            .padding(vertical = 11.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            label,
            color = if (primary) BronzeLight else Bone,
            fontSize = 14.sp,
            fontFamily = MwDisplay,
            fontWeight = FontWeight.Bold,
            letterSpacing = 1.sp
        )
    }
}

/* ---- On-screen text-entry keyboard (bottom screen) ---- */

// Custom keyboard rows: a letters page and a numbers/symbols page. See TextInputOverlay for why
// this is a hand-drawn Compose keyboard rather than the Android IME.
private val KB_LETTERS = listOf(
    listOf("q", "w", "e", "r", "t", "y", "u", "i", "o", "p"),
    listOf("a", "s", "d", "f", "g", "h", "j", "k", "l"),
    listOf("z", "x", "c", "v", "b", "n", "m"),
)
private val KB_SYMBOLS = listOf(
    listOf("1", "2", "3", "4", "5", "6", "7", "8", "9", "0"),
    listOf("-", "/", ":", ";", "(", ")", "&", "@", "'", "\""),
    listOf(".", ",", "?", "!", "+", "_"),
)

// Letters page for PROSE entry (manual journal notes). An apostrophe is appended to the home row —
// which brings it to ten keys, the same as the top row, so nothing is narrowed — and comma/period
// flank the space bar below, exactly where a phone keyboard puts them. Writing a sentence should
// not require a trip to the symbols page for every contraction and full stop. Deliberately NOT
// applied to the native-triggered instance, where the field is a character/class/save NAME.
private val KB_LETTERS_PROSE = listOf(
    KB_LETTERS[0],
    KB_LETTERS[1] + "'",
    KB_LETTERS[2],
)

private fun shiftLabel(k: String, shift: Boolean): String = if (shift) k.uppercase() else k

/**
 * On-screen text-entry overlay for character name / class name / save name. Driven by
 * COMPANION_TEXT_INPUT_OPEN/_CLOSED (native, when a MyGUI EditBox gains/loses key focus) and shown
 * whenever [GameStateRepository.textInputRequest] is non-null. A CUSTOM Compose keyboard, deliberately
 * NOT the Android OS keyboard: the IME is a focusable window that moves Android's input-focused
 * display to the bottom screen, after which controller input goes to the bottom-screen launcher and
 * cannot be reliably returned to the game (proven across several attempts — moveTaskToFront, focus
 * nudges, etc.). This overlay is only TOUCH-interactive (no key focus), so the game keeps controller
 * focus the whole time, and the keys always render on the bottom panel regardless of the user's IME
 * pinning. [onConfirm] fires on Enter with the full text → CMPTEXT:set, which fills the field and
 * injects Return to accept/advance the dialog. Auto-dismisses when the request clears (commit, or the
 * top field losing focus). In-window overlay, NOT a Dialog (Dialog crashes on the Presentation).
 */
@Composable
private fun TextInputOverlay(
    initialText: String,
    onConfirm: (String) -> Unit,
    // --- Everything below is for the SECOND call site (manual journal entries). Every default
    // reproduces the original native-triggered behaviour exactly, so that path is untouched. ---
    title: String = "ENTER TEXT",
    /** Long-form entry: a taller scrolling field, prose sizing, and the punctuation letters page. */
    prose: Boolean = false,
    /**
     * Non-null makes the overlay cancellable — a Cancel button appears in the header and a tap
     * outside the card dismisses. Null keeps the original behaviour of swallowing outside taps with
     * no escape, which is correct there: some in-game prompts genuinely cannot be dismissed.
     */
    onCancel: (() -> Unit)? = null,
    /** Called on every keystroke. Backs the top-screen live preview; null for the native path. */
    onTextChange: ((String) -> Unit)? = null
) {
    var text by remember(initialText) { mutableStateOf(initialText) }
    // One-shot shift: capitalises the next letter then resets. Starts on for an empty field so names
    // (and sentences) begin with a capital.
    var shift by remember(initialText) { mutableStateOf(initialText.isEmpty()) }
    var symbols by remember(initialText) { mutableStateOf(false) }

    // Single choke point so the preview can never drift from the field — every mutation below goes
    // through this rather than assigning `text` directly.
    val setText: (String) -> Unit = { next ->
        text = next
        onTextChange?.invoke(next)
    }
    val typeKey: (String) -> Unit = { k ->
        setText(text + shiftLabel(k, shift))
        if (shift) shift = false
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(22f)
            .background(Color(0xCC0B0906))
            // Outside taps: dismiss when cancellable, otherwise swallowed (see [onCancel]).
            .pointerInput(onCancel) {
                detectTapGestures(onTap = { onCancel?.invoke() })
            },
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth(0.97f)
                .mwPanel()
                // Always swallow taps on the card itself, so a stray tap between keys can't fall
                // through to the scrim and cancel a half-written note.
                .pointerInput(Unit) { detectTapGestures(onTap = {}) }
                .padding(horizontal = 12.dp, vertical = 12.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            // Header. Cancel sits here rather than in the key grid: the bottom row is already full
            // in prose mode, and a destructive action next to Enter invites mis-taps.
            Box(Modifier.fillMaxWidth(), contentAlignment = Alignment.Center) {
                Text(
                    title,
                    color = BronzeLight,
                    fontSize = 14.sp,
                    fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold,
                    letterSpacing = 2.sp
                )
                if (onCancel != null) {
                    Text(
                        "Cancel",
                        color = BoneDim,
                        fontSize = 12.sp,
                        fontFamily = MwBody,
                        modifier = Modifier
                            .align(Alignment.CenterEnd)
                            .clickable { onCancel() }
                            .padding(horizontal = 6.dp, vertical = 2.dp)
                    )
                }
            }
            Spacer(Modifier.height(8.dp))
            // Read-only display of the current text (the keys edit [text]).
            val fieldScroll = rememberScrollState()
            // Keep the newest text in view as it grows past the field. Without this, prose entry
            // types off the bottom edge and the player is writing blind.
            LaunchedEffect(text) { if (prose) fieldScroll.animateScrollTo(fieldScroll.maxValue) }
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(4.dp))
                    .background(SlotBg)
                    .border(1.dp, Bronze, RoundedCornerShape(4.dp))
                    .then(
                        if (prose) Modifier.height(TEXT_INPUT_PROSE_FIELD_HEIGHT)
                                           .verticalScroll(fieldScroll)
                        else Modifier
                    )
                    .padding(horizontal = 12.dp, vertical = 10.dp)
            ) {
                Text(
                    text.ifEmpty { " " },
                    color = BoneBright,
                    // Prose wraps at journal-ish sizing; the name field keeps its original single
                    // large line.
                    fontSize = if (prose) 15.sp else 20.sp,
                    fontFamily = if (prose) MwBody else MwData,
                    lineHeight = if (prose) 20.sp else TextUnit.Unspecified,
                    maxLines = if (prose) Int.MAX_VALUE else 1
                )
            }
            Spacer(Modifier.height(10.dp))

            val letters = if (prose) KB_LETTERS_PROSE else KB_LETTERS
            val rows = if (symbols) KB_SYMBOLS else letters
            KbRow { rows[0].forEach { k -> KbKey(shiftLabel(k, shift)) { typeKey(k) } } }
            KbRow { rows[1].forEach { k -> KbKey(shiftLabel(k, shift)) { typeKey(k) } } }
            KbRow {
                if (symbols) {
                    Spacer(Modifier.weight(1.6f))
                } else {
                    KbKey("⇧", weight = 1.6f, active = shift) { shift = !shift }
                }
                rows[2].forEach { k -> KbKey(shiftLabel(k, shift)) { typeKey(k) } }
                KbKey("⌫", weight = 1.6f) { if (text.isNotEmpty()) setText(text.dropLast(1)) }
            }
            KbRow {
                KbKey(if (symbols) "ABC" else "123", weight = 1.6f) { symbols = !symbols }
                if (prose && !symbols) {
                    // Comma and period flank the space bar, as on a phone keyboard. Only on the
                    // letters page — the symbols page already carries both.
                    KbKey(",") { typeKey(",") }
                    KbKey("space", weight = 2.4f) { setText("$text ") }
                    KbKey(".") { typeKey(".") }
                } else {
                    KbKey("space", weight = 4.4f) { setText("$text ") }
                }
                KbKey("Enter", weight = 2.2f, primary = true) { onConfirm(text) }
            }
        }
    }
}

// Height of the prose field: roughly six lines at 20sp line height, which is as much as can be
// given to the field before the key grid starts to crowd on the 1240x1080 bottom panel.
private val TEXT_INPUT_PROSE_FIELD_HEIGHT = 120.dp

@Composable
private fun KbRow(content: @Composable RowScope.() -> Unit) {
    Row(modifier = Modifier.fillMaxWidth(), content = content)
}

@Composable
private fun RowScope.KbKey(
    label: String,
    weight: Float = 1f,
    primary: Boolean = false,
    active: Boolean = false,
    onClick: () -> Unit
) {
    // Every key — letters, shift, backspace, space, the 123 page flip and Enter — passes through
    // here, so hooking the sound at this one point covers the whole keyboard for BOTH call sites
    // (the native text-input prompt and the manual journal composer). Enter takes the heavier cue
    // because it commits rather than types; `primary` is already the flag that marks it out
    // visually, so the two stay in step.
    val keyCue = if (primary) UiSounds.Cue.TOGGLE else UiSounds.Cue.KEY
    val press: () -> Unit = { UiSounds.play(keyCue); onClick() }
    val highlight = primary || active
    Box(
        modifier = Modifier
            .weight(weight)
            .padding(2.dp)
            .height(48.dp)
            .clip(RoundedCornerShape(4.dp))
            .background(if (highlight) SlotWorn else SlotBg)
            .border(1.dp, if (highlight) Bronze else BronzeDark, RoundedCornerShape(4.dp))
            // [tapFlash], not a bare clickable: an on-screen keyboard is the one place where every
            // single tap needs its own visible acknowledgement, and Foundation's default press
            // indication is 30% BLACK over an already-dark key — see the tapFlash block comment.
            .tapFlash { press() },
        contentAlignment = Alignment.Center
    ) {
        Text(
            label,
            color = if (highlight) BronzeLight else Bone,
            fontSize = 17.sp,
            fontFamily = MwData
        )
    }
}

/* ---- Merchant-repair overlay (bottom screen) ---- */

// Condition-bar thresholds (spec): red ≤40%, amber 41–70%, green 71–99% (and 100%).
private val RepairCondRed = Color(0xFFE87070)
private val RepairCondAmber = Color(0xFFC8A040)
private val RepairCondGreen = Color(0xFF6AAA6A)

private fun repairCondColor(ratio: Float): Color = when {
    ratio <= 0.40f -> RepairCondRed
    ratio <= 0.70f -> RepairCondAmber
    else -> RepairCondGreen
}

/**
 * Bottom-screen merchant-repair overlay. Driven by COMPANION_REPAIR_* (native MerchantRepair
 * window), shown whenever [GameStateRepository.repairSession] is non-null and Repair is DS.
 * NOT a Compose Dialog (crashes on the Presentation display — see ItemInfoOverlay); an
 * in-window centred Box at zIndex 17f. No tap-outside dismiss — only the Cancel button
 * closes it (→ CMP:repair_cancel → the engine pops GM_MerchantRepair and emits
 * COMPANION_REPAIR_CLOSED). Each row taps to repair that item immediately; the engine
 * re-exports the (shorter) list + updated gold after every repair, so [session] just
 * refreshes in place (no optimistic local state needed — repair is one authoritative call).
 */
@Composable
private fun RepairOverlay(session: RepairSession) {
    // Bottom vs Split from the repair layout pref (Top pending → falls back to the bottom card).
    // Currently BOTTOM-only (no Split pill), so this is always the centred card.
    val splitMode = UiPreferences.repairLocationFlow().collectAsState().value == ScreenLocation.SPLIT
    val rowFontSize = if (splitMode) SPLIT_ROW_FONT_SIZE else 14.sp
    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(17f)
            .background(Color(0xCC0F0C08))
            // Swallow taps so nothing falls through to the tab underneath. NO dismiss.
            .pointerInput(Unit) { detectTapGestures {} },
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .then(if (splitMode) Modifier.splitDialoguePanel() else Modifier.fillMaxWidth(0.7f).fillMaxHeight(0.86f))
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures {} }
        ) {
            // ---- Title bar ----
            Text(
                "Repair: ${session.npcName.ifBlank { "Merchant" }}",
                color = BronzeLight, fontSize = 15.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                maxLines = 1, overflow = TextOverflow.Ellipsis,
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp)
            )
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))

            // ---- Item list ---- (D-pad up/down navigate, A repairs the focused one, X repairs all)
            val focusIndex = rememberListNavFocus(
                itemCount = session.items.size,
                onConfirm = { i ->
                    val it = session.items[i]
                    if (it.cost <= session.playerGold) CompanionActions.repairItem(it.sid)
                },
                onAction1 = { if (session.items.isNotEmpty()) CompanionActions.repairAll() },
            )
            val listState = rememberLazyListState()
            LaunchedEffect(focusIndex) {
                if (focusIndex in session.items.indices) listState.animateScrollToItem(focusIndex)
            }
            if (session.items.isEmpty()) {
                Box(Modifier.fillMaxWidth().weight(1f), contentAlignment = Alignment.Center) {
                    Text(
                        "Nothing needs repair", color = BoneDim,
                        fontSize = 13.sp, fontFamily = MwBody
                    )
                }
            } else {
                LazyColumn(state = listState, modifier = Modifier.fillMaxWidth().weight(1f)) {
                    itemsIndexed(session.items, key = { _, it -> it.sid }) { i, item ->
                        RepairRow(
                            item = item,
                            affordable = item.cost <= session.playerGold,
                            nameFontSize = rowFontSize,
                            focused = i == focusIndex,
                            onRepair = { CompanionActions.repairItem(item.sid) }
                        )
                        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
                    }
                }
            }

            // ---- Divider + bottom row ----
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Text(
                    "Gold: ${session.playerGold}", color = BronzeLight, fontSize = 13.sp,
                    fontFamily = MwData, modifier = Modifier.weight(1f)
                )
                // Repair All shows the total cost of ALL listed items; the engine repairs as
                // many as the player can afford (cheapest-affordable first). Disabled only
                // when there's nothing at all to repair.
                RepairButton(
                    label = "Repair All (${session.totalCost}g)",
                    color = ActionConfirm,
                    enabled = session.items.isNotEmpty()
                ) { CompanionActions.repairAll() }
                RepairButton(label = "Cancel", color = ActionCancel, enabled = true) {
                    CompanionActions.repairCancel()
                }
            }
        }
    }
}

/** One repair row: name (flex) + condition bar with "X/Y" + cost, tap to repair. Unaffordable
 *  rows are dimmed with a red cost and are not tappable (the engine ignores them anyway). */
@Composable
private fun RepairRow(
    item: RepairItem,
    affordable: Boolean,
    nameFontSize: TextUnit = 14.sp,
    focused: Boolean = false,
    onRepair: () -> Unit
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            // Controller focus: a bronze border + faint fill on the focused row.
            .then(
                if (focused) Modifier.background(BronzeLight.copy(alpha = 0.12f)).border(2.dp, BronzeLight)
                else Modifier
            )
            .then(if (affordable) Modifier.clickable { onRepair() } else Modifier)
            .padding(horizontal = 14.dp, vertical = 10.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            item.name,
            color = when {
                !affordable -> BoneDim
                focused -> BoneBright
                else -> Bone
            },
            fontSize = nameFontSize, fontFamily = MwBody,
            maxLines = 1, overflow = TextOverflow.Ellipsis,
            modifier = Modifier.weight(1f)
        )
        // Condition column: a thin bar + "X/Y" text.
        Column(
            modifier = Modifier.width(96.dp).padding(horizontal = 10.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(6.dp)
                    .clip(RoundedCornerShape(2.dp))
                    .background(Color(0xFF0E0B07))
                    .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
            ) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth(item.ratio)
                        .fillMaxHeight()
                        .background(repairCondColor(item.ratio))
                )
            }
            Spacer(Modifier.height(2.dp))
            Text(
                "${item.condition}/${item.maxCondition}",
                color = BoneDim, fontSize = 9.sp, fontFamily = MwData
            )
        }
        Text(
            "${item.cost}g",
            color = if (affordable) BronzeLight else RepairCondRed,
            fontSize = 13.sp, fontFamily = MwData,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.End,
            modifier = Modifier.width(54.dp)
        )
    }
}

/** A repair action button (Repair All / Cancel), styled like [BarterButton]. */
@Composable
private fun RepairButton(
    label: String,
    color: Color,
    enabled: Boolean,
    modifier: Modifier = Modifier,
    onClick: () -> Unit
) {
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(3.dp))
            .background(if (enabled) color.copy(alpha = 0.20f) else SlotBg)
            .border(1.dp, if (enabled) color else BronzeDark, RoundedCornerShape(3.dp))
            .then(if (enabled) Modifier.clickable { onClick() } else Modifier)
            .padding(horizontal = 14.dp, vertical = 9.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            label,
            color = if (enabled) color else BoneDim,
            fontSize = 12.sp, fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
            maxLines = 1, overflow = TextOverflow.Ellipsis
        )
    }
}

/* ---- Training overlay (bottom screen) ---- */



/* ---- DS Alchemy (bottom + top screens) ---- */

/**
 * The four apparatus types, `ESM::Apparatus::AppaType`. The engine hardcodes exactly these and
 * throws on any other value, so four slots is safe to assume rather than derive.
 *
 * Only index 0 is required to brew at all; the other three are optional quality modifiers (a retort
 * for beneficial effects, an alembic for harmful ones, a calcinator either way).
 */
private val ALCHEMY_APPARATUS_NAMES = listOf("Mortar & Pestle", "Alembic", "Calcinator", "Retort")

/** Gap between the top-screen alchemy panel and the bottom edge of that screen. The top screen is
 *  1920x1080 at density 369, i.e. ~832 x ~468 dp, so this is a small inset on a ~468dp-tall screen —
 *  enough that the panel is not flush against the edge, not so much that it creeps back to centre. */
private val ALCHEMY_TOP_PANEL_INSET = 24.dp

/** Width fraction shared by BOTH top-screen DS service panels (alchemy and enchanting), so the two
 *  are the same size. Extracted from alchemy's inline 0.82f when enchanting adopted it. */
private const val ALCHEMY_TOP_PANEL_WIDTH = 0.82f

/** Cap on the enchanting readout's height. The panel is intrinsically sized, so without this a full
 *  eight effects (several of them two lines) would push it off the top of the screen. */
private val ENCHANT_TOP_EFFECTS_MAX = 240.dp

/** Floor under the enchanting top panel, so it keeps its size when there is little in it — with no
 *  effects yet the left column alone would set the height and the panel would visibly shrink as the
 *  player works. ~25% taller than the height the stat column produces on its own. */
private val ENCHANT_TOP_PANEL_MIN_HEIGHT = 215.dp

/** Control height for the BOTTOM enchanting screen — deliberately its own constant rather than the
 *  shared ALCHEMY_CONTROL_HEIGHT: this screen is denser (three popup types, a slider editor) and was
 *  sized up on its own without dragging alchemy's proportions along with it. */
private val ENCHANT_CONTROL_HEIGHT = 56.dp

/**
 * Cross-screen alchemy UI state. Both companion surfaces are separate compositions in separate
 * windows, so anything one has to tell the other lives here — Compose snapshot state is process-wide
 * and observed from both. Same technique as [ManualJournalComposerState].
 *
 * All of it is pure presentation. Nothing here influences a mechanic: the picker and the composer
 * only decide which command gets sent, and the filter only decides which rows are drawn.
 */
private object AlchemyUiState {
    /** Non-null while the TOP screen's apparatus picker is open, holding the apparatus TYPE it is
     *  filtered to — the same per-type filter vanilla's ItemSelectionDialog applies. */
    var pickerType by mutableStateOf<Int?>(null)
    /** True while the BOTTOM screen's name keyboard is up (raised by A on the top screen's name
     *  field). The keyboard has to live on the bottom panel — it is touch-only by design, because
     *  the Android IME would move input focus off the game entirely (see [TextInputOverlay]). */
    var nameComposer by mutableStateOf(false)
    /** Browse-list filter — matched against the display name AND the ingredient's KNOWN effect
     *  names at once. Vanilla keeps those two as mutually-exclusive modes behind a toggle button
     *  (setting both throws in its model); one combined field is strictly more permissive, finds
     *  everything either mode would, and saves a tap. Purely presentational — filtering decides
     *  which rows are drawn and nothing else. */
    var filter by mutableStateOf("")
    /** The quantity spinner, clamped to 1..maxBrew.
     *
     *  Vanilla's own spinner is UNCAPPED (`AlchemyWindow` never calls setMaxValue) and silently
     *  brews only `min(countPotionsToBrew(), value)` — a deliberate divergence, because a number you
     *  can raise with no effect reads as broken on a touch screen. The engine still applies that
     *  same clamp underneath, so this cap is a UI affordance and never the thing enforcing it. */
    var qty by mutableStateOf(1)

    fun reset() {
        pickerType = null
        nameComposer = false
        filter = ""
        qty = 1
    }
}

/**
 * Does this ingredient pass the current browse filter?
 *
 * Case-insensitive substring against the display name OR any effect the player can actually SEE.
 * Both halves come from `SortFilterItemModel::filterAccepts` under `Filter_OnlyIngredients`, which
 * offers them as two mutually-exclusive modes; they are combined here because one field that finds
 * either is easier to use on a touch screen and can never find less.
 *
 * UNKNOWN EFFECTS CAN NEVER MATCH, and that is not merely cosmetic — the engine filters against
 * `Alchemy::effectsDescription`, which stops at the first slot the player's Alchemy cannot reach, so
 * matching a hidden effect would leak exactly the information the skill gate exists to withhold.
 * (The exporter does not even send a name for an unknown effect, so this is belt and braces.)
 */
private fun alchemyIngredientMatches(item: AlchemyIngredient, filter: String): Boolean {
    val needle = filter.trim().lowercase()
    if (needle.isEmpty()) return true
    if (item.name.lowercase().contains(needle)) return true
    return item.effects.any { it.known && it.name.lowercase().contains(needle) }
}

/**
 * BOTTOM-screen alchemy: ingredient slots, the searchable ingredient list, the quantity spinner,
 * the success chance and Create/Cancel.
 *
 * TOUCH ONLY, by design — the companion panel is `FLAG_NOT_FOCUSABLE`, so no D-pad input reaches it.
 * The controller half of the screen is the TOP overlay (name + apparatus), which consumes NavEvents.
 *
 * PRESENTATION ONLY. Every tap sends a `CMP:alchemy_*` command to the native AlchemyWindow and the
 * screen is redrawn from the batch that comes back, so the combination rule and its slot order, the
 * duplicate-ingredient rejection, the validation order, `countPotionsToBrew()` and the per-potion
 * success roll are all still the engine's.
 */
@Composable
private fun AlchemyOverlay(session: AlchemySession) {
    // Reset the local view state once per session, not per recomposition.
    DisposableEffect(Unit) {
        AlchemyUiState.reset()
        onDispose { AlchemyUiState.reset() }
    }

    var searching by remember { mutableStateOf(false) }
    val message by GameStateRepository.alchemyMessage.collectAsState()

    // Highest quantity currently brewable. countPotionsToBrew() is 0 whenever the recipe is not
    // ready at all (no mortar, <2 ingredients, no name, no shared effects), so floor the cap at 1 —
    // the spinner should sit at 1 in those states, not collapse to 0, and pressing Create is how
    // vanilla's validation message is produced.
    val qtyCap = session.maxBrew.coerceAtLeast(1)
    // Follow the craftable maximum DOWN as it changes — most visibly right after a brew, which
    // consumes one of each ingredient per potion and can empty a slot entirely. Keyed on maxBrew so
    // it re-clamps on every fresh batch; it also runs on first composition, pinning the initial 1.
    LaunchedEffect(qtyCap) { AlchemyUiState.qty = AlchemyUiState.qty.coerceIn(1, qtyCap) }

    val visible = remember(session.ingredients, AlchemyUiState.filter) {
        session.ingredients.filter { alchemyIngredientMatches(it, AlchemyUiState.filter) }
    }

    Box(
        Modifier
            .fillMaxSize()
            .zIndex(18f)
            // Swallow stray taps: this is a full-screen replacement for the native window, and there
            // is no tap-outside-to-dismiss (Cancel is an explicit button, as it is in vanilla).
            .pointerInput(Unit) { detectTapGestures { } }
            .background(StoneDark)
    ) {
        Column(Modifier.fillMaxSize().padding(horizontal = 8.dp, vertical = 6.dp)) {

            // --- Header -----------------------------------------------------------------------------
            // A "Success N%" badge sat here briefly and was REMOVED; see AlchemySession.chance for
            // why. Do not put it back without reading that note first.
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                Text(
                    "ALCHEMY",
                    color = BronzeLight, fontSize = 15.sp, fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold
                )
            }
            Spacer(Modifier.height(4.dp))
            Box(Modifier.fillMaxWidth().height(1.dp).background(Bronze))
            Spacer(Modifier.height(6.dp))

            // --- Ingredient slots ------------------------------------------------------------------
            // Rendered in SLOT ORDER including the gaps: order decides which effects the potion ends
            // up with and the order they apply, so a hole in the middle is real state. Nothing is
            // ever compacted or sorted here.
            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                session.slots.forEach { slot ->
                    AlchemySlotBox(
                        slot = slot,
                        modifier = Modifier.weight(1f),
                        onTap = {
                            if (slot.present) {
                                UiSounds.play(UiSounds.Cue.TOGGLE)
                                CompanionActions.alchemyClearIngredient(slot.slot)
                            }
                        }
                    )
                }
            }

            Spacer(Modifier.height(6.dp))

            // --- Filter row -------------------------------------------------------------------------
            // One field matching the name OR any KNOWN effect (see alchemyIngredientMatches).
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                Box(
                    Modifier
                        .weight(1f)
                        .clip(RoundedCornerShape(3.dp))
                        .background(SlotBg)
                        .border(1.dp, BronzeDark, RoundedCornerShape(3.dp))
                        .clickable { searching = true }
                        .padding(horizontal = 9.dp, vertical = 8.dp)
                ) {
                    Text(
                        AlchemyUiState.filter.ifBlank { "Search name or known effect…" },
                        color = if (AlchemyUiState.filter.isBlank()) BoneDim else BoneBright,
                        fontSize = 12.sp, fontFamily = MwBody, maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
                if (AlchemyUiState.filter.isNotBlank()) {
                    Spacer(Modifier.width(6.dp))
                    AlchemyChip(label = "Clear", active = false, onTap = { AlchemyUiState.filter = "" })
                }
            }

            Spacer(Modifier.height(6.dp))

            // --- Browse list ------------------------------------------------------------------------
            // Ingredients already placed are absent from the export (vanilla drops them from its own
            // list too), and a full set of four slots leaves every row inert — addIngredient() would
            // return -1 with no feedback, so the row is greyed rather than pretending to work.
            val canAdd = session.freeSlots > 0
            Column(Modifier.weight(1f).fillMaxWidth().verticalScroll(rememberScrollState())) {
                if (visible.isEmpty()) {
                    Text(
                        if (session.ingredients.isEmpty()) "No ingredients carried"
                        else "No ingredients match",
                        color = BoneDim, fontSize = 12.sp, fontFamily = MwBody,
                        modifier = Modifier.padding(vertical = 10.dp)
                    )
                } else visible.forEach { item ->
                    AlchemyIngredientRow(
                        item = item,
                        enabled = canAdd,
                        onTap = {
                            if (canAdd) {
                                UiSounds.play(UiSounds.Cue.TOGGLE)
                                CompanionActions.alchemyAddIngredient(item.id)
                            }
                        }
                    )
                }
            }

            Spacer(Modifier.height(6.dp))
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
            Spacer(Modifier.height(6.dp))

            // --- Quantity + Create/Cancel -------------------------------------------------------------
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                // Both steppers are bounded and grey out at their limit, so the cap is visible
                // rather than just felt. See AlchemyUiState.qty for why this diverges from vanilla's
                // unbounded spinner.
                AlchemyStepButton("−", enabled = AlchemyUiState.qty > 1) {
                    AlchemyUiState.qty--
                    UiSounds.play(UiSounds.Cue.TICK)
                }
                Spacer(Modifier.width(8.dp))
                Box(
                    Modifier
                        .width(58.dp)
                        // Same height as the two step buttons flanking it, so the trio reads as one
                        // control rather than a short box wedged between two tall ones.
                        .height(ALCHEMY_CONTROL_HEIGHT)
                        .clip(RoundedCornerShape(3.dp))
                        .background(SlotBg)
                        .border(1.dp, BronzeDark, RoundedCornerShape(3.dp)),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        "${AlchemyUiState.qty}",
                        color = BoneBright, fontSize = 15.sp, fontFamily = MwData,
                        fontWeight = FontWeight.Bold
                    )
                }
                Spacer(Modifier.width(8.dp))
                AlchemyStepButton("+", enabled = AlchemyUiState.qty < qtyCap) {
                    AlchemyUiState.qty++
                    UiSounds.play(UiSounds.Cue.TICK)
                }
                Spacer(Modifier.width(10.dp))
                // countPotionsToBrew() — the smallest selected stack, or 0 whenever the recipe is not
                // ready at all (which INCLUDES an empty name). Shown as information, not as a cap.
                Text(
                    "of ${session.maxBrew}",
                    color = if (session.maxBrew > 0) BoneDim else BoneMuted,
                    fontSize = 13.sp, fontFamily = MwData
                )
                Spacer(Modifier.weight(1f))
                // Create is ALWAYS enabled, exactly as in vanilla: pressing it with an invalid recipe
                // is how the validation message is produced, and pressing it with two ingredients
                // that share no effect really does destroy one of each. No pre-warning is added.
                AlchemyActionButton(label = "Create", color = BronzeLight) {
                    UiSounds.play(UiSounds.Cue.ACTION)
                    CompanionActions.alchemyCreate(AlchemyUiState.qty)
                }
                Spacer(Modifier.width(8.dp))
                AlchemyActionButton(label = "Cancel", color = Bone) {
                    UiSounds.play(UiSounds.Cue.TOGGLE)
                    CompanionActions.alchemyCancel()
                }
            }
        }

        // --- Result / validation banner -------------------------------------------------------------
        // The resolved GMST text, routed here because the native transient message renders on the TOP
        // screen behind these panels. Keyed on the sequence number so an identical repeat re-shows.
        message?.let { (text, seq) ->
            LaunchedEffect(seq) {
                delay(ALCHEMY_MSG_MS)
                GameStateRepository.clearAlchemyMessage()
            }
            Box(
                Modifier.fillMaxWidth().align(Alignment.TopCenter).padding(top = 34.dp),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text,
                    color = BoneBright, fontSize = 13.sp, fontFamily = MwDisplay,
                    textAlign = TextAlign.Center,
                    modifier = Modifier
                        .fillMaxWidth(0.9f)
                        .clip(RoundedCornerShape(4.dp))
                        .background(Color(0xF2201A12))
                        .border(1.dp, BronzeLight, RoundedCornerShape(4.dp))
                        .padding(horizontal = 12.dp, vertical = 9.dp)
                )
            }
        }

        // --- Search entry ------------------------------------------------------------------------
        if (searching) {
            TextInputOverlay(
                initialText = AlchemyUiState.filter,
                title = "SEARCH NAME OR EFFECT",
                onConfirm = { AlchemyUiState.filter = it; searching = false },
                onCancel = { searching = false }
            )
        }

        // --- Potion name entry --------------------------------------------------------------------
        // Raised from the TOP screen's name field (A / tap), because the keyboard has to be touch and
        // touch only reaches the bottom panel. Confirming sends CMP:alchemy_name, after which the
        // native window re-publishes and the top field shows the new value.
        // `!searching` keeps the two keyboards mutually exclusive: the name composer is raised from
        // the TOP screen, so it can arrive while the search field is already open down here, and two
        // stacked keyboards would take each other's taps.
        if (AlchemyUiState.nameComposer && !searching) {
            TextInputOverlay(
                initialText = session.name,
                title = "POTION NAME",
                onConfirm = {
                    CompanionActions.alchemySetName(it)
                    AlchemyUiState.nameComposer = false
                },
                onCancel = { AlchemyUiState.nameComposer = false }
            )
        }
    }
}

/** How long the alchemy result banner stays up. Matched to the crime toast so the two read the same. */
private const val ALCHEMY_MSG_MS = 4200L

@Composable
private fun AlchemyChip(label: String, active: Boolean, onTap: () -> Unit) {
    Box(
        Modifier
            .clip(RoundedCornerShape(3.dp))
            .background(if (active) PillActiveBg else SlotBg)
            .border(1.dp, if (active) BronzeLight else BronzeDark, RoundedCornerShape(3.dp))
            .clickable { onTap() }
            .padding(horizontal = 9.dp, vertical = 6.dp)
    ) {
        Text(
            label,
            color = if (active) BoneBright else BoneDim,
            fontSize = 11.sp, fontFamily = MwDisplay, maxLines = 1
        )
    }
}

/** Height shared by the whole bottom control row — the two step buttons, the quantity readout
 *  between them, and Create/Cancel — so nothing in that row is a different size from its neighbour. */
private val ALCHEMY_CONTROL_HEIGHT = 46.dp

@Composable
private fun AlchemyStepButton(label: String, enabled: Boolean = true, onTap: () -> Unit) {
    Box(
        Modifier
            .size(ALCHEMY_CONTROL_HEIGHT)
            .clip(RoundedCornerShape(3.dp))
            .background(SlotBg)
            .border(1.dp, if (enabled) BronzeDark else Color(0xFF2A2118), RoundedCornerShape(3.dp))
            .then(if (enabled) Modifier.clickable { onTap() } else Modifier),
        contentAlignment = Alignment.Center
    ) {
        Text(
            label,
            color = if (enabled) BoneBright else BoneMuted.copy(alpha = 0.45f),
            fontSize = 18.sp, fontFamily = MwData, fontWeight = FontWeight.Bold
        )
    }
}

/** Create / Cancel. A local button rather than the shared [RepairButton] purely so this row can be
 *  sized for a fingertip without changing how the repair overlay looks. */
@Composable
private fun AlchemyActionButton(label: String, color: Color, onTap: () -> Unit) {
    Box(
        Modifier
            .height(ALCHEMY_CONTROL_HEIGHT)
            .clip(RoundedCornerShape(3.dp))
            .background(color.copy(alpha = 0.20f))
            .border(1.dp, color, RoundedCornerShape(3.dp))
            .clickable { onTap() }
            .padding(horizontal = 18.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            label, color = color,
            fontSize = 14.sp, fontFamily = MwDisplay, fontWeight = FontWeight.Bold, maxLines = 1
        )
    }
}

/** One ingredient slot. Tapping a filled slot empties it IN PLACE — the other slots keep their
 *  positions, because the order they were placed in is what decides the created effects. */
@Composable
private fun AlchemySlotBox(slot: AlchemySlot, modifier: Modifier = Modifier, onTap: () -> Unit) {
    val icon = rememberItemIcon(slot.icon)
    Column(
        modifier
            .height(62.dp)
            .clip(RoundedCornerShape(3.dp))
            .background(if (slot.present) SlotWorn else SlotBg)
            .border(1.dp, if (slot.present) BronzeLight else BronzeDark, RoundedCornerShape(3.dp))
            .clickable { onTap() }
            .padding(3.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        if (slot.present) {
            if (icon != null) {
                Image(bitmap = icon, contentDescription = null, modifier = Modifier.size(28.dp))
            }
            Text(
                slot.name,
                color = BoneBright, fontSize = 9.sp, fontFamily = MwBody,
                maxLines = 1, overflow = TextOverflow.Ellipsis, textAlign = TextAlign.Center
            )
        } else {
            Text("empty", color = BoneMuted, fontSize = 10.sp, fontFamily = MwBody)
        }
    }
}

/**
 * One browse-list row: the ingredient plus one entry per NON-EMPTY effect slot. Unknown slots show
 * "?" and carry no name at all (the exporter sends none), which is exactly what the vanilla
 * ingredient tooltip does — it lists every filled slot and renders the ones the player's Alchemy
 * cannot yet reach as a bare question mark.
 *
 * The effects are joined with ", " rather than laid out as separate columns: bare space separation
 * read as one run-on phrase ("Drain Agility ? ? ?"), with no visible boundary between a two-word
 * effect name and the question marks after it.
 *
 * Sized generously for a fingertip — this is the one list on the screen that is tapped repeatedly.
 */
@Composable
private fun AlchemyIngredientRow(item: AlchemyIngredient, enabled: Boolean, onTap: () -> Unit) {
    val icon = rememberItemIcon(item.icon)
    Row(
        Modifier
            .fillMaxWidth()
            .padding(vertical = 3.dp)
            .clip(RoundedCornerShape(3.dp))
            .background(SlotBg)
            .border(1.dp, BronzeDark, RoundedCornerShape(3.dp))
            .then(if (enabled) Modifier.clickable { onTap() } else Modifier)
            .padding(horizontal = 8.dp, vertical = 9.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        if (icon != null) {
            Image(bitmap = icon, contentDescription = null, modifier = Modifier.size(40.dp))
            Spacer(Modifier.width(9.dp))
        }
        Column(Modifier.weight(1f)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text(
                    item.name,
                    color = if (enabled) BoneBright else BoneMuted,
                    fontSize = 14.sp, fontFamily = MwBody,
                    maxLines = 1, overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f, fill = false)
                )
                if (item.count > 1) {
                    Spacer(Modifier.width(6.dp))
                    Text("x${item.count}", color = BoneDim, fontSize = 12.sp, fontFamily = MwData)
                }
            }
            if (item.effects.isNotEmpty()) {
                Spacer(Modifier.height(3.dp))
                Text(
                    item.effects.joinToString(",   ") { if (it.known) it.name else "?" },
                    color = BoneDim, fontSize = 11.sp, fontFamily = MwData,
                    lineHeight = 15.sp, maxLines = 2, overflow = TextOverflow.Ellipsis
                )
            }
        }
    }
}

/**
 * TOP-screen alchemy: the name field and the four apparatus slots on the left, the created-effects
 * preview on the right.
 *
 * This is the D-PAD half of the screen. It is hosted non-touchable, so the whole left column is
 * driven by the controller: Up/Down walks the five focusables (name, then the four apparatus slots)
 * and A activates the focused one. The created-effects column is view-only and deliberately OUTSIDE
 * that loop — there is nothing to do to it.
 *
 * Apparatus behaviour matches the native window exactly: A on a FILLED slot empties it, A on an
 * EMPTY one opens a picker restricted to that apparatus type — the same per-type filter vanilla's
 * ItemSelectionDialog applies.
 */
@Composable
fun AlchemyTopOverlay() {
    val session by GameStateRepository.alchemySession.collectAsState()
    val s = session ?: return

    val picker = AlchemyUiState.pickerType
    val pickerTools = if (picker == null) emptyList() else s.toolsOfType(picker)

    // The main loop yields entirely while the picker or the name keyboard owns input.
    // One action for both input paths: A on the focused row and a tap on any row run this, so the
    // two can never diverge. Apparatus behaviour matches the native window — a FILLED slot is
    // emptied, an EMPTY one opens the per-type picker.
    val activate: (Int) -> Unit = { i ->
        if (i == 0) {
            AlchemyUiState.nameComposer = true
        } else {
            s.apparatus.getOrNull(i - 1)?.let { slot ->
                if (slot.present) CompanionActions.alchemyClearApparatus(slot.slot)
                else AlchemyUiState.pickerType = slot.type
            }
        }
    }
    val focus = rememberListNavFocus(
        itemCount = 1 + s.apparatus.size,
        enabled = picker == null && !AlchemyUiState.nameComposer,
        onConfirm = activate
    )

    // Bottom-aligned rather than centred: the top screen is the game, and a centred panel sits
    // right over the middle of the view. Dropping it low keeps the upper two thirds clear. The
    // apparatus picker below uses the same alignment and inset so it lands where the panel was
    // rather than floating in the space the panel just vacated.
    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.BottomCenter) {
        // ONE panel around all three sections (name, apparatus, created effects). They are parts of
        // a single screen, not three independent overlays, so they share one frame; the columns are
        // separated by a hairline rule rather than by borders of their own, which would have read as
        // three unrelated windows that happened to be adjacent.
        Row(
            Modifier
                // Outside the panel frame, so it is a gap from the screen edge and not interior
                // padding — hence before mwPanel() in the chain, not after.
                .padding(bottom = ALCHEMY_TOP_PANEL_INSET)
                .fillMaxWidth(ALCHEMY_TOP_PANEL_WIDTH)
                // IntrinsicSize.Min so the divider's fillMaxHeight() below resolves to the TALLEST
                // COLUMN rather than to the incoming (full-screen) constraint, which would stretch
                // this whole panel down the screen.
                .height(IntrinsicSize.Min)
                .mwPanel()
                .padding(12.dp),
            horizontalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            // ---- Left: name + apparatus (the focus loop) ----
            Column(Modifier.weight(1f)) {
                Text(
                    "POTION NAME",
                    color = BronzeLight, fontSize = 11.sp, fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.height(4.dp))
                AlchemyTopFocusBox(focused = focus == 0, onTap = { activate(0) }) {
                    Text(
                        // The native window auto-fills this with suggestPotionName() whenever the
                        // suggestion CHANGES, which is what lets a hand-typed name survive. The
                        // value shown is always the field's real caption, echoed back in the batch.
                        s.name.ifBlank { "(unnamed)" },
                        color = if (s.name.isBlank()) BoneMuted else BoneBright,
                        fontSize = 13.sp, fontFamily = MwBody,
                        maxLines = 1, overflow = TextOverflow.Ellipsis
                    )
                }

                Spacer(Modifier.height(10.dp))
                Text(
                    "APPARATUS",
                    color = BronzeLight, fontSize = 11.sp, fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.height(4.dp))
                s.apparatus.forEachIndexed { i, appa ->
                    val icon = rememberItemIcon(appa.icon)
                    AlchemyTopFocusBox(
                        focused = focus == i + 1,
                        modifier = Modifier.padding(bottom = 4.dp),
                        onTap = { activate(i + 1) }
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            if (appa.present && icon != null) {
                                Image(bitmap = icon, contentDescription = null, modifier = Modifier.size(22.dp))
                                Spacer(Modifier.width(6.dp))
                            }
                            Column(Modifier.weight(1f)) {
                                Text(
                                    ALCHEMY_APPARATUS_NAMES.getOrElse(appa.type) { "Apparatus" },
                                    // Only the Mortar & Pestle is required; the rest are optional
                                    // quality modifiers, so an empty one is not an error state.
                                    color = if (appa.type == 0 && !appa.present) Color(0xFFC75C5C) else BoneDim,
                                    fontSize = 9.sp, fontFamily = MwData
                                )
                                Text(
                                    if (appa.present) appa.name else "(none)",
                                    color = if (appa.present) BoneBright else BoneMuted,
                                    fontSize = 12.sp, fontFamily = MwBody,
                                    maxLines = 1, overflow = TextOverflow.Ellipsis
                                )
                            }
                            if (appa.present) {
                                Text(
                                    formatQuality(appa.quality),
                                    color = BronzeLight, fontSize = 10.sp, fontFamily = MwData
                                )
                            }
                        }
                    }
                }
            }

            // Divider between the two columns. fillMaxHeight inside a Row measures against the
            // tallest sibling, so it tracks the left column's height without a fixed value.
            Box(Modifier.width(1.dp).fillMaxHeight().background(BronzeDark))

            // ---- Right: created effects (view-only, never focused) ----
            Column(Modifier.weight(1f)) {
                Text(
                    "CREATED EFFECTS",
                    color = BronzeLight, fontSize = 11.sp, fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.height(6.dp))
                if (s.created.isEmpty()) {
                    Text(
                        "None",
                        color = BoneMuted, fontSize = 12.sp, fontFamily = MwBody
                    )
                } else s.created.forEach { eff ->
                    val icon = rememberItemIcon(if (eff.known) eff.icon else "")
                    Row(
                        Modifier.fillMaxWidth().padding(vertical = 2.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        if (icon != null) {
                            Image(bitmap = icon, contentDescription = null, modifier = Modifier.size(20.dp))
                            Spacer(Modifier.width(6.dp))
                        }
                        // NAME ONLY — no magnitude, no duration, no range. Vanilla builds this list
                        // with mIsConstant/mNoTarget/mNoMagnitude all set, so it shows nothing else
                        // either; and an entry the player's Alchemy cannot yet reach is a bare "?".
                        Text(
                            if (eff.known) eff.name else "?",
                            color = if (eff.known) Bone else BoneMuted,
                            fontSize = 12.sp, fontFamily = MwBody,
                            maxLines = 1, overflow = TextOverflow.Ellipsis
                        )
                    }
                }
            }
        }

        // ---- Apparatus picker ----
        // Lives on the TOP screen so the whole apparatus flow stays reachable with the D-pad. Marked
        // as a cancel-able modal so native routes B to COMPANION_NAV_CANCEL (closing just this) rather
        // than popping GM_Alchemy, and so the loop above yields while it is up.
        if (picker != null) {
            DisposableEffect(picker) {
                ModalNav.count++
                CompanionActions.setModalCancelOpen(true)
                onDispose {
                    ModalNav.count--
                    if (ModalNav.count == 0) CompanionActions.setModalCancelOpen(false)
                }
            }
            val pickerFocus = rememberListNavFocus(
                itemCount = pickerTools.size,
                onConfirm = { i ->
                    pickerTools.getOrNull(i)?.let { CompanionActions.alchemySetApparatus(picker, it.id) }
                    AlchemyUiState.pickerType = null
                },
                onCancel = { AlchemyUiState.pickerType = null }
            )
            Box(
                Modifier
                    // The scrim stays full-bleed; only the card is inset, so there is no unscrimmed
                    // strip along the bottom edge.
                    .fillMaxSize()
                    .background(Color.Black.copy(alpha = 0.6f))
                    .pointerInput(picker) { detectTapGestures { AlchemyUiState.pickerType = null } },
                contentAlignment = Alignment.BottomCenter
            ) {
                Column(
                    Modifier
                        .padding(bottom = ALCHEMY_TOP_PANEL_INSET)
                        .fillMaxWidth(0.5f)
                        .mwPanel()
                        // Swallow taps on the card so a miss between rows cannot dismiss it.
                        .pointerInput(Unit) { detectTapGestures { } }
                        .padding(12.dp)
                ) {
                    Text(
                        ALCHEMY_APPARATUS_NAMES.getOrElse(picker) { "Apparatus" }.uppercase(),
                        color = BronzeLight, fontSize = 13.sp, fontFamily = MwDisplay,
                        fontWeight = FontWeight.Bold
                    )
                    Spacer(Modifier.height(8.dp))
                    if (pickerTools.isEmpty()) {
                        Text("You carry none.", color = BoneMuted, fontSize = 12.sp, fontFamily = MwBody)
                    } else pickerTools.forEachIndexed { i, tool ->
                        val icon = rememberItemIcon(tool.icon)
                        AlchemyTopFocusBox(
                            focused = pickerFocus == i,
                            modifier = Modifier.padding(bottom = 4.dp),
                            onTap = {
                                CompanionActions.alchemySetApparatus(picker, tool.id)
                                AlchemyUiState.pickerType = null
                            }
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                if (icon != null) {
                                    Image(bitmap = icon, contentDescription = null, modifier = Modifier.size(22.dp))
                                    Spacer(Modifier.width(6.dp))
                                }
                                Text(
                                    tool.name,
                                    color = BoneBright, fontSize = 12.sp, fontFamily = MwBody,
                                    maxLines = 1, overflow = TextOverflow.Ellipsis,
                                    modifier = Modifier.weight(1f)
                                )
                                Text(
                                    formatQuality(tool.quality),
                                    color = BronzeLight, fontSize = 10.sp, fontFamily = MwData
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

/** Apparatus quality, as the native tooltip prints it — one decimal place. */
private fun formatQuality(q: Float): String = String.format("%.1f", q)

/** A focusable row on the top screen. Focus is a brighter, thicker border, matching the launcher's
 *  Play button: a pre-selected control that looks identical to an idle one reads as broken. */
@Composable
private fun AlchemyTopFocusBox(
    focused: Boolean,
    modifier: Modifier = Modifier,
    onTap: (() -> Unit)? = null,
    content: @Composable () -> Unit
) {
    Box(
        modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(3.dp))
            .background(if (focused) PillActiveBg else SlotBg)
            .border(if (focused) 2.dp else 1.dp, if (focused) BronzeLight else BronzeDark, RoundedCornerShape(3.dp))
            .then(if (onTap != null) Modifier.clickable { onTap() } else Modifier)
            .padding(horizontal = 8.dp, vertical = 6.dp)
    ) { content() }
}



/* ================= DS Map ================= */

/**
 * Per-map zoom limits, in SCREEN PIXELS PER CELL (local) or per world-map cell (global).
 *
 * **There is no World/Local continuum any more.** Both maps are on screen at once, one per physical
 * display, so there is nothing to flip BETWEEN — the old "zoom the local map out far enough and it
 * becomes the world map" mechanic was removed with the single-surface design that needed it. What
 * replaces it is two plain clamps whose job is to stop either map impersonating the other:
 *  - the world map has a zoom-IN ceiling, so it cannot become a de-facto local map;
 *  - the local map has a zoom-OUT floor, so it cannot become a de-facto world map.
 *
 * The floors are not constants: each is "the map exactly fills the viewport width", measured per
 * surface (see [mapZoomBounds]), so neither can be shrunk into empty background — and because a map
 * can be moved between screens, its floor is re-measured against whichever surface it is on.
 */
private const val MAP_LOCAL_MAX = 8000f
private const val MAP_GLOBAL_FIT = 22f
private const val MAP_GLOBAL_MAX = 260f

/**
 * How much further OUT the DS local map opens than the HUD minimap sits.
 *
 * A multiplier on the pixels-per-cell below, so `< 1` is zoomed out: 0.75 shows a third more map
 * across each axis. The minimap's own crop is deliberately tight because it is a corner widget a
 * few centimetres across; a full surface at that same scale opens showing about a third of one
 * cell, which is less than the room actually warrants. This is the one knob for that — the
 * minimap's [MINIMAP_CROP_FRACTION] is left alone so the HUD widget is unchanged.
 */
private const val MAP_LOCAL_DEFAULT_ZOOM_OUT = 0.75f

/**
 * The local map's DEFAULT zoom, derived from the HUD minimap so the two read as the same map rather
 * than two different views of it, then pulled [MAP_LOCAL_DEFAULT_ZOOM_OUT] further out.
 *
 * The minimap works in exactly these units — `cellPx = size.minDimension / MINIMAP_CROP_FRACTION`
 * — so this is that same expression against whichever surface the local map currently occupies.
 * Derived per surface rather than stored as a constant, because the two displays differ in size and
 * the map can be swapped between them. The caller clamps the result into [mapZoomBounds], so this
 * can never open further out than there is loaded content to show.
 */
private fun mapLocalDefaultScale(viewport: Size): Float =
    if (viewport.minDimension > 0f)
        viewport.minDimension / MINIMAP_CROP_FRACTION * MAP_LOCAL_DEFAULT_ZOOM_OUT
    else 620f

/** Marker size as a FRACTION OF A CELL, so markers are locked to the map and grow as you zoom in.
 *
 *  THE TWO MAPS NEED VERY DIFFERENT FRACTIONS, and that is why there are two constants. A cell is a
 *  completely different size on screen in each — hundreds of px on the local map against tens on the
 *  world map — so reusing one figure drew local markers hundreds of px across. The local figure is
 *  vanilla's own: `doorMarkerCreated` uses `getMarkerCoordinates(x, y, data, 8)` against a
 *  `local map widget size` of 512, i.e. 8/512. (Vanilla's custom/note markers use 16 in the same
 *  units, which is what MAP_NOTE_CELLS mirrors.) */
private const val MAP_PLACE_CELLS = 0.45f          // world map — a whole town inside one small cell
private const val MAP_DOOR_CELLS = 8f / 512f       // local map — vanilla's door-marker ratio
private const val MAP_NOTE_CELLS = 16f / 512f      // vanilla's custom-marker ratio

/**
 * How much LARGER the player arrow is drawn than the marker boxes on the same map.
 *
 * It is still sized in cell units, so it shrinks and grows with the map exactly as the icons do —
 * these are just multipliers on that. Two reasons it needs them rather than matching the boxes 1:1:
 * `compass.dds` carries transparent padding, so the visible arrow is only a fraction of the box it
 * is drawn into; and the arrow conveys a DIRECTION, which needs more pixels to read than a static
 * square does. The world figure is larger because its boxes stand for whole towns while the arrow
 * still marks a single point.
 */
private const val MAP_ARROW_SCALE_LOCAL = 1.5f
private const val MAP_ARROW_SCALE_WORLD = 4f

/** Floor on the TOUCH target only (never the drawn box). Markers scale, so they get genuinely small
 *  when zoomed out; the tap area stops shrinking here while the square carries on. */
private val MAP_PLACE_MIN_HIT = 22.dp

/** How long a tapped marker's name/note label stays up before auto-dismissing. Matches the HUD
 *  minimap's own door-marker bubble so the two read the same. */
private const val MAP_PLACE_LABEL_MS = 3000L

/**
 * The interior rotation parameters, or the identity for an exterior.
 *
 * **INTERIOR LOCAL MAPS ARE ROTATED BY THE CELL'S NORTHMARKER** (`mAngle = atan2(north.x, north.y)`
 * about the expanded bounds centre) — the engine applies it to the map, the player dot and the
 * arrow alike, and it is NOT exposed to Lua, so the companion receives `angle`/`center` on the
 * segment export and replicates it. Exteriors are world-aligned, so angle 0 and the bounds terms
 * fall out. Getting this wrong looks exactly like it sounds: everything sits at a CONSTANT rotation
 * (commonly near 90 degrees) and never self-corrects as you move.
 */
private data class MapLocalFrame(
    val angle: Float, val centerX: Float, val centerY: Float,
    val boundsMinX: Float, val boundsMinY: Float
)

private fun mapLocalFrame(interior: Boolean, seg: InteriorSegment?): MapLocalFrame =
    if (interior && seg != null)
        MapLocalFrame(seg.angle, seg.centerX, seg.centerY, seg.boundsMinX, seg.boundsMinY)
    else MapLocalFrame(0f, 0f, 0f, 0f, 0f)

/**
 * World position -> SEGMENT SPACE (units of one segment, +Y up), the single conversion the whole
 * local map is built on. Rotates first, exactly as `LocalMap::updatePlayer` does, then shifts by the
 * interior bounds. For an exterior this reduces to `world / cellSize`, i.e. plain cell coordinates.
 *
 * Everything downstream is a DIFFERENCE against the player's own value, so the `boundsMin` term
 * cancels for markers and only matters for locating the segment grid itself.
 */
private fun mapLocalRaw(worldX: Float, worldY: Float, s: MapDsState, f: MapLocalFrame): Offset {
    val ca = cos(f.angle); val sa = sin(f.angle)
    val rx = ca * (worldX - f.centerX) - sa * (worldY - f.centerY) + f.centerX
    val ry = sa * (worldX - f.centerX) + ca * (worldY - f.centerY) + f.centerY
    return Offset((rx - f.boundsMinX) / s.cellSize, (ry - f.boundsMinY) / s.cellSize)
}

/** World position -> screen, on the LOCAL map. Player-centred, so the player's own position lands
 *  exactly on (cx, cy) and the `boundsMin`/centre terms cancel. Shared by the door markers, the
 *  notes and the hit tests so they cannot drift apart. */
private fun mapLocalPos(
    worldX: Float, worldY: Float, s: MapDsState, f: MapLocalFrame, px: Float, cx: Float, cy: Float
): Offset {
    val m = mapLocalRaw(worldX, worldY, s, f)
    val p = mapLocalRaw(s.playerX, s.playerY, s, f)
    return Offset(cx + (m.x - p.x) * px, cy - (m.y - p.y) * px)
}

/**
 * Is this world position EXPLORED — i.e. is the fog at that point lifted?
 *
 * A transcription of `LocalMap::isPositionExplored`, against the same per-segment fog the DS map
 * already draws. Vanilla puts door markers on `Local_MarkerLayer`, which is BEHIND
 * `Local_FogLayer`, so an undiscovered door is simply covered by the black fog square; this Canvas
 * paints in draw order instead, so the markers have to be gated explicitly or they float on top of
 * the fog and hand the player a map of places they have not found yet.
 *
 * **Notes deliberately do NOT go through this.** Vanilla puts custom markers — and magic/`Mark`
 * markers — on `Local_MarkerAboveFogLayer`, i.e. in FRONT of the fog: a note the player placed
 * themselves is theirs to see. Only the game's own door markers are a discovery.
 *
 * Three details are the engine's, not ours:
 *  - **The fog image is Y-DOWN** (row 0 = the cell's HIGH-world-Y edge) — `getMarkerPosition` does
 *    `nY = 1 - fract(worldY / cellSize)`, and `mapwindow.cpp` notes the fog texture is the one
 *    layer whose UV is *not* inverted. So the row index is `1 - fractional Y`, not the fraction.
 *  - **The threshold is `alpha < 200`, not `< 255`** — a partially-lifted texel counts as explored.
 *  - **No fog image at all means NOT explored** (`isPositionExplored` returns false on a null
 *    image). That is the safe direction: a cell whose imagery was force-rendered but which the
 *    player has never entered must not reveal its doors.
 *
 * Interiors work through the same path because [mapLocalRaw] already applies the NorthMarker
 * rotation and the bounds shift, which is exactly what `worldToInteriorMapPosition` does before
 * taking the same fractional parts.
 */
private fun mapPositionExplored(
    worldX: Float, worldY: Float, s: MapDsState, f: MapLocalFrame,
    fog: Map<Triple<Int, Int, Boolean>, Bitmap>
): Boolean {
    val raw = mapLocalRaw(worldX, worldY, s, f)
    val gx = floor(raw.x).toInt()
    val gy = floor(raw.y).toInt()
    val bmp = fog[Triple(gx, gy, s.interior)] ?: return false
    val nX = (raw.x - gx).coerceIn(0f, 1f)
    val nY = (1f - (raw.y - gy)).coerceIn(0f, 1f)
    val u = ((bmp.width - 1) * nX).toInt().coerceIn(0, bmp.width - 1)
    val v = ((bmp.height - 1) * nY).toInt().coerceIn(0, bmp.height - 1)
    return (bmp.getPixel(u, v) ushr 24) < 200
}

/** A real WORLD POSITION -> screen, on the world map. This is the projection the player marker and
 *  the notes use. [mapPlaceCentre] is the sibling for discovered locations, which differ only in
 *  carrying integer cell indices and therefore needing the half-cell centring offset. */
private fun mapWorldPos(
    worldX: Float, worldY: Float, s: MapDsState, gi: GlobalMapInfo, k: Float, left: Float, top: Float
): Offset = Offset(
    left + (worldX / s.cellSize - gi.minX) * gi.cellPixels * k,
    top + (gi.height - (worldY / s.cellSize - gi.minY) * gi.cellPixels) * k
)

/** The exact inverse of [mapWorldPos] — screen -> world position on the world map. Backs long-press
 *  note placement, which must land the note where the finger was and NOT at the player. */
private fun mapWorldFromScreen(
    screen: Offset, s: MapDsState, gi: GlobalMapInfo, k: Float, left: Float, top: Float
): Offset = Offset(
    ((screen.x - left) / (gi.cellPixels * k) + gi.minX) * s.cellSize,
    (gi.minY + (gi.height - (screen.y - top) / k) / gi.cellPixels) * s.cellSize
)

/** Screen centre of a world-map DISCOVERED-LOCATION marker.
 *
 *  THE +0.5 IS LOAD-BEARING. A place's coordinates are integer CELL INDICES (addVisitedLocation is
 *  handed getGridX()/getGridY(), and a cluster's barycentre stays in that same index space), so the
 *  bare index addresses the cell's south-west CORNER. The engine adds half a cell to reach the
 *  centre before converting — `createMarkerCoords` calls
 *      worldPosToGlobalMapImageSpace((x + 0.5f) * CellSizeInUnits, (y + 0.5f) * CellSizeInUnits, ...)
 *  — and omitting it put every marker half a cell left of and below where it belonged. Notes and the
 *  player position carry REAL world positions and must NOT get this offset; they use [mapWorldPos]. */
private fun mapPlaceCentre(
    p: MapPlace, gi: GlobalMapInfo, k: Float, left: Float, top: Float
): Offset = Offset(
    left + (p.x + 0.5f - gi.minX) * gi.cellPixels * k,
    top + (gi.height - (p.y + 0.5f - gi.minY) * gi.cellPixels) * k
)

/** The world map's top-left corner on screen, given the surface size and the map's own pan/zoom. */
private fun mapWorldOrigin(gi: GlobalMapInfo, k: Float, viewport: Size, offset: Offset): Offset =
    Offset(
        viewport.width / 2f + offset.x - gi.width * k / 2f,
        viewport.height / 2f + offset.y - gi.height * k / 2f
    )

/** The pan offset that puts the PLAYER under the world map's centre. Derived by inverting
 *  [mapWorldOrigin]: the image's left edge sits at `viewportCentre + offset - imageWidth/2`, so
 *  solving "the player lands on the centre" for offset gives this. Meaningless indoors, where the
 *  player's coordinates are in the interior's own space — callers gate on that. */
private fun mapCentreOnPlayer(s: MapDsState, gi: GlobalMapInfo, scale: Float): Offset {
    val k = scale / gi.cellPixels
    val pcx = s.playerX / s.cellSize
    val pcy = s.playerY / s.cellSize
    return Offset(
        (gi.width / 2f - (pcx - gi.minX) * gi.cellPixels) * k,
        (gi.height / 2f - (gi.height - (pcy - gi.minY) * gi.cellPixels)) * k
    )
}

private data class MapZoomBounds(val min: Float, val max: Float)

/** The local map's rect in cell/segment indices — see [mapLocalCellRect]. */
private data class MapCellRect(val xMin: Int, val xMax: Int, val yMin: Int, val yMax: Int) {
    val cellsAcross: Int get() = (xMax - xMin + 1).coerceAtLeast(1)
}

/**
 * WHAT THE LOCAL MAP ACTUALLY HAS CONTENT FOR, as a rect of cell/segment indices. The zoom FLOOR
 * and the pan CLAMP are both measured from this, so neither can travel past real content.
 *
 * It is the intersection of TWO different notions of "loaded", because each is authoritative for a
 * different case and each is wrong on its own:
 *
 *  - **The cached segments.** Measured from the segments that ACTUALLY have imagery rather than
 *    from the declared grid, because for an INTERIOR `mGrid` is `getInteriorGrid()` — the whole
 *    interior, however large — while only rendered segments are exported, so trusting the grid let
 *    big interiors zoom out into black.
 *  - **The engine's grid** (`gridXMin..gridXMax`), EXTERIORS ONLY. `GameStateRepository` keeps a
 *    rolling cache of up to `MAX_EXTERIOR_SEGMENTS` (25) segments so the HUD minimap survives
 *    boundary transitions, but the engine itself only ever has a **3x3** window loaded
 *    (`Constants::CellGridRadius` = 1, short-circuited by `[Map] allow zooming = false`). So after
 *    walking a few cells the cache spans far more columns than exist: those stale segments have no
 *    fog mask any more (fog is cleared on unmount and re-pushed only for `mGrid`), and the draw
 *    fills imagery-without-fog SOLID BLACK on purpose. Measuring the floor from the cache therefore
 *    let the player zoom out into a field of black squares and empty background. The grid is exact
 *    here — it is the same `mGrid` the fog export walks — so it is the cap.
 *
 * Intersected rather than either one alone, and the intersection is IGNORED if it comes out empty:
 * a nonsense grid must degrade to the old cache-measured behaviour, never to a map with nothing on
 * it. Interiors keep the cache bounds untouched, for the reason in the first bullet.
 */
private fun mapLocalCellRect(s: MapDsState?, segmentKeys: Set<Pair<Int, Int>>): MapCellRect? {
    if (segmentKeys.isEmpty()) return null
    val xs = segmentKeys.map { it.first }
    val ys = segmentKeys.map { it.second }
    val cached = MapCellRect(xs.min(), xs.max(), ys.min(), ys.max())
    if (s == null || s.interior) return cached
    val clipped = MapCellRect(
        maxOf(cached.xMin, s.gridXMin), minOf(cached.xMax, s.gridXMax),
        maxOf(cached.yMin, s.gridYMin), minOf(cached.yMax, s.gridYMax)
    )
    return if (clipped.xMin <= clipped.xMax && clipped.yMin <= clipped.yMax) clipped else cached
}

/**
 * Zoom limits for ONE map on ONE surface. The floor is "the map exactly fills the viewport width",
 * so neither map can be shrunk into empty background; the ceiling is the fixed cap that stops each
 * map impersonating the other.
 *
 * The LOCAL floor is measured against [mapLocalCellRect] — the content that genuinely exists, which
 * outdoors is the engine's 3x3 window and NOT the larger rolling segment cache.
 */
private fun mapZoomBounds(
    view: MapView, viewportWidth: Float, info: GlobalMapInfo?, segmentKeys: Set<Pair<Int, Int>>,
    s: MapDsState?
): MapZoomBounds = when (view) {
    MapView.GLOBAL -> {
        val floor = if (info != null && info.width > 0 && viewportWidth > 0f)
            viewportWidth / (info.width.toFloat() / info.cellPixels.coerceAtLeast(1))
        else MAP_GLOBAL_FIT
        MapZoomBounds(floor, maxOf(MAP_GLOBAL_MAX, floor))
    }
    MapView.LOCAL -> {
        val cellsAcross = mapLocalCellRect(s, segmentKeys)?.cellsAcross ?: 3
        val floor = if (viewportWidth > 0f) viewportWidth / cellsAcross else 620f
        MapZoomBounds(floor, maxOf(MAP_LOCAL_MAX, floor))
    }
}

/**
 * Clamp the pan so a map always covers its surface — you can never scroll off into background.
 *
 * Asks where the map's rectangle would sit with a ZERO offset, then solves per axis for the offsets
 * that keep it over the viewport. When the map is SMALLER than the viewport on an axis (possible
 * vertically, since the floor only guarantees a width fit) the valid range is empty and the map is
 * centred on that axis rather than jammed against an edge.
 */
private fun mapClampOffset(
    offset: Offset, viewport: Size, scale: Float, view: MapView,
    s: MapDsState?, info: GlobalMapInfo?, segmentKeys: Set<Pair<Int, Int>>, frame: MapLocalFrame
): Offset {
    if (viewport.width <= 0f || viewport.height <= 0f) return offset
    val l: Float; val t: Float; val r: Float; val b: Float
    if (view == MapView.GLOBAL) {
        val gi = info ?: return offset
        val k = scale / gi.cellPixels
        val w = gi.width * k; val h = gi.height * k
        l = viewport.width / 2f - w / 2f; r = l + w
        t = viewport.height / 2f - h / 2f; b = t + h
    } else {
        val st = s ?: return offset
        // The LOADED rect, not the raw segment cache — outdoors the cache outlives the engine's
        // 3x3 window, and panning onto a stale segment shows the same black squares zooming out
        // used to. Zoom and pan share this so they can never disagree about where the map ends.
        val rect = mapLocalCellRect(st, segmentKeys) ?: return offset
        // SEGMENT space, via the same rotation-aware conversion the draw uses — otherwise the clamp
        // disagrees with what is on screen indoors.
        val pr = mapLocalRaw(st.playerX, st.playerY, st, frame)
        l = viewport.width / 2f + (rect.xMin - pr.x) * scale
        r = viewport.width / 2f + (rect.xMax + 1 - pr.x) * scale
        // Y is inverted (segment +Y up, screen +Y down), so the MAX row is the TOP edge.
        t = viewport.height / 2f - ((rect.yMax + 1) - pr.y) * scale
        b = viewport.height / 2f - (rect.yMin - pr.y) * scale
    }
    fun clamp1(off: Float, lo: Float, hi: Float, extent: Float): Float {
        val min = extent - hi
        val max = -lo
        return if (min > max) (min + max) / 2f else off.coerceIn(min, max)
    }
    return Offset(clamp1(offset.x, l, r, viewport.width), clamp1(offset.y, t, b, viewport.height))
}

/**
 * Cross-screen DS map state. Both surfaces are separate compositions in separate windows, so
 * everything they share lives here — the same technique [AlchemyUiState] and [EnchantUiState] use.
 *
 * **Pan/zoom is stored PER MAP, not per screen**, which is what makes swapping non-destructive: a
 * map carries its own view with it when it changes displays, so a swap re-homes it rather than
 * resetting it. (Its zoom FLOOR is re-measured against the new surface's width, so a map moving to a
 * narrower screen can be nudged out to fit — that is the clamp doing its job, not a reset.)
 */
private object MapDsUiState {
    /** false = world on top, local on bottom (the default). Swap exchanges the two. */
    var swapped by mutableStateOf(false)
    val topView: MapView get() = if (swapped) MapView.LOCAL else MapView.GLOBAL
    val bottomView: MapView get() = if (swapped) MapView.GLOBAL else MapView.LOCAL

    /** Each map applies its default zoom and auto-centres ONCE, on the first frame where its
     *  surface has been measured and the data has arrived. Deliberately NOT remembered across
     *  opens: going in and out of buildings invalidates a stored local view anyway, and you almost
     *  always open the map to see where you are NOW rather than where you last looked. */
    var worldInit by mutableStateOf(false)
    var localInit by mutableStateOf(false)

    var worldScale by mutableStateOf(MAP_GLOBAL_FIT)
    var worldOffset by mutableStateOf(Offset.Zero)
    var localScale by mutableStateOf(620f)   // replaced on first measure — see mapLocalDefaultScale
    var localOffset by mutableStateOf(Offset.Zero)

    /**
     * CENTRE is a REQUEST, not an assignment — the action bar bumps this and each surface answers
     * it for the map it currently holds ([MapSurface]).
     *
     * It has to work that way because centring must be CLAMPED, and the button cannot clamp:
     * [mapClampOffset] needs the measured VIEWPORT, and only a surface knows its own (the two
     * displays differ in size, and either map can be on either one). Writing the centred offset
     * straight from the button is exactly the bug this replaced — near a map edge, putting the
     * player dead centre pushes the map's edge inside the viewport and shows background past it.
     * The local map is not exempt: it is player-centred by construction, but the player stands at a
     * FRACTIONAL position inside the middle cell, so at the zoom floor a zero offset still leaves a
     * gap on whichever side they are nearer.
     *
     * 0 means "never pressed", so a surface can tell a real press from its own first composition.
     */
    var centreRequest by mutableStateOf(0)
        private set

    fun requestCentre() { centreRequest++ }

    fun scaleOf(v: MapView) = if (v == MapView.GLOBAL) worldScale else localScale
    fun offsetOf(v: MapView) = if (v == MapView.GLOBAL) worldOffset else localOffset
    fun setScale(v: MapView, value: Float) {
        if (v == MapView.GLOBAL) worldScale = value else localScale = value
    }
    fun setOffset(v: MapView, value: Offset) {
        if (v == MapView.GLOBAL) worldOffset = value else localOffset = value
    }

    /** The marker whose label is showing (a MapPlace, a DoorMarker or a MapNote), its text, and the
     *  MAP it was tapped on. One triple across both surfaces, so only one label is ever up.
     *
     *  [selectedView] is what keeps the label on ONE screen (Aug 21 2026 — it used to appear on both
     *  at once). Deliberately the VIEW and not the screen: the label describes a marker that belongs
     *  to a particular map, so if the maps are swapped while it is up it should travel with its own
     *  map rather than sit over the other one. In practice a swap clears it — see [swapMaps] — but
     *  keying on the view is what makes that a choice rather than the only thing that works.
     *
     *  Always mutate through [select] / [clearSelection]: the marker, its text and its view have to
     *  move together, and the render gate reads all three. */
    var selectedMarker by mutableStateOf<Any?>(null)
        private set
    var selectedLabel by mutableStateOf("")
        private set
    var selectedView by mutableStateOf<MapView?>(null)
        private set

    fun select(marker: Any, label: String, view: MapView) {
        selectedMarker = marker
        selectedLabel = label
        selectedView = view
    }

    fun clearSelection() {
        selectedMarker = null
        selectedLabel = ""
        selectedView = null
    }

    /** Swap the maps between the screens, dismissing any open marker label. The label is dropped
     *  rather than carried because its surface changes underneath it mid-animation, and a name
     *  card that jumps screens reads as a glitch; it is one tap to bring back. */
    fun swapMaps() {
        clearSelection()
        swapped = !swapped
    }

    /** Note composer. [pendingWorld] is where a long-press landed; index >= 0 means editing an
     *  existing note instead of creating one. */
    var noteEditorOpen by mutableStateOf(false)
    var noteEditIndex by mutableStateOf(-1)
    var pendingWorld by mutableStateOf(Offset.Zero)
    var noteDraft by mutableStateOf("")
    var keyboardOpen by mutableStateOf(false)

    fun reset() {
        swapped = false
        worldScale = MAP_GLOBAL_FIT; worldOffset = Offset.Zero
        localScale = 620f; localOffset = Offset.Zero
        worldInit = false; localInit = false
        centreRequest = 0
        clearSelection()
        noteEditorOpen = false; noteEditIndex = -1; noteDraft = ""; keyboardOpen = false
    }
}

/**
 * ONE map surface, used by BOTH screens — the top overlay and the bottom panel each render one of
 * these with a different [view]. Owns its own gesture handling, zoom clamping and hit testing, all
 * against the per-map pan/zoom in [MapDsUiState], so the two surfaces are fully independent and a
 * swap simply hands each map to the other surface.
 *
 * The map imagery is ENGINE-ACCURATE throughout: the same local segment textures the HUD minimap
 * draws, the engine's own world base and explored overlay, and the engine's own fog masks. Only the
 * frame around it is DS-styled.
 *
 * [allowNotePlacement] is world-map-only, by design — a note is placed at a real exterior position,
 * and the local map is the wrong surface to express that on.
 */
/** The map surface's own frame. Shared so the empty placeholder that holds the layout slot before
 *  the first export arrives is pixel-identical to the real surface -- the panel is already there,
 *  it just has no map in it yet, so nothing shifts when the data lands.
 *
 *  **[adaptiveDimTint] lives HERE, on the map surface itself, not on the top overlay's container**
 *  (Aug 22 2026). The DS map is the one feature whose content MOVES between the two screens — the
 *  swap button hands each map to the other surface — so anchoring the dim to a fixed top-screen box
 *  was anchoring it to a position rather than to the thing being drawn. On this modifier it travels
 *  with whichever map is currently up top, and it is a no-op on the bottom surface (see
 *  [rememberMapDimAlpha]: the bottom screen's full-screen [AdaptiveDimOverlay] scrim does that
 *  screen, so the two can never double up).
 *
 *  ORDER IS LOAD-BEARING, and matches [mwPanel]: the tint comes FIRST so the frame's own fill and
 *  bronze border are drawn INSIDE its layer and get tinted too. Put it after `background(...)` and
 *  `SrcAtop` only ever sees the children, leaving the frame at full brightness around a dimmed map.
 *
 *  @Composable purely to read the dim; both call sites are already composable. */
@Composable
private fun Modifier.mapSurfaceFrame(): Modifier =
    this.dimTint(rememberMapDimAlpha())
        .clip(RoundedCornerShape(3.dp)).background(Color(0xFF0B0906))
        .border(2.dp, Bronze, RoundedCornerShape(3.dp))

/**
 * The dim a DS map surface applies to ITSELF — the BOTTOM screen's ramp, even on the top screen.
 *
 * **This is the one place a top-screen surface deliberately does NOT use [adaptiveDimTint], and the
 * reason is that the DS map is not a panel** (Aug 22 2026). [TOP_DIM_ABSOLUTE_MAX_ALPHA] (0.42) was
 * measured for a top-screen PANEL: something already thinned by the manual opacity slider, laid over
 * a live game scene that is itself dark, where dimming past that point costs readability of text
 * sitting on top of moving imagery. None of that describes this surface. The DS map overlay is
 * OPAQUE and full-screen — the game view is completely hidden behind it — so it is functionally a
 * second companion screen, and the constraint the cap exists to protect simply is not present.
 *
 * Keeping the panel cap here produced a visible MISMATCH between the two halves of one feature: in a
 * pitch-dark interior the ramp asks for the same alpha on both surfaces, the bottom screen's scrim
 * delivers it in full, and the top screen clamped to 0.42. Two views of the same map, side by side,
 * at different brightnesses. Reading the bottom screen's alpha instead makes the two exactly equal
 * at every scene and every slider position, because it is now literally the same number.
 *
 * **Returns 0f on the bottom surface, and that is not an optimisation.** There the map is inside
 * `CompanionScreen`'s composition and already under the full-screen [AdaptiveDimOverlay] scrim;
 * tinting as well would darken it TWICE (`1-(1-a)^2`). [LocalIsTopScreen] is the only reliable
 * "which screen am I on" signal — [LocalTopScreenDim] reads 0f both on the bottom AND on the top
 * with dimming switched off, so it cannot answer this.
 *
 * NOTE this deliberately leaves [TOP_DIM_ABSOLUTE_MAX_ALPHA] itself alone: every OTHER top-screen
 * overlay is a real panel over the live game and still wants that cap. The change is which ceiling
 * applies to one surface, not what the ceiling is.
 */
@Composable
private fun rememberMapDimAlpha(): Float =
    if (LocalIsTopScreen.current) rememberBottomScreenDimAlpha() else 0f

@Composable
private fun MapSurface(
    view: MapView,
    /** Bottom surface only: an empty tap (one that hits no marker) closes the whole DS map. The top
     *  overlay deliberately does not, since it sits over the game view. */
    closeOnEmptyTap: Boolean = false,
    modifier: Modifier = Modifier
) {
    val s = GameStateRepository.mapDsState.collectAsState().value
    // The map export is a full round trip behind this overlay mounting (the DisposableEffect's
    // CMP:map_mount:1 -> the native push -> parse), so there are frames where the overlay is up
    // with no state yet. Emitting NOTHING here would drop the parent Column's weight(1f) slot and
    // let the action bar ride to the top of the screen for those frames -- the last of the reported
    // open-flicker. Hold the slot with the empty frame instead. Do not restore the `?: return`.
    if (s == null) {
        Box(modifier.mapSurfaceFrame())
        return
    }
    val exteriorMaps by GameStateRepository.exteriorMapBitmaps.collectAsState()
    val interiorMaps by GameStateRepository.interiorMapBitmaps.collectAsState()
    val fog by GameStateRepository.mapFog.collectAsState()
    val base by GameStateRepository.globalMapBase.collectAsState()
    val overlay by GameStateRepository.globalMapOverlay.collectAsState()
    val info by GameStateRepository.globalMapInfo.collectAsState()
    val notes by GameStateRepository.mapNotes.collectAsState()
    val places by GameStateRepository.mapPlaces.collectAsState()
    val doorMarkers by GameStateRepository.doorMarkers.collectAsState()

    val isWorld = view == MapView.GLOBAL
    // Player heading, and the game's own compass.dds arrow — the same asset and the same maths the
    // HUD minimap uses, so the two agree. rotZ comes from COMPANION_STATS (the general state flow),
    // not from the map export.
    val playerRotZ = GameStateRepository.state.collectAsState().value.rotZ
    val compassBitmap = rememberItemIcon("textures/compass.dds")
    val frame = mapLocalFrame(s.interior, interiorMaps.values.firstOrNull())
    val segmentKeys = if (s.interior) interiorMaps.keys else exteriorMaps.keys
    // Notes belong to whichever map their cell does: exterior notes on the world map, interior ones
    // on the local map. The `ext` flag is computed natively from the marker's own cell id, so it
    // cannot disagree with how the note was filed.
    val myNotes = remember(notes, isWorld) { notes.filter { it.exterior == isWorld } }
    // Door markers the player has actually discovered. Computed once per data change rather than
    // inside the Canvas: it samples a bitmap per marker, and both the draw and the hit test need
    // the same answer — deriving it twice would let a tap find a marker that is not drawn.
    //
    // **`isWorld` IS A KEY, and leaving it out was a bug (Aug 21 2026).** The lambda READS it, so a
    // surface that swapped between the two maps kept whatever it computed under its PREVIOUS view:
    // the top surface starts out showing the world map, caches `emptyList()`, and then took the
    // local map on a swap still holding that empty list — no door markers drawn, and none tappable
    // either, since the hit test shares this list. It presented as "local map icons are missing on
    // the top screen"; it was really "the surface whose view changed", and only looked
    // top-specific because the default layout puts the world map there. The sibling `myNotes` above
    // already keys on `isWorld` for exactly this reason.
    val visibleDoors = remember(doorMarkers, fog, s, frame, isWorld) {
        if (isWorld) emptyList()
        else doorMarkers.filter { mapPositionExplored(it.worldX, it.worldY, s, frame, fog) }
    }

    Box(modifier.mapSurfaceFrame()) {

        // Measure this surface and clamp the map on it. Each surface measures ITSELF, so a map moved
        // between screens is re-clamped against the new width without either surface knowing about
        // the other.
        BoxWithConstraints(Modifier.matchParentSize()) {
            val d = LocalDensity.current
            val wPx = with(d) { maxWidth.toPx() }
            val hPx = with(d) { maxHeight.toPx() }
            val vp = Size(wPx, hPx)
            val bounds = mapZoomBounds(view, wPx, info, segmentKeys, s)
            LaunchedEffect(view, bounds, vp, s, info, segmentKeys, MapDsUiState.scaleOf(view)) {
                // ONE-SHOT INIT: default zoom + centred on the player. Runs on the first frame this
                // surface has a size AND the data it needs, then never again for that map.
                val gi = info   // local val: `info` is a delegated property and cannot smart-cast
                if (isWorld && !MapDsUiState.worldInit && gi != null && wPx > 0f) {
                    MapDsUiState.worldInit = true
                    MapDsUiState.worldScale = MAP_GLOBAL_FIT.coerceIn(bounds.min, bounds.max)
                    MapDsUiState.worldOffset = if (!s.interior)
                        mapCentreOnPlayer(s, gi, MapDsUiState.worldScale) else Offset.Zero
                } else if (!isWorld && !MapDsUiState.localInit && vp.minDimension > 0f) {
                    MapDsUiState.localInit = true
                    // The local map is player-centred by construction, so a zero offset already IS
                    // centred on the player — only the zoom needs setting.
                    MapDsUiState.localScale =
                        mapLocalDefaultScale(vp).coerceIn(bounds.min, bounds.max)
                    MapDsUiState.localOffset = Offset.Zero
                }
                val clamped = MapDsUiState.scaleOf(view).coerceIn(bounds.min, bounds.max)
                if (clamped != MapDsUiState.scaleOf(view)) MapDsUiState.setScale(view, clamped)
                MapDsUiState.setOffset(view, mapClampOffset(
                    MapDsUiState.offsetOf(view), vp, clamped, view, s, info, segmentKeys, frame))
            }

            // CENTRE, answered here rather than in the action bar so the result goes through the
            // SAME clamp every other pan does — see MapDsUiState.centreRequest. Its own effect, not
            // another key on the one above: that one restarts on every zoom change and would then
            // re-centre the map out from under a pinch.
            LaunchedEffect(MapDsUiState.centreRequest, vp, s, info, segmentKeys) {
                if (MapDsUiState.centreRequest == 0) return@LaunchedEffect   // first composition
                // Before the one-shot init the scale is still a pre-measure placeholder, so
                // centring against it would be meaningless; the init centres anyway.
                if (!(if (isWorld) MapDsUiState.worldInit else MapDsUiState.localInit)) return@LaunchedEffect
                if (vp.minDimension <= 0f) return@LaunchedEffect
                val scale = MapDsUiState.scaleOf(view)
                val gi = info   // local val: `info` is a delegated property and cannot smart-cast
                val centred = if (!isWorld) Offset.Zero
                    // Outdoors only: indoors the player's coordinates are in the interior's own
                    // space, so the world map keeps its pan rather than jumping somewhere
                    // meaningless. Re-clamped regardless, which is harmless when nothing moved.
                    else if (gi != null && !s.interior) mapCentreOnPlayer(s, gi, scale)
                    else MapDsUiState.worldOffset
                MapDsUiState.setOffset(view, mapClampOffset(
                    centred, vp, scale, view, s, info, segmentKeys, frame))
            }
        }

        Box(
            Modifier
                .fillMaxSize()
                .pointerInput(view, s, info, segmentKeys) {
                    // One detector for pan AND pinch: a single finger reports pan with zoom == 1,
                    // two fingers report both at once, so there is no mode switch to arbitrate.
                    // This is the whole reason the DS map is Compose rather than a restyled native
                    // window — OpenMW's SDL layer discards every touch and gesture event before
                    // MyGUI sees it, so the native map has only ever had single-finger drag.
                    detectTransformGestures { centroid, pan, zoom, _ ->
                        val vp = Size(size.width.toFloat(), size.height.toFloat())
                        val bounds = mapZoomBounds(view, vp.width, info, segmentKeys, s)
                        val before = MapDsUiState.scaleOf(view)
                        val after = (before * zoom).coerceIn(bounds.min, bounds.max)
                        // Anchor on the pinch centroid so whatever is under the fingers stays there.
                        // The map is drawn from an origin of (viewportCentre + offset), so keeping a
                        // point fixed is centroid + (centre + offset - centroid) * k - centre.
                        // Omitting the `centre` terms pivots around the panel's top-left instead — a
                        // constant centre*(k-1) diagonal drift. Use the ACTUAL ratio, not the
                        // requested one, or panning dies at a zoom limit.
                        val k = after / before
                        val centre = Offset(vp.width / 2f, vp.height / 2f)
                        val moved = centroid + (centre + MapDsUiState.offsetOf(view) - centroid) * k -
                            centre + pan
                        MapDsUiState.setScale(view, after)
                        MapDsUiState.setOffset(view, mapClampOffset(
                            moved, vp, after, view, s, info, segmentKeys, frame))
                    }
                }
                .pointerInput(view, places, info, doorMarkers, myNotes, s, interiorMaps, closeOnEmptyTap) {
                    detectTapGestures(
                        onLongPress = { tap ->
                            // NOTE PLACEMENT — world map only. A note is an exterior position, and
                            // the local map is the wrong surface to express that on.
                            if (!isWorld) return@detectTapGestures
                            val gi = info ?: return@detectTapGestures
                            val vp = Size(size.width.toFloat(), size.height.toFloat())
                            val k = MapDsUiState.scaleOf(view) / gi.cellPixels
                            val o = mapWorldOrigin(gi, k, vp, MapDsUiState.offsetOf(view))
                            val w = mapWorldFromScreen(tap, s, gi, k, o.x, o.y)
                            UiSounds.play(UiSounds.Cue.TOGGLE)
                            MapDsUiState.pendingWorld = w
                            MapDsUiState.noteEditIndex = -1
                            MapDsUiState.noteDraft = ""
                            MapDsUiState.noteEditorOpen = true
                            MapDsUiState.keyboardOpen = true
                        },
                        onTap = { tap ->
                            val vp = Size(size.width.toFloat(), size.height.toFloat())
                            val px = MapDsUiState.scaleOf(view)
                            val off = MapDsUiState.offsetOf(view)
                            val cx = vp.width / 2f + off.x
                            val cy = vp.height / 2f + off.y
                            val cells = if (isWorld) MAP_PLACE_CELLS else MAP_DOOR_CELLS
                            val hit = maxOf(px * cells, MAP_PLACE_MIN_HIT.toPx())

                            // Candidates as (key, screen position, label) so one nearest-wins test
                            // serves places, doors and notes alike. NOTES FIRST in the list so a
                            // note stacked on a town wins the tie — a note is the only thing here
                            // the player can act on.
                            val candidates = buildList<Triple<Any, Offset, String>> {
                                val gi = info
                                if (isWorld && gi != null) {
                                    val k = px / gi.cellPixels
                                    val o = mapWorldOrigin(gi, k, vp, off)
                                    myNotes.forEach {
                                        add(Triple(it, mapWorldPos(it.worldX, it.worldY, s, gi, k, o.x, o.y),
                                            it.note))
                                    }
                                    places.filter { it.visible }.forEach {
                                        add(Triple(it, mapPlaceCentre(it, gi, k, o.x, o.y),
                                            if (it.count > 1) "${it.name} (${it.count})" else it.name))
                                    }
                                } else {
                                    myNotes.forEach {
                                        add(Triple(it, mapLocalPos(it.worldX, it.worldY, s, frame, px, cx, cy),
                                            it.note))
                                    }
                                    // Same fog gate as the draw — a marker that is not on screen
                                    // must not be tappable either, or an undiscovered door leaks
                                    // its name through a tap on empty fog.
                                    visibleDoors.forEach {
                                        add(Triple(it, mapLocalPos(it.worldX, it.worldY, s, frame, px, cx, cy),
                                            it.name))
                                    }
                                }
                            }
                            val found = candidates
                                .filter { (_, c, _) -> (c - tap).getDistance() <= hit }
                                .minByOrNull { (_, c, _) -> (c - tap).getDistance() }

                            when {
                                found != null && found.first != MapDsUiState.selectedMarker -> {
                                    // `view` is this surface's map, so the label shows only here.
                                    MapDsUiState.select(
                                        found.first, found.third.ifBlank { "(empty note)" }, view)
                                }
                                // A label is up: this tap DISMISSES it and is consumed — it must not
                                // also close the map. A second tap then closes. Same rule the HUD
                                // minimap uses for its door-marker bubble, and it is what stops a
                                // dismiss from being read as "close".
                                MapDsUiState.selectedMarker != null -> {
                                    MapDsUiState.clearSelection()
                                }
                                // Empty tap on the bottom surface: close the DS map. Routed through
                                // the same toggle the minimap tap uses, so the native mode pops via
                                // the engine's own path rather than a special case.
                                closeOnEmptyTap -> {
                                    UiSounds.play(UiSounds.Cue.TOGGLE)
                                    CompanionActions.openWorldMap()
                                }
                                else -> MapDsUiState.clearSelection()
                            }
                        }
                    )
                }
        ) {
            // Nothing is drawn until this map has applied its default zoom and centring. The
            // seed values in MapDsUiState are pre-measure placeholders — drawing with them paints
            // one frame at the wrong scale (typically fully zoomed out) before the LaunchedEffect
            // above corrects it, which is the second half of the open flicker. An empty panel for
            // that frame is the honest thing to show.
            val ready = if (isWorld) MapDsUiState.worldInit else MapDsUiState.localInit
            if (ready) Canvas(Modifier.fillMaxSize()) {
                val px = MapDsUiState.scaleOf(view)
                val off = MapDsUiState.offsetOf(view)
                val cx = size.width / 2f + off.x
                val cy = size.height / 2f + off.y

                if (!isWorld) {
                    // ---- LOCAL: segment grid, centred on the player ----
                    // Positions go through mapLocalRaw, which handles the interior NorthMarker
                    // rotation. Plain world/cellSize is correct only for exteriors.
                    val pr = mapLocalRaw(s.playerX, s.playerY, s, frame)
                    for ((gx, gy) in segmentKeys) {
                        val bmp = if (s.interior) interiorMaps[Pair(gx, gy)]?.bitmap
                                  else exteriorMaps[Pair(gx, gy)]
                        val left = cx + (gx - pr.x) * px
                        val top = cy - ((gy + 1) - pr.y) * px
                        if (bmp != null) {
                            drawImage(bmp.asImageBitmap(),
                                dstOffset = IntOffset(left.toInt(), top.toInt()),
                                dstSize = IntSize(px.toInt(), px.toInt()))
                        }
                        val f = fog[Triple(gx, gy, s.interior)]
                        if (f != null) {
                            // ALPHA_8, opaque where unexplored; drawn over the segment in black,
                            // which is how vanilla composites it.
                            drawImage(f.asImageBitmap(),
                                dstOffset = IntOffset(left.toInt(), top.toInt()),
                                dstSize = IntSize(px.toInt(), px.toInt()),
                                colorFilter = ColorFilter.tint(Color.Black))
                        } else if (bmp != null) {
                            // Imagery but NO fog mask means the player has never been in this cell:
                            // the engine only calls initFogOfWar() for its own grid, while this
                            // app's export force-renders the eight neighbours too. Drawing nothing
                            // would render them FULLY EXPLORED — a free reveal — so fill solid.
                            drawRect(Color.Black, topLeft = Offset(left, top), size = Size(px, px))
                        }
                    }
                    // Fog-gated: vanilla hides an undiscovered door behind the fog layer, and a
                    // Canvas has no layers to do that for us. See mapPositionExplored.
                    visibleDoors.forEach { dm ->
                        val c = mapLocalPos(dm.worldX, dm.worldY, s, frame, px, cx, cy)
                        val half = px * MAP_DOOR_CELLS / 2f
                        drawRect(
                            color = if (MapDsUiState.selectedMarker == dm) BoneBright else BronzeLight,
                            topLeft = Offset(c.x - half, c.y - half), size = Size(half * 2f, half * 2f),
                            style = Stroke(width = (half * 0.3f).coerceIn(1.5f, 4f)))
                    }
                    myNotes.forEach { n ->
                        val c = mapLocalPos(n.worldX, n.worldY, s, frame, px, cx, cy)
                        drawMapNote(c, px * MAP_NOTE_CELLS / 2f, MapDsUiState.selectedMarker == n)
                    }
                    // Player arrow LAST so nothing can cover it. Indoors the heading is offset by
                    // the map's own rotation — and SUBTRACTED, not added: the vertical bitmap flip
                    // inverts the arrow's rotation sense, so position uses +angle (matching the
                    // engine) while the arrow's screen convention is the mirror of it. Same
                    // reasoning, and the same sign, as the HUD minimap.
                    val deg = playerRotZ * (180f / PI.toFloat()) - frame.angle * (180f / PI.toFloat())
                    drawPlayerArrow(
                        Offset(cx, cy), px * MAP_DOOR_CELLS * MAP_ARROW_SCALE_LOCAL,
                        deg, compassBitmap)
                } else {
                    // ---- WORLD: base terrain + explored overlay ----
                    val gi = info
                    val b = base
                    if (gi != null && b != null) {
                        val k = px / gi.cellPixels
                        val o = mapWorldOrigin(gi, k, Size(size.width, size.height), off)
                        val w = (gi.width * k).toInt(); val h = (gi.height * k).toInt()
                        drawImage(b.asImageBitmap(),
                            dstOffset = IntOffset(o.x.toInt(), o.y.toInt()), dstSize = IntSize(w, h))
                        overlay?.let {
                            drawImage(it.asImageBitmap(),
                                dstOffset = IntOffset(o.x.toInt(), o.y.toInt()), dstSize = IntSize(w, h))
                        }
                        places.filter { it.visible }.forEach { p ->
                            val c = mapPlaceCentre(p, gi, k, o.x, o.y)
                            val half = px * MAP_PLACE_CELLS / 2f
                            drawRect(
                                color = if (MapDsUiState.selectedMarker == p) BoneBright else BronzeLight,
                                topLeft = Offset(c.x - half, c.y - half),
                                size = Size(half * 2f, half * 2f),
                                style = Stroke(width = (px * 0.045f).coerceIn(1.5f, 6f)))
                        }
                        myNotes.forEach { n ->
                            val c = mapWorldPos(n.worldX, n.worldY, s, gi, k, o.x, o.y)
                            drawMapNote(c, px * MAP_PLACE_CELLS / 2.4f, MapDsUiState.selectedMarker == n)
                        }
                        // Player position — OUTDOORS ONLY. Indoors the player's coordinates are in
                        // the interior's own space and mean nothing here; vanilla resolves a
                        // last-known-exterior position, which is not exported, so the marker is
                        // omitted rather than drawn somewhere wrong.
                        if (!s.interior) {
                            val c = mapWorldPos(s.playerX, s.playerY, s, gi, k, o.x, o.y)
                            // No interior offset here: the world map is exterior-only, so the
                            // heading is the raw yaw.
                            drawPlayerArrow(c, px * MAP_PLACE_CELLS * MAP_ARROW_SCALE_WORLD,
                                playerRotZ * (180f / PI.toFloat()), compassBitmap)
                        }
                    }
                }
            }

            // Tapped marker's label. Auto-dismissed like the minimap's door-marker bubble.
            //
            // Only on the surface whose map was actually tapped: the state is shared by both
            // surfaces, so without this gate one tap raised the same card on BOTH screens. The
            // auto-dismiss timer sits inside the gate on purpose — exactly one surface owns the
            // selection, so exactly one timer runs it out.
            MapDsUiState.selectedMarker?.takeIf { MapDsUiState.selectedView == view }?.let { marker ->
                LaunchedEffect(marker) {
                    delay(MAP_PLACE_LABEL_MS)
                    if (MapDsUiState.selectedMarker == marker) MapDsUiState.clearSelection()
                }
                val isNote = marker is MapNote
                Row(
                    Modifier.align(Alignment.TopCenter).padding(top = 8.dp)
                        .clip(RoundedCornerShape(3.dp))
                        .background(Color(0xF2201A12))
                        .border(1.dp, BronzeLight, RoundedCornerShape(3.dp))
                        .padding(horizontal = 10.dp, vertical = 7.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(MapDsUiState.selectedLabel, color = BoneBright, fontSize = 14.sp,
                        fontFamily = MwDisplay, maxLines = 2, overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.widthIn(max = 320.dp))
                    // Note CRUD, relocated from the old list panel onto the marker itself — the
                    // backend is unchanged, only the entry point moved.
                    if (isNote) {
                        val n = marker as MapNote
                        Spacer(Modifier.width(10.dp))
                        MapLabelAction("Edit") {
                            MapDsUiState.noteEditIndex = n.index
                            MapDsUiState.noteDraft = n.note
                            MapDsUiState.noteEditorOpen = true
                            MapDsUiState.keyboardOpen = true
                            MapDsUiState.clearSelection()
                        }
                        Spacer(Modifier.width(6.dp))
                        MapLabelAction("Delete", BarterRed) {
                            CompanionActions.mapDeleteNote(n.index)
                            MapDsUiState.clearSelection()
                        }
                    }
                }
            }
        }
    }
}

/** The player marker: the game's OWN `compass.dds` arrow, rotated to face. Falls back to the drawn
 *  arrow while the texture is still being extracted or if extraction fails — the same asset, the
 *  same fallback and the same neutral "up" orientation the HUD minimap uses, so the two cannot look
 *  like different markers. */
private fun DrawScope.drawPlayerArrow(
    c: Offset, side: Float, degrees: Float, compass: androidx.compose.ui.graphics.ImageBitmap?
) {
    // [side] is in px, derived from the marker box side times MAP_ARROW_SCALE_* — so the arrow
    // scales with the map exactly as the icons do, just drawn proportionally bigger. Taking the
    // SIDE rather than a radius is deliberate: the call sites pass the same `px * <cells>`
    // expression the boxes use, so the two cannot drift apart.
    if (compass != null) {
        rotate(degrees = degrees, pivot = c) {
            drawImage(
                image = compass,
                dstOffset = IntOffset((c.x - side / 2f).toInt(), (c.y - side / 2f).toInt()),
                dstSize = IntSize(side.toInt().coerceAtLeast(1), side.toInt().coerceAtLeast(1))
            )
        }
    } else {
        // drawArrow spans about 2.4r vertically, so this keeps the fallback's footprint equal to
        // the box it stands in for.
        drawArrow(c.x, c.y, side / 2.4f, degrees)
    }
}

/** A note pin — a filled diamond, deliberately a different SHAPE from the hollow squares used for
 *  door markers and discovered locations, so the two are distinguishable at any zoom. */
private fun DrawScope.drawMapNote(c: Offset, half: Float, selected: Boolean) {
    val r = half.coerceAtLeast(4f)
    val path = Path().apply {
        moveTo(c.x, c.y - r); lineTo(c.x + r, c.y); lineTo(c.x, c.y + r); lineTo(c.x - r, c.y); close()
    }
    drawPath(path, color = if (selected) BoneBright else BarterRed)
    drawPath(path, color = Color.Black, style = Stroke(width = (r * 0.25f).coerceIn(1f, 3f)))
}

@Composable
private fun MapLabelAction(label: String, colour: Color = BronzeLight, onTap: () -> Unit) {
    Box(
        Modifier.clip(RoundedCornerShape(2.dp)).background(SlotBg)
            .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
            .clickable { UiSounds.play(UiSounds.Cue.TOGGLE); onTap() }
            .padding(horizontal = 10.dp, vertical = 6.dp)
    ) { Text(label, color = colour, fontSize = 12.sp, fontFamily = MwDisplay) }
}

/** TOP-screen map surface — whichever map is currently assigned to the top display. */
@Composable
fun MapDsTopOverlay() {
    // No `?: return` here either: MapSurface now draws its own empty frame, so the panel is painted
    // from the first frame and the game view never shows through the gap before the export lands.
    // The backdrop is dimmed by COLOUR, not by a second tint: the map surface inside it carries its
    // own (see mapSurfaceFrame), and a tint here would NEST around it and darken the map twice —
    // 1-(1-a)^2 instead of a. For an opaque colour, lerping toward black IS compositing black over
    // it, so this lands on exactly the value a scrim would have produced. Same two-halves trick
    // CompanionDropdownMenu uses for its container. It reads the SAME rememberMapDimAlpha() the
    // surface does, so the frame and the map it frames can never disagree.
    Box(
        Modifier.fillMaxSize()
            .background(dimColor(StoneDark, rememberMapDimAlpha()))
            .padding(8.dp)
    ) {
        MapSurface(MapDsUiState.topView, modifier = Modifier.fillMaxSize())
    }
}

/**
 * BOTTOM screen: the other map surface, plus the action bar.
 *
 * **This composable's `DisposableEffect` IS the native suppression flag** — mounting sends
 * `CMP:map_mount:1` and disposing sends `:0`, which makes the flag mount-scoped by construction
 * rather than by discipline, and is why the combined inventory view and the pinned HUD map stay
 * native.
 */
@Composable
private fun MapDsControls() {
    // No map state is collected here any more. Centring used to be computed in this composable and
    // needed it; now the surfaces do that (MapDsUiState.centreRequest), so subscribing would only
    // recompose the whole panel every time the map state or the global-map info changed.
    DisposableEffect(Unit) {
        MapDsUiState.reset()
        CompanionActions.mapMount(true)
        onDispose {
            CompanionActions.mapMount(false)
            GameStateRepository.clearMapDs()
            MapDsUiState.reset()
        }
    }

    Box(
        Modifier.fillMaxSize().zIndex(18f)
            .pointerInput(Unit) { detectTapGestures { } }
            .background(StoneDark)
    ) {
        Column(Modifier.fillMaxSize().padding(horizontal = 8.dp, vertical = 6.dp)) {
            MapSurface(
                MapDsUiState.bottomView,
                closeOnEmptyTap = true,
                modifier = Modifier.weight(1f).fillMaxWidth()
            )
            Spacer(Modifier.height(8.dp))
            MapDsActionBar(
                onSwap = { MapDsUiState.swapMaps() },
                onCentre = {
                    // CENTRE recentres BOTH maps on the player, because both are on screen at once
                    // and "where am I" is the question either one is being asked.
                    //
                    // Only REQUESTED here — each surface performs it, because the result has to go
                    // through mapClampOffset and only a surface knows its own measured viewport.
                    // This used to assign the two offsets directly, which let a player near a map
                    // edge centre the map off its own bounds and show background past the edge.
                    MapDsUiState.requestCentre()
                },
                onClose = {
                    // Closes via the same toggle the minimap tap uses, so the native mode pops
                    // through the engine's own path rather than a special case.
                    CompanionActions.openWorldMap()
                }
            )
        }

        // Note keyboard — touch-only by design, so it has to live on this panel even when the
        // long-press happened on the top screen.
        if (MapDsUiState.keyboardOpen) {
            TextInputOverlay(
                initialText = MapDsUiState.noteDraft,
                title = if (MapDsUiState.noteEditIndex >= 0) "EDIT NOTE" else "NEW NOTE",
                onConfirm = { text ->
                    MapDsUiState.keyboardOpen = false
                    MapDsUiState.noteEditorOpen = false
                    if (MapDsUiState.noteEditIndex >= 0) {
                        CompanionActions.mapEditNote(MapDsUiState.noteEditIndex, text)
                    } else {
                        // exterior = true: a world-map note is an exterior position even when the
                        // player is standing in an interior. Without the flag the engine would file
                        // it under the interior cell (getCellIdInWorldSpace ignores x/y there) and
                        // it would never be drawn.
                        CompanionActions.mapAddNote(
                            MapDsUiState.pendingWorld.x, MapDsUiState.pendingWorld.y,
                            exterior = true, note = text)
                    }
                },
                onCancel = {
                    MapDsUiState.keyboardOpen = false
                    MapDsUiState.noteEditorOpen = false
                }
            )
        }
    }
}

/** Action bar along the bottom of the map panel. Styled as the app's [BottomTabBar] is — same frame,
 *  same inner boxes — but these are ACTIONS, not a selection, so none is ever shown active. */
@Composable
private fun MapDsActionBar(onSwap: () -> Unit, onCentre: () -> Unit, onClose: () -> Unit) {
    Row(
        Modifier.fillMaxWidth()
            .clip(RoundedCornerShape(3.dp))
            .background(FloatStone)
            .border(2.dp, Bronze, RoundedCornerShape(3.dp))
            .padding(6.dp),
        horizontalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        listOf("Swap Screens" to onSwap, "Centre" to onCentre, "Close" to onClose).forEach { (label, action) ->
            Box(
                Modifier.weight(1f)
                    .clip(RoundedCornerShape(2.dp))
                    .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
                    .clickable { UiSounds.play(UiSounds.Cue.TOGGLE); action() }
                    .padding(vertical = 13.dp),
                contentAlignment = Alignment.Center
            ) {
                Text(label.uppercase(), color = Bone, fontSize = 14.sp, fontFamily = MwDisplay,
                    textAlign = TextAlign.Center)
            }
        }
    }
}


/* ================= DS Enchanting ================= */

/**
 * Cross-screen enchanting UI state. Both companion surfaces are separate compositions in separate
 * windows, so anything one has to tell the other lives here — the same technique [AlchemyUiState]
 * uses. All of it is pure presentation: it only decides which popup is drawn and which command a
 * tap will send.
 */
private object EnchantUiState {
    /** Which slot picker is open: "item", "soul", or null. Drawn on the BOTTOM screen even though
     *  the slots can also be reached from there — vanilla puts every one of these popups on the
     *  window's own screen, and the bottom panel is the one with the room and the touch precision. */
    var picker by mutableStateOf<String?>(null)
    /** True while the BOTTOM screen's name keyboard is up (raised by a tap on the TOP screen's name
     *  field). The keyboard has to live on the bottom panel — it is touch-only by design. */
    var nameComposer by mutableStateOf(false)
    /** Browse-list filter. Purely presentational. */
    var filter by mutableStateOf("")

    /** Non-null while the Skill / Attribute selector is up — the third popup type, raised by the
     *  engine (COMPANION_ENCHANTING_ARGPICK) when the tapped effect targets one. */
    var argPick by mutableStateOf<EffectArgPick?>(null)

    fun reset() {
        picker = null
        nameComposer = false
        filter = ""
        argPick = null
        EffectEditorState.close()
    }
}

/**
 * The effect editor's working copy, SHARED by every screen that opens it — enchanting today,
 * spellmaking next. It lives outside those screens' own UI state for the same reason
 * `EffectEditorBase` owns the editor natively: `EditEffectDialog`, its slider bounds and its
 * add-then-remove-on-cancel semantics belong to the editor, not to whatever window raised it.
 *
 * Mirrors the native working copy: the values are pushed to the engine live (via
 * [EffectEditorActions.push]) so the top-screen readout and the cost figures track the sliders, and
 * OK / Cancel are what commit or revert. Only ONE editor can be open at a time (both owning modes
 * pause the sim and neither can raise the other), so a single object is enough.
 */
private object EffectEditorState {
    var index by mutableStateOf(-1)
    var isNew by mutableStateOf(false)
    var range by mutableStateOf(EffectRange.SELF)
    var magMin by mutableStateOf(1)
    var magMax by mutableStateOf(1)
    var duration by mutableStateOf(1)
    var area by mutableStateOf(0)

    val editing: Boolean get() = index >= 0

    /** Seed from the effect as the ENGINE actually stored it — for a new effect that is after the
     *  native opening-range override, so the popup opens on the range the engine chose. */
    fun open(index: Int, isNew: Boolean, range: Int, magMin: Int, magMax: Int, duration: Int, area: Int) {
        this.index = index
        this.isNew = isNew
        this.range = range
        this.magMin = magMin
        this.magMax = magMax
        this.duration = duration
        this.area = area
    }

    fun close() {
        index = -1
        isNew = false
    }
}

/**
 * The commands the shared effect editor drives. One bundle per owning screen, so the popup itself
 * knows nothing about which `CMP:` family it is talking to.
 *
 * [push] sends the live working copy as one `*_effect_set`; the engine clamps and range-repairs it
 * and republishes, so this is fire-and-forget. [delete] / [ok] / [cancel] map to the engine's own
 * handlers — in particular [cancel] must route natively, because deciding between erasing a NEW
 * effect and restoring an EDITED one is `EditEffectDialog::exit()`'s two halves.
 */
private class EffectEditorActions(
    val push: () -> Unit,
    val delete: (Int) -> Unit,
    val ok: () -> Unit,
    val cancel: () -> Unit
)

/** How long the enchanting result/validation banner stays up. Matched to alchemy's. */
private const val ENCHANT_MSG_MS = 4200L

/** Push the editor's working values at the engine. Called on every slider tick and range change, so
 *  the live readout, the Enchantment X/Y figure and the Cast Cost all move with the sliders — the
 *  native editor behaves the same way (each handler fires eventEffectModified immediately). */
/** Enchanting's binding of the shared editor to its own CMP: family. Spellmaking gets a sibling
 *  bundle; the popup itself knows about neither. */
private val EnchantEditorActions = EffectEditorActions(
    push = {
        if (EffectEditorState.editing) CompanionActions.enchantSetEffect(
            EffectEditorState.index,
            EffectEditorState.range,
            EffectEditorState.magMin,
            EffectEditorState.magMax,
            EffectEditorState.duration,
            EffectEditorState.area
        )
    },
    delete = { index -> CompanionActions.enchantDeleteEffect(index) },
    ok = { CompanionActions.enchantEffectOk() },
    cancel = { CompanionActions.enchantEffectCancel() }
)

/**
 * BOTTOM-screen enchanting: the item and soul slots, the Magic Effects browse list, the cast-type
 * and Buy/Cancel controls, and ALL THREE popup types (item/soul picker, effect editor, skill or
 * attribute selector).
 *
 * TOUCH ONLY, by design — the companion panel is `FLAG_NOT_FOCUSABLE`, so no D-pad input reaches it.
 *
 * PRESENTATION ONLY. Every tap sends a `CMP:enchant_*` command to the native EnchantingDialog and
 * the screen is redrawn from the batch that comes back, so the cast-style state machine, the
 * accumulating per-effect cost, the capacity check, the seven Buy validations and the self-enchant
 * roll are all still the engine's.
 */
@Composable
private fun EnchantingOverlay(session: EnchantSession) {
    DisposableEffect(Unit) {
        EnchantUiState.reset()
        onDispose { EnchantUiState.reset() }
    }

    var searching by remember { mutableStateOf(false) }
    val message by GameStateRepository.enchantMessage.collectAsState()
    val argPick by GameStateRepository.enchantArgPick.collectAsState()
    val editReq by GameStateRepository.enchantEdit.collectAsState()

    // The engine drives both popups: tapping a browse row sends _add, and the ENGINE decides whether
    // that means "pick a skill first" or "open the editor". Keyed on the sequence number so adding
    // the same effect twice raises the popup twice.
    LaunchedEffect(argPick?.second) {
        argPick?.let { (pick, _) ->
            EnchantUiState.argPick = pick
            GameStateRepository.clearEnchantArgPick()
        }
    }
    LaunchedEffect(editReq?.second) {
        editReq?.let { (req, _) ->
            // Seed the editor from the effect as the engine actually stored it — for a NEW effect
            // that is after companionFirstRange has overridden the range, so the popup opens on the
            // first LEGAL range rather than on vanilla's cascade result.
            val eff = GameStateRepository.enchantSession.value?.effects?.getOrNull(req.index)
            EffectEditorState.open(
                index = req.index,
                isNew = req.isNew,
                range = eff?.range ?: EffectRange.SELF,
                magMin = eff?.magMin ?: 1,
                magMax = eff?.magMax ?: 1,
                duration = eff?.duration ?: 1,
                area = eff?.area ?: 0
            )
            EnchantUiState.argPick = null
            GameStateRepository.clearEnchantEdit()
        }
    }

    val visible = remember(session.available, EnchantUiState.filter) {
        val needle = EnchantUiState.filter.trim().lowercase()
        if (needle.isEmpty()) session.available
        else session.available.filter { it.name.lowercase().contains(needle) }
    }

    // ---- Controller navigation --------------------------------------------------------------
    // Native already swallows the controller in GUI mode while this screen is up (enchantNav is in
    // EngineActivity's setCompanionNavActive combine) and re-emits it as COMPANION_NAV_*; nothing
    // consumed those events until now. The bottom screen never receives Android input — see the
    // controller-nav design note in CLAUDE_ENGINE.md.
    //
    // ONE lambda per action, shared by the touch and controller paths, so the two can never diverge
    // (the alchemy convention). The slot actions keep the tap semantics exactly: a FILLED slot
    // CLEARS, an empty one opens the picker — so L1/R1 are "the item/soul slot button", not "open
    // the picker unconditionally", which would silently do nothing on a filled slot.
    val itemSlotAction: () -> Unit = {
        UiSounds.play(UiSounds.Cue.TOGGLE)
        if (session.item.present) CompanionActions.enchantClearItem()
        else EnchantUiState.picker = "item"
    }
    val soulSlotAction: () -> Unit = {
        UiSounds.play(UiSounds.Cue.TOGGLE)
        if (session.soul.present) CompanionActions.enchantClearSoul()
        else EnchantUiState.picker = "soul"
    }
    val addEffect: (EffectAvail) -> Unit = { avail ->
        UiSounds.play(UiSounds.Cue.TOGGLE)
        CompanionActions.enchantAddEffect(avail.id)
    }
    val castTypeAction: () -> Unit = {
        // Gated exactly as the button is: the engine answers whether this item has anything to
        // cycle to, and a locked item (scroll/ammo, or a bow without a big enough soul) must read
        // as inert on the controller too, not silently do nothing different from the button.
        if (session.castCycle) {
            UiSounds.play(UiSounds.Cue.TOGGLE)
            CompanionActions.enchantCastTypeNext()
        }
    }
    val buyAction: () -> Unit = {
        UiSounds.play(UiSounds.Cue.ACTION)
        CompanionActions.enchantBuy()
    }

    // Any popup open = that popup owns input. The main loop yields (enabled = false) and B is
    // re-routed: registering the cancelable-modal bridge flips the native atomic so B arrives as
    // NAV_CANCEL instead of falling through to exitCurrentGuiMode, which would pop the whole
    // enchanting mode out from under an open picker. Persuasion popup is the template.
    val popupOpen = EnchantUiState.picker != null || EnchantUiState.argPick != null ||
        EffectEditorState.editing || searching || EnchantUiState.nameComposer
    DisposableEffect(popupOpen) {
        if (popupOpen) {
            ModalNav.count++
            CompanionActions.setModalCancelOpen(true)
        }
        onDispose {
            if (popupOpen) {
                ModalNav.count--
                if (ModalNav.count == 0) CompanionActions.setModalCancelOpen(false)
            }
        }
    }

    // B while a popup is up closes the TOPMOST one. Its own collector, because the main list loop
    // is disabled exactly when this is needed. Order mirrors the render order below (later = drawn
    // on top): the two keyboards, then the editor, then the arg picker, then the item/soul picker.
    val popupOpenState = rememberUpdatedState(popupOpen)
    val searchingState = rememberUpdatedState(searching)
    LaunchedEffect(Unit) {
        var lastSeq = GameStateRepository.navEvent.value?.seq ?: -1L
        GameStateRepository.navEvent.collect { ev ->
            if (ev == null || ev.seq <= lastSeq) return@collect
            lastSeq = ev.seq
            if (ev !is NavEvent.Cancel || !popupOpenState.value) return@collect
            when {
                searchingState.value -> searching = false
                EnchantUiState.nameComposer -> EnchantUiState.nameComposer = false
                EffectEditorState.editing -> {
                    // Through the ENGINE, never by just closing the popup: cancel erases a
                    // newly-added effect and restores an edited one, and only the native handler
                    // knows which of the two this was.
                    CompanionActions.enchantEffectCancel()
                    EffectEditorState.close()
                }
                EnchantUiState.argPick != null -> EnchantUiState.argPick = null
                EnchantUiState.picker != null -> EnchantUiState.picker = null
            }
        }
    }

    val listState = rememberLazyListState()
    val focusIndex = rememberListNavFocus(
        itemCount = visible.size,
        enabled = !popupOpen,
        onConfirm = { i -> visible.getOrNull(i)?.let(addEffect) },
        onAction1 = buyAction,          // X
        onAction2 = castTypeAction,     // Y
        onL1 = itemSlotAction,
        onR1 = soulSlotAction,
        // R3 → toggle the info popup for the focused effect. EFFECT, not item/spell: the id is a
        // MagicEffect RefId and only companion.lua's `effect:` branch can resolve it.
        onInfo = { i ->
            visible.getOrNull(i)?.let { ItemInfoPopupState.toggle(it.id, it.name, null, kind = InfoKind.EFFECT) }
        },
        // Follow the focus SYNCHRONOUSLY (before recomposition) so the newly focused row re-reports
        // its anchor during the ensuing layout pass — same reason as the spell-buying list.
        onFocusChanged = { i ->
            if (ItemInfoPopupState.isOpen) {
                visible.getOrNull(i)?.let { ItemInfoPopupState.follow(it.id, it.name, null, kind = InfoKind.EFFECT) }
            }
        },
    )
    LaunchedEffect(focusIndex) {
        if (focusIndex in visible.indices) listState.animateScrollToItem(focusIndex)
    }

    Box(
        Modifier
            .fillMaxSize()
            .zIndex(18f)
            // Swallow stray taps: this fully replaces a native window and there is no
            // tap-outside-to-dismiss (Cancel is an explicit button, as in vanilla).
            .pointerInput(Unit) { detectTapGestures { } }
            .background(StoneDark)
    ) {
        Column(Modifier.fillMaxSize().padding(horizontal = 8.dp, vertical = 6.dp)) {

            // --- Header ---------------------------------------------------------------------------
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                Text(
                    "ENCHANTING",
                    color = BronzeLight, fontSize = 18.sp, fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.weight(1f))
                // Gold only matters when there is a bill to pay; self-enchanting costs nothing.
                if (session.showPrice) {
                    Text(
                        "Gold: ${session.gold}",
                        color = BronzeLight, fontSize = 15.sp, fontFamily = MwData
                    )
                }
            }
            Spacer(Modifier.height(4.dp))
            Box(Modifier.fillMaxWidth().height(1.dp).background(Bronze))
            Spacer(Modifier.height(6.dp))

            // --- Item + soul slots ------------------------------------------------------------------
            // Tap-to-remove is a straight empty/filled branch, exactly as onSelectItem/onSelectSoul
            // do it: an empty slot opens the picker, a filled one CLEARS. So changing a filled slot
            // takes two taps. The asymmetry between the two clears (the soul clear also re-runs the
            // cast style and refreshes the effects view) is handled natively.
            Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                EnchantSlotBox(
                    label = "ITEM",
                    slot = session.item,
                    detail = if (session.item.present) "${session.maxPoints} pts" else "",
                    modifier = Modifier.weight(1f),
                    hint = "L1",
                    onTap = itemSlotAction
                )
                EnchantSlotBox(
                    label = "SOUL",
                    slot = session.soul,
                    detail = if (session.soul.present) "${session.soul.charge}" else "",
                    modifier = Modifier.weight(1f),
                    hint = "R1",
                    onTap = soulSlotAction
                )
            }

            Spacer(Modifier.height(6.dp))

            // --- Filter ------------------------------------------------------------------------------
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                Box(
                    Modifier
                        .weight(1f)
                        .clip(RoundedCornerShape(3.dp))
                        .background(SlotBg)
                        .border(1.dp, BronzeDark, RoundedCornerShape(3.dp))
                        .clickable { searching = true }
                        .padding(horizontal = 11.dp, vertical = 12.dp)
                ) {
                    Text(
                        EnchantUiState.filter.ifBlank { "Search magic effects…" },
                        color = if (EnchantUiState.filter.isBlank()) BoneDim else BoneBright,
                        fontSize = 15.sp, fontFamily = MwBody, maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
                if (EnchantUiState.filter.isNotBlank()) {
                    Spacer(Modifier.width(6.dp))
                    EffectChip(label = "Clear", active = false, onTap = { EnchantUiState.filter = "" })
                }
            }

            Spacer(Modifier.height(6.dp))

            // --- Magic Effects browse list -------------------------------------------------------------
            // The union of every effect in any ST_Spell the player knows, filtered to AllowEnchanting,
            // deduplicated and name-sorted by the engine. A row whose effect has NO legal range under
            // the current cast style is greyed: vanilla ignores that tap silently (its own unresolved
            // TODO), so no message is invented here — the row simply reads as unavailable.
            // A LazyColumn, NOT a verticalScroll Column: D-pad focus has to drag the viewport with
            // it, and only a LazyListState can be scrolled to an index. The persuasion popup was
            // fixed for exactly this on Aug 20 2026 ("focus walked off the bottom edge invisibly").
            // The hoisted state also feeds the scrollbar.
            if (visible.isEmpty()) {
                Box(Modifier.weight(1f).fillMaxWidth()) {
                    Text(
                        if (session.available.isEmpty()) "No known enchantable effects"
                        else "No effects match",
                        color = BoneDim, fontSize = 15.sp, fontFamily = MwBody,
                        modifier = Modifier.padding(vertical = 12.dp)
                    )
                }
            } else {
                Row(Modifier.weight(1f).fillMaxWidth()) {
                    // Unkeyed, deliberately — see the crash note on the item picker. These ids ARE
                    // unique today (startEditing dedupes knownEffects, and the stale-tail bug that
                    // could double them was fixed the same day), but keying would make a Compose
                    // crash the failure mode if that engine invariant ever slipped, and there is
                    // nothing to gain: the list only ever changes by FILTERING, never reordering.
                    LazyColumn(state = listState, modifier = Modifier.weight(1f).fillMaxHeight()) {
                        itemsIndexed(visible) { i, avail ->
                            val usable = session.ranges(avail.flags).isNotEmpty()
                            val room = session.effects.size < session.effectCap
                            EffectPickRow(
                                icon = avail.icon,
                                title = avail.name,
                                subtitle = if (!usable) "Not available for this enchantment" else null,
                                enabled = usable && room,
                                focused = i == focusIndex,
                                infoId = avail.id,
                                onTap = { addEffect(avail) }
                            )
                        }
                    }
                    // Position + length, which the chevron below cannot express on a list this long.
                    Spacer(Modifier.width(4.dp))
                    VerticalListScrollbar(listState, Modifier.fillMaxHeight())
                }
                // Kept alongside the bar: the chevron answers "is there more?" at a glance, and it
                // is what survives being glanced at on a 3.92" screen.
                ScrollMoreHint(listState)
            }

            Spacer(Modifier.height(6.dp))
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
            Spacer(Modifier.height(6.dp))

            // --- Cast type + Buy / Cancel ---------------------------------------------------------------
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                // Disabled when the engine says this item has nothing to cycle to — books/scrolls and
                // ammo/thrown are locked to a single type, and bows only gain a second option with a
                // soul of at least iSoulAmountForConstantEffect. That answer is exported, never
                // re-derived here.
                EffectActionButton(
                    label = session.castLabel.ifBlank { "Cast Once" },
                    color = if (session.castCycle) BronzeLight else BoneDim,
                    enabled = session.castCycle,
                    hint = "Y",
                    onTap = castTypeAction
                )
                Spacer(Modifier.weight(1f))
                // ALWAYS enabled, exactly as in vanilla: pressing Buy with something missing is how
                // the validation message is produced, and there is no native "validate without
                // committing" call to grey it out with.
                EffectActionButton(
                    label = if (session.self) "Create" else "Buy",
                    color = BronzeLight,
                    hint = "X",
                    onTap = buyAction
                )
                Spacer(Modifier.width(8.dp))
                // B, not a NAV binding: B is deliberately never intercepted at the top level, so it
                // reaches native exitCurrentGuiMode -> EnchantingDialog::exit(), which emits the
                // close signal and pops the mode. The hint documents the button that already works.
                EffectActionButton(label = "Cancel", color = Bone, hint = "B") {
                    UiSounds.play(UiSounds.Cue.TOGGLE)
                    CompanionActions.enchantCancel()
                }
            }
        }

        // --- Validation / result banner --------------------------------------------------------------
        message?.let { (text, seq) ->
            LaunchedEffect(seq) {
                delay(ENCHANT_MSG_MS)
                GameStateRepository.clearEnchantMessage()
            }
            Box(
                Modifier.fillMaxWidth().align(Alignment.TopCenter).padding(top = 34.dp),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text,
                    color = BoneBright, fontSize = 13.sp, fontFamily = MwDisplay,
                    textAlign = TextAlign.Center,
                    modifier = Modifier
                        .fillMaxWidth(0.9f)
                        .clip(RoundedCornerShape(4.dp))
                        .background(Color(0xF2201A12))
                        .border(1.dp, BronzeLight, RoundedCornerShape(4.dp))
                        .padding(horizontal = 12.dp, vertical = 9.dp)
                )
            }
        }

        // --- Popup 1: item / soul picker ---------------------------------------------------------------
        EnchantUiState.picker?.let { which ->
            val soul = which == "soul"
            EnchantPickerPopup(
                title = if (soul) "SOUL GEMS" else "ITEMS TO ENCHANT",
                options = if (soul) session.soulOptions else session.itemOptions,
                soul = soul,
                empty = if (soul) "No filled soul gems" else "Nothing enchantable carried",
                onPick = { id ->
                    // The item's DOWN sound is played NATIVELY on selection (getDownSoundId, as
                    // vanilla does for both slots) — deliberately not duplicated here.
                    if (soul) CompanionActions.enchantSelectSoul(id) else CompanionActions.enchantSelectItem(id)
                    EnchantUiState.picker = null
                },
                onCancel = { EnchantUiState.picker = null }
            )
        }

        // --- Popup 2: skill / attribute selector -------------------------------------------------------
        EnchantUiState.argPick?.let { pick ->
            EffectArgPickerPopup(
                pick = pick,
                onPick = { argId ->
                    if (pick.isSkill) CompanionActions.enchantEffectSkill(pick.effectId, argId)
                    else CompanionActions.enchantEffectAttribute(pick.effectId, argId)
                    EnchantUiState.argPick = null
                },
                onCancel = { EnchantUiState.argPick = null }
            )
        }

        // --- Popup 3: effect editor --------------------------------------------------------------------
        if (EffectEditorState.editing) {
            val effect = session.effects.getOrNull(EffectEditorState.index)
            if (effect == null) {
                // The effect vanished under us (a Cancel raced a republish). Close rather than draw
                // an editor pointed at nothing.
                EffectEditorState.close()
            } else {
                EffectEditorPopup(
                    title = effect.text.ifBlank { "EFFECT" }.uppercase(),
                    flags = effect.flags,
                    constant = session.constant,
                    actions = EnchantEditorActions
                ) {
                    // The live cost of the whole enchantment, so the player can see the capacity
                    // fill up while dragging. Over capacity is coloured, not blocked — Buy refuses.
                    Text(
                        "Enchantment ${session.points} / ${session.maxPoints}",
                        color = if (session.overCapacity) BarterRed else BoneDim,
                        fontSize = 15.sp, fontFamily = MwData
                    )
                }
            }
        }

        // --- Search entry --------------------------------------------------------------------------
        if (searching) {
            TextInputOverlay(
                initialText = EnchantUiState.filter,
                title = "SEARCH MAGIC EFFECTS",
                onConfirm = { EnchantUiState.filter = it; searching = false },
                onCancel = { searching = false }
            )
        }

        // --- Enchantment name entry ------------------------------------------------------------------
        // Raised from the TOP screen's name field, because the keyboard is touch-only and touch only
        // reaches the bottom panel. `!searching` keeps the two keyboards mutually exclusive.
        if (EnchantUiState.nameComposer && !searching) {
            TextInputOverlay(
                initialText = session.name,
                title = "ENCHANTMENT NAME",
                onConfirm = {
                    CompanionActions.enchantSetName(it)
                    EnchantUiState.nameComposer = false
                },
                onCancel = { EnchantUiState.nameComposer = false }
            )
        }
    }
}

/** The item or soul slot box. Shows the filled item, or a prompt when empty. */
@Composable
private fun EnchantSlotBox(
    label: String,
    slot: EnchantSlotItem,
    detail: String,
    modifier: Modifier = Modifier,
    // Controller binding, drawn beside the ITEM/SOUL caption. Same inline-hint convention as
    // EffectActionButton — these two slots are the screen's L1/R1 shortcuts.
    hint: String? = null,
    onTap: () -> Unit
) {
    val icon = rememberItemIcon(slot.icon)
    Row(
        modifier
            .clip(RoundedCornerShape(3.dp))
            .background(SlotBg)
            .border(1.dp, if (slot.present) BronzeLight else BronzeDark, RoundedCornerShape(3.dp))
            .clickable { onTap() }
            .padding(horizontal = 11.dp, vertical = 12.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        if (icon != null) {
            Image(bitmap = icon, contentDescription = null, modifier = Modifier.size(42.dp))
            Spacer(Modifier.width(9.dp))
        }
        Column(Modifier.weight(1f)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text(
                    label,
                    color = BronzeLight, fontSize = 11.sp, fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold, letterSpacing = 1.sp
                )
                if (hint != null) {
                    Spacer(Modifier.width(5.dp))
                    Text("[$hint]", color = BoneDim, fontSize = 10.sp, fontFamily = MwData)
                }
            }
            Text(
                if (slot.present) slot.name else "Tap to select",
                color = if (slot.present) BoneBright else BoneDim,
                fontSize = 15.sp, fontFamily = MwBody, maxLines = 1, overflow = TextOverflow.Ellipsis
            )
        }
        if (detail.isNotBlank()) {
            Spacer(Modifier.width(8.dp))
            Text(detail, color = BronzeLight, fontSize = 14.sp, fontFamily = MwData)
        }
    }
}

/** One row of the browse list, or of the current-effects list.
 *
 *  [infoId] is the effect's serialized RefId. Non-null turns the row into an info target: it reports
 *  its bounds so the floating info popup can anchor to it, and a LONG PRESS opens that popup — the
 *  touch equivalent of R3, exactly as every item/spell row in the app already works. The
 *  current-effects list on the top screen passes null (its tap is Edit, and a long press there has
 *  no meaning). */
@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun EffectPickRow(
    icon: String,
    title: String,
    subtitle: String?,
    enabled: Boolean,
    focused: Boolean = false,
    infoId: String? = null,
    onTap: () -> Unit
) {
    val bmp = rememberItemIcon(icon)
    Column(
        modifier = if (infoId == null) Modifier
        else Modifier.onGloballyPositioned { ItemInfoPopupState.reportAnchor(infoId, it.boundsInRoot()) }
    ) {
        Row(
            Modifier
                .fillMaxWidth()
                // Focus ring matches SpellForSaleRow's (12% fill + a 2dp bright border), so the
                // D-pad cursor reads the same on every DS list.
                .then(
                    if (focused) Modifier.background(BronzeLight.copy(alpha = 0.12f))
                        .border(2.dp, BronzeLight)
                    else Modifier
                )
                .then(
                    when {
                        enabled && infoId != null -> Modifier.combinedClickable(
                            onClick = onTap,
                            onLongClick = { ItemInfoPopupState.open(infoId, title, null, kind = InfoKind.EFFECT) }
                        )
                        enabled -> Modifier.clickable { onTap() }
                        // A greyed row still reports info: vanilla ignores the TAP silently, but
                        // "why can I not use this?" is exactly when the description is wanted.
                        infoId != null -> Modifier.combinedClickable(
                            onClick = {},
                            onLongClick = { ItemInfoPopupState.open(infoId, title, null, kind = InfoKind.EFFECT) }
                        )
                        else -> Modifier
                    }
                )
                .padding(vertical = 11.dp, horizontal = 5.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            if (bmp != null) {
                Image(bitmap = bmp, contentDescription = null, modifier = Modifier.size(30.dp))
                Spacer(Modifier.width(9.dp))
            }
            Column(Modifier.weight(1f)) {
                Text(
                    title,
                    color = if (enabled) Bone else BoneMuted,
                    fontSize = 16.sp, fontFamily = MwBody, maxLines = 2,
                    overflow = TextOverflow.Ellipsis
                )
                if (subtitle != null) {
                    Text(subtitle, color = BoneMuted, fontSize = 12.sp, fontFamily = MwBody)
                }
            }
        }
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
    }
}

/** Shared action button for the enchanting screen.
 *
 *  [hint] draws the controller binding inline as "[X]", the convention every other DS overlay uses
 *  (LootButton, BarterButton, the quantity selector's MAX). DS screens carry their own hints rather
 *  than relying on the native ControllerButtonsOverlay: that bar reads the ACTIVE window's
 *  mControllerButtons, and in DS mode this window is hidden, so it shows whatever is underneath. */
@Composable
private fun EffectActionButton(
    label: String,
    color: Color,
    enabled: Boolean = true,
    hint: String? = null,
    // D-pad focus (the effect editor's action row). Same 2dp bright ring as every other DS list.
    focused: Boolean = false,
    onTap: () -> Unit
) {
    Box(
        Modifier
            .height(ENCHANT_CONTROL_HEIGHT)
            .clip(RoundedCornerShape(3.dp))
            .background(if (focused) BronzeLight.copy(alpha = 0.12f) else SlotBg)
            .border(
                if (focused) 2.dp else 1.dp,
                when {
                    focused -> BronzeLight
                    enabled -> BronzeDark
                    else -> Color(0xFF2A2118)
                },
                RoundedCornerShape(3.dp)
            )
            .then(if (enabled) Modifier.clickable { onTap() } else Modifier)
            .padding(horizontal = 18.dp),
        contentAlignment = Alignment.Center
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(
                label,
                color = if (enabled) color else BoneMuted,
                fontSize = 16.sp, fontFamily = MwDisplay, fontWeight = FontWeight.Bold, maxLines = 1
            )
            if (hint != null) {
                Spacer(Modifier.width(6.dp))
                Text(
                    "[$hint]",
                    color = if (enabled) BoneDim else BoneDim.copy(alpha = 0.5f),
                    fontSize = 11.sp, fontFamily = MwData
                )
            }
        }
    }
}

/** Chip for the enchanting screen — the range selector and the filter's Clear. Same shape as
 *  [AlchemyChip], sized for this screen. */
@Composable
private fun EffectChip(label: String, active: Boolean, onTap: () -> Unit) {
    Box(
        Modifier
            .clip(RoundedCornerShape(3.dp))
            .background(if (active) PillActiveBg else SlotBg)
            .border(if (active) 2.dp else 1.dp, if (active) BronzeLight else BronzeDark, RoundedCornerShape(3.dp))
            .clickable { onTap() }
            .padding(horizontal = 16.dp, vertical = 11.dp)
    ) {
        Text(
            label,
            color = if (active) BoneBright else BoneDim,
            fontSize = 15.sp, fontFamily = MwDisplay, maxLines = 1
        )
    }
}

/** Square +/- stepper for the effect editor's sliders, at the enchanting screen's own control
 *  height rather than alchemy's smaller one. */
@Composable
private fun EffectStepButton(label: String, enabled: Boolean = true, onTap: () -> Unit) {
    Box(
        Modifier
            .size(ENCHANT_CONTROL_HEIGHT)
            .clip(RoundedCornerShape(3.dp))
            .background(SlotBg)
            .border(1.dp, if (enabled) BronzeDark else Color(0xFF2A2118), RoundedCornerShape(3.dp))
            .then(if (enabled) Modifier.clickable { onTap() } else Modifier),
        contentAlignment = Alignment.Center
    ) {
        Text(
            label,
            color = if (enabled) BronzeLight else BoneMuted,
            fontSize = 20.sp, fontFamily = MwDisplay, fontWeight = FontWeight.Bold
        )
    }
}

/** Shared popup frame for the three enchanting popups. In-window overlay, never a Compose Dialog
 *  (that crashes on the Presentation display — see ItemInfoOverlay). The scrim swallows taps: none
 *  of vanilla's equivalents dismiss on an outside click either. */
@Composable
private fun EffectPopupFrame(title: String, content: @Composable ColumnScope.() -> Unit) {
    Box(
        Modifier
            .fillMaxSize()
            .zIndex(22f)
            .background(Color(0xCC000000))
            .pointerInput(Unit) { detectTapGestures { } },
        contentAlignment = Alignment.Center
    ) {
        Column(
            Modifier
                .fillMaxWidth(0.92f)
                .fillMaxHeight(0.9f)
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures { } }
                .padding(10.dp)
        ) {
            Text(
                title,
                color = BronzeLight, fontSize = 16.sp, fontFamily = MwDisplay,
                fontWeight = FontWeight.Bold, letterSpacing = 1.sp
            )
            Spacer(Modifier.height(6.dp))
            Box(Modifier.fillMaxWidth().height(1.dp).background(Bronze))
            Spacer(Modifier.height(6.dp))
            content()
        }
    }
}

/** Popup 1 — the item or soul-gem picker. Both browse the PLAYER's own inventory (never the
 *  enchanter's) and are answered with a serialized RefId, because the underlying container store
 *  reorders as its contents change. */
@Composable
private fun EnchantPickerPopup(
    title: String,
    options: List<EnchantPickOption>,
    soul: Boolean,
    empty: String,
    onPick: (String) -> Unit,
    onCancel: () -> Unit
) {
    // One lambda for both input paths, as everywhere else on this screen.
    val pick: (EnchantPickOption) -> Unit = { opt ->
        UiSounds.play(UiSounds.Cue.TOGGLE); onPick(opt.id)
    }
    // L1/R1 raise this popup, so it has to be drivable by controller or those shortcuts dead-end.
    // B is NOT handled here — the parent overlay's popup-cancel collector owns it for all five
    // popups, so binding it again would close two things at once.
    val listState = rememberLazyListState()
    val focusIndex = rememberListNavFocus(
        itemCount = options.size,
        onConfirm = { i -> options.getOrNull(i)?.let(pick) }
    )
    LaunchedEffect(focusIndex) {
        if (focusIndex in options.indices) listState.animateScrollToItem(focusIndex)
    }
    EffectPopupFrame(title) {
        if (options.isEmpty()) {
            Box(Modifier.weight(1f).fillMaxWidth()) {
                Text(empty, color = BoneDim, fontSize = 15.sp, fontFamily = MwBody,
                    modifier = Modifier.padding(vertical = 12.dp))
            }
        } else {
            Row(Modifier.weight(1f).fillMaxWidth()) {
                // NO `key = { … o.id }` — CRASH (Aug 21 2026). `id` is the item's RECORD RefId and
                // the engine emits one row per container-store STACK, so two rows can legitimately
                // share it: enchantable items are weapons/armour/clothing, which do NOT stack when
                // their condition differs, so two iron daggers at different durability are two rows
                // with the same id. LazyColumn wraps each item in a SaveableStateProvider keyed on
                // that value and throws once both duplicates are composed at the same time — which
                // is why it took a big inventory and ~15 rows of scrolling to reach, and never fired
                // on a short list. Index keys (the default) are correct here anyway: this list does
                // not reorder while it is open (the sim is paused and the popup closes on pick) and
                // the rows hold no state worth preserving, so a key buys nothing and can only hurt.
                LazyColumn(state = listState, modifier = Modifier.weight(1f).fillMaxHeight()) {
                    itemsIndexed(options) { i, opt ->
                        EffectPickRow(
                            icon = opt.icon,
                            title = if (opt.count > 1) "${opt.name} (${opt.count})" else opt.name,
                            // Soul gems show the trapped soul and its value — the number that becomes
                            // the enchantment's Charge. Items show the capacity they would give.
                            subtitle = if (soul) "${opt.soul} (${opt.charge})"
                            else "${opt.maxPoints} enchantment points",
                            enabled = true,
                            focused = i == focusIndex,
                            onTap = { pick(opt) }
                        )
                    }
                }
                Spacer(Modifier.width(4.dp))
                VerticalListScrollbar(listState, Modifier.fillMaxHeight())
            }
            ScrollMoreHint(listState)
        }
        Spacer(Modifier.height(8.dp))
        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
            EffectActionButton(label = "Cancel", color = Bone, hint = "B") {
                UiSounds.play(UiSounds.Cue.TOGGLE); onCancel()
            }
        }
    }
}

/** Popup 2 — the Skill or Attribute selector, raised by the ENGINE for a TargetSkill/TargetAttribute
 *  effect. The lists come from the character batch, which walks the record stores, so a mod adding
 *  skills or attributes flows through. Deliberately offers EVERY entry with no duplicate filtering:
 *  vanilla has no such check on this path, so the same skill may be picked twice. */
@Composable
private fun EffectArgPickerPopup(
    pick: EffectArgPick,
    onPick: (String) -> Unit,
    onCancel: () -> Unit
) {
    val state by GameStateRepository.state.collectAsState()
    val rows: List<Pair<String, String>> = remember(pick, state.character) {
        if (pick.isSkill) state.character.skills.map { it.id to it.name }
        else state.character.attributes.map { it.id to it.name }
    }
    val choose: (String) -> Unit = { id -> UiSounds.play(UiSounds.Cue.TOGGLE); onPick(id) }
    // The skill list is 27 rows on a stock install (and mods can add more), so this one genuinely
    // needs the scroll-to-focus that only a LazyListState can give. B is left to the parent
    // overlay's popup-cancel collector, as with the other popups.
    val listState = rememberLazyListState()
    val focusIndex = rememberListNavFocus(
        itemCount = rows.size,
        onConfirm = { i -> rows.getOrNull(i)?.let { choose(it.first) } }
    )
    LaunchedEffect(focusIndex) {
        if (focusIndex in rows.indices) listState.animateScrollToItem(focusIndex)
    }
    EffectPopupFrame(if (pick.isSkill) "SELECT SKILL" else "SELECT ATTRIBUTE") {
        if (rows.isEmpty()) {
            Box(Modifier.weight(1f).fillMaxWidth()) {
                Text("Unavailable", color = BoneDim, fontSize = 15.sp, fontFamily = MwBody,
                    modifier = Modifier.padding(vertical = 12.dp))
            }
        } else {
            Row(Modifier.weight(1f).fillMaxWidth()) {
                // Unkeyed for the same reason as the other two. These skill/attribute ids are
                // genuinely unique (they come from the record stores), but the list is static while
                // the popup is open, so the key would be pure risk for no benefit.
                LazyColumn(state = listState, modifier = Modifier.weight(1f).fillMaxHeight()) {
                    itemsIndexed(rows) { i, (id, name) ->
                        EffectPickRow(
                            icon = "", title = name, subtitle = null, enabled = true,
                            focused = i == focusIndex,
                            onTap = { choose(id) }
                        )
                    }
                }
                Spacer(Modifier.width(4.dp))
                VerticalListScrollbar(listState, Modifier.fillMaxHeight())
            }
            ScrollMoreHint(listState)
        }
        Spacer(Modifier.height(8.dp))
        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.End) {
            EffectActionButton(label = "Cancel", color = Bone, hint = "B") {
                UiSounds.play(UiSounds.Cue.TOGGLE); onCancel()
            }
        }
    }
}

/** The editor's D-pad focus stops, in screen order. Built fresh on every recomposition from the
 *  SAME visibility tests that decide what is drawn (see the popup's KDoc — two of them move under
 *  the player), so the focus list can never offer a row that is not on screen. */
private enum class EffectEditRow { RANGE, MAG_MIN, MAG_MAX, DURATION, AREA, DELETE, OK, CANCEL }

/**
 * Popup 3 — the effect editor: the Range button plus whichever of the Magnitude / Duration / Area
 * sliders apply.
 *
 * The three visibility tests are INDEPENDENT and are recomputed here on every recomposition rather
 * than cached, because two of them move under the player: Duration disappears the moment the cast
 * type becomes Constant, and Area is keyed to the CURRENT range, so it appears and vanishes as the
 * Range button is cycled. An effect like Almsivi Intervention (Self-only, NoMagnitude, NoDuration)
 * correctly shows the Range control and nothing else.
 *
 * Every change is pushed to the engine immediately, so the top-screen readout and the
 * Enchantment / Cast Cost figures track the sliders live — the native editor does the same. OK
 * keeps the result; Cancel removes a newly-added effect or restores an edited one, which is
 * `EditEffectDialog::exit()`'s two halves and is executed NATIVELY.
 */
@Composable
private fun EffectEditorPopup(
    title: String,
    flags: Int,
    constant: Boolean,
    actions: EffectEditorActions,
    /** Drawn under the sliders. Enchanting shows the capacity fill; spellmaking, which has no
     *  capacity ceiling, shows its magicka cost. Nothing else about the popup differs. */
    footer: @Composable () -> Unit
) {
    val ranges = effectRanges(flags, constant)
    val showMag = effectShowMagnitude(flags)
    val showDur = effectShowDuration(flags, constant)
    val showArea = effectShowArea(EffectEditorState.range)

    // The cast type can change while the editor is open (it cannot be reached from here, but a
    // republish can arrive), so keep the working range legal.
    LaunchedEffect(flags, constant, EffectEditorState.range) {
        if (ranges.isNotEmpty() && EffectEditorState.range !in ranges) {
            EffectEditorState.range = ranges.first()
            EffectEditorState.area = 0
            actions.push()
        }
    }

    // ---- Shared actions -----------------------------------------------------------------------
    // One lambda per action, used by BOTH the touch controls below and the D-pad collector, so the
    // two paths cannot drift (the same rule the browse list follows).
    val setRange: (Int) -> Unit = { r ->
        UiSounds.play(UiSounds.Cue.TICK)
        EffectEditorState.range = r
        // onRangeButtonClicked zeroes the area slider whenever it lands on Self.
        if (r == EffectRange.SELF) EffectEditorState.area = 0
        actions.push()
    }
    val setMagMin: (Int) -> Unit = { v ->
        EffectEditorState.magMin = v
        // The ONE coupling vanilla has: max is forced up to meet min.
        if (EffectEditorState.magMax < v) EffectEditorState.magMax = v
        actions.push()
    }
    val setMagMax: (Int) -> Unit = { v ->
        EffectEditorState.magMax = v.coerceAtLeast(EffectEditorState.magMin)
        actions.push()
    }
    val setDuration: (Int) -> Unit = { v -> EffectEditorState.duration = v; actions.push() }
    val setArea: (Int) -> Unit = { v -> EffectEditorState.area = v; actions.push() }
    val deleteAction: () -> Unit = {
        UiSounds.play(UiSounds.Cue.TOGGLE)
        actions.delete(EffectEditorState.index)
        EffectEditorState.close()
    }
    val okAction: () -> Unit = {
        UiSounds.play(UiSounds.Cue.ACTION)
        actions.ok()
        EffectEditorState.close()
    }
    val cancelAction: () -> Unit = {
        UiSounds.play(UiSounds.Cue.TOGGLE)
        actions.cancel()
        EffectEditorState.close()
    }

    // ---- Controller navigation ----------------------------------------------------------------
    // Mirrors EditEffectDialog::onControllerButtonEvent (spellcreationdialog.cpp) rather than
    // inventing a mapping: Up/Down walk the controls, Left/Right cycle the range or step the focused
    // slider by 1, L1/R1 jump that slider to its min/max, A activates the focused control, X is an
    // always-available OK and B cancels.
    //
    // A on a SLIDER row is deliberately INERT — vanilla has no branch for it either, and X is the
    // commit that always works regardless of where focus is sitting, so nothing is unreachable.
    // B is not handled here: the parent overlay's popup-cancel collector already owns it (and routes
    // through the engine, which is what decides between erasing a new effect and restoring an
    // edited one).
    val rows = buildList {
        if (ranges.isNotEmpty()) add(EffectEditRow.RANGE)
        if (showMag) { add(EffectEditRow.MAG_MIN); add(EffectEditRow.MAG_MAX) }
        if (showDur) add(EffectEditRow.DURATION)
        if (showArea) add(EffectEditRow.AREA)
        if (!EffectEditorState.isNew) add(EffectEditRow.DELETE)
        add(EffectEditRow.OK)
        add(EffectEditRow.CANCEL)
    }
    var focus by remember { mutableStateOf(0) }
    LaunchedEffect(rows) { focus = focus.coerceIn(0, rows.lastIndex) }
    val focusedRow = rows.getOrNull(focus)

    // Scroll offset of each focusable row WITHIN the scrolling column, reported from layout. A plain
    // mutable map, never snapshot state: it is written during the layout pass for every visible row,
    // so a snapshot map would invalidate this popup every frame (the same reasoning as
    // ItemInfoPopupState's anchor cache).
    val rowOffsets = remember { HashMap<EffectEditRow, Int>() }
    val scrollState = rememberScrollState()

    val rowsState = rememberUpdatedState(rows)
    val rangesState = rememberUpdatedState(ranges)
    LaunchedEffect(Unit) {
        var lastSeq = GameStateRepository.navEvent.value?.seq ?: -1L
        GameStateRepository.navEvent.collect { ev ->
            if (ev == null || ev.seq <= lastSeq) return@collect
            lastSeq = ev.seq
            val list = rowsState.value
            if (list.isEmpty()) return@collect
            val cur = list.getOrNull(focus.coerceIn(0, list.lastIndex)) ?: return@collect
            val legal = rangesState.value
            // Step the focused slider by [d], or jump it to an end when [toEnd] is set.
            fun step(d: Int, toEnd: Boolean = false) {
                when (cur) {
                    EffectEditRow.RANGE -> if (legal.size > 1) {
                        val i = legal.indexOf(EffectEditorState.range).coerceAtLeast(0)
                        setRange(legal[(i + d + legal.size) % legal.size])
                    }
                    EffectEditRow.MAG_MIN -> {
                        val lo = EffectBounds.MAG_MIN
                        val hi = EffectBounds.MAG_MAX
                        setMagMin(
                            if (toEnd) (if (d < 0) lo else hi)
                            else (EffectEditorState.magMin + d).coerceIn(lo, hi)
                        )
                    }
                    EffectEditRow.MAG_MAX -> {
                        // Its floor is the CURRENT min, exactly as the touch slider's `min` is.
                        val lo = EffectEditorState.magMin
                        val hi = EffectBounds.MAG_MAX
                        setMagMax(
                            if (toEnd) (if (d < 0) lo else hi)
                            else (EffectEditorState.magMax + d).coerceIn(lo, hi)
                        )
                    }
                    EffectEditRow.DURATION -> {
                        val lo = EffectBounds.DURATION_MIN
                        val hi = EffectBounds.DURATION_MAX
                        setDuration(
                            if (toEnd) (if (d < 0) lo else hi)
                            else (EffectEditorState.duration + d).coerceIn(lo, hi)
                        )
                    }
                    EffectEditRow.AREA -> {
                        val lo = EffectBounds.AREA_MIN
                        val hi = EffectBounds.AREA_MAX
                        setArea(
                            if (toEnd) (if (d < 0) lo else hi)
                            else (EffectEditorState.area + d).coerceIn(lo, hi)
                        )
                    }
                    // The action buttons sit on one visual row, so Left/Right walks BETWEEN them
                    // (vanilla does the same) instead of adjusting anything.
                    EffectEditRow.DELETE, EffectEditRow.OK, EffectEditRow.CANCEL ->
                        if (!toEnd) focus = (focus + d).coerceIn(0, list.lastIndex)
                }
            }
            when (ev) {
                is NavEvent.Down -> focus = (focus + 1) % list.size
                is NavEvent.Up -> focus = (focus - 1 + list.size) % list.size
                is NavEvent.Right -> step(1)
                is NavEvent.Left -> step(-1)
                is NavEvent.R1 -> step(1, toEnd = true)
                is NavEvent.L1 -> step(-1, toEnd = true)
                // Left stick, the app-wide "nudge a slider" axis (barter gold, rest hours).
                is NavEvent.SliderRight -> step(1)
                is NavEvent.SliderLeft -> step(-1)
                is NavEvent.Confirm -> when (cur) {
                    EffectEditRow.RANGE -> step(1)   // A on the range button cycles it, as in vanilla
                    EffectEditRow.DELETE -> deleteAction()
                    EffectEditRow.OK -> okAction()
                    EffectEditRow.CANCEL -> cancelAction()
                    else -> Unit                       // inert on a slider — see the note above
                }
                is NavEvent.Action1 -> okAction()       // X = OK, vanilla's explicit shortcut
                else -> Unit
            }
        }
    }

    // Keep the focused row in view. The value rows live in a plain scrolling Column (they are
    // heterogeneous and few, so a LazyColumn would buy nothing), which cannot scroll to an index —
    // hence the measured offsets above. The action buttons are OUTSIDE that column and always
    // visible, so they have no offset and are skipped.
    LaunchedEffect(focusedRow) {
        rowOffsets[focusedRow]?.let { y ->
            scrollState.animateScrollTo((y - EDITOR_FOCUS_SCROLL_MARGIN).coerceAtLeast(0))
        }
    }

    EffectPopupFrame(title) {
        Column(Modifier.weight(1f).fillMaxWidth().verticalScroll(scrollState)) {

            // Reports a row's offset within this scrolling column so the D-pad can bring it into
            // view. positionInParent() is the UNSCROLLED layout position, which is exactly what
            // animateScrollTo takes — the scroll modifier translates the column as a whole.
            fun Modifier.reportRow(row: EffectEditRow) = this.onGloballyPositioned {
                rowOffsets[row] = it.positionInParent().y.toInt()
            }

            // --- Range ------------------------------------------------------------------------------
            // Only the legal options are drawn. An effect with a single legal range shows that one
            // as an inert label rather than a button that cannot change anything.
            Column(Modifier.fillMaxWidth().reportRow(EffectEditRow.RANGE)) {
                Text("Range", color = BronzeLight, fontSize = 14.sp, fontFamily = MwDisplay)
                Spacer(Modifier.height(6.dp))
                Row(
                    Modifier
                        .fillMaxWidth()
                        // The focus ring goes around the GROUP, not one chip: Left/Right moves the
                        // selection, so the focused chip is always the active one and a second
                        // highlight on it would say nothing.
                        .then(
                            if (focusedRow == EffectEditRow.RANGE)
                                Modifier.border(2.dp, BronzeLight, RoundedCornerShape(3.dp)).padding(3.dp)
                            else Modifier
                        ),
                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    ranges.forEach { r ->
                        EffectChip(
                            label = EffectRange.label(r),
                            active = r == EffectEditorState.range,
                            onTap = { setRange(r) }
                        )
                    }
                }
            }

            if (showMag) {
                Spacer(Modifier.height(10.dp))
                EffectSliderRow(
                    label = "Magnitude (min)",
                    value = EffectEditorState.magMin,
                    min = EffectBounds.MAG_MIN, max = EffectBounds.MAG_MAX,
                    focused = focusedRow == EffectEditRow.MAG_MIN,
                    modifier = Modifier.reportRow(EffectEditRow.MAG_MIN),
                    onChange = setMagMin
                )
                Spacer(Modifier.height(6.dp))
                EffectSliderRow(
                    label = "Magnitude (max)",
                    value = EffectEditorState.magMax,
                    min = EffectEditorState.magMin, max = EffectBounds.MAG_MAX,
                    focused = focusedRow == EffectEditRow.MAG_MAX,
                    modifier = Modifier.reportRow(EffectEditRow.MAG_MAX),
                    onChange = setMagMax
                )
            }

            if (showDur) {
                Spacer(Modifier.height(10.dp))
                EffectSliderRow(
                    label = "Duration (s)",
                    value = EffectEditorState.duration,
                    min = EffectBounds.DURATION_MIN, max = EffectBounds.DURATION_MAX,
                    focused = focusedRow == EffectEditRow.DURATION,
                    modifier = Modifier.reportRow(EffectEditRow.DURATION),
                    onChange = setDuration
                )
            }

            if (showArea) {
                Spacer(Modifier.height(10.dp))
                EffectSliderRow(
                    label = "Area (ft)",
                    value = EffectEditorState.area,
                    min = EffectBounds.AREA_MIN, max = EffectBounds.AREA_MAX,
                    focused = focusedRow == EffectEditRow.AREA,
                    modifier = Modifier.reportRow(EffectEditRow.AREA),
                    onChange = setArea
                )
            }

            Spacer(Modifier.height(10.dp))
            footer()
        }

        Spacer(Modifier.height(8.dp))
        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
            // Delete is offered only for an EXISTING effect, matching vanilla (mDeleteButton is
            // hidden by newEffect and shown by editEffect).
            if (!EffectEditorState.isNew) {
                EffectActionButton(
                    label = "Delete", color = BarterRed,
                    focused = focusedRow == EffectEditRow.DELETE,
                    onTap = deleteAction
                )
            }
            Spacer(Modifier.weight(1f))
            EffectActionButton(
                label = "OK", color = BronzeLight, hint = "X",
                focused = focusedRow == EffectEditRow.OK,
                onTap = okAction
            )
            Spacer(Modifier.width(8.dp))
            EffectActionButton(
                label = "Cancel", color = Bone, hint = "B",
                focused = focusedRow == EffectEditRow.CANCEL,
                onTap = cancelAction
            )
        }
    }
}

/** One editor slider: a label, the value, and −/+ steppers either side of a drag track. The bounds
 *  are the FIXED layout constants ([EffectBounds]) — never adjusted by skill, soul or base cost. */
@Composable
private fun EffectSliderRow(
    label: String,
    value: Int,
    min: Int,
    max: Int,
    modifier: Modifier = Modifier,
    // D-pad focus. Left/Right (and L1/R1 for the ends) act on the focused row — see the editor's
    // nav collector. Drawn as the same 2dp ring the browse list and the action buttons use.
    focused: Boolean = false,
    onChange: (Int) -> Unit
) {
    // ONE column so the label/value line and the stepper line highlight and scroll as a single row.
    Column(
        modifier
            .fillMaxWidth()
            .then(
                if (focused) Modifier.border(2.dp, BronzeLight, RoundedCornerShape(3.dp)).padding(3.dp)
                else Modifier
            )
    ) {
    Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
        Text(label, color = BronzeLight, fontSize = 14.sp, fontFamily = MwDisplay,
            modifier = Modifier.width(140.dp))
        Text(
            "$value", color = BoneBright, fontSize = 16.sp, fontFamily = MwData,
            fontWeight = FontWeight.Bold, modifier = Modifier.width(58.dp), textAlign = TextAlign.End
        )
    }
    Spacer(Modifier.height(3.dp))
    Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
        EffectStepButton("−", enabled = value > min) { onChange((value - 1).coerceAtLeast(min)) }
        Spacer(Modifier.width(8.dp))
        // A one-point range would make Slider divide by zero working out the thumb fraction. That is
        // reachable: dragging Magnitude(min) to its 100 ceiling forces Magnitude(max)'s own minimum
        // to 100 as well. Widen the TRACK in that case and keep the value clamped to the real bound.
        val trackMax = if (max > min) max else min + 1
        Slider(
            value = value.toFloat(),
            // Only fire on a real INTEGER change: Slider reports every touch-move sample, so an
            // unguarded handler would push dozens of identical CMP:enchant_effect_set commands per
            // step of the drag.
            onValueChange = { raw ->
                val v = raw.toInt().coerceIn(min, max)
                if (v != value) onChange(v)
            },
            valueRange = min.toFloat()..trackMax.toFloat(),
            colors = SliderDefaults.colors(
                thumbColor = BronzeLight,
                activeTrackColor = Bronze,
                inactiveTrackColor = BronzeDark
            ),
            modifier = Modifier.weight(1f)
        )
        Spacer(Modifier.width(8.dp))
        EffectStepButton("+", enabled = value < max) { onChange((value + 1).coerceAtMost(max)) }
    }
    }
}

/** Padding kept above the D-pad-focused editor row when scrolling it into view, so the focused row
 *  never sits flush against the top edge with its label clipped. */
private const val EDITOR_FOCUS_SCROLL_MARGIN = 24

/**
 * TOP-screen enchanting half: the name field, the stat column and the live effects readout.
 *
 * Hosted by [org.openmw.EngineActivity] in an INTERACTIVE panel window while an enchanting session
 * is live AND Enchanting is DS — interactive because the name field and the effect rows answer to a
 * tap (the name field raises the bottom screen's keyboard; an effect row opens the editor down
 * there).
 *
 * The readout shows the effects as they are RIGHT NOW, including one that is only half-configured:
 * a newly-added effect is on the enchantment from the moment the editor opens (vanilla's
 * eventEffectAdded), and Cancel is what takes it back off.
 */
@Composable
fun EnchantingTopOverlay() {
    val session by GameStateRepository.enchantSession.collectAsState()
    val s = session ?: return

    // Bottom-aligned, and sized IDENTICALLY to the alchemy top panel — same width fraction, same
    // bottom inset, same interior padding and column gap — so the two DS service screens read as one
    // family rather than as two windows that happen to be near each other.
    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.BottomCenter) {
        Row(
            Modifier
                // Outside the panel frame, so it is a gap from the screen edge and not interior
                // padding — hence before mwPanel() in the chain, not after.
                .padding(bottom = ALCHEMY_TOP_PANEL_INSET)
                .fillMaxWidth(ALCHEMY_TOP_PANEL_WIDTH)
                // IntrinsicSize.Min so the divider's fillMaxHeight() below resolves to the TALLEST
                // COLUMN rather than to the incoming (full-screen) constraint, which would stretch
                // this whole panel down the screen.
                .height(IntrinsicSize.Min)
                .heightIn(min = ENCHANT_TOP_PANEL_MIN_HEIGHT)
                .mwPanel()
                .padding(14.dp),
            horizontalArrangement = Arrangement.spacedBy(14.dp),
            verticalAlignment = Alignment.Top
        ) {
            // --- Left: name + stats ------------------------------------------------------------------
            Column(Modifier.weight(0.44f)) {
                Text(
                    "ENCHANTMENT", color = BronzeLight, fontSize = 13.sp,
                    fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 1.sp
                )
                Spacer(Modifier.height(6.dp))
                Box(
                    Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(3.dp))
                        .background(SlotBg)
                        .border(1.dp, BronzeDark, RoundedCornerShape(3.dp))
                        .clickable { EnchantUiState.nameComposer = true }
                        .padding(horizontal = 10.dp, vertical = 11.dp)
                ) {
                    Text(
                        s.name.ifBlank { "Tap to name" },
                        color = if (s.name.isBlank()) BoneDim else BoneBright,
                        fontSize = 16.sp, fontFamily = MwBody, maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
                Spacer(Modifier.height(10.dp))

                // Enchantment X / Y — points used against the ITEM's capacity. Over capacity is
                // coloured; Buy is still what refuses (with sNotifyMessage29).
                EnchantStatRow(
                    "Enchantment", "${s.points} / ${s.maxPoints}",
                    if (s.overCapacity) BarterRed else BoneBright
                )
                // Constant Effect has no cast cost at all (getBaseCastCost returns 0 for it).
                EnchantStatRow("Cast Cost", "${s.castCost}", BoneBright)
                EnchantStatRow("Charge", "${s.charge}", BoneBright)
                if (s.showPrice) EnchantStatRow("Price", "${s.price}", BronzeLight)
                // Gated on the ENGINE's own "show enchant chance" setting, which ships false — the
                // exact condition vanilla applies to mChanceLayout. The value is exported either
                // way, so turning that setting on makes this appear with no further change.
                if (s.showChance) EnchantStatRow("Chance", "${s.chance}%", BronzeLight)
            }

            Box(Modifier.width(1.dp).fillMaxHeight().background(BronzeDark))

            // --- Right: live effects readout -----------------------------------------------------------
            Column(Modifier.weight(0.56f)) {
                Text(
                    "EFFECTS ${s.effects.size}/${s.effectCap}", color = BronzeLight, fontSize = 13.sp,
                    fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 1.sp
                )
                Spacer(Modifier.height(6.dp))
                if (s.effects.isEmpty()) {
                    Text(
                        "None", color = BoneDim, fontSize = 14.sp, fontFamily = MwBody,
                        modifier = Modifier.padding(vertical = 6.dp)
                    )
                } else {
                    Column(Modifier.heightIn(max = ENCHANT_TOP_EFFECTS_MAX).verticalScroll(rememberScrollState())) {
                        s.effects.forEach { eff ->
                            val bmp = rememberItemIcon(eff.icon)
                            Row(
                                Modifier
                                    .fillMaxWidth()
                                    .clickable { CompanionActions.enchantEditEffect(eff.index) }
                                    .padding(vertical = 4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                if (bmp != null) {
                                    Image(bitmap = bmp, contentDescription = null,
                                        modifier = Modifier.size(22.dp))
                                    Spacer(Modifier.width(7.dp))
                                }
                                Text(
                                    // Composed natively from MWSpellEffect's own formatting, so this
                                    // reads exactly as the vanilla list does.
                                    eff.text,
                                    color = Bone, fontSize = 13.sp, fontFamily = MwBody,
                                    maxLines = 2, overflow = TextOverflow.Ellipsis
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun EnchantStatRow(label: String, value: String, valueColor: Color) {
    Row(Modifier.fillMaxWidth().padding(vertical = 4.dp), verticalAlignment = Alignment.CenterVertically) {
        Text(label, color = BoneDim, fontSize = 14.sp, fontFamily = MwBody, modifier = Modifier.weight(1f))
        Text(value, color = valueColor, fontSize = 16.sp, fontFamily = MwData, fontWeight = FontWeight.Bold)
    }
}

/* ---- DS Spellmaking ---- */

/** Bottom-screen spellmaking UI state. The effect EDITOR's working copy is not here — that is
 *  [EffectEditorState], shared with enchanting, because it is one editor natively too. */
private object SpellmakingUiState {
    /** True while the BOTTOM screen's name keyboard is up (raised by a tap on the TOP screen's name
     *  field). The keyboard has to live on the bottom panel — it is touch-only by design. */
    var nameComposer by mutableStateOf(false)
    /** Browse-list filter. Purely presentational. */
    var filter by mutableStateOf("")
    /** Non-null while the Skill / Attribute selector is up, raised by the engine
     *  (COMPANION_SPELLMAKING_ARGPICK) when the tapped effect targets one. */
    var argPick by mutableStateOf<EffectArgPick?>(null)

    fun reset() {
        nameComposer = false
        filter = ""
        argPick = null
        EffectEditorState.close()
    }
}

/** Spellmaking's binding of the shared effect editor to its own CMP: family. The sibling of
 *  [EnchantEditorActions] — and the only thing that differs between the two screens' editors. */
private val SpellmakingEditorActions = EffectEditorActions(
    push = {
        if (EffectEditorState.editing) CompanionActions.spellmakingSetEffect(
            EffectEditorState.index,
            EffectEditorState.range,
            EffectEditorState.magMin,
            EffectEditorState.magMax,
            EffectEditorState.duration,
            EffectEditorState.area
        )
    },
    delete = { index -> CompanionActions.spellmakingDeleteEffect(index) },
    ok = { CompanionActions.spellmakingEffectOk() },
    cancel = { CompanionActions.spellmakingEffectCancel() }
)

/**
 * BOTTOM-screen spellmaking: the Magic Effects browse list, Gold/Price/Buy/Cancel, and both popup
 * types (effect editor, skill or attribute selector).
 *
 * TOUCH ONLY, by design — the companion panel is `FLAG_NOT_FOCUSABLE`, so no D-pad input reaches it.
 *
 * PRESENTATION ONLY. Every tap sends a `CMP:spellmaking_*` command to the native
 * SpellCreationDialog and the screen is redrawn from the batch that comes back, so the
 * order-dependent magicka cost, the cast chance, the barter-adjusted price and the four Buy
 * validations are all still the engine's. Unlike enchanting there is no success roll at all:
 * creation always succeeds once validation passes.
 *
 * Simpler than the enchanting screen by exactly the things spellmaking does not have: no item slot,
 * no soul gem, no cast type and no capacity ceiling.
 */
@Composable
private fun SpellmakingOverlay(session: SpellmakingSession) {
    DisposableEffect(Unit) {
        SpellmakingUiState.reset()
        onDispose { SpellmakingUiState.reset() }
    }

    var searching by remember { mutableStateOf(false) }
    val message by GameStateRepository.spellmakingMessage.collectAsState()
    val argPick by GameStateRepository.spellmakingArgPick.collectAsState()
    val editReq by GameStateRepository.spellmakingEdit.collectAsState()

    // The engine drives both popups: tapping a browse row sends _effect_add, and the ENGINE decides
    // whether that means "pick a skill first" or "open the editor". Keyed on the sequence number so
    // adding the same effect twice raises the popup twice.
    LaunchedEffect(argPick?.second) {
        argPick?.let { (pick, _) ->
            SpellmakingUiState.argPick = pick
            GameStateRepository.clearSpellmakingArgPick()
        }
    }
    LaunchedEffect(editReq?.second) {
        editReq?.let { (req, _) ->
            // Seed from the effect as the engine actually stored it — for a NEW effect that is after
            // companionInitialRange has overridden the range, so the popup opens on the range the
            // engine chose rather than on vanilla's raw cascade result.
            val eff = GameStateRepository.spellmakingSession.value?.effects?.getOrNull(req.index)
            EffectEditorState.open(
                index = req.index,
                isNew = req.isNew,
                range = eff?.range ?: EffectRange.SELF,
                magMin = eff?.magMin ?: 1,
                magMax = eff?.magMax ?: 1,
                duration = eff?.duration ?: 1,
                area = eff?.area ?: 0
            )
            SpellmakingUiState.argPick = null
            GameStateRepository.clearSpellmakingEdit()
        }
    }

    val visible = remember(session.available, SpellmakingUiState.filter) {
        val needle = SpellmakingUiState.filter.trim().lowercase()
        if (needle.isEmpty()) session.available
        else session.available.filter { it.name.lowercase().contains(needle) }
    }

    // ONE lambda per action, shared by the touch and controller paths, so the two can never diverge.
    val addEffect: (EffectAvail) -> Unit = { avail ->
        UiSounds.play(UiSounds.Cue.TOGGLE)
        CompanionActions.spellmakingAddEffect(avail.id)
    }
    val buyAction: () -> Unit = {
        UiSounds.play(UiSounds.Cue.ACTION)
        CompanionActions.spellmakingBuy()
    }

    // Any popup open = that popup owns input. The main loop yields and B is re-routed: registering
    // the cancelable-modal bridge flips the native atomic so B arrives as NAV_CANCEL instead of
    // falling through to exitCurrentGuiMode, which would pop the whole spellmaking mode out from
    // under an open popup.
    val popupOpen = SpellmakingUiState.argPick != null || EffectEditorState.editing ||
        searching || SpellmakingUiState.nameComposer
    DisposableEffect(popupOpen) {
        if (popupOpen) {
            ModalNav.count++
            CompanionActions.setModalCancelOpen(true)
        }
        onDispose {
            if (popupOpen) {
                ModalNav.count--
                if (ModalNav.count == 0) CompanionActions.setModalCancelOpen(false)
            }
        }
    }

    // B while a popup is up closes the TOPMOST one. Its own collector, because the main list loop is
    // disabled exactly when this is needed. Order mirrors the render order below.
    val popupOpenState = rememberUpdatedState(popupOpen)
    val searchingState = rememberUpdatedState(searching)
    LaunchedEffect(Unit) {
        var lastSeq = GameStateRepository.navEvent.value?.seq ?: -1L
        GameStateRepository.navEvent.collect { ev ->
            if (ev == null || ev.seq <= lastSeq) return@collect
            lastSeq = ev.seq
            if (ev !is NavEvent.Cancel || !popupOpenState.value) return@collect
            when {
                searchingState.value -> searching = false
                SpellmakingUiState.nameComposer -> SpellmakingUiState.nameComposer = false
                EffectEditorState.editing -> {
                    // Through the ENGINE, never by just closing the popup: cancel erases a
                    // newly-added effect and restores an edited one, and only the native handler
                    // knows which of the two this was.
                    CompanionActions.spellmakingEffectCancel()
                    EffectEditorState.close()
                }
                SpellmakingUiState.argPick != null -> SpellmakingUiState.argPick = null
            }
        }
    }

    val listState = rememberLazyListState()
    val focusIndex = rememberListNavFocus(
        itemCount = visible.size,
        enabled = !popupOpen,
        onConfirm = { i -> visible.getOrNull(i)?.let(addEffect) },
        onAction1 = buyAction,          // X
        // R3 → toggle the info popup for the focused effect. EFFECT, not item/spell: the id is a
        // MagicEffect RefId and only companion.lua's `effect:` branch can resolve it.
        onInfo = { i ->
            visible.getOrNull(i)?.let { ItemInfoPopupState.toggle(it.id, it.name, null, kind = InfoKind.EFFECT) }
        },
        onFocusChanged = { i ->
            if (ItemInfoPopupState.isOpen) {
                visible.getOrNull(i)?.let { ItemInfoPopupState.follow(it.id, it.name, null, kind = InfoKind.EFFECT) }
            }
        },
    )
    LaunchedEffect(focusIndex) {
        if (focusIndex in visible.indices) listState.animateScrollToItem(focusIndex)
    }

    Box(
        Modifier
            .fillMaxSize()
            .zIndex(18f)
            // Swallow stray taps: this fully replaces a native window and there is no
            // tap-outside-to-dismiss (Cancel is an explicit button, as in vanilla).
            .pointerInput(Unit) { detectTapGestures { } }
            .background(StoneDark)
    ) {
        Column(Modifier.fillMaxSize().padding(horizontal = 8.dp, vertical = 6.dp)) {

            // --- Header ---------------------------------------------------------------------------
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                Text(
                    "SPELLMAKING",
                    color = BronzeLight, fontSize = 18.sp, fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.weight(1f))
                Text(
                    "Gold: ${session.gold}",
                    color = BronzeLight, fontSize = 15.sp, fontFamily = MwData
                )
            }
            Spacer(Modifier.height(4.dp))
            Box(Modifier.fillMaxWidth().height(1.dp).background(Bronze))
            Spacer(Modifier.height(6.dp))

            // --- Filter ------------------------------------------------------------------------------
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                Box(
                    Modifier
                        .weight(1f)
                        .clip(RoundedCornerShape(3.dp))
                        .background(SlotBg)
                        .border(1.dp, BronzeDark, RoundedCornerShape(3.dp))
                        .clickable { searching = true }
                        .padding(horizontal = 11.dp, vertical = 12.dp)
                ) {
                    Text(
                        SpellmakingUiState.filter.ifBlank { "Search magic effects…" },
                        color = if (SpellmakingUiState.filter.isBlank()) BoneDim else BoneBright,
                        fontSize = 15.sp, fontFamily = MwBody, maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
                if (SpellmakingUiState.filter.isNotBlank()) {
                    Spacer(Modifier.width(6.dp))
                    EffectChip(label = "Clear", active = false, onTap = { SpellmakingUiState.filter = "" })
                }
            }

            Spacer(Modifier.height(6.dp))

            // --- Magic Effects browse list -------------------------------------------------------------
            // The union of every effect in any ST_Spell the player knows, filtered to
            // AllowSpellmaking (NOT AllowEnchanting — that one-line difference is made natively, in
            // the shared startEditing, on mType), deduplicated and name-sorted by the engine. A row
            // whose effect has NO legal range is greyed: vanilla ignores that tap silently (its own
            // unresolved TODO), so no message is invented here.
            if (visible.isEmpty()) {
                Box(Modifier.weight(1f).fillMaxWidth()) {
                    Text(
                        if (session.available.isEmpty()) "No known spellmaking effects"
                        else "No effects match",
                        color = BoneDim, fontSize = 15.sp, fontFamily = MwBody,
                        modifier = Modifier.padding(vertical = 12.dp)
                    )
                }
            } else {
                Row(Modifier.weight(1f).fillMaxWidth()) {
                    // Unkeyed, deliberately — same reasoning as the enchanting browse list: the ids
                    // ARE unique (startEditing dedupes), but keying would make a Compose crash the
                    // failure mode if that engine invariant ever slipped, and the list only ever
                    // changes by FILTERING, never reordering.
                    LazyColumn(state = listState, modifier = Modifier.weight(1f).fillMaxHeight()) {
                        itemsIndexed(visible) { i, avail ->
                            // constant is always false for spellmaking, so this is just the record's
                            // own CastSelf/Touch/Target flags.
                            val usable = effectRanges(avail.flags, session.constant).isNotEmpty()
                            val room = session.effects.size < session.effectCap
                            EffectPickRow(
                                icon = avail.icon,
                                title = avail.name,
                                subtitle = if (!usable) "Not available for spellmaking" else null,
                                enabled = usable && room,
                                focused = i == focusIndex,
                                infoId = avail.id,
                                onTap = { addEffect(avail) }
                            )
                        }
                    }
                    Spacer(Modifier.width(4.dp))
                    VerticalListScrollbar(listState, Modifier.fillMaxHeight())
                }
                ScrollMoreHint(listState)
            }

            Spacer(Modifier.height(6.dp))
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
            Spacer(Modifier.height(6.dp))

            // --- Price + Buy / Cancel ---------------------------------------------------------------
            Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
                Text(
                    "Price: ${session.price}",
                    color = if (session.cantAfford) BarterRed else BronzeLight,
                    fontSize = 15.sp, fontFamily = MwData
                )
                Spacer(Modifier.weight(1f))
                // ALWAYS enabled, exactly as in vanilla: pressing Buy with something missing is how
                // the validation message is produced, and there is no native "validate without
                // committing" call to grey it out with.
                EffectActionButton(
                    label = "Buy",
                    color = BronzeLight,
                    hint = "X",
                    onTap = buyAction
                )
                Spacer(Modifier.width(8.dp))
                // B, not a NAV binding: B is deliberately never intercepted at the top level, so it
                // reaches native exitCurrentGuiMode -> SpellCreationDialog::exit(), which emits the
                // close signal and pops the mode. The hint documents the button that already works.
                EffectActionButton(label = "Cancel", color = Bone, hint = "B") {
                    UiSounds.play(UiSounds.Cue.TOGGLE)
                    CompanionActions.spellmakingCancel()
                }
            }
        }

        // --- Validation / result banner --------------------------------------------------------------
        message?.let { (text, seq) ->
            LaunchedEffect(seq) {
                delay(ENCHANT_MSG_MS)
                GameStateRepository.clearSpellmakingMessage()
            }
            Box(
                Modifier.fillMaxWidth().align(Alignment.TopCenter).padding(top = 34.dp),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text,
                    color = BoneBright, fontSize = 13.sp, fontFamily = MwDisplay,
                    textAlign = TextAlign.Center,
                    modifier = Modifier
                        .fillMaxWidth(0.9f)
                        .clip(RoundedCornerShape(4.dp))
                        .background(Color(0xF2201A12))
                        .border(1.dp, BronzeLight, RoundedCornerShape(4.dp))
                        .padding(horizontal = 12.dp, vertical = 9.dp)
                )
            }
        }

        // --- Popup 1: skill / attribute selector -------------------------------------------------------
        SpellmakingUiState.argPick?.let { pick ->
            EffectArgPickerPopup(
                pick = pick,
                onPick = { argId ->
                    if (pick.isSkill) CompanionActions.spellmakingEffectSkill(pick.effectId, argId)
                    else CompanionActions.spellmakingEffectAttribute(pick.effectId, argId)
                    SpellmakingUiState.argPick = null
                },
                onCancel = { SpellmakingUiState.argPick = null }
            )
        }

        // --- Popup 2: effect editor --------------------------------------------------------------------
        if (EffectEditorState.editing) {
            val effect = session.effects.getOrNull(EffectEditorState.index)
            if (effect == null) {
                // The effect vanished under us (a Cancel raced a republish). Close rather than draw
                // an editor pointed at nothing.
                EffectEditorState.close()
            } else {
                EffectEditorPopup(
                    title = effect.text.ifBlank { "EFFECT" }.uppercase(),
                    flags = effect.flags,
                    constant = session.constant,
                    actions = SpellmakingEditorActions
                ) {
                    // Where enchanting shows its capacity fill, spellmaking shows the live magicka
                    // cost — there is no ceiling to fill, so there is no "/ max" half and no
                    // over-capacity colour.
                    Text(
                        "${session.costLabel.ifBlank { "Magicka Cost" }} ${session.cost}",
                        color = BoneDim, fontSize = 15.sp, fontFamily = MwData
                    )
                }
            }
        }

        // --- Search entry --------------------------------------------------------------------------
        if (searching) {
            TextInputOverlay(
                initialText = SpellmakingUiState.filter,
                title = "SEARCH MAGIC EFFECTS",
                onConfirm = { SpellmakingUiState.filter = it; searching = false },
                onCancel = { searching = false }
            )
        }

        // --- Spell name entry ------------------------------------------------------------------------
        // Raised from the TOP screen's name field, because the keyboard is touch-only and touch only
        // reaches the bottom panel. `!searching` keeps the two keyboards mutually exclusive.
        if (SpellmakingUiState.nameComposer && !searching) {
            TextInputOverlay(
                initialText = session.name,
                title = "SPELL NAME",
                onConfirm = {
                    CompanionActions.spellmakingSetName(it)
                    SpellmakingUiState.nameComposer = false
                },
                onCancel = { SpellmakingUiState.nameComposer = false }
            )
        }
    }
}

/**
 * TOP-screen spellmaking half: the name field, Magicka Cost / Spell Chance, and the live effects
 * readout.
 *
 * Hosted by [org.openmw.EngineActivity] in an INTERACTIVE panel window while a spellmaking session
 * is live AND Spellmaking is DS — interactive because the name field and the effect rows answer to a
 * tap (the name field raises the bottom screen's keyboard; an effect row opens the editor there).
 *
 * The readout shows the effects as they are RIGHT NOW, including one that is only half-configured:
 * a newly-added effect is on the spell from the moment the editor opens (vanilla's
 * eventEffectAdded), and Cancel is what takes it back off.
 */
@Composable
fun SpellmakingTopOverlay() {
    val session by GameStateRepository.spellmakingSession.collectAsState()
    val s = session ?: return

    // Sized identically to the enchanting and alchemy top panels so the DS service screens read as
    // one family.
    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.BottomCenter) {
        Row(
            Modifier
                .padding(bottom = ALCHEMY_TOP_PANEL_INSET)
                .fillMaxWidth(ALCHEMY_TOP_PANEL_WIDTH)
                .height(IntrinsicSize.Min)
                .heightIn(min = ENCHANT_TOP_PANEL_MIN_HEIGHT)
                .mwPanel()
                .padding(14.dp),
            horizontalArrangement = Arrangement.spacedBy(14.dp),
            verticalAlignment = Alignment.Top
        ) {
            // --- Left: name + stats ------------------------------------------------------------------
            Column(Modifier.weight(0.44f)) {
                Text(
                    "SPELL", color = BronzeLight, fontSize = 13.sp,
                    fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 1.sp
                )
                Spacer(Modifier.height(6.dp))
                Box(
                    Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(3.dp))
                        .background(SlotBg)
                        .border(1.dp, BronzeDark, RoundedCornerShape(3.dp))
                        .clickable { SpellmakingUiState.nameComposer = true }
                        .padding(horizontal = 10.dp, vertical = 11.dp)
                ) {
                    Text(
                        s.name.ifBlank { "Tap to name" },
                        color = if (s.name.isBlank()) BoneDim else BoneBright,
                        fontSize = 16.sp, fontFamily = MwBody, maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
                Spacer(Modifier.height(10.dp))

                // Both labels come from the ENGINE's own GMSTs, resolved in companionEmitState —
                // sEnchantmentMenu4 ("Magicka Cost") and sSpellmakingMenu1. The fallbacks are only
                // for a malformed batch; vanilla's wording is what normally shows.
                EnchantStatRow(s.costLabel.ifBlank { "Magicka Cost" }, "${s.cost}", BoneBright)
                EnchantStatRow(s.chanceLabel.ifBlank { "Spell Chance" }, "${s.chance}%", BoneBright)
                EnchantStatRow("Price", "${s.price}", if (s.cantAfford) BarterRed else BronzeLight)
            }

            Box(Modifier.width(1.dp).fillMaxHeight().background(BronzeDark))

            // --- Right: live effects readout -----------------------------------------------------------
            Column(Modifier.weight(0.56f)) {
                Text(
                    "EFFECTS ${s.effects.size}/${s.effectCap}", color = BronzeLight, fontSize = 13.sp,
                    fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 1.sp
                )
                Spacer(Modifier.height(6.dp))
                if (s.effects.isEmpty()) {
                    Text(
                        "None", color = BoneDim, fontSize = 14.sp, fontFamily = MwBody,
                        modifier = Modifier.padding(vertical = 6.dp)
                    )
                } else {
                    // ENGINE ORDER, never sorted. It is the handle every command uses AND — unlike
                    // enchanting — it changes the magicka cost: notifyEffectsChanged's Target x1.5
                    // multiplies the running total, so [Self, Target] and [Target, Self] cost
                    // differently. Reordering this list for display would misreport the real spell.
                    Column(Modifier.heightIn(max = ENCHANT_TOP_EFFECTS_MAX).verticalScroll(rememberScrollState())) {
                        s.effects.forEach { eff ->
                            val bmp = rememberItemIcon(eff.icon)
                            Row(
                                Modifier
                                    .fillMaxWidth()
                                    .clickable { CompanionActions.spellmakingEditEffect(eff.index) }
                                    .padding(vertical = 4.dp),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                if (bmp != null) {
                                    Image(bitmap = bmp, contentDescription = null,
                                        modifier = Modifier.size(22.dp))
                                    Spacer(Modifier.width(7.dp))
                                }
                                Text(
                                    // Composed natively from MWSpellEffect's own formatting, so this
                                    // reads exactly as the vanilla list does.
                                    eff.text,
                                    color = Bone, fontSize = 13.sp, fontFamily = MwBody,
                                    maxLines = 2, overflow = TextOverflow.Ellipsis
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

/**
 * Bottom-screen LEVEL UP window — the attribute picker.
 *
 * PRESENTATION ONLY. Every rule it appears to enforce is actually enforced by the native
 * LevelupDialog: a tap sends `CMP:levelup_pick:<id>` and the resulting selection comes back on
 * COMPANION_LEVELUP_SELECTION, so the toggle / replace-last-at-quota semantics are the game's and
 * this composable never computes them. Done sends `CMP:levelup_ok`, which lands on the native OK
 * handler — so even if the gate here were wrong, the commit would still refuse under quota and
 * show vanilla's own message.
 *
 * There is deliberately NO dismiss path: no scrim tap, no cancel button, and the back/B handler is
 * a consuming no-op. That mirrors how vanilla actually enforces it — the native window does not
 * refuse to close, its controller handler simply swallows B.
 *
 * The coin row is a small addition over vanilla, which only shows spent coins moving to the
 * attributes: here the count of filled vs required is explicit. Presentation, not behaviour.
 */
@Composable
private fun LevelUpOverlay(session: LevelUpSession) {
    var infoAttr by remember { mutableStateOf<LevelUpAttribute?>(null) }

    // NOTE there is deliberately no BackHandler here. The companion renders inside a Presentation,
    // which has no OnBackPressedDispatcherOwner, so BackHandler would not work; and B never reaches
    // Compose anyway. The no-exit rule is enforced on the ENGINE side, where the button actually
    // arrives: LevelupDialog::exit() refuses while Level up is DS, and windowmanagerimp's
    // escape-hatch is suppressed for that case, so B is a true no-op. See
    // companion-levelup-export.patch.

    Box(
        Modifier
            .fillMaxSize()
            .zIndex(18f)
            // Swallow every tap that misses a control: no tap-outside-to-dismiss here.
            .pointerInput(Unit) { detectTapGestures { } }
            .background(Color.Black.copy(alpha = 0.72f)),
        contentAlignment = Alignment.Center
    ) {
        Column(
            Modifier
                .fillMaxWidth(0.96f)
                .clip(RoundedCornerShape(4.dp))
                .background(StonePanel.copy(alpha = 0.98f))
                .border(2.dp, BronzeLight, RoundedCornerShape(4.dp))
                .padding(14.dp)
        ) {
            Text(
                "You have ascended to level ${session.level}",
                color = BronzeLight, fontSize = 15.sp, fontFamily = MwDisplay,
                fontWeight = FontWeight.Bold, maxLines = 1, overflow = TextOverflow.Ellipsis
            )
            Spacer(Modifier.height(6.dp))
            Box(Modifier.fillMaxWidth().height(1.dp).background(Bronze))
            Spacer(Modifier.height(8.dp))

            // Coins: one per REQUIRED pick. coinCount comes from the native window and is
            // min(3, attributes below 100) — it really does drop below 3 late-game, so this row is
            // sized from the session, never from a literal 3.
            Row(verticalAlignment = Alignment.CenterVertically) {
                repeat(session.coinCount) { i ->
                    val filled = i < session.selected.size
                    Box(
                        Modifier
                            .padding(end = 6.dp)
                            .size(14.dp)
                            .clip(CircleShape)
                            .background(if (filled) BronzeLight else Color(0xFF0E0B07))
                            .border(1.dp, if (filled) BronzeLight else BronzeDark, CircleShape)
                    )
                }
                Spacer(Modifier.width(4.dp))
                Text(
                    "${session.selected.size} of ${session.coinCount} chosen",
                    color = if (session.canConfirm) BoneBright else BoneDim,
                    fontSize = 11.sp, fontFamily = MwBody
                )
            }
            Spacer(Modifier.height(8.dp))

            // Two-column attribute grid, sized from the exported list rather than a hardcoded 8 —
            // the exporter walks the attribute record store, so a mod that adds attributes flows
            // through to both columns.
            val attrs = session.attributes
            val perCol = (attrs.size + 1) / 2
            // Capped and scrollable so the Done button can never be pushed off-screen. With the
            // stock 8 attributes the grid is ~200dp and never scrolls; the cap only engages if a
            // mod adds enough attributes to overflow, which is exactly the case a fixed layout
            // would have clipped silently. Both columns scroll as ONE unit.
            Row(
                Modifier
                    .fillMaxWidth()
                    .heightIn(max = LEVELUP_GRID_MAX_HEIGHT)
                    .verticalScroll(rememberScrollState())
            ) {
                listOf(0, 1).forEach { col ->
                    Column(Modifier.weight(1f).padding(end = if (col == 0) 6.dp else 0.dp)) {
                        val from = col * perCol
                        val to = minOf(from + perCol, attrs.size)
                        if (from < to) attrs.subList(from, to).forEach { attr ->
                            LevelUpAttributeRow(
                                attr = attr,
                                selected = session.isSelected(attr.id),
                                onTap = {
                                    if (!attr.disabled) {
                                        UiSounds.play(UiSounds.Cue.TOGGLE)
                                        CompanionActions.levelUpPick(attr.id)
                                    }
                                },
                                onInfo = { infoAttr = attr }
                            )
                        }
                    }
                }
            }

            Spacer(Modifier.height(10.dp))
            // Done. Gated on the session's own canConfirm, which is exactly the native condition
            // (selected >= coinCount) evaluated against the native coin count.
            val enabled = session.canConfirm
            Box(
                Modifier
                    .fillMaxWidth()
                    .clip(RoundedCornerShape(4.dp))
                    .background(if (enabled) PillActiveBg else Color(0xFF15120F))
                    .border(1.dp, if (enabled) BronzeLight else BronzeDark, RoundedCornerShape(4.dp))
                    .then(
                        if (enabled) Modifier.clickable {
                            UiSounds.play(UiSounds.Cue.ACTION)
                            CompanionActions.levelUpConfirm()
                        } else Modifier
                    )
                    .padding(vertical = 11.dp),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    "Done",
                    color = if (enabled) BoneBright else BoneMuted,
                    fontSize = 14.sp, fontFamily = MwDisplay, fontWeight = FontWeight.Bold
                )
            }
        }

        // Info panel for a tapped attribute. Shows the count, the resulting multiplier and the
        // skills that GOVERN the attribute — deliberately not a per-skill contribution breakdown,
        // which the engine does not record (it stores only the bare count).
        infoAttr?.let { attr ->
            Box(
                Modifier
                    .fillMaxSize()
                    .zIndex(1f)
                    .pointerInput(attr.id) { detectTapGestures { infoAttr = null } }
                    .background(Color.Black.copy(alpha = 0.55f)),
                contentAlignment = Alignment.Center
            ) {
                Column(
                    Modifier
                        .fillMaxWidth(0.8f)
                        .clip(RoundedCornerShape(3.dp))
                        .background(StonePanel.copy(alpha = 0.98f))
                        .border(2.dp, BronzeDark, RoundedCornerShape(3.dp))
                        .pointerInput(attr.id) { detectTapGestures { } }
                        .padding(12.dp)
                ) {
                    Text(
                        attr.name, color = BronzeLight, fontSize = 14.sp,
                        fontFamily = MwDisplay, fontWeight = FontWeight.Bold
                    )
                    if (attr.description.isNotBlank()) {
                        Spacer(Modifier.height(4.dp))
                        Text(attr.description, color = Bone, fontSize = 11.sp, fontFamily = MwBody)
                    }
                    Spacer(Modifier.height(8.dp))
                    Text(
                        if (attr.count > 0)
                            "${attr.count} skill increase${if (attr.count == 1) "" else "s"} " +
                                "since your last level, worth x${attr.mult} here."
                        else
                            "No skill increases since your last level, so this rises by 1.",
                        color = BoneBright, fontSize = 11.sp, fontFamily = MwBody
                    )
                    if (attr.skills.isNotEmpty()) {
                        Spacer(Modifier.height(8.dp))
                        Text(
                            "GOVERNS", color = BronzeLight, fontSize = 9.sp,
                            fontFamily = MwDisplay, letterSpacing = 0.8.sp
                        )
                        Spacer(Modifier.height(2.dp))
                        Text(
                            attr.skills.joinToString(", "),
                            color = BoneDim, fontSize = 11.sp, fontFamily = MwBody
                        )
                    }
                }
            }
        }
    }
}

/**
 * One attribute row: coin marker, icon, name, current→projected value, and the multiplier caption.
 *
 * Sized as a real button rather than a list row — [LEVELUP_ROW_MIN_HEIGHT] with Rest/Wait's own
 * `vertical = 9.dp` padding, so the eight of them are as easy to hit as the service overlays'
 * buttons. The containing panel simply grows to suit.
 *
 * SELECTED STATE IS SHOWN FOUR WAYS, deliberately: a filled coin at the left, a bronze-tinted fill,
 * a bright border, and the value switching to `base→projected`. The coin is the one that carries
 * it — vanilla moves an actual coin next to the attribute you spend it on, and the fill/border
 * alone read as "focused" more than "chosen". A tick glyph was NOT used: MysticCards has no U+2713
 * (see the missing-glyph list under "Game font"), so it would render as tofu with the game font on.
 */
private val LEVELUP_ROW_MIN_HEIGHT = 44.dp

/** Cap on the attribute grid's height, past which it scrolls. Sized so the stock 8 attributes
 *  (4 rows per column, ~200dp) never scroll — it exists only so a modded attribute list cannot
 *  push the Done button off the 468dp-tall companion panel. */
private val LEVELUP_GRID_MAX_HEIGHT = 300.dp

@Composable
private fun LevelUpAttributeRow(
    attr: LevelUpAttribute,
    selected: Boolean,
    onTap: () -> Unit,
    onInfo: () -> Unit
) {
    val icon = rememberItemIcon(attr.icon)
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 3.dp)
            .heightIn(min = LEVELUP_ROW_MIN_HEIGHT)
            .clip(RoundedCornerShape(3.dp))
            .background(if (selected) SlotWorn else Color(0xC0151210))
            .border(
                if (selected) 2.dp else 1.dp,
                if (selected) BronzeLight else BronzeDark,
                RoundedCornerShape(3.dp)
            )
            .combinedClickable(
                enabled = !attr.disabled,
                onClick = onTap,
                onLongClick = onInfo
            )
            .padding(horizontal = 7.dp, vertical = 9.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        // Coin marker. Always occupies its slot so the icons stay column-aligned whether or not a
        // row is selected — an appearing/disappearing coin would shuffle every name sideways.
        Box(
            Modifier
                .size(12.dp)
                .clip(CircleShape)
                .background(if (selected) BronzeLight else Color.Transparent)
                .border(
                    1.dp,
                    if (selected) BronzeLight else BronzeDark.copy(alpha = 0.5f),
                    CircleShape
                )
        )
        Spacer(Modifier.width(6.dp))
        Box(Modifier.size(22.dp)) {
            if (icon != null) {
                Image(
                    bitmap = icon, contentDescription = null,
                    contentScale = ContentScale.Fit, modifier = Modifier.fillMaxSize()
                )
            }
        }
        Spacer(Modifier.width(6.dp))
        Text(
            attr.name,
            color = when {
                attr.disabled -> BoneMuted
                selected -> BoneBright
                else -> Bone
            },
            fontSize = 12.sp, fontFamily = MwBody,
            fontWeight = if (selected) FontWeight.Bold else FontWeight.Normal,
            maxLines = 1, overflow = TextOverflow.Ellipsis,
            modifier = Modifier.weight(1f)
        )
        // Multiplier caption: shown ONLY above x1, exactly as vanilla. `mult` arrives already
        // clamped to 100 - base, so an attribute near the cap advertises what it can really gain.
        if (attr.mult > 1 && !attr.disabled) {
            Text(
                "x${attr.mult}",
                color = BronzeLight, fontSize = 12.sp, fontFamily = MwData,
                modifier = Modifier.padding(end = 6.dp)
            )
        }
        Text(
            if (selected) "${attr.base}→${attr.projected}" else "${attr.base}",
            color = if (selected) BoneBright else if (attr.disabled) BoneMuted else Bone,
            fontSize = 12.sp, fontFamily = MwData, maxLines = 1
        )
    }
}

// Tweakable timings for the training completion flow (see TrainingOverlayHost).
private const val TRAINING_SAFETY_MS = 5000L         // force-dismiss if CLOSED never arrives
private const val TRAINING_COMPLETE_DWELL_MS = 1200L // how long "…training complete" shows

private enum class TrainingPhase { LIST, TRAINING, COMPLETE }

/**
 * Host for the bottom-screen training overlay. Driven by COMPANION_TRAINING_* (native TrainingWindow).
 * Unlike Repair, the overlay must OUTLIVE [GameStateRepository.trainingSession] going null: the repo
 * nulls the session on COMPANION_TRAINING_CLOSED (fired after the native 2-hour fade/advance), but the
 * "…training complete" message needs to show afterwards. So mount is latched locally ([overlayActive],
 * set when a session first appears, cleared only by the dismiss path) and the NPC name is cached, and
 * a local three-state machine drives the content:
 *
 *   LIST → (tap a valid skill) → TRAINING → (CLOSED / 5s safety) → COMPLETE → (1.2s dwell) → dismissed
 *
 * On EVERY dismiss path we also call [CompanionActions.trainCancel] — idempotent (native guards on
 * containsMode(GM_Training); the CLOSED emit is once-guarded), so it no-ops if the mode already popped,
 * but rescues a stuck hidden GM_Training if a train command was rejected and no CLOSED ever came.
 */
@Composable
private fun TrainingOverlayHost(session: TrainingSession?) {
    var overlayActive by remember { mutableStateOf(false) }
    var phase by remember { mutableStateOf(TrainingPhase.LIST) }
    var trainedSkillName by remember { mutableStateOf("") }
    var cachedNpcName by remember { mutableStateOf("") }

    val hasSession = session != null

    fun dismiss() {
        CompanionActions.trainCancel() // idempotent; rescues a stuck GM_Training if the train was rejected
        overlayActive = false
        phase = TrainingPhase.LIST
    }

    // Activate + cache the NPC name when a session first appears. Latched — we do NOT unmount when
    // the session later goes null (the TRAINING/COMPLETE messages must outlive COMPANION_TRAINING_CLOSED).
    LaunchedEffect(hasSession) {
        if (session != null) {
            overlayActive = true
            session.npcName.takeIf { it.isNotBlank() }?.let { cachedNpcName = it }
        }
    }

    // Session-null transitions: from TRAINING it means the train finished (→ COMPLETE); from LIST it
    // means the conversation ended externally (B / native close / NPC left) with no train in flight,
    // so just tear the overlay down. COMPLETE is timer-driven and ignores the session.
    LaunchedEffect(phase, hasSession) {
        if (!hasSession && overlayActive) {
            when (phase) {
                TrainingPhase.TRAINING -> phase = TrainingPhase.COMPLETE
                TrainingPhase.LIST -> dismiss()
                else -> Unit
            }
        }
    }

    // Timed transitions: safety net out of TRAINING, and the COMPLETE dwell before dismiss.
    LaunchedEffect(phase) {
        when (phase) {
            TrainingPhase.TRAINING -> {
                delay(TRAINING_SAFETY_MS)
                if (phase == TrainingPhase.TRAINING) phase = TrainingPhase.COMPLETE
            }
            TrainingPhase.COMPLETE -> {
                delay(TRAINING_COMPLETE_DWELL_MS)
                dismiss()
            }
            else -> Unit
        }
    }

    if (!overlayActive) return

    // Bottom vs Split from the training layout pref (Top pending → never selectable; falls back to
    // the bottom card). Mirrors the looting/bartering per-service layout selectors.
    val splitMode = UiPreferences.trainingLocationFlow().collectAsState().value == ScreenLocation.SPLIT
    val rowFontSize = if (splitMode) SPLIT_ROW_FONT_SIZE else 14.sp
    val skills = session?.skills ?: emptyList()
    val playerGold = session?.playerGold ?: 0

    // Tapping any NON-capped row sends the train command; native silently rejects it if the player
    // can't afford it (matches Spell Buying — unaffordable is a transient gold state, not a hard block
    // like capped). We only enter the TRAINING/COMPLETE flow when the train will actually happen
    // (affordable), so a rejected unaffordable tap stays on the list instead of showing a false
    // "…training complete". Capped rows never reach here (non-tappable / onConfirm-guarded).
    fun attemptTrain(sk: TrainingSkill) {
        if (sk.capped) return
        CompanionActions.trainSkill(sk.index)
        if (sk.cost <= playerGold) {
            trainedSkillName = sk.skillName
            GameStateRepository.markTrainingInProgress()
            phase = TrainingPhase.TRAINING
        }
    }

    // List navigation (LIST phase only): D-pad up/down, A trains the focused row, B cancels.
    val focusIndex = rememberListNavFocus(
        itemCount = skills.size,
        enabled = phase == TrainingPhase.LIST,
        onConfirm = { i -> skills.getOrNull(i)?.let { attemptTrain(it) } },
        onCancel = { if (phase == TrainingPhase.LIST) dismiss() }
    )
    val listState = rememberLazyListState()
    LaunchedEffect(focusIndex) {
        if (focusIndex in skills.indices) listState.animateScrollToItem(focusIndex)
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(17f)
            .background(Color(0xCC0F0C08))
            .pointerInput(Unit) { detectTapGestures {} }, // swallow taps; NO tap-outside dismiss
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .then(if (splitMode) Modifier.splitDialoguePanel() else Modifier.fillMaxWidth(0.7f).fillMaxHeight(0.86f))
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures {} }
        ) {
            // ---- Title bar ----
            Text(
                "Training: ${cachedNpcName.ifBlank { "Trainer" }}",
                color = BronzeLight, fontSize = 15.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                maxLines = 1, overflow = TextOverflow.Ellipsis,
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp)
            )
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))

            // ---- Content: list (LIST) or centred message (TRAINING / COMPLETE) ----
            if (phase == TrainingPhase.LIST) {
                if (skills.isEmpty()) {
                    Box(Modifier.fillMaxWidth().weight(1f), contentAlignment = Alignment.Center) {
                        Text("No skills to train", color = BoneDim, fontSize = 13.sp, fontFamily = MwBody)
                    }
                } else {
                    LazyColumn(state = listState, modifier = Modifier.fillMaxWidth().weight(1f)) {
                        itemsIndexed(skills, key = { _, sk -> sk.index }) { i, sk ->
                            TrainingRow(
                                skill = sk,
                                affordable = sk.cost <= playerGold,
                                nameFontSize = rowFontSize,
                                focused = i == focusIndex,
                                onTrain = { attemptTrain(sk) }
                            )
                            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
                        }
                    }
                }
            } else {
                Box(Modifier.fillMaxWidth().weight(1f), contentAlignment = Alignment.Center) {
                    Text(
                        if (phase == TrainingPhase.COMPLETE) "${trainedSkillName.ifBlank { "Skill" }} training complete"
                        else "Training…",
                        color = BronzeLight, fontSize = 16.sp,
                        fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.padding(horizontal = 20.dp)
                    )
                }
            }

            // ---- Divider + bottom row ----
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Text(
                    "Gold: $playerGold", color = BronzeLight, fontSize = 13.sp,
                    fontFamily = MwData, modifier = Modifier.weight(1f)
                )
                // Cancel only makes sense while choosing (LIST); during the messages it's inert.
                RepairButton(label = "Cancel", color = ActionCancel, enabled = phase == TrainingPhase.LIST) {
                    dismiss()
                }
            }
        }
    }
}

/** One training row: skill name (flex) + "Current: X[ (capped)]" beneath + cost. Capped rows are
 *  dimmed with "—" and fully non-tappable (a hard block — the skill can't be trained here at all).
 *  Unaffordable rows show a RED cost but stay tappable/focusable (matches SpellForSaleRow): a tap
 *  sends the train command and the native window rejects it silently, and keeping them focusable
 *  preserves a stable D-pad order as gold changes. */
@Composable
private fun TrainingRow(
    skill: TrainingSkill,
    affordable: Boolean,
    nameFontSize: TextUnit = 14.sp,
    focused: Boolean = false,
    onTrain: () -> Unit
) {
    val tappable = !skill.capped
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .then(
                if (focused) Modifier.background(BronzeLight.copy(alpha = 0.12f)).border(2.dp, BronzeLight)
                else Modifier
            )
            .then(if (tappable) Modifier.clickable { onTrain() } else Modifier)
            .padding(horizontal = 14.dp, vertical = 10.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(
                skill.skillName,
                color = when {
                    skill.capped -> BoneDim
                    focused -> BoneBright
                    else -> Bone
                },
                fontSize = nameFontSize, fontFamily = MwBody,
                maxLines = 1, overflow = TextOverflow.Ellipsis
            )
            Text(
                if (skill.capped) "Current: ${skill.currentLevel} (capped)" else "Current: ${skill.currentLevel}",
                color = BoneDim, fontSize = 10.sp, fontFamily = MwData
            )
        }
        Text(
            if (skill.capped) "-" else "${skill.cost}g",
            color = when {
                skill.capped -> BoneDim
                affordable -> BronzeLight
                else -> RepairCondRed
            },
            fontSize = 13.sp, fontFamily = MwData, fontWeight = FontWeight.Bold,
            textAlign = TextAlign.End,
            modifier = Modifier.width(60.dp)
        )
    }
}

/* ---- Spell-buying overlay (bottom screen) ---- */

/**
 * Bottom-screen spell-buying overlay. Driven by COMPANION_SPELLBUYING_* (native SpellBuyingWindow),
 * shown whenever [GameStateRepository.spellBuyingSession] is non-null and Spell buying is DS. Same
 * frame as RepairOverlay (in-window centred Box at zIndex 17f, no tap-outside dismiss). Each row taps
 * to buy immediately; the engine re-exports the list + gold after each purchase, so [session] just
 * refreshes in place (the bought spell reappears greyed as "Already known", holding indices stable).
 */
@Composable
private fun SpellBuyingOverlay(session: SpellBuyingSession) {
    // Close any open spell-info popup when the buying session ends (overlay leaves composition).
    DisposableEffect(Unit) { onDispose { ItemInfoPopupState.close() } }
    // Bottom vs Split from the spell-buying layout pref (Top pending → falls back to the bottom card).
    val splitMode = UiPreferences.spellBuyingLocationFlow().collectAsState().value == ScreenLocation.SPLIT
    val rowFontSize = if (splitMode) SPLIT_ROW_FONT_SIZE else 14.sp
    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(17f)
            .background(Color(0xCC0F0C08))
            .pointerInput(Unit) { detectTapGestures {} }, // swallow taps; NO tap-outside dismiss
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .then(if (splitMode) Modifier.splitDialoguePanel() else Modifier.fillMaxWidth(0.7f).fillMaxHeight(0.86f))
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures {} }
        ) {
            // ---- Title bar ----
            Text(
                "Spells: ${session.npcName.ifBlank { "Merchant" }}",
                color = BronzeLight, fontSize = 15.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                maxLines = 1, overflow = TextOverflow.Ellipsis,
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp)
            )
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))

            // ---- Spell list ---- (D-pad up/down navigate, A buys the focused one)
            val focusIndex = rememberListNavFocus(
                itemCount = session.spells.size,
                onConfirm = { i ->
                    session.spells.getOrNull(i)?.let { sp ->
                        // Known → nothing to buy. Unaffordable → tappable but native rejects silently.
                        if (!sp.known) CompanionActions.buySpell(sp.index)
                    }
                },
                // R3 → toggle the info popup for the focused spell (same idea as barter items).
                onInfo = { i ->
                    session.spells.getOrNull(i)?.let { sp ->
                        ItemInfoPopupState.toggle(sp.id, sp.spellName, null, kind = InfoKind.SPELL)
                    }
                },
                // D-pad focus moved → if the info popup is open, follow to the newly focused spell.
                // Done here (synchronously, before recomposition) so the new row re-reports its anchor
                // in the ensuing layout pass — otherwise the popup would blank out (see barter parity).
                onFocusChanged = { i ->
                    if (ItemInfoPopupState.isOpen) {
                        session.spells.getOrNull(i)?.let { sp ->
                            ItemInfoPopupState.follow(sp.id, sp.spellName, null, kind = InfoKind.SPELL)
                        }
                    }
                },
            )
            val listState = rememberLazyListState()
            LaunchedEffect(focusIndex) {
                if (focusIndex in session.spells.indices) listState.animateScrollToItem(focusIndex)
            }
            if (session.spells.isEmpty()) {
                Box(Modifier.fillMaxWidth().weight(1f), contentAlignment = Alignment.Center) {
                    Text("No spells for sale", color = BoneDim, fontSize = 13.sp, fontFamily = MwBody)
                }
            } else {
                LazyColumn(state = listState, modifier = Modifier.fillMaxWidth().weight(1f)) {
                    itemsIndexed(session.spells, key = { _, sp -> sp.index }) { i, spell ->
                        SpellForSaleRow(
                            spell = spell,
                            affordable = spell.cost <= session.playerGold,
                            nameFontSize = rowFontSize,
                            focused = i == focusIndex,
                            onBuy = { if (!spell.known) CompanionActions.buySpell(spell.index) },
                            onInfo = { ItemInfoPopupState.open(spell.id, spell.spellName, null, kind = InfoKind.SPELL) }
                        )
                        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
                    }
                }
            }

            // ---- Divider + bottom row ----
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Text(
                    "Gold: ${session.playerGold}", color = BronzeLight, fontSize = 13.sp,
                    fontFamily = MwData, modifier = Modifier.weight(1f)
                )
                RepairButton(label = "Cancel", color = ActionCancel, enabled = true) {
                    CompanionActions.spellBuyingCancel()
                }
            }
        }
    }
}

/** One spell-for-sale row: name (flex) + school beneath + cost. Known spells are dimmed with
 *  "Already known" + "—" and non-tappable-to-buy; unaffordable spells show a red cost but stay tappable
 *  (the native window rejects the purchase silently — the red cost is the only signal). Long-press (or
 *  R3 on the focused row) opens the spell info popup — same idea as barter items. */
@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun SpellForSaleRow(
    spell: SpellForSale,
    affordable: Boolean,
    nameFontSize: TextUnit = 14.sp,
    focused: Boolean = false,
    onBuy: () -> Unit,
    onInfo: () -> Unit = {}
) {
    // Report bounds so the info popup can anchor beside this row (same pattern as ItemRow/SpellRow).
    Box(modifier = Modifier.onGloballyPositioned { ItemInfoPopupState.reportAnchor(spell.id, it.boundsInRoot()) }) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .then(
                if (focused) Modifier.background(BronzeLight.copy(alpha = 0.12f)).border(2.dp, BronzeLight)
                else Modifier
            )
            // Tap buys (no-op for known via onBuy's own guard); long-press opens info for ANY spell.
            .combinedClickable(onClick = onBuy, onLongClick = onInfo)
            .padding(horizontal = 14.dp, vertical = 10.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(
                spell.spellName,
                color = when {
                    spell.known -> BoneDim
                    focused -> BoneBright
                    else -> Bone
                },
                fontSize = nameFontSize, fontFamily = MwBody,
                maxLines = 1, overflow = TextOverflow.Ellipsis
            )
            Text(
                if (spell.known) "Already known" else spell.school,
                color = BoneDim, fontSize = 10.sp, fontFamily = MwData
            )
        }
        Text(
            if (spell.known) "-" else "${spell.cost}g",
            color = when {
                spell.known -> BoneDim
                affordable -> BronzeLight
                else -> RepairCondRed
            },
            fontSize = 13.sp, fontFamily = MwData, fontWeight = FontWeight.Bold,
            textAlign = TextAlign.End,
            modifier = Modifier.width(60.dp)
        )
    }
    }
}

/* ---- Travel overlay (bottom screen) ---- */

/**
 * Bottom-screen travel overlay. Driven by COMPANION_TRAVEL_* (native TravelWindow), shown whenever
 * [GameStateRepository.travelSession] is non-null and Travel is DS. NOT a Compose Dialog (crashes on
 * the Presentation display — see ItemInfoOverlay); an in-window centred Box at zIndex 17f. No
 * tap-outside dismiss — only Cancel closes it (→ CMP:travel_cancel → the engine pops GM_Travel and
 * emits COMPANION_TRAVEL_CLOSED). Each row taps to travel to that destination immediately
 * (→ CMP:travel_go <index> → the native onTravelButtonClick path: gold, time advance, follower
 * teleport). Travelling also ends the conversation, so the dialogue overlay dismisses alongside.
 */
@Composable
private fun TravelOverlay(session: TravelSession) {
    // Bottom vs Split from the travel layout pref (Top pending → falls back to the bottom card).
    // Currently BOTTOM-only (no Split pill), so this is always the centred card.
    val splitMode = UiPreferences.travelLocationFlow().collectAsState().value == ScreenLocation.SPLIT
    val rowFontSize = if (splitMode) SPLIT_ROW_FONT_SIZE else 14.sp
    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(17f)
            .background(Color(0xCC0F0C08))
            // Swallow taps so nothing falls through to the tab underneath. NO dismiss.
            .pointerInput(Unit) { detectTapGestures {} },
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .then(if (splitMode) Modifier.splitDialoguePanel() else Modifier.fillMaxWidth(0.7f).fillMaxHeight(0.86f))
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures {} }
        ) {
            // ---- Title bar ----
            Text(
                "Travel: ${session.npcName.ifBlank { "Caravaner" }}",
                color = BronzeLight, fontSize = 15.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                maxLines = 1, overflow = TextOverflow.Ellipsis,
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp)
            )
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))

            // ---- Destination list ---- (D-pad up/down navigate, A travels to the focused one)
            val focusIndex = rememberListNavFocus(
                itemCount = session.destinations.size,
                onConfirm = { i ->
                    val d = session.destinations[i]
                    if (d.cost <= session.playerGold) CompanionActions.travelGo(d.index)
                },
            )
            val listState = rememberLazyListState()
            LaunchedEffect(focusIndex) {
                if (focusIndex in session.destinations.indices) listState.animateScrollToItem(focusIndex)
            }
            if (session.destinations.isEmpty()) {
                Box(Modifier.fillMaxWidth().weight(1f), contentAlignment = Alignment.Center) {
                    Text(
                        "No destinations", color = BoneDim,
                        fontSize = 13.sp, fontFamily = MwBody
                    )
                }
            } else {
                LazyColumn(state = listState, modifier = Modifier.fillMaxWidth().weight(1f)) {
                    itemsIndexed(session.destinations, key = { _, it -> it.index }) { i, dest ->
                        TravelRow(
                            dest = dest,
                            affordable = dest.cost <= session.playerGold,
                            nameFontSize = rowFontSize,
                            focused = i == focusIndex,
                            onTravel = { CompanionActions.travelGo(dest.index) }
                        )
                        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
                    }
                }
            }

            // ---- Divider + bottom row (player gold + Cancel; no "Travel All") ----
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                Text(
                    "Gold: ${session.playerGold}", color = BronzeLight, fontSize = 13.sp,
                    fontFamily = MwData, modifier = Modifier.weight(1f)
                )
                RepairButton(label = "Cancel", color = ActionCancel, enabled = true) {
                    CompanionActions.travelCancel()
                }
            }
        }
    }
}

/** One travel row: destination name (flex) + cost, tap to travel immediately. Unaffordable rows are
 *  dimmed with a red cost and are not tappable (the engine ignores them anyway). */
@Composable
private fun TravelRow(
    dest: TravelDest,
    affordable: Boolean,
    nameFontSize: TextUnit = 14.sp,
