/* ---- Rest/Wait overlay (bottom screen) ---- */

/**
 * Bottom-screen rest/wait picker. Driven by COMPANION_SLEEP_* (native WaitDialog), shown
 * whenever [GameStateRepository.sleepSession] is non-null and Rest/Wait is DS. NOT a Compose
 * Dialog (crashes on the Presentation display); an in-window centred Box at zIndex 17f, no
 * tap-outside dismiss. Confirming "Rest"/"Wait" sends CMP:sleep <hours> — the engine then runs
 * the fade + time advance (+ sleep interruption / level-up) on the TOP screen and emits
 * COMPANION_SLEEP_CLOSED, which dismisses this overlay. Cancel sends CMP:sleep_cancel.
 */
@Composable
private fun RestWaitOverlay(session: SleepSession) {
    val isRest = session.mode == SleepMode.REST
    var hours by remember { mutableStateOf(1) }

    // Controller: D-pad left/right adjust the hours by ±1; the left stick (SliderLeft/Right, polled
    // at ~60ms) does the same but smoothly while held; A confirms (Rest/Wait); X rests until healed
    // when that button is available (mirrors vanilla's X binding). B cancels natively.
    LaunchedEffect(Unit) {
        var lastSeq = GameStateRepository.navEvent.value?.seq ?: -1L
        GameStateRepository.navEvent.collect { ev ->
            if (ev == null || ev.seq <= lastSeq) return@collect
            lastSeq = ev.seq
            when (ev) {
                is NavEvent.Left, is NavEvent.SliderLeft -> hours = (hours - 1).coerceIn(1, 24)
                is NavEvent.Right, is NavEvent.SliderRight -> hours = (hours + 1).coerceIn(1, 24)
                is NavEvent.Confirm -> CompanionActions.sleep(hours)
                is NavEvent.Action1 ->
                    if (isRest && session.untilHealedAvailable) CompanionActions.sleep(session.hoursToHeal)
                else -> Unit
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(17f)
            .background(Color(0xCC0F0C08))
            .pointerInput(Unit) { detectTapGestures {} },   // swallow taps, NO dismiss
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth(0.7f)
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures {} }
        ) {
            // ---- Title ----
            Text(
                if (isRest) "Rest" else "Wait",
                color = BronzeLight, fontSize = 15.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp)
            )
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))

            Column(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 14.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                // ---- Date / time ----
                Text(
                    session.dateString, color = Bone, fontSize = 15.sp,
                    fontFamily = MwBody, textAlign = TextAlign.Center,
                    modifier = Modifier.fillMaxWidth()
                )
                Spacer(Modifier.height(14.dp))

                // ---- Middle line: illegal-rest warning (WAIT) or "REST" banner ----
                if (!isRest && session.warning.isNotBlank()) {
                    Text(
                        session.warning, color = RepairCondRed, fontSize = 13.sp,
                        fontFamily = MwBody, textAlign = TextAlign.Center,
                        modifier = Modifier.fillMaxWidth()
                    )
                    Spacer(Modifier.height(14.dp))
                } else if (isRest) {
                    Text(
                        "REST", color = BronzeLight, fontSize = 22.sp,
                        fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 3.sp,
                        textAlign = TextAlign.Center, modifier = Modifier.fillMaxWidth()
                    )
                    Spacer(Modifier.height(14.dp))
                }

                // ---- Hours label ----
                Text(
                    "$hours ${if (hours == 1) "hour" else "hours"}",
                    color = Bone, fontSize = 16.sp, fontFamily = MwData,
                    fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.height(4.dp))

                // ---- Slider (1..24, no track numbers, 1h / 24h end labels) ----
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text("1h", color = BoneDim, fontSize = 11.sp, fontFamily = MwData)
                    Slider(
                        value = hours.toFloat(),
                        onValueChange = { hours = it.roundToInt().coerceIn(1, 24) },
                        valueRange = 1f..24f,
                        steps = 22,   // 24 discrete stops (1..24)
                        colors = SliderDefaults.colors(
                            thumbColor = BronzeLight,
                            activeTrackColor = BronzeLight,
                            inactiveTrackColor = BronzeDark,
                            activeTickColor = Color.Transparent,
                            inactiveTickColor = Color.Transparent
                        ),
                        modifier = Modifier.weight(1f).padding(horizontal = 10.dp)
                    )
                    Text("24h", color = BoneDim, fontSize = 11.sp, fontFamily = MwData)
                }
            }

            // ---- Buttons ----
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            // "Rest Until Healed" — REST mode only, and only when the engine reports it available
            // (health or magicka below max). Rests for the exact native getHoursToRest() count,
            // replayed via the existing CMP:sleep <hours>. Full-width row above Rest/Cancel so the
            // long label has room; mirrors vanilla, which shows it only in this same condition.
            if (isRest && session.untilHealedAvailable) {
                Row(
                    modifier = Modifier.fillMaxWidth().padding(start = 14.dp, end = 14.dp, top = 14.dp),
                ) {
                    RepairButton(
                        label = "Rest Until Healed",
                        // Was already BronzeLight — i.e. this button is what the rest of them now
                        // look like. Named for its role so it stays in step with them.
                        color = ActionConfirm, enabled = true,
                        modifier = Modifier.fillMaxWidth()
                    ) { CompanionActions.sleep(session.hoursToHeal) }
                }
            }
            Row(
                modifier = Modifier.fillMaxWidth().padding(14.dp),
                horizontalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                RepairButton(
                    label = if (isRest) "Rest" else "Wait",
                    color = ActionConfirm, enabled = true,
                    modifier = Modifier.weight(1f)
                ) { CompanionActions.sleep(hours) }
                RepairButton(
                    label = "Cancel", color = ActionCancel, enabled = true,
                    modifier = Modifier.weight(1f)
                ) { CompanionActions.sleepCancel() }
            }
        }
    }
}

/* ---- Barter overlay (bottom screen) ---- */

// Money DIRECTION only — green "you receive" vs red "you pay", the pairing that makes the offer
// balance readable at a glance. Same two values as the magic-effect dots, deliberately.
//
// These are NOT button colours. Every service overlay's buttons used to take BarterGreen (confirm)
// and a BarterBlue (cancel), which put a green and a blue button in the middle of an otherwise
// entirely bronze UI; they now use [ActionConfirm]/[ActionCancel] below. BarterBlue is gone
// entirely — it only ever meant "Cancel", and that is a role, not a value.
private val BarterGreen = Color(0xFF7FBF7F)   // "player receives" (matches effect green)
private val BarterRed = Color(0xFFC75C5C)     // "player pays" / rejected (matches effect red)

/** The per-side visible barter list: filter by the selected category tab, then sort. On the PLAYER
 *  side, worn (equipped) items are floated to the top; the existing [itemCategoryRank] + name order is
 *  the secondary sort, applied WITHIN the worn group and WITHIN the rest (a stable worn-first
 *  partition, not a full re-sort). This worn-first float is a deliberate DS barter UX choice — vanilla
 *  does NOT float equipped items in its own barter window — and is scoped to this barter list only: it
 *  does not touch the shared category+name convention used by the inventory tab / looting. The merchant
 *  side keeps plain category+name order (vendor items are never worn). Shared by both barter layouts
 *  (BarterGridCell / BarterRow) and the controller focus index so the D-pad index maps 1:1 to a visible
 *  cell/row. */
private fun barterVisible(
    items: List<BarterItem>,
    category: String?,
    isPlayerSide: Boolean,
    // DEFAULT keeps barter's own original order (worn-first player, then category + name). An
    // explicit Weight/Value sort is a pure ordering over the whole side — no worn tier, no category
    // tier — matching the inventory tab.
    sortMode: InvSort = InvSort.DEFAULT,
    sortDescending: Boolean = true
): List<BarterItem> {
    val filtered = items.filter { category == null || it.category == category }
    if (sortMode != InvSort.DEFAULT) {
        return filtered.sortedWith(
            invSortComparator(sortMode, sortDescending, { it.displayName() }, { it.weight }, { it.value })
        )
    }
    val byCategoryThenName = compareBy<BarterItem>({ itemCategoryRank(it.category) }, { it.displayName().lowercase() })
    val comparator =
        if (isPlayerSide) compareByDescending<BarterItem> { it.worn }.then(byCategoryThenName)
        else byCategoryThenName
    return filtered.sortedWith(comparator)
}

/**
 * The sort modes the barter overlay offers: Default, Weight and Value — the same three as the
 * inventory and looting screens.
 *
 * Weight was unavailable until `companion-barter-weight.patch` added a per-item `weight` to the
 * native `COMPANION_BARTER_ITEM` export. It had to come from the engine: player-side weights could
 * have been joined from the player's inventory, but VENDOR items exist nowhere else on the Kotlin
 * side, so a chip fed from anything but the export would have sorted the vendor's whole stock as
 * weightless while looking like it worked.
 *
 * Kept as an explicit list rather than defaulting to `InvSort.entries` so the set barter offers is
 * a deliberate choice at this call site, not a side effect of adding a mode to the enum.
 */
private val BARTER_SORTS = listOf(InvSort.DEFAULT, InvSort.WEIGHT, InvSort.PRICE)

/**
 * Coarse gold step for the barter trade amount: left stick UP/DOWN moves the offer by this much,
 * where left/right moves it by 1. Deliberately the same 10 the `[−10]`/`[+10]` tap buttons on the
 * SPLIT stepper row use, so the two ways of making a big adjustment agree.
 *
 * Both collectors below apply it at HALF the native ~16 Hz poll rate (the same halving the fine
 * step uses), i.e. ~80g/sec while the stick is held.
 */
private const val BARTER_GOLD_COARSE_STEP = 10

/** Current controller focus in the barter overlay: which [side] (0 = player/left,
 *  1 = vendor/right) and which [index] into that side's visible list. */
private data class BarterFocus(val side: Int, val index: Int)

/**
 * Controller focus + navigation for the barter overlay (Phase 4), shared by the BOTTOM list
 * layout ([rows] = 1) and the SPLIT grid layout ([rows] = 4). Owns focus (side + index into that
 * side's VISIBLE list) and consumes NavEvents:
 *  - D-pad moves focus and WRAPS within the grid (grid: column-major ±1 within a column, ±rows
 *    across columns, both wrapping; list: Up/Down wrap ±1, Left/Right switch side to its first item).
 *  - L2 / R2 switch to the player / vendor side, focus → that side's FIRST item.
 *  - A toggles the focused item (select/deselect) via [onToggle] (stacks > 1 prompt first).
 *  - X = [onOffer] (Make offer); left stick left/right = [onSlider](-1 / +1) (gold offset), and
 *    left stick up/down the same thing in coarse [BARTER_GOLD_COARSE_STEP] steps. In SPLIT
 *    these two are no-ops here — the bottom controls window owns the slider + Offer button (its own
 *    collector), because the gold offset state lives there; passing no-ops avoids a top/bottom desync.
 * Focus starts on the VENDOR side's first item when barter opens; clears when the overlay leaves
 * composition. Only one barter grid layout is composed at a time (its collector owns barter nav);
 * the dialogue collector yields while a barter session is active. B (Cancel) is the existing patch.
 */
@Composable
private fun rememberBarterNavFocus(
    visiblePlayer: List<BarterItem>,
    visibleVendor: List<BarterItem>,
    rows: Int,
    onToggle: (BarterItem) -> Unit,
    onOffer: () -> Unit,
    onSlider: (Int) -> Unit,
    // Cycle the given side's category filter (L1 = -1 prev, R1 = +1 next).
    onCycleCategory: (side: Int, dir: Int) -> Unit,
    // Cycle the sort mode/direction (L3). Takes the focused side because SPLIT holds one
    // InvSortState PER COLUMN; BOTTOM shares one across both sides and ignores the argument.
    onCycleSort: (side: Int) -> Unit = { },
): BarterFocus {
    var side by remember { mutableStateOf(1) } // start on the vendor side
    var index by remember { mutableStateOf(0) }

    LaunchedEffect(visiblePlayer.size, visibleVendor.size, side) {
        val n = if (side == 0) visiblePlayer.size else visibleVendor.size
        index = index.coerceIn(0, (n - 1).coerceAtLeast(0))
    }

    val snapshot = rememberUpdatedState(Triple(visiblePlayer, visibleVendor, rows))
    val toggleState = rememberUpdatedState(onToggle)
    val offerState = rememberUpdatedState(onOffer)
    val sliderState = rememberUpdatedState(onSlider)
    val cycleState = rememberUpdatedState(onCycleCategory)
    val sortState = rememberUpdatedState(onCycleSort)
    LaunchedEffect(Unit) {
        var lastSeq = GameStateRepository.navEvent.value?.seq ?: -1L
        var sliderTick = 0 // apply the gold step every OTHER slider tick → ~half rate (~8g/sec held)
        var coarseTick = 0 // ditto for the vertical (±10) axis; its own counter so the two axes
                           // can't halve each other by sharing a parity.
        GameStateRepository.navEvent.collect { ev ->
            if (ev == null || ev.seq <= lastSeq) return@collect
            lastSeq = ev.seq
            if (ModalNav.open) return@collect // the quantity selector owns nav while up
            val (pVis, vVis, r) = snapshot.value
            fun list(s: Int) = if (s == 0) pVis else vVis
            val size = list(side).size
            // Column-major grid move with per-axis wrap (rows = r); partial last column clamps rows.
            fun gridMove(i: Int, n: Int): Int {
                if (n <= 0) return 0
                val cols = (n + r - 1) / r
                val col = i / r; val row = i % r
                fun colLast(c: Int) = minOf((c + 1) * r, n) - 1
                return when (ev) {
                    is NavEvent.Down -> if (row + 1 >= r || col * r + row + 1 >= n) col * r else i + 1
                    is NavEvent.Up -> if (row == 0) colLast(col) else i - 1
                    is NavEvent.Right -> (if (col + 1 >= cols) 0 else col + 1).let { minOf(it * r + row, colLast(it)) }
                    is NavEvent.Left -> (if (col - 1 < 0) cols - 1 else col - 1).let { minOf(it * r + row, colLast(it)) }
                    else -> i
                }
            }
            when (ev) {
                is NavEvent.Down -> if (size > 0) index = if (r <= 1) (index + 1) % size else gridMove(index, size)
                is NavEvent.Up -> if (size > 0) index = if (r <= 1) (index - 1 + size) % size else gridMove(index, size)
                is NavEvent.Right ->
                    if (r <= 1) { side = 1; index = 0 } else if (size > 0) index = gridMove(index, size)
                is NavEvent.Left ->
                    if (r <= 1) { side = 0; index = 0 } else if (size > 0) index = gridMove(index, size)
                is NavEvent.L2 -> { side = 0; index = 0 }
                is NavEvent.R2 -> { side = 1; index = 0 }
                // Shoulder buttons cycle the focused side's category filter; reset focus to the
                // first item of the new (filtered) list.
                is NavEvent.L1 -> { cycleState.value(side, -1); index = 0 }
                is NavEvent.R1 -> { cycleState.value(side, 1); index = 0 }
                is NavEvent.Confirm -> list(side).getOrNull(index)?.let { toggleState.value(it) }
                is NavEvent.Action1 -> offerState.value()
                is NavEvent.Info -> list(side).getOrNull(index)?.let {
                    ItemInfoPopupState.toggle(it.id, it.displayName(), it.enchant, onTop = r > 1)
                }
                // L3 re-orders the focused column — focus back to the top, same as a category
                // cycle, since the index no longer points at the item the player was looking at.
                is NavEvent.Sort -> { sortState.value(side); index = 0 }
                is NavEvent.SliderLeft -> if (sliderTick++ % 2 == 0) sliderState.value(-1)
                is NavEvent.SliderRight -> if (sliderTick++ % 2 == 0) sliderState.value(1)
                // Left stick UP/DOWN = the same gold adjustment in ±10 steps. onSlider takes the
                // signed step (its caller multiplies by the 1g fine step), so passing ±10 reuses the
                // exact same clamping and buy/sell direction inversion as the fine axis.
                is NavEvent.SliderUp ->
                    if (coarseTick++ % 2 == 0) sliderState.value(BARTER_GOLD_COARSE_STEP)
                is NavEvent.SliderDown ->
                    if (coarseTick++ % 2 == 0) sliderState.value(-BARTER_GOLD_COARSE_STEP)
                else -> Unit // Scroll* handled elsewhere
            }
            // While the info popup is open, D-pad focus moves follow to the newly focused item.
            if (ItemInfoPopupState.isOpen) {
                list(side).getOrNull(index)?.let {
                    ItemInfoPopupState.follow(it.id, it.displayName(), it.enchant, onTop = r > 1)
                }
            }
        }
    }
    // Clamp the REPORTED focus in composition (see the same note in rememberLootNavFocus) — a
    // category cycle or a list shrinking under the fixed index must not resolve focus to null for a
    // pass and close a focus-linked info popup.
    val n = (if (side == 0) visiblePlayer.size else visibleVendor.size)
    return BarterFocus(side, index.coerceIn(0, (n - 1).coerceAtLeast(0)))
}

/**
 * Bottom-screen barter overlay. Driven by COMPANION_BARTER_* (native TradeWindow),
 * shown whenever [GameStateRepository.barterSession] is non-null. NOT a Compose Dialog
 * (crashes on the Presentation display — see ItemInfoOverlay); an in-window Box at
 * zIndex 16f (above the dialogue overlay it sits on top of, below QuantitySelector 20f).
 *
 * Item selection is OPTIMISTIC and local: GM_Barter pauses the sim, so the engine's
 * COMPANION_BARTER_OFFER re-exports are frame-starved and can't refresh the display mid-
 * session (same as LootingOverlay). Each tap mutates the local lists (driving its own
 * recomposition) AND sends the real CMP:barter_* command; the engine reconciles the
 * authoritative balance. Lists are initialized once on open and NOT re-synced from later
 * `session` emissions; on close→reopen the overlay re-enters composition and re-inits.
 */
@Composable
private fun BarterOverlay(session: BarterSession, disposition: Int, location: ScreenLocation) {
    // Dismiss the item info popup when the barter session ends (Offer/Cancel/B/close) so it doesn't
    // linger over the game. Composed in BOTH bottom and SPLIT modes, so this covers the top-grid
    // popup too (both this and BarterTopOverlay leave composition on session-null).
    DisposableEffect(Unit) { onDispose { ItemInfoPopupState.close() } }
    val playerName = rememberPlayerName()
    // SPLIT: the item grids live on the TOP screen (BarterTopOverlay, hosted by EngineActivity);
    // the bottom screen shows ONLY the gold bar + Offer/Cancel. Item selection (borrow/return) is
    // sent to the engine from the top grid; the bottom controls read the engine's authoritative
    // merchantOffer + a local gold offset, so they need no shared item-selection state. The
    // disposition bar is omitted here (no natural place in the controls-only panel).
    if (location == ScreenLocation.SPLIT) {
        BarterControlsOnly(session)
        return
    }

    var vendorItems by remember { mutableStateOf(session.vendorItems) }
    var playerItems by remember { mutableStateOf(session.playerItems) }
    var extraGold by remember { mutableStateOf(session.extraGoldOffer) }
    var vendorCat by remember { mutableStateOf<String?>(null) }
    var playerCat by remember { mutableStateOf<String?>(null) }

    // Net estimate from the optimistic selection (positive = player receives gold). `value`
    // is the merchant's actual barter price per unit, so this tracks the engine balance.
    val playerSelValue = playerItems.filter { it.isSelected }.sumOf { it.value * it.selectedCount }
    val vendorSelValue = vendorItems.filter { it.isSelected }.sumOf { it.value * it.selectedCount }
    val net = playerSelValue - vendorSelValue + extraGold
    val anySelected = playerItems.any { it.isSelected } || vendorItems.any { it.isSelected }

    // The actual gold changing hands = the engine's fair price for the selected items
    // (merchantOffer, updated by COMPANION_BARTER_OFFER) + the player's manual offset.
    // Positive = the player receives gold, negative = the player pays.
    val offerBalance = session.merchantOffer + extraGold

    val playerCantAfford = net < 0 && -net > session.playerGold
    val vendorCantAfford = net > 0 && net > session.vendorGold
    // Enabled when there's anything to offer (items OR a gold adjustment) and it's
    // affordable. A gold-only offer (no items) is still submittable so the engine's
    // no_items rejection surfaces as feedback; a completely empty offer stays disabled.
    val offerEnabled = (anySelected || extraGold != 0) && !playerCantAfford && !vendorCantAfford
    val offerLabel = when {
        playerCantAfford -> "Insufficient gold"
        vendorCantAfford -> "Vendor lacks gold"
        else -> "Offer"
    }

    // Bug 2: match/transfer by the PER-INSTANCE stackId, NOT the record id. Two same-record stacks
    // (e.g. one worn Bonemold Boot + one unworn) share id but have distinct stackIds, so keying by
    // id marked BOTH selected and let the engine sell the wrong (equipped) copy. stackId now carries
    // a genuine per-instance handle end-to-end (see companion-barter-export.patch). ifEmpty{id} keeps
    // an old engine (no sid) working, degrading to the previous by-record behaviour.
    fun barterKey(it: BarterItem) = it.stackId.ifEmpty { it.id }
    fun mutate(side: BarterSide, sid: String, transform: (BarterItem) -> BarterItem) {
        if (side == BarterSide.VENDOR) vendorItems = vendorItems.map { if (barterKey(it) == sid) transform(it) else it }
        else playerItems = playerItems.map { if (barterKey(it) == sid) transform(it) else it }
    }

    fun toggle(item: BarterItem) {
        val sid = barterKey(item)
        if (item.isSelected) {
            mutate(item.side, sid) { it.copy(isSelected = false, selectedCount = 0) }
            CompanionActions.barterReturn(item.side, sid, item.selectedCount)
        } else {
            // Stack > 1 → ask "how many?" via the shared QuantitySelector (20f, above this).
            QuantityRequestState.requestOrRun(item.displayName(), item.count, "Select") { n ->
                mutate(item.side, sid) { it.copy(isSelected = true, selectedCount = n) }
                CompanionActions.barterBorrow(item.side, sid, n)
            }
        }
    }
    // Set the gold changing hands to an absolute signed balance (positive = player receives),
    // clamped to what each side can pay; derive the manual offset from it. Matches the SPLIT
    // controls (BarterGoldSlider).
    fun setBalance(target: Int) {
        val clamped = target.coerceIn(-session.playerGold, session.vendorGold)
        extraGold = clamped - session.merchantOffer
        CompanionActions.barterSetExtraGold(extraGold)
    }

    // Controller focus (BOTTOM = two side-by-side lists → rows = 1). All state is co-located here,
    // so this collector also owns X (Offer) + the left-stick gold slider.
    // Sort controls (Default / Weight / Value) — the same InvSortState + chips as the inventory tab. Feeding
    // barterVisible here keeps ONE source of order for both the display and the focus index.
    val sort = rememberInvSortState()
    val visiblePlayer = remember(playerItems, playerCat, sort.mode, sort.descending) {
        barterVisible(playerItems, playerCat, true, sort.mode, sort.descending)
    }
    val visibleVendor = remember(vendorItems, vendorCat, sort.mode, sort.descending) {
        barterVisible(vendorItems, vendorCat, false, sort.mode, sort.descending)
    }
    // Flat 1g per left-stick tick. At the ~60ms native slider-poll cadence (~16 ticks/sec) that's
    // ~16g/sec when held — precise for fine adjustment, still reaches large values by holding. Tune
    // here (or add an accelerating hold) if needed.
    val goldStep = 1
    // Clamp the left-stick gold adjustment to the SAME balance range the touch slider
    // (BarterGoldSlider) can reach — selling (merchantOffer >= 0): 0 .. vendorGold; buying
    // (merchantOffer < 0): -min(item value, playerGold) .. 0 — so the stick can't push the
    // offer past what the slider allows.
    val navReceiving = session.merchantOffer >= 0
    val navSliderMax = (if (navReceiving) session.vendorGold
        else minOf(abs(session.merchantOffer), session.playerGold)).coerceAtLeast(0)
    val navSliderLo = if (navReceiving) 0 else -navSliderMax
    val navSliderHi = if (navReceiving) navSliderMax else 0
    // Offer + left-stick gold slider — shared by the Classic grid nav and the Shelf nav (below).
    // Physical stick right always moves the slider visually rightward (toward max), matching the touch
    // slider. Selling (balance positive) rightward = +gold; buying (negative, magnitude = cost)
    // rightward = MORE negative → invert dir. Clamped to the touch-slider range; no-op at a bound.
    val doOffer: () -> Unit = { if (offerEnabled) CompanionActions.barterOffer() }
    val barterSlider: (Int) -> Unit = { dir ->
        val delta = (if (navReceiving) dir else -dir) * goldStep
        val next = (offerBalance + delta).coerceIn(navSliderLo, navSliderHi)
        if (next != offerBalance) setBalance(next)
    }
    // Classic mode only — the shelf layout runs its own nav (ShelfDualPanel).
    val shelfMode = UiPreferences.inventoryLayoutFlow().collectAsState().value == InventoryLayout.SHELF
    val focus = if (shelfMode) null else rememberBarterNavFocus(
        visiblePlayer = visiblePlayer,
        visibleVendor = visibleVendor,
        rows = 1,
        onToggle = ::toggle,
        onOffer = doOffer,
        onSlider = barterSlider,
        onCycleCategory = { side, dir ->
            if (side == 0) playerCat = cycleBarterCat(playerItems, playerCat, dir)
            else vendorCat = cycleBarterCat(vendorItems, vendorCat, dir)
        },
        // BOTTOM has ONE sort shared by both lists (chips in the shared title bar) — focused side
        // irrelevant. BARTER_SORTS so the cycle steps through exactly the chips shown.
        onCycleSort = { sort.cycle(BARTER_SORTS) },
    )

    // Bug 1: keep a focus-linked info popup on the focused item when selecting an item re-sorts the
    // list (selected-first float) under the fixed focus index. Classic nav only (shelf runs its own).
    if (!shelfMode) {
        val focusedItem = focus?.let { (if (it.side == 0) visiblePlayer else visibleVendor).getOrNull(it.index) }
        FollowFocusedInfoPopup(focusedItem?.let { InfoTarget(it.id, it.displayName(), it.enchant) }, onTop = false)
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(16f)
            .background(Color(0xCC0F0C08))
            .pointerInput(Unit) { detectTapGestures {} }
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                // bottom = 12.dp (not BOTTOM_BAR_SPACE): barter is a modal interaction left
                // via Cancel / B, so the panel fills over the bottom tab bar rather than
                // reserving space for it. 12dp matches the top/side insets.
                .padding(top = 12.dp, bottom = 12.dp, start = 12.dp, end = 12.dp)
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures {} }
        ) {
            // ---- Title bar: "Vendor — Barter" + (Classic only) sort chips + disposition bar ----
            // Chips ride IN the title bar rather than on their own row — same reasoning as the
            // looting overlay: this list is being made roomier, so a dedicated control strip would
            // give back the height the row tuning just won. Padding 8 → 4 since the chips (which
            // carry their own) now set the bar height.
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 4.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    "Barter: ${session.vendorName.ifBlank { "Merchant" }}",
                    color = BronzeLight, fontSize = 14.sp,
                    fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                    maxLines = 1, overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f)
                )
                // Classic only — Shelf builds its own lists from playerItems/vendorItems directly.
                // Default/Weight/Value (BARTER_SORTS).
                if (!shelfMode) {
                    Spacer(Modifier.width(8.dp))
                    SortChipRow(sort, BARTER_SORTS)
                }
                if (disposition >= 0) {
                    Spacer(Modifier.width(12.dp))
                    Box(Modifier.width(120.dp)) { DispositionBar(disposition) }
                }
            }
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))

            // ---- Item panels: Shelf (grouped shelves) or Classic (two side-by-side lists) ----
            // Player's carried weight — snapshot once (GM_Barter pauses the sim, like looting's enc).
            val playerEnc = remember { GameStateRepository.state.value.encumbrance }
            if (shelfMode) {
                ShelfDualPanel(
                    playerHeaderLeft = playerName,
                    playerHeaderRight = goldWeightHeaderRight(session.playerGold, playerEnc),
                    playerShelfItems = playerItems.filter { !it.worn }.map { itm -> itm.toShelfItem { toggle(itm) } },
                    playerEquipped = playerItems.filter { it.worn }.map { itm -> itm.toShelfItem { toggle(itm) } },
                    otherHeaderLeft = session.vendorName.ifBlank { "Merchant" },
                    otherHeaderRight = goldHeaderRight(session.vendorGold),
                    otherItems = vendorItems.map { itm -> itm.toShelfItem { toggle(itm) } },
                    otherEmptyText = "Empty",
                    infoOnTop = false,
                    onAction1 = doOffer,
                    onSlider = barterSlider,
                    dividerWidth = SHELF_CENTER_DIVIDER_WIDTH_BOTTOM,
                    modifier = Modifier.weight(1f).padding(8.dp)
                )
            } else Row(Modifier.weight(1f).fillMaxWidth()) {
                BarterColumn(
                    header = playerPackHeader(playerEnc),
                    items = playerItems,
                    isPlayerSide = true,
                    selectedCategory = playerCat,
                    onSelectCategory = { playerCat = it },
                    onToggle = ::toggle,
                    focusedIndex = if (focus!!.side == 0) focus.index else -1,
                    sortMode = sort.mode,
                    sortDescending = sort.descending,
                    modifier = Modifier.weight(1f).fillMaxHeight().padding(8.dp)
                )
                // Dashed vertical divider.
                Canvas(Modifier.fillMaxHeight().width(1.dp)) {
                    drawLine(
                        color = BronzeDark,
                        start = Offset(0f, 0f),
                        end = Offset(0f, size.height),
                        strokeWidth = size.width.coerceAtLeast(1f),
                        pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(6f, 6f))
                    )
                }
                BarterColumn(
                    header = AnnotatedString("${session.vendorName.ifBlank { "Merchant" }} (${session.vendorGold}g)"),
                    items = vendorItems,
                    isPlayerSide = false,
                    selectedCategory = vendorCat,
                    onSelectCategory = { vendorCat = it },
                    onToggle = ::toggle,
                    focusedIndex = if (focus!!.side == 1) focus.index else -1,
                    sortMode = sort.mode,
                    sortDescending = sort.descending,
                    modifier = Modifier.weight(1f).fillMaxHeight().padding(8.dp)
                )
            }

            // ---- Offer section: the gold-amount slider (same as SPLIT controls) ----
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            Box(Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 8.dp)) {
                BarterGoldSlider(
                    merchantOffer = session.merchantOffer,
                    playerGold = session.playerGold,
                    vendorGold = session.vendorGold,
                    offerBalance = offerBalance,
                    onSetBalance = ::setBalance
                )
            }

            // ---- Buttons ----
            Row(
                modifier = Modifier.fillMaxWidth().padding(8.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                BarterButton(
                    label = offerLabel, color = ActionConfirm, enabled = offerEnabled,
                    modifier = Modifier.weight(1f)
                ) { CompanionActions.barterOffer() }
                BarterButton(
                    label = "Cancel", hint = "B", color = ActionCancel, enabled = true,
                    modifier = Modifier.weight(1f)
                ) { CompanionActions.barterCancel() }
            }
        }

        // Local dropdown-dismiss scrim for BarterRow long-press (Info) menus — same as
        // LootingOverlay (this overlay renders above the global scrim at 10f).
        if (DropdownState.anyOpen) {
            Box(
                Modifier
                    .fillMaxSize()
                    .pointerInput(Unit) { detectTapGestures { DropdownState.closeAll() } }
            )
        }
    }
}

/* ---- Barter SPLIT mode (top-screen grids + bottom-screen controls) ---- */

// Gap between the two separate column boxes on the top screen. Single tweakable constant.
private val BARTER_SPLIT_COLUMN_GAP = 8.dp

/**
 * SPLIT-mode bottom-screen barter controls: gold totals + the [−100..+100] gold offset bar +
 * Offer / Cancel, centred vertically. Item selection happens on the top grid ([BarterTopOverlay])
 * and is tracked engine-side (barter_borrow/return), so these controls read only the engine's
 * authoritative [BarterSession.merchantOffer] plus a LOCAL gold offset — no shared item state.
 * The disposition bar is intentionally omitted (decision: no natural place here).
 */
@Composable
private fun BarterControlsOnly(session: BarterSession) {
    // Local gold offset (the +/- row), initialised once from the session; NOT re-synced from
    // later emissions (matches the full overlay). Persisted engine-side via barter_gold.
    var extraGold by remember { mutableStateOf(session.extraGoldOffer) }

    // Balance actually changing hands = engine fair price for staged items + the manual offset.
    // Positive = the player receives gold, negative = the player pays. Affordability is derived
    // from this authoritative balance (no optimistic item net needed on the bottom screen).
    val offerBalance = session.merchantOffer + extraGold
    val playerCantAfford = offerBalance < 0 && -offerBalance > session.playerGold
    val vendorCantAfford = offerBalance > 0 && offerBalance > session.vendorGold
    val offerEnabled = !playerCantAfford && !vendorCantAfford
    val offerLabel = when {
        playerCantAfford -> "Insufficient gold"
        vendorCantAfford -> "Vendor lacks gold"
        else -> "Offer"
    }

    // Set the gold changing hands to an absolute signed balance (positive = player receives),
    // clamped to what each side can pay; derive the manual offset from it.
    fun setBalance(target: Int) {
        val clamped = target.coerceIn(-session.playerGold, session.vendorGold)
        extraGold = clamped - session.merchantOffer
        CompanionActions.barterSetExtraGold(extraGold)
    }

    // Controller: in SPLIT mode the grid nav + A + L2/R2 live on the TOP grids (BarterTopOverlay);
    // this bottom window owns the gold slider (left stick) + X (Offer) because the gold-offset state
    // lives here. A small dedicated collector — no focus/grid on the bottom, disjoint event set from
    // the top collector (Action1 + the four Slider* events only), so the two never double-handle
    // (the top overlay passes a no-op onSlider for exactly this reason).
    // Flat 1g per left-stick tick. At the ~60ms native slider-poll cadence (~16 ticks/sec) that's
    // ~16g/sec when held — precise for fine adjustment, still reaches large values by holding. Tune
    // here (or add an accelerating hold) if needed.
    val goldStep = 1
    val ctlSnapshot = rememberUpdatedState(Triple(offerBalance, offerEnabled, goldStep))
    // Clamp the left-stick gold adjustment to the SAME balance range the touch slider
    // (BarterGoldSlider) can reach — selling (merchantOffer >= 0): 0 .. vendorGold; buying
    // (merchantOffer < 0): -min(item value, playerGold) .. 0 — so the stick can't push the
    // offer past what the slider allows.
    val navReceiving = session.merchantOffer >= 0
    val navSliderMax = (if (navReceiving) session.vendorGold
        else minOf(abs(session.merchantOffer), session.playerGold)).coerceAtLeast(0)
    val navBounds = rememberUpdatedState(
        (if (navReceiving) 0 else -navSliderMax) to (if (navReceiving) navSliderMax else 0)
    )
    // Fresh (live-frame) receiving flag for the captured collector — buying inverts the stick dir.
    val navReceivingState = rememberUpdatedState(navReceiving)
    // setBalance() reads session.merchantOffer to derive the manual offset. LaunchedEffect(Unit)
    // captures its closure once, so calling setBalance directly would use the STALE first-frame
    // merchantOffer (0, before items are staged) and re-fold the item price into extraGold — the
    // "cost doubles regardless of direction" bug. rememberUpdatedState keeps a reference to the
    // current-frame setBalance so the offset is derived from the live merchantOffer.
    val setBalanceState = rememberUpdatedState<(Int) -> Unit> { target -> setBalance(target) }
    LaunchedEffect(Unit) {
        var lastSeq = GameStateRepository.navEvent.value?.seq ?: -1L
        var sliderTick = 0 // apply the gold step every OTHER slider tick → ~half rate (~8g/sec held)
        var coarseTick = 0 // ditto for the vertical (±10) axis; its own counter so the two axes
                           // can't halve each other by sharing a parity.
        GameStateRepository.navEvent.collect { ev ->
            if (ev == null || ev.seq <= lastSeq) return@collect
            lastSeq = ev.seq
            if (ModalNav.open) return@collect // the quantity selector owns nav while up
            val (balance, enabled, step) = ctlSnapshot.value
            val (sliderLo, sliderHi) = navBounds.value
            val receiving = navReceivingState.value
            // dir = +1 moves the slider visually RIGHTWARD (toward max cost/gold), -1 toward 0.
            // Selling: right = +gold. Buying (balance negative, magnitude = cost): invert, so right =
            // more negative (pay more). Clamped to the touch slider's range; no-op at a bound.
            fun nudge(dir: Int, size: Int) {
                val next = (balance + (if (receiving) dir else -dir) * size)
                    .coerceIn(sliderLo, sliderHi)
                if (next != balance) setBalanceState.value(next)
            }
            when (ev) {
                is NavEvent.Action1 -> if (enabled) CompanionActions.barterOffer()
                is NavEvent.SliderLeft -> if (sliderTick++ % 2 == 0) nudge(-1, step)
                is NavEvent.SliderRight -> if (sliderTick++ % 2 == 0) nudge(1, step)
                // Left stick UP/DOWN = the same adjustment in coarse ±10 steps, matching the
                // [−10]/[+10] tap buttons beside the slider. Up = rightward = "more", so it agrees
                // with the horizontal axis rather than inventing a second spatial convention.
                is NavEvent.SliderUp ->
                    if (coarseTick++ % 2 == 0) nudge(1, BARTER_GOLD_COARSE_STEP)
                is NavEvent.SliderDown ->
                    if (coarseTick++ % 2 == 0) nudge(-1, BARTER_GOLD_COARSE_STEP)
                else -> Unit
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(16f)
            .background(Color(0xCC0F0C08))
            .pointerInput(Unit) { detectTapGestures {} },
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                // Widened 0.6 → 0.84 (+40%) when the gold ± steppers landed (Aug 10 2026): four
                // buttons sharing the row left the slider itself too short to aim at. The panel's
                // OWN width is the dial here — the steppers are fixed-size and the slider takes
                // weight(1f), so every extra dp of panel goes straight into slider travel.
                .fillMaxWidth(BARTER_CONTROLS_PANEL_WIDTH)
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures {} }
                .padding(16.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            Text(
                "Barter: ${session.vendorName.ifBlank { "Merchant" }}",
                color = BronzeLight, fontSize = 14.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                maxLines = 1, overflow = TextOverflow.Ellipsis
            )
            // Gold totals: your gold | their gold.
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Text("You: ${session.playerGold}g", color = Bone, fontSize = 12.sp, fontFamily = MwData)
                Text("${session.vendorName.ifBlank { "Merchant" }}: ${session.vendorGold}g",
                    color = Bone, fontSize = 12.sp, fontFamily = MwData,
                    maxLines = 1, overflow = TextOverflow.Ellipsis)
            }
            Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            BarterGoldSlider(
                merchantOffer = session.merchantOffer,
                playerGold = session.playerGold,
                vendorGold = session.vendorGold,
                offerBalance = offerBalance,
                // SPLIT only: this window is sparse, so the ± taps fit alongside the slider. The
                // full BOTTOM overlay (BarterOverlay) shares this composable but keeps the bare
                // slider — its panel already carries two item lists; flip this flag there if the
                // steppers are wanted in that layout too.
                showSteppers = true,
                onSetBalance = ::setBalance
            )
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                BarterButton(
                    label = offerLabel, color = ActionConfirm, enabled = offerEnabled,
                    modifier = Modifier.weight(1f)
                ) { CompanionActions.barterOffer() }
                BarterButton(
                    label = "Cancel", hint = "B", color = ActionCancel, enabled = true,
                    modifier = Modifier.weight(1f)
                ) { CompanionActions.barterCancel() }
            }
        }
    }
}

/**
 * Trade-amount slider for the SPLIT barter controls. The slider sets the gold changing hands; its
 * range depends on the current direction of the deal (the sign of the engine's fair price for the
 * staged items, [merchantOffer]):
 *  - player RECEIVES (merchantOffer >= 0): 0 .. vendorGold (how much the vendor pays).
 *  - player PAYS (merchantOffer < 0): 0 .. min(item value, playerGold) — can't pay more than the
 *    goods are worth (nor more than you hold).
 * The signed gold amount is shown as a coloured label above the slider (green = you receive, red =
 * you pay).
 *
 * NOTE: the "0" end is neutral/no-gold, not the mathematically "fair" balance — see the brief; the
 * exact semantics are easy to retune here.
 *
 * [showSteppers] flanks the slider with `[−10][−] … [+][+10]` tap buttons (SPLIT controls only —
 * see the note on the stepper row below).
 */
@Composable
private fun BarterGoldSlider(
    merchantOffer: Int,
    playerGold: Int,
    vendorGold: Int,
    offerBalance: Int,
    showSteppers: Boolean = false,
    onSetBalance: (Int) -> Unit
) {
    val receiving = merchantOffer >= 0
    val sliderMax = (if (receiving) vendorGold else minOf(abs(merchantOffer), playerGold))
        .coerceAtLeast(0)
    // Slider magnitude in the active direction (gold received when selling, paid when buying).
    val magnitude = (if (receiving) offerBalance else -offerBalance).coerceIn(0, sliderMax)

    val labelColor = when {
        offerBalance > 0 -> BarterGreen
        offerBalance < 0 -> BarterRed
        else -> Bone
    }

    // Single choke point for every way the amount moves (slider drag, stepper taps): set the
    // MAGNITUDE, clamped to the slider's own 0..sliderMax range, then re-apply the deal's sign.
    // So the steppers can never reach a value the slider couldn't.
    fun setMagnitude(mag: Int) {
        val m = mag.coerceIn(0, sliderMax)
        onSetBalance(if (receiving) m else -m)
    }

    Column(
        modifier = Modifier.fillMaxWidth(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text(
            if (offerBalance > 0) "+${offerBalance}g" else "${offerBalance}g",
            color = labelColor, fontSize = 20.sp, fontFamily = MwData, fontWeight = FontWeight.Bold
        )
        val slider = @Composable { modifier: Modifier ->
            Slider(
                value = magnitude.toFloat(),
                onValueChange = { v -> setMagnitude(v.roundToInt()) },
                valueRange = 0f..sliderMax.coerceAtLeast(1).toFloat(),
                enabled = sliderMax > 0,
                colors = SliderDefaults.colors(
                    thumbColor = BronzeLight,
                    activeTrackColor = Bronze,
                    inactiveTrackColor = BronzeDark
                ),
                modifier = modifier
            )
        }
        if (!showSteppers) {
            slider(Modifier.fillMaxWidth())
        } else {
            // Stepper row: [−10][−]  slider  [+][+10], mirroring the QuantitySelector's stepper
            // shape (the drop menu) — the value itself is already the big label above, so the
            // slider takes the middle instead of a number.
            //
            // DIRECTION: +/− move the MAGNITUDE (how much gold changes hands), i.e. the slider
            // right/left — NOT the signed label. Selling, "+" means you receive more; BUYING, "+"
            // means you pay more, so the label reads -100g → -110g. That matches the slider's own
            // spatial meaning and the left-stick mapping in BarterControlsOnly ("physical right
            // always moves the slider rightward, toward max cost/gold"), which would otherwise
            // disagree with the buttons sitting right next to it.
            //
            // ±10 only when the range is big enough to need it (same rule as QuantitySelector's
            // showTens). Shrink STEP_BTN if the row ever crowds the slider on a narrower panel.
            val showTens = sliderMax > 10
            val canDown = sliderMax > 0 && magnitude > 0
            val canUp = sliderMax > 0 && magnitude < sliderMax
            Row(
                modifier = Modifier.fillMaxWidth(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(BARTER_STEP_GAP)
            ) {
                if (showTens) {
                    QtyButton("−10", enabled = canDown, size = BARTER_STEP_BTN) { setMagnitude(magnitude - 10) }
                }
                QtyButton("−", enabled = canDown, size = BARTER_STEP_BTN) { setMagnitude(magnitude - 1) }
                slider(Modifier.weight(1f))
                QtyButton("+", enabled = canUp, size = BARTER_STEP_BTN) { setMagnitude(magnitude + 1) }
                if (showTens) {
                    QtyButton("+10", enabled = canUp, size = BARTER_STEP_BTN) { setMagnitude(magnitude + 10) }
                }
            }
        }
    }
}

// SPLIT barter gold-stepper sizing. Smaller than QuantitySelector's 48dp squares because four of
// them share a row WITH the slider.
private val BARTER_STEP_BTN = 34.dp
private val BARTER_STEP_GAP = 4.dp

/** Width of the SPLIT barter controls panel (`BarterControlsOnly`) as a fraction of the bottom
 *  screen. Was 0.6 before the gold ± steppers; +40% → 0.84, which is where the slider's remaining
 *  travel stops feeling cramped. Grow this (not the button size) if the row ever tightens again —
 *  the buttons are fixed-width and the slider is `weight(1f)`, so the panel width IS the slider
 *  width. Applies to SPLIT only; the full bottom `BarterOverlay` has its own layout. */
private const val BARTER_CONTROLS_PANEL_WIDTH = 0.84f

/**
 * TOP-screen barter grids (Display 0). Hosted by [org.openmw.EngineActivity] in an interactive
 * WindowManager panel window while a barter session is active AND Bartering is routed to SPLIT.
 * Player inventory LEFT, vendor inventory RIGHT — both 3-row horizontally-scrolling icon grids
 * with per-side category tabs. Tapping a cell selects/deselects it (adds to / removes from the
 * offer, sending barter_borrow / barter_return); a stack > 1 prompts for a quantity first.
 * Selected cells get a bronze border highlight. Reads its state from [GameStateRepository].
 */
@Composable
fun BarterTopOverlay() {
    val sessionState by GameStateRepository.barterSession.collectAsState()
    val session = sessionState ?: return
    val playerName = rememberPlayerName()

    // Optimistic COLUMN contents — remember WITHOUT a key so they init once on enter and are NOT
    // re-synced from later (frame-starved) emissions. The window is removed on session-null.
    // Items MOVE between columns on tap (like looting): a bought vendor item leaves the vendor
    // column and appears (highlighted) in the player column, and a sold player item vice versa.
    // An item's `side` is its HOME; `isSelected` = staged (currently shown in the OPPOSITE column).
    var playerCol by remember { mutableStateOf(session.playerItems) }
    var vendorCol by remember { mutableStateOf(session.vendorItems) }
    var playerCat by remember { mutableStateOf<String?>(null) }
    var vendorCat by remember { mutableStateOf<String?>(null) }

    // Local quantity picker (kept on the TOP screen). Barter always opens on the whole stack —
    // there is no pickpocket case here (selection is reversible and the Offer is a separate step).
    var qtyReq by remember { mutableStateOf<QuantityRequest?>(null) }
    val requestQty: (String, Int, String, (Int) -> Unit) -> Unit = { name, count, label, action ->
        if (count > 1) qtyReq = QuantityRequest(name, count, label, count) { n -> qtyReq = null; action(n) }
        else action(1)
    }

    // Brief auto-dismissing inline banner (e.g. the merchant won't buy a restricted item). The
    // nonce re-arms the auto-dismiss timer even when the same message is tapped again.
    var restrictionBanner by remember { mutableStateOf<String?>(null) }
    var bannerNonce by remember { mutableStateOf(0) }
    LaunchedEffect(bannerNonce) {
        if (restrictionBanner != null) {
            delay(2200)
            restrictionBanner = null
        }
    }

    // Bug 2: identify a stack by its PER-INSTANCE stackId (not the record id), so two same-record
    // stacks (one worn, one not) are distinct entries and the tapped one is the one that moves +
    // gets sold. ifEmpty{id} keeps an old engine (no sid) working. See companion-barter-export.patch.
    fun barterKey(it: BarterItem) = it.stackId.ifEmpty { it.id }
    // Move `n` of `item` from `source` column to `dest` column, setting the destination copy's
    // staged flag. Reduces/removes the matched entry in source (matched by stackId+side+isSelected)
    // and merges into (or appends) a same-(stackId, side, selected) entry in dest — so moving 1 of a
    // stack of 5 leaves a ×4 remainder behind. Mirrors looting's moveOptimistic for BarterItem.
    // Returns (newSource, newDest).
    fun moveBarter(
        source: List<BarterItem>, dest: List<BarterItem>, item: BarterItem, n: Int, selected: Boolean
    ): Pair<List<BarterItem>, List<BarterItem>> {
        val moved = n.coerceIn(1, item.count)
        val newSource = source.mapNotNull { e ->
            if (barterKey(e) == barterKey(item) && e.side == item.side && e.isSelected == item.isSelected) {
                if (e.count > moved) e.copy(count = e.count - moved) else null
            } else e
        }
        val idx = dest.indexOfFirst { barterKey(it) == barterKey(item) && it.side == item.side && it.isSelected == selected }
        val newDest = if (idx >= 0) {
            dest.mapIndexed { i, e ->
                if (i == idx) e.copy(count = e.count + moved, selectedCount = if (selected) e.count + moved else 0) else e
            }
        } else {
            dest + item.copy(count = moved, isSelected = selected, selectedCount = if (selected) moved else 0)
        }
        return newSource to newDest
    }

    // Buy/sell: move `n` from the item's HOME column to the opposite column, mark it staged, and
    // tell the engine (barter_borrow). PLAYER items go player→vendor (sell); VENDOR items go
    // vendor→player (buy).
    fun borrow(item: BarterItem, n: Int) {
        if (item.side == BarterSide.PLAYER) {
            val (s, d) = moveBarter(playerCol, vendorCol, item, n, selected = true)
            playerCol = s; vendorCol = d
        } else {
            val (s, d) = moveBarter(vendorCol, playerCol, item, n, selected = true)
            vendorCol = s; playerCol = d
        }
        CompanionActions.barterBorrow(item.side, barterKey(item), n.coerceIn(1, item.count))
    }

    // Un-stage: move a staged item back to its HOME column (whole amount) and return it to the
    // engine (barter_return). A staged PLAYER item currently sits in the vendor column; a staged
    // VENDOR item in the player column.
    fun returnHome(item: BarterItem) {
        val amount = item.count
        if (item.side == BarterSide.PLAYER) {
            val (s, d) = moveBarter(vendorCol, playerCol, item, amount, selected = false)
            vendorCol = s; playerCol = d
        } else {
            val (s, d) = moveBarter(playerCol, vendorCol, item, amount, selected = false)
            playerCol = s; vendorCol = d
        }
        CompanionActions.barterReturn(item.side, barterKey(item), amount)
    }

    fun toggle(item: BarterItem) {
        if (item.isSelected) { returnHome(item); return }
        // Pre-tap restriction gate: the merchant won't buy this player item — flash a banner and
        // skip (no move to undo). Vendor items are always sellable=true.
        if (item.side == BarterSide.PLAYER && !item.sellable) {
            restrictionBanner = "This vendor doesn't buy that"
            bannerNonce++
            return
        }
        requestQty(item.displayName(), item.count, "Select") { n -> borrow(item, n) }
    }

    // Controller focus (SPLIT = two 3-row icon grids → rows = 3). X (Offer) + the gold slider are
    // owned by the bottom controls window (BarterControlsOnly, its own collector) because the gold-
    // offset state lives there — passing no-ops here avoids a top/bottom desync.
    // Per-column sort state (Default / Weight / Value — see BARTER_SORTS).
    // Owned here so the SAME state drives both the grid display and this focus list.
    val playerSort = rememberInvSortState()
    val vendorSort = rememberInvSortState()
    val visiblePlayer = remember(playerCol, playerCat, playerSort.mode, playerSort.descending) {
        barterVisible(playerCol, playerCat, true, playerSort.mode, playerSort.descending)
    }
    val visibleVendor = remember(vendorCol, vendorCat, vendorSort.mode, vendorSort.descending) {
        barterVisible(vendorCol, vendorCat, false, vendorSort.mode, vendorSort.descending)
    }
    // Classic mode only — the shelf layout runs its own nav (ShelfDualPanel). Offer/slider stay
    // owned by the bottom controls window either way.
    val shelfMode = UiPreferences.inventoryLayoutFlow().collectAsState().value == InventoryLayout.SHELF
    val focus = if (shelfMode) null else rememberBarterNavFocus(
        visiblePlayer = visiblePlayer,
        visibleVendor = visibleVendor,
        rows = 3,
        onToggle = ::toggle,
        onOffer = {},
        onSlider = {},
        onCycleCategory = { side, dir ->
            if (side == 0) playerCat = cycleBarterCat(playerCol, playerCat, dir)
            else vendorCat = cycleBarterCat(vendorCol, vendorCat, dir)
        },
        // SPLIT has one sort PER COLUMN → L3 targets the focused one, matching L1/R1's rule.
        onCycleSort = { side -> (if (side == 0) playerSort else vendorSort).cycle(BARTER_SORTS) },
    )

    // Bug 1: keep a focus-linked info popup (rendered on THIS top screen) on the focused item when
    // selecting re-sorts the list under the fixed focus index. Classic nav only (shelf runs its own).
    if (!shelfMode) {
        val focusedItem = focus?.let { (if (it.side == 0) visiblePlayer else visibleVendor).getOrNull(it.index) }
        FollowFocusedInfoPopup(focusedItem?.let { InfoTarget(it.id, it.displayName(), it.enchant) }, onTop = true)
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .pointerInput(Unit) { detectTapGestures {} }
            // Bottom-anchored, 12dp up — matching the looting overlay.
            .padding(bottom = 12.dp),
        contentAlignment = Alignment.BottomCenter
    ) {
        // Two separate boxed columns (player | vendor) with an 8dp gap — no outer panel, no
        // divider. Same height as the looting overlay (0.675). Items MOVE across on tap.
        // Player's carried weight — snapshot once (GM_Barter pauses the sim, like looting's enc).
        val playerEnc = remember { GameStateRepository.state.value.encumbrance }
        if (shelfMode) {
            ShelfDualPanel(
                playerHeaderLeft = playerName,
                playerHeaderRight = goldWeightHeaderRight(session.playerGold, playerEnc),
                playerShelfItems = playerCol.filter { !it.worn }.map { itm -> itm.toShelfItem { toggle(itm) } },
                playerEquipped = playerCol.filter { it.worn }.map { itm -> itm.toShelfItem { toggle(itm) } },
                otherHeaderLeft = session.vendorName.ifBlank { "Merchant" },
                otherHeaderRight = goldHeaderRight(session.vendorGold),
                otherItems = vendorCol.map { itm -> itm.toShelfItem { toggle(itm) } },
                otherEmptyText = "Empty",
                infoOnTop = true,
                // Offer (X) + gold slider stay owned by the bottom controls window — no-op here.
                modifier = Modifier.fillMaxWidth(0.96f).fillMaxHeight(0.675f)
            )
        } else Row(
            modifier = Modifier
                .fillMaxWidth(0.96f)
                // Taller than Shelf's 0.675 so the 3-row grid's cells fit a two-line name.
                .fillMaxHeight(SPLIT_PANEL_HEIGHT_FRACTION)
        ) {
            // LEFT: player column (own inventory + bought vendor items, highlighted).
            BarterGridColumn(
                // Same "You <weight>kg" header the looting columns use — see playerPackHeader for
                // why it is "You" rather than the character name, and why gold is not repeated here.
                header = playerPackHeader(playerEnc),
                items = playerCol,
                isPlayerSide = true,
                selectedCategory = playerCat,
                onSelectCategory = { playerCat = it },
                onToggle = ::toggle,
                focusedIndex = if (focus!!.side == 0) focus.index else -1,
                sort = playerSort,
                modifier = Modifier.weight(1f).fillMaxHeight().splitColumnBox()
            )
            Spacer(Modifier.width(BARTER_SPLIT_COLUMN_GAP))
            // RIGHT: vendor column (own stock + sold player items, highlighted).
            BarterGridColumn(
                header = AnnotatedString(session.vendorName.ifBlank { "Merchant" }),
                items = vendorCol,
                isPlayerSide = false,
                selectedCategory = vendorCat,
                onSelectCategory = { vendorCat = it },
                onToggle = ::toggle,
                focusedIndex = if (focus!!.side == 1) focus.index else -1,
                sort = vendorSort,
                modifier = Modifier.weight(1f).fillMaxHeight().splitColumnBox()
            )
        }

        if (DropdownState.anyOpen) {
            Box(
                Modifier
                    .fillMaxSize()
                    .pointerInput(Unit) { detectTapGestures { DropdownState.closeAll() } }
            )
        }
        qtyReq?.let { req ->
            QuantitySelector(
                name = req.name,
                max = req.max,
                confirmLabel = req.confirmLabel,
                initial = req.initial,
                showControllerHint = req.showControllerHint,
                onConfirm = req.onConfirm,
                onCancel = { qtyReq = null }
            )
        }

        // Brief auto-dismissing restriction banner, top-centre (non-blocking, not a popup).
        restrictionBanner?.let { msg ->
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(top = 24.dp),
                contentAlignment = Alignment.TopCenter
            ) {
                Text(
                    msg,
                    color = BoneBright, fontSize = 13.sp, fontFamily = MwBody,
                    textAlign = TextAlign.Center,
                    modifier = Modifier
                        .clip(RoundedCornerShape(4.dp))
                        .background(Color(0xF01A1206))
                        .border(1.dp, BarterRed, RoundedCornerShape(4.dp))
                        .padding(horizontal = 16.dp, vertical = 8.dp)
                )
            }
        }

        // Item info popup on the TOP screen (SPLIT barter): anchored to the grid cell in THIS
        // window's coords. Only when the trigger came from here (onTopScreen).
        if (ItemInfoPopupState.isOpen && ItemInfoPopupState.onTopScreen) {
            ItemInfoPopupHost()
        }
    }
}

/** One side of the SPLIT barter grids — header, per-side category tabs, 3-row icon grid. */
@Composable
private fun BarterGridColumn(
    header: AnnotatedString,
    items: List<BarterItem>,
    isPlayerSide: Boolean,
    selectedCategory: String?,
    onSelectCategory: (String?) -> Unit,
    onToggle: (BarterItem) -> Unit,
    focusedIndex: Int = -1,
    /** This column's sort — per-column, owned by the parent so the same state feeds the focus list.
     *  See the matching note on [LootGridColumn]. Default/Weight/Value (BARTER_SORTS). */
    sort: InvSortState,
    modifier: Modifier = Modifier
) {
    Column(modifier) {
        // Header + this column's sort chips on one line (compact — see LootGridColumn).
        Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
            Text(
                header,
                color = BronzeLight, fontSize = 14.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                maxLines = 1, overflow = TextOverflow.Ellipsis,
                modifier = Modifier.weight(1f)
            )
            Spacer(Modifier.width(6.dp))
            SortChipRow(sort, BARTER_SORTS, compact = true)
        }
        Spacer(Modifier.height(4.dp))
        val presentCats = remember(items) { items.map { it.category }.toSet() }
        val tabs = remember(presentCats) { BARTER_CATEGORIES.filter { it.cat in presentCats } }
        CategoryTabStrip(
            tabs = tabs,
            selected = selectedCategory,
            label = { it.label },
            key = { it.cat },            // barter filters by the engine's category string
            onSelect = onSelectCategory
        )
        Spacer(Modifier.height(4.dp))
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.5f)))
        Spacer(Modifier.height(6.dp))

        // Same filter+sort the controller focus index is computed against (barterVisible). The sort
        // MUST be the state the parent fed its focus list, or the grid and the cursor desync.
        val visible = remember(items, selectedCategory, isPlayerSide, sort.mode, sort.descending) {
            barterVisible(items, selectedCategory, isPlayerSide, sort.mode, sort.descending)
        }
        if (visible.isEmpty()) {
            Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                Text("Nothing to trade", color = BoneDim, fontSize = 12.sp, fontFamily = MwBody)
            }
        } else {
            val gridState = rememberLazyGridState()
            // Windowed, NOT pinned-to-the-left-edge — same helper as the looting grid.
            WindowedFocusScroll(gridState, focusedIndex, visible.size, visible)
            // Right stick left/right scrolls this horizontal grid while it's the focused side.
            ScrollByNav(gridState, active = focusedIndex >= 0, horizontal = true)
            LazyHorizontalGrid(
                // 3 rows / tight spacing — matching the looting overlay. Column-major fill, so item
                // index i is at grid row i%3, column i/3 — MUST match rememberBarterNavFocus (rows = 3).
                state = gridState,
                rows = GridCells.Fixed(3),
                modifier = Modifier.fillMaxWidth().weight(1f),
                horizontalArrangement = Arrangement.spacedBy(4.dp),
                verticalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                gridItemsIndexed(visible) { i, item ->
                    BarterGridCell(
                        item = item,
                        isPlayerSide = isPlayerSide,
                        iconBitmap = rememberItemIcon(item.icon),
                        focused = i == focusedIndex,
                        onToggle = onToggle
                    )
                }
            }
            HorizontalGridScrollbar(gridState, Modifier.padding(top = 4.dp))
        }
    }
}

/**
 * One icon cell in the SPLIT barter grids. Tap = select/deselect (add to / remove from the
 * offer); long-press = Info + Buy/Sell. A selected cell gets a bright bronze border highlight
 * (mirroring the current barter overlay's selected state). Stacks > 1 prompt for a quantity.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun BarterGridCell(
    item: BarterItem,
    isPlayerSide: Boolean,
    iconBitmap: ImageBitmap? = null,
    focused: Boolean = false,
    onToggle: (BarterItem) -> Unit
) {
    var menuOpen by remember { mutableStateOf(false) }
    LaunchedEffect(DropdownState.closeRequest) {
        if (DropdownState.closeRequest > 0) menuOpen = false
    }
    val selected = item.isSelected
    val label = item.displayName()

    Box(modifier = Modifier.onGloballyPositioned { ItemInfoPopupState.reportAnchor(item.id, it.boundsInRoot()) }) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            modifier = Modifier
                .width(54.dp)
                // Controller focus: a bronze ring + faint fill around the WHOLE cell (icon + label +
                // price). SELECTED is an inner-icon BronzeLight border + SlotWorn icon fill, so this
                // outer-cell ring reads as a distinct "cursor here" marker even on a selected cell.
                .then(
                    if (focused) Modifier
                        .clip(RoundedCornerShape(4.dp))
                        .background(BronzeLight.copy(alpha = 0.15f))
                        .border(2.dp, BronzeLight, RoundedCornerShape(4.dp))
                    else Modifier
                )
                .combinedClickable(
                    onClick = { onToggle(item) },
                    onLongClick = { menuOpen = true; DropdownState.open() }
                )
                .padding(2.dp)
        ) {
            // Worn (player-side, equipped) gets the same 2dp BronzeLight icon border the looting grid
            // uses — a highlight around the icon, not a backdrop tint. Selected (staged into the offer)
            // uses that same bright border PLUS the SlotWorn fill + count badge, so the two still read
            // distinctly (worn = border only; selected = border + fill + badge).
            val highlightIcon = selected || (isPlayerSide && item.worn)
            Box(
                modifier = Modifier
                    .size(SPLIT_CELL_ICON)
                    .clip(RoundedCornerShape(3.dp))
                    .background(if (selected) SlotWorn else SlotBg)
                    .border(
                        BorderStroke(if (highlightIcon) 2.dp else 1.dp, if (highlightIcon) BronzeLight else BronzeDark),
                        RoundedCornerShape(3.dp)
                    )
            ) {
                EnchantBackdrop(item.enchant != null)
                if (iconBitmap != null) {
                    Image(
                        bitmap = iconBitmap,
                        contentDescription = null,
                        contentScale = ContentScale.Fit,
                        modifier = Modifier.fillMaxSize().padding(3.dp)
                    )
                }
                // Selected-count badge (bottom-right) when > 1.
                if (selected && item.selectedCount > 1) {
                    Text(
                        "×${item.selectedCount}",
                        color = BronzeLight, fontSize = 9.sp,
                        fontFamily = MwData, fontWeight = FontWeight.Bold,
                        modifier = Modifier
                            .align(Alignment.BottomEnd)
                            .background(Color(0xCC0E0B07))
                            .padding(horizontal = 2.dp)
                    )
                } else if (!selected && item.count > 1) {
                    Text(
                        "×${item.count}",
                        color = BoneBright, fontSize = 9.sp,
                        fontFamily = MwData, fontWeight = FontWeight.Bold,
                        modifier = Modifier
                            .align(Alignment.BottomEnd)
                            .background(Color(0xCC0E0B07))
                            .padding(horizontal = 2.dp)
                    )
                }
            }
            Spacer(Modifier.height(2.dp))
            Text(
                label,
                // BoneMuted, not Bone — the app-wide default for an un-highlighted item name
                // (LootGridCell, LootRow, the inventory tab's rows and cards all use it).
                color = if (selected) BoneBright else BoneMuted,
                fontSize = 8.sp, fontFamily = MwBody,
                textAlign = TextAlign.Center,
                maxLines = 2, overflow = TextOverflow.Ellipsis,
                lineHeight = 9.sp,
                modifier = Modifier.width(54.dp)
            )
            // Per-unit barter price.
            Text(
                "${item.value}g",
                color = BoneDim, fontSize = 8.sp, fontFamily = MwData,
                maxLines = 1
            )
        }

        CompanionDropdownMenu(
            expanded = menuOpen,
            onDismissRequest = { menuOpen = false; DropdownState.closeAll() }
        ) {
            Text(
                label,
                color = BronzeLight, fontSize = 12.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp)
            )
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
            val menuItemColors = MenuDefaults.itemColors(textColor = Bone)
            DropdownMenuItem(
                text = {
                    Text(
                        if (selected) "Remove from offer"
                        else if (isPlayerSide) "Sell" else "Buy",
                        fontFamily = MwBody, fontSize = 13.sp
                    )
                },
                onClick = { menuOpen = false; DropdownState.closeAll(); onToggle(item) },
                colors = menuItemColors
            )
            DropdownMenuItem(
                text = { Text("Info", fontFamily = MwBody, fontSize = 13.sp) },
                onClick = { menuOpen = false; DropdownState.closeAll(); ItemInfoPopupState.open(item.id, item.name, item.enchant, onTop = true) },
                colors = menuItemColors
            )
        }
    }
}

/** One side of the barter overlay — header, per-side category tabs, scrolling item list. */
@Composable
private fun BarterColumn(
    header: AnnotatedString,
    items: List<BarterItem>,
    isPlayerSide: Boolean,
    selectedCategory: String?,
    onSelectCategory: (String?) -> Unit,
    onToggle: (BarterItem) -> Unit,
    focusedIndex: Int = -1,
    // MUST match what the parent fed rememberBarterNavFocus — this column re-derives the same
    // visible list, so a different sort here would silently desync the display from the focus index.
    sortMode: InvSort = InvSort.DEFAULT,
    sortDescending: Boolean = true,
    modifier: Modifier = Modifier
) {
    Column(modifier) {
        Text(
            header,
            color = BronzeLight, fontSize = 13.sp,
            fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
            maxLines = 1, overflow = TextOverflow.Ellipsis
        )
        Spacer(Modifier.height(4.dp))
        // Category tabs — All + only the buckets present on this side.
        val presentCats = remember(items) { items.map { it.category }.toSet() }
        val tabs = remember(presentCats) { BARTER_CATEGORIES.filter { it.cat in presentCats } }
        CategoryTabStrip(
            tabs = tabs,
            selected = selectedCategory,
            label = { it.label },
            key = { it.cat },            // barter filters by the engine's category string
            onSelect = onSelectCategory
        )
        Spacer(Modifier.height(4.dp))
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.5f)))

        // Same filter+sort the controller focus index is computed against (barterVisible).
        val visible = remember(items, selectedCategory, isPlayerSide, sortMode, sortDescending) {
            barterVisible(items, selectedCategory, isPlayerSide, sortMode, sortDescending)
        }
        // weight(1f) so the list explicitly takes ALL remaining height in the column —
        // the item lists expand to fill the overlay (matching the looting overlay).
        if (visible.isEmpty()) {
            Box(Modifier.fillMaxWidth().weight(1f), contentAlignment = Alignment.Center) {
                Text("Nothing to trade", color = BoneDim, fontSize = 12.sp, fontFamily = MwBody)
            }
        } else {
            val listState = rememberLazyListState()
            LaunchedEffect(focusedIndex) {
                if (focusedIndex in visible.indices) listState.animateScrollToItem(focusedIndex)
            }
            // Right stick scrolls this list while it's the focused side.
            ScrollByNav(listState, active = focusedIndex >= 0)
            LazyColumn(state = listState, modifier = Modifier.fillMaxWidth().weight(1f)) {
                itemsIndexed(visible) { i, item ->
                    BarterRow(
                        item = item,
                        isPlayerSide = isPlayerSide,
                        iconBitmap = rememberItemIcon(item.icon),
                        focused = i == focusedIndex,
                        onToggle = onToggle
                    )
                }
            }
        }
    }
}

/**
 * One barter item row. Tap = select/deselect (add to / remove from the offer); a stack
 * > 1 routes the SELECT through QuantityRequestState first. Long-press = Info. Selected
 * rows get a SlotWorn highlight + a green "✓ selling"/"✓ buying" tag replacing the tap hint.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun BarterRow(
    item: BarterItem,
    isPlayerSide: Boolean,
    iconBitmap: ImageBitmap? = null,
    focused: Boolean = false,
    onToggle: (BarterItem) -> Unit
) {
    var menuOpen by remember { mutableStateOf(false) }
    LaunchedEffect(DropdownState.closeRequest) {
        if (DropdownState.closeRequest > 0) menuOpen = false
    }
    val selected = item.isSelected
    val label = item.displayName()
    Box(modifier = Modifier.onGloballyPositioned { ItemInfoPopupState.reportAnchor(item.id, it.boundsInRoot()) }) {
        Column {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(if (selected) SlotWorn else Color.Transparent)
                    // Controller focus: a bronze border + faint fill on the row. SELECTED is a
                    // SlotWorn fill (no border), so the border reads as a distinct "cursor here".
                    .then(
                        if (focused) Modifier
                            .background(BronzeLight.copy(alpha = 0.12f))
                            .border(2.dp, BronzeLight)
                        else Modifier
                    )
                    .combinedClickable(
                        onClick = { onToggle(item) },
                        onLongClick = { menuOpen = true; DropdownState.open() }
                    )
                    // Uniform row box (see CLASSIC_ROW_MIN_HEIGHT) so one- and two-line names line up.
                    .heightIn(min = CLASSIC_ROW_MIN_HEIGHT)
                    // 8dp horizontal, matching LootRow — these two Classic rows are the same
                    // component in two screens and were 2dp apart for no reason.
                    .padding(horizontal = 8.dp, vertical = CLASSIC_ROW_PAD_V),
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Icon box.
                Box(
                    modifier = Modifier
                        .size(CLASSIC_ROW_ICON)
                        .clip(RoundedCornerShape(2.dp))
                        .background(SlotBg)
                        .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
                ) {
                    EnchantBackdrop(item.enchant != null)
                    if (iconBitmap != null) {
                        Image(
                            bitmap = iconBitmap,
                            contentDescription = null,
                            contentScale = ContentScale.Fit,
                            modifier = Modifier.fillMaxSize()
                        )
                    }
                }
                Spacer(Modifier.width(8.dp))
                // Name + sub-line (qty · value). Same geometry as LootRow: 8dp end padding, and the
                // WORN tag rides INLINE after the name rather than in the right column, so the two
                // Classic rows line up and the right column is left to selection state alone.
                Column(Modifier.weight(1f).padding(end = 8.dp)) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Text(
                            label,
                            color = if (selected) BoneBright else BoneMuted,
                            fontSize = 13.sp, fontFamily = MwBody,
                            // Two lines before ellipsis — see the matching note in LootRow.
                            maxLines = 2, overflow = TextOverflow.Ellipsis,
                            modifier = Modifier.weight(1f, fill = false)
                        )
                        if (isPlayerSide && item.worn) {
                            Spacer(Modifier.width(6.dp))
                            Text(
                                "WORN",
                                color = BronzeLight, fontSize = 9.sp,
                                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                                letterSpacing = 0.8.sp
                            )
                        }
                    }
                    val sub = buildString {
                        if (item.count > 1) append("×${item.count}  ")
                        append("${item.value}g")
                    }
                    Text(sub, color = BoneDim, fontSize = 9.sp, fontFamily = MwData)
                }
                // Right column: selection state, else the tap hint styled exactly like LootRow's
                // (8sp + 0.3sp tracking). WORN moved inline next to the name — see above.
                Column(horizontalAlignment = Alignment.End) {
                    if (selected) {
                        val n = if (item.selectedCount > 1) " ×${item.selectedCount}" else ""
                        Text(
                            (if (isPlayerSide) "✓ selling" else "✓ buying") + n,
                            color = BronzeLight, fontSize = 10.sp,
                            fontFamily = MwDisplay, fontWeight = FontWeight.Bold
                        )
                    } else {
                        Text(
                            if (isPlayerSide) "tap to sell" else "tap to buy",
                            color = BoneDim.copy(alpha = 0.7f), fontSize = 8.sp,
                            fontFamily = MwBody, letterSpacing = 0.3.sp
                        )
                    }
                }
            }
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
        }

        CompanionDropdownMenu(
            expanded = menuOpen,
            onDismissRequest = { menuOpen = false; DropdownState.closeAll() }
        ) {
            Text(
                label,
                color = BronzeLight, fontSize = 12.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp)
            )
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
            val menuItemColors = MenuDefaults.itemColors(textColor = Bone)
            DropdownMenuItem(
                text = {
                    Text(
                        if (selected) "Remove from offer"
                        else if (isPlayerSide) "Sell" else "Buy",
                        fontFamily = MwBody, fontSize = 13.sp
                    )
                },
                onClick = { menuOpen = false; DropdownState.closeAll(); onToggle(item) },
                colors = menuItemColors
            )
            DropdownMenuItem(
                text = { Text("Info", fontFamily = MwBody, fontSize = 13.sp) },
                onClick = { menuOpen = false; DropdownState.closeAll(); ItemInfoPopupState.open(item.id, item.name, item.enchant) },
                colors = menuItemColors
            )
        }
    }
}

/** Offer / Cancel button — colored border + tinted fill + colored label (theme-consistent
 *  take on the spec's "green Offer / blue Cancel"). Disabled → dim, non-tappable. */
@Composable
private fun BarterButton(
    label: String,
    color: Color,
    enabled: Boolean,
    modifier: Modifier = Modifier,
    hint: String? = null,
    onClick: () -> Unit
) {
    val c = if (enabled) color else BoneDim
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(3.dp))
            .background(if (enabled) color.copy(alpha = 0.18f) else SlotBg)
            .border(1.dp, c, RoundedCornerShape(3.dp))
            .then(if (enabled) Modifier.clickable { onClick() } else Modifier)
            .padding(vertical = 11.dp),
        contentAlignment = Alignment.Center
    ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(label, color = c, fontSize = 14.sp, fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 1.sp)
            if (hint != null) {
                Spacer(Modifier.width(6.dp))
                Text("[$hint]", color = c.copy(alpha = 0.7f), fontSize = 11.sp, fontFamily = MwData)
            }
        }
    }
}

/** Offer-rejected alert — in-window Box overlay (NOT a Dialog). Tap scrim or OK to dismiss;
 *  the barter session stays open so the player can adjust and try again. */
@Composable
private fun BarterRejectedAlert(reason: String, onDismiss: () -> Unit) {
    val msg = when (reason) {
        "player_gold" -> "You don't have enough gold for that."
        "vendor_gold" -> "The merchant can't afford that."
        "no_items" -> "Select something to trade first."
        "stolen" -> "That item was stolen, so it has been confiscated."
        else -> "The merchant refused your offer."
    }
    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(18f)
            .background(Color(0x99000000))
            .pointerInput(Unit) { detectTapGestures { onDismiss() } },
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .width(320.dp)
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures {} }
                .padding(20.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text("Offer rejected", color = BarterRed, fontSize = 16.sp, fontFamily = MwDisplay, fontWeight = FontWeight.Bold)
            Spacer(Modifier.height(10.dp))
            Text(msg, color = Bone, fontSize = 13.sp, fontFamily = MwBody, textAlign = TextAlign.Center)
            Spacer(Modifier.height(16.dp))
            QtyActionButton("OK", Modifier.fillMaxWidth(), primary = true) { onDismiss() }
        }
    }
}

/* ---- Splash panel for when not in game ---- */
/**
 * Shown from companion start until the first `COMPANION_STATS` line arrives — i.e. across the
 * engine's boot and its initial loading screen — then auto-dismissed by the `state.hasData` effect
 * at the call site.
 *
 * **TAPPING IT DOES NOTHING, DELIBERATELY.** It used to carry `clickable(onClick = onDismiss)`, a
 * manual escape from the days before the auto-dismiss worked (the call site's comment still records
 * why that effect once never fired). With auto-dismiss in place the tap only ever fired by
 * accident, and what it revealed was the thing the splash exists to hide: a live HUD with no game
 * data behind it. So the gesture is gone — but the panel must still SWALLOW the tap, because an
 * Image carrying no pointer modifier does not consume input and the press would fall through to the
 * tab content and the tab bar underneath (HUD is the default tab, so it would open the world map).
 * An empty `detectTapGestures` is the same swallow the DS overlays' panels use.
 *
 * Consequence worth knowing: with no manual dismissal, a game that never sends a single stats line
 * (engine failed to start, or the companion mod is not loaded) leaves this up indefinitely. That is
 * the better of the two outcomes — the alternative was an empty HUD that looks like a broken game
 * rather than one that never started.
 */
@Composable
private fun SplashPanel() {
    Image(
        painter = painterResource(id = R.drawable.openmw_ds_splash),
        contentDescription = null,
        contentScale = ContentScale.Crop,
        modifier = Modifier
            .fillMaxSize()
            .pointerInput(Unit) { detectTapGestures { } }
    )
}

/* ---- Top stat bar (floats over all tabs) ---- */

@Composable
private fun TopStatBar(state: GameState, modifier: Modifier = Modifier) {
    var effectsExpanded by remember { mutableStateOf(false) }
    LaunchedEffect(DropdownState.closeRequest) {
        if (DropdownState.closeRequest > 0) effectsExpanded = false
    }
    val hasEffects = state.activeEffects.isNotEmpty()
    // Collected ONCE here, not inside the per-effect row: this bar recomposes at the stats tick
    // rate (~10 Hz while playing), so a per-row collectAsState would restart one collector per
    // effect per frame. Remembered for the same reason — effectTimersFlow() returns a new wrapper
    // per call, and collectAsState keys on the instance.
    val effectTimersFlow = remember { UiPreferences.effectTimersFlow() }
    val showEffectTimer by effectTimersFlow.collectAsState()

    // The bar, wrapped so the effects dropdown can anchor to the BAR's own bottom-right corner
    // instead of to the little "Effects" button — see the anchor box at the end of this Box.
    Box(modifier) {
    Row(
        modifier = Modifier
            .fillMaxSize()
            .clip(RoundedCornerShape(3.dp))
            .background(FloatStone)
            .border(2.dp, Bronze, RoundedCornerShape(3.dp))
            .padding(horizontal = 14.dp, vertical = 10.dp),
        horizontalArrangement = Arrangement.spacedBy(14.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        CompactStat("Health", state.health, HealthCol, Modifier.weight(1f))
        CompactStat("Magicka", state.magicka, MagickaCol, Modifier.weight(1f))
        CompactStat("Fatigue", state.fatigue, FatigueCol, Modifier.weight(1f))

        if (hasEffects) {
            Box(
                Modifier
                    .width(1.dp)
                    .height(28.dp)
                    .background(BronzeDark)
            )
            Column(
                modifier = Modifier.clickable {
                    effectsExpanded = !effectsExpanded
                    if (effectsExpanded) DropdownState.open() else DropdownState.closeAll()
                },
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Text(
                    "Effects",
                    color = BronzeLight, fontSize = 12.sp,
                    fontFamily = MwDisplay, fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.height(4.dp))
                EffectsSummary(state.activeEffects)
            }
        }
    }

    // Effects dropdown, anchored to a ZERO-SIZE box at the bar's bottom-right corner rather than to
    // the Effects button, so it lands flush with the minimap panel below: the bar and the map box
    // are both fillMaxWidth() in the same Column, so their left/right borders share an x — which
    // makes this anchor's x the map's RIGHT border — and the only thing between them is that
    // Column's 6dp spacing, which the y offset adds back to reach the map's TOP border.
    //
    // Anchoring rather than nudging is what makes it exact: M3's position provider tries
    // anchor.left first, sees a menu that wide would overflow the window, and falls back to
    // aligning the menu's RIGHT edge with anchor.right — the corner itself. No measurement, no
    // tuned pixel offset that a font or padding change would silently invalidate.
    if (hasEffects) {
        Box(Modifier.align(Alignment.BottomEnd)) {
            CompanionDropdownMenu(
                expanded = effectsExpanded,
                onDismissRequest = { effectsExpanded = false; DropdownState.closeAll() },
                offset = DpOffset(0.dp, TOP_BOX_TO_MAP_GAP)
            ) {
                // Cap at ~7 rows then scroll, so a heavily-buffed character can't grow the
                // dropdown to the full screen height. Same heightIn(max) + verticalScroll
                // pattern as InventoryEquippedSection / ItemInfoPopupCard. (M3's own
                // DropdownMenuContent also scrolls, but only at the window bound — it has no
                // row-count cap, and with the content bounded here it has nothing left to do.)
                val effectsScroll = rememberScrollState()
                Column(
                    Modifier
                        .heightIn(max = EFFECTS_DROPDOWN_MAX_HEIGHT)
                        .verticalScroll(effectsScroll)
                ) {
                state.activeEffects.forEach { effect ->
                    val effectIcon = rememberItemIcon(effect.icon)
                    Row(
                        modifier = Modifier
                            .widthIn(min = 170.dp)
                            .padding(horizontal = 12.dp, vertical = 7.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        // Compact 20dp icon box (same placeholder styling as
                        // inventory/spell rows, sized down for the dropdown).
                        Box(
                            modifier = Modifier
                                .size(20.dp)
                                .clip(RoundedCornerShape(2.dp))
                                .background(SlotBg)
                                .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
                        ) {
                            if (effectIcon != null) {
                                Image(
                                    bitmap = effectIcon,
                                    contentDescription = null,
                                    contentScale = ContentScale.Fit,
                                    modifier = Modifier.fillMaxSize()
                                )
                            }
                        }
                        Spacer(Modifier.width(6.dp))
                        EffectDot(effect.harmful, 8.dp)
                        Spacer(Modifier.width(8.dp))
                        Column(Modifier.weight(1f)) {
                            Text(
                                effect.name,
                                color = Bone, fontSize = 12.sp,
                                fontFamily = MwBody,
                                maxLines = 1, overflow = TextOverflow.Ellipsis
                            )
                            val subtitle = effectSubtitle(effect, showEffectTimer)
                            if (subtitle.isNotEmpty()) {
                                Text(
                                    subtitle,
                                    color = BoneDim, fontSize = 10.sp,
                                    fontFamily = MwData,
                                    maxLines = 1, overflow = TextOverflow.Ellipsis
                                )
                            }
                        }
                    }
                }
                }
                ScrollMoreHint(effectsScroll)
            }
        }
    }
    }
}

/** Height cap for the active-effects dropdown before it starts scrolling. Deliberately **6.5 rows,
 *  not 7** (a row = a 20dp icon + 7dp padding either side = 34dp): cutting the last row in half is
 *  itself the "this list continues" signal, which needs no widget and no explanation.
 *
 *  Only a heuristic, which is why [ScrollMoreHint] carries the real signal: rows are NOT uniform —
 *  an effect with a subtitle is ~43dp — so with a subtitled list the cap lands somewhere else in
 *  the row, and could in principle land right on a boundary. */
private val EFFECTS_DROPDOWN_MAX_HEIGHT = 221.dp

/** Fixed width of the [EffectsSummary] cluster. Hard-set (rather than wrap-content) so the row is
 *  the SAME width whether the player has one effect or thirty — that constancy is the whole point
 *  of the summary, since the Health/Magicka/Fatigue bars share this Row's space via weight(1f) and
 *  a growing effects cluster used to squeeze them. Sized for two 2-digit counts. */
private val EFFECTS_SUMMARY_WIDTH = 66.dp

/** The active-effects indicator in [TopStatBar]: a beneficial count and a harmful count, each with
 *  its palette dot, in a fixed-width cluster.
 *
 *  Replaced a one-dot-per-effect row (Aug 2026), which grew without bound and starved the vitals
 *  bars. Deliberately NOT a proportional/averaged indicator: a single harmful effect among many
 *  beneficial ones must stay visible (it is the one you need to notice mid-combat), and any
 *  ratio-based form rounds it away. A count cannot — 1 harmful always reads as 1.
 *
 *  A zero count is dimmed rather than hidden, so the cluster keeps a stable shape while a nonzero
 *  harmful count still stands out against it. */
@Composable
private fun EffectsSummary(effects: List<ActiveEffect>) {
    val harmful = effects.count { it.harmful }
    val beneficial = effects.size - harmful
    Row(
        modifier = Modifier.width(EFFECTS_SUMMARY_WIDTH),
        horizontalArrangement = Arrangement.Center,
        verticalAlignment = Alignment.CenterVertically
    ) {
        EffectsSummaryCount(count = beneficial, harmful = false)
        Spacer(Modifier.width(8.dp))
        EffectsSummaryCount(count = harmful, harmful = true)
    }
}

@Composable
private fun EffectsSummaryCount(count: Int, harmful: Boolean) {
    Row(
        modifier = Modifier.alpha(if (count == 0) 0.35f else 1f),
        verticalAlignment = Alignment.CenterVertically
    ) {
        EffectDot(harmful, 10.dp)
        Spacer(Modifier.width(3.dp))
        Text(
            count.toString(),
            color = Bone, fontSize = 11.sp, fontFamily = MwData,
            maxLines = 1
        )
    }
}

@Composable
private fun EffectDot(harmful: Boolean, sizeDp: Dp) {
    val dotColor = if (harmful) Color(0xFFC75C5C) else Color(0xFF7FBF7F)
    Canvas(Modifier.size(sizeDp)) {
        drawCircle(dotColor.copy(alpha = 0.3f))
        drawCircle(dotColor, radius = size.minDimension * 0.38f)
    }
}

@Composable
private fun CompactStat(
    label: String,
    value: Dynamic,
    color: Color,
    modifier: Modifier = Modifier
) {
    Column(modifier = modifier) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Text(label, color = BronzeLight, fontSize = 12.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold)
            Text(
                "${value.current.toInt()}/${value.max.toInt()}",
                color = Bone, fontSize = 12.sp, fontFamily = MwData
            )
        }
        Spacer(Modifier.height(5.dp))
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(9.dp)
                .clip(RoundedCornerShape(1.dp))
                .background(Color(0xFF0E0B07))
                .border(1.dp, BronzeDark, RoundedCornerShape(1.dp))
        ) {
            Box(
                modifier = Modifier
                    .fillMaxWidth(value.ratio)
                    .height(9.dp)
                    .clip(RoundedCornerShape(1.dp))
                    .background(color)
            )
        }
    }
}

/* ---- Map: local-map texture from the engine + player direction arrow ---- */

@Composable
private fun MapPanel(
    state: GameState,
    splashVisible: Boolean = false,
    // Switch the bottom tab bar. Owned by CompanionScreenContent; the HUD needs it so an empty
    // favourite slot can take the player to the list the favourite is added from.
    onSelectTab: (Tab) -> Unit = {}
) {
    val exteriorMaps by GameStateRepository.exteriorMapBitmaps.collectAsState()
    val interiorMaps by GameStateRepository.interiorMapBitmaps.collectAsState()

    val hasMap = if (state.cellIsExterior)
        exteriorMaps.containsKey(Pair(state.cellGridX, state.cellGridY))
    else
        interiorMaps.isNotEmpty()

    // Teleport-door markers + the interior rotation params for placing them (exterior = identity).
    val doorMarkers by GameStateRepository.doorMarkers.collectAsState()
    val markerSeg = if (!state.cellIsExterior) interiorMaps.values.firstOrNull() else null
    val markerAngle = markerSeg?.angle ?: 0f
    val markerCX = markerSeg?.centerX ?: 0f
    val markerCY = markerSeg?.centerY ?: 0f
    // Holds ONLY the tapped DoorMarker (not a captured screen offset) — its name bubble's screen
    // position is recomputed live from state.pos each recomposition (see the overlay below), so the
    // bubble tracks the marker as the player moves instead of freezing where it was tapped.
    var selectedMarker by remember { mutableStateOf<DoorMarker?>(null) }
    // Map panel size in px, captured from the Box (== the fillMaxSize Canvas) so the name-bubble
    // overlay can run the same markerScreenPos transform the Canvas draw uses.
    var mapBoxSize by remember { mutableStateOf(IntSize.Zero) }
    // Auto-dismiss the door-marker name bubble after DOOR_MARKER_POPUP_MS. Keyed on selectedMarker,
    // so tapping a DIFFERENT marker restarts the timer for it, and closing it (tap-elsewhere / re-tap)
    // cancels the pending dismiss (the null-key branch does nothing). Same LaunchedEffect+delay pattern
    // as the splash / Training dwell timers.
    LaunchedEffect(selectedMarker) {
        if (selectedMarker != null) {
            delay(DOOR_MARKER_POPUP_MS)
            selectedMarker = null
        }
    }

    val favs by FavouritesRepository.state.collectAsState()
    val context = LocalContext.current

    // How many favourite slots each group shows (0..FAV_SLOTS_MAX). These drive the LAYOUT only —
    // the repository has already truncated `favs` to the same counts, so the two cannot disagree.
    val favGearSlots by UiPreferences.favGearSlotsFlow().collectAsState()
    val favMagicSlots by UiPreferences.favMagicSlotsFlow().collectAsState()

    // Native sneak indicator (sneaking && undetected). Drives the stealth icon below.
    val sneakVisible by GameStateRepository.sneakVisible.collectAsState()

    val weaponId = state.equipment["weapon"]
    val weaponItem = weaponId?.let {
        state.inventory.find { it.stackId == weaponId }
            ?: state.inventory.find { it.stackId.isEmpty() && it.id == weaponId }
    }
    val weaponName = if (weaponId == null) "Hand-to-Hand"
                     else weaponItem?.displayName() ?: "None"
    val weaponIcon = weaponItem?.icon ?: ""

    val selectedSpellEntry = state.selectedSpell
        ?.let { sid -> state.spells.find { it.id == sid } }
    val selectedSpellName = selectedSpellEntry?.displayName() ?: "None"
    val spellIcon = selectedSpellEntry?.icon ?: ""

    // Meter on the SPELL icon: a cast-on-use enchanted item's remaining charge. Learned spells
    // and scrolls have no charge (maxCharge = 0) and get no meter.
    val spellMeter = selectedSpellEntry
        ?.takeIf { it.maxCharge > 0 }
        ?.let { (it.charge.toFloat() / it.maxCharge).coerceIn(0f, 1f) }

    // Meter on the WEAPON (equipped item) icon. Two things share the one meter, because they are
    // the same question — how much of this item is left to use:
    //   * enchantment charge, for an item whose enchantment drains (state.equippedCharge is
    //     already null unless it does — see EquippedCharge);
    //   * a lockpick's or probe's remaining USES, which vanilla shows as a number on the item.
    // Charge wins when an item has both, matching the inventory list's condition column. Ordinary
    // weapons deliberately show nothing: their condition degrades slowly and is repairable,
    // whereas both of the above are consumables you need to watch mid-fight or mid-lock.
    val weaponMeter = state.equippedCharge?.ratio
        ?: weaponItem
            ?.takeIf { it.category == "lockpick" || it.category == "probe" }
            ?.cond

    // The game's own player-direction arrow texture (same asset the native HUD minimap and world
    // map use, via RotatingSkin). Extracted through the shared icon pipeline (raw VFS path, DXT
    // decompressed) and drawn rotated by arrowDeg below; falls back to the drawn arrow while it
    // loads or if extraction fails.
    val compassBitmap = rememberItemIcon("textures/compass.dds")

    var showWeaponName by remember { mutableStateOf(false) }
    var showSpellName by remember { mutableStateOf(false) }

    // Auto-dismiss the equipped weapon/spell name labels after EQUIP_NAME_POPUP_MS, mirroring the
    // door-marker bubble. Keyed on the flag, so opening (re)starts the timer and a re-tap that
    // toggle-closes it cancels the timer.
    LaunchedEffect(showWeaponName) {
        if (showWeaponName) {
            delay(EQUIP_NAME_POPUP_MS)
            showWeaponName = false
        }
    }
    LaunchedEffect(showSpellName) {
        if (showSpellName) {
            delay(EQUIP_NAME_POPUP_MS)
            showSpellName = false
        }
    }

    // Laid out like Inventory/Spells: a fixed-height top box (the vitals bar) at 12dp from the
    // top, a 6dp gap, then the map box filling the rest to the tab bar — so all three tabs' boxes
    // line up. The map still fills its own box, so the crop math and overlays are unaffected.
    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(top = 12.dp, bottom = BOTTOM_BAR_SPACE.dp, start = 12.dp, end = 12.dp),
        verticalArrangement = Arrangement.spacedBy(TOP_BOX_TO_MAP_GAP)
    ) {
        TopStatBar(state, Modifier.fillMaxWidth().height(TOP_BOX_HEIGHT))
        Box(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                .mwPanel()
                .onSizeChanged { mapBoxSize = it }
        ) {
        // Canvas fills the whole panel; labels float over it. A tap on a door marker shows its
        // destination name (and is reserved for richer per-marker info later); a tap anywhere else
        // (not covered by an overlay declared later in this Box — those consume the tap first via
        // Compose z-order) opens the in-game world map. Disabled while the splash is up.
        // mapReady gates opening the in-game map: during character creation the inventory/map GUI
        // isn't available, and forcing it (CMP:openmap -> AddUiMode Interface) wedges the game (the
        // top-screen map can't render). The first journal entry is the reliable "character created"
        // signal; it's a pointerInput key so the handler refreshes once char-gen completes.
        val mapReady = state.journalEntries.isNotEmpty()
        Canvas(
            Modifier
                .fillMaxSize()
                .pointerInput(doorMarkers, state.pos, markerAngle, markerCX, markerCY, splashVisible, mapReady) {
                    detectTapGestures { tap ->
                        if (splashVisible) return@detectTapGestures
                        val w = size.width.toFloat(); val h = size.height.toFloat()
                        val hitR = minOf(w, h) * 0.06f
                        // Nearest marker within the (generous, finger-sized) hit radius wins.
                        val hit = doorMarkers
                            .map { m ->
                                m to markerScreenPos(m.worldX, m.worldY, state.pos.x, state.pos.y,
                                    markerAngle, markerCX, markerCY, w, h)
                            }
                            .filter { (_, p) -> (p - tap).getDistance() <= hitR }
                            .minByOrNull { (_, p) -> (p - tap).getDistance() }
                        if (hit != null) {
                            // Re-tapping the marker already shown toggles it closed; tapping a
                            // different one swaps (and the LaunchedEffect above restarts its 3s timer).
                            val m = hit.first
                            selectedMarker = if (selectedMarker == m) null else m
                        } else if (selectedMarker != null) {
                            // A name bubble is showing: this empty-map tap just dismisses it and is
                            // consumed — do NOT also open the world map. A subsequent tap opens it.
                            selectedMarker = null
                        } else if (mapReady) {
                            CompanionActions.openWorldMap()
                        }
                        // else: character not yet created (no journal entries) — ignore the tap
                        // rather than opening the map, which would wedge the game during char-gen.
                    }
                }
        ) {
            val cx = size.width / 2f
            val cy = size.height / 2f
            val cellPx = size.minDimension / MINIMAP_CROP_FRACTION
            // Interior maps are rendered rotated by the cell's NorthMarker angle, so the interior
            // branch adds that angle below; exterior maps are world-aligned (angle 0).
            var arrowDeg = state.rotZ * (180f / Math.PI.toFloat())

            if (state.cellIsExterior) {
                val cellSize = 8192f
                val playerU = ((state.pos.x - state.cellGridX * cellSize) / cellSize).coerceIn(0f, 1f)
                val playerV = (1f - (state.pos.y - state.cellGridY * cellSize) / cellSize).coerceIn(0f, 1f)

                val originX = cx - playerU * cellPx
                val originY = cy - playerV * cellPx

                val reach = (maxOf(size.width, size.height) / cellPx).toInt() + 1
                for (dy in -reach..reach) {
                    for (dx in -reach..reach) {
                        val bmp = exteriorMaps[Pair(state.cellGridX + dx, state.cellGridY + dy)] ?: continue
                        val left = originX + dx * cellPx
                        val top  = originY - dy * cellPx
                        if (left + cellPx < 0f || left > size.width)  continue
                        if (top  + cellPx < 0f || top  > size.height) continue
                        drawImage(
                            image = bmp.asImageBitmap(),
                            dstOffset = IntOffset(left.toInt(), top.toInt()),
                            dstSize   = IntSize(cellPx.toInt(), cellPx.toInt()),
                        )
                    }
                }
            } else if (interiorMaps.isNotEmpty()) {
                // Interior cells are divided into mMapWorldSize-sized segments the same
                // way exterior cells are, anchored at the interior's mBounds min corner
                // (boundsMinX/boundsMinY — constant across all segments of one interior).
                // Compute which segment the player is standing in and their fractional
                // position within it, then crop/zoom exactly like the exterior branch.
                val interiorMapWorldSize = 8192f
                val seg0 = interiorMaps.values.first()
                val boundsMinX = seg0.boundsMinX
                val boundsMinY = seg0.boundsMinY

                // The interior map texture is rendered ROTATED by the cell's NorthMarker angle, so
                // the raw world position/yaw don't line up with it. Mirror the engine's
                // LocalMap::worldToInteriorMapPosition: rotate the player position by `angle` about
                // `center` (rotatePoint), THEN crop; and offset the arrow by the same `angle`
                // (LocalMap::updatePlayer applies +mAngle to the direction). Without this the dot
                // and arrow are off by a constant angle (the interior-spawn bug). angle=0 for a
                // pre-fix export leaves the old world-aligned behaviour.
                val cosA = cos(seg0.angle)
                val sinA = sin(seg0.angle)
                val rotX = cosA * (state.pos.x - seg0.centerX) - sinA * (state.pos.y - seg0.centerY) + seg0.centerX
                val rotY = sinA * (state.pos.x - seg0.centerX) + cosA * (state.pos.y - seg0.centerY) + seg0.centerY
                // Subtract (not add) the map angle: the vertical bitmap flip inverts the arrow's
                // rotation sense, so the interior offset is -angle. Position uses +angle (rotatePoint
                // matches the engine exactly); the arrow's screen convention is the mirror of it.
                arrowDeg -= seg0.angle * (180f / Math.PI.toFloat())

                val rawX = (rotX - boundsMinX) / interiorMapWorldSize
                val rawY = (rotY - boundsMinY) / interiorMapWorldSize
                val playerSegX = floor(rawX).toInt()
                val playerSegY = floor(rawY).toInt()
                val playerU = (rawX - playerSegX).coerceIn(0f, 1f)
                val playerV = (1f - (rawY - playerSegY)).coerceIn(0f, 1f)

                val originX = cx - playerU * cellPx
                val originY = cy - playerV * cellPx

                val reach = (maxOf(size.width, size.height) / cellPx).toInt() + 1
                for (dy in -reach..reach) {
                    for (dx in -reach..reach) {
                        val seg = interiorMaps[Pair(playerSegX + dx, playerSegY + dy)] ?: continue
                        val left = originX + dx * cellPx
                        val top  = originY - dy * cellPx
                        if (left + cellPx < 0f || left > size.width)  continue
                        if (top  + cellPx < 0f || top  > size.height) continue
                        drawImage(
                            image = seg.bitmap.asImageBitmap(),
                            dstOffset = IntOffset(left.toInt(), top.toInt()),
                            dstSize   = IntSize(cellPx.toInt(), cellPx.toInt()),
                        )
                    }
                }
            }

            // Door markers: a small square per teleport door, placed with the same transform as the
            // arrow (drawn UNDER the arrow). The tapped marker is highlighted with a brighter border.
            if (hasMap) {
                val half = size.minDimension * 0.028f
                doorMarkers.forEach { m ->
                    val p = markerScreenPos(m.worldX, m.worldY, state.pos.x, state.pos.y,
                        markerAngle, markerCX, markerCY, size.width, size.height)
                    if (p.x < -half || p.x > size.width + half || p.y < -half || p.y > size.height + half)
                        return@forEach
                    val sel = selectedMarker == m
                    val topLeft = Offset(p.x - half, p.y - half)
                    val sz = Size(half * 2f, half * 2f)
                    drawRect(color = SlotBg, topLeft = topLeft, size = sz)
                    drawRect(
                        color = if (sel) BoneBright else BronzeLight,
                        topLeft = topLeft, size = sz,
                        style = androidx.compose.ui.graphics.drawscope.Stroke(
                            width = half * (if (sel) 0.55f else 0.35f))
                    )
                }
            }

            if (hasMap) {
                val bmp = compassBitmap
                if (bmp != null) {
                    // Draw the game's compass.dds arrow centered on the player, rotated to face.
                    // Its neutral orientation is "up" (angle 0), matching drawArrow, so arrowDeg
                    // feeds in directly. Diameter ~matches the old drawn arrow's footprint.
                    val side = (size.minDimension * 0.12f)
                    rotate(degrees = arrowDeg, pivot = Offset(cx, cy)) {
                        drawImage(
                            image = bmp,
                            dstOffset = IntOffset((cx - side / 2f).toInt(), (cy - side / 2f).toInt()),
                            dstSize = IntSize(side.toInt(), side.toInt()),
                        )
                    }
                } else {
                    drawArrow(cx, cy, size.minDimension * 0.04f, arrowDeg)
                }
            }
        }

        // Tapped door marker's name, anchored just above the marker (px offset within this Box; the
        // offset{} lambda is a Density receiver so dp→px is available). Tapping it dismisses; tapping
        // elsewhere on the map clears it and opens the world map. This is the seed for the future
        // richer per-marker info popup.
        // The anchor is recomputed EACH recomposition from the live state.pos via the SAME
        // markerScreenPos transform the Canvas draw uses, so the bubble follows the marker as the
        // player moves (rather than freezing at the tap-time screen position). state.pos updates on
        // the fast tick, so the offset re-runs and tracks smoothly. Gated on a laid-out map size.
        if (mapBoxSize.width > 0 && mapBoxSize.height > 0) selectedMarker?.let { marker ->
            val pos = markerScreenPos(
                marker.worldX, marker.worldY, state.pos.x, state.pos.y,
                markerAngle, markerCX, markerCY,
                mapBoxSize.width.toFloat(), mapBoxSize.height.toFloat()
            )
            Box(
                Modifier
                    .align(Alignment.TopStart)
                    .offset {
                        IntOffset(
                            (pos.x - 80.dp.toPx()).roundToInt().coerceAtLeast(4),
                            (pos.y - 46.dp.toPx()).roundToInt().coerceAtLeast(4)
                        )
                    }
                    .widthIn(max = 160.dp)
                    .clip(RoundedCornerShape(4.dp))
                    .background(StoneDark)
                    .border(1.dp, Bronze, RoundedCornerShape(4.dp))
                    .pointerInput(Unit) { detectTapGestures { selectedMarker = null } }
                    .padding(horizontal = 8.dp, vertical = 4.dp)
            ) {
                Text(
                    marker.name.ifBlank { "Door" },
                    color = BoneBright, fontSize = 12.sp, fontFamily = MwBody,
                    maxLines = 2, overflow = TextOverflow.Ellipsis, lineHeight = 14.sp
                )
            }
        }

        // Cell name — bottom-centre overlay. Horizontal padding keeps it clear of
        // the GEAR/SPELLS favourite groups in the bottom corners. Up to TWO lines: because the
        // Text is BottomCenter-anchored, a short name renders as one line in its current spot and
        // a long one grows UPWARD into a second row (so more of e.g. "Seyda Neen, Census and
        // Excise Office" is shown); anything past two lines still truncates with an ellipsis.
        // textAlign centres both rows.
        Text(
            if (state.hasData) state.cell.ifEmpty { "Exterior" } else "-",
            color = Bone, fontSize = 16.sp, fontFamily = MwDisplay,
            fontWeight = FontWeight.SemiBold,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis,
            textAlign = TextAlign.Center,
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .padding(bottom = 8.dp, start = 144.dp, end = 144.dp)
        )

        // Spell — top-LEFT icon box, on the same side as the FAV. SPELLS group below it. A
        // cast-on-use enchanted item in the spell slot shows its enchantment charge as a small
        // meter on the icon.
        //
        // Sides are chosen to match the favourite groups at the bottom (FAV. SPELLS bottom-left,
        // FAV. GEAR bottom-right), so each screen edge is consistently "magic" or "gear". If the
        // fav groups are ever swapped, swap these two to match.
        EquippedCornerIcon(
            modifier = Modifier.align(Alignment.TopStart).padding(start = 8.dp, top = 6.dp),
            label = "SPELL",
            iconPath = spellIcon,
            showName = showSpellName,
            onToggle = { showSpellName = !showSpellName },
            meter = spellMeter
        )

        // Weapon — top-RIGHT icon box, above the FAV. GEAR group. Tapping toggles a persistent
        // name label.
        EquippedCornerIcon(
            modifier = Modifier.align(Alignment.TopEnd).padding(end = 8.dp, top = 6.dp),
            label = "WEAPON",
            iconPath = weaponIcon,
            showName = showWeaponName,
            onToggle = { showWeaponName = !showWeaponName },
            // Ammo count for a bow/crossbow. Null for everything else — the exporter decides that
            // (see EquippedAmmo), so there is no weapon-type test here to drift out of step with
            // the engine's own rule.
            ammoCount = state.ammo?.count,
            meter = weaponMeter
        )

        // Sneak indicator — vanilla stealth icon (sneaking && undetected), shown just below the
        // top-left icon box (the SPELL slot) at the same 40dp size. Left deliberately on this
        // side when weapon/spell swapped sides: its 64dp offset is tuned to the corner-icon
        // column height, and it stays clear of the name-label popouts (horizontal), the
        // combat-target overlay (centre) and the bottom fav groups either way.
        // Driven by the native COMPANION_SNEAK_VISIBLE signal.
        if (sneakVisible) {
            SneakCornerIcon(
                modifier = Modifier.align(Alignment.TopStart).padding(start = 8.dp, top = 64.dp)
            )
        }

        // Name labels — absolutely-positioned siblings of the icon columns above, so showing or
        // hiding them never shifts the icons. Each opens INWARD from its icon (spell: to the
        // right of the left icon; weapon: to the left of the right icon), vertically centred on
        // the box. Must stay on the same side as the icon each one belongs to.
        // Horizontal offset = corner gap (8dp) + icon width (40dp) + 6dp gap.
        if (showSpellName) {
            CornerNameLabel(
                name = selectedSpellName,
                alignEnd = false,
                modifier = Modifier
                    .align(Alignment.TopStart)
                    .padding(start = 8.dp + 40.dp + 6.dp, top = 6.dp)
            )
        }
        if (showWeaponName) {
            CornerNameLabel(
                name = weaponName,
                alignEnd = true,
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .padding(end = 8.dp + 40.dp + 6.dp, top = 6.dp)
            )
        }

        // Loading placeholder
        if (!hasMap && state.hasData) {
            Text(
                "Loading map…",
                color = BronzeDark, fontSize = 13.sp, fontFamily = MwBody,
                modifier = Modifier.align(Alignment.Center)
            )
        }

        // Gear favourites — bottom-right, stacked vertically. Wrapped in a tap-catcher (A) whose
        // FAV_GROUP_MARGIN extends the swallow area a few dp around the group (the outer 2dp + the 6dp
        // margin keeps the visible group at its original 8dp from the corner). Un-handled taps here —
        // the label, the inter-slot gap, and just around/below the slots — become no-ops instead of
        // falling through to the map canvas below and opening the world map.
        //
        // At a count of 0 the whole group -- label, slots AND its tap-catcher -- is skipped, so the
        // screen space is genuinely freed and taps there fall through to the map as they would if
        // the group had never existed. Slots stack in a Column, so 1..4 needs no layout maths.
        if (favGearSlots > 0) {
        Box(
            modifier = Modifier
                .align(Alignment.BottomEnd)
                .padding(end = 2.dp, bottom = 2.dp)
                .pointerInput(Unit) { detectTapGestures {} }
                .padding(FAV_GROUP_MARGIN)
        ) {
        Column(
            horizontalAlignment = Alignment.End
        ) {
            Text(
                "FAV. GEAR",
                color = BoneDim,
                fontSize = 10.sp,
                fontFamily = MwDisplay,
                letterSpacing = 1.sp
            )
            Spacer(Modifier.height(FAV_LABEL_GAP))
            repeat(favGearSlots) { idx ->
                if (idx > 0) Spacer(Modifier.height(FAV_SLOT_SPACING))
                val slot = favs.gear.getOrNull(idx)
                val slotItem = slot?.let { s -> state.inventory.find { it.id == s.id } }
                val slotWorn = slot != null && (
                    if (slotItem?.stackId?.isNotEmpty() == true)
                        state.equipment.values.contains(slotItem.stackId)
                    else
                        state.equipment.values.contains(slot.id)
                )
                FavSlotView(
                    slot = slot,
                    borderColor = BronzeLight,
                    equipped = slotWorn,
                    // C: extend the tap target outward only — top slot (idx 0) up, bottom slot down.
                    hitPadTop = if (idx == 0) FAV_SLOT_HIT_EXTEND else 0.dp,
                    // LAST slot, not "slot 1" — the group is 1..4 tall now, and hardcoding index 1
                    // would have left the bottom slot without its downward tap extension at any
                    // count above 2 (and given it to a middle slot).
                    hitPadBottom = if (idx == favGearSlots - 1) FAV_SLOT_HIT_EXTEND else 0.dp,
                    onEmptyTap = {
                        onSelectTab(Tab.INVENTORY)
                        HintToastState.show(FAV_GEAR_HINT)
                    },
                    menuItems = { s, dismiss ->
                        val item = state.inventory.find { it.id == s.id }
                        val readable = item?.category == "book" || item?.category == "scroll"
                        val equippable = item != null && item.category != "misc" && !readable
                        val target = item?.stackId?.takeIf { it.isNotEmpty() } ?: s.id
                        val worn = if (item?.stackId?.isNotEmpty() == true)
                            state.equipment.values.contains(item.stackId)
                        else
                            state.equipment.values.contains(s.id)
                        val colors = MenuDefaults.itemColors(textColor = Bone)
                        if (equippable) {
                            DropdownMenuItem(
                                text = { Text(if (worn) "Unequip" else "Equip", fontFamily = MwBody, fontSize = 13.sp) },
                                onClick = {
                                    dismiss()
                                    if (worn) CompanionActions.unequipItem(target)
                                    else CompanionActions.equipItem(target)
                                },
                                colors = colors
                            )
                        }
                        if (readable) {
                            DropdownMenuItem(
                                text = { Text("Read", fontFamily = MwBody, fontSize = 13.sp) },
                                onClick = { dismiss(); CompanionActions.readItem(s.id) },
                                colors = colors
                            )
                        }
                        DropdownMenuItem(
                            text = { Text("Drop", fontFamily = MwBody, fontSize = 13.sp) },
                            onClick = {
                                dismiss()
                                val count = item?.count ?: 1
                                // Map tab (favourites slot) — a plain TAB, no controller nav routed
                                // here, so no "[Y]" hint. Same reasoning as the inventory Drop.
                                QuantityRequestState.requestOrRun(
                                    s.name, count, "Drop", showControllerHint = false
                                ) { n ->
                                    CompanionActions.dropItem(s.id, n)
                                }
                            },
                            colors = colors
                        )
                        DropdownMenuItem(
                            text = { Text("Unfavourite", fontFamily = MwBody, fontSize = 13.sp) },
                            onClick = { dismiss(); FavouritesRepository.clearGear(context, idx) },
                            colors = colors
                        )
                    }
                ) {
                    val s = slot ?: return@FavSlotView
                    val item = state.inventory.find { it.id == s.id }
                    val readable = item?.category == "book" || item?.category == "scroll"
                    val equippable = item != null && item.category != "misc" && !readable
                    // Use per-stack instance id when available; fall back to recordId.
                    val target = item?.stackId?.takeIf { it.isNotEmpty() } ?: s.id
                    val worn = if (item?.stackId?.isNotEmpty() == true)
                        state.equipment.values.contains(item.stackId)
                    else
                        state.equipment.values.contains(s.id)
                    when {
                        readable    -> CompanionActions.readItem(s.id)
                        equippable && worn -> CompanionActions.unequipItem(target)
                        equippable  -> CompanionActions.equipItem(target)
                    }
                }
            }
        }
        }
        }

        // Magic favourites — bottom-left, stacked vertically. Wrapped in the same tap-catcher (A)
        // + margin so near-miss taps around the group don't open the map. See the gear group above,
        // including why a count of 0 skips the tap-catcher too.
        if (favMagicSlots > 0) {
        Box(
            modifier = Modifier
                .align(Alignment.BottomStart)
                .padding(start = 2.dp, bottom = 2.dp)
                .pointerInput(Unit) { detectTapGestures {} }
                .padding(FAV_GROUP_MARGIN)
        ) {
        Column {
            Text(
                "FAV. SPELLS",
                color = BoneDim,
                fontSize = 10.sp,
                fontFamily = MwDisplay,
                letterSpacing = 1.sp
            )
            Spacer(Modifier.height(FAV_LABEL_GAP))
            repeat(favMagicSlots) { idx ->
                if (idx > 0) Spacer(Modifier.height(FAV_SLOT_SPACING))
                val slot = favs.magic.getOrNull(idx)
                val slotSelected = slot != null && state.selectedSpell == slot.id
                FavSlotView(
                    slot = slot,
                    borderColor = BronzeLight,
                    equipped = slotSelected,
                    // C: extend the tap target outward only — top slot (idx 0) up, LAST slot down.
                    hitPadTop = if (idx == 0) FAV_SLOT_HIT_EXTEND else 0.dp,
                    hitPadBottom = if (idx == favMagicSlots - 1) FAV_SLOT_HIT_EXTEND else 0.dp,
                    onEmptyTap = {
                        onSelectTab(Tab.MAGIC)
                        HintToastState.show(FAV_SPELL_HINT)
                    },
                    menuItems = { s, dismiss ->
                        val colors = MenuDefaults.itemColors(textColor = Bone)
                        DropdownMenuItem(
                            text = { Text("Set as active spell", fontFamily = MwBody, fontSize = 13.sp) },
                            onClick = { dismiss(); CompanionActions.selectSpell(s.id) },
                            colors = colors
                        )
                        DropdownMenuItem(
                            text = { Text("Unfavourite", fontFamily = MwBody, fontSize = 13.sp) },
                            onClick = { dismiss(); FavouritesRepository.clearMagic(context, idx) },
                            colors = colors
                        )
                    }
                ) {
                    slot?.let { CompanionActions.selectSpell(it.id) }
                }
            }
        }
        }
        }

        // Combat target — top-centre, in the gap between the WEAPON and SPELL
        // pills. Only present while a target exists (during combat), and only when the
        // target-health bar is routed to the bottom screen (TOP moves it to a top-screen overlay).
        val targetHealthLocation by UiPreferences.targetHealthLocationFlow().collectAsState()
        val combatTarget =
            if (targetHealthLocation == TargetHealthLocation.BOTTOM) state.target else null
        // Non-null == the top-centre slot is taken; the followed-quest label below yields to it.
        val targetOverlayShowing = combatTarget != null
        if (combatTarget != null) {
            TargetHealthOverlay(
                target = combatTarget,
                modifier = Modifier
                    .align(Alignment.TopCenter)
                    .padding(top = 6.dp)
            )
        }

        // Followed quest — top-centre, the same slot the combat target uses, so it yields whenever
        // that overlay is up (combat is transient, and target health routed to the bottom screen is
        // not the default). Declared LAST in this Box so it paints above the door-marker bubble if
        // they ever overlap.
        val questPrefs by QuestPrefsRepository.state.collectAsState()
        val followedId = questPrefs.followed
        if (!targetOverlayShowing && followedId == null) {
            // Still yields to the combat target, exactly as the followed label does — a transient
            // fight matters more than an empty slot.
            EmptyTrackedQuestLabel(modifier = Modifier.align(Alignment.TopCenter))
        }
        if (!targetOverlayShowing && followedId != null) {
            // Resolved against the QUEST LIST, the same source the Quests tab now reads, so the
            // HUD can never name a quest differently from the page it navigates to. The manual
            // pseudo-quest is special-cased because it exists only on this side and is never in
            // the export — without it this falls through to prettifyQuestId of the reserved id and
            // prints garbage on the HUD.
            val followedQuests by GameStateRepository.quests.collectAsState()
            val followedTitle = remember(followedId, followedQuests) {
                when {
                    followedId == MANUAL_QUEST_ID -> MANUAL_QUEST_NAME
                    else -> followedQuests.firstOrNull { it.id == followedId }?.name
                        ?: prettifyQuestId(followedId)
                }
            }
            FollowedQuestLabel(
                questId = followedId,
                title = followedTitle,
                hidden = followedId in questPrefs.hidden,
                modifier = Modifier.align(Alignment.TopCenter)
            )
        }
        }  // end map Box
    }
}

/**
 * Width cap on the followed-quest label — doubled from 200dp Aug 10 2026 so long quest names get a
 * real chance to read on one or two lines.
 *
 * 200dp was the width at which the label cleared the corner NAME LABELS (each side occupies about
 * 8 + 40 + 120 = 168dp once a weapon/spell name is toggled on). At 400dp it no longer does, and
 * that overlap is a DELIBERATE, accepted trade: the bare corner icons only take ~48dp a side, so
 * the common case is clear either way, and the name popouts are opt-in and transient while the
 * followed quest is persistent. If this needs to grow again, the corner labels are the thing to
 * look at first — not this constant.
 */
private val FOLLOWED_QUEST_MAX_WIDTH = 400.dp

/**
 * How often to re-ask for the finished-quest set while a quest is followed on the HUD, so the
 * auto-unfollow fires without the player having to open the journal.
 *
 * 10s rather than something snappier because the normal completion path does NOT wait for it: a
 * finished quest almost always adds a journal entry, and the effect that owns this loop is keyed on
 * the entry count, so that case refreshes on the next journal tick (5s) regardless. This interval
 * only bounds the rarer no-entry case (MWScript SetJournalIndex, or an entry with empty text).
 *
 * The export it triggers is one small line per FINISHED quest, which grows over a playthrough, so
 * this is deliberately not run when nothing is followed and deliberately not run fast.
 */
private const val QUEST_STATUS_POLL_MS = 10_000L

/**
 * Hint copy for the three empty-state taps. Deliberately says "long-press an item" rather than
 * spelling out navigate-then-long-press: the tap has ALREADY done the navigating by the time the
 * hint is read, so describing that step would narrate what just happened instead of the one thing
 * left to do.
 */
private const val FAV_GEAR_HINT = "Long-press an item here to make it a favourite"
private const val FAV_SPELL_HINT = "Long-press a spell here to make it a favourite"
private const val TRACKED_QUEST_HINT = "Long-press a quest here to track it"

/** Heading over the HUD's tracked-quest slot, shared by the followed and empty states so the two
 *  can never disagree. Was "QUEST"; renamed Aug 21 2026, styling untouched. */
private const val TRACKED_QUEST_HEADING = "TRACKED QUEST"

/**
 * The followed quest's name, top-centre on the HUD map. Tap jumps to its journal page; long-press
 * opens the same Hide/Follow menu the quest list rows use.
 *
 * TOUCH HANDLING IS LOAD-BEARING, not decoration. The map Canvas covers the whole panel with its
 * own detectTapGestures, and Compose delivers a pointer event to the TOPMOST node with a
 * pointer-input modifier rather than fanning it out — so a plain Text here would not be a hit
 * target at all and every tap on it would fall through and open the world map (which is exactly
 * what the cell name does today). Hence: an outer empty tap-catcher + FAV_GROUP_MARGIN so
 * near-miss taps around the label become no-ops (the fav groups' treatment, same constant), and a
 * combinedClickable on the label itself, which consumes both gestures so the Canvas never sees
 * them — no ambiguity with the map-open or door-marker-dismiss branches.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun FollowedQuestLabel(
    questId: String,
    title: String,
    hidden: Boolean,
    modifier: Modifier = Modifier
) {
    var menuOpen by remember { mutableStateOf(false) }
    LaunchedEffect(DropdownState.closeRequest) {
        if (DropdownState.closeRequest > 0) menuOpen = false
    }

    // Outer swallow margin; the inner padding keeps the visible label at the same 6dp from the top
    // the combat-target overlay uses.
    Box(
        modifier = modifier
            .pointerInput(Unit) { detectTapGestures {} }
            .padding(FAV_GROUP_MARGIN)
    ) {
        Box {
            Column(
                modifier = Modifier
                    .widthIn(max = FOLLOWED_QUEST_MAX_WIDTH)
                    // NO background/border — the label sits straight on the map, matching
                    // TargetHealthOverlay, which shares this exact slot and never had a box. The
                    // panel was what made the two look like different kinds of thing.
                    .combinedClickable(
                        onClick = { JournalQuestNavState.request(questId) },
                        onLongClick = { menuOpen = true; DropdownState.open() }
                    )
                    .padding(horizontal = 8.dp, vertical = 4.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Text(
                    TRACKED_QUEST_HEADING,
                    color = BoneDim, fontSize = 9.sp,
                    fontFamily = MwDisplay, letterSpacing = 1.5.sp
                )
                Spacer(Modifier.height(2.dp))
                // No star here: the label IS the followed quest, so the marker would be redundant.
                // The star only earns its place in the quest LIST, where it distinguishes one row.
                Text(
                    title,
                    color = BronzeLight, fontSize = 13.sp, fontFamily = MwBody,
                    fontWeight = FontWeight.SemiBold,
                    maxLines = 2, overflow = TextOverflow.Ellipsis,
                    textAlign = TextAlign.Center,
                    lineHeight = 15.sp
                )
            }

            QuestContextMenu(
                questId = questId, title = title, hidden = hidden, followed = true,
                expanded = menuOpen,
                onDismiss = { menuOpen = false; DropdownState.closeAll() }
            )
        }
    }
}

/**
 * The tracked-quest slot with nothing tracked. Same heading, same slot, same swallow-margin
 * treatment as [FollowedQuestLabel] — dimmed, and with a placeholder line in place of the title so
 * the area reads as an EMPTY SLOT rather than as blank map. That is the same idiom the empty
 * favourite slots use (label + dim boxes), which is what makes both discoverable at all.
 *
 * A tap opens the quest list and explains how to track one. There is no long-press: tracking is the
 * quest row's own long-press over in the journal, exactly as before.
 */
@Composable
private fun EmptyTrackedQuestLabel(modifier: Modifier = Modifier) {
    Box(
        modifier = modifier
            .pointerInput(Unit) { detectTapGestures {} }
            .padding(FAV_GROUP_MARGIN)
    ) {
        Column(
            modifier = Modifier
                .clickable {
                    JournalQuestNavState.requestList()
                    HintToastState.show(TRACKED_QUEST_HINT)
                }
                .padding(horizontal = 8.dp, vertical = 4.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                TRACKED_QUEST_HEADING,
                // Dimmer than the followed label's heading by the same ratio the empty favourite
                // slots use (0.4f), so "nothing here" reads at a glance.
                color = BoneDim.copy(alpha = 0.4f), fontSize = 9.sp,
                fontFamily = MwDisplay, letterSpacing = 1.5.sp
            )
            Spacer(Modifier.height(2.dp))
            Text(
                "None",
                color = BoneMuted.copy(alpha = 0.5f), fontSize = 13.sp, fontFamily = MwBody,
                fontWeight = FontWeight.SemiBold
            )
        }
    }
}

/** Target name + health bar shown at the bottom-centre of the HUD map. */
@Composable
private fun TargetHealthOverlay(target: TargetInfo, modifier: Modifier = Modifier) {
    Column(
        modifier = modifier.width(200.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text(
            "TARGET",
            color = BoneDim,
            fontSize = 9.sp,
            fontFamily = MwDisplay,
            letterSpacing = 1.5.sp
        )
        Spacer(Modifier.height(4.dp))
        Text(
            target.name,
            color = BronzeLight,
            fontSize = 16.sp,
            fontFamily = MwBody,
            fontWeight = FontWeight.SemiBold,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            textAlign = TextAlign.Center,
            modifier = Modifier.widthIn(max = 196.dp)
        )
        Spacer(Modifier.height(5.dp))
        // Taller variant of the player health bar in TopStatBar's CompactStat.
        Box(
            modifier = Modifier
                .width(200.dp)
                .height(16.dp)
                .clip(RoundedCornerShape(2.dp))
                .background(Color(0xFF0E0B07))
                .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
        ) {
            Box(
                modifier = Modifier
                    .fillMaxWidth(target.health.ratio)
                    .height(16.dp)
                    .clip(RoundedCornerShape(2.dp))
                    .background(HealthCol)
            )
        }
    }
}

// Top-corner equipped weapon / selected spell: a 40dp icon box with a centered
// caption above it. Tapping the box toggles a persistent name label (rendered as
// a separate sibling overlay — see CornerNameLabel — so it never shifts the icon).
// Border brightens to BronzeLight while the name label is showing.
@Composable
private fun EquippedCornerIcon(
    modifier: Modifier,
    label: String,
    iconPath: String,
    showName: Boolean,
    onToggle: () -> Unit,
    // A thin meter across the bottom of the icon, same colours as the spells-tab charge bar:
    // enchantment charge, or a lockpick/probe's remaining uses. 0f..1f; null = no meter.
    // Computed by the caller so this box stays a dumb renderer and each slot keeps its own rule
    // for what the meter means (see the two call sites).
    meter: Float? = null,
    // Remaining rounds in the equipped ammo stack, for a bow/crossbow in the WEAPON slot.
    // null = no counter, which is the normal case for every other weapon (and for a bow with
    // nothing loaded) — see EquippedAmmo.
    ammoCount: Int? = null,
) {
    val icon = rememberItemIcon(iconPath)
    Column(
        modifier = modifier,
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(4.dp)
    ) {
        Text(
            label,
            color = BoneDim,
            fontSize = 7.sp,
            fontFamily = MwDisplay,
            letterSpacing = 1.sp
        )
        Box(
            modifier = Modifier
                .size(40.dp)
                .clip(RoundedCornerShape(2.dp))
                .background(SlotBg)
                .border(1.dp, if (showName) BronzeLight else BronzeDark, RoundedCornerShape(2.dp))
                .clickable { onToggle() }
        ) {
            if (icon != null) {
                Image(
                    bitmap = icon,
                    contentDescription = null,
                    contentScale = ContentScale.Fit,
                    modifier = Modifier.size(40.dp)
                )
            }
            // Charge / uses meter, overlaid across the bottom edge of the icon (spells-tab style).
            if (meter != null) {
                val ratio = meter.coerceIn(0f, 1f)
                val fillColor = if (ratio >= 0.5f) BronzeLight else Color(0xFFC75C5C)
                Box(
                    modifier = Modifier
                        .align(Alignment.BottomCenter)
                        .padding(horizontal = 2.dp, vertical = 2.dp)
                        .fillMaxWidth()
                        .height(4.dp)
                        .clip(RoundedCornerShape(1.dp))
                        .background(Color(0xFF0E0B07))
                        .border(1.dp, BronzeDark, RoundedCornerShape(1.dp))
                ) {
                    Box(
                        Modifier
                            .fillMaxWidth(ratio)
                            .fillMaxHeight()
                            .background(fillColor)
                    )
                }
            }
        }
        // Ammo count, in a chip directly BELOW the icon box. Inside the same Column so it stays
        // centred under the icon and the Column simply grows downward — the corner name label is an
        // absolutely-positioned sibling anchored to the box's own top, so it does not move, and
        // the only other corner element (the sneak icon at top+64dp) is on the opposite side.
        // The × is one of the few symbols the game typeface actually carries; see the glyph note
        // on MysticCards before using any other decorative mark here.
        if (ammoCount != null) {
            Text(
                "×$ammoCount",
                color = Bone,
                fontSize = 10.sp,
                fontFamily = MwData,
                maxLines = 1,
                modifier = Modifier
                    .clip(RoundedCornerShape(2.dp))
                    .background(SlotBg)
                    .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
                    .padding(horizontal = 5.dp, vertical = 1.dp)
            )
        }
    }
}

// The sneak indicator icon (vanilla "sneaking && undetected" state). Mirrors
// EquippedCornerIcon's 40dp box + caption but is non-interactive (no name toggle).
// Rendered only while GameStateRepository.sneakVisible is true. The icon is the same
// VFS DDS the native HUD uses (icons/k/stealth_sneak.dds), loaded via rememberItemIcon.
@Composable
private fun SneakCornerIcon(modifier: Modifier) {
    val icon = rememberItemIcon("icons/k/stealth_sneak.dds")
    Column(
        modifier = modifier,
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(4.dp)
    ) {
        Text(
            "SNEAK",
            color = BoneDim,
            fontSize = 7.sp,
            fontFamily = MwDisplay,
            letterSpacing = 1.sp
        )
        Box(
            modifier = Modifier
                .size(40.dp)
                .clip(RoundedCornerShape(2.dp))
                .background(SlotBg)
                .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
        ) {
            if (icon != null) {
                Image(
                    bitmap = icon,
                    contentDescription = null,
                    contentScale = ContentScale.Fit,
                    modifier = Modifier.size(40.dp)
                )
            }
        }
    }
}

// The equipped weapon / spell name label, rendered as an absolutely-positioned
// sibling of the icon Column (NOT a child) so toggling it can never move the icon.
// It sits beside the 40dp icon box and is vertically centred on it: an invisible
// caption placeholder + 4dp spacer reproduce the icon Column's vertical offset
// (top padding → caption → gap → icon) so the label lines up with the icon exactly
// regardless of font metrics. `alignEnd` mirrors the layout for the right corner.
@Composable
private fun CornerNameLabel(name: String, alignEnd: Boolean, modifier: Modifier) {
    Column(
        modifier = modifier,
        horizontalAlignment = if (alignEnd) Alignment.End else Alignment.Start
    ) {
        // Transparent copy of the WEAPON/SPELL caption: reserves the exact same
        // height as the real caption above the icon so the label below aligns.
        Text(
            "W",
            color = Color.Transparent,
            fontSize = 7.sp,
            fontFamily = MwDisplay,
            letterSpacing = 1.sp
        )
        Spacer(Modifier.height(4.dp))
        // The panel wraps its content, but a Text that WRAPS to two lines otherwise reports the full
        // max width (leaving empty space beside right-aligned text). Measure the widest actual laid-out
        // line and constrain the Text to it, so the panel hugs the text tightly on both one and two
        // lines. Re-measures per name; converges in one extra layout (constraining to the widest line
        // keeps the same line breaks).
        val density = LocalDensity.current
        var lineWidth by remember(name) { mutableStateOf<Dp?>(null) }
        // 40dp-tall band matching the icon box; centre the label within it.
        Box(Modifier.height(40.dp), contentAlignment = Alignment.Center) {
            Box(
                modifier = Modifier
                    .widthIn(max = 120.dp)
                    .clip(RoundedCornerShape(2.dp))
                    .background(StonePanel)
                    .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
                    .padding(horizontal = 8.dp, vertical = 3.dp)
            ) {
                Text(
                    name,
                    color = Bone,
                    fontSize = 9.sp,
                    fontFamily = MwBody,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                    textAlign = if (alignEnd) TextAlign.End else TextAlign.Start,
                    modifier = lineWidth?.let { Modifier.width(it) } ?: Modifier,
                    onTextLayout = { result ->
                        var widest = 0f
                        for (i in 0 until result.lineCount) {
                            widest = maxOf(widest, result.getLineRight(i) - result.getLineLeft(i))
                        }
                        val w = with(density) { widest.toDp() }
                        if (lineWidth == null || kotlin.math.abs((lineWidth!! - w).value) > 0.5f) {
                            lineWidth = w
                        }
                    }
                )
            }
        }
    }
}

private val EQUIPPED_PILL_MAX_FONT = 12.sp
private val EQUIPPED_PILL_MIN_FONT = 8.sp

@Composable
private fun EquippedDisplayPill(value: String) {
    val isEmpty = value == "None"
    var fontSize by remember(value) { mutableStateOf(EQUIPPED_PILL_MAX_FONT) }
    Box(
        modifier = Modifier
            .width(FAV_SLOT_WIDTH)
            .height(FAV_SLOT_HEIGHT)
            .clip(RoundedCornerShape(4.dp))
            .background(Color(0xC0151210))
            .border(1.dp, BronzeDark, RoundedCornerShape(4.dp)),
        contentAlignment = Alignment.Center
    ) {
        Text(
            value,
            color = if (isEmpty) BoneDim else Bone,
            fontSize = fontSize,
            fontFamily = MwBody,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            textAlign = TextAlign.Center,
            softWrap = false,
            onTextLayout = { result ->
                if (result.didOverflowWidth && fontSize > EQUIPPED_PILL_MIN_FONT) {
                    fontSize = (fontSize.value - 1).sp
                }
            },
            modifier = Modifier.padding(horizontal = 6.dp)
        )
    }
}

// Screen position (px, within a wxh canvas) of a world point on the companion minimap, using the
// SAME transform as the player arrow: player centered, exterior world-aligned or interior rotated by
// `angle` about (centerX,centerY). angle=0 (with center 0,0) → the identity used for exterior. Shared
// by the door-marker draw and the tap hit-test so they can never diverge.
private fun markerScreenPos(
    worldX: Float, worldY: Float, playerX: Float, playerY: Float,
    angle: Float, centerX: Float, centerY: Float, w: Float, h: Float
): Offset {
    val cellPx = minOf(w, h) / MINIMAP_CROP_FRACTION
    val ca = cos(angle); val sa = sin(angle)
    val rmx = ca * (worldX - centerX) - sa * (worldY - centerY) + centerX
    val rmy = sa * (worldX - centerX) + ca * (worldY - centerY) + centerY
    val rpx = ca * (playerX - centerX) - sa * (playerY - centerY) + centerX
    val rpy = sa * (playerX - centerX) + ca * (playerY - centerY) + centerY
    return Offset(w / 2f + (rmx - rpx) / 8192f * cellPx, h / 2f - (rmy - rpy) / 8192f * cellPx)
}

private fun DrawScope.drawArrow(cx: Float, cy: Float, r: Float, degrees: Float) {
    val path = androidx.compose.ui.graphics.Path().apply {
        moveTo(cx, cy - r * 1.8f)
        lineTo(cx - r * 0.7f, cy + r * 0.6f)
        lineTo(cx,             cy + r * 0.1f)
        lineTo(cx + r * 0.7f, cy + r * 0.6f)
        close()
    }
    rotate(degrees = degrees, pivot = Offset(cx, cy)) {
        drawPath(path, color = androidx.compose.ui.graphics.Color(0xFFFFD700))
        drawPath(path, color = androidx.compose.ui.graphics.Color(0xFF000000),
            style = androidx.compose.ui.graphics.drawscope.Stroke(width = r * 0.25f))
    }
}


@Composable
private fun MapButton(label: String, filled: Boolean, onClick: () -> Unit) {
    Box(
        modifier = Modifier
            .clip(RoundedCornerShape(2.dp))
            .background(if (filled) Bronze else Color.Transparent)
            .border(1.dp, if (filled) BronzeLight else BronzeDark, RoundedCornerShape(2.dp))
            .clickable { onClick() }
            .padding(horizontal = 14.dp, vertical = 8.dp)
    ) {
        Text(
            label,
            color = if (filled) StoneDark else Bone,
            fontSize = 12.sp,
            fontFamily = MwDisplay,
            fontWeight = if (filled) FontWeight.Bold else FontWeight.Normal
        )
    }
}

/* ---- Favourites: shared helpers ---- */

/** Small gold star drawn to the RIGHT of a favourited item/spell name. It's a
 *  standalone Icon (never concatenated into the name string) so it appears and
 *  disappears the instant the favourites state changes. */
@Composable
private fun FavStar() {
    Icon(
        imageVector = Icons.Filled.Star,
        contentDescription = "Favourite",
        tint = BronzeLight,
        modifier = Modifier.size(13.dp)
    )
}

/**
 * Favourites section for an item/spell long-press dropdown (rendered inside a
 * DropdownMenu's ColumnScope). Shows "Unfavourite" when the record already
 * occupies a slot; otherwise "Add to favourites" when a slot is free, or an
 * explicit slot picker when they are ALL full — the old auto-pick always
 * clobbered slot 1, so slot 2 could never be replaced. `isGear` selects the
 * gear vs magic slot list; `makeSlot` builds the FavSlot with the live name.
 *
 * Works at any configured slot count without change: it reads the repository's already-truncated
 * list and indexes into it, so 1..FAV_SLOTS_MAX all behave identically and only the number of
 * "Slot N" rows in the replace picker differs. A count of 0 renders nothing.
 */
@Composable
private fun ColumnScope.FavouriteMenuItems(
    context: Context,
    isGear: Boolean,
    itemId: String,
    makeSlot: () -> FavSlot,
    onDone: () -> Unit
) {
    val favs by FavouritesRepository.state.collectAsState()
    // Already truncated to the configured visible count by the repository, so this section scales
    // to 1..FAV_SLOTS_MAX with no arithmetic of its own.
    val slots = if (isGear) favs.gear else favs.magic
    // Count 0 = the category's HUD group is off, so offer nothing at all. Without this the
    // "both slots full" branch below would render its "Replace favourite…" header over an empty
    // slot list — a heading with no options under it.
    if (slots.isEmpty()) return
    val colors = MenuDefaults.itemColors(textColor = Bone)
    val favIdx = slots.indexOfFirst { it?.id == itemId }

    fun assign(index: Int) {
        onDone()
        if (isGear) FavouritesRepository.assignGear(context, makeSlot(), index)
        else FavouritesRepository.assignMagic(context, makeSlot(), index)
    }

    if (favIdx >= 0) {
        DropdownMenuItem(
            text = { Text("Unfavourite", fontFamily = MwBody, fontSize = 13.sp) },
            onClick = {
                onDone()
                if (isGear) FavouritesRepository.clearGear(context, favIdx)
                else FavouritesRepository.clearMagic(context, favIdx)
            },
            colors = colors
        )
    } else {
        val emptyIdx = slots.indexOfFirst { it == null }
        if (emptyIdx >= 0) {
            DropdownMenuItem(
                text = { Text("Add to favourites", fontFamily = MwBody, fontSize = 13.sp) },
                onClick = { assign(emptyIdx) },
                colors = colors
            )
        } else {
            // Every visible slot is full — let the user choose which one to overwrite.
            Text(
                "Replace favourite…",
                color = BoneDim, fontSize = 10.sp, fontFamily = MwDisplay,
                letterSpacing = 0.5.sp,
                modifier = Modifier.padding(start = 12.dp, end = 12.dp, top = 6.dp, bottom = 2.dp)
            )
            slots.forEachIndexed { i, s ->
                DropdownMenuItem(
                    text = {
                        Text(
                            "Slot ${i + 1}: ${s?.name ?: "—"}",
                            fontFamily = MwBody, fontSize = 13.sp,
                            maxLines = 1, overflow = TextOverflow.Ellipsis
                        )
                    },
                    onClick = { assign(i) },
                    colors = colors
                )
            }
        }
    }
}

/* ---- Favourite slots (floating over the map) ---- */

@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun FavSlotView(
    slot: FavSlot?,
    borderColor: Color,
    equipped: Boolean = false,
    // C: outward-only tap-target extension (transparent). hitPadTop enlarges the touch area upward
    // (used by the top slot), hitPadBottom downward (bottom slot). The visual box is unchanged.
    hitPadTop: Dp = 0.dp,
    hitPadBottom: Dp = 0.dp,
    menuItems: (@Composable ColumnScope.(slot: FavSlot, dismiss: () -> Unit) -> Unit)? = null,
    // Tap on an EMPTY slot. Until Aug 21 2026 an empty slot was not clickable at all, so the tap
    // fell through to whatever was behind it and the slot read as broken. It now takes the player
    // to the tab the favourite comes from and explains how to add one. Null keeps the old
    // do-nothing behaviour for any caller that has no sensible destination.
    onEmptyTap: (() -> Unit)? = null,
    onClick: () -> Unit
) {
    val isEmpty = slot == null
    val alpha   = if (isEmpty) 0.4f else 1f
    // Mirror the inventory worn/unworn styling: equipped favourites get the
    // bronze-tinted fill + bright border/name, non-equipped ones stay dim.
    val bgColor    = if (equipped) SlotWorn else Color(0xC0151210)
    val slotBorder = if (equipped) borderColor else BronzeDark
    val textColor  = if (equipped) BoneBright else BoneMuted

    var menuOpen by remember { mutableStateOf(false) }
    // Snapshot the slot the menu was opened for. The menu renders from this, NOT
    // the live `slot`, so that Unfavourite (which nulls the live slot the instant
    // it's tapped) doesn't blank the menu content mid-close and make the popup
    // reposition/"slide" — it fades in place like the other actions. Never reset
    // on dismiss; it's overwritten on the next long-press.
    var menuSlot by remember { mutableStateOf<FavSlot?>(null) }
    LaunchedEffect(DropdownState.closeRequest) {
        if (DropdownState.closeRequest > 0) menuOpen = false
    }

    // Wrapper: wraps the (hit-extended) slot and anchors the dropdown menu.
    Box {
        // Tap target = the visual slot PLUS the outward transparent extension. The clickable is on
        // this box and the extension padding is INSIDE it, so the hit area includes the extension; it
        // only grows away from the neighbour slot (never into the gap), so no ambiguous middle spot.
        Box(
            modifier = Modifier
                .combinedClickable(
                    // An empty slot is clickable ONLY when it has somewhere to send the player.
                    enabled = !isEmpty || onEmptyTap != null,
                    onClick = { if (isEmpty) onEmptyTap?.invoke() else onClick() },
                    // Long-press is unchanged and stays FILLED-only: the add-to-favourites flow is
                    // the item's own long-press over in the Inventory/Spells list, not this slot's.
                    onLongClick = {
                        if (menuItems != null && slot != null) {
                            menuSlot = slot; menuOpen = true; DropdownState.open()
                        }
                    }
                )
                .padding(top = hitPadTop, bottom = hitPadBottom)
        ) {
            // Visual slot box — exact FAV_SLOT_WIDTH x FAV_SLOT_HEIGHT, look unchanged.
            Box(
                modifier = Modifier
                    .width(FAV_SLOT_WIDTH)
                    .height(FAV_SLOT_HEIGHT)
                    .clip(RoundedCornerShape(4.dp))
                    .background(bgColor)
                    .then(
                        if (!isEmpty) Modifier.border(1.dp, slotBorder, RoundedCornerShape(4.dp))
                        else Modifier
                    ),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = slot?.name ?: "Empty",
                    color = textColor.copy(alpha = alpha),
                    fontSize = 11.sp,
                    fontFamily = MwBody,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(horizontal = 6.dp)
                )
                // Dashed border for empty slots drawn as Canvas overlay (avoids clip-halving issue)
                if (isEmpty) {
                    Canvas(modifier = Modifier.fillMaxSize()) {
                        drawRoundRect(
                            color = borderColor.copy(alpha = alpha),
                            style = androidx.compose.ui.graphics.drawscope.Stroke(
                                width = 1.dp.toPx(),
                                pathEffect = androidx.compose.ui.graphics.PathEffect
                                    .dashPathEffect(floatArrayOf(6f, 4f))
                            ),
                            cornerRadius = CornerRadius(4.dp.toPx())
                        )
                    }
                }
            }
        }
        if (menuItems != null) {
            CompanionDropdownMenu(
                expanded = menuOpen,
                onDismissRequest = { menuOpen = false; DropdownState.closeAll() }
            ) {
                menuSlot?.let { s ->
                    Text(
                        s.name,
                        color = BronzeLight, fontSize = 12.sp,
                        fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                        maxLines = 1, overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp)
                    )
                    Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
                    menuItems(s) { menuOpen = false; DropdownState.closeAll() }
                }
            }
        }
    }
}

/* ---- Inventory ---- */

@Composable
private fun InventoryPanel(state: GameState) {
    val tabStyle by UiPreferences.inventoryTabStyleFlow().collectAsState()
    val cards = tabStyle == InventoryTabStyle.CARDS
    // Sort state (mode + direction + the tap/toggle rules) — shared with the looting and barter
    // Classic lists via InvSortState, so all three behave identically. Resets to Default whenever
    // the tab is left; see InvSortState for why it isn't persisted.
    val sort = rememberInvSortState()
    val sortMode = sort.mode
    val sortDescending = sort.descending
    val hideEquippedBar by UiPreferences.hideEquippedBarFlow().collectAsState()
    val showEquippedInList by UiPreferences.showEquippedInListFlow().collectAsState()
    var selectedCategoryLabel by remember { mutableStateOf<String?>(null) }
    val presentCategories = remember(state.inventory) {
        INV_CATEGORIES.filter { grp -> state.inventory.any { it.category in grp.cats } }
    }
    val hasEquipped = remember(state.inventory, state.equipment) {
        val wornIds = state.equipment.values.toSet()
        state.inventory.any {
            if (it.stackId.isNotEmpty()) wornIds.contains(it.stackId) else wornIds.contains(it.id)
        }
    }
    // If the Equipped filter is active and the last equipped item comes off, fall back to All so
    // the (now-hidden) tab doesn't leave a blank list selected.
    LaunchedEffect(hasEquipped) {
        if (!hasEquipped && selectedCategoryLabel == EQUIPPED_FILTER) selectedCategoryLabel = null
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(top = 12.dp, bottom = BOTTOM_BAR_SPACE.dp, start = 12.dp, end = 12.dp),
        verticalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        EquippedStrip(state = state, sort = sort)
        // Ordered filter tabs (All, [Equipped], then present categories) for swipe-cycling — same
        // order CategorySubTabs renders.
        val invTabOrder = buildList<String?> {
            add(null)
            if (hasEquipped) add(EQUIPPED_FILTER)
            presentCategories.forEach { add(it.label) }
        }
        Column(Modifier.weight(1f).mwPanel()) {
            CategorySubTabs(
                categories = presentCategories,
                selected = selectedCategoryLabel,
                hasEquipped = hasEquipped,
                onSelect = { selectedCategoryLabel = it }
            )
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
            // Swipe left/right across the list body to cycle the filter category.
            Box(
                Modifier.weight(1f).categorySwipe(selectedCategoryLabel) { dir ->
                    selectedCategoryLabel = cycleValue(invTabOrder, selectedCategoryLabel, dir)
                }
            ) {
                InventoryItemList(
                    state, selectedCategoryLabel, cards, hideEquippedBar, showEquippedInList,
                    sortMode, sortDescending
                )
            }
        }
    }
}

@Composable
private fun EquippedStrip(state: GameState, sort: InvSortState) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(TOP_BOX_HEIGHT)
            .mwPanel()
            .padding(horizontal = 10.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        // Gold + carried weight. From COMPANION_STATS, and the ONLY place either is shown on this
        // tab — kept exactly as-is when the equipped chip row was replaced by the sort controls.
        StripStat("GOLD", state.gold.toString())
        StripDivider()
        StripStat(
            "WEIGHT",
            "${state.encumbrance.current.toInt()}/${state.encumbrance.max.toInt()}"
        )
        // Flexible gap: pushes the whole SORT cluster to the RIGHT edge of the strip, separating
        // the read-only stats (left) from the controls (right). The weight lives here rather than
        // on the chip Row so the chips wrap their content and stay hard against the right edge
        // instead of stretching across the free space.
        Spacer(Modifier.weight(1f))
        // The chip cluster (icon + Default/Weight/Value) — shared with the looting and barter
        // Classic lists. The flexible gap above pushes it hard against the strip's right edge,
        // separating the read-only stats (left) from the controls (right).
        SortChipRow(sort)
    }
}

/** Sort modes for the inventory tab. [label] is what the chip shows. */
private enum class InvSort(val label: String) {
    // "Value" rather than "Price": the field is the item's base record value (what the vanilla
    // tooltip calls Value), not a merchant-adjusted price — the number differs from what you'd
    // actually be paid, so "Price" overstated it.
    DEFAULT("Default"), WEIGHT("Weight"), PRICE("Value")
}

/**
 * The Weight/Value half of the sort order, generic over the item type so the inventory tab
 * ([InventoryItem]) and the barter overlay ([BarterItem]) run the SAME code rather than two
 * comparators that drift apart. DEFAULT is deliberately NOT handled here: each context's "default"
 * is its own established order (inventory = category → favourite → name; looting = worn → category
 * → name; barter = worn → category → name), and "Default restores the original order" means each
 * screen's own original, so callers keep their existing comparator for that mode.
 *
 * Weight/Value are a PURE ordering — no category tier and no favourite tier (see the long note at
 * the inventory call site for why). Name is the final tiebreak in every mode so equal weights or
 * values don't shuffle between recompositions.
 */
private fun <T> invSortComparator(
    mode: InvSort,
    descending: Boolean,
    name: (T) -> String,
    weight: (T) -> Float,
    value: (T) -> Int
): Comparator<T> {
    val base: Comparator<T> = when (mode) {
        InvSort.WEIGHT ->
            if (descending) compareByDescending { weight(it) } else compareBy { weight(it) }
        // DEFAULT never reaches here (callers branch first); fall back to value so the function is
        // total rather than throwing.
        else ->
            if (descending) compareByDescending { value(it) } else compareBy { value(it) }
    }
    return base.thenBy { name(it).lowercase() }
}

/**
 * Tap/toggle behaviour for the sort chips, extracted so every screen that offers sorting behaves
 * IDENTICALLY (tap a new mode → that mode, high→low; re-tap the active mode → flip direction;
 * Default → back to the screen's own order, no direction). Hold it with [rememberInvSortState].
 *
 * Deliberately NOT persisted anywhere: it's a transient "let me find the heavy things" view, not a
 * setting, and returning later to a remembered non-default order would be surprising.
 */
@Stable
private class InvSortState {
    var mode by mutableStateOf(InvSort.DEFAULT)
        private set
    var descending by mutableStateOf(true)
        private set

    fun onSort(tapped: InvSort) {
        when {
            tapped == InvSort.DEFAULT -> mode = InvSort.DEFAULT
            // Re-tapping the active sort flips direction rather than doing nothing.
            mode == tapped -> descending = !descending
            else -> {
                // A fresh sort starts high→low: "what's heaviest / most valuable" is the question
                // people actually open these for.
                mode = tapped
                descending = true
            }
        }
    }

    /**
     * Advance one step through the full sort cycle — the L3 (left stick click) shortcut, an
     * ALTERNATE INPUT to this same state rather than a parallel mechanism, so a chip tap and an L3
     * press always agree on where the cycle resumes from.
     *
     * The sequence is derived from [modes] rather than hardcoded: Default, then each non-default
     * mode descending-then-ascending, wrapping back to Default. For the three-mode screens (looting
     * and, since `companion-barter-weight.patch`, barter) that is Default → Weight ▼ → Weight ▲ →
     * Value ▼ → Value ▲ → Default; a screen that offered fewer modes would get the correspondingly
     * shorter cycle for free instead of stepping through chips it does not show.
     *
     * Descending-first matches [onSort]'s "a fresh sort starts high→low".
     */
    fun cycle(modes: List<InvSort>) {
        val steps = buildList {
            add(InvSort.DEFAULT to true)
            modes.filter { it != InvSort.DEFAULT }.forEach { add(it to true); add(it to false) }
        }
        // DEFAULT has no direction, so match it on mode alone — otherwise a Default reached with a
        // stale `descending == false` would not be found and the cycle would restart from step 0.
        val at = steps.indexOfFirst { (m, d) ->
            m == mode && (m == InvSort.DEFAULT || d == descending)
        }
        val (nextMode, nextDesc) = steps[(at + 1) % steps.size]  // at = -1 (mode not offered) → step 0
        mode = nextMode
        descending = nextDesc
    }
}

@Composable
private fun rememberInvSortState(): InvSortState = remember { InvSortState() }

/**
 * The sort chip cluster: an icon then one [SortChip] per offered mode. [modes] is a parameter
 * rather than a hardcoded `InvSort.entries` so each screen states the set it offers explicitly —
 * a chip is only honest if the underlying data supports it (barter's Weight chip, for one, needs
 * the per-item weight that `companion-barter-weight.patch` added to COMPANION_BARTER_ITEM; see
 * [BARTER_SORTS]). The default covers screens that offer all of them.
 */
@Composable
private fun SortChipRow(
    state: InvSortState,
    modes: List<InvSort> = InvSort.entries,
    // Compact = the SPLIT grid columns, where the chips share a line with the column header and
    // every dp they take comes straight out of the item grid below them. The chip's normal vertical
    // padding was tuned for the inventory tab's 54dp strip, which had room to spare; here it does not.
    compact: Boolean = false
) {
    // Icon in place of a "SORT" caption + divider rule. Those cost ~55dp of a ~473dp strip, which
    // the game font's larger text turned into a real squeeze. The icon says the same thing in ~18dp.
    //
    // A VECTOR rather than a text glyph on purpose: MysticCards has no arrow/symbol coverage
    // (no ▲ ▼ ◀ ▶ · ✓ …), so a typographic sort mark would be at the mercy of font fallback.
    // An ImageVector renders identically whichever font role is active. Precedent: the favourite
    // star is already Icons.Filled.Star.
    Icon(
        imageVector = Icons.AutoMirrored.Filled.Sort,
        contentDescription = "Sort",
        tint = BronzeLight,
        modifier = Modifier.size(if (compact) 15.dp else 18.dp)
    )
    Spacer(Modifier.width(if (compact) 5.dp else 8.dp))
    Row(
        horizontalArrangement = Arrangement.spacedBy(if (compact) 4.dp else 5.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        modes.forEach { mode ->
            SortChip(
                label = mode.label,
                active = state.mode == mode,
                // Default has no direction — an arrow on it would imply a toggle that isn't there.
                arrow = if (state.mode == mode && mode != InvSort.DEFAULT) {
                    if (state.descending) "▼" else "▲"
                } else null,
                compact = compact,
                onClick = { state.onSort(mode) }
            )
        }
    }
}

/** A sort control in the inventory strip. Styled like [CategoryTab] (the tab row directly below it)
 *  so the two rows of controls read as the same family, with a direction arrow when active. */
@Composable
private fun SortChip(
    label: String,
    active: Boolean,
    arrow: String?,
    compact: Boolean = false,
    onClick: () -> Unit
) {
    Row(
        modifier = Modifier
            .clip(RoundedCornerShape(2.dp))
            .background(if (active) Bronze else Color.Transparent)
            .border(1.dp, if (active) BronzeLight else BronzeDark, RoundedCornerShape(2.dp))
            .clickable { onClick() }
            // ~60% taller than the original 4dp: these are frequently-tapped controls sitting in a
            // 54dp strip that had spare vertical room, and the extra height also makes them a
            // comfortably bigger touch target on the small panel. Horizontal padding trimmed 8->6
            // to claw back width for the wider game-font labels; the vertical padding (which is
            // what makes the target comfortable) is untouched.
            // [compact] halves the vertical padding for the SPLIT column headers, where that height
            // is taken directly from the item grid — still a ~24dp touch target.
            .padding(horizontal = 6.dp, vertical = if (compact) 5.dp else 11.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            label.uppercase(),
            color = if (active) BoneBright else BoneMuted,
            fontSize = 10.sp,
            fontFamily = MwDisplay,
            fontWeight = FontWeight.Bold,
            letterSpacing = 0.8.sp,
            maxLines = 1
        )
        if (arrow != null) {
            Spacer(Modifier.width(3.dp))
            Text(arrow, color = BoneBright, fontSize = 8.sp, fontFamily = MwData)
        }
    }
}

/** A compact label-over-value readout for the equipped strip (Gold / Weight). */
@Composable
private fun StripStat(label: String, value: String) {
    // Label BESIDE the value, not stacked above it: the strip is 54dp tall but the sort controls
    // only need one line, so the stats were wasting the width they had and cramping the height.
    // Reading "GOLD 250" left-to-right is also closer to how the rest of the UI reads.
    Row(verticalAlignment = Alignment.CenterVertically) {
        Text(
            label,
            color = BoneDim,
            fontSize = 9.sp,
            fontFamily = MwDisplay,
            fontWeight = FontWeight.Bold,
            letterSpacing = 1.sp
        )
        Spacer(Modifier.width(5.dp))
        Text(
            value,
            color = BronzeLight,
            fontSize = 13.sp,
            fontFamily = MwData,
            fontWeight = FontWeight.Bold,
            maxLines = 1
        )
    }
}

/** The 1dp vertical divider used between segments of the equipped strip. */
@Composable
private fun StripDivider() {
    Box(
        Modifier
            .padding(horizontal = 10.dp)
            .width(1.dp)
            .height(28.dp)
            .background(BronzeDark)
    )
}

@Composable
private fun CategorySubTabs(
    categories: List<InvCategory>,
    selected: String?,
    hasEquipped: Boolean,
    onSelect: (String?) -> Unit
) {
    // Single horizontally-scrolling row, deliberately. A FlowRow that wrapped to two lines made
    // every tab reachable without scrolling, but the second line cost the item list below too much
    // vertical space on the 1240x1080 panel — squeezing the rows/cards more than the scrolling was
    // costing. Scrolling the tabs is the cheaper trade here.
    // Side effect of this shape: the nested horizontal scroller consumes drags that START on the
    // tab row, so categorySwipe only fires from the list body below.
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .horizontalScroll(rememberScrollState())
            .padding(horizontal = 8.dp, vertical = 6.dp),
        horizontalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        CategoryTab(label = "All", active = selected == null) { onSelect(null) }
        // "Equipped" filter — first after All, only when something is equipped.
        if (hasEquipped) {
            CategoryTab(label = EQUIPPED_FILTER, active = selected == EQUIPPED_FILTER) { onSelect(EQUIPPED_FILTER) }
        }
        categories.forEach { cat ->
            CategoryTab(label = cat.label, active = selected == cat.label) { onSelect(cat.label) }
        }
    }
}

/**
 * The horizontal category-filter strip shared by the looting and barter columns: an "All" tab
 * followed by one tab per present category, kept SCROLLED SO THE SELECTED TAB IS VISIBLE.
 *
 * WHY IT IS A LazyRow. These strips were `Row(horizontalScroll(...))`, which has no per-item layout
 * information and so nothing to scroll *to*. With the strip now long enough to overflow the ~260dp
 * split column (All + up to 8 categories), cycling the filter with L1/R1 walked the selection
 * straight off the edge and there was no way to see which filter was active. A LazyRow's
 * [LazyListState.layoutInfo] is exactly what [WindowedFocusScroll] needs, so this reuses that
 * helper rather than adding a second scroll-into-view mechanism — meaning the strip inherits the
 * same windowed behaviour as the item grids: no scroll at all while the selected tab is fully
 * visible, and otherwise a scroll by just the overhang, so tabs are never yanked to the left edge.
 *
 * [key] is the value compared against [selected] and handed to [onSelect] — the looting strip keys
 * tabs by their display label ([InvCategory.label]) while barter keys them by the engine's category
 * string ([BarterCat.cat]), which is the only difference between the three call sites.
 */
@Composable
private fun <T> CategoryTabStrip(
    tabs: List<T>,
    selected: String?,
    label: (T) -> String,
    key: (T) -> String,
    onSelect: (String?) -> Unit
) {
    val state = rememberLazyListState()
    // Index 0 is "All", so a real category sits at its position in [tabs] + 1. A selection that is
    // no longer present (its last item was taken/sold) resolves to 0 = All, which is also where the
    // list itself falls back to — so the strip and the filter agree rather than scrolling nowhere.
    val selectedIndex = if (selected == null) 0 else tabs.indexOfFirst { key(it) == selected } + 1
    // contentKey = tabs: re-run when the tab SET changes under an unchanged selection (a category
    // emptying out shifts every later tab's index), not just when the selection moves.
    WindowedFocusScroll(state, selectedIndex, tabs.size + 1, tabs)
    LazyRow(
        state = state,
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        item { CategoryTab("All", active = selected == null) { onSelect(null) } }
        items(tabs) { c -> CategoryTab(label(c), active = selected == key(c)) { onSelect(key(c)) } }
    }
}

@Composable
private fun CategoryTab(label: String, active: Boolean, onClick: () -> Unit) {
    Box(
        modifier = Modifier
            .clip(RoundedCornerShape(2.dp))
            .background(if (active) Bronze else Color.Transparent)
            .border(1.dp, if (active) BronzeLight else BronzeDark, RoundedCornerShape(2.dp))
            .clickable { onClick() }
            .padding(horizontal = 12.dp, vertical = 5.dp)
    ) {
        Text(
            label.uppercase(),
            color = if (active) StoneDark else Bone,
            fontSize = 12.sp,
            fontFamily = MwDisplay,
            fontWeight = if (active) FontWeight.Bold else FontWeight.Normal
        )
    }
}

@Composable
private fun InventoryItemList(
    state: GameState,
    selectedCategoryLabel: String?,
    cards: Boolean,
    hideEquippedBar: Boolean,
    showEquippedInList: Boolean,
    sortMode: InvSort = InvSort.DEFAULT,
    sortDescending: Boolean = true
) {
    val wornIds = remember(state.equipment) { state.equipment.values.toSet() }
    val equippedFilter = selectedCategoryLabel == EQUIPPED_FILTER
    val selectedGroup = INV_CATEGORIES.find { it.label == selectedCategoryLabel }
    // The bottom "Equipped" collapsible section (All view) starts collapsed, matching the barter
    // menu's Equipped drop-down.
    var equippedExpanded by remember { mutableStateOf(false) }

    if (state.inventory.isEmpty()) {
        EmptyPanel("No inventory recorded")
        return
    }

    // Match by per-stack instance id (stackId) when available; fall back to
    // recordId for items whose Lua side didn't emit a sid field.
    fun isWorn(item: InventoryItem): Boolean =
        if (item.stackId.isNotEmpty()) wornIds.contains(item.stackId)
        else wornIds.contains(item.id)

    // Favourited (gear) record ids — favourites float to the TOP of their category section.
    val favs by FavouritesRepository.state.collectAsState()
    val favIds = remember(favs) { favs.gear.mapNotNull { it?.id }.toSet() }

    // DEFAULT is the canonical three-tier order: category rank, then favourite-first, then name.
    //
    // Weight/Price are a PURE ordering — no category tier and no favourite tier. Choosing "heaviest
    // first" means the heaviest thing you own, not the heaviest thing in each category; a category
    // tier made the grid still look grouped by type. List mode keeps its headers regardless, because
    // that view iterates INV_CATEGORIES and filters per group — the headers come from the grouping,
    // not from this comparator — so dropping the tier sorts purely within each header, which is what
    // "sort within each category" should mean. (It also fixes categories whose members have
    // different ranks, e.g. Consumables, where potions used to sort ahead of every ingredient
    // regardless of weight.)
    //
    // Name is the final tiebreak in every mode so equal weights/prices don't shuffle between
    // recompositions.
    val catNameSort = remember(favIds, sortMode, sortDescending) {
        if (sortMode == InvSort.DEFAULT) {
            compareBy<InventoryItem> { itemCategoryRank(it.category) }
                .thenByDescending { it.id in favIds }
                .thenBy { it.displayName().lowercase() }
        } else {
            // Weight/Value go through the shared comparator (also used by looting + barter).
            invSortComparator(sortMode, sortDescending, { it.displayName() }, { it.weight }, { it.value })
        }
    }
    // Equipped items float to the front ONLY in the default order. With an explicit Weight/Price
    // sort the whole list must be in that order — a pinned block of worn gear at the top is exactly
    // the "it's not really sorted" problem the category tier caused.
    fun wornFirst(base: Comparator<InventoryItem>): Comparator<InventoryItem> =
        if (sortMode == InvSort.DEFAULT) compareByDescending<InventoryItem> { isWorn(it) }.then(base)
        else base
    // Key must include the sort inputs — catNameSort is rebuilt when they change, and without them
    // here the Equipped list/section would keep serving the previous ordering.
    val wornItems = remember(state.inventory, wornIds, favIds, sortMode, sortDescending) {
        state.inventory.filter { isWorn(it) }.sortedWith(catNameSort)
    }
    // Enchantment charge for cast-on-use items, sourced from the SPELLS export (the only place
    // per-item charge is carried — those items appear in the magic "Enchanted Items" section).
    // id -> (charge, maxCharge). Rendered in the condition column (those items have no durability).
    val chargeById = remember(state.spells) {
        state.spells.filter { it.maxCharge > 0 }.associate { it.id to (it.charge to it.maxCharge) }
    }

    Column(Modifier.fillMaxSize()) {
        if (cards) {
            // CARDS: a fixed-row horizontal grid, filled column-major (top-to-bottom then
            // left-to-right) using the SAME canonical sort. The "All" view flattens the categories
            // into one sorted sequence (the sort already groups categories) — no per-category headers
            // (they don't fit a fixed-row horizontal grid); worn items move to the pinned section.
            val gridItems = when {
                equippedFilter -> wornItems
                // "All": worn items are listed inline only when the user opts in (showEquippedInList),
                // and then float to the FRONT (worn-first, like the container player-inventory view);
                // otherwise they're reached via the bar and/or the Equipped tab.
                selectedGroup == null ->
                    state.inventory.filter { showEquippedInList || !isWorn(it) }
                        .sortedWith(
                            if (showEquippedInList) wornFirst(catNameSort) else catNameSort
                        )
                else ->
                    state.inventory.filter { it.category in selectedGroup.cats }
                        .sortedWith(wornFirst(catNameSort))
            }
            ItemCardGrid(
                items = gridItems,
                isWorn = { isWorn(it) },
                forceHighlight = equippedFilter,
                chargeById = chargeById,
                // ALWAYS 4 rows. Hiding the Equipped bar used to buy a 5th row; instead that freed
                // height now goes into taller (and, via the card's own scaling, proportionally
                // wider) cards — see the INV_CARD_* geometry block.
                rows = INV_CARD_ROWS,
                modifier = Modifier.weight(1f).fillMaxWidth().padding(horizontal = 4.dp, vertical = 2.dp)
            )
        } else {
            // LIST: full-width rows, category section headers in the "All" view (unchanged).
            LazyColumn(modifier = Modifier.weight(1f).fillMaxWidth().padding(horizontal = 4.dp)) {
                when {
                    // "Equipped" filter — a flat list of just the worn items, each with the highlight outline.
                    equippedFilter -> {
                        items(wornItems, key = { "eqf_" + it.stackId.ifEmpty { it.id } }) { item ->
                            ItemRow(item, worn = true, equippable = item.isEquippable(),
                                usable = item.isUsable(), readable = item.isReadable(),
                                highlight = true, iconBitmap = rememberItemIcon(item.icon),
                                enchantCharge = chargeById[item.id])
                        }
                    }
                    // "All" — category groups. Worn items are listed inline (highlighted) only when the
                    // user opts in (showEquippedInList); otherwise only the UNWORN items appear here and
                    // worn items are reached via the bar / Equipped tab. When showEquippedInList is off
                    // every item here is unworn → worn/highlight are false, identical to the original.
                    selectedGroup == null -> {
                        INV_CATEGORIES.forEach { grp ->
                            val groupItems = state.inventory
                                .filter { it.category in grp.cats && (showEquippedInList || !isWorn(it)) }
                                // Worn items float to the front of their category group when shown inline.
                                .sortedWith(
                                    if (showEquippedInList) wornFirst(catNameSort) else catNameSort
                                )
                            if (groupItems.isNotEmpty()) {
                                item(key = "hdr_${grp.label}") { SpellSectionHeader(grp.label) }
                                items(groupItems) { item ->
                                    val worn = isWorn(item)
                                    ItemRow(item, worn = worn, equippable = item.isEquippable(),
                                        usable = item.isUsable(), readable = item.isReadable(),
                                        highlight = worn, iconBitmap = rememberItemIcon(item.icon),
                                        enchantCharge = chargeById[item.id])
                                }
                            }
                        }
                    }
                    // Single category — that category's items, worn first; worn rows get the highlight.
                    else -> {
                        val groupItems = state.inventory
                            .filter { it.category in selectedGroup.cats }
                            .sortedWith(wornFirst(catNameSort))
                        items(groupItems) { item ->
                            val worn = isWorn(item)
                            ItemRow(item, worn, equippable = item.isEquippable(),
                                usable = item.isUsable(), readable = item.isReadable(),
                                highlight = worn, iconBitmap = rememberItemIcon(item.icon),
                                enchantCharge = chargeById[item.id])
                        }
                    }
                }
                item { Spacer(Modifier.height(4.dp)) }
            }
        }

        // Equipped drop-down — pinned to the bottom (always visible), dashed outline, matching the
        // barter Equipped section. Only in the "All" view (the Equipped filter already shows just
        // worn items; a single category shows its own worn items inline). Renders its worn items as
        // cards or rows to match the active layout. Suppressed entirely when the user hides the bar
        // (worn items are then reachable via the Equipped tab, or inline if that option is on).
        if (!hideEquippedBar && selectedGroup == null && !equippedFilter && wornItems.isNotEmpty()) {
            InventoryEquippedSection(wornItems, chargeById, equippedExpanded, cards) { equippedExpanded = !equippedExpanded }
        }
    }
}

/** A fixed-row horizontal grid of condensed [ItemCard]s + the shared [HorizontalGridScrollbar]. Fill
 *  order is column-major (top-to-bottom, then left-to-right) — same as the SPLIT loot/barter grids —
 *  so the caller's canonical sort reads down each column. [modifier] must bound the height (the main
 *  list passes weight(1f); the equipped section passes a fixed height). */
@Composable
private fun ItemCardGrid(
    items: List<InventoryItem>,
    isWorn: (InventoryItem) -> Boolean,
    forceHighlight: Boolean,
    chargeById: Map<String, Pair<Int, Int>>,
    rows: Int = INV_CARD_ROWS,
    modifier: Modifier = Modifier
) {
    val gridState = rememberLazyGridState()
    Column(modifier) {
        LazyHorizontalGrid(
            state = gridState,
            rows = GridCells.Fixed(rows),
            modifier = Modifier.fillMaxWidth().weight(1f),
            horizontalArrangement = Arrangement.spacedBy(6.dp),
            verticalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            gridItemsIndexed(items) { _, item ->
                val worn = isWorn(item)
                ItemCard(
                    item, worn = worn, equippable = item.isEquippable(),
                    usable = item.isUsable(), readable = item.isReadable(),
                    highlight = forceHighlight || worn,
                    iconBitmap = rememberItemIcon(item.icon),
                    enchantCharge = chargeById[item.id]
                )
            }
        }
        HorizontalGridScrollbar(gridState, Modifier.padding(top = 4.dp))
    }
}

/** Pinned, dashed-outline "Equipped (N)" drop-down for the bottom of the inventory list — same
 *  styling + always-at-the-bottom placement as the barter menu's [EquippedSection]. Collapsed by
 *  default; when expanded, the worn rows scroll internally (capped height) so the section can't eat
 *  the whole panel. */
@Composable
private fun InventoryEquippedSection(
    items: List<InventoryItem>,
    chargeById: Map<String, Pair<Int, Int>>,
    expanded: Boolean,
    cards: Boolean,
    onToggle: () -> Unit
) {
    val dash = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(6f, 4f))
    // Cards mode uses HALF the bar's vertical padding, freeing height for the (fixed-row) grid so
    // cards render slightly larger; List mode keeps the original padding.
    val outerV = if (cards) 2.dp else 4.dp
    val innerV = if (cards) 3.dp else 6.dp
    val barV = if (cards) 3.dp else 6.dp
    Column(
        Modifier
            .fillMaxWidth()
            .padding(top = outerV, start = 4.dp, end = 4.dp, bottom = outerV)
            .drawBehind {
                drawRoundRect(
                    color = BronzeDark,
                    style = androidx.compose.ui.graphics.drawscope.Stroke(width = 1.dp.toPx(), pathEffect = dash),
                    cornerRadius = androidx.compose.ui.geometry.CornerRadius(4.dp.toPx())
                )
            }
            .padding(horizontal = 6.dp, vertical = innerV)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .clickable { onToggle() }
                .padding(horizontal = 6.dp, vertical = barV),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                "Equipped (${items.size})",
                color = BoneMuted, fontSize = 16.sp,            // ~50% larger font (was 11)
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold, letterSpacing = 0.5.sp
            )
            Spacer(Modifier.weight(1f))
            Text(if (expanded) "▾" else "▸", color = BronzeLight, fontSize = 18.sp, fontFamily = MwDisplay)
        }
        if (expanded) {
            Spacer(Modifier.height(3.dp))
            if (cards) {
                // Same condensed-card grid as the main list, bounded to the worn item count (up to
                // the full row height) so the section stays compact.
                val rows = items.size.coerceIn(1, INV_CARD_ROWS)
                ItemCardGrid(
                    items = items,
                    isWorn = { true },
                    forceHighlight = true,
                    chargeById = chargeById,
                    rows = rows,
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(INV_CARD_HEIGHT * rows + 6.dp * (rows - 1) + 12.dp)
                )
            } else {
                Column(
                    Modifier
                        .fillMaxWidth()
                        .heightIn(max = 220.dp)
                        .verticalScroll(rememberScrollState())
                ) {
                    items.forEach { item ->
                        ItemRow(item, worn = true, equippable = item.isEquippable(),
                            usable = item.isUsable(), readable = item.isReadable(),
                            highlight = true, iconBitmap = rememberItemIcon(item.icon),
                            enchantCharge = chargeById[item.id])
                    }
                }
            }
        }
    }
}

// Lazily extracts + caches an item icon from the OpenMW VFS (BSA / loose files)
// and returns it as an ImageBitmap, or null while loading / on failure (in which
// case the caller shows the empty placeholder box). Cache key is the icon path,
// which is shared by every instance of the same record — icons never change, so a
// PNG is written to cacheDir/item_icons once and reloaded from disk thereafter.
// Safe to call from inside a LazyColumn item: LaunchedEffect cancels/restarts as
// rows recycle, and the actual extract/decode runs on Dispatchers.IO.
@Composable
private fun rememberItemIcon(iconPath: String): ImageBitmap? {
    val context = LocalContext.current
    var bitmap by remember(iconPath) { mutableStateOf<ImageBitmap?>(null) }
    LaunchedEffect(iconPath) {
        if (iconPath.isEmpty()) return@LaunchedEffect
        val cacheDir = File(context.cacheDir, "item_icons").apply { mkdirs() }
        val cacheFile = File(cacheDir, iconPath.replace('\\', '_').replace('/', '_') + ".png")
        // Bounded retry: exportIconToPng needs the engine's ResourceSystem, which may not be ready
        // yet when an icon on the default HUD tab (the compass) first composes at launch / save-load.
        // A single early failure used to be permanent (LaunchedEffect(iconPath) never re-runs); now
        // we retry until it succeeds. A genuinely-missing texture just exhausts the retries and the
        // caller shows its placeholder/fallback (same end state as before, only delayed).
        var attempt = 0
        while (true) {
            val decoded = withContext(Dispatchers.IO) {
                if (!cacheFile.exists()) {
                    CompanionActions.exportIconToPng(iconPath, cacheFile.absolutePath)
                }
                if (!cacheFile.exists()) return@withContext null
                val rawBitmap = BitmapFactory.decodeFile(cacheFile.absolutePath)
                if (rawBitmap == null) {
                    cacheFile.delete()  // corrupt/partial write — let the next attempt re-extract
                    return@withContext null
                }
                // Flip vertically: OpenGL row 0 = bottom, Android bitmap row 0 = top, so exported
                // icon PNGs come out upside-down (same as the minimap flip in GameStateRepository).
                val flipMatrix = Matrix().apply { preScale(1f, -1f) }
                val flipped = Bitmap.createBitmap(
                    rawBitmap, 0, 0, rawBitmap.width, rawBitmap.height, flipMatrix, false
                )
                rawBitmap.recycle()
                flipped.asImageBitmap()
            }
            if (decoded != null) {
                bitmap = decoded
                return@LaunchedEffect
            }
            attempt++
            if (attempt >= 12) return@LaunchedEffect
            delay(500L)
        }
    }
    return bitmap
}

/** Compact item weight for the inventory row: whole numbers drop the decimal (8.0 → "8"),
 *  otherwise one decimal (0.5 → "0.5"). */
private fun fmtWeight(w: Float): String =
    if (w == w.toInt().toFloat()) w.toInt().toString() else String.format("%.1f", w)

/* ---- Shared inventory-item building blocks ---- */
// These are the exact stat/icon/menu widgets lifted verbatim out of ItemRow so the new Cards
// layout renders every stat identically to the List. Called from BOTH ItemRow (List — output
// unchanged) and ItemCard (Cards). Only the size/width params differ between call sites.

/** Icon box (icon + enchant backdrop + ×N count badge), lifted from ItemRow. */
@Composable
private fun ItemIconBox(
    item: InventoryItem,
    iconBitmap: ImageBitmap?,
    size: Dp = 40.dp,
    badgeFontSize: TextUnit = 9.sp
) {
    Box(
        modifier = Modifier
            .size(size)
            .clip(RoundedCornerShape(2.dp))
            .background(SlotBg)
            .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
    ) {
        EnchantBackdrop(item.enchant != null)
        if (iconBitmap != null) {
            Image(
                bitmap = iconBitmap,
                contentDescription = null,
                contentScale = ContentScale.Fit,
                modifier = Modifier.fillMaxSize()
            )
        }
        // Stack quantity badge on the icon corner (matches the loot/barter shelf cells).
        if (item.count > 1) {
            Text(
                "×${item.count}",
                color = BoneBright, fontSize = badgeFontSize,
                fontFamily = MwData, fontWeight = FontWeight.Bold,
                modifier = Modifier
                    .align(Alignment.BottomEnd)
                    .background(Color(0xCC0E0B07))
                    .padding(horizontal = 2.dp)
            )
        }
    }
}

/** Stat column (weapon damage / armor rating / etc.), lifted from ItemRow.
 *  [width] null → wrap content (Cards); a fixed Dp → the List's aligned fixed-width slot.
 *  [cardStyle] false (List) → value over a tiny key, right-aligned. [cardStyle] true (Cards) → the
 *  KEY on top and the value below, centred under it (matches the COND/CHARGE label-over-bar style). */
@Composable
private fun ItemStatColumn(statVal: String, statKey: String, width: Dp? = 66.dp, cardStyle: Boolean = false) {
    Box(
        if (width != null) Modifier.width(width) else Modifier,
        contentAlignment = if (cardStyle) Alignment.Center else Alignment.CenterEnd
    ) {
        if (statVal.isNotEmpty()) {
            if (cardStyle) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    if (statKey.isNotEmpty()) {
                        Text(
                            statKey,
                            color = BoneDim,
                            fontSize = 8.sp,
                            fontFamily = MwBody,
                            letterSpacing = 0.5.sp,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                    Text(
                        statVal,
                        color = BronzeLight,
                        fontSize = 11.sp,
                        fontFamily = MwData,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
            } else {
                Column(horizontalAlignment = Alignment.End) {
                    Text(
                        statVal,
                        color = BronzeLight,
                        fontSize = 11.sp,
                        fontFamily = MwData,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                    if (statKey.isNotEmpty()) {
                        Text(
                            statKey,
                            color = BoneDim,
                            fontSize = 8.sp,
                            fontFamily = MwBody,
                            letterSpacing = 0.5.sp,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                }
            }
        }
    }
}

/** Weight column, lifted from ItemRow. Hidden for weightless items (gold = 0).
 *  [width] null → wrap content (Cards); a fixed Dp → the List's aligned fixed-width slot.
 *  [cardStyle] false (List) → value over "WT", right-aligned. [cardStyle] true (Cards) → "WT" on top
 *  and the value below, centred under it. */
@Composable
private fun ItemWeightColumn(weight: Float, width: Dp? = 44.dp, cardStyle: Boolean = false) {
    Box(
        if (width != null) Modifier.width(width) else Modifier,
        contentAlignment = if (cardStyle) Alignment.Center else Alignment.CenterEnd
    ) {
        if (weight > 0f) {
            if (cardStyle) {
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    Text(
                        "WT",
                        color = BoneDim,
                        fontSize = 8.sp,
                        fontFamily = MwBody,
                        letterSpacing = 0.5.sp,
                        maxLines = 1
                    )
                    Text(
                        fmtWeight(weight),
                        color = BronzeLight,
                        fontSize = 11.sp,
                        fontFamily = MwData,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
            } else {
                Column(horizontalAlignment = Alignment.End) {
                    Text(
                        fmtWeight(weight),
                        color = BronzeLight,
                        fontSize = 11.sp,
                        fontFamily = MwData,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                    Text(
                        "WT",
                        color = BoneDim,
                        fontSize = 8.sp,
                        fontFamily = MwBody,
                        letterSpacing = 0.5.sp,
                        maxLines = 1
                    )
                }
            }
        }
    }
}

/** Condition OR (for a cast-on-use enchanted item) charge column — same bar widget, lifted from
 *  ItemRow. Charge takes priority when present (those items have no durability, so no conflict). */
@Composable
private fun ItemConditionColumn(cond: Float?, enchantCharge: Pair<Int, Int>?, width: Dp = 50.dp) {
    Box(Modifier.width(width), contentAlignment = Alignment.Center) {
        val chargePair = enchantCharge?.takeIf { it.second > 0 }
        when {
            chargePair != null -> {
                val (cur, max) = chargePair
                val ratio = (cur.toFloat() / max).coerceIn(0f, 1f)
                val fillColor = if (ratio >= 0.5f) BronzeLight else Color(0xFFC75C5C)
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    Text(
                        "CHARGE",
                        color = BoneDim,
                        fontSize = 7.sp,
                        fontFamily = MwBody,
                        letterSpacing = 0.5.sp
                    )
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(4.dp)
                            .clip(RoundedCornerShape(1.dp))
                            .background(Color(0xFF0E0B07))
                            .border(1.dp, BronzeDark, RoundedCornerShape(1.dp))
                    ) {
                        Box(
                            Modifier
                                .fillMaxWidth(ratio)
                                .fillMaxHeight()
                                .background(fillColor)
                        )
                    }
                }
            }
            cond != null -> {
                val fillColor = if (cond >= 0.5f) BronzeLight else Color(0xFFC75C5C)
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    Text(
                        "COND",
                        color = BoneDim,
                        fontSize = 7.sp,
                        fontFamily = MwBody,
                        letterSpacing = 0.5.sp
                    )
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(4.dp)
                            .clip(RoundedCornerShape(1.dp))
                            .background(Color(0xFF0E0B07))
                            .border(1.dp, BronzeDark, RoundedCornerShape(1.dp))
                    ) {
                        Box(
                            Modifier
                                .fillMaxWidth(cond.coerceIn(0f, 1f))
                                .fillMaxHeight()
                                .background(fillColor)
                        )
                    }
                }
            }
        }
    }
}

/** The primary tap action for an inventory item (read / use / equip / unequip). Shared by the
 *  List row and the Cards cell so a tap behaves identically in both. */
private fun itemPrimaryAction(
    item: InventoryItem,
    worn: Boolean,
    equippable: Boolean,
    usable: Boolean,
    readable: Boolean
) {
    val target = item.stackId.ifEmpty { item.id }
    when {
        readable -> CompanionActions.readItem(item.id)
        usable -> CompanionActions.useItem(item.id)
        equippable && worn -> CompanionActions.unequipItem(target)
        equippable -> CompanionActions.equipItem(target)
    }
}

/** The long-press context menu for an inventory item (Equip/Unequip, Read, Use, Info, Drop,
 *  Favourite), lifted verbatim from ItemRow so List and Cards share one identical menu. */
@Composable
private fun ItemContextMenu(
    item: InventoryItem,
    worn: Boolean,
    equippable: Boolean,
    usable: Boolean,
    readable: Boolean,
    expanded: Boolean,
    onDismiss: () -> Unit
) {
    val context = LocalContext.current
    val label = item.displayName()
    CompanionDropdownMenu(
        expanded = expanded,
        onDismissRequest = { onDismiss() }
    ) {
        Text(
            label,
            color = BronzeLight,
            fontSize = 12.sp,
            fontFamily = MwDisplay,
            fontWeight = FontWeight.Bold,
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp)
        )
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
        val menuItemColors = MenuDefaults.itemColors(textColor = Bone)
        if (worn || equippable) {
            DropdownMenuItem(
                text = { Text(if (worn) "Unequip" else "Equip", fontFamily = MwBody, fontSize = 13.sp) },
                onClick = {
                    onDismiss()
                    val target = item.stackId.ifEmpty { item.id }
                    if (worn) CompanionActions.unequipItem(target)
                    else CompanionActions.equipItem(target)
                },
                colors = menuItemColors
            )
        }
        if (readable) {
            DropdownMenuItem(
                text = { Text("Read", fontFamily = MwBody, fontSize = 13.sp) },
                onClick = { onDismiss(); CompanionActions.readItem(item.id) },
                colors = menuItemColors
            )
        }
        if (usable) {
            DropdownMenuItem(
                text = { Text(item.useVerb(), fontFamily = MwBody, fontSize = 13.sp) },
                onClick = { onDismiss(); CompanionActions.useItem(item.id) },
                colors = menuItemColors
            )
        }
        DropdownMenuItem(
            text = { Text("Info", fontFamily = MwBody, fontSize = 13.sp) },
            onClick = { onDismiss(); ItemInfoPopupState.open(item.id, item.name, item.enchant) },
            colors = menuItemColors
        )
        DropdownMenuItem(
            text = { Text("Drop", fontFamily = MwBody, fontSize = 13.sp) },
            onClick = {
                onDismiss()
                // count > 1 → ask how many; count == 1 drops immediately. Inventory is a plain TAB,
                // not a DS session overlay, so controller nav isn't routed here — no "[Y]" hint.
                QuantityRequestState.requestOrRun(
                    label, item.count, "Drop", showControllerHint = false
                ) { n ->
                    CompanionActions.dropItem(item.id, n)
                }
            },
            colors = menuItemColors
        )
        // Add to favourites / Unfavourite / replace-slot picker.
        FavouriteMenuItems(
            context = context,
            isGear = true,
            itemId = item.id,
            makeSlot = { FavSlot(item.id, label) },
            onDone = { onDismiss() }
        )
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun ItemRow(
    item: InventoryItem,
    worn: Boolean,
    equippable: Boolean,
    usable: Boolean = false,
    readable: Boolean,
    highlight: Boolean = false,   // slight outline around equipped items (the Equipped section/filter)
    iconBitmap: ImageBitmap? = null,
    // (charge, maxCharge) for a cast-on-use enchanted item; null = not charge-bearing. Shown in the
    // condition column (those items have no durability). Same bar style as the spells tab.
    enchantCharge: Pair<Int, Int>? = null
) {
    var menuOpen by remember { mutableStateOf(false) }
    LaunchedEffect(DropdownState.closeRequest) {
        if (DropdownState.closeRequest > 0) menuOpen = false
    }
    val label = item.displayName()
    val favs by FavouritesRepository.state.collectAsState()
    val isFav = favs.gear.any { it?.id == item.id }

    Box(modifier = Modifier.onGloballyPositioned { ItemInfoPopupState.reportAnchor(item.id, it.boundsInRoot()) }) {
        Column {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .then(
                        if (highlight) Modifier
                            .clip(RoundedCornerShape(3.dp))
                            .background(BronzeLight.copy(alpha = 0.06f))
                            .border(1.dp, BronzeLight, RoundedCornerShape(3.dp))
                        else Modifier
                    )
                    .combinedClickable(
                        onClick = { itemPrimaryAction(item, worn, equippable, usable, readable) },
                        onLongClick = { menuOpen = true; DropdownState.open() }
                    )
                    .padding(start = 14.dp, end = 10.dp, top = 11.dp, bottom = 11.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Icon box (leftmost). Placeholder empty slot until the icon
                // pipeline loads real DDS textures; drop in a real bitmap by
                // passing iconBitmap non-null at the call site.
                ItemIconBox(item, iconBitmap)
                Spacer(Modifier.width(10.dp))
                // Name + (optional) favourite star share the flex column so the
                // name truncates before the star, and the star stays a standalone
                // Icon — never concatenated into the name string.
                Row(
                    modifier = Modifier.weight(1f).padding(end = 12.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        label,
                        color = if (worn) BoneBright else BoneMuted,
                        fontSize = 14.sp,
                        fontFamily = MwBody,
                        fontWeight = FontWeight.Normal,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.weight(1f, fill = false)
                    )
                    if (isFav) {
                        Spacer(Modifier.width(4.dp))
                        FavStar()
                    }
                }
                // Trailing columns are fixed-width slots (empty when N/A) so the stat value, weight
                // and condition bar always sit in the same horizontal position across every row
                // (right-aligned; the flex name column pushes them to the right edge).
                ItemStatColumn(item.statVal, item.statKey)
                Spacer(Modifier.width(12.dp))
                ItemWeightColumn(item.weight)
                Spacer(Modifier.width(16.dp))
                ItemConditionColumn(item.cond, enchantCharge)
                // No "WORN" text column — equipped items are shown by the highlight outline + the
                // bottom Equipped section, so the stat/weight/condition columns fill the space.
            }
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
        }

        ItemContextMenu(
            item = item, worn = worn, equippable = equippable, usable = usable, readable = readable,
            expanded = menuOpen,
            onDismiss = { menuOpen = false; DropdownState.closeAll() }
        )
    }
}

/* ---- Inventory Cards layout (condensed card grid, horizontal scroll) ---- */

// Card grid geometry, tuned for the 1240×1080 / 3.92" bottom screen (~473×412 dp, density ~2.62):
// a fixed 4-row horizontal grid renders wide+short cards. The FIXED row count (over the grid's
// bounded height) is what keeps every card a uniform height regardless of name/stat content — each
// card fills its evenly-divided grid cell.
//
// [INV_CARD_ROWS] is ALWAYS 4 (Aug 2026). It used to be bumped to 5 whenever the Equipped bar was
// hidden — which, since that pref defaults to hidden, meant 5 was what most players actually saw.
// The freed height now makes the CARDS bigger instead of adding a row.
//
// The numbers below (width, icon size, font sizes, paddings — including the ones inside the shared
// stat widgets) are all authored against [INV_CARD_HEIGHT] as the REFERENCE cell height. [ItemCard]
// measures the height its grid cell actually hands it and scales everything by
// `cellHeight / INV_CARD_HEIGHT` through a scaled [LocalDensity], so the card keeps its exact shape
// at whatever size the row division produces — taller cell ⇒ proportionally wider card with
// proportionally larger icon and text, no distortion and no hand-tuned second set of dimensions.
// That also self-corrects for the two different grid heights (Equipped bar shown vs hidden) and for
// the bounded-height equipped-section grid, which sizes its own rows from INV_CARD_HEIGHT directly.
private val INV_CARD_WIDTH = 214.dp
private val INV_CARD_HEIGHT = 54.dp
private const val INV_CARD_ROWS = 4
// Sanity rails on the derived scale, so an unexpected constraint can never produce an absurd card.
private const val INV_CARD_MIN_SCALE = 0.85f
private const val INV_CARD_MAX_SCALE = 1.6f
// Fixed widths for the card's stat cluster (right-aligned), so weight + condition/charge always sit
// in the same spot and the stat/effect column (widest; long effect names truncate) is left of them.
private val INV_CARD_STAT_W = 74.dp
private val INV_CARD_WT_W = 30.dp
private val INV_CARD_COND_W = 42.dp

/** A single-line item name that shrinks 13sp → 11sp before ellipsis-truncating, staying within the
 *  card's fixed name width. Mirrors the CornerNameLabel onTextLayout measure trick: render at the
 *  larger size, and if it overflows, drop to the smaller size (which then ellipsis-truncates). */
@Composable
private fun AutoShrinkItemName(text: String, color: Color, modifier: Modifier = Modifier) {
    // Two-stage: try 13sp; on visual overflow, fall back to 11sp (still single-line, ellipsis).
    var shrink by remember(text) { mutableStateOf(false) }
    Text(
        text,
        color = color,
        fontSize = if (shrink) 11.sp else 13.sp,
        fontFamily = MwBody,
        fontWeight = FontWeight.Normal,
        maxLines = 1,
        overflow = TextOverflow.Ellipsis,
        onTextLayout = { result ->
            // Only step down once (13 → 11); at 11sp we keep the ellipsis rather than shrinking further.
            if (!shrink && result.hasVisualOverflow) shrink = true
        },
        modifier = modifier
    )
}

/** One condensed inventory card: icon on the left, name over a compact stat row on the right. Reuses
 *  the exact List stat/menu widgets (ItemIconBox / ItemStatColumn / ItemWeightColumn /
 *  ItemConditionColumn / ItemContextMenu) — same data, same visuals, repackaged. Fixed size so the
 *  grid stays uniform. Tap / long-press behave identically to [ItemRow]. */
@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun ItemCard(
    item: InventoryItem,
    worn: Boolean,
    equippable: Boolean,
    usable: Boolean = false,
    readable: Boolean,
    highlight: Boolean = false,
    iconBitmap: ImageBitmap? = null,
    enchantCharge: Pair<Int, Int>? = null
) {
    var menuOpen by remember { mutableStateOf(false) }
    LaunchedEffect(DropdownState.closeRequest) {
        if (DropdownState.closeRequest > 0) menuOpen = false
    }
    val favs by FavouritesRepository.state.collectAsState()
    val isFav = favs.gear.any { it?.id == item.id }

    BoxWithConstraints(
        modifier = Modifier.onGloballyPositioned { ItemInfoPopupState.reportAnchor(item.id, it.boundsInRoot()) }
    ) {
        // UNIFORM SCALE (see the INV_CARD_* geometry block). The grid hands every cell a FIXED
        // height, so maxHeight here IS the card height; everything inside is authored against
        // INV_CARD_HEIGHT. Scaling LocalDensity — rather than multiplying each dimension by hand —
        // scales dp AND sp together, so the width, icon, paddings, name and the shared
        // ItemStatColumn/ItemWeightColumn/ItemConditionColumn internals all grow by exactly the same
        // factor. The card's shape and its internal proportions are therefore identical at any size,
        // and the List style (which uses those same shared widgets outside this provider) is
        // completely untouched.
        val base = LocalDensity.current
        val scale = if (constraints.hasBoundedHeight)
            (maxHeight / INV_CARD_HEIGHT).coerceIn(INV_CARD_MIN_SCALE, INV_CARD_MAX_SCALE) else 1f
        CompositionLocalProvider(
            LocalDensity provides Density(base.density * scale, base.fontScale)
        ) {
            // Plain Box so the fav-star overlay still has a BoxScope to align within (the
            // provider's content lambda drops BoxWithConstraints' own scope).
            Box {
                Row(
                    modifier = Modifier
                        .width(INV_CARD_WIDTH)
                        // Height comes from the grid's fixed-row division (uniform across all
                        // cards); fill it.
                        .fillMaxHeight()
                        .clip(RoundedCornerShape(3.dp))
                        // Equipped items get the same faint fill + BronzeLight outline as the List
                        // highlight; otherwise a plain slot panel so cards read as discrete tiles.
                        .background(if (highlight) BronzeLight.copy(alpha = 0.06f) else StoneDark)
                        .border(1.dp, if (highlight) BronzeLight else BronzeDark, RoundedCornerShape(3.dp))
                        .combinedClickable(
                            onClick = { itemPrimaryAction(item, worn, equippable, usable, readable) },
                            onLongClick = { menuOpen = true; DropdownState.open() }
                        )
                        .padding(horizontal = 6.dp, vertical = 4.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    ItemIconBox(item, iconBitmap, size = 34.dp, badgeFontSize = 8.sp)
                    Spacer(Modifier.width(6.dp))
                    // Right side: name over a compact stat row. The favourite star is a corner
                    // overlay (below) rather than inline, so it never steals width from the name.
                    Column(Modifier.weight(1f), verticalArrangement = Arrangement.Center) {
                        AutoShrinkItemName(
                            item.displayName(),
                            color = if (worn) BoneBright else BoneMuted,
                            modifier = Modifier.fillMaxWidth()
                        )
                        Spacer(Modifier.height(2.dp))
                        // Compact stat row: the same stat / condition-charge / weight widgets as the
                        // List, in cardStyle (label on TOP, value centred beneath). FIXED widths +
                        // right-aligned so every section sits in the SAME position on every card
                        // regardless of which are populated or how long an effect name is. WEIGHT is
                        // far right (every item has weight), condition/charge next, then the stat/
                        // effect column (widest, long effect names ellipsis-truncate within it).
                        // Empty sections still occupy their slot, keeping the others aligned.
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(4.dp, Alignment.End),
                            verticalAlignment = Alignment.Top
                        ) {
                            ItemStatColumn(item.statVal, item.statKey, width = INV_CARD_STAT_W, cardStyle = true)
                            ItemConditionColumn(item.cond, enchantCharge, width = INV_CARD_COND_W)
                            ItemWeightColumn(item.weight, width = INV_CARD_WT_W, cardStyle = true)
                        }
                    }
                }

                // Favourite star, top-right corner of the card box (overlay, not inline with the name).
                if (isFav) {
                    Box(Modifier.align(Alignment.TopEnd).padding(top = 3.dp, end = 3.dp)) { FavStar() }
                }

                ItemContextMenu(
                    item = item, worn = worn, equippable = equippable, usable = usable, readable = readable,
                    expanded = menuOpen,
                    onDismiss = { menuOpen = false; DropdownState.closeAll() }
                )
            }
        }
    }
}

/* ---- Magic (list of spells) ---- */

@Composable
private fun SpellSectionHeader(title: String) {
    Column {
        Text(
            title,
            color = BronzeLight, fontSize = 13.sp,
            fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
            modifier = Modifier.padding(start = 6.dp, top = 8.dp, bottom = 4.dp)
        )
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
    }
}

@Composable
private fun MagicPanel(state: GameState) {
    val sel = state.selectedSpell
    // Success chance per learned spell, joined by id at render time. Its own flow rather than a
    // field on SpellEntry because it is dynamic (fatigue term, and 0 when magicka is short) while
    // the rest of a spell row is static — see GameStateRepository.spellChances.
    val spellChances by GameStateRepository.spellChances.collectAsState()
    // The spell list is always the compact layout now (the Standard/Compact toggle was removed).

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(top = 12.dp, bottom = BOTTOM_BAR_SPACE.dp, start = 12.dp, end = 12.dp),
        verticalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        // ---- Active spell panel ----
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(TOP_BOX_HEIGHT)
                .mwPanel()
                .padding(horizontal = 14.dp),
            contentAlignment = Alignment.CenterStart
        ) {
            if (sel != null) {
                val selName = state.spells.find { it.id == sel }?.displayName() ?: prettify(sel)

                Column {
                    Text(
                        "Active Spell",
                        color = BronzeLight, fontSize = 10.sp,
                        fontFamily = MwDisplay, fontWeight = FontWeight.Bold
                    )
                    Spacer(Modifier.height(3.dp))
                    Text(
                        selName,
                        color = Bone, fontSize = 18.sp,
                        fontFamily = MwBody, fontWeight = FontWeight.SemiBold,
                        maxLines = 1, overflow = TextOverflow.Ellipsis
                    )
                }
            } else {
                Text(
                    "No spell selected",
                    color = BoneDim, fontSize = 14.sp,
                    fontFamily = MwBody
                )
            }
        }

        // ---- Spell list panel ----
        if (state.spells.isEmpty()) {
            EmptyPanel("No spells known")
        } else {
            // Selected/equipped entry first, then the rest alphabetically.
            val bySelectionThenName = compareByDescending<SpellEntry> { it.id == sel }
                .thenBy { it.id.lowercase() }
            val powers = remember(state.spells, sel) {
                state.spells.filter { it.type == "power" }.sortedWith(bySelectionThenName)
            }
            val spells = remember(state.spells, sel) {
                state.spells.filter { it.type == "spell" }.sortedWith(bySelectionThenName)
            }
            val scrolls = remember(state.spells, sel) {
                state.spells.filter { it.type == "scroll" && !it.isItem }.sortedWith(bySelectionThenName)
            }
            // Cast-on-use enchanted items (rings/amulets/clothing/weapons). They
            // arrive with type "scroll" but carry isItem=true; broken out into
            // their own section.
            val enchantedItems = remember(state.spells, sel) {
                state.spells.filter { it.isItem }.sortedWith(bySelectionThenName)
            }
            // Scroll/enchanted-item rows carry an ITEM recordId, not a spell id, so their Info
            // must go through the item path (CMP:info item:) and can show the enchant section
            // instantly from the matching inventory entry — same as InventoryPanel's Info.
            val enchantByRecordId = remember(state.inventory) {
                state.inventory.associate { it.id to it.enchant }
            }

            // Category filter tabs — only present (non-empty) categories get a tab.
            // ALL is always shown. Mirrors InventoryPanel's CategorySubTabs pattern.
            var selectedMagicTab by remember { mutableStateOf("ALL") }
            val presentMagicTabs = remember(powers, spells, scrolls, enchantedItems) {
                buildList {
                    if (powers.isNotEmpty()) add("POWERS")
                    if (spells.isNotEmpty()) add("SPELLS")
                    if (scrolls.isNotEmpty()) add("SCROLLS")
                    if (enchantedItems.isNotEmpty()) add("ITEMS")
                }
            }
            // Reset to ALL if the selected category became empty (spells removed mid-game).
            LaunchedEffect(presentMagicTabs) {
                if (selectedMagicTab != "ALL" && selectedMagicTab !in presentMagicTabs) {
                    selectedMagicTab = "ALL"
                }
            }

            val showPowers = selectedMagicTab == "ALL" || selectedMagicTab == "POWERS"
            val showSpells = selectedMagicTab == "ALL" || selectedMagicTab == "SPELLS"
            val showScrolls = selectedMagicTab == "ALL" || selectedMagicTab == "SCROLLS"
            val showItems = selectedMagicTab == "ALL" || selectedMagicTab == "ITEMS"
            // Section headers only in the "ALL" view; a single-category tab is self-labelling.
            val showHeaders = selectedMagicTab == "ALL"

            // Ordered tabs (ALL + present categories) for swipe-cycling.
            val magicTabOrder = remember(presentMagicTabs) { listOf("ALL") + presentMagicTabs }
            // Tabs + list live in one mwPanel box, matching InventoryPanel. Swipe left/right across
            // the list body cycles the category.
            Column(
                Modifier.weight(1f).mwPanel().categorySwipe(selectedMagicTab) { dir ->
                    selectedMagicTab = cycleValue(magicTabOrder, selectedMagicTab, dir)
                }
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .horizontalScroll(rememberScrollState())
                        .padding(horizontal = 8.dp, vertical = 6.dp),
                    horizontalArrangement = Arrangement.spacedBy(6.dp)
                ) {
                    CategoryTab(label = "ALL", active = selectedMagicTab == "ALL") {
                        selectedMagicTab = "ALL"
                    }
                    presentMagicTabs.forEach { label ->
                        CategoryTab(label = label, active = selectedMagicTab == label) {
                            selectedMagicTab = label
                        }
                    }
                }
                Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
                LazyColumn(Modifier.weight(1f).fillMaxWidth().padding(horizontal = 4.dp)) {
                    if (showPowers && powers.isNotEmpty()) {
                        if (showHeaders) {
                            item {
                                SpellSectionHeader("Powers")
                            }
                        }
                        items(powers) { spell ->
                            SpellRow(
                                spellId = spell.id,
                                title = spell.displayName(),
                                selected = spell.id == sel,
                                effect = spell.effect,
                                effectCount = spell.effectCount,
                                school = spell.school,
                                cost = spell.cost,
                                onInfo = { ItemInfoPopupState.open(spell.id, spell.name, null, kind = InfoKind.SPELL) },
                                iconBitmap = rememberItemIcon(spell.icon)
                            ) { CompanionActions.selectSpell(spell.id) }
                        }
                    }
                    if (showSpells && spells.isNotEmpty()) {
                        if (showHeaders) {
                            item {
                                SpellSectionHeader("Spells")
                            }
                        }
                        items(spells) { spell ->
                            SpellRow(
                                spellId = spell.id,
                                title = spell.displayName(),
                                selected = spell.id == sel,
                                effect = spell.effect,
                                effectCount = spell.effectCount,
                                school = spell.school,
                                cost = spell.cost,
                                // Only this section passes a chance. The map is keyed by spell id
                                // and contains learned spells only, so the powers/scrolls/enchanted
                                // sections would look up null anyway — but not passing it there
                                // keeps that intent explicit rather than incidental.
                                chance = spellChances[spell.id],
                                onInfo = { ItemInfoPopupState.open(spell.id, spell.name, null, kind = InfoKind.SPELL) },
                                iconBitmap = rememberItemIcon(spell.icon)
                            ) { CompanionActions.selectSpell(spell.id) }
                        }
                    }
                    if (showScrolls && scrolls.isNotEmpty()) {
                        if (showHeaders) {
                            item {
                                SpellSectionHeader("Scrolls")
                            }
                        }
                        items(scrolls) { spell ->
                            SpellRow(
                                spellId = spell.id,
                                title = spell.displayName(),
                                selected = false,
                                effect = spell.effect,
                                effectCount = spell.effectCount,
                                onInfo = {
                                    ItemInfoPopupState.open(spell.id, spell.name, enchantByRecordId[spell.id])
                                },
                                iconBitmap = rememberItemIcon(spell.icon)
                            ) { CompanionActions.selectSpell(spell.id) }
                        }
                    }
                    if (showItems && enchantedItems.isNotEmpty()) {
                        if (showHeaders) {
                            item {
                                SpellSectionHeader("Enchanted Items")
                            }
                        }
                        items(enchantedItems) { spell ->
                            SpellRow(
                                spellId = spell.id,
                                title = spell.displayName(),
                                selected = spell.id == sel,
                                charge = spell.charge,
                                maxCharge = spell.maxCharge,
                                effect = spell.effect,
                                effectCount = spell.effectCount,
                                onInfo = {
                                    ItemInfoPopupState.open(spell.id, spell.name, enchantByRecordId[spell.id])
                                },
                                iconBitmap = rememberItemIcon(spell.icon)
                            ) { CompanionActions.selectSpell(spell.id) }
                        }
                    }
                    item { Spacer(Modifier.height(4.dp)) }
                }
            }
        }
    }
}

@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun SpellRow(
    spellId: String,
    title: String,
    selected: Boolean = false,
    charge: Int = 0,
    maxCharge: Int = 0,
    effect: String = "",
    // TOTAL effects on the spell/scroll/enchantment. [effect] is the FIRST one only, so anything
    // above 1 is drawn as a "+N MORE" line under the effect text. 0 = not reported, same as 1.
    effectCount: Int = 0,
    school: String = "",
    cost: Int = 0,
    // Success chance as a whole percent, or null for "no chance column". Null is the norm for
    // powers, scrolls and enchanted items — vanilla shows a chance for LEARNED SPELLS only (a
    // power's column is left empty and an enchanted item's second number is charge, not chance),
    // and the exporter already filters to that set, so there is no spell-type test here.
    chance: Int? = null,
    onInfo: (() -> Unit)? = null,
    iconBitmap: ImageBitmap? = null,
    onTap: () -> Unit
) {
    val context = LocalContext.current
    var menuOpen by remember { mutableStateOf(false) }
    LaunchedEffect(DropdownState.closeRequest) {
        if (DropdownState.closeRequest > 0) menuOpen = false
    }
    val favs by FavouritesRepository.state.collectAsState()
    val isFav = favs.magic.any { it?.id == spellId }
    // Compact spell-list sizing is the only version now (smaller icon + shorter rows so more spells
    // fit). The former "Standard" values are kept in comments in case the toggle is ever restored.
    val iconSize = 30.dp        // Standard: 40.dp
    val rowVerticalPad = 6.dp   // Standard: 11.dp
    val iconGap = 9.dp          // Standard: 10.dp
    val nameFont = 13.sp        // Standard: 14.sp
    Box(modifier = Modifier.onGloballyPositioned { ItemInfoPopupState.reportAnchor(spellId, it.boundsInRoot()) }) {
        Column {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    // Equipped/selected spell gets the same highlight as a worn item in the
                    // inventory tab: faint fill + BronzeLight outline (in place of an "EQUIPPED" tag).
                    .then(
                        if (selected) Modifier
                            .clip(RoundedCornerShape(3.dp))
                            .background(BronzeLight.copy(alpha = 0.06f))
                            .border(1.dp, BronzeLight, RoundedCornerShape(3.dp))
                        else Modifier
                    )
                    .combinedClickable(
                        onClick = onTap,
                        onLongClick = { menuOpen = true; DropdownState.open() }
                    )
                    .padding(start = 14.dp, end = 10.dp, top = rowVerticalPad, bottom = rowVerticalPad),
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Icon box (leftmost). Placeholder empty slot until the icon
                // pipeline loads real textures; drop in a real bitmap by
                // passing iconBitmap non-null at the call site.
                Box(
                    modifier = Modifier
                        .size(iconSize)
                        .clip(RoundedCornerShape(2.dp))
                        .background(SlotBg)
                        .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
                ) {
                    if (iconBitmap != null) {
                        Image(
                            bitmap = iconBitmap,
                            contentDescription = null,
                            contentScale = ContentScale.Fit,
                            modifier = Modifier.fillMaxSize()
                        )
                    }
                }
                Spacer(Modifier.width(iconGap))
                // Text colours mirror the inventory worn/unworn styling: the
                // equipped spell is the brighter BoneBright (like a worn item)
                // with an "EQUIPPED" tag, rather than a bronze/bold highlight.
                // Name + (optional) favourite star share the flex column so the
                // name truncates before the star; the star is a standalone Icon.
                // Name column (narrower — weight 1 — so the stat cluster, especially EFFECT, has more
                // room). The favourite star is a top-right corner overlay (added below), not inline,
                // mirroring the inventory cards.
                Text(
                    title, color = if (selected) BoneBright else BoneMuted,
                    fontSize = nameFont, fontFamily = MwBody,
                    fontWeight = FontWeight.Normal,
                    maxLines = 1, overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f).padding(end = 8.dp)
                )
                // Stat cluster, left→right: CHARGE/COST, SCHOOL, EFFECT. Titles on TOP with the value
                // beneath (cardStyle, matching the inventory cards). Charge/cost + school are fixed-
                // width and shown ONLY when present; EFFECT is the flexible right-most column (weight)
                // so it gets the most room and STRETCHES to absorb whatever the missing sections free
                // up (e.g. a scroll, which has only an effect). Weight/value are deliberately excluded.
                if (maxCharge > 0) {
                    ItemConditionColumn(cond = null, enchantCharge = charge to maxCharge, width = 40.dp)
                    Spacer(Modifier.width(6.dp))
                } else if (cost > 0) {
                    ItemStatColumn(cost.toString(), "COST", width = 40.dp, cardStyle = true)
                    Spacer(Modifier.width(6.dp))
                }
                // CHANCE as its own labelled column rather than folded into COST as vanilla's
                // "24/87" single cell. Vanilla has no column headers so it can afford the compact
                // form; ours does, and the combined heading does not fit — measured against the
                // real game font, "COST/CHANCE" is 77.6dp and the value "100/100" is 42.1dp, so the
                // one-cell version would need an ~82dp column against COST's current 40dp. Two
                // labelled columns are both narrower overall and unambiguous. 48dp fits the widest
                // title ("CHANCE", 44.8dp) and value ("100%", ~25dp).
                if (chance != null) {
                    ItemStatColumn("$chance%", "CHANCE", width = 48.dp, cardStyle = true)
                    Spacer(Modifier.width(6.dp))
                }
                if (school.isNotEmpty()) {
                    ItemStatColumn(
                        school.replaceFirstChar { it.uppercase() }, "SCHOOL", width = 66.dp, cardStyle = true
                    )
                    Spacer(Modifier.width(6.dp))
                }
                // EFFECT: the flexible right-most column. The description is now the fuller
                // "Frost Damage 25pts for 1s (touch)" form, so — unlike the single-line stat columns —
                // its value wraps to TWO lines (proportional font, centred) to fit; the "EFFECT" title
                // stays on top. Given the widest weight so it gets the most room and stretches when
                // school/cost are absent.
                Box(Modifier.weight(1.6f), contentAlignment = Alignment.Center) {
                    if (effect.isNotEmpty()) {
                        Column(horizontalAlignment = Alignment.CenterHorizontally) {
                            Text(
                                "EFFECT",
                                color = BoneDim, fontSize = 8.sp, fontFamily = MwBody,
                                letterSpacing = 0.5.sp, maxLines = 1
                            )
                            Text(
                                effect,
                                color = BronzeLight, fontSize = 10.sp, fontFamily = MwBody,
                                textAlign = TextAlign.Center, lineHeight = 11.sp,
                                maxLines = 2, overflow = TextOverflow.Ellipsis
                            )
                            // "+N MORE" sits AFTER the effect, on its OWN line rather than appended
                            // to the value above. Appending inline would put it inside a 2-line
                            // ellipsised box, so on exactly the spells this exists for — a long
                            // first-effect description like "Detect Animal 200pts for 60s (self)",
                            // which already fills both lines — it would be the part that gets cut.
                            // A separate line cannot be truncated away. It costs height only on
                            // multi-effect rows, so it is kept deliberately small (8sp with a 9sp
                            // line height, the heading's size) to spend as little of this
                            // density-tuned list as possible.
                            val extraEffects = (effectCount - 1).coerceAtLeast(0)
                            if (extraEffects > 0) {
                                Text(
                                    "+$extraEffects MORE",
                                    color = BoneMuted, fontSize = 8.sp, fontFamily = MwBody,
                                    letterSpacing = 0.5.sp, lineHeight = 9.sp, maxLines = 1
                                )
                            }
                        }
                    }
                }
            }
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
        }
        // Favourite star, top-right corner of the spell box (overlay, not inline with the name) —
        // same treatment as the inventory cards.
        if (isFav) {
            Box(Modifier.align(Alignment.TopEnd).padding(top = 3.dp, end = 3.dp)) { FavStar() }
        }
        CompanionDropdownMenu(
            expanded = menuOpen,
            onDismissRequest = { menuOpen = false; DropdownState.closeAll() }
        ) {
            Text(
                title,
                color = BronzeLight, fontSize = 12.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                maxLines = 1, overflow = TextOverflow.Ellipsis,
                modifier = Modifier.padding(horizontal = 12.dp, vertical = 8.dp)
            )
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
            if (onInfo != null) {
                DropdownMenuItem(
                    text = { Text("Info", fontFamily = MwBody, fontSize = 13.sp) },
                    onClick = { menuOpen = false; DropdownState.closeAll(); onInfo() },
                    colors = MenuDefaults.itemColors(textColor = Bone)
                )
            }
            // Add to favourites / Unfavourite / replace-slot picker (magic slots).
            FavouriteMenuItems(
                context = context,
                isGear = false,
                itemId = spellId,
                makeSlot = { FavSlot(spellId, title) },
                onDone = { menuOpen = false; DropdownState.closeAll() }
            )
        }
    }
}

/* ---- Journal ---- */

// Persistent three-tab header for the Journal panel. Declared left→right so
// JournalTab.entries renders TOPICS | JOURNAL | QUESTS in order.
private enum class JournalTab { Topics, Journal, Quests }

// COMPANION_JOURNAL_ENTRY's "m" is 1-based: the Lua binding returns mMonth + 1
// (mwlua/types/player.cpp), so subtract before indexing.
private fun morrowindMonthName(month: Int): String = listOf(
    "Morning Star", "Sun's Dawn", "First Seed", "Rain's Hand",
    "Second Seed", "Midyear", "Sun's Height", "Last Seed",
    "Hearthfire", "Frostfall", "Sun's Dusk", "Evening Star"
).getOrElse(month - 1) { "Month $month" }

/**
 * Date stamp for a journal entry, matching the in-game journal verbatim:
 * "16 Last Seed (Day 1)". The engine builds the same string in
 * JournalViewModelImpl::timestamp() (journalviewmodel.cpp) from mDayOfMonth /
 * getMonthName(mMonth) / mDay, where mDay is the DaysPassed global — exactly the
 * three fields this entry carries. "Day" is the sDay GMST engine-side; hardcoded
 * here for the same reason morrowindMonthName's names are.
 */
private fun journalDateLabel(entry: JournalEntry): String =
    "${entry.dayOfMonth} ${morrowindMonthName(entry.month)} (Day ${entry.day})"

/**
 * The journal as the DS presents it: the game's own entries followed by the player's manual ones.
 *
 * MERGED HERE rather than injected into `GameState.journalEntries`, because that list is rebuilt
 * wholesale from the COMPANION_JOURNAL_* buffer on every journal tick — anything written into it
 * would be wiped moments later, and it would blur the line between "what the game exported" and
 * "what the player wrote".
 *
 * CUSTOM ENTRIES ARE APPENDED AT THE END, which is what `JournalChronological` wants: it groups
 * with `getOrPut(e.day)` into a LinkedHashMap, so a manual entry joins the bottom of its own day's
 * column, or — if it is the first entry of a new day — creates the last column, which is correct
 * since it can only ever be written "now".
 *
 * The QUEST LIST no longer depends on this ordering at all (Aug 24 2026). It is built from the
 * quest export by `buildQuestGroups`, sorted alphabetically, with "Manual Entries" pinned first by
 * `rememberQuestGroups` — where the append used to float it to the top implicitly.
 */
@Composable
private fun rememberMergedJournal(entries: List<JournalEntry>): List<JournalEntry> {
    val custom by CustomJournalRepository.state.collectAsState()
    return remember(entries, custom) {
        if (custom.isEmpty()) entries else entries + custom.map { it.toJournalEntry() }
    }
}

/**
 * The Quests list as vanilla derives it, from the quest export rather than the journal entries.
 *
 * Transcribes `JournalViewModelImpl::visitQuestNames` (journalviewmodel.cpp): [quests] already
 * excludes the nameless ones on the Lua side, so what is left here is the two things that function
 * does — collapse quests sharing a name into ONE log, and mark a log finished when ANY of its
 * members is. Neither could be done from journal entries, which is where this list used to come
 * from and why it both invented rows and dropped real ones.
 *
 * ORDERING IS ALPHABETICAL, also matching vanilla: `notifyQuests` calls `MWList::sort()`, which is
 * `Misc::StringUtils::ciLess` — a case-insensitive lexicographic compare. `lowercase()` is
 * Locale.ROOT, so it agrees with that byte-for-byte over ASCII; it differs only in that it also
 * folds non-ASCII, which the engine's ASCII-only `toLower` leaves alone. That is the better
 * behaviour for a localised name and cannot arise in vanilla English content.
 *
 * This REPLACED a most-recently-active ordering (Aug 24 2026). That was a DS-only choice carried
 * over from when the list was built from journal entries, and it had a real cost beyond being
 * unlike vanilla: a quest log with no journal entry — one advanced by `SetJournalIndex`, or whose
 * entries so far are empty-texted — has no recency at all, so it could only ever be dumped at the
 * bottom. Alphabetical gives every log a real position and makes a named quest findable.
 */
private fun buildQuestGroups(
    quests: List<QuestInfo>,
    finishedQuestIds: Set<String>
): List<QuestGroup> {
    val byName = LinkedHashMap<String, MutableList<QuestInfo>>()
    quests.forEach { q -> byName.getOrPut(q.name.lowercase()) { mutableListOf() }.add(q) }
    return byName.values.map { members ->
        QuestGroup(
            id = members.first().id,
            ids = members.mapTo(LinkedHashSet()) { it.id },
            // Verbatim: QS_Name is already the string vanilla prints.
            name = members.first().name,
            finished = members.any { it.id in finishedQuestIds }
        )
    }.sortedBy { it.name.lowercase() }
}

/**
 * [buildQuestGroups] with the manual-entries pseudo-quest PINNED FIRST.
 *
 * It is prepended rather than sorted in among the quests, which is a deliberate departure from the
 * alphabetical rule above: it is not a quest, it is the player's own notebook, and it kept its
 * top-of-list position from the day it was added. Sorting it under "M" would bury it in the middle
 * of a long list of things the game wrote. It exists only on this side and is never in the export,
 * hence the synthetic group here.
 */
@Composable
private fun rememberQuestGroups(
    quests: List<QuestInfo>,
    finishedQuestIds: Set<String>,
    hasManualEntries: Boolean
): List<QuestGroup> = remember(quests, finishedQuestIds, hasManualEntries) {
    val groups = buildQuestGroups(quests, finishedQuestIds)
    if (!hasManualEntries) groups
    else listOf(
        QuestGroup(
            id = MANUAL_QUEST_ID,
            ids = setOf(MANUAL_QUEST_ID),
            name = MANUAL_QUEST_NAME,
            // Never finished — the notebook always reads active. Mirrors the reserved id's
            // deliberate absence from finishedQuestIds.
            finished = false
        )
    ) + groups
}

@Composable
private fun JournalPanel() {
    val state by GameStateRepository.state.collectAsState()
    val finishedQuestIds by GameStateRepository.finishedQuestIds.collectAsState()
    // The quest list proper. NOT derived from journalEntries — see QuestInfo / buildQuestGroups.
    val questInfos by GameStateRepository.quests.collectAsState()
    val customEntries by CustomJournalRepository.state.collectAsState()
    val topics by GameStateRepository.journalTopics.collectAsState()
    // The game's entries plus the player's manual ones. Every view below reads THIS, never
    // state.journalEntries — the three of them already take a List<JournalEntry>, so merging once
    // here is the whole integration.
    val journalEntries = rememberMergedJournal(state.journalEntries)
    val questGroups = rememberQuestGroups(
        quests = questInfos,
        finishedQuestIds = finishedQuestIds,
        hasManualEntries = customEntries.isNotEmpty()
    )
    var selectedJournalTab by remember { mutableStateOf(JournalTab.Journal) }
    // Sub-navigation within the QUESTS tab: null = quest list, non-null = detail.
    var selectedQuestId by remember { mutableStateOf<String?>(null) }
    // Sub-navigation within the TOPICS tab: null = topic list, non-null = detail.
    var selectedTopic by remember { mutableStateOf<TopicInfo?>(null) }
    // Quest-list filter state. Hoisted OUT of JournalQuestList so it survives opening a quest and
    // coming back — that list leaves composition on every detail navigation, so state owned there
    // silently reverted to Active and dumped the player somewhere they hadn't chosen.
    // Off = active quests only (default); on = also show finished quests.
    var showAllQuests by remember { mutableStateOf(false) }
    // Hidden-only view. MUTUALLY EXCLUSIVE with the above rather than additive: while on it
    // REPLACES the list with the hidden quests.
    var showHiddenQuests by remember { mutableStateOf(false) }

    /** Back to the default quest view: the list (not a detail page), active quests only. */
    fun resetQuestView() {
        selectedQuestId = null
        showAllQuests = false
        showHiddenQuests = false
    }

    // Bottom-bar JOURNAL tap → back to the chronological journal view. Compared against a
    // remembered count so a FRESHLY composed panel ignores the standing value: firing on first
    // composition would race the quest-nav effect below and clobber the quest the HUD label asked
    // for. A fresh panel is already in the default state, so there's nothing to reset anyway.
    var lastJournalReset by remember { mutableIntStateOf(JournalResetState.resetRequest) }
    LaunchedEffect(JournalResetState.resetRequest) {
        if (JournalResetState.resetRequest != lastJournalReset) {
            lastJournalReset = JournalResetState.resetRequest
            selectedJournalTab = JournalTab.Journal
            selectedTopic = null
            resetQuestView()
        }
    }

    // A tap on the HUD's followed-quest label routes here (CompanionScreen switches to this tab
    // first, so this panel is composed by the time the effect runs): jump straight to that quest's
    // detail page. Keyed on the pending id so a later tap on a different quest re-fires.
    val pendingQuestNav = JournalQuestNavState.questId
    LaunchedEffect(pendingQuestNav) {
        JournalQuestNavState.consume()?.let { qid ->
            selectedJournalTab = JournalTab.Quests
            selectedQuestId = qid
        }
    }
    // The empty tracked-quest slot: the LIST, with no quest opened — that is the point, the player
    // is here to pick one.
    val pendingQuestList = JournalQuestNavState.listRequest
    LaunchedEffect(pendingQuestList) {
        if (JournalQuestNavState.consumeList()) {
            selectedJournalTab = JournalTab.Quests
            selectedQuestId = null
        }
    }

    LaunchedEffect(Unit) {
        CompanionActions.refreshJournal()
        CompanionActions.refreshQuestStatus()
        // Also needed by the JOURNAL and QUESTS tabs now, not just the Topics list: the known-topic
        // set is what the entry text is linked against, and the journal opens on the Journal tab —
        // without this, links would only appear after a visit to Topics.
        CompanionActions.refreshTopics()
    }

    // Tapping a topic link in any entry jumps to that topic's page, which is the vanilla journal's
    // behaviour. Matched case-insensitively because the link shows the text as written, which need
    // not match the topic's own capitalisation.
    val openTopic: (String) -> Unit = { name ->
        topics.firstOrNull { it.name.equals(name, ignoreCase = true) }?.let {
            selectedTopic = it
            selectedJournalTab = JournalTab.Topics
        }
    }
    // Link phrases, recomputed only when the topic set actually changes.
    val topicNames = remember(topics) { topics.map { it.name } }

    Box(
        Modifier
            .fillMaxSize()
            .padding(top = 12.dp, bottom = BOTTOM_BAR_SPACE.dp, start = 12.dp, end = 12.dp)
    ) {
        Column(Modifier.fillMaxSize()) {
            JournalTabBar(
                selected = selectedJournalTab,
                onSelect = { t ->
                    // Tapping QUESTS always lands on the default view — the list, active quests
                    // only — rather than resuming whatever detail page / filter was last left
                    // open. Same "the heading is a way home" role the bottom JOURNAL button has.
                    if (t == JournalTab.Quests) resetQuestView()
                    selectedJournalTab = t
                }
            )
            Spacer(Modifier.height(8.dp))
            Box(Modifier.fillMaxSize()) {
                when (selectedJournalTab) {
                    JournalTab.Topics -> {
                        val sel = selectedTopic
                        if (sel == null)
                            JournalTopicsList(topics = topics, onTopic = { selectedTopic = it })
                        else
                            JournalTopicDetail(
                                topic = sel,
                                onBack = { selectedTopic = null },
                                topicNames = topicNames,
                                onTopicLink = openTopic
                            )
                    }
                    JournalTab.Journal ->
                        if (journalEntries.isEmpty()) JournalEmptyState()
                        else JournalChronological(journalEntries, topicNames, openTopic)
                    JournalTab.Quests -> {
                        val qid = selectedQuestId
                        if (qid == null)
                            JournalQuestList(
                                groups = questGroups,
                                showAll = showAllQuests,
                                showHidden = showHiddenQuests,
                                // Choosing Active/All always leaves the hidden-only view (exclusive).
                                onShowAll = { showAllQuests = it; showHiddenQuests = false },
                                onShowHidden = { showHiddenQuests = it },
                                onQuest = { selectedQuestId = it }
                            )
                        else {
                            // Resolved against the group so the detail page shows the entries of
                            // EVERY quest id in this log, as visitJournalEntries(questName) does.
                            // A miss (the HUD label pointing at a quest that has since gone) still
                            // renders, as a single-id group with whatever entries exist.
                            val group = remember(questGroups, qid) {
                                questGroups.firstOrNull { qid in it.ids }
                                    ?: QuestGroup(qid, setOf(qid), "", false)
                            }
                            JournalQuestDetail(
                                group = group,
                                entries = journalEntries.filter { it.questId in group.ids },
                                onBack = { selectedQuestId = null },
                                topicNames = topicNames,
                                onTopicLink = openTopic
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun JournalTabBar(selected: JournalTab, onSelect: (JournalTab) -> Unit) {
    Column(Modifier.fillMaxWidth().background(StonePanel)) {
        // Top edge, matching mwPanel()'s Bronze frame.
        Box(Modifier.fillMaxWidth().height(1.dp).background(Bronze))
        Row(Modifier.fillMaxWidth().height(36.dp)) {
            JournalTab.entries.forEach { tab ->
                val active = tab == selected
                Box(
                    Modifier.weight(1f).fillMaxHeight().clickable { onSelect(tab) },
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        tab.name.uppercase(),
                        color = if (active) BronzeLight else BoneDim,
                        fontSize = 12.sp, fontFamily = MwBody, letterSpacing = 1.5.sp
                    )
                    if (active) {
                        Box(
                            Modifier.align(Alignment.BottomCenter)
                                .fillMaxWidth().height(2.dp).background(BronzeDark)
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun JournalEmptyState() {
    Column(
        Modifier.fillMaxSize().mwPanel().padding(16.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        Text("Journal", color = Bone, fontSize = 20.sp,
            fontFamily = MwDisplay, fontWeight = FontWeight.SemiBold)
        Spacer(Modifier.height(8.dp))
        Text("No journal entries yet",
            color = BoneDim, fontSize = 13.sp, fontFamily = MwBody,
            textAlign = TextAlign.Center)
    }
}

@Composable
private fun JournalTopicsList(topics: List<TopicInfo>, onTopic: (TopicInfo) -> Unit) {
    // Ask the engine for the known-topic list whenever this view is (re)shown —
    // new topics may have been learned since the last visit. Native reply arrives
    // as the streamed COMPANION_TOPICS_* block. Mirrors JournalPanel's refreshJournal().
    LaunchedEffect(Unit) { CompanionActions.refreshTopics() }

    if (topics.isEmpty()) {
        Box(Modifier.fillMaxSize().mwPanel(), contentAlignment = Alignment.Center) {
            Text("Loading topics…", color = BoneDim, fontSize = 15.sp, fontFamily = MwBody)
        }
        return
    }

    // Group by uppercased first letter (non-letter initials → "#"), keys sorted
    // with "#" first. Native emits topics already alphabetical, so groupBy keeps
    // each letter's topics in that order.
    val grouped = remember(topics) {
        topics.groupBy { t ->
            val c = t.name.trim().firstOrNull()
            if (c != null && c.isLetter()) c.uppercaseChar().toString() else "#"
        }.toSortedMap(compareBy { if (it == "#") "" else it })
    }

    Column(Modifier.fillMaxSize().mwPanel()) {
        LazyColumn(Modifier.fillMaxSize().padding(horizontal = 4.dp)) {
            grouped.forEach { (letter, list) ->
                item(key = "hdr_$letter") { TopicLetterHeader(letter) }
                // No item key: topic display names are usually but not guaranteed
                // unique (keyed by RefId engine-side), and duplicate keys crash LazyColumn.
                items(list) { topic ->
                    Row(
                        Modifier
                            .fillMaxWidth()
                            .clickable { onTopic(topic) }
                            .padding(horizontal = 10.dp, vertical = 11.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(topic.name, color = Bone, fontSize = 14.sp, fontFamily = MwBody,
                            modifier = Modifier.weight(1f))
                        Text("▶", color = BronzeLight, fontSize = 13.sp, fontFamily = MwBody)
                    }
                    Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
                }
            }
            item { Spacer(Modifier.height(8.dp)) }
        }
    }
}

// Single-letter alphabet divider for the topics list — SpellSectionHeader style,
// bumped to 16sp for the letter.
@Composable
private fun TopicLetterHeader(letter: String) {
    Column {
        Text(
            letter,
            color = BronzeLight, fontSize = 16.sp,
            fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
            modifier = Modifier.fillMaxWidth().padding(start = 6.dp, top = 8.dp, bottom = 4.dp)
        )
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
    }
}

@Composable
private fun JournalTopicDetail(
    topic: TopicInfo,
    onBack: () -> Unit,
    topicNames: List<String>,
    onTopicLink: (String) -> Unit
) {
    Column(Modifier.fillMaxSize().mwPanel()) {
        // Back nav (matches the journal back-navigation style).
        Row(
            Modifier.fillMaxWidth().padding(horizontal = 10.dp, vertical = 8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text("◀ Topics", color = BronzeLight, fontSize = 14.sp, fontFamily = MwBody,
                modifier = Modifier.clickable { onBack() }.padding(4.dp))
        }
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
        // Topic name header.
        Text(topic.name, color = BronzeLight, fontSize = 16.sp, fontFamily = MwDisplay,
            fontWeight = FontWeight.Bold,
            modifier = Modifier.padding(start = 10.dp, top = 10.dp, bottom = 6.dp))
        LazyColumn(Modifier.fillMaxSize().padding(horizontal = 4.dp)) {
            itemsIndexed(topic.entries) { idx, entry ->
                if (entry.actorName.isNotEmpty()) {
                    Text(entry.actorName, color = BronzeLight, fontSize = 12.sp,
                        fontFamily = MwBody, fontWeight = FontWeight.Bold,
                        modifier = Modifier.padding(start = 10.dp, top = 10.dp, bottom = 2.dp))
                }
                Text(journalAnnotated(entry.text, topicNames, onTopicLink),
                    color = Bone, fontSize = 14.sp, fontFamily = MwBody,
                    lineHeight = 22.4.sp,
                    modifier = Modifier.padding(
                        start = 10.dp, end = 10.dp,
                        top = if (entry.actorName.isEmpty()) 10.dp else 0.dp, bottom = 8.dp))
                if (idx < topic.entries.lastIndex)
                    Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
            }
            item { Spacer(Modifier.height(8.dp)) }
        }
    }
}

@Composable
private fun JournalNavBar(left: String?, onLeft: (() -> Unit)?, center: String, right: String?, onRight: (() -> Unit)?) {
    Row(
        Modifier.fillMaxWidth().padding(horizontal = 10.dp, vertical = 8.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        if (left != null && onLeft != null)
            Text("◀ $left", color = BronzeLight, fontSize = 14.sp, fontFamily = MwBody,
                modifier = Modifier.clickable { onLeft() }.padding(4.dp))
        else
            Spacer(Modifier.size(1.dp))
        Text(center, color = Bone, fontSize = 16.sp, fontFamily = MwDisplay, fontWeight = FontWeight.SemiBold)
        if (right != null && onRight != null)
            Text("$right ▶", color = BronzeLight, fontSize = 14.sp, fontFamily = MwBody,
                modifier = Modifier.clickable { onRight() }.padding(4.dp))
        else
            Spacer(Modifier.size(1.dp))
    }
    Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
}

/* ---- Journal book pagination (animated page-turn mode only) ---- */

/**
 * One drawable piece of a journal column. The whole point of the type is that a [Body] is a
 * FRAGMENT, not an entry: the paginator is free to cut one entry's text across a page boundary, and
 * the renderer neither knows nor cares whether what it holds is a whole entry or the tail of one.
 */
private sealed interface JournalPageItem {
    data class Header(val label: String) : JournalPageItem
    data class Body(val text: AnnotatedString) : JournalPageItem
    data object AddEntry : JournalPageItem
}

/**
 * Paddings baked into the journal column layout, named here because the paginator has to ADD THEM
 * UP to know how much fits while the renderers apply them as modifiers. Two consumers, one set of
 * numbers — the same discipline [JOURNAL_SPREAD_H_PAD] and friends already enforce between the
 * in-pager spread and [JournalLeafOverlay]'s arithmetic copy of it. Never write one of these as a
 * literal at a use site.
 */
private val JOURNAL_COL_H_PAD = 6.dp
/** Breathing room at the head and foot of every column. Without the top inset, a column that opens
 *  mid-entry (which reflow makes the common case) starts its text hard against the page edge. */
private val JOURNAL_COL_TOP_PAD = 10.dp
private val JOURNAL_COL_BOTTOM_PAD = 6.dp
/** Separation ABOVE a date header — from the previous day's text, so it is dropped when the header
 *  is the first thing on a column and there is nothing above it to separate from. */
private val JOURNAL_HEADER_PAD_TOP = 14.dp
/** Gap between a date and its own first entry. Deliberately much smaller than [JOURNAL_HEADER_PAD_TOP]
 *  so the heading groups with the text BELOW it rather than floating between two days. */
private val JOURNAL_HEADER_PAD_BOTTOM = 6.dp
private val JOURNAL_BODY_PAD_BOTTOM = 4.dp
/** Outer (8 top + 10 bottom) plus the pill's own vertical padding (5 + 5). The 1dp border draws
 *  inside the bounds and does NOT add layout height, so it is not counted. */
private val JOURNAL_ADD_ENTRY_EXTRA_V = 28.dp

/** Height always reserved for the page-dot strip — see the circularity note in [JournalChronological]. */
private val JOURNAL_INDICATOR_STRIP = 13.dp

/** Past this many pages the dots stop fitting across the panel and a counter is shown instead. */
private const val JOURNAL_MAX_DOTS = 14

/**
 * Minimum lines of an entry left on a column, and carried onto the next, when its text is split.
 * Stops a single orphaned line dangling at the foot of a page (or arriving alone at the head of
 * one), which is the thing that most makes a reflowed page stop reading like a book.
 */
private const val JOURNAL_MIN_SPLIT_LINES = 2

/**
 * Text styles for the chronological journal, SHARED by the renderers and by the paginator's
 * measurement pass. This sharing is load-bearing, not tidiness: a style the paginator measures with
 * that differs by even a line-height from the one actually drawn produces pages that overflow or
 * come up short, and the symptom (clipped last line) looks nothing like the cause.
 */
/** Larger than the body (14.sp) on purpose — a date is a heading and should read as one. */
@Composable
private fun journalHeaderStyle() = TextStyle(
    color = BronzeLight, fontSize = 16.sp, fontFamily = MwDisplay, fontWeight = FontWeight.Bold
)

@Composable
private fun journalBodyStyle() = TextStyle(
    color = Bone, fontSize = 14.sp, fontFamily = MwBody, lineHeight = 18.sp
)

@Composable
private fun journalAddEntryStyle() = TextStyle(
    color = BronzeLight, fontSize = 12.sp, fontFamily = MwBody
)

/**
 * Live handler for a topic link tapped inside a PAGINATED entry.
 *
 * The paginated strings are cached across compositions of `JournalPanel` (which is destroyed and
 * rebuilt on every tab switch), so a link that captured its callback directly would, after the
 * first rebuild, be calling into a dead composition — silently doing nothing. Reading a global at
 * click time is what makes the cache safe to keep. Same role `rememberUpdatedState` plays for the
 * non-cached call sites; a global is needed here only because the value has to outlive the
 * composition that produced it.
 */
private object JournalTopicLinkHandler {
    @Volatile
    var current: ((String) -> Unit)? = null
}

/**
 * Flows a linear stream of blocks into fixed-height columns, cutting entry text at LINE boundaries
 * when it does not fit — i.e. real book pagination, where content spills to the next page rather
 * than scrolling within one.
 *
 * Splitting at a line boundary is what makes this correct rather than merely plausible: line
 * breaking is deterministic for a given (text, width, style, density), so a remainder that starts
 * where a break already fell re-lays-out on the next column exactly as it did here. An arbitrary
 * character split would not have that property and the two halves could disagree.
 *
 * Pure and Compose-free by design — everything it needs is passed in — so it can be reasoned about
 * (and its output eyeballed) without a pager, an overlay or a recomposition anywhere near it.
 *
 * @param columnHeightPx usable height of one column, paddings already deducted by the caller.
 * @return one list of items per COLUMN, in reading order. The caller pairs them into spreads.
 */
private fun paginateJournal(
    blocks: List<JournalPageItem>,
    measurer: TextMeasurer,
    headerStyle: TextStyle,
    bodyStyle: TextStyle,
    contentWidthPx: Int,
    columnHeightPx: Float,
    headerPadTopPx: Float,
    headerPadBottomPx: Float,
    bodyPadPx: Float,
    addEntryHeightPx: Float,
    bodyLineHeightPx: Float
): List<List<JournalPageItem>> {
    if (contentWidthPx <= 0 || columnHeightPx <= 0f) return listOf(blocks)

    val columns = mutableListOf<List<JournalPageItem>>()
    var current = mutableListOf<JournalPageItem>()
    var used = 0f
    // Bare text height of the header most recently placed, so it can be re-costed if it turns out
    // to be moving to a column of its own (where it loses its top padding).
    var lastHeaderTextH = 0f

    fun breakColumn() {
        columns.add(current)
        current = mutableListOf()
        used = 0f
    }

    /** A header's total cost, which depends on whether anything sits above it on the column. */
    fun headerHeight(textH: Float, first: Boolean) =
        textH + headerPadBottomPx + if (first) 0f else headerPadTopPx

    /** True when a date header is all that is on this column so far. */
    fun onlyHeaderSoFar() = current.size == 1 && current[0] is JournalPageItem.Header

    /**
     * Move to a fresh column, TAKING A TRAILING DATE HEADER WITH US.
     *
     * This is the fix for a header stranded at the foot of one page with its entry starting on the
     * next. The header is placed before its first entry is measured, so any later decision to break
     * — the orphan rule, the widow rule, or simply not enough room — would otherwise leave it
     * behind. A lookahead when placing the header cannot cover this on its own: it can only
     * ESTIMATE how much of the entry will follow, and the widow rule can force a full push no
     * matter how much room there was.
     */
    fun breakCarryingHeader() {
        val trailing = current.lastOrNull()
        if (trailing !is JournalPageItem.Header) {
            breakColumn()
            return
        }
        current.removeAt(current.lastIndex)
        columns.add(current)
        current = mutableListOf(trailing)
        used = headerHeight(lastHeaderTextH, first = true)
    }

    val constraints = Constraints(maxWidth = contentWidthPx)
    fun measure(text: AnnotatedString) =
        measurer.measure(text, style = bodyStyle, constraints = constraints)

    blocks.forEach { block ->
        when (block) {
            is JournalPageItem.Header -> {
                val textH = measurer.measure(
                    AnnotatedString(block.label), style = headerStyle, constraints = constraints
                ).size.height.toFloat()
                var h = headerHeight(textH, first = current.isEmpty())
                // Cheap lookahead so the common case does not need the carry above: only keep the
                // header here if a couple of lines of its first entry could follow it.
                val needed = h + bodyPadPx + bodyLineHeightPx * JOURNAL_MIN_SPLIT_LINES
                if (current.isNotEmpty() && used + needed > columnHeightPx) {
                    breakColumn()
                    h = headerHeight(textH, first = true)
                }
                current.add(block)
                used += h
                lastHeaderTextH = textH
            }

            is JournalPageItem.Body -> {
                var rest = block.text
                while (true) {
                    // Can this block do better on a fresh column? Not if this one is already fresh
                    // — and not if all that is on it is this block's own date header, which would
                    // travel with it and leave the situation unchanged.
                    val canEscape = used > 0f && !onlyHeaderSoFar()
                    val available = columnHeightPx - used - bodyPadPx
                    // Nothing worth starting here. The canEscape guard is also what terminates this
                    // loop — without it a column too short for a single line would spin forever.
                    if (available < bodyLineHeightPx) {
                        if (!canEscape) {
                            current.add(JournalPageItem.Body(rest))
                            used = columnHeightPx
                            break
                        }
                        breakCarryingHeader()
                        continue
                    }
                    val layout = measure(rest)
                    if (layout.size.height <= available) {
                        current.add(JournalPageItem.Body(rest))
                        used += layout.size.height + bodyPadPx
                        break
                    }
                    // Last line whose bottom still clears the column floor.
                    var line = layout.lineCount - 1
                    while (line >= 0 && layout.getLineBottom(line) > available) line--
                    val keptLines = line + 1
                    // Too little would stay behind (or too little would carry over) to be worth
                    // cutting — move the whole thing to a fresh column instead.
                    val carriedLines = layout.lineCount - keptLines
                    if (canEscape &&
                        (keptLines < JOURNAL_MIN_SPLIT_LINES || carriedLines < JOURNAL_MIN_SPLIT_LINES)
                    ) {
                        breakCarryingHeader()
                        continue
                    }
                    if (keptLines <= 0) {
                        if (!canEscape) {
                            current.add(JournalPageItem.Body(rest))
                            used = columnHeightPx
                            break
                        }
                        breakCarryingHeader()
                        continue
                    }
                    // visibleEnd = false so the break keeps the line's trailing whitespace with the
                    // line it belongs to; the remainder then starts cleanly on the next word.
                    val split = layout.getLineEnd(line, false)
                    if (split <= 0 || split >= rest.length) {
                        // Degenerate — refuse to emit an empty fragment or spin on the same text.
                        current.add(JournalPageItem.Body(rest))
                        used = columnHeightPx
                        break
                    }
                    current.add(JournalPageItem.Body(rest.subSequence(0, split)))
                    breakColumn()
                    rest = rest.subSequence(split, rest.length)
                }
            }

            JournalPageItem.AddEntry -> {
                if (used > 0f && used + addEntryHeightPx > columnHeightPx) breakColumn()
                current.add(block)
                used += addEntryHeightPx
            }
        }
    }
    if (current.isNotEmpty() || columns.isEmpty()) columns.add(current)
    return columns
}

/**
 * One journal's worth of paginated pages, held OUTSIDE composition.
 *
 * `JournalPanel` is destroyed and rebuilt on every tab switch, and its `LaunchedEffect(Unit)` fires
 * `refreshJournal()`, which re-streams the whole journal and hands back a NEW list instance holding
 * identical content. A plain `remember(entries)` would therefore re-run the measurement pass on
 * every journal open, and again a moment later when that refresh lands. Keying on a CONTENT
 * signature instead of list identity is what makes reopening the journal free.
 *
 * Single-slot on purpose: only one journal is ever on screen, and the pages hold the entry text, so
 * keeping a history of them would be a real memory cost for no benefit.
 */
private object JournalPaginationCache {
    private var key: Any? = null
    private var pages: List<List<JournalPageItem>> = emptyList()

    fun get(signature: Any, compute: () -> List<List<JournalPageItem>>): List<List<JournalPageItem>> {
        if (signature != key) {
            pages = compute()
            key = signature
        }
        return pages
    }
}

/**
 * Everything the paginated output depends on. Anything that can change a line break has to be in
 * here or the cache serves stale pages — which shows up as visibly wrong content, not as a crash.
 * `fontScale` and `fontFamily` earn their places because the Game Font toggle changes both.
 */
private data class JournalPaginationKey(
    val entriesHash: Int,
    val topicsHash: Int,
    val widthPx: Int,
    val heightPx: Int,
    val fontScale: Float,
    val bodyFont: Any?,
    val headerFont: Any?,
    val showAddEntry: Boolean
)

/**
 * The chronological journal. Two page MODELS live behind the "Journal Page Turn" preference and
 * this wrapper picks between them:
 *
 *  - OFF — the original: one day per column, two days per spread, each column scrolling when its
 *    day does not fit. Unchanged.
 *  - ON  — real book pagination: content flows column to column, cutting an entry's text mid-way
 *    when it has to, and nothing scrolls.
 *
 * The pref used to select only a TRANSITION, so it could flip freely under a shared pager. It now
 * selects what a page CONTAINS, so `currentPage` means something different on either side of it —
 * hence `key`, which rebuilds the pager state rather than leaving it indexing the wrong model.
 * The cost is landing back on the newest page after a toggle, which is where the journal opens
 * anyway.
 */
@Composable
private fun JournalChronological(
    entries: List<JournalEntry>,
    topicNames: List<String>,
    onTopicLink: (String) -> Unit
) {
    val pageTurn by UiPreferences.journalPageTurnFlow().collectAsState()
    key(pageTurn) {
        JournalChronologicalPages(entries, topicNames, onTopicLink, pageTurn)
    }
}

@Composable
private fun JournalChronologicalPages(
    entries: List<JournalEntry>,
    topicNames: List<String>,
    onTopicLink: (String) -> Unit,
    pageTurn: Boolean
) {
    // GROUPED BY entry.day (the DaysPassed global), NOT by the printed date. dayOfMonth+month
    // repeat every in-game year, so keying on the label merged year 2's entries into year 1's
    // bucket: past the anniversary of the first entry no NEW page was ever created again and the
    // journal looked permanently frozen on its last page, with new entries silently appended to an
    // old page near the front. day is monotonic, so it can't collide.
    //
    // BOTH page models are built from this one grouping, so that fix cannot be reintroduced by
    // only half of them.
    //
    // SORTED BY DAY, not left in encounter order (fixed Aug 10 2026). The map is keyed correctly,
    // but a LinkedHashMap orders buckets by FIRST APPEARANCE, and custom entries are appended after
    // every engine entry (rememberMergedJournal) — so a manual note written on a day with no game
    // entry of its own created its bucket LAST, after days that came after it. Repro: write a note,
    // then let a quest update arrive the next day; the note jumped to the end of the journal. The
    // append-at-end merge is still correct (it is what floats "Manual Entries" to the top of the
    // quest list) — what was wrong was relying on it to also produce chronological BUCKETS here.
    // Sorting on the key is the whole fix, and it keeps the year-collision fix intact: `day` is the
    // monotonic DaysPassed global, so this is NOT a re-sort on the printed date.
    //
    // Within a day the order is unchanged — game entries in engine order, then any manual notes
    // (themselves already day/createdAt-sorted by CustomJournalRepository). Engine entries carry no
    // intra-day time, so nothing finer is derivable.
    val dayGroups = remember(entries) {
        val byDay = LinkedHashMap<Int, Pair<String, MutableList<JournalEntry>>>()
        entries.forEach { e ->
            byDay.getOrPut(e.day) { journalDateLabel(e) to mutableListOf() }.second.add(e)
        }
        byDay.entries.sortedBy { it.key }
            .map { (_, group) -> group.first to group.second.toList() }
    }

    // ---- Model A: one day per column (page-turn OFF) ----
    val dayPages = remember(dayGroups, pageTurn) {
        if (pageTurn) emptyList()
        else dayGroups.map { (date, dayEntries) ->
            buildList<Pair<String?, JournalEntry?>> {
                add(date to null)
                dayEntries.forEach { add(null to it) }
            }
        }.chunked(2)  // pair days: [leftDay, rightDay]
    }

    // ---- Model B: reflowed columns (page-turn ON) ----
    // The "+ Add Entry" block participates in the flow rather than being tacked onto whichever
    // column happens to be last, so its height is reserved and it can never overhang the page.
    val gameDate by GameStateRepository.gameDate.collectAsState()
    val showAddEntry = gameDate != null
    val topicIndex = rememberTopicIndex(topicNames)
    val measurer = rememberTextMeasurer()
    val headerStyle = journalHeaderStyle()
    val bodyStyle = journalBodyStyle()
    val addEntryStyle = journalAddEntryStyle()
    val density = LocalDensity.current

    // Links inside PAGINATED text route through this rather than a captured callback, because the
    // strings outlive the composition that built them (see JournalTopicLinkHandler). Keyed on Unit
    // over a rememberUpdatedState rather than on the callback itself: `onTopicLink` is rebuilt on
    // every recomposition of JournalPanel, so keying on it would tear this down and set it up again
    // continuously.
    val liveTopicLink = rememberUpdatedState(onTopicLink)
    DisposableEffect(Unit) {
        JournalTopicLinkHandler.current = { liveTopicLink.value(it) }
        onDispose { JournalTopicLinkHandler.current = null }
    }

    BoxWithConstraints(Modifier.fillMaxSize().mwPanel()) {
        // Column geometry, derived from the SAME constants the spread is laid out with. The
        // paginator needs this before the pager exists, because page COUNT now depends on it —
        // which is the whole reason this is a BoxWithConstraints.
        val colWidthPx: Int
        val colHeightPx: Float
        with(density) {
            val spreadW = maxWidth - JOURNAL_SPREAD_H_PAD * 2
            val halfW = (spreadW - JOURNAL_SPINE_WIDTH) / 2
            colWidthPx = (halfW - JOURNAL_COL_H_PAD * 2).toPx().toInt()
            // The dot strip's height is reserved WHETHER OR NOT it draws. It used to render only
            // for >1 page, which under reflow is circular: showing it shortens the column, which
            // can add a page, which makes it show. Reserving unconditionally cuts the loop.
            colHeightPx = (maxHeight - JOURNAL_SPREAD_V_PAD * 2 - JOURNAL_INDICATOR_STRIP -
                JOURNAL_COL_TOP_PAD - JOURNAL_COL_BOTTOM_PAD).toPx()
        }

        val bookPages: List<List<JournalPageItem>> = if (!pageTurn) emptyList() else {
            val signature = JournalPaginationKey(
                entriesHash = entries.hashCode(),
                topicsHash = topicNames.hashCode(),
                widthPx = colWidthPx,
                heightPx = colHeightPx.toInt(),
                fontScale = density.fontScale,
                bodyFont = bodyStyle.fontFamily,
                headerFont = headerStyle.fontFamily,
                showAddEntry = showAddEntry
            )
            JournalPaginationCache.get(signature) {
                // ONE HEADER PER ENTRY, not per day (fixed Aug 10 2026) — vanilla parity, and the
                // fix for "most entries have no date above them" in this model.
                //
                // A per-DAY header is only sound while a day is a whole column, which is Model A's
                // invariant, not this one: reflow cuts a day across pages, so every entry after the
                // first landed under a heading that could be one or more pages back. The engine's
                // own book does exactly what is done here — `AddJournalEntry` (journalbooks.cpp)
                // writes `entry.timestamp()` before EVERY entry, then a section break — so a day
                // with several entries repeats its date, by design and matching the game.
                //
                // Still driven off `dayGroups` rather than walking `entries` on day-change: the day
                // grouping is what carries the year-collision fix (see above), and it keeps
                // same-day entries adjacent regardless of where they came from in the merge.
                val blocks = buildList {
                    dayGroups.forEach { (date, dayEntries) ->
                        dayEntries.forEach { e ->
                            add(JournalPageItem.Header(date))
                            add(
                                JournalPageItem.Body(
                                    buildJournalAnnotated(e.text, topicIndex) {
                                        JournalTopicLinkHandler.current
                                    }
                                )
                            )
                        }
                    }
                    if (showAddEntry) add(JournalPageItem.AddEntry)
                }
                val constraints = Constraints(maxWidth = colWidthPx.coerceAtLeast(1))
                val addEntryHeightPx = with(density) {
                    measurer.measure(
                        AnnotatedString(JOURNAL_ADD_ENTRY_LABEL),
                        style = addEntryStyle, constraints = constraints
                    ).size.height + JOURNAL_ADD_ENTRY_EXTRA_V.toPx()
                }
                paginateJournal(
                    blocks = blocks,
                    measurer = measurer,
                    headerStyle = headerStyle,
                    bodyStyle = bodyStyle,
                    contentWidthPx = colWidthPx,
                    columnHeightPx = colHeightPx,
                    headerPadTopPx = with(density) { JOURNAL_HEADER_PAD_TOP.toPx() },
                    headerPadBottomPx = with(density) { JOURNAL_HEADER_PAD_BOTTOM.toPx() },
                    bodyPadPx = with(density) { JOURNAL_BODY_PAD_BOTTOM.toPx() },
                    addEntryHeightPx = addEntryHeightPx,
                    bodyLineHeightPx = with(density) { bodyStyle.lineHeight.toPx() }
                )
            }
        }

        // Spreads. Both models produce a flat list of COLUMNS in reading order, so pairing them
        // into two-page spreads is identical either way — the reflow never touched this.
        val pageCount = if (pageTurn) (bookPages.size + 1) / 2 else dayPages.size
        JournalSpreadPager(
            pageCount = pageCount,
            pageTurn = pageTurn,
            dayPages = dayPages,
            bookPages = bookPages,
            topicNames = topicNames,
            onTopicLink = onTopicLink,
            addEntryStyle = addEntryStyle,
            headerStyle = headerStyle,
            bodyStyle = bodyStyle
        )
    }
}

/** The label on the manual-entry button. Named because the paginator measures it. */
private const val JOURNAL_ADD_ENTRY_LABEL = "+ Add Manual Entry"

@Composable
private fun JournalSpreadPager(
    pageCount: Int,
    pageTurn: Boolean,
    dayPages: List<List<List<Pair<String?, JournalEntry?>>>>,
    bookPages: List<List<JournalPageItem>>,
    topicNames: List<String>,
    onTopicLink: (String) -> Unit,
    addEntryStyle: TextStyle,
    headerStyle: TextStyle,
    bodyStyle: TextStyle
) {
    val pagerState = rememberPagerState(
        initialPage = (pageCount - 1).coerceAtLeast(0),
        pageCount = { pageCount }
    )
    // initialPage only applies when the state is first created, so a page added while the journal
    // is already open would otherwise sit there unvisited (and unnoticed — the dot indicator just
    // gains one 5dp dot). Follow the new page ONLY if the reader was already on the last one; if
    // they've paged back to read something older, leave them there.
    //
    // Still correct under reflow: the flow is strictly sequential, so appending entries can only
    // ever extend the tail — it never re-breaks a column the reader has already passed. So the
    // count remains monotone and "was on the last page" keeps its meaning.
    var knownPageCount by remember { mutableStateOf(pageCount) }
    LaunchedEffect(pageCount) {
        val previous = knownPageCount
        knownPageCount = pageCount
        if (pageCount > previous && pagerState.currentPage >= previous - 1)
            pagerState.animateScrollToPage(pageCount - 1)
    }

    // Hand the pager to JournalLeafOverlay while (and only while) the flip is actually in use, so
    // the overlay is inert on the plain-slide path and after this screen goes away.
    DisposableEffect(pagerState, pageTurn) {
        if (pageTurn) JournalLeafOverlayState.pagerState = pagerState
        onDispose {
            if (JournalLeafOverlayState.pagerState === pagerState)
                JournalLeafOverlayState.pagerState = null
        }
    }

    /** One half of a spread, whichever model is in play. */
    @Composable
    fun Half(pageIdx: Int, right: Boolean, modifier: Modifier) {
        if (pageTurn) {
            JournalPaginatedColumn(
                items = bookPages.getOrElse(pageIdx * 2 + if (right) 1 else 0) { emptyList() },
                modifier = modifier,
                headerStyle = headerStyle,
                bodyStyle = bodyStyle,
                addEntryStyle = addEntryStyle
            )
        } else {
            val pageDays = dayPages.getOrElse(pageIdx) { emptyList() }
            // The most recent day is the last column of the last page — which is the RIGHT half on
            // a full spread but the LEFT half when the final page holds a single day (odd day
            // count). Comparing against pageDays.size - 1 covers both without a special case, and
            // yields nothing at all for an empty page.
            val col = if (right) 1 else 0
            JournalColumn(
                pageDays.getOrElse(col) { emptyList() }, modifier, topicNames, onTopicLink,
                showAddEntry = pageIdx == pageCount - 1 && pageDays.size - 1 == col
            )
        }
    }

    Column(Modifier.fillMaxSize()) {
        HorizontalPager(
            state = pagerState,
            // The pager's own rect is what the overlay measures each half from. Read from the
            // PAGER, not from a page: pages are translated in the draw phase, so their laid-out
            // bounds would not describe where they actually appear mid-drag.
            modifier = Modifier.weight(1f).onGloballyPositioned {
                JournalLeafOverlayState.pagerBounds = it.boundsInRoot()
            }
        ) { pageIdx ->
            if (!pageTurn) {
                // Plain slide: the pager's own translation carries the whole spread sideways, so
                // there is no stacking, no leaf, and no per-frame draw work at all.
                Row(
                    Modifier.fillMaxSize()
                        .padding(horizontal = JOURNAL_SPREAD_H_PAD, vertical = JOURNAL_SPREAD_V_PAD)
                ) {
                    Half(pageIdx, right = false, modifier = Modifier.weight(1f))
                    Box(Modifier.width(JOURNAL_SPINE_WIDTH).fillMaxHeight().background(BronzeDark))
                    Half(pageIdx, right = true, modifier = Modifier.weight(1f))
                }
                return@HorizontalPager
            }
            val offset = remember(pageIdx) { { pagerState.getOffsetDistanceInPages(pageIdx) } }
            // Every spread is STACKED on the same rect (the graphicsLayer below cancels the pager's
            // slide), so the two pages in play overlap exactly and only the turning leaf moves.
            // Draw order therefore matters: the leaf must sit above the flat page it is uncovering
            // (first half of the turn) or burying (second half). The page nearer its settled
            // position is always the one holding the leaf, so "closest to settled draws on top" is
            // the whole rule. derivedStateOf keeps this to ONE recomposition per turn — it flips at
            // the halfway point, exactly when both leaves are edge-on and the swap can't be seen.
            val onTop by remember(pageIdx) {
                derivedStateOf { abs(pagerState.getOffsetDistanceInPages(pageIdx)) < 0.5f }
            }
            Row(
                Modifier
                    .fillMaxSize()
                    .zIndex(if (onTop) 1f else 0f)
                    .graphicsLayer {
                        val off = offset()
                        // Cancel the pager's slide so the book never travels sideways; the turn is
                        // carried entirely by the leaf. Draw phase, so dragging costs no layout.
                        translationX = -off * size.width
                        // A page a full turn away is off-viewport in the pager's own layout, so it
                        // must not linger on the stack.
                        alpha = if (abs(off) >= 1f) 0f else 1f
                    }
                    .padding(horizontal = JOURNAL_SPREAD_H_PAD, vertical = JOURNAL_SPREAD_V_PAD)
            ) {
                JournalPageHalf(offset, spineAtRight = true, pageIdx = pageIdx,
                    modifier = Modifier.weight(1f)) {
                    Half(pageIdx, right = false, modifier = Modifier.fillMaxSize())
                }
                // The spine itself stays flat — it is the hinge the leaf swings from.
                Box(Modifier.width(JOURNAL_SPINE_WIDTH).fillMaxHeight().background(BronzeDark))
                JournalPageHalf(offset, spineAtRight = false, pageIdx = pageIdx,
                    modifier = Modifier.weight(1f)) {
                    Half(pageIdx, right = true, modifier = Modifier.fillMaxSize())
                }
            }
        }

        // ALWAYS occupies its height, even at one page — see the circularity note where
        // JOURNAL_INDICATOR_STRIP is deducted from the column height.
        Box(
            Modifier.fillMaxWidth().height(JOURNAL_INDICATOR_STRIP),
            contentAlignment = Alignment.TopCenter
        ) {
            if (pageCount in 2..JOURNAL_MAX_DOTS) {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    repeat(pageCount) { idx ->
                        Box(
                            Modifier
                                .padding(horizontal = 3.dp)
                                .size(if (idx == pagerState.currentPage) 7.dp else 5.dp)
                                .clip(CircleShape)
                                .background(
                                    if (idx == pagerState.currentPage) BronzeLight else BronzeDark
                                )
                        )
                    }
                }
            } else if (pageCount > JOURNAL_MAX_DOTS) {
                // A long playthrough reflows into far more pages than the old one-day-per-column
                // model produced, and a Row of dots simply runs off the panel. A counter is the
                // only thing that stays readable at that length.
                Text(
                    "${pagerState.currentPage + 1} / $pageCount",
                    color = BronzeLight, fontSize = 9.sp, fontFamily = MwBody
                )
            }
        }
    }
}

// A leaf is exactly perpendicular to the page at the halfway point of a turn — that is geometry,
// not taste, so it is not a tuning dial. It is named only to keep the intent readable below.
private const val JOURNAL_LEAF_PERPENDICULAR = 90f

// Below this many degrees the page is treated as FLAT. It is the handover point between the
// in-pager copy (drawn at rest) and the overlay copy (drawn while turning) — see
// JournalLeafOverlay. Small enough that the two are pixel-identical when they swap, so the
// handover cannot be seen; the conditions are exact complements (<= here, > there) so there is
// never a frame where neither draws.
private const val JOURNAL_LEAF_FLAT_EPSILON = 0.5f

// Spread geometry, SHARED by the in-pager layout and the overlay's copy of it. The overlay derives
// each half's rect arithmetically from the pager's bounds rather than reading it back from layout,
// because the page Row cancels the pager's scroll in the DRAW phase (translationX) and laid-out
// bounds do not reflect that. These constants are what keep the two in step — change them here,
// never at one of the two use sites.
private val JOURNAL_SPREAD_H_PAD = 6.dp
private val JOURNAL_SPREAD_V_PAD = 4.dp
private val JOURNAL_SPINE_WIDTH = 1.dp

// Draw order for the turning leaf. Must stay BELOW AdaptiveDimOverlay's 40f so the leaf dims with
// everything else, and above the tab bars it is meant to paint over.
private const val JOURNAL_LEAF_OVERLAY_Z = 35f

/**
 * Rotation of one half of a spread, in degrees, for a given pager offset.
 *
 * Extracted to a top-level function because the in-pager half and the overlay copy MUST agree
 * exactly: the overlay shows a half precisely when the in-pager copy hides it. Two copies of this
 * formula would be a silent-divergence bug waiting to happen.
 *
 * `spineAtRight` describes where the hinge is, so it identifies the LEFT column of a spread (its
 * spine is on its right edge) — which rotates only while its page is ARRIVING (offset > 0) — versus
 * the RIGHT column, which rotates only while its page is being LEFT BEHIND (offset < 0).
 */
private fun journalTurnDegrees(off: Float, spineAtRight: Boolean): Float =
    (if (spineAtRight) off.coerceAtLeast(0f) else off.coerceAtMost(0f)) * 180f

// Edge line of a journal page half. 1dp Bronze is the panel-border convention (mwPanel, the
// context menus) — this is that treatment, not a new one.
private val JOURNAL_PAGE_EDGE_WIDTH = 1.dp

/**
 * Draws a page half's THREE outer edges — top, bottom, and the outer side — and never the spine
 * edge, where the two halves meet. A line down the middle of the spread would read as two boxes
 * rather than one open book, and the spine already has its own 1dp divider between the halves.
 *
 * `Modifier.border` is not usable here: it always draws all four sides, and masking one off after
 * the fact would fight the rotation. Three `drawLine` calls are the whole implementation.
 *
 * Which side is the spine comes from the SAME `spineAtRight` flag that drives the hinge and
 * `transformOrigin`, so the two can never disagree: `spineAtRight` marks the LEFT column (hinged on
 * its right edge), whose outer edge is therefore its left, and vice versa.
 *
 * Inset by half the stroke so the line sits fully inside the half's bounds, matching how
 * `Modifier.border` renders.
 */
private fun DrawScope.drawJournalPageEdges(spineAtRight: Boolean) {
    val stroke = JOURNAL_PAGE_EDGE_WIDTH.toPx()
    val inset = stroke / 2f
    val w = size.width
    val h = size.height
    drawLine(Bronze, Offset(0f, inset), Offset(w, inset), stroke)
    drawLine(Bronze, Offset(0f, h - inset), Offset(w, h - inset), stroke)
    // Outer side: the left column's outer edge is its left; the right column's is its right.
    val x = if (spineAtRight) inset else w - inset
    drawLine(Bronze, Offset(x, 0f), Offset(x, h), stroke)
}

/**
 * Handoff between the journal's page halves (inside the pager) and [JournalLeafOverlay] (outside
 * every clip in the journal's own subtree).
 *
 * WHY an overlay at all: the turning leaf has to paint OVER the journal's sub-tab bar and the
 * bottom tab bar to read correctly, and it cannot from where it lives. `HorizontalPager` applies
 * `clipScrollableContainer` internally — a hard clip on the scroll axis with no opt-out (its own
 * KDoc says clipping "is not possible via [modifier] param") — and `mwPanel()` clips the panel on
 * top of that. Neither has any reach over sibling composables regardless.
 *
 * What is published here is deliberately only STABLE data — the pager's state object, its laid-out
 * bounds, and one [GraphicsLayer] per half — all written at composition or layout time. Nothing is
 * written per frame: the overlay reads `pagerState` inside its own draw-phase lambda exactly as the
 * in-pager halves do, so the two are frame-coherent by construction with no state writes during
 * draw (which would risk an invalidation loop).
 */
private object JournalLeafOverlayState {
    /** Non-null only while the chronological journal is showing AND the page-turn pref is on. */
    var pagerState: PagerState? by mutableStateOf(null)
    /** The pager's own laid-out rect in root coordinates. Not transformed, so it is stable. */
    var pagerBounds: Rect by mutableStateOf(Rect.Zero)
    /** Recorded content per half, keyed by (page index, spineAtRight). */
    val halves = mutableStateMapOf<Pair<Int, Boolean>, GraphicsLayer>()
}
// ---- Journal page-turn tuning dials (hand-tune on device; these are starting points) ----
// Camera distance as a MULTIPLE OF THE LEAF'S OWN MEASURED WIDTH. Higher = flatter/weaker
// perspective; lower = more extreme foreshortening.
//
// It is a multiple of the width, NOT a dp constant, because `cameraDistance` is a RAW PIXEL value
// (`GraphicsLayer` KDoc: "The distance is expressed in pixels") whose sane range is set by the size
// of the thing being rotated — the same KDoc recommends "a distance at least as far as the size of
// the view, if the view is to be rotated", warning of artifacts when the rotated view ends up
// partially behind the camera.
//
// The shipped value (0.15) is FAR below that recommendation, and deliberately so: it was chosen on
// device for how dramatic the turn looks now that JournalLeafOverlay draws the leaf unclipped. At
// this multiplier the free edge passes behind the camera after roughly 9° of turn, so the effect
// is knowingly trading geometric correctness for looks. Judge any change to it on device, not
// against the KDoc — and do not "correct" it back toward 1.0+ on principle.
//
// The previous form was `14f * density` (~32px here) against a ~578px-wide leaf — about 5% of the
// documented minimum, so the leaf ballooned under extreme perspective and was then visibly clipped
// by the panel. A density-scaled dp value is simply the wrong shape for this API: density says
// nothing about how large the rotated element is. Do NOT reintroduce one.
private const val JOURNAL_LEAF_CAMERA_WIDTH_FACTOR = 0.15f

// Peak darkness of the crease shadow at the spine, reached when the leaf stands perpendicular.
private const val JOURNAL_LEAF_SHADE_ALPHA = 0.5f
// Fraction of the half's width the crease shadow reaches before fading out.
private const val JOURNAL_LEAF_SHADE_SPREAD = 0.55f

/**
 * One half of a journal spread — either the flat page lying in the book, or the leaf being turned.
 * Which one it is depends on the sign of [offset], so a half swaps roles without any extra state.
 *
 * A real turn moves ONE leaf whose two faces belong to DIFFERENT spreads: turning forward, the
 * front face is the outgoing spread's right column and the back face is the incoming spread's left
 * column. Those live in different pager pages, so the leaf is built from two half-rotations that
 * hand over at the perpendicular, where both are edge-on and the seam is invisible:
 *
 *  - the RIGHT half rotates 0° → -90° while its page is being left behind (offset < 0),
 *  - the LEFT half rotates +90° → 0° while its page is arriving (offset > 0),
 *  - on the other side of zero each half is the flat page underneath and does not rotate at all.
 *
 * Both use the SAME unmirrored `offset * 180` — the mirrored signs of the first attempt are exactly
 * what made the right column appear to bend backwards while the left column fell correctly.
 *
 * Everything here is draw-phase: [offset] is read only inside `graphicsLayer`'s and `drawBehind`'s
 * lambdas, so a drag invalidates draw alone. Composition (and therefore each column's scroll state
 * and `journalAnnotated`'s topic-scan memo) is untouched.
 */
@Composable
private fun JournalPageHalf(
    offset: () -> Float,
    spineAtRight: Boolean,
    pageIdx: Int,
    modifier: Modifier = Modifier,
    content: @Composable () -> Unit
) {
    fun turnDegrees(off: Float) = journalTurnDegrees(off, spineAtRight)
    // Pages are stacked, so a half must be opaque or the spread beneath reads through it. Matches
    // the panel it sits in, including the top-screen opacity setting.
    val pageFill = StonePanel.copy(alpha = LocalPanelOpacity.current)
    // The .adaptiveDimTint() below is for the same reason the fill honours the opacity setting:
    // this half is its own drawn surface, not part of an enclosing tinted panel. Currently INERT —
    // the journal spread is a bottom-screen tab, where LocalTopScreenDim is 0 and the whole screen
    // is dimmed by AdaptiveDimOverlay instead — but it keeps the page in step if it ever moves up.

    // This half's content, recorded so JournalLeafOverlay can replay it OUTSIDE every clip in this
    // subtree. rememberGraphicsLayer releases it automatically when this half leaves composition
    // (pager recycling), which is why the overlay must never hold onto it past that — hence the
    // DisposableEffect below rather than a bare assignment.
    val leafLayer = rememberGraphicsLayer()
    DisposableEffect(pageIdx, spineAtRight, leafLayer) {
        val key = pageIdx to spineAtRight
        JournalLeafOverlayState.halves[key] = leafLayer
        onDispose { JournalLeafOverlayState.halves.remove(key) }
    }

    Box(
        modifier
            .fillMaxHeight()
            // NO rotation here any more — the overlay owns the turning leaf. This half records
            // itself every draw and paints in place ONLY while flat; past the epsilon the overlay
            // is drawing it instead, and drawing it twice would show the clipped copy through the
            // unclipped one. The two conditions are exact complements, so there is no gap.
            .drawWithContent {
                if (size.width <= 0f || size.height <= 0f) {
                    drawContent()
                    return@drawWithContent
                }
                leafLayer.record { this@drawWithContent.drawContent() }
                if (abs(turnDegrees(offset())) <= JOURNAL_LEAF_FLAT_EPSILON) drawLayer(leafLayer)
            }
            .background(pageFill)
            .adaptiveDimTint()
    ) {
        content()
        // Crease shadow + page edges, drawn OVER the text (later child wins). drawBehind on an
        // empty Box keeps both in the draw phase alongside the rotation.
        //
        // The EDGES live here, inside the recorded content, on purpose: JournalLeafOverlay replays
        // this same recorded layer, so the flat page and the turning leaf get the border from ONE
        // source. That is what makes it impossible for a border to pop in at the 0.5° handover
        // between the two — there is no second, overlay-only border to switch on.
        Box(
            Modifier.matchParentSize().drawBehind {
                val f = abs(turnDegrees(offset())) / JOURNAL_LEAF_PERPENDICULAR
                if (f > 0.001f) {                       // flat page: no shading, no cost
                    val shade = Color.Black.copy(
                        alpha = f.coerceAtMost(1f) * JOURNAL_LEAF_SHADE_ALPHA
                    )
                    val reach = size.width * JOURNAL_LEAF_SHADE_SPREAD
                    drawRect(
                        if (spineAtRight)
                            Brush.horizontalGradient(
                                listOf(Color.Transparent, shade),
                                startX = size.width - reach, endX = size.width
                            )
                        else
                            Brush.horizontalGradient(
                                listOf(shade, Color.Transparent), startX = 0f, endX = reach
                            )
                    )
                }
                // After the shadow, so the crease darkens the page but not its edge.
                drawJournalPageEdges(spineAtRight)
            }
        )
    }
}

/**
 * The turning journal leaf, drawn OUTSIDE the journal's own clips so it can sweep over the
 * sub-tab bar above and the bottom tab bar below. Hosted at the CompanionScreen root (see the
 * placement note below) and reading [JournalLeafOverlayState].
 *
 * HOW IT AVOIDS THE Aug 6 2026 FAILURE, which reverted the first attempt at this:
 *  - The 3D transform is applied by **`Modifier.graphicsLayer` only** — the same path already
 *    proven in the pager. That attempt rotated via `Matrix.rotateY` inside a `DrawScope`, which
 *    carries NO perspective term at all (verified in Compose's `Matrix.kt`: on an identity matrix
 *    the `[3,2]` element stays 0, and Compose has no perspective/camera helper). An orthographic
 *    Y-rotation is a pure `cos θ` horizontal squash, which is exactly the reported "no vertical
 *    foreshortening". A `DrawScope` cannot express this transform — its `rotate` is 2D about Z —
 *    so the recorded layer is used ONLY as flat content (`drawLayer` inside an already-rotated
 *    modifier), never as the thing doing the rotating.
 *  - `transformOrigin` is a **fraction** (`TransformOrigin`), which is the correct unit for this
 *    API. The standalone `GraphicsLayer.pivotOffset` is in PIXELS and is deliberately not used;
 *    writing a fraction into it puts the hinge a pixel from the corner, which would fold the leaf
 *    sideways across the spine — the other half of what went wrong.
 *  - `cameraDistance` is in raw pixels, derived from the leaf's measured width.
 *
 * NO POINTER INPUT, deliberately — a Box carrying only drawing modifiers does not consume touches
 * (the dropdown scrim has to add `pointerInput` explicitly to intercept), so the tab bars it paints
 * over stay tappable throughout. Same rule as `AdaptiveDimOverlay`.
 */
@Composable
private fun JournalLeafOverlay() {
    val pagerState = JournalLeafOverlayState.pagerState ?: return
    val bounds = JournalLeafOverlayState.pagerBounds
    if (bounds.width <= 0f || bounds.height <= 0f) return
    val halves = JournalLeafOverlayState.halves
    if (halves.isEmpty()) return

    val density = LocalDensity.current
    // This overlay's own origin, so root-space rects can be placed relative to it. Usually (0,0),
    // but the CompanionScreen root carries imePadding, so it is measured rather than assumed.
    var origin by remember { mutableStateOf(Offset.Zero) }

    Box(
        Modifier
            .fillMaxSize()
            .zIndex(JOURNAL_LEAF_OVERLAY_Z)
            .onGloballyPositioned { origin = it.boundsInRoot().topLeft }
    ) {
        val hPad = with(density) { JOURNAL_SPREAD_H_PAD.toPx() }
        val vPad = with(density) { JOURNAL_SPREAD_V_PAD.toPx() }
        val spine = with(density) { JOURNAL_SPINE_WIDTH.toPx() }
        // Mirrors the in-pager Row: the spread is the pager rect inset by the shared padding, split
        // into two equal halves around the spine. Because each page cancels the pager's scroll in
        // the draw phase, every spread occupies this same rect — so one arithmetic rect serves any
        // page, and there is nothing to re-measure mid-drag.
        val contentW = bounds.width - hPad * 2f
        val contentH = bounds.height - vPad * 2f
        val halfW = (contentW - spine) / 2f
        if (halfW <= 0f || contentH <= 0f) return@Box
        val halfWidthDp = with(density) { halfW.toDp() }
        val halfHeightDp = with(density) { contentH.toDp() }
        val top = bounds.top + vPad

        halves.forEach { (key, layer) ->
            val (pageIdx, spineAtRight) = key
            // spineAtRight == true is the LEFT column (its hinge is on its right edge).
            val left = if (spineAtRight) bounds.left + hPad
                       else bounds.left + hPad + halfW + spine
            Box(
                Modifier
                    .offset {
                        IntOffset(
                            (left - origin.x).roundToInt(),
                            (top - origin.y).roundToInt()
                        )
                    }
                    .size(halfWidthDp, halfHeightDp)
                    .graphicsLayer {
                        val turn = journalTurnDegrees(
                            pagerState.getOffsetDistanceInPages(pageIdx), spineAtRight
                        )
                        val swing = abs(turn)
                        rotationY = turn.coerceIn(
                            -JOURNAL_LEAF_PERPENDICULAR, JOURNAL_LEAF_PERPENDICULAR
                        )
                        // Visible ONLY while actually turning: at rest the in-pager copy draws
                        // (complementary condition), and past the perpendicular this face has
                        // turned away and the other page's half carries the leaf.
                        alpha = if (swing <= JOURNAL_LEAF_FLAT_EPSILON ||
                                    swing > JOURNAL_LEAF_PERPENDICULAR) 0f else 1f
                        cameraDistance = size.width * JOURNAL_LEAF_CAMERA_WIDTH_FACTOR
                        transformOrigin = TransformOrigin(if (spineAtRight) 1f else 0f, 0.5f)
                        // NO clip — being free of it is the entire reason this overlay exists.
                    }
                    // The recorded layer already carries the page's three edges (see
                    // drawJournalPageEdges in JournalPageHalf), so they rotate and foreshorten with
                    // the content for free — and are identical to the flat page's, which is what
                    // makes the handover invisible. Do NOT add a border modifier here: it would be
                    // a second, overlay-only edge that appears the moment a turn starts.
                    .drawBehind { drawLayer(layer) }
            )
        }
    }
}

@Composable
private fun JournalColumn(
    items: List<Pair<String?, JournalEntry?>>,
    modifier: Modifier,
    topicNames: List<String>,
    onTopicLink: (String) -> Unit,
    /**
     * True for the single column holding the most recent day, where the "+ Add Entry" button is
     * drawn. Passed in rather than derived here: only [JournalChronological] knows which page and
     * which half that is.
     */
    showAddEntry: Boolean = false
) {
    val headerStyle = journalHeaderStyle()
    val bodyStyle = journalBodyStyle()
    // verticalScroll lets long entries overflow cleanly rather than clip.
    Column(
        modifier
            .padding(
                start = JOURNAL_COL_H_PAD, end = JOURNAL_COL_H_PAD,
                top = JOURNAL_COL_TOP_PAD, bottom = JOURNAL_COL_BOTTOM_PAD
            )
            .verticalScroll(rememberScrollState())
    ) {
        items.forEachIndexed { idx, (date, entry) ->
            if (date != null) {
                Text(date, style = headerStyle, modifier = Modifier.padding(
                    // Nothing above it to separate from at the head of a column.
                    top = if (idx == 0) 0.dp else JOURNAL_HEADER_PAD_TOP,
                    bottom = JOURNAL_HEADER_PAD_BOTTOM))
            } else if (entry != null) {
                Text(journalAnnotated(entry.text, topicNames, onTopicLink), style = bodyStyle,
                    modifier = Modifier.padding(bottom = JOURNAL_BODY_PAD_BOTTOM))
            }
        }
        if (showAddEntry) AddJournalEntryButton(journalAddEntryStyle())
    }
}

/**
 * A pre-paginated column: exactly what fits, already decided, so nothing here scrolls or clips.
 *
 * A [JournalPageItem.Body] may be a whole entry or a FRAGMENT of one — this draws them identically,
 * which is the point. It is also what makes the page-turn overlay strictly better than before: a
 * half is now fully drawn within its own rect, so the recorded [GraphicsLayer] the leaf replays
 * carries the whole page rather than whatever slice of a scrolling column happened to be visible.
 */
@Composable
private fun JournalPaginatedColumn(
    items: List<JournalPageItem>,
    modifier: Modifier,
    headerStyle: TextStyle,
    bodyStyle: TextStyle,
    addEntryStyle: TextStyle
) {
    Column(
        modifier.padding(
            start = JOURNAL_COL_H_PAD, end = JOURNAL_COL_H_PAD,
            top = JOURNAL_COL_TOP_PAD, bottom = JOURNAL_COL_BOTTOM_PAD
        )
    ) {
        items.forEachIndexed { idx, item ->
            when (item) {
                is JournalPageItem.Header -> Text(
                    item.label, style = headerStyle,
                    modifier = Modifier.padding(
                        // Must mirror headerHeight()'s `first` term in paginateJournal — the
                        // paginator costed this header without a top pad when it leads a column.
                        top = if (idx == 0) 0.dp else JOURNAL_HEADER_PAD_TOP,
                        bottom = JOURNAL_HEADER_PAD_BOTTOM
                    )
                )
                is JournalPageItem.Body -> Text(
                    item.text, style = bodyStyle,
                    modifier = Modifier.padding(bottom = JOURNAL_BODY_PAD_BOTTOM)
                )
                JournalPageItem.AddEntry -> AddJournalEntryButton(addEntryStyle)
            }
        }
    }
}

/**
 * "+ Add Entry" — opens the manual journal composer. Sits at the foot of the most recent day's
 * column, i.e. directly below the newest entry, which is where a reader who has just caught up
 * would reach for it.
 *
 * Gated on a real in-game date being known: an entry can only be filed under the day the engine
 * reports (COMPANION_GAMEDATE), so with no date there is nothing correct to write. It arrives
 * within a second of gameplay starting and does not go away again, so in practice this is only the
 * first moment after a load.
 *
 * Uses "+" rather than a symbol glyph on purpose: the bundled MysticCards game font is missing the
 * arrow/chevron block, which is why FavStar is a vector icon. "+" is plain ASCII and safe.
 */
@Composable
private fun AddJournalEntryButton(style: TextStyle) {
    val gameDate by GameStateRepository.gameDate.collectAsState()
    if (gameDate == null) return
    Box(
        Modifier.fillMaxWidth().padding(top = 8.dp, bottom = 10.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            JOURNAL_ADD_ENTRY_LABEL,
            style = style,
            modifier = Modifier
                .clip(RoundedCornerShape(3.dp))
                .border(1.dp, BronzeDark, RoundedCornerShape(3.dp))
                .clickable { ManualJournalComposerState.open() }
                .padding(horizontal = 10.dp, vertical = 5.dp)
        )
    }
}

@Composable
private fun JournalQuestList(
    groups: List<QuestGroup>,
    // Filter state is OWNED BY JournalPanel, not remembered here: this composable leaves
    // composition on every quest-detail navigation, so state held locally would silently reset the
    // view under the player each time they came back from reading a quest.
    showAll: Boolean,
    showHidden: Boolean,
    onShowAll: (Boolean) -> Unit,
    onShowHidden: (Boolean) -> Unit,
    onQuest: (String) -> Unit
) {
    val questPrefs by QuestPrefsRepository.state.collectAsState()

    // A hidden quest is gone from BOTH the Active and All views regardless of its completion state
    // — hiding is the player's own "I'm done with this" flag, independent of the engine's. Tested
    // across the whole group so a preference stored against any member id still resolves.
    val visible = remember(groups, showAll, showHidden, questPrefs.hidden) {
        val hidden = questPrefs.hidden
        fun isHidden(g: QuestGroup) = g.ids.any { it in hidden }
        when {
            showHidden -> groups.filter { isHidden(it) }
            showAll -> groups.filter { !isHidden(it) }
            else -> groups.filter { !isHidden(it) && !it.finished }
        }
    }

    Column(Modifier.fillMaxSize().mwPanel()) {
        // Toggle buttons: each label reflects the mode it switches TO. Show Hidden (left) and
        // Active/All (right) are exclusive — tapping either drops out of the other's view.
        Row(
            Modifier.fillMaxWidth().padding(horizontal = 10.dp, vertical = 8.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                if (showHidden) "Hide Hidden" else "Show Hidden",
                color = BronzeLight, fontSize = 12.sp, fontFamily = MwBody,
                modifier = Modifier.clickable { onShowHidden(!showHidden) }.padding(4.dp)
            )
            Text(
                if (showAll) "Show Active Only" else "Show All",
                color = BronzeLight, fontSize = 12.sp, fontFamily = MwBody,
                modifier = Modifier.clickable { onShowAll(!showAll) }.padding(4.dp)
            )
        }
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
        if (showHidden && visible.isEmpty()) {
            Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                Text("No hidden quests", color = BoneDim, fontSize = 14.sp, fontFamily = MwBody)
            }
            return@Column
        }
        LazyColumn(Modifier.fillMaxSize().padding(horizontal = 4.dp)) {
            items(visible, key = { it.id }) { group ->
                QuestRow(
                    group = group,
                    hidden = group.ids.any { it in questPrefs.hidden },
                    followed = questPrefs.followed in group.ids,
                    onClick = { onQuest(group.id) }
                )
            }
            item { Spacer(Modifier.height(8.dp)) }
        }
    }
}

/**
 * One quest-list row: tap opens the quest, long-press opens [QuestContextMenu]. Long-press is new
 * to the Journal (every other row here was tap-only), so it follows ItemRow's idiom exactly —
 * combinedClickable + DropdownState so the root-level scrim handles tap-outside dismissal.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun QuestRow(
    group: QuestGroup,
    hidden: Boolean,
    followed: Boolean,
    onClick: () -> Unit
) {
    var menuOpen by remember { mutableStateOf(false) }
    LaunchedEffect(DropdownState.closeRequest) {
        if (DropdownState.closeRequest > 0) menuOpen = false
    }
    val finished = group.finished
    val title = questGroupTitle(group)

    Box {
        Column {
            Row(
                Modifier
                    .fillMaxWidth()
                    .combinedClickable(
                        onClick = onClick,
                        onLongClick = { menuOpen = true; DropdownState.open() }
                    )
                    .padding(horizontal = 10.dp, vertical = 11.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                // Name + (optional) followed star share the flex column so the name truncates
                // before the star, and the star stays a standalone Icon (ItemRow's convention).
                Row(
                    modifier = Modifier.weight(1f).padding(end = 8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        title,
                        color = if (finished) BoneDim else Bone,
                        fontSize = 14.sp, fontFamily = MwBody,
                        maxLines = 1, overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.weight(1f, fill = false)
                    )
                    if (followed) {
                        Spacer(Modifier.width(4.dp))
                        FavStar()
                    }
                }
                Text("▶", color = BronzeLight, fontSize = 13.sp, fontFamily = MwBody)
            }
            Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.4f)))
        }

        QuestContextMenu(
            questId = group.id, groupIds = group.ids, title = title,
            hidden = hidden, followed = followed,
            expanded = menuOpen,
            onDismiss = { menuOpen = false; DropdownState.closeAll() }
        )
    }
}

/**
 * Long-press menu shared by the quest list rows and the HUD's followed-quest label: Hide/Unhide and
 * Follow/Unfollow, each shown in whichever direction the quest's CURRENT state allows. Available
 * regardless of active/finished/hidden status. Styled as ItemContextMenu.
 */
@Composable
private fun QuestContextMenu(
    questId: String,
    // Every quest id in this log. Hiding writes the representative id, but UNHIDING has to clear
    // all of them: the row reads as hidden while ANY member is in the set, so clearing only the
    // representative could leave it stuck out of view (and a set stored before quest logs were
    // grouped may hold a non-representative member).
    groupIds: Set<String> = setOf(questId),
    title: String,
    hidden: Boolean,
    followed: Boolean,
    expanded: Boolean,
    onDismiss: () -> Unit
) {
    val context = LocalContext.current
    CompanionDropdownMenu(
        expanded = expanded,
        onDismissRequest = { onDismiss() }
    ) {
        Text(
            title,
            color = BronzeLight,
            fontSize = 12.sp,
            fontFamily = MwDisplay,
            fontWeight = FontWeight.Bold,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier.widthIn(max = 220.dp).padding(horizontal = 12.dp, vertical = 8.dp)
        )
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
        val menuItemColors = MenuDefaults.itemColors(textColor = Bone)
        DropdownMenuItem(
            text = {
                Text(if (hidden) "Unhide Quest" else "Hide Quest",
                    fontFamily = MwBody, fontSize = 13.sp)
            },
            onClick = {
                onDismiss()
                if (hidden) groupIds.forEach { QuestPrefsRepository.unhide(context, it) }
                else QuestPrefsRepository.hide(context, questId)
            },
            colors = menuItemColors
        )
        DropdownMenuItem(
            text = {
                Text(if (followed) "Unfollow Quest" else "Follow Quest on HUD",
                    fontFamily = MwBody, fontSize = 13.sp)
            },
            onClick = {
                onDismiss()
                // Following a different quest replaces the current one — only ever one at a time.
                if (followed) QuestPrefsRepository.unfollow(context)
                else QuestPrefsRepository.follow(context, questId)
            },
            colors = menuItemColors
        )
    }
}

@Composable
private fun JournalQuestDetail(
    group: QuestGroup,
    entries: List<JournalEntry>,
    onBack: () -> Unit,
    topicNames: List<String>,
    onTopicLink: (String) -> Unit
) {
    val title = questGroupTitle(group)
    // The manual pseudo-quest renders from the CustomJournalEntry list rather than the projected
    // JournalEntry one, purely so each row carries its own stable id to delete by. Resolving the id
    // positionally against the merged list would work today but only because both happen to be in
    // the same order — an invariant nothing enforces.
    val isManual = MANUAL_QUEST_ID in group.ids
    val customEntries by CustomJournalRepository.state.collectAsState()

    Column(Modifier.fillMaxSize().mwPanel()) {
        JournalNavBar(left = "Quests", onLeft = onBack, center = title, right = null, onRight = null)
        LazyColumn(Modifier.fillMaxSize().padding(horizontal = 4.dp)) {
            if (isManual) {
                items(customEntries, key = { it.id }) { custom ->
                    JournalEntryBlock(
                        entry = custom.toJournalEntry(),
                        topicNames = topicNames,
                        onTopicLink = onTopicLink,
                        customEntryId = custom.id
                    )
                }
            } else {
                items(entries, key = { e -> "e:${e.day}:${e.dayOfMonth}:${e.text.length}" }) { entry ->
                    // customEntryId null ⇒ no long-press menu. Real journal entries are the game's
                    // record and must never be deletable.
                    JournalEntryBlock(entry, topicNames, onTopicLink, customEntryId = null)
                }
            }
            item { Spacer(Modifier.height(8.dp)) }
        }
    }
}

/**
 * One dated entry in a quest's detail page: date header + body, with topic links.
 *
 * When [customEntryId] is non-null the entry is one the PLAYER wrote, and a long press opens
 * [ManualEntryContextMenu] to delete it — following QuestRow's idiom (combinedClickable +
 * DropdownState, so the root-level scrim handles tap-outside dismissal for free). A null id means a
 * real game entry: no long press, nothing to delete.
 *
 * NOTE the long press is attached to the whole block, which includes the non-link date header and
 * the padding around the text — so there is always somewhere reliable to press even though a topic
 * link inside the body may swallow the gesture over its own span.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun JournalEntryBlock(
    entry: JournalEntry,
    topicNames: List<String>,
    onTopicLink: (String) -> Unit,
    customEntryId: String?
) {
    var menuOpen by remember { mutableStateOf(false) }
    LaunchedEffect(DropdownState.closeRequest) {
        if (DropdownState.closeRequest > 0) menuOpen = false
    }

    Box {
        Column(
            Modifier
                .fillMaxWidth()
                .then(
                    if (customEntryId == null) Modifier
                    else Modifier.combinedClickable(
                        // Tap does nothing: these are read-only notes, and the only action is the
                        // long-press menu. onClick is required by combinedClickable.
                        onClick = {},
                        onLongClick = { menuOpen = true; DropdownState.open() }
                    )
                )
        ) {
            Text(journalDateLabel(entry), color = BronzeLight, fontSize = 12.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                modifier = Modifier.padding(start = 10.dp, top = 10.dp, bottom = 2.dp))
            Text(journalAnnotated(entry.text, topicNames, onTopicLink),
                color = Bone, fontSize = 14.sp, fontFamily = MwBody,
                lineHeight = 20.sp,
                modifier = Modifier.padding(start = 10.dp, end = 10.dp, bottom = 6.dp))
        }

        if (customEntryId != null) {
            ManualEntryContextMenu(
                entryId = customEntryId,
                expanded = menuOpen,
                onDismiss = { menuOpen = false; DropdownState.closeAll() }
            )
        }
    }
}

/**
 * Long-press menu for a player-written journal entry. Delete only — editing is deliberately not
 * built yet; delete-and-retype covers the same ground until it is. Styled as QuestContextMenu.
 */
@Composable
private fun ManualEntryContextMenu(
    entryId: String,
    expanded: Boolean,
    onDismiss: () -> Unit
) {
    CompanionDropdownMenu(
        expanded = expanded,
        onDismissRequest = { onDismiss() }
    ) {
        Text(
            MANUAL_QUEST_NAME,
            color = BronzeLight,
            fontSize = 12.sp,
            fontFamily = MwDisplay,
            fontWeight = FontWeight.Bold,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
            modifier = Modifier.widthIn(max = 220.dp).padding(horizontal = 12.dp, vertical = 8.dp)
        )
        Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark))
        DropdownMenuItem(
            text = { Text("Delete Entry", fontFamily = MwBody, fontSize = 13.sp) },
            onClick = {
                onDismiss()
                CustomJournalRepository.delete(entryId)
            },
            colors = MenuDefaults.itemColors(textColor = Bone)
        )
    }
}

/**
 * The name shown for a quest log — the QS_Name response, VERBATIM.
 *
 * It is already the exact string vanilla's journal prints ("Temple: Pilgrimages of the Seven
 * Graces"), so it is not re-cased. The word-by-word title-casing that used to be applied here was
 * for the days when the name could be a record id in disguise; on real names it only mangled them
 * ("Pilgrimages Of The Seven Graces"), and record ids no longer reach this function at all — a
 * quest without a QS_Name is not a quest as far as the journal is concerned, and is now dropped in
 * `exportQuests`.
 *
 * The id fallback survives for one case only: a [QuestGroup] synthesised for a selection that no
 * longer matches any exported quest (see JournalPanel), which has no name to show.
 */
private fun questGroupTitle(group: QuestGroup): String =
    group.name.ifEmpty { prettifyQuestId(group.id) }

private fun prettifyQuestId(id: String): String {
    val parts = id.split(Regex("[\\s_]+")).filter { it.isNotEmpty() }
    val body = parts.dropWhile { it.length <= 3 || it.all { c -> c.isDigit() } }.ifEmpty { parts }
    return body.joinToString(" ") { it.replaceFirstChar { c -> c.uppercaseChar() } }
}

@Composable
private fun EmptyPanel(message: String) {
    Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
        Text(message, color = BoneDim, fontSize = 15.sp, fontFamily = MwBody)
    }
}

/* ---- Stats ---- */

/**
 * What a tapped stat row opens a popup for. Each variant carries the data it
 * needs; [toContent] renders it into the shared [StatInfoPopup] layout.
 */
private sealed interface StatInfo {
    data class AttributeInfo(val attr: AttributeStat) : StatInfo
    data class SkillInfo(val skill: SkillStat) : StatInfo
    data class DynamicInfo(val label: String, val value: Dynamic, val desc: String) : StatInfo
    data class LevelInfo(val level: Int, val progress: Int, val total: Int) : StatInfo
    data class RaceInfo(val character: CharacterInfo) : StatInfo
    data class BirthSignInfo(
        val name: String, val desc: String, val spells: List<String>, val texture: String
    ) : StatInfo
    data class ClassInfo(val character: CharacterInfo) : StatInfo
    data class FactionInfo(val faction: FactionMembership) : StatInfo
    data class ReputationInfo(val value: Int) : StatInfo
    data class BountyInfo(val value: Int) : StatInfo
    data class ActiveEffectInfo(val effect: ActiveEffect) : StatInfo
}

/** Uniform, render-ready popup contents produced from any [StatInfo]. */
private data class StatPopupContent(
    val title: String,
    val rows: List<Pair<String, String>>,
    val sections: List<Pair<String, List<String>>>,
    val description: String,
    /** VFS icon path for the header, "" when the popup has no icon. */
    val icon: String = "",
    /** Optional large body image (VFS path) shown below the title; "" = none. */
    val bodyImage: String = "",
    /** Optional progress bar (skill increase / level-up progress). */
    val progress: StatProgress? = null,
    /** Header title color; defaults to the usual BronzeLight. */
    val titleColor: Color = BronzeLight,
    /** Optional per-row value colors, aligned by index with [rows]; null/absent = Bone. */
    val rowValueColors: List<Color?> = emptyList()
)

/** A labelled 0..1 progress bar with a caption line beneath it. */
private data class StatProgress(val label: String, val ratio: Float, val caption: String)

private fun capWord(s: String): String =
    if (s.isBlank()) s else s.replaceFirstChar { it.uppercase() }

private fun StatInfo.toContent(showEffectTimer: Boolean = true): StatPopupContent = when (this) {
    is StatInfo.AttributeInfo -> StatPopupContent(
        title = attr.name.ifBlank { attr.id },
        rows = listOf(
            "Current" to attr.current.toInt().toString(),
            "Base" to attr.base.toInt().toString()
        ),
        sections = if (attr.governedSkills.isNotEmpty())
            listOf("Governed Skills" to attr.governedSkills) else emptyList(),
        description = attr.desc,
        icon = attr.icon
    )
    is StatInfo.SkillInfo -> StatPopupContent(
        title = skill.name.ifBlank { skill.id },
        rows = listOf(
            "Value" to skill.value.toInt().toString(),
            "Category" to capWord(skill.category),
            "Governing Attribute" to skill.governingAttribute,
            "Specialization" to skill.specialization
        ).filter { it.second.isNotBlank() },
        sections = emptyList(),
        description = skill.desc,
        icon = skill.icon,
        // Per-skill progress toward the next skill increase ([0-1] from the
        // engine's SkillStat.progress). Caption shows the rounded percentage.
        progress = skill.progress.coerceIn(0f, 1f).let { r ->
            StatProgress("Progress", r, "${(r * 100).toInt()}% to next increase")
        }
    )
    is StatInfo.DynamicInfo -> StatPopupContent(
        title = label,
        rows = listOf(
            "Current" to value.current.toInt().toString(),
            "Maximum" to value.max.toInt().toString()
        ),
        sections = emptyList(),
        description = desc
    )
    is StatInfo.LevelInfo -> StatPopupContent(
        title = "Level $level",
        rows = buildList {
            add("Level" to level.toString())
            if (total > 0) add("Progress to Next" to "$progress / $total")
        },
        sections = emptyList(),
        description = "",
        progress = if (total > 0)
            StatProgress(
                "Level Progress",
                (progress.toFloat() / total).coerceIn(0f, 1f),
                "$progress / $total increases"
            ) else null
    )
    is StatInfo.RaceInfo -> StatPopupContent(
        title = character.race.ifBlank { "Race" },
        rows = emptyList(),
        sections = buildList {
            if (character.raceSkillBonuses.isNotEmpty())
                add("Skill Bonuses" to character.raceSkillBonuses)
            if (character.raceAbilities.isNotEmpty())
                add("Abilities" to character.raceAbilities)
        },
        description = character.raceDesc
    )
    is StatInfo.BirthSignInfo -> StatPopupContent(
        title = name.ifBlank { "Birthsign" },
        rows = emptyList(),
        sections = if (spells.isNotEmpty()) listOf("Abilities" to spells) else emptyList(),
        description = desc,
        bodyImage = texture
    )
    is StatInfo.ClassInfo -> StatPopupContent(
        title = character.className.ifBlank { "Class" },
        rows = if (character.classSpecialization.isNotBlank())
            listOf("Specialization" to character.classSpecialization) else emptyList(),
        sections = buildList {
            if (character.classFavoredAttributes.isNotEmpty())
                add("Favored Attributes" to character.classFavoredAttributes)
            if (character.classMajorSkills.isNotEmpty())
                add("Major Skills" to character.classMajorSkills)
            if (character.classMinorSkills.isNotEmpty())
                add("Minor Skills" to character.classMinorSkills)
        },
        description = character.classDesc
    )
    is StatInfo.FactionInfo -> StatPopupContent(
        title = faction.name.ifBlank { faction.id },
        rows = buildList {
            if (faction.rankName.isNotBlank()) add("Rank" to faction.rankName)
            if (faction.rank > 0) add("Rank Number" to faction.rank.toString())
        },
        sections = emptyList(),
        description = ""
    )
    is StatInfo.ReputationInfo -> StatPopupContent(
        title = "Reputation",
        rows = listOf("Reputation" to value.toString()),
        sections = emptyList(),
        description = "Reputation reflects your renown across Vvardenfell. Higher " +
            "reputation improves NPC disposition toward you, which in turn lowers " +
            "merchant prices and makes people more willing to help."
    )
    is StatInfo.BountyInfo -> StatPopupContent(
        title = "Bounty",
        rows = listOf("Bounty" to value.toString()),
        sections = emptyList(),
        description = "Your bounty is the total fine for crimes witnessed by others. " +
            "While it is above zero, guards will demand you pay the fine, go to jail, " +
            "or resist arrest. Clearing it restores your standing with the law.",
        // Match the row's red-when-wanted styling in the popup header.
        titleColor = if (value > 0) Color(0xFFC75C5C) else BronzeLight
    )
    is StatInfo.ActiveEffectInfo -> StatPopupContent(
        // No description is exported for effects — just name, type, source, magnitude, icon.
        title = effect.name,
        rows = buildList {
            add("Type" to if (effect.harmful) "Harmful" else "Beneficial")
            if (effect.source.isNotBlank()) add("Source" to effect.source)
            if (effect.magnitude > 0) add("Magnitude" to "${effect.magnitude} pts")
            // Its own row rather than tacked onto the subtitle, because this popup renders rows
            // and never calls effectSubtitle. Absent for permanent effects (null remaining).
            if (showEffectTimer) {
                effect.remainingSeconds?.let { add("Time remaining" to formatRemaining(it)) }
            }
        },
        sections = emptyList(),
        description = "",
        icon = effect.icon,
        // Colour only the Type value (index 0): red when harmful, dim when beneficial.
        rowValueColors = listOf(if (effect.harmful) Color(0xFFC75C5C) else BoneDim)
    )
}

/**
 * Remaining time on a timed effect, from the already-quantized seconds the exporter sends: "45s"
 * below a minute, "12m" above. The unit split mirrors the engine's own `ToolTips::getDurationString`
 * — a per-second countdown on a twenty-minute buff is noise, not information.
 *
 * The value is rendered exactly as received, never extrapolated locally: its underlying counter
 * stops while the game is paused, and this UI is read over paused screens constantly. See
 * [ActiveEffect.remainingSeconds].
 */
private fun formatRemaining(seconds: Int): String =
    if (seconds < 60) "${seconds}s" else "${seconds / 60}m"

/**
 * Vanilla-style effect subtitle: "<source>: <mag> pts", or just the source / just
 * the magnitude when only one is available; "" when neither is.
 *
 * With [showTimer] on, a timed effect appends its remaining duration ("Warwyrd: 10 pts — 45s").
 * A PERMANENT effect appends nothing whatever the toggle says, because `remainingSeconds` is null
 * for it — so the switch only ever changes what timed effects show.
 *
 * The timer is PARENTHESISED rather than set off by a separator. It used to be an em dash, chosen
 * because the game typeface (MysticCards) has no `·` glyph and `—` is one of the few punctuation
 * marks it does carry — but em dashes are now out of the app's text entirely, and brackets say
 * "this is how long is left" more plainly than any separator did.
 */
private fun effectSubtitle(e: ActiveEffect, showTimer: Boolean = true): String {
    val base = when {
        e.source.isNotBlank() && e.magnitude > 0 -> "${e.source}: ${e.magnitude} pts"
        e.source.isNotBlank() -> e.source
        e.magnitude > 0 -> "${e.magnitude} pts"
        else -> ""
    }
    val timer = if (showTimer) e.remainingSeconds?.let(::formatRemaining) else null
    return when {
        timer == null -> base
        base.isEmpty() -> timer
        else -> "$base ($timer)"
    }
}

/**
 * Shared stat detail popup. In-window overlay (NOT a Dialog — the companion UI
 * lives in a Presentation on a secondary display where Dialog throws a window
 * type mismatch), mirroring ItemInfoOverlay: full-screen scrim dismisses on tap,
 * the panel swallows its own taps.
 */
@Composable
private fun StatInfoPopup(info: StatInfo, onDismiss: () -> Unit) {
    // Remembered so collectAsState keys on ONE flow instance: effectTimersFlow() returns a fresh
    // asStateFlow() wrapper per call, which would otherwise restart the collection on every
    // recomposition (the documented inline-accessor trap).
    val effectTimersFlow = remember { UiPreferences.effectTimersFlow() }
    val showEffectTimer by effectTimersFlow.collectAsState()
    val content = info.toContent(showEffectTimer)
    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(20f)
            .background(Color(0xB3000000))
            .pointerInput(Unit) { detectTapGestures(onTap = { onDismiss() }) },
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .width(420.dp)
                .heightIn(max = 560.dp)
                .mwPanel()
                .pointerInput(Unit) { detectTapGestures(onTap = {}) }
                .padding(16.dp)
                .verticalScroll(rememberScrollState())
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                if (content.icon.isNotBlank()) {
                    val headerIcon = rememberItemIcon(content.icon)
                    Box(
                        modifier = Modifier
                            .size(32.dp)
                            .clip(RoundedCornerShape(2.dp))
                            .background(SlotBg)
                            .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
                    ) {
                        if (headerIcon != null) {
                            Image(
                                bitmap = headerIcon,
                                contentDescription = null,
                                contentScale = ContentScale.Fit,
                                modifier = Modifier.fillMaxSize()
                            )
                        }
                    }
                    Spacer(Modifier.width(10.dp))
                }
                Text(
                    content.title,
                    color = content.titleColor,
                    fontSize = 16.sp,
                    fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold
                )
            }
            Spacer(Modifier.height(10.dp))

            // Optional large portrait art below the title (e.g. the birthsign
            // sign image), framed like the app's other art slots. Loaded through
            // the same rememberItemIcon pipeline as icons — the path is a uniform
            // VFS texture path. Only rendered once the bitmap resolves.
            if (content.bodyImage.isNotBlank()) {
                val bodyBitmap = rememberItemIcon(content.bodyImage)
                if (bodyBitmap != null) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(160.dp)
                            .clip(RoundedCornerShape(2.dp))
                            .background(SlotBg)
                            .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
                            .padding(6.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Image(
                            bitmap = bodyBitmap,
                            contentDescription = null,
                            contentScale = ContentScale.Fit,
                            modifier = Modifier.fillMaxSize()
                        )
                    }
                    Spacer(Modifier.height(12.dp))
                }
            }

            content.rows.forEachIndexed { i, (label, value) ->
                if (i > 0) Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.5f)))
                Row(
                    modifier = Modifier.fillMaxWidth().padding(vertical = 7.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(label, color = BoneDim, fontSize = 12.sp, fontFamily = MwBody)
                    Text(
                        value,
                        color = content.rowValueColors.getOrNull(i) ?: Bone,
                        fontSize = 12.sp,
                        fontFamily = MwData,
                        modifier = Modifier.padding(start = 12.dp)
                    )
                }
            }

            content.sections.forEach { (heading, items) ->
                Spacer(Modifier.height(10.dp))
                Text(
                    heading.uppercase(),
                    color = BronzeLight,
                    fontSize = 11.sp,
                    fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold,
                    letterSpacing = 0.8.sp
                )
                Spacer(Modifier.height(4.dp))
                items.forEach { item ->
                    Text(
                        item,
                        color = Bone,
                        fontSize = 12.sp,
                        fontFamily = MwBody,
                        modifier = Modifier.padding(vertical = 3.dp)
                    )
                }
            }

            content.progress?.let { p ->
                Spacer(Modifier.height(14.dp))
                Text(
                    p.label.uppercase(),
                    color = BoneDim,
                    fontSize = 11.sp,
                    fontFamily = MwBody,
                    letterSpacing = 0.8.sp
                )
                Spacer(Modifier.height(5.dp))
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(6.dp)
                        .clip(RoundedCornerShape(1.dp))
                        .background(Color(0xFF0E0B07))
                        .border(1.dp, BronzeDark, RoundedCornerShape(1.dp))
                ) {
                    Box(
                        modifier = Modifier
                            .fillMaxWidth(p.ratio)
                            .height(6.dp)
                            .clip(RoundedCornerShape(1.dp))
                            .background(BronzeLight)
                    )
                }
                Spacer(Modifier.height(4.dp))
                Text(p.caption, color = BoneDim, fontSize = 11.sp, fontFamily = MwBody)
            }

            if (content.description.isNotBlank()) {
                Spacer(Modifier.height(12.dp))
                Box(Modifier.fillMaxWidth().height(1.dp).background(BronzeDark.copy(alpha = 0.5f)))
                Spacer(Modifier.height(10.dp))
                Text(
                    content.description,
                    color = Bone,
                    fontSize = 13.sp,
                    fontFamily = MwBody,
                    lineHeight = 18.sp
                )
            }
        }
    }
}

/**
 * Width of the Stats tab's left column (vitals + attributes + active effects).
 *
 * Widened 165 → 200dp Aug 10 2026, paid for by folding Minor skills into the Major column so the
 * skills panel needs two columns instead of three. The whole tab was cramped and this is the one
 * budget that governs it — the panel is 537.7dp wide (1240px at density 369), so:
 *
 *   skills panel = 537.7 − 24 (tab padding) − 8 (row gap) − LEFT
 *   per column   = (skills panel − 20 (mwPanel padding) − 1 (divider)) / 2 − 16 (column padding)
 *
 * At 165dp with THREE columns that left ~90dp of usable text per column, which is not enough for
 * "Restoration" + its value; at 200dp with two it is ~126dp, and the left column gains 35dp with it.
 * Raising this further keeps working until the skill columns drop back under ~95dp (around 260dp).
 */
private val STATS_LEFT_WIDTH = 200.dp

@Composable
private fun StatsPanel(state: GameState, onSelectStat: (StatInfo) -> Unit) {
    val character = state.character

    Column(
        Modifier
            .fillMaxSize()
            .padding(top = 12.dp, bottom = BOTTOM_BAR_SPACE.dp, start = 12.dp, end = 12.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        CharacterHeaderPanel(character, onSelectStat)

        Row(
            Modifier.fillMaxWidth().weight(1f),
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            AttributesAndEffectsPanel(
                state = state,
                modifier = Modifier.width(STATS_LEFT_WIDTH).fillMaxHeight(),
                onSelectStat = onSelectStat
            )
            SkillsPanel(
                skills = character.skills,
                modifier = Modifier.weight(1f).fillMaxHeight(),
                onSelectStat = onSelectStat
            )
        }
    }
}

@Composable
private fun CharacterHeaderPanel(character: CharacterInfo, onSelectStat: (StatInfo) -> Unit) {
    Row(
        Modifier
            .fillMaxWidth()
            .mwPanel()
            .padding(horizontal = 14.dp, vertical = 10.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column {
            Text(
                character.name.ifBlank { "-" },
                color = Bone, fontSize = 18.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.SemiBold
            )
            // Race · Class · Birthsign — all three are tappable for their popups.
            val hasSubtitle = listOf(character.race, character.className, character.birthSign)
                .any { it.isNotBlank() }
            if (hasSubtitle) {
                Spacer(Modifier.height(2.dp))
                Row(verticalAlignment = Alignment.CenterVertically) {
                    if (character.race.isNotBlank()) {
                        Text(
                            character.race, color = BoneDim, fontSize = 12.sp, fontFamily = MwBody,
                            modifier = Modifier.clickable { onSelectStat(StatInfo.RaceInfo(character)) }
                        )
                    }
                    if (character.className.isNotBlank()) {
                        if (character.race.isNotBlank())
                            Text(" · ", color = BoneDim, fontSize = 12.sp, fontFamily = MwBody)
                        Text(
                            character.className, color = BoneDim, fontSize = 12.sp, fontFamily = MwBody,
                            modifier = Modifier.clickable { onSelectStat(StatInfo.ClassInfo(character)) }
                        )
                    }
                    if (character.birthSign.isNotBlank()) {
                        if (character.race.isNotBlank() || character.className.isNotBlank())
                            Text(" · ", color = BoneDim, fontSize = 12.sp, fontFamily = MwBody)
                        Text(
                            character.birthSign, color = BoneDim, fontSize = 12.sp, fontFamily = MwBody,
                            modifier = Modifier.clickable {
                                onSelectStat(
                                    StatInfo.BirthSignInfo(
                                        character.birthSign,
                                        character.birthSignDesc,
                                        character.birthSignSpells,
                                        character.birthSignTexture
                                    )
                                )
                            }
                        )
                    }
                }
            }
        }
        Column(
            modifier = Modifier
                .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
                .clickable {
                    onSelectStat(
                        StatInfo.LevelInfo(character.level, character.levelProgress, character.levelTotal)
                    )
                }
                .padding(horizontal = 12.dp, vertical = 6.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                "${character.level}",
                color = BronzeLight, fontSize = 20.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold
            )
            Text(
                "LEVEL",
                color = BoneDim, fontSize = 9.sp, fontFamily = MwDisplay,
                fontWeight = FontWeight.Bold
            )
        }
    }
}

@Composable
private fun AttributesAndEffectsPanel(
    state: GameState,
    modifier: Modifier = Modifier,
    onSelectStat: (StatInfo) -> Unit
) {
    val character = state.character
    Column(
        modifier.mwPanel().padding(10.dp).verticalScroll(rememberScrollState())
    ) {
        SpellSectionHeader("Vitals")
        Column(Modifier.padding(top = 4.dp)) {
            VitalRow("Health", state.health, HealthCol) {
                onSelectStat(StatInfo.DynamicInfo("Health", state.health, character.healthDesc))
            }
            VitalRow("Magicka", state.magicka, MagickaCol) {
                onSelectStat(StatInfo.DynamicInfo("Magicka", state.magicka, character.magickaDesc))
            }
            VitalRow("Fatigue", state.fatigue, FatigueCol) {
                onSelectStat(StatInfo.DynamicInfo("Fatigue", state.fatigue, character.fatigueDesc))
            }
        }

        Spacer(Modifier.height(4.dp))
        SpellSectionHeader("Attributes")
        Column(Modifier.padding(top = 4.dp)) {
            character.attributes.forEach { attr ->
                AttributeRow(attr) { onSelectStat(StatInfo.AttributeInfo(attr)) }
            }
        }

        Spacer(Modifier.height(4.dp))
        SpellSectionHeader("Standing")
        Column(Modifier.padding(top = 4.dp)) {
            StandingRow("Reputation", character.reputation.toString(), BronzeLight) {
                onSelectStat(StatInfo.ReputationInfo(character.reputation))
            }
            // Bounty in red when the player is wanted, dim when clean.
            StandingRow(
                "Bounty", character.bounty.toString(),
                if (character.bounty > 0) Color(0xFFC75C5C) else BoneDim
            ) {
                onSelectStat(StatInfo.BountyInfo(character.bounty))
            }
        }

        Spacer(Modifier.height(4.dp))
        SpellSectionHeader("Factions")
        if (character.factions.isEmpty()) {
            Text(
                "None",
                color = BoneDim, fontSize = 12.sp, fontFamily = MwBody,
                fontStyle = FontStyle.Italic,
                modifier = Modifier.padding(top = 6.dp, start = 2.dp)
            )
        } else {
            Column(Modifier.padding(top = 4.dp)) {
                character.factions.forEach { faction ->
                    FactionRow(faction) { onSelectStat(StatInfo.FactionInfo(faction)) }
                }
            }
        }

        Spacer(Modifier.height(4.dp))
        SpellSectionHeader("Active Effects")
        if (state.activeEffects.isEmpty()) {
            Text(
                "No active effects",
                color = BoneDim, fontSize = 12.sp, fontFamily = MwBody,
                fontStyle = FontStyle.Italic,
                modifier = Modifier.padding(top = 6.dp, start = 2.dp)
            )
        } else {
            // Collected once for the whole list rather than per row — see the same note in
            // TopStatBar.
            val effectTimersFlow = remember { UiPreferences.effectTimersFlow() }
            val showEffectTimer by effectTimersFlow.collectAsState()
            Column(Modifier.padding(top = 4.dp)) {
                state.activeEffects.forEach { effect ->
                    ActiveEffectRow(
                        effect,
                        showTimer = showEffectTimer,
                        onTap = { onSelectStat(StatInfo.ActiveEffectInfo(effect)) }
                    )
                }
            }
        }
    }
}

@Composable
private fun StandingRow(label: String, value: String, valueColor: Color, onClick: () -> Unit) {
    Row(
        Modifier.fillMaxWidth().clickable(onClick = onClick).padding(vertical = 3.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(label, color = Bone, fontSize = 13.sp, fontFamily = MwBody)
        Text(
            value,
            color = valueColor, fontSize = 13.sp,
            fontFamily = MwData, fontWeight = FontWeight.Bold
        )
    }
}

@Composable
private fun FactionRow(faction: FactionMembership, onClick: () -> Unit) {
    // Rank title is intentionally omitted here — it's revealed in the tap popup.
    Row(
        Modifier.fillMaxWidth().clickable(onClick = onClick).padding(vertical = 3.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            faction.name.ifBlank { faction.id },
            color = Bone, fontSize = 13.sp, fontFamily = MwBody,
            maxLines = 1, overflow = TextOverflow.Ellipsis,
            modifier = Modifier.weight(1f)
        )
    }
}

@Composable
private fun VitalRow(label: String, value: Dynamic, barColor: Color, onClick: () -> Unit) {
    Row(
        Modifier.fillMaxWidth().clickable(onClick = onClick).padding(vertical = 3.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(label, color = Bone, fontSize = 13.sp, fontFamily = MwBody)
        Row(verticalAlignment = Alignment.CenterVertically) {
            Box(
                Modifier
                    .padding(end = 6.dp)
                    .size(6.dp)
                    .clip(CircleShape)
                    .background(barColor)
            )
            Text(
                "${value.current.toInt()}",
                color = BronzeLight, fontSize = 13.sp,
                fontFamily = MwData, fontWeight = FontWeight.Bold
            )
            Text(
                " / ${value.max.toInt()}",
                color = BoneDim, fontSize = 13.sp, fontFamily = MwData
            )
        }
    }
}

@Composable
private fun AttributeRow(attr: AttributeStat, onClick: () -> Unit) {
    val diff = attr.current - attr.base
    val currentColor = when {
        diff > 0.01f -> Color(0xFF7FBF7F)
        diff < -0.01f -> Color(0xFFC75C5C)
        else -> BronzeLight
    }
    Row(
        Modifier.fillMaxWidth().clickable(onClick = onClick).padding(vertical = 3.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            attr.name.ifBlank { attr.id },
            color = Bone, fontSize = 13.sp, fontFamily = MwBody
        )
        Row {
            Text(
                "${attr.current.toInt()}",
                color = currentColor, fontSize = 13.sp,
                fontFamily = MwData, fontWeight = FontWeight.Bold
            )
            Text(
                " / ${attr.base.toInt()}",
                color = BoneDim, fontSize = 13.sp, fontFamily = MwData
            )
        }
    }
}

@Composable
private fun ActiveEffectRow(
    effect: ActiveEffect,
    showTimer: Boolean = true,
    onTap: (() -> Unit)? = null
) {
    // Vanilla layout: effect icon, then the effect name, with "<source>: <mag> pts"
    // beneath it (e.g. "Fortify Attack" / "Warwyrd: 10 pts").
    val icon = rememberItemIcon(effect.icon)
    val subtitle = effectSubtitle(effect, showTimer)
    Row(
        Modifier
            .fillMaxWidth()
            .let { if (onTap != null) it.clickable(onClick = onTap) else it }
            .padding(vertical = 4.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Box(
            modifier = Modifier
                .size(28.dp)
                .clip(RoundedCornerShape(2.dp))
                .background(SlotBg)
                .border(1.dp, BronzeDark, RoundedCornerShape(2.dp))
        ) {
            if (icon != null) {
                Image(
                    bitmap = icon,
                    contentDescription = null,
                    contentScale = ContentScale.Fit,
                    modifier = Modifier.fillMaxSize()
                )
            }
        }
        Spacer(Modifier.width(8.dp))
        EffectDot(effect.harmful, 8.dp)
        Spacer(Modifier.width(8.dp))
        Column(Modifier.weight(1f)) {
            Text(
                effect.name,
                color = Bone, fontSize = 12.sp, fontFamily = MwBody,
                maxLines = 1, overflow = TextOverflow.Ellipsis
            )
            if (subtitle.isNotEmpty()) {
                Text(
                    subtitle,
                    color = BoneDim, fontSize = 10.sp, fontFamily = MwData,
                    maxLines = 1, overflow = TextOverflow.Ellipsis
                )
            }
        }
    }
}

@Composable
private fun SkillsPanel(
    skills: List<SkillStat>,
    modifier: Modifier = Modifier,
    onSelectStat: (StatInfo) -> Unit
) {
    // TWO columns, not three: Major and Minor SHARE the left one (stacked, each still under its own
    // heading). Three equal columns left ~90dp of usable width apiece, which truncated the longer
    // skill names, and the space freed here is what lets STATS_LEFT_WIDTH grow — see that constant
    // for the width budget. Major above Minor keeps the game's own ordering.
    val majorMinor = remember(skills) {
        buildList {
            skills.filter { it.category == "major" }.let { if (it.isNotEmpty()) add("Major" to it) }
            skills.filter { it.category == "minor" }.let { if (it.isNotEmpty()) add("Minor" to it) }
        }
    }
    val misc = remember(skills) {
        skills.filter { it.category == "misc" }.let {
            if (it.isEmpty()) emptyList() else listOf("Misc" to it)
        }
    }

    Row(modifier.mwPanel().padding(10.dp)) {
        SkillColumn(majorMinor, Modifier.weight(1f).fillMaxHeight(), onSelectStat)
        Box(Modifier.width(1.dp).fillMaxHeight().background(BronzeDark))
        SkillColumn(misc, Modifier.weight(1f).fillMaxHeight(), onSelectStat)
    }
}

/**
 * One skills column holding one or more labelled sections.
 *
 * The headings are `stickyHeader`s rather than a fixed heading above the list, because a column can
 * now hold two sections and both lists scroll (Major+Minor is ~10 rows against ~292dp of height,
 * Misc is 17). A heading pinned outside the scroll — what this did while every column held exactly
 * one section — cannot say which section you are currently looking at once there are two.
 */
@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun SkillColumn(
    sections: List<Pair<String, List<SkillStat>>>,
    modifier: Modifier = Modifier,
    onSelectStat: (StatInfo) -> Unit
) {
    Column(modifier.padding(horizontal = 8.dp)) {
        LazyColumn(Modifier.fillMaxSize()) {
            sections.forEach { (label, list) ->
                stickyHeader(key = "hdr_$label") {
                    // Opaque: a sticky header scrolls OVER the rows beneath it, so without a fill
                    // the skill names would read through it. Plain StonePanel rather than
                    // mwPanel's `StonePanel.copy(alpha = LocalPanelOpacity.current)` because this
                    // tab is bottom-screen only, where that local is always 1f — and a translucent
                    // header could not occlude anything anyway.
                    Box(Modifier.fillMaxWidth().background(StonePanel)) {
                        SpellSectionHeader(label)
                    }
                }
                items(list, key = { it.id }) { skill ->
                    SkillRow(skill) { onSelectStat(StatInfo.SkillInfo(skill)) }
                }
            }
        }
    }
}

@Composable
private fun SkillRow(skill: SkillStat, onClick: () -> Unit) {
    Row(
        Modifier.fillMaxWidth().clickable(onClick = onClick).padding(vertical = 4.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            skill.name.ifBlank { skill.id },
            color = Bone, fontSize = 12.sp, fontFamily = MwBody,
            maxLines = 1, overflow = TextOverflow.Ellipsis,
            modifier = Modifier.weight(1f)
        )
        Text(
            "${skill.value.toInt()}",
            color = BronzeLight, fontSize = 12.sp,
            fontFamily = MwData, fontWeight = FontWeight.Bold
        )
    }
}

/* ---- Bottom tab row ---- */

@Composable
private fun BottomTabBar(
    selected: Tab,
    onSelect: (Tab) -> Unit,
    modifier: Modifier = Modifier
) {
    Row(
        modifier = modifier
            .clip(RoundedCornerShape(3.dp))
            .background(FloatStone)
            .border(2.dp, Bronze, RoundedCornerShape(3.dp))
            .padding(6.dp),
        horizontalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        Tab.entries.forEach { t ->
            val isSel = t == selected
            Box(
                modifier = Modifier
                    .weight(1f)
                    .clip(RoundedCornerShape(2.dp))
                    .background(if (isSel) Bronze else Color.Transparent)
                    .border(
                        1.dp,
                        if (isSel) BronzeLight else BronzeDark,
                        RoundedCornerShape(2.dp)
                    )
                    .clickable { onSelect(t) }
                    .padding(vertical = 13.dp),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    t.label,
                    color = if (isSel) StoneDark else Bone,
                    fontSize = 14.sp,
                    fontFamily = MwDisplay,
                    fontWeight = if (isSel) FontWeight.Bold else FontWeight.Normal,
                    textAlign = TextAlign.Center
                )
            }
        }
    }
}

/* ---- Helpers ---- */

/** Stopgap readability: "pick_journeyman_01" -> "Pick Journeyman 01".
 *  Real display names will come from a future export or lookup table. */
private fun prettify(id: String): String =
    id.replace('_', ' ')
        .split(' ')
        .joinToString(" ") { w ->
            if (w.isNotEmpty()) w.replaceFirstChar { it.uppercase() } else w
        }

/* ---- Options / display-settings menu (shown on the bottom screen while the in-game
 *      pause/options menu is open; hosted as a WindowManager panel by EngineActivity). ---- */

/** Warm near-black background for the full-screen options menu. */
private val OptionsBg = Color(0xFF1A1410)
/** Fill of the "active" pill in the two-option selectors. */
private val PillActiveBg = Color(0xFF3A2A10)
/** Armed state of the "Default settings" button. Same red as the crime toast + harmful effect
 *  dots, so "this is destructive" reads the same way everywhere. */
private val ResetWarnRed = Color(0xFFC75C5C)
/** How long "Default settings" stays armed before disarming itself. */
private const val RESET_CONFIRM_MS = 4000L

/* ---- Tap flash: the options menu's press feedback ----
 *
 * WHY THIS EXISTS RATHER THAN THE BUILT-IN PRESS INDICATION (investigated Aug 21 2026; the report
 * was "the flash is too brief to notice and doesn't always fire"). Two independent causes, both
 * confirmed against the Compose Foundation 1.11.2 sources rather than guessed at:
 *
 *  1. **TIMING — `Modifier.clickable` delays its press interaction inside a scrollable container.**
 *     `AbstractClickableNode.handlePressInteractionStart` checks `delayPressInteraction()`, which is
 *     true whenever the composition root is in a scrollable container — which the options list
 *     always is — and defers emitting `PressInteraction.Press` by `TapIndicationDelay`
 *     (`ViewConfiguration.getTapTimeout()`, 100 ms on Android). If the finger lifts first,
 *     `handlePressInteractionRelease` cancels that job and emits Press and Release back-to-back from
 *     ONE coroutine. The indication node's collector therefore sees its press count go 1 → 0 with no
 *     frame in between, so a normal quick tap draws a pressed frame for 0–1 frames, or none at all,
 *     while a deliberate >100 ms hold lights up properly. That is exactly "too brief, and
 *     inconsistent" — the inconsistency was tap SPEED, not a missed event.
 *  2. **CONTRAST — what gets drawn is near-invisible here.** No `MaterialTheme` wraps the options
 *     overlay (EngineActivity composes it as `AdaptiveDimmedWindow { OptionsMenuOverlay() }`), so
 *     `LocalIndication` is Foundation's fallback `DefaultDebugIndication`, whose entire effect is
 *     `drawRect(Color.Black.copy(alpha = 0.3f))`. Over this menu's near-black palette (OptionsBg
 *     #1A1410, SlotBg, PillActiveBg #3A2A10) that is 30% black on almost-black — imperceptible even
 *     on the holds where it does fire.
 *
 * So the fix has to change both halves: drive the flash from the CLICK (which is emitted exactly
 * once per registered tap, with no timing gate) and give it a minimum on-screen life; and draw it in
 * a colour that reads on a dark panel. The built-in indication is deliberately left in place
 * underneath — it costs nothing, and it still gives press-down feedback on a long hold.
 */

/** How long a tap flash stays at full strength before fading. Comfortably longer than a frame at
 *  any refresh rate, which is the entire failure mode being fixed. */
private const val TAP_FLASH_HOLD_MS = 110L
/** Fade-out length. Long enough to register in peripheral vision, short enough not to smear when
 *  tapping several pills in a row. */
private const val TAP_FLASH_FADE_MS = 260
/** Peak opacity of the flash overlay. Bright enough to be unmistakable on the dark palette; below
 *  the point where the label underneath washes out. */
private const val TAP_FLASH_MAX_ALPHA = 0.42f

/**
 * A [Modifier.clickable] that also flashes the element for [TAP_FLASH_HOLD_MS] + [TAP_FLASH_FADE_MS]
 * on every registered tap. See the block comment above for why the built-in press indication could
 * not do this.
 *
 * Driven by a click COUNTER rather than by the press state: a re-tap during the fade bumps the
 * counter, which restarts the effect and snaps back to full — where re-setting a boolean that is
 * already true would do nothing and the second tap would go unacknowledged.
 *
 * Draws with [drawWithContent] AFTER `drawContent()`, so the flash covers fill, border and label
 * alike and needs no background of its own — an element with a transparent background flashes
 * exactly as visibly as a filled one.
 */
@Composable
private fun Modifier.tapFlash(
    enabled: Boolean = true,
    flashColor: Color = BronzeLight,
    onClick: () -> Unit,
): Modifier {
    // State is remembered UNCONDITIONALLY, and [enabled] is applied at the end — an early return
    // above the remembers would make the slot structure of this call site depend on a value that
    // can change (a pill going from disabled to enabled), which is the one thing composable slot
    // tables dislike. Costs two slots on a disabled pill; buys never having to think about it.
    var flashes by remember { mutableIntStateOf(0) }
    var lit by remember { mutableStateOf(false) }
    LaunchedEffect(flashes) {
        if (flashes == 0) return@LaunchedEffect
        lit = true
        delay(TAP_FLASH_HOLD_MS)
        lit = false
    }
    // tween(0) on the way UP so the flash is instant, and only the fade is animated.
    val alpha by animateFloatAsState(
        targetValue = if (lit) TAP_FLASH_MAX_ALPHA else 0f,
        animationSpec = tween(
            durationMillis = if (lit) 0 else TAP_FLASH_FADE_MS,
            easing = LinearEasing
        ),
        label = "tapFlash"
    )
    if (!enabled) return this
    return this
        .clickable { flashes++; onClick() }
        .drawWithContent {
            drawContent()
            if (alpha > 0.001f) drawRect(flashColor, alpha = alpha)
        }
}

/**
 * The options menu's top level is a list of CATEGORIES; each one opens as its own page.
 *
 * Replaces the collapsible in-place sections (Aug 21 2026). Those turned the menu into a five-line
 * index only while everything happened to be collapsed — open one section and every other heading
 * was pushed off-screen, so "where am I" was answered by scroll position rather than by the screen.
 * A page per category means the top level is ALWAYS the short scannable list, and a category always
 * starts at its own top.
 *
 * Two things follow from the restructure and are deliberate, not oversights:
 *  - **Nothing is remembered between visits.** The old menu carried a module-level
 *    `OptionsMenuScrollState` and `OptionsSectionState` purely because the pause overlay is a
 *    separate window destroyed and rebuilt on every open, so a plain `remember` could not survive
 *    it. With a category list there is no position worth restoring, so both objects are gone and
 *    the page state is an ordinary `remember` — the menu opens at the category list every time.
 *  - **The title is what identifies a page**, exactly as the section headings were, so there is no
 *    separate key constant that could drift from the label.
 */
private enum class OptionsPage(val title: String) {
    /** Per-menu: who draws it, and (when the companion does) on which screen. */
    GAME_MENUS("Game Menus"),
    /**
     * Everything about the top screen: the game's own HUD, the DS overlays drawn over it, and the
     * game-world brightness floors.
     *
     * Merges the old "Display" section into "Top Screen" (Aug 21 2026). Display existed for one row
     * — Game Brightness — which lifts dark scenes in the GAME WORLD, i.e. the top screen; a section
     * of its own overstated how cross-cutting it was now that Screen Dimming had moved out to
     * Developer Tools.
     */
    TOP_DISPLAY("Top Display Settings"),
    /** How the companion screen itself looks. */
    BOTTOM_DISPLAY("Bottom Display Settings"),
    /** How the game is controlled from the two screens. */
    CONTROLS("Controls"),
    /** Cheats, test helpers, and the settings that are correct by default. */
    DEVELOPER_TOOLS("Developer Tools"),
}

/**
 * A category button on the options menu's top level — the title, a one-line description of what is
 * inside, and a "▸" affordance.
 *
 * The description is what makes the category list usable as an index: a bare five-word list gives no
 * clue which page a given setting is on, which is the one thing the old always-visible section
 * headings did well.
 */
@Composable
private fun OptionsCategoryButton(page: OptionsPage, blurb: String, onOpen: () -> Unit) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(vertical = 5.dp)
            .clip(RoundedCornerShape(4.dp))
            .background(SlotBg)
            .border(1.dp, BronzeDark, RoundedCornerShape(4.dp))
            .tapFlash { onOpen() }
            .padding(horizontal = 14.dp, vertical = 12.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column(Modifier.weight(1f)) {
            Text(
                page.title.uppercase(),
                color = BronzeLight,
                fontSize = 17.sp,
                fontFamily = MwDisplay,
                fontWeight = FontWeight.Bold,
                letterSpacing = 1.2.sp
            )
            Text(
                blurb,
                color = BoneDim,
                fontSize = 11.sp,
                fontFamily = MwBody,
                lineHeight = 14.sp,
                modifier = Modifier.padding(top = 2.dp)
            )
        }
        // A VECTOR, not a "▸": MysticCards has no arrow/chevron coverage, and this row is now
        // drawn in it (the settings window joined the game font on Aug 21 2026). Same call the
        // sort affordance and the favourite star already make, for the same reason.
        Icon(
            imageVector = Icons.AutoMirrored.Filled.KeyboardArrowRight,
            contentDescription = null,
            tint = BronzeLight,
            modifier = Modifier.size(24.dp)
        )
    }
}

/**
 * The header every settings sub-page carries: a Back button and the page title, over the same bronze
 * rule the section headings used.
 *
 * A back button per page rather than a persistent sidebar — the companion panel is ~538 x 469 dp, so
 * a sidebar would cost roughly a third of the width permanently to save one tap.
 *
 * Shared with [DsControlsPage] so the two kinds of sub-page cannot drift apart.
 */
@Composable
private fun OptionsSubPageHeader(title: String, onBack: () -> Unit) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 10.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Box(
            modifier = Modifier
                .clip(RoundedCornerShape(4.dp))
                .background(PillActiveBg.copy(alpha = 0.94f))
                .border(1.dp, BronzeLight, RoundedCornerShape(4.dp))
                .tapFlash { UiSounds.play(UiSounds.Cue.TOGGLE); onBack() }
                .padding(start = 8.dp, end = 14.dp, top = 8.dp, bottom = 8.dp)
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                // Vector arrow rather than a "◀" glyph — see [OptionsCategoryButton].
                Icon(
                    imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                    contentDescription = null,
                    tint = BronzeLight,
                    modifier = Modifier.size(18.dp)
                )
                Spacer(Modifier.width(6.dp))
                Text(
                    "Back",
                    color = BronzeLight, fontSize = 15.sp,
                    fontFamily = MwDisplay, fontWeight = FontWeight.Bold
                )
            }
        }
        Spacer(Modifier.width(12.dp))
        Text(
            title.uppercase(),
            color = BronzeLight,
            fontSize = 18.sp,
            fontFamily = MwDisplay,
            fontWeight = FontWeight.Bold,
            letterSpacing = 1.5.sp
        )
    }
    Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
}

/* ---- DS Controls reference page ---- */

/**
 * A button or gesture name, in the app's existing `[X]`-style chip idiom (see [LootButton] and the
 * quantity picker's `MAX [Y]`): monospace [MwData] on a dark slot fill with a bronze hairline.
 *
 * ONE treatment for every control on the page — face buttons (`R3`, `X`, `Y`, `B`), sticks
 * (`Left stick`), and gestures (`Tap`, `Long press`, `Swipe`) all render identically. That is
 * deliberate: roughly a third of the reference is gestures, which have no honest unbranded glyph,
 * so an icon set would inevitably become icons-for-some, text-for-the-rest. A fixed [minWidth]
 * keeps the description column aligned down the page.
 */
@Composable
private fun ControlChip(label: String, minWidth: Dp = 82.dp) {
    Box(
        modifier = Modifier
            .widthIn(min = minWidth)
            .clip(RoundedCornerShape(3.dp))
            .background(SlotBg)
            .border(1.dp, BronzeDark, RoundedCornerShape(3.dp))
            .padding(horizontal = 7.dp, vertical = 4.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            label,
            color = BronzeLight,
            fontSize = 10.sp,
            fontFamily = MwData,
            maxLines = 1
        )
    }
}

/** One control: the chip on the left, what it does on the right. */
private data class ControlEntry(val chip: String, val text: String)

/** A context the controls apply in (Inventory, HUD, Looting, …). */
private data class ControlGroup(val title: String, val entries: List<ControlEntry>)

/**
 * The reference content. Documents EXISTING behaviour only — nothing here rebinds anything.
 *
 * "Tap: equip or use" is phrased loosely on purpose: the inventory tap action is context-dependent
 * (books read, potions drink, gear equips/unequips, plain misc items do nothing), and spelling all
 * four cases out here would cost more clarity than it buys on a quick-reference page.
 */
private val DS_CONTROL_GROUPS = listOf(
    ControlGroup(
        "Inventory & Spells",
        listOf(
            ControlEntry("Tap", "Equip or use the item"),
            ControlEntry("Long press", "More options"),
            ControlEntry("Swipe", "Left or right to switch category")
        )
    ),
    ControlGroup(
        "HUD",
        listOf(
            ControlEntry("Tap", "The Effects label to see active effects"),
            ControlEntry("Tap", "The map to open the full map"),
            ControlEntry("Tap", "A door marker to see where it leads"),
            ControlEntry("Tap", "The Spell or Weapon icon to show its name"),
            ControlEntry("Tap", "A favourite slot to use it"),
            ControlEntry("Long press", "A favourite slot to see more options"),
            ControlEntry("Tap", "The followed quest to open it in the journal"),
            ControlEntry("Long press", "The followed quest to hide or unfollow it")
        )
    ),
    ControlGroup(
        "Stats",
        listOf(ControlEntry("Tap", "Anything for more information"))
    ),
    ControlGroup(
        "Journal",
        listOf(
            ControlEntry("Long press", "A quest to hide it or follow it on the HUD"),
            ControlEntry("Swipe", "Left or right to page through entries")
        )
    ),
    ControlGroup(
        "Looting",
        listOf(
            ControlEntry("R3", "Inspect item"),
            ControlEntry("X", "Take all"),
            ControlEntry("Y", "Dispose of corpse"),
            ControlEntry("B", "Close")
        )
    ),
    ControlGroup(
        "Bartering",
        listOf(
            ControlEntry("R3", "Inspect item"),
            ControlEntry("X", "Make offer"),
            ControlEntry("Left stick", "Adjust gold"),
            ControlEntry("B", "Cancel")
        )
    ),
    ControlGroup(
        "Elsewhere",
        listOf(
            ControlEntry("D-pad", "Quantity to adjust the amount"),
            ControlEntry("Y", "Quantity to set to the whole stack"),
            ControlEntry("D-pad", "Resting to choose how many hours"),
            ControlEntry("X", "Resting to rest until healed"),
            ControlEntry("A", "Repair to repair the selected item"),
            ControlEntry("X", "Repair to repair everything"),
            ControlEntry("A", "Training to train the selected skill"),
            ControlEntry("A", "Travel to confirm the destination"),
            ControlEntry("Tap", "Dialogue highlighted words to see NPC says to ask about them")
        )
    ),
    // Last on purpose: a conditional caveat rather than a control you use every session. Scoped
    // deliberately to what A does — this is not a general explainer for the Input options. The
    // cause is the engine's own gamepad-cursor handling (mGamepadGuiCursorEnabled), so it applies
    // in the game's NATIVE menus, not the companion's own screens.
    ControlGroup(
        "With Game cursor on",
        listOf(
            ControlEntry("A", "Clicks whatever the cursor is over in the game's own menus, rather than the highlighted item"),
            ControlEntry("D-pad", "Still highlights menu items as usual")
        )
    )
)

// DsControlsButton — the pinned "DS Controls" button that used to sit above Presets on the top
// level. REMOVED Aug 21 2026: it did exactly what the Controls page's own "View DS UI Controls"
// button does, and duplicating it made the top level longer than the scannable category list it is
// meant to be. Its original justification is gone with the collapsible sections — back then the
// in-page row could be scrolled far off screen, whereas now Controls is one tap from the top level
// and the button is the last thing on that page.


/**
 * The controls reference. Replaces the settings list in place (rather than being an overlay) so it
 * works identically from the in-game pause menu and the title-screen popup, neither of which can
 * host a Compose `Dialog` — the companion runs in a TYPE_PRESENTATION window.
 */
@Composable
private fun DsControlsPage(onBack: () -> Unit) {
    Column(Modifier.fillMaxSize()) {
        // Shares [OptionsSubPageHeader] with the settings categories: two kinds of sub-page, one
        // back affordance, so the two cannot drift apart.
        OptionsSubPageHeader("DS UI Controls", onBack)

        LazyColumn(
            modifier = Modifier.fillMaxSize().padding(horizontal = 16.dp),
            contentPadding = androidx.compose.foundation.layout.PaddingValues(
                top = 4.dp, bottom = 24.dp
            )
        ) {
            DS_CONTROL_GROUPS.forEach { group ->
                item(key = "hdr_${group.title}") { SpellSectionHeader(group.title) }
                itemsIndexed(
                    group.entries,
                    // Chip labels repeat within a group ("Tap" appears 4x under HUD), so the key
                    // must include the index — a chip-only key would be a duplicate-key crash.
                    key = { i, e -> "${group.title}_${i}_${e.chip}" }
                ) { _, entry ->
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(vertical = 5.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        ControlChip(entry.chip)
                        Spacer(Modifier.width(12.dp))
                        Text(
                            entry.text,
                            color = Bone,
                            fontSize = 13.sp,
                            fontFamily = MwBody,
                            lineHeight = 17.sp
                        )
                    }
                }
            }
        }
    }
}

/**
 * The display-settings menu. A DS Controls button and a Presets row ([All DS]/[Custom]/[All
 * Native]), then five collapsible sections: GAME MENUS (one merged row per game menu — who draws it
 * and on which screen), TOP SCREEN (the game's own HUD + the DS overlays drawn over it), BOTTOM
 * SCREEN (how the companion looks), CONTROLS, and DEVELOPER TOOLS. Full-screen, scrollable,
 * BronzeLight-themed. Writes to [UiPreferences] live on every tap (no save/cancel).
 *
 * Public because [org.openmw.EngineActivity] hosts it in a WindowManager panel window on
 * the companion Presentation when the pause/options menu opens.
 */
@Composable
fun OptionsMenuOverlay() {
    val context = LocalContext.current
    remember(context) { UiPreferences.init(context); true }
    // The settings window is its own WindowManager panel, outside both CompanionScreen and the
    // top-screen overlays, so it has to declare the game font for itself. It was excluded from it
    // until Aug 21 2026 — see [LocalGameFont] for what that exclusion was protecting and why it
    // lost. init() above runs FIRST, so the preference is read at its real value on the very first
    // composition instead of defaulting and re-fonting the screen a frame later.
    ProvideCompanionFont { OptionsMenuContent() }
}

@Composable
private fun OptionsMenuContent() {

    // True while shown for the TITLE-screen main menu (no game loaded), vs the in-game pause menu.
    val onTitleScreen by GameStateRepository.titleMenuVisible.collectAsState()
    // On the title screen the settings live in a popup (opened by the Options button) below the
    // intro/info, keeping the welcome screen uncluttered. The in-game pause menu is UNCHANGED — it
    // shows the settings list inline.
    var showOptionsPopup by remember { mutableStateOf(false) }

    Box(Modifier.fillMaxSize()) {
        Column(Modifier.fillMaxSize().background(OptionsBg)) {
            OptionsTitleBar(onTitleScreen)
            if (onTitleScreen) {
                // Title screen: intro/info + an "Options" button that opens the settings in a popup.
                Column(
                    Modifier
                        .fillMaxSize()
                        .padding(horizontal = 16.dp)
                        .verticalScroll(rememberScrollState())
                ) {
                    OptionsWelcomeBlock()
                    Spacer(Modifier.height(14.dp))
                    OptionsOpenButton { showOptionsPopup = true }
                    Spacer(Modifier.height(24.dp))
                }
            } else {
                // In-game pause menu — settings list inline (unchanged behaviour).
                OptionsSettingsList()
            }
        }
        if (onTitleScreen && showOptionsPopup) {
            OptionsPopup(onDismiss = { showOptionsPopup = false })
        }
    }
}

/** The options overlay's title bar + divider. On the TITLE screen it's a large centred "OpenMW-DS"
 *  banner (no subtitle); the in-game pause menu keeps the compact app-identity bar (unchanged). */
@Composable
private fun OptionsTitleBar(titleScreen: Boolean) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .background(StonePanel)
            .padding(horizontal = 16.dp, vertical = if (titleScreen) 26.dp else 12.dp),
        contentAlignment = if (titleScreen) Alignment.Center else Alignment.CenterStart
    ) {
        Column(horizontalAlignment = if (titleScreen) Alignment.CenterHorizontally else Alignment.Start) {
            Text(
                // The in-game bar names the SCREEN ("DS Settings"), the title screen names the APP.
                // Renamed from "OpenMW-DS" + a "Display settings" subtitle on Aug 21 2026: this menu
                // has never been only about display, and the app name is already on the title screen
                // and in the version footer.
                if (titleScreen) "OpenMW-DS" else "DS Settings",
                color = BronzeLight,
                fontSize = if (titleScreen) 46.sp else 18.sp,
                fontFamily = MwDisplay, fontWeight = FontWeight.Bold,
                letterSpacing = if (titleScreen) 3.sp else 1.sp
            )
            if (!titleScreen) {
                Text(
                    "Settings for the OpenMW-DS companion screens",
                    color = BoneDim, fontSize = 11.sp, fontFamily = MwBody
                )
            }
        }
    }
    Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
}

/**
 * The settings UI below the title bar: the top-level CATEGORY LIST, or whichever sub-page is open.
 * Rendered inline for the in-game pause menu and inside [OptionsPopup] for the title screen.
 *
 * **Nothing here persists between visits, deliberately** (see [OptionsPage]). The page state and the
 * DS Controls flag are plain `remember`s, and the pause overlay's window is destroyed and rebuilt on
 * every open — so pausing always lands on the category list, never on the page you were last in or
 * the scroll position you left. The module-level scroll/section state the old menu carried for the
 * opposite behaviour is gone.
 *
 * The DS Controls page is hosted HERE rather than in [OptionsMenuOverlay] so both entry points — the
 * in-game pause menu (which renders this inline) and the title screen (which renders it inside
 * [OptionsPopup]) — get it from one wiring.
 */
@Composable
private fun OptionsSettingsList(nav: OptionsNavState = remember { OptionsNavState() }) {
    when {
        nav.showControls -> DsControlsPage(onBack = { nav.showControls = false })
        nav.page != null -> OptionsSubPage(
            page = nav.page!!,
            onBack = { nav.page = null },
            // Only the Controls page opens the reference now, so this goes straight there rather
            // than through a shared lambda the category list also used to take.
            onOpenControls = { nav.showControls = true },
        )
        else -> OptionsCategoryListContent(onOpenPage = { nav.page = it })
    }
}

/**
 * Where the settings UI currently is: the category list, one category's page, or the DS Controls
 * reference.
 *
 * Hoisted out of [OptionsSettingsList] so a HOST can see it. The title-screen [OptionsPopup] wraps
 * the list in chrome of its own — a Back button and a heading — which must disappear the moment a
 * sub-page opens, or the screen carries two Back buttons and two headings at once. The host cannot
 * ask that question without owning the state, so it owns it.
 *
 * A holder class rather than an `onNestedChange` callback: reporting the change back up would be a
 * side effect fired from composition, and would leave the host's copy able to disagree with the
 * real one for a frame. This way there is one value and both read it.
 */
@Stable
private class OptionsNavState {
    /** The open category page, or null for the top-level category list. */
    var page by mutableStateOf<OptionsPage?>(null)
    /** Whether the DS Controls reference is open (it replaces the list, from either level). */
    var showControls by mutableStateOf(false)
    /** True only on the category list — i.e. when a host's own back/heading chrome should show. */
    val atTopLevel: Boolean get() = page == null && !showControls
}

/**
 * The top level: the Presets row, then one button per [OptionsPage].
 *
 * Presets stays at this level rather than being filed into a category. It is a single row, not a
 * section, and it is the fastest path from "I just installed this" to a working layout, so burying
 * it a page deep would cost exactly the players it exists for. (A pinned "DS Controls" button sat
 * here too until Aug 21 2026; it duplicated the button on the Controls page.)
 */
@Composable
private fun OptionsCategoryListContent(onOpenPage: (OptionsPage) -> Unit) {
    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 16.dp),
        contentPadding = androidx.compose.foundation.layout.PaddingValues(bottom = 24.dp)
    ) {
        item { QuickSetRow() }
        item { GameBrightnessQuickSetRow() }

        item {
            OptionsCategoryButton(
                OptionsPage.GAME_MENUS,
                "Which menus the companion draws, and on which screen."
            ) { onOpenPage(OptionsPage.GAME_MENUS) }
        }
        item {
            OptionsCategoryButton(
                OptionsPage.TOP_DISPLAY,
                "The game's own HUD, the DS overlays over it, and game brightness."
            ) { onOpenPage(OptionsPage.TOP_DISPLAY) }
        }
        item {
            OptionsCategoryButton(
                OptionsPage.BOTTOM_DISPLAY,
                "How the companion screen itself looks and sounds."
            ) { onOpenPage(OptionsPage.BOTTOM_DISPLAY) }
        }
        item {
            OptionsCategoryButton(
                OptionsPage.CONTROLS,
                "Touch, cursor, and the button and gesture reference."
            ) { onOpenPage(OptionsPage.CONTROLS) }
        }
        item {
            OptionsCategoryButton(
                OptionsPage.DEVELOPER_TOOLS,
                "Restore defaults, plus cheats and testing tools."
            ) { onOpenPage(OptionsPage.DEVELOPER_TOOLS) }
        }

        // Quiet release-version footer (diagnostic/reference; `v` prefix added here). Stays on the
        // top level, which is the page someone reporting a bug is always able to reach.
        item {
            Text(
                text = "OpenMW-DS v${BuildConfig.RELEASE_VERSION}",
                color = BoneDim,
                fontSize = 10.sp,
                fontFamily = MwBody,
                textAlign = TextAlign.Center,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = 14.dp, bottom = 4.dp)
            )
        }
    }
}

/** One settings category, on its own page: the shared [OptionsSubPageHeader] over that page's rows. */
@Composable
private fun OptionsSubPage(
    page: OptionsPage,
    onBack: () -> Unit,
    onOpenControls: () -> Unit,
) {
    // Read here rather than inside the page's own branch: the rows are emitted from the LazyColumn's
    // item scope, which is not a composable context.
    val developerMode by UiPreferences.developerModeFlow().collectAsState()

    Column(Modifier.fillMaxSize()) {
        OptionsSubPageHeader(page.title, onBack)
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(horizontal = 16.dp),
            contentPadding = androidx.compose.foundation.layout.PaddingValues(bottom = 24.dp)
        ) {
            when (page) {
                // GAME MENUS: one row per game menu, answering "who draws this, and where?" as a
                // single decision — the mode and the screen on one row.
                OptionsPage.GAME_MENUS -> {
                    item { ConversationMenuRow() }
                    item { LootingMenuRow() }
                    item { BarteringMenuRow() }
                    item { PersuasionMenuRow() }
                    item { RepairMenuRow() }
                    item { TravelMenuRow() }
                    item { SpellBuyingMenuRow() }
                    item { TrainingMenuRow() }
                    item { RestwaitMenuRow() }
                    item { CrimeMenuRow() }
                    // The menus with no companion version yet: one muted line each.
                    items(GAME_UI_ELEMENTS.filter { it.pending }, key = { "unavail_" + it.key }) {
                        UnavailableMenuRow(it.label)
                    }
                }

                // TOP DISPLAY SETTINGS: everything drawn on the game's screen, plus the game-world
                // brightness floors that were their own "Display" section until Aug 21 2026.
                OptionsPage.TOP_DISPLAY -> {
                    item { OptionsSubLabel("The game world") }
                    item { GameBrightnessRow() }
                    item { OptionsSubLabel("The game's own HUD") }
                    // The blurb belongs UNDER its label and above the switches it is about:
                    // "Minimap -> Off" otherwise reads as "remove my minimap".
                    item { TopScreenBlurb() }
                    items(HUD_ELEMENTS, key = { it.key }) { HudToggleRow(it) }
                    item { OptionsSubLabel("DS overlays on the top screen") }
                    item { TopPanelOpacityRow() }
                }

                // BOTTOM DISPLAY SETTINGS: how the companion screen itself looks.
                OptionsPage.BOTTOM_DISPLAY -> {
                    item { UiSoundsRow() }
                    item { OptionsSubLabel("Inventory tab") }
                    item { EquippedInListRow() }
                    item { OptionsSubLabel("HUD favourites") }
                    item { FavSlotCountRow(isGear = false) }
                    item { FavSlotCountRow(isGear = true) }
                }

                // CONTROLS: how the game is driven from the two screens.
                OptionsPage.CONTROLS -> {
                    // The reference leads the page. It is the only thing here that TEACHES rather
                    // than configures, so it is what someone opening "Controls" for the first time
                    // is most likely to be after — and it is now the sole way in, since the pinned
                    // top-level button was removed.
                    item { ControlsReferenceRow(onOpen = onOpenControls) }
                    item { TouchInputRow() }
                    item { GameCursorRow() }
                    item { InputPairNote() }
                }

                // DEVELOPER TOOLS: cheats and test helpers, plus the settings that are correct by
                // default and only want touching by someone who knows why. Everything except
                // "Default settings" is gated behind the Developer mode toggle.
                OptionsPage.DEVELOPER_TOOLS -> {
                    item { DeveloperToolsBlurb() }
                    // Above the gate on purpose: restoring defaults is not a developer action and
                    // must not require turning Developer mode on to reach.
                    item(key = "dev_reset_settings") { ResetSettingsRow() }
                    item { DeveloperModeRow() }
                    if (developerMode) {
                        // Console FIRST: it is the reason most people turn Developer mode on, and
                        // the one entry here that is a general-purpose tool rather than a specific
                        // cheat or a tuning knob.
                        item(key = "dev_console") { OpenConsoleRow() }
                        // Correct-by-default settings, relocated here Aug 21 2026 so the main pages
                        // hold only the choices a player has a reason to make.
                        item(key = "dev_dimming") { AdaptiveDimmingRow() }
                        item(key = "dev_target_health") { TargetHealthLocationRow() }
                        item(key = "dev_player_combat") { PlayerCombatRow() }
                        item(key = "dev_game_font") { GameFontRow() }
                        item(key = "dev_inv_tab_style") { InventoryTabStyleRow() }
                        item(key = "dev_journal_page_turn") { JournalPageTurnRow() }
                        item(key = "dev_alpha3_overlay") { Alpha3OverlayRow() }
                        item(key = "dev_actions") { DeveloperActionsPanel() }
                    }
                }
            }
        }
    }
}

/** The title-screen button that opens the settings popup. Labelled with the destination — "DS
 *  Settings", the same name the popup's heading and the in-game title bar carry — rather than the
 *  generic "Options" it read until Aug 21 2026. */
@Composable
private fun OptionsOpenButton(onClick: () -> Unit) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .clip(RoundedCornerShape(4.dp))
            .background(PillActiveBg.copy(alpha = 0.94f))
            .border(1.dp, BronzeLight, RoundedCornerShape(4.dp))
            .tapFlash { UiSounds.play(UiSounds.Cue.TOGGLE); onClick() }
            .padding(vertical = 16.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            "DS Settings",
            color = BronzeLight, fontSize = 24.sp, fontFamily = MwDisplay,
            fontWeight = FontWeight.Bold, letterSpacing = 1.5.sp
        )
    }
}

/** Title-screen settings popup — an in-window overlay (NOT a Compose Dialog; the options overlay
 *  lives in a Presentation panel window). Scrim tap or the Close button dismisses. */
@Composable
private fun OptionsPopup(onDismiss: () -> Unit) {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .zIndex(30f)
            .background(Color(0xCC000000))
            .pointerInput(Unit) { detectTapGestures { onDismiss() } },
        contentAlignment = Alignment.Center
    ) {
        Column(
            modifier = Modifier
                .fillMaxWidth(0.94f)
                .fillMaxHeight(0.9f)
                .clip(RoundedCornerShape(4.dp))
                .background(OptionsBg)
                .border(2.dp, Bronze, RoundedCornerShape(4.dp))
                // Swallow taps so tapping the panel doesn't reach the dismiss scrim.
                .pointerInput(Unit) { detectTapGestures {} }
        ) {
            // The popup owns the nav state so it can hide its OWN chrome while a sub-page is open:
            // that page brings its own Back button and heading, and showing both left two Back
            // buttons and two headings stacked, with no way to tell which one left which level.
            // At the top level this bar is the only way back to the title screen, so it stays.
            //
            // Back therefore always means "up one level", wherever you are: out of DS Controls or a
            // category to the category list, then out of the popup to the title screen.
            val nav = remember { OptionsNavState() }
            if (nav.atTopLevel) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(StonePanel)
                        .padding(start = 12.dp, end = 16.dp, top = 10.dp, bottom = 10.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    // Prominent Back button (top-left) — returns to the title/intro screen.
                    Box(
                        modifier = Modifier
                            .clip(RoundedCornerShape(4.dp))
                            .background(PillActiveBg.copy(alpha = 0.94f))
                            .border(1.dp, BronzeLight, RoundedCornerShape(4.dp))
                            .tapFlash { UiSounds.play(UiSounds.Cue.TOGGLE); onDismiss() }
                            .padding(start = 8.dp, end = 14.dp, top = 8.dp, bottom = 8.dp)
                    ) {
                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Icon(
                                imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                                contentDescription = null,
                                tint = BronzeLight,
                                modifier = Modifier.size(18.dp)
                            )
                            Spacer(Modifier.width(6.dp))
                            Text(
                                "Back",
                                color = BronzeLight, fontSize = 15.sp, fontFamily = MwDisplay,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                    Spacer(Modifier.width(12.dp))
                    Text(
                        // Same name as the entry button and the in-game title bar.
                        "DS Settings",
                        color = BronzeLight, fontSize = 16.sp, fontFamily = MwDisplay,
                        fontWeight = FontWeight.Bold, modifier = Modifier.weight(1f)
                    )
                }
                Box(Modifier.fillMaxWidth().height(2.dp).background(Bronze))
            }
            OptionsSettingsList(nav)
        }
    }
}

/** One-time welcome shown at the top of the options overlay ONLY on the title screen (before a game
 *  is loaded), to orient first-time users and nudge them toward a starting preset. */
@Composable
private fun OptionsWelcomeBlock() {
    Column(
        modifier = Modifier.fillMaxWidth().padding(top = 16.dp, bottom = 8.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Text(
            "Under sun and sky, outlander. We greet you warmly.",
            color = BronzeLight,
            fontSize = 26.sp,
            fontFamily = MwDisplay,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center,
            lineHeight = 32.sp
        )
        Spacer(Modifier.height(12.dp))
        // Short centred lead under the greeting: what this screen IS, in one sentence. The
        // paragraph it replaces also carried three separate instructions, which is what made it
        // read as a wall of text — those are now the notes below, one idea each.
        Text(
            "A companion screen for Morrowind on the AYN Thor. Inventory, magic, map, journal " +
                "and stats live down here.",
            color = Bone,
            fontSize = 16.sp,
            fontFamily = MwBody,
            lineHeight = 22.sp,
            textAlign = TextAlign.Center,
