/**
 * "Default settings" — restores every companion setting to its shipped default.
 *
 * Sits in Developer Tools but ABOVE the "Developer mode" gate, so it is reachable without turning
 * developer mode on. That placement is also why it CONFIRMS: unlike the gated rows below it, any
 * player who opens this section can reach it, and a stray tap would otherwise discard a layout that
 * took a long time to arrange. The first tap arms, the second commits, and the arming lapses on its
 * own after [RESET_CONFIRM_MS] so the button cannot sit primed indefinitely.
 *
 * Scope is [UiPreferences] only — favourites, quest pins and hand-written journal entries live in
 * their own stores and are player-CREATED content, not settings, so a settings reset leaves them
 * alone. Note the reset also turns Developer mode itself back off (its default), which collapses
 * the rows below; that is correct, not a glitch.
 */
@Composable
private fun ResetSettingsRow() {
    val context = LocalContext.current
    var armed by remember { mutableStateOf(false) }

    // Disarm on its own, so the destructive state is never left standing.
    LaunchedEffect(armed) {
        if (armed) {
            delay(RESET_CONFIRM_MS)
            armed = false
        }
    }

    val accent = if (armed) ResetWarnRed else BronzeLight

    Column(Modifier.fillMaxWidth().padding(vertical = 9.dp)) {
        Text("Default settings", color = Bone, fontSize = 14.sp, fontFamily = MwBody)
        Text(
            if (armed) {
                "This clears every companion setting \u2014 Game Menus, layouts, HUD, brightness, " +
                    "sounds \u2014 back to how the app ships. Favourites, quest pins and your own " +
                    "journal entries are not touched."
            } else {
                "Restore every companion setting to its shipped default."
            },
            color = if (armed) BoneBright else BoneDim,
            fontSize = 10.sp,
            fontFamily = MwBody,
            lineHeight = 14.sp,
            modifier = Modifier.padding(top = 1.dp)
        )
        Spacer(Modifier.height(6.dp))
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .clip(RoundedCornerShape(4.dp))
                .background(PillActiveBg.copy(alpha = 0.94f))
                .border(1.dp, accent, RoundedCornerShape(4.dp))
                // Flashes in the warning red once armed, so the second (destructive) tap is
                // acknowledged in the same colour the row has already turned.
                .tapFlash(flashColor = accent) {
                    if (armed) {
                        UiSounds.play(UiSounds.Cue.ACTION)
                        UiPreferences.resetToDefaults(context)
                        armed = false
                    } else {
                        UiSounds.play(UiSounds.Cue.TOGGLE)
                        armed = true
                    }
                }
                .padding(vertical = 9.dp),
            contentAlignment = Alignment.Center
        ) {
            Text(
                if (armed) "TAP AGAIN TO RESET" else "DEFAULT SETTINGS",
                color = accent,
                fontSize = 14.sp,
                fontFamily = MwDisplay,
                fontWeight = FontWeight.Bold,
                letterSpacing = 1.sp
            )
        }
    }
}

/**
 * Opens the native in-game console on the TOP screen, exactly as a hardware keyboard's backtick
 * would.
 *
 * Traced path for a real keypress: `SDLActivity.dispatchKeyEvent` → `onNativeKeyDown(keyCode)` →
 * SDL's Android backend maps `AKEYCODE_GRAVE` (Android `KEYCODE_GRAVE`, 68) to
 * **`SDL_SCANCODE_GRAVE`** (`SDL_androidkeyboard.c` Android_Keycodes[68]) → OpenMW's
 * `KeyboardManager::keyPressed` matches it against `getKeyBinding(A_Console)`, whose default IS
 * `SDL_SCANCODE_GRAVE` (`bindingsmanager.cpp`) → `ActionManager::toggleConsole()` →
 * `WindowManager::toggleConsole()`.
 *
 * So this injects the SAME event a real key produces rather than reaching into the engine — no
 * native bridge, no new console-opening mechanism, and it automatically respects a rebound console
 * key only insofar as the DEFAULT binding is concerned (see the caveat in the report: if the user
 * rebinds A_Console away from grave, this stops matching).
 *
 * `onNativeKeyDown`/`Up` are already `public static native` on the bundled SDLActivity and are what
 * its own key handler calls, so this is a Kotlin-only change.
 */
private fun openNativeConsole() {
    runCatching {
        SDLActivity.onNativeKeyDown(KeyEvent.KEYCODE_GRAVE)
        SDLActivity.onNativeKeyUp(KeyEvent.KEYCODE_GRAVE)
    }.onFailure { Log.w("CompanionScreen", "could not inject console key", it) }
}

/** Developer Tools action: open the native console for manual testing. Full-width tappable row.
