/**
 * The Developer Tools action panel, shown only while "Developer mode" is on.
 *
 * Every button sends one `CMP:dev_*` command, and all of them are handled in companion.lua using
 * ordinary Lua APIs (see the Developer Tools block there for why that is preferred over raw
 * console commands). Emitted as a SINGLE lazy item rather than one per button — they are a
 * unit, they appear and disappear together, and keeping them in one item avoids ~14 more keys in
 * a list whose key collisions are already a documented hazard.
 *
 * God Mode and Noclip are the only stateful entries: they mirror real engine flags, read back
 * from [GameStateRepository.devToggles], so the pills stay correct even if the flag is changed
 * from the console or was already set when the save loaded.
 */
@Composable
private fun DeveloperActionsPanel() {
    val devToggles by GameStateRepository.devToggles.collectAsState()

    Column(Modifier.fillMaxWidth().padding(top = 4.dp, bottom = 8.dp)) {
        DevToggleRow(
            label = "God mode",
            description = "No damage, no magicka cost, no encumbrance limit",
            on = devToggles.godMode,
            onToggle = { CompanionActions.devToggleGodMode() }
        )
        DevToggleRow(
            label = "Noclip",
            description = "Walk through walls and floors",
            on = devToggles.noclip,
            onToggle = { CompanionActions.devToggleNoclip() }
        )

        DevSectionLabel("Character")
        DevActionButton(
            title = "Health",
            description = "Raises your maximum health to 99,999 and refills it.",
            button = "Max Health"
        ) { CompanionActions.devMaxHealth() }
        DevActionButton(
            title = "Magicka",
            description = "Raises your maximum magicka to 99,999 and refills it.",
            button = "Max Magicka"
        ) { CompanionActions.devMaxMagicka() }
        DevActionButton(
            title = "Fatigue",
            description = "Raises your maximum fatigue to 99,999 and refills it.",
            button = "Max Fatigue"
        ) { CompanionActions.devMaxFatigue() }
        // Additive, not set-to-100: pressing repeatedly keeps stacking, which is the point — it is
        // how you push a character far past vanilla limits to see how the UI copes with 3- and
        // 4-digit values. One press on a fresh character lands about where the old "max" did.
        DevActionButton(
            title = "Attributes",
            description = "Adds 100 to all eight attributes and clears any damage to them. " +
                "Press again to keep raising them past the usual limit.",
            button = "Add 100 to All Attributes"
        ) { CompanionActions.devAddAttributes() }
        DevActionButton(
            title = "Skills",
            description = "Adds 100 to all 27 skills and clears any damage to them. " +
                "Press again to keep raising them past the usual limit.",
            button = "Add 100 to All Skills"
        ) { CompanionActions.devAddSkills() }
        // Two deliberately different level buttons — the difference is the whole point of having
        // both, so each description says plainly what it skips or shows.
        DevActionButton(
            title = "Level",
            description = "Jumps straight to level 20. Skips the level-up screen, so you get no " +
                "attribute increases from it.",
            button = "Set Level 20"
        ) { CompanionActions.devSetLevel20() }
        DevActionButton(
            title = "Level up",
            description = "Fills the level-up bar and opens the level-up screen",
            button = "Trigger Level Up"
        ) { CompanionActions.devTriggerLevelUp() }

        DevSectionLabel("Items")
        // Two gold amounts, titled by the amount rather than both being "Gold" — the same reason
        // the Daytime/Night-time pair below is titled that way, so the rows are told apart by
        // their heading and not only by their button text. Smaller first: it is the one that
        // leaves prices and merchant gold limits meaningful, so it is the usual choice.
        DevActionButton(
            title = "10,000 gold",
            description = "Puts 10,000 gold in your inventory. Enough to buy and train freely " +
                "while merchant gold limits and prices still mean something.",
            button = "Add 10,000 Gold"
        ) { CompanionActions.devAddGold10k() }
        DevActionButton(
            title = "100,000 gold",
            description = "Puts 100,000 gold in your inventory. For pushing six-figure values " +
                "through the gold display and barter.",
            button = "Add 100,000 Gold"
        ) { CompanionActions.devAddGold() }
        DevActionButton(
            title = "Equipment samples",
            description = "One item of every wearable kind: an enchanted ring and amulet, a " +
                "torch, armour for each slot, one of each weapon type, and basic clothing. For " +
                "checking how gear equips and displays.",
            button = "Add Equipment Samples"
        ) { CompanionActions.devAddRegressionKit() }
        DevActionButton(
            title = "Inventory filler",
            description = "Dozens of mixed stacks. Potions, ingredients, books, tools, weapons " +
                "and armour. For testing scrolling, sorting and the category tabs with a full bag.",
            button = "Fill Inventory"
        ) { CompanionActions.devAddBulkItems() }
        // The two item halves of the enchanting kit. Kept in Items rather than in a section of
        // their own so the groups stay by KIND, as the rest of this screen is organised; the spell
        // half sits under Magic for the same reason.
        DevActionButton(
            title = "Enchantable items",
            description = "One unenchanted item of every kind the enchanting screen treats " +
                "differently: armour, clothing, a melee weapon, a bow, a stack of ammo and a " +
                "scroll. Each one unlocks a different set of cast types.",
            button = "Add Enchantable Items"
        ) { CompanionActions.devAddEnchantItems() }
        DevActionButton(
            title = "Filled soul gems",
            description = "Three soul gems holding a weak, a middling and a powerful soul. The " +
                "powerful one is the smallest soul that still unlocks Constant Effect, which " +
                "nothing weaker can reach.",
            button = "Add Filled Soul Gems"
        ) { CompanionActions.devAddSoulGems() }

        DevSectionLabel("Magic")
        DevActionButton(
            title = "Spells",
            description = "Teaches you a couple of cheap spells from each school of magic.",
            button = "Add Test Spell Kit"
        ) { CompanionActions.devAddSpellKit() }
        DevActionButton(
            title = "Active effects",
            description = "Applies a dozen different beneficial effects at once, to fill the " +
                "effects list on the HUD and Stats screen.",
            button = "Stack Many Effects"
        ) { CompanionActions.devStackEffects() }
        DevActionButton(
            title = "Enchanting and spellmaking spells",
            description = "Teaches spells chosen so both the enchanting and the spellmaking " +
                "effect lists cover every range and slider combination, including the two that " +
                "ask for a skill or an attribute first.",
            button = "Add Crafting Spells"
        ) { CompanionActions.devAddCraftSpells() }

        DevSectionLabel("World")
        // The two ends of the clock, mainly for exercising lighting-dependent behaviour such as
        // adaptive dimming. Titled by the time rather than both being "Time of day", so the two
        // rows are told apart by their heading and not only by their button text.
        DevActionButton(
            title = "Daytime",
            description = "Sets the in-game clock to midday.",
            button = "Set Day Time"
        ) { CompanionActions.devSetDay() }
        DevActionButton(
            title = "Night-time",
            description = "Sets the in-game clock to 10 PM.",
            button = "Set Night Time"
        ) { CompanionActions.devSetNight() }
        DevWeatherRow()
    }
}

/**
 * Developer Tools weather setter: one pill per weather, plus a live readout.
 *
 * **The readout is not decoration.** `core.weather.changeWeather` is vanilla's `ChangeWeather`,
 * which starts a TRANSITION rather than snapping: `mTransitionFactor` decays by
 * `elapsedRealSeconds * transitionDelta` of the TARGET weather, so with the shipped deltas a change
 * takes roughly 29s real to reach Ashstorm, 25s for Blight and 67s for Clear — and `getCurrent`
 * keeps naming the OLD weather for that whole time. Without something on screen saying "Clear ->
 * Ashstorm", every button would look broken for half a minute.
 *
 * A pill grid rather than [DevActionButton]s because ten of those would be a screen and a half, and
 * because these are a closed set of alternatives, which is what the pill row is the idiom for. The
 * pills are ACTIONS, not a selection, so none is ever drawn active — the current weather is stated
 * in the readout instead, where it can also show a transition.
 *
 * Ordered darkest-first to match the day-brightness sliders, so the two lists read the same way.
 */
@Composable
private fun DevWeatherRow() {
    val weather by GameStateRepository.currentWeather.collectAsState()

    Column(Modifier.fillMaxWidth().padding(vertical = 9.dp)) {
        Text("Weather", color = Bone, fontSize = 14.sp, fontFamily = MwBody)
        Spacer(Modifier.height(2.dp))
        Text(
            // Both limits are the engine's, not ours, and both look like bugs if unexplained.
            "Sets the weather for your current region. Outdoors only, and it fades in over about " +
                "half a minute rather than switching instantly, exactly as the game's own weather " +
                "command does.",
            color = BoneDim, fontSize = 11.sp, fontFamily = MwBody
        )
        Spacer(Modifier.height(4.dp))
        Text(
            when {
                weather == null -> "Now: indoors (no weather)"
                weather!!.transition > 0f && weather!!.next.isNotEmpty() ->
                    "Now: ${weather!!.name} -> ${weather!!.next} " +
                        "(${((1f - weather!!.transition) * 100).roundToInt()}%)"
                else -> "Now: ${weather!!.name}"
            },
            color = BronzeLight, fontSize = 11.sp, fontFamily = MwBody
        )
        Spacer(Modifier.height(6.dp))
        // Two rows of five: ten pills across the 3.92in screen would each be too narrow to hit.
        DAY_FLOOR_WEATHERS.chunked(5).forEach { row ->
            Row(
                Modifier.fillMaxWidth().padding(top = 4.dp),
                horizontalArrangement = Arrangement.spacedBy(6.dp)
            ) {
                row.forEach { w ->
                    OptionPill(
                        Modifier.weight(1f),
                        label = w.label,
                        active = false,
                        enabled = true
                    ) { CompanionActions.devSetWeather(w.weather) }
                }
            }
        }
    }
}

/** Small grouping label inside the Developer Tools action panel — the same treatment the section
 *  sub-labels use, so the two never drift apart. */
@Composable
private fun DevSectionLabel(text: String) = OptionsSubLabel(text)

/**
 * A one-shot Developer Tools action, presented exactly like [OpenConsoleRow]: a short heading, a
 * sentence saying what it actually does, then a full-width button.
 *
 * The description is not decoration — several of these actions are impossible to guess from a
 * label ("Inventory filler", and the two level buttons whose whole distinction is what they skip),
 * and the panel is reached from the pause menu where a wrong tap edits the save. Matching the
 * console row's metrics rather than a tighter custom size keeps the section visually one thing and
 * gives every action a comfortable tap target on the 3.92" bottom screen.
 */
@Composable
private fun DevActionButton(
    title: String,
    description: String,
    button: String,
    onClick: () -> Unit,
) {
    Column(Modifier.fillMaxWidth().padding(vertical = 9.dp)) {
        Text(title, color = Bone, fontSize = 14.sp, fontFamily = MwBody)
        Text(
            description,
            color = BoneDim,
            fontSize = 10.sp,
            fontFamily = MwBody,
            lineHeight = 14.sp,
            modifier = Modifier.padding(top = 1.dp)
        )
        Spacer(Modifier.height(6.dp))
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .clip(RoundedCornerShape(4.dp))
                .background(PillActiveBg.copy(alpha = 0.94f))
                .border(1.dp, BronzeLight, RoundedCornerShape(4.dp))
                // Cue.ACTION — the heaviest of the four, and the reason this feature exists: a
                // cheat button changes state somewhere off-screen, so without a sound there is no
                // evidence at all that the tap landed. [tapFlash] gives the same tap a visible
                // acknowledgement, which matters most here for exactly the same reason.
                .tapFlash { UiSounds.play(UiSounds.Cue.ACTION); onClick() }
                .padding(vertical = 9.dp),
            contentAlignment = Alignment.Center
        ) {
            Text(
                button,
                color = BronzeLight,
                fontSize = 14.sp,
                fontFamily = MwDisplay,
                fontWeight = FontWeight.Bold,
                letterSpacing = 1.sp
            )
        }
    }
}

/** A Developer Tools entry backed by a live ENGINE flag rather than a preference: [Off][On] pills
 *  reflecting [on], with taps sending a TOGGLE command (the engine owns the value, so we ask it to
 *  flip rather than telling it what to be — that keeps this correct if the flag changed elsewhere).
 *  Tapping the already-active pill is a deliberate no-op rather than a redundant toggle. */
@Composable
private fun DevToggleRow(label: String, description: String, on: Boolean, onToggle: () -> Unit) {
    Column(Modifier.fillMaxWidth().padding(vertical = 6.dp)) {
        Text(label, color = Bone, fontSize = 14.sp, fontFamily = MwBody)
        Text(
            description,
            color = BoneDim,
            fontSize = 10.sp,
            fontFamily = MwBody,
            modifier = Modifier.padding(top = 1.dp)
        )
        Spacer(Modifier.height(6.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            OptionPill(Modifier.weight(1f), label = "Off", active = !on, enabled = true) {
                if (on) onToggle()
            }
            OptionPill(Modifier.weight(1f), label = "On", active = on, enabled = true) {
                if (!on) onToggle()
            }
        }
    }
}

/** Input: direct touch-to-click on the top screen while a menu is open. [Off][On] pill selector
 *  (default On), writing to UiPreferences on every tap.
 *
 *  Mostly independent of [GameCursorRow] — the two are orthogonal (tap-to-click vs. a steerable
 *  cursor) and either or both may be on. Both OFF is the one disallowed combination (it leaves no
 *  top-screen pointer input at all), so turning this off while the cursor is off turns the cursor
 *  on instead — handled in [UiPreferences.setTouchInput], which is why both pills stay tappable. */
@Composable
private fun TouchInputRow() {
    val context = LocalContext.current
    val enabled by UiPreferences.touchInputFlow().collectAsState()

    Column(Modifier.fillMaxWidth().padding(vertical = 9.dp)) {
        Text("Touch input", color = Bone, fontSize = 14.sp, fontFamily = MwBody)
        Text(
            "Tap the top screen to click there in menus, even with no cursor showing",
            color = BoneDim,
            fontSize = 10.sp,
            fontFamily = MwBody,
            modifier = Modifier.padding(top = 1.dp)
        )
        Spacer(Modifier.height(6.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            OptionPill(
                Modifier.weight(1f),
                label = "Off",
                active = !enabled,
                enabled = true
            ) { UiPreferences.setTouchInput(context, false) }
            OptionPill(
                Modifier.weight(1f),
                label = "On",
                active = enabled,
                enabled = true
            ) { UiPreferences.setTouchInput(context, true) }
        }
    }
}

/** Input row: toggle the visible, thumbstick-steered cursor on the top screen. [Off][On] pill
 *  selector (default Off), writing to UiPreferences on every tap. Mostly independent of
 *  [TouchInputRow] — either or both may be on, but turning this off while touch input is also off
 *  turns touch input on instead (see [UiPreferences.setGameCursor]).
 *
 *  The second subtitle line documents a real behaviour change that comes with the cursor: the engine
 *  treats **A** as a click at the cursor rather than "activate the highlighted item" whenever a
 *  gamepad cursor is active (`mGamepadGuiCursorEnabled` in `controllermanager.cpp`). It belongs on
 *  THIS row because it is caused by the cursor, not by touch input. Also on the DS Controls page. */
@Composable
private fun GameCursorRow() {
    val context = LocalContext.current
    val enabled by UiPreferences.gameCursorFlow().collectAsState()

    Column(Modifier.fillMaxWidth().padding(vertical = 9.dp)) {
        Text("Game cursor", color = Bone, fontSize = 14.sp, fontFamily = MwBody)
        Text(
            "Show a cursor on the top screen and steer it with the thumbstick",
            color = BoneDim,
            fontSize = 10.sp,
            fontFamily = MwBody,
            modifier = Modifier.padding(top = 1.dp)
        )
        Text(
            "While it is on, A clicks whatever the cursor is over in the game's own menus, " +
                "instead of the highlighted item. The D-pad still highlights as usual.",
            color = BoneDim.copy(alpha = 0.7f),
            fontSize = 10.sp,
            fontFamily = MwBody,
            lineHeight = 13.sp,
            modifier = Modifier.padding(top = 3.dp)
        )
        Spacer(Modifier.height(6.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            OptionPill(
                Modifier.weight(1f),
                label = "Off",
                active = !enabled,
                enabled = true
            ) { UiPreferences.setGameCursor(context, false) }
            OptionPill(
                Modifier.weight(1f),
                label = "On",
                active = enabled,
                enabled = true
            ) { UiPreferences.setGameCursor(context, true) }
        }
    }
}

// OptionsSectionHeader — the flat in-place section heading. Removed Aug 21 2026 along with the
// collapsible sections it was the basis for; sub-pages carry [OptionsSubPageHeader] instead.

/** Toggle for the Alpha3 launcher overlay (the gear + arrow cluster on the top screen).
 *  [On][Off] pill selector (default Off). On = shown; Off hides the whole cluster including the
 *  arrow's expanded quick-action row (one composable). Purely Kotlin-side; writes on every tap.
 *
 *  **Named "Alpha3 Overlay" again, and moved to Developer Tools (Aug 21 2026).** It had been
 *  relabelled "Launcher touch overlay" on the reasoning that "Alpha3" names a different app and
 *  means nothing to an OpenMW-DS player — true, but the conclusion has been reversed: this control
 *  is inherited from that app, is not part of the DS design, and is kept only for anyone still
 *  relying on it. Calling it by its real name and filing it with the other legacy/advanced entries
 *  is more honest than a neutral label on a main page, and the subtitle now says outright that it is
 *  legacy. It still describes where the cluster sits, so it stays findable from "what is that thing
 *  in the corner of my top screen". */
@Composable
private fun Alpha3OverlayRow() {
    val context = LocalContext.current
    val shown by UiPreferences.alpha3OverlayFlow().collectAsState()

    Column(Modifier.fillMaxWidth().padding(vertical = 9.dp)) {
        Text("Alpha3 Overlay", color = Bone, fontSize = 14.sp, fontFamily = MwBody)
        Text(
            "Legacy. The gear + arrow button cluster in the top corner of the top screen, " +
                "inherited from the Alpha3 launcher. Not part of the DS interface; off by default.",
            color = BoneDim,
            fontSize = 10.sp,
            fontFamily = MwBody,
            lineHeight = 13.sp,
            modifier = Modifier.padding(top = 1.dp)
        )
        Spacer(Modifier.height(6.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            OptionPill(
                Modifier.weight(1f),
                label = "On",
                active = shown,
                enabled = true
            ) { UiPreferences.setAlpha3Overlay(context, true) }
            OptionPill(
                Modifier.weight(1f),
                label = "Off",
                active = !shown,
                enabled = true
            ) { UiPreferences.setAlpha3Overlay(context, false) }
        }
    }
}

/** A HUD-element row: element name (+ PENDING tag) over an [On][Off] pill selector. On = the native
 *  top-screen version is visible; Off = hidden (companion bottom-screen version only). The companion
 *  always draws these on the bottom screen. Writes a Boolean to UiPreferences on every tap. Pending
 *  elements (no native gate yet) render dimmed and locked to On. */
@Composable
private fun HudToggleRow(el: UiElement) {
    val context = LocalContext.current
    // Controller tooltips is force-shown until the first real journal entry (see
    // UiPreferences.controllerTooltipsForcedFlow). The pills below deliberately STAY LIVE and keep
    // showing the stored preference: this window is exactly when a new player is most likely to be
    // in here choosing All DS, so locking the control would block the setting at the one moment it
    // is most wanted, and a pill that ignores taps reads as broken. The tag plus the line under the
    // pills explain why the screen disagrees with the setting for now.
    val forcedOn = if (el.key == "hud_controller_tooltips") {
        UiPreferences.controllerTooltipsForcedFlow().collectAsState(initial = false).value
    } else false

    Column(Modifier.fillMaxWidth().padding(vertical = 9.dp)) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(
                el.label,
                color = if (el.pending) BoneDim else Bone,
                fontSize = 14.sp,
                fontFamily = MwBody,
                modifier = Modifier.weight(1f)
            )
            if (el.pending) {
                Text(
                    "PENDING",
                    color = BoneDim.copy(alpha = 0.7f),
                    fontSize = 9.sp,
                    fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold,
                    letterSpacing = 1.sp
                )
            } else if (forcedOn) {
                Text(
                    "ON FOR NOW",
                    color = BronzeLight,
                    fontSize = 9.sp,
                    fontFamily = MwDisplay,
                    fontWeight = FontWeight.Bold,
                    letterSpacing = 1.sp
                )
            }
        }
        Spacer(Modifier.height(6.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            if (el.pending) {
                // Not gated yet — native version stays On, both pills disabled.
                OptionPill(Modifier.weight(1f), label = "On", active = true, enabled = false) {}
                OptionPill(Modifier.weight(1f), label = "Off", active = false, enabled = false) {}
            } else {
                val on by UiPreferences.hudOnFlow(el.key).collectAsState()
                OptionPill(
                    Modifier.weight(1f),
                    label = "On",
                    active = on,
                    enabled = true
                ) { UiPreferences.setHudOn(context, el.key, true) }
                OptionPill(
                    Modifier.weight(1f),
                    label = "Off",
                    active = !on,
                    enabled = true
                ) { UiPreferences.setHudOn(context, el.key, false) }
            }
        }
        if (forcedOn) {
            Text(
                "Shown until your first journal entry, so the button hints are there while you " +
                    "make your character. Your choice above applies after that.",
                color = BoneDim.copy(alpha = 0.7f),
                fontSize = 10.sp,
                fontFamily = MwBody,
                lineHeight = 13.sp,
                modifier = Modifier.padding(top = 4.dp)
            )
        }
    }
}

/**
 * One option in a two-choice pill selector. Active = bronze-tinted fill + BronzeLight
 * border/text with a trailing "●"; inactive = dark fill + muted border/text. When
 * [enabled] is false the pill is dimmed and non-tappable (used for PENDING elements).
 */
@Composable
private fun OptionPill(
    modifier: Modifier,
    label: String,
    active: Boolean,
    enabled: Boolean,
    onClick: () -> Unit,
) {
    val a = if (enabled) 1f else 0.4f
    val bg = (if (active) PillActiveBg else SlotBg).copy(alpha = (if (active) 0.94f else 1f) * a)
    val border = (if (active) BronzeLight else BronzeDark).copy(alpha = a)
    val fg = (if (active) BronzeLight else BoneDim).copy(alpha = a)
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(4.dp))
            .background(bg)
            .border(1.dp, border, RoundedCornerShape(4.dp))
            // EVERY options pill in the menu is one of these — the Game Menus mode selectors, the
            // On/Off rows, and the Developer Tools toggles — so this single hook is the whole
            // "changing a setting makes a sound" requirement, and (since Aug 21 2026) the whole
            // "changing a setting flashes" one too. A disabled pill stays silent and unlit along
            // with being inert, which is the correct signal.
            //
            // [tapFlash] rather than a bare clickable: the built-in press indication is both too
            // brief to see on a quick tap and too dark to see on this palette — see the block
            // comment on tapFlash for the measured reason.
            .tapFlash(enabled = enabled) { UiSounds.play(UiSounds.Cue.TOGGLE); onClick() }
            .padding(vertical = 8.dp, horizontal = 6.dp),
        contentAlignment = Alignment.Center
    ) {
        // The selected marker is a DRAWN dot, not a "●" glyph: MysticCards has no U+25CF, and every
        // pill in the menu is now set in it. A Box also gives a rounder, better-aligned dot than the
        // glyph did, and it cannot be thrown off by a font's own baseline.
        Row(verticalAlignment = Alignment.CenterVertically) {
            Text(
                label,
                color = fg,
                fontSize = 12.sp,
                fontFamily = MwDisplay,
                fontWeight = FontWeight.Bold,
                maxLines = 1
            )
            if (active) {
                Spacer(Modifier.width(5.dp))
                Box(
                    Modifier
                        .size(6.dp)
                        .clip(CircleShape)
                        .background(fg)
                )
            }
        }
    }
}
